CREATE OR REPLACE FUNCTION public._comunicacao_trg_os_onfarm_pronto_retirada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_idem text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'pronto_entrega'::public.status_os_onfarm THEN
    v_idem := 'os_pronto_retirada:ordens_servico_onfarm:' || NEW.id::text;
    PERFORM public._comunicacao_publish_system_event(
      'produto_pronto_retirada','ordens_servico_onfarm', NEW.id, '{}'::jsonb, v_idem);
  END IF;
  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public._comunicacao_trg_os_pronto_retirada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_idem text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'pronto_entrega'::public.status_os THEN
    v_idem := 'os_pronto_retirada:ordens_servico:' || NEW.id::text;
    PERFORM public._comunicacao_publish_system_event(
      'produto_pronto_retirada','ordens_servico', NEW.id, '{}'::jsonb, v_idem);
  END IF;
  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public._comunicacao_trg_portal_solicitacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ev text;
  v_transition text;
  v_idem text;
  v_status_ant text;
  v_status_novo text;
  v_first_assign boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_ev := 'solicitacao_criada';
    v_transition := 'insert';
    v_status_ant := NULL;
    v_status_novo := NEW.status::text;
    v_first_assign := (NEW.consultor_atribuido IS NOT NULL AND NEW.status = 'atribuida');
    -- Se INSERT já com status=atribuida, o evento canônico é solicitacao_criada
    -- (linha nova). A primeira atribuição via UPDATE é que precisa emitir
    -- 'solicitacao_atribuida' adicional; em INSERT, criada já é suficiente.
    v_first_assign := false;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      v_ev := CASE NEW.status
        WHEN 'atribuida' THEN 'solicitacao_atribuida'
        WHEN 'checkin_realizado' THEN 'solicitacao_checkin_realizado'
        WHEN 'em_visita' THEN 'solicitacao_em_visita'
        WHEN 'aguardando_os' THEN 'solicitacao_aguardando_os'
        WHEN 'concluida' THEN 'solicitacao_concluida'
        WHEN 'cancelada' THEN 'solicitacao_cancelada'
        ELSE NULL
      END;
      v_transition := 'status:' || COALESCE(NEW.status::text,'null');
      v_status_ant := OLD.status::text;
      v_status_novo := NEW.status::text;
    END IF;
    -- Primeira atribuição: consultor NULL→X. Deduplicação: se status já
    -- transicionou para 'atribuida' neste mesmo comando, o evento canônico
    -- já será emitido; não emitir de novo.
    IF OLD.consultor_atribuido IS NULL AND NEW.consultor_atribuido IS NOT NULL
       AND (v_ev IS DISTINCT FROM 'solicitacao_atribuida') THEN
      v_first_assign := true;
    END IF;
  END IF;

  IF v_ev IS NOT NULL THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|', v_ev, NEW.id::text, v_transition, COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      v_ev, 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_anterior', v_status_ant,
        'status_novo', v_status_novo,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', v_transition
      )),
      v_idem
    );
  END IF;

  IF v_first_assign THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|','solicitacao_atribuida', NEW.id::text,
                  'first_assign:'||NEW.consultor_atribuido::text,
                  COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      'solicitacao_atribuida', 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_novo', NEW.status::text,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', 'first_assign'
      )),
      v_idem
    );
  END IF;

  IF (TG_OP = 'INSERT' AND NEW.urgencia = 'critica')
     OR (TG_OP = 'UPDATE' AND NEW.urgencia = 'critica' AND OLD.urgencia IS DISTINCT FROM 'critica') THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|', 'solicitacao_urgencia_critica', NEW.id::text, 'urgencia:critica',
                  COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      'solicitacao_urgencia_critica', 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_novo', NEW.status::text,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', 'urgencia:critica'
      )),
      v_idem
    );
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._avancar_os_status(p_origem text, p_os_id uuid, p_alvo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    status_order TEXT[] := ARRAY['aberta','aprovada','programada','em_producao','em_cq','envase','aguardando_reserva','pronto_entrega','entregue','finalizada'];
    v_atual TEXT;
    v_idx_atual INT;
    v_idx_alvo INT;
    v_proximo TEXT;
    v_use_manual BOOLEAN;
BEGIN
    v_use_manual := p_origem IN ('manual','b2b');

    IF v_use_manual THEN
        SELECT status::text INTO v_atual FROM public.ordens_servico WHERE id = p_os_id;
    ELSE
        SELECT status::text INTO v_atual FROM public.ordens_servico_onfarm WHERE id = p_os_id;
    END IF;

    SELECT i INTO v_idx_atual FROM unnest(status_order) WITH ORDINALITY AS t(val,i) WHERE val = v_atual;
    SELECT i INTO v_idx_alvo FROM unnest(status_order) WITH ORDINALITY AS t(val,i) WHERE val = p_alvo;

    IF v_idx_atual IS NULL OR v_idx_alvo IS NULL THEN
        RAISE EXCEPTION 'Status OS inválido (% -> %).', v_atual, p_alvo;
    END IF;

    WHILE v_idx_atual < v_idx_alvo LOOP
        v_proximo := status_order[v_idx_atual + 1];
        IF v_use_manual THEN
            UPDATE public.ordens_servico SET status = v_proximo::public.status_os WHERE id = p_os_id;
        ELSE
            UPDATE public.ordens_servico_onfarm SET status = v_proximo::public.status_os_onfarm WHERE id = p_os_id;
        END IF;
        v_idx_atual := v_idx_atual + 1;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_partner_order_payment_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id uuid;
BEGIN
  SELECT partner_id INTO v_partner_id FROM public.partner_orders WHERE id = NEW.partner_order_id;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
    VALUES (NEW.partner_order_id, v_partner_id, auth.uid(), 'payment_terms_created', NULL, to_jsonb(NEW));
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
    VALUES (NEW.partner_order_id, v_partner_id, auth.uid(), 'payment_terms_updated', to_jsonb(OLD), to_jsonb(NEW));
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_advance_solicitacao_on_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_solicitacao_id uuid;
BEGIN
  IF NEW.registro_consultor_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT solicitacao_id INTO v_solicitacao_id
    FROM public.registros_consultor WHERE id = NEW.registro_consultor_id;
  IF v_solicitacao_id IS NOT NULL THEN
    UPDATE public.portal_solicitacoes
      SET status = 'aguardando_os', updated_at = now()
      WHERE id = v_solicitacao_id
        AND status NOT IN ('concluida','cancelada');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public._comunicacao_build_snapshot_v2(_event_key text, _source_type text, _source_id uuid, _payload jsonb, _user_id uuid, _cliente_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_codigo_os text; v_data_prevista text; v_nome_dest text;
  v_titulo text; v_mensagem text; v_target_role text;
  v_sol RECORD;
BEGIN
  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao','administrative_important_update') THEN
    IF _user_id IS NOT NULL THEN
      SELECT nome INTO v_nome_dest FROM public.profiles WHERE user_id = _user_id LIMIT 1;
    ELSIF _cliente_id IS NOT NULL THEN
      SELECT nome INTO v_nome_dest FROM public.clientes WHERE id = _cliente_id LIMIT 1;
    END IF;
  END IF;
  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    IF _source_type NOT IN ('ordens_servico','ordens_servico_onfarm') THEN
      RAISE EXCEPTION 'source_type inválido: %', _source_type; END IF;
    CASE _source_type
      WHEN 'ordens_servico' THEN
        SELECT o.numero_os, to_char(o.data_programada,'DD/MM/YYYY')
          INTO v_codigo_os, v_data_prevista FROM public.ordens_servico o WHERE o.id = _source_id;
      WHEN 'ordens_servico_onfarm' THEN
        SELECT o.numero_os, to_char(o.data_recomendada,'DD/MM/YYYY')
          INTO v_codigo_os, v_data_prevista FROM public.ordens_servico_onfarm o WHERE o.id = _source_id;
    END CASE;
    RETURN jsonb_build_object(
      'nome_destinatario', COALESCE(v_nome_dest,''),
      'codigo_os', COALESCE(v_codigo_os,''),
      'data_prevista', COALESCE(v_data_prevista,''));
  END IF;
  IF _event_key = 'administrative_important_update' THEN
    v_titulo := left(COALESCE(_payload->>'titulo',''), 200);
    v_mensagem := left(COALESCE(_payload->>'mensagem',''), 2000);
    v_target_role := _payload->>'target_role';
    RETURN jsonb_build_object(
      'nome_destinatario', COALESCE(v_nome_dest,''),
      'titulo', v_titulo, 'mensagem', v_mensagem,
      'target_role', COALESCE(v_target_role,''));
  END IF;
  IF _event_key IN (
    'solicitacao_criada','solicitacao_atribuida','solicitacao_checkin_realizado',
    'solicitacao_em_visita','solicitacao_aguardando_os','solicitacao_concluida',
    'solicitacao_cancelada','solicitacao_urgencia_critica'
  ) THEN
    IF _source_type <> 'portal_solicitacoes' THEN
      RAISE EXCEPTION 'source_type inválido: %', _source_type; END IF;
    SELECT s.numero_solicitacao, s.tipo_demanda::text, s.urgencia::text, s.status::text
      INTO v_sol FROM public.portal_solicitacoes s WHERE s.id = _source_id;
    IF v_sol IS NULL THEN RETURN '{}'::jsonb; END IF;
    RETURN jsonb_build_object(
      'numero', COALESCE(v_sol.numero_solicitacao,''),
      'tipo_demanda', COALESCE(v_sol.tipo_demanda,''),
      'urgencia', COALESCE(v_sol.urgencia,''),
      'status_novo', COALESCE(v_sol.status,''),
      'solicitacao_id', _source_id::text);
  END IF;
  RETURN '{}'::jsonb;
END $function$

CREATE OR REPLACE FUNCTION public._comunicacao_dlq_replay_rate_check(p_scope text, p_max_per_minute integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid; v_cnt int;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'sem contexto de usuário' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO v_cnt
    FROM public.comunicacao_dlq_replay_audit
   WHERE actor_id = v_actor
     AND scope = p_scope
     AND created_at > now() - interval '1 minute';
  IF v_cnt >= p_max_per_minute THEN
    RAISE EXCEPTION 'rate_limited: replay % excede % por minuto', p_scope, p_max_per_minute
      USING ERRCODE='53400';
  END IF;
END;$function$

CREATE OR REPLACE FUNCTION public._comunicacao_expand_event(_event_id uuid, _event_key text, _source_type text, _source_id uuid, _payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_rule public.comunicacao_regras%rowtype;
  v_tpl public.comunicacao_templates%rowtype;
  v_rec record; v_snapshot jsonb; v_payload_snapshot jsonb; v_idem_out text;
  v_enq int := 0; v_skp int := 0; v_row int := 0; v_target_role public.app_role;
BEGIN
  IF _event_key = 'administrative_important_update' THEN
    BEGIN v_target_role := (_payload->>'target_role')::public.app_role;
    EXCEPTION WHEN others THEN RAISE EXCEPTION 'target_role inválido'; END;
  END IF;
  FOR v_rule IN
    SELECT * FROM public.comunicacao_regras
     WHERE event_key = _event_key AND enabled = true
       AND (_event_key <> 'administrative_important_update'
            OR (estrategia='broadcast_role' AND perfil = v_target_role))
     ORDER BY prioridade ASC
  LOOP
    v_tpl := public._comunicacao_resolve_template(v_rule.template_chave, v_rule.canal, v_rule.template_versao);
    IF v_tpl.id IS NULL OR v_tpl.canal <> v_rule.canal THEN v_skp := v_skp+1; CONTINUE; END IF;
    v_snapshot := jsonb_build_object(
      'assunto', v_tpl.assunto, 'corpo', v_tpl.corpo,
      'variaveis', v_tpl.variaveis, 'canal', v_tpl.canal, 'locale', v_tpl.locale,
      'provider_template_name', v_tpl.provider_template_name,
      'language_code', v_tpl.language_code,
      'parameter_mapping', v_tpl.parameter_mapping,
      'provider_template_status', v_tpl.provider_template_status);
    FOR v_rec IN SELECT * FROM public._comunicacao_resolve_recipients_v2(_event_key, v_rule, _source_type, _source_id)
    LOOP
      IF NOT public._comunicacao_can_deliver(v_rec.recipient_user_id, v_rec.recipient_cliente_id, v_rule.canal) THEN
        v_skp := v_skp+1; CONTINUE; END IF;
      v_payload_snapshot := public._comunicacao_build_snapshot_v2(
        _event_key, _source_type, _source_id, _payload,
        v_rec.recipient_user_id, v_rec.recipient_cliente_id);
      v_idem_out := encode(extensions.digest(
        concat_ws('|', _event_id::text, v_rule.id::text, v_tpl.id::text,
          COALESCE(v_rec.recipient_user_id::text,''),
          COALESCE(v_rec.recipient_cliente_id::text,'')), 'sha256'),'hex');
      INSERT INTO public.comunicacao_outbox(
        event_id, rule_id, template_id, template_chave, template_versao,
        template_snapshot, canal, recipient_user_id, recipient_cliente_id,
        payload_snapshot, idempotency_key)
      VALUES (_event_id, v_rule.id, v_tpl.id, v_tpl.chave, v_tpl.versao,
        v_snapshot, v_rule.canal, v_rec.recipient_user_id, v_rec.recipient_cliente_id,
        v_payload_snapshot, v_idem_out)
      ON CONFLICT (idempotency_key) DO NOTHING;
      GET DIAGNOSTICS v_row = ROW_COUNT;
      IF v_row = 1 THEN v_enq := v_enq+1; ELSE v_skp := v_skp+1; END IF;
    END LOOP;
  END LOOP;
  UPDATE public.comunicacao_eventos
     SET status='processed', processed_at=now(),
         outbox_enqueued=v_enq, outbox_skipped=v_skp
   WHERE id = _event_id;
  RETURN jsonb_build_object('enqueued',v_enq,'skipped',v_skp);
END$function$

CREATE OR REPLACE FUNCTION public.catalog_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entidade text := TG_ARGV[0];
  v_old jsonb;
  v_new jsonb;
  v_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_old := to_jsonb(OLD); v_new := NULL; v_id := OLD.id;
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD); v_new := to_jsonb(NEW); v_id := NEW.id;
  ELSE
    v_old := NULL; v_new := to_jsonb(NEW); v_id := NEW.id;
  END IF;

  INSERT INTO public.catalog_technical_audit_logs(entidade_tipo, entidade_id, acao, dados_anteriores, dados_novos, usuario_id)
  VALUES (v_entidade, v_id, lower(TG_OP), v_old, v_new, auth.uid());

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_lifecycle_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.operation IN ('create_global_product','set_global_product_status')
    OR NEW.operation IN ('create_global_product','set_global_product_status') THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_lifecycle_audit_immutable';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.create_global_product_core(p_payload jsonb, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid; v_existing public.catalog_platform_admin_audit%ROWTYPE;
  v_new public.produtos%ROWTYPE; v_request jsonb; v_receipt jsonb; v_audit uuid:=gen_random_uuid();
  v_key text; v_item jsonb; v_comp jsonb:='[]'::jsonb; v_ids uuid[]:='{}';
  v_snapshot jsonb; v_dose numeric; v_vol numeric; v_prop numeric; v_micro uuid; v_count int;
  v_allowed constant text[]:=ARRAY['nome','tipo','descricao','modo_acao','funcao_completa','modo_aplicacao','dose_ml_ha','composicao'];
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_idempotency_key IS NULL OR p_reason IS NULL
    OR pg_catalog.char_length(pg_catalog.btrim(p_reason)) NOT BETWEEN 10 AND 500
    OR p_payload IS NULL OR pg_catalog.jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
  END IF;
  -- Só depois de provar 'object' chamamos jsonb_object_keys (arrays/escalares abortariam com erro genérico).
  FOR v_key IN SELECT pg_catalog.jsonb_object_keys(p_payload) LOOP
    IF NOT (v_key=ANY(v_allowed)) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid'; END IF;
  END LOOP;
  IF pg_catalog.jsonb_typeof(p_payload->'nome') IS DISTINCT FROM 'string'
    OR pg_catalog.char_length(pg_catalog.btrim(p_payload->>'nome')) NOT BETWEEN 1 AND 500
    OR pg_catalog.jsonb_typeof(p_payload->'tipo') IS DISTINCT FROM 'string'
    OR NOT ((p_payload->>'tipo') = ANY(pg_catalog.enum_range(NULL::public.tipo_produto)::text[])) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
  END IF;
  FOREACH v_key IN ARRAY ARRAY['descricao','modo_acao','funcao_completa','modo_aplicacao'] LOOP
    IF p_payload ? v_key AND (pg_catalog.jsonb_typeof(p_payload->v_key) IS DISTINCT FROM 'string'
      AND pg_catalog.jsonb_typeof(p_payload->v_key) IS DISTINCT FROM 'null'
      OR pg_catalog.char_length(p_payload->>v_key) > 10000) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
    END IF;
  END LOOP;
  -- Dose: número JSON finito (JSON não representa NaN/Infinity), 0 < d <= 1e6, até 6 casas.
  IF p_payload ? 'dose_ml_ha' AND pg_catalog.jsonb_typeof(p_payload->'dose_ml_ha') IS DISTINCT FROM 'null' THEN
    IF pg_catalog.jsonb_typeof(p_payload->'dose_ml_ha') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid'; END IF;
    v_dose:=(p_payload->>'dose_ml_ha')::numeric;
    IF v_dose <= 0 OR v_dose > 1000000 OR pg_catalog.scale(v_dose) > 6 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
    END IF;
  END IF;
  IF p_payload ? 'composicao' THEN
    IF pg_catalog.jsonb_typeof(p_payload->'composicao') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
    END IF;
    IF pg_catalog.jsonb_array_length(p_payload->'composicao') > 50 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
    END IF;
    FOR v_item IN SELECT * FROM pg_catalog.jsonb_array_elements(p_payload->'composicao') LOOP
      -- Objeto primeiro (curto-circuito explícito), depois chaves e tipos com IS DISTINCT FROM (NULL/ausente = inválido).
      IF pg_catalog.jsonb_typeof(v_item) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
      END IF;
      IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_object_keys(v_item) k WHERE k NOT IN ('microrganismo_id','volume_ml','proporcao'))
        OR pg_catalog.jsonb_typeof(v_item->'microrganismo_id') IS DISTINCT FROM 'string'
        OR (v_item->>'microrganismo_id') IS NULL
        OR (v_item->>'microrganismo_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR pg_catalog.jsonb_typeof(v_item->'volume_ml') IS DISTINCT FROM 'number'
        OR (v_item ? 'proporcao' AND pg_catalog.jsonb_typeof(v_item->'proporcao') IS DISTINCT FROM 'number'
            AND pg_catalog.jsonb_typeof(v_item->'proporcao') IS DISTINCT FROM 'null') THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
      END IF;
      v_micro:=(v_item->>'microrganismo_id')::uuid; v_vol:=(v_item->>'volume_ml')::numeric;
      v_prop:=CASE WHEN pg_catalog.jsonb_typeof(v_item->'proporcao')='number' THEN (v_item->>'proporcao')::numeric END;
      IF v_vol IS NULL OR v_micro=ANY(v_ids) OR v_vol <= 0 OR v_vol > 1000000 OR pg_catalog.scale(v_vol) > 6
        OR (v_prop IS NOT NULL AND (v_prop <= 0 OR v_prop > 100 OR pg_catalog.scale(v_prop) > 6)) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
      END IF;
      v_ids:=v_ids||v_micro;
      v_comp:=v_comp||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('microrganismo_id',v_micro,'volume_ml',v_vol,'proporcao',v_prop));
    END LOOP;
  END IF;
  v_request:=pg_catalog.jsonb_build_object('payload',(p_payload-'composicao')||pg_catalog.jsonb_build_object(
    'nome',pg_catalog.btrim(p_payload->>'nome'),'composicao',v_comp),'reason',pg_catalog.btrim(p_reason));

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_idempotency_key::text,0));
  SELECT * INTO v_existing FROM public.catalog_platform_admin_audit WHERE correlation_id=p_idempotency_key;
  IF FOUND THEN
    IF v_existing.operation<>'create_global_product' OR v_existing.actor_id<>v_actor
      OR v_existing.counts_after->'request' IS DISTINCT FROM v_request THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_create_conflict';
    END IF;
    RETURN (v_existing.counts_after->'receipt')||pg_catalog.jsonb_build_object('idempotent',true);
  END IF;
  -- Microrganismos referenciados devem existir; lock compartilhado evita remoção concorrente.
  -- FOR SHARE bloqueia UPDATE concorrente (inclusive de ativo) até o fim da transação;
  -- só microrganismos ATIVOS entram em novas composições. Históricas não são tocadas.
  SELECT count(*) INTO v_count FROM (SELECT 1 FROM public.microrganismos WHERE id=ANY(v_ids) AND ativo IS TRUE FOR SHARE) s;
  IF v_count <> pg_catalog.cardinality(v_ids) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid'; END IF;

  -- Novo item nasce INATIVO e fora do B2B; preços NULL (motor canônico decide depois);
  -- código NULL → trigger set_codigo_produto/proximo_codigo (upsert serializado).
  INSERT INTO public.produtos (nome,tipo,descricao,modo_acao,funcao_completa,modo_aplicacao,dose_ml_ha,
    ativo,b2b_enabled,codigo,valor_dose_brl,valor_litro_brl,valor_ha_brl)
  VALUES (pg_catalog.btrim(p_payload->>'nome'),(p_payload->>'tipo')::public.tipo_produto,
    p_payload->>'descricao',p_payload->>'modo_acao',p_payload->>'funcao_completa',p_payload->>'modo_aplicacao',
    v_dose,false,false,NULL,NULL,NULL,NULL)
  RETURNING * INTO v_new;
  IF v_new.id IS NULL OR v_new.codigo IS NULL OR v_new.ativo IS DISTINCT FROM false OR v_new.b2b_enabled
    OR v_new.valor_dose_brl IS NOT NULL OR v_new.valor_litro_brl IS NOT NULL OR v_new.valor_ha_brl IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_create_confirmation_failed';
  END IF;
  INSERT INTO public.formulacoes (produto_id,microrganismo_id,volume_ml,proporcao,e_volume_fixo,unidade)
  SELECT v_new.id,(c->>'microrganismo_id')::uuid,(c->>'volume_ml')::numeric,
    CASE WHEN c->>'proporcao' IS NULL THEN NULL ELSE (c->>'proporcao')::numeric END,true,'mL'
  FROM pg_catalog.jsonb_array_elements(v_comp) c;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> pg_catalog.jsonb_array_length(v_comp) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_create_confirmation_failed';
  END IF;
  -- Snapshot canônico relido do banco na mesma transação (produto + formulações com IDs).
  SELECT pg_catalog.jsonb_build_object('produto',pg_catalog.to_jsonb(p) - ARRAY['created_at'],
    'formulacoes',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',f.id,'microrganismo_id',f.microrganismo_id,
      'volume_ml',f.volume_ml,'proporcao',f.proporcao,'e_volume_fixo',f.e_volume_fixo,'unidade',f.unidade) ORDER BY f.id)
      FROM public.formulacoes f WHERE f.produto_id=p.id),'[]'::jsonb))
  INTO v_snapshot FROM public.produtos p WHERE p.id=v_new.id;
  IF v_snapshot IS NULL OR pg_catalog.jsonb_array_length(v_snapshot->'formulacoes') <> v_count
    OR (v_snapshot->'produto'->>'ativo')::boolean IS DISTINCT FROM false
    OR (v_snapshot->'produto'->>'b2b_enabled')::boolean IS DISTINCT FROM false THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_create_confirmation_failed';
  END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',v_new.id,'codigo',v_new.codigo,'updated_at',v_new.updated_at,
    'composicao_count',v_count,'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  INSERT INTO public.catalog_platform_admin_audit (id,operation,actor_id,reason,correlation_id,status,counts_before,counts_after,completed_at)
  VALUES (v_audit,'create_global_product',v_actor,pg_catalog.btrim(p_reason),p_idempotency_key,'completed','{}'::jsonb,
    pg_catalog.jsonb_build_object('request',v_request,'receipt',v_receipt,'after',v_snapshot),pg_catalog.clock_timestamp());
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public._comunicacao_resolve_recipients(_event_key text, _rule comunicacao_regras, _source_id uuid)
 RETURNS TABLE(recipient_user_id uuid, recipient_cliente_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_os_cliente uuid;
BEGIN
  IF _event_key = 'administrative_important_update' THEN
    IF _rule.estrategia <> 'broadcast_role' OR _rule.perfil IS NULL THEN RETURN; END IF;
    RETURN QUERY
      SELECT DISTINCT pr.user_id, NULL::uuid
        FROM public.user_roles ur
        JOIN public.profiles pr ON pr.user_id = ur.user_id
       WHERE ur.role = _rule.perfil AND COALESCE(pr.ativo, true) = true;
    RETURN;
  END IF;
  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico o WHERE o.id = _source_id;
    IF v_os_cliente IS NULL THEN RETURN; END IF;
    IF _rule.estrategia = 'source_participants' THEN
      RETURN QUERY
        SELECT NULL::uuid AS recipient_user_id, v_os_cliente AS recipient_cliente_id
        UNION
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.profiles pr
         WHERE pr.cliente_id = v_os_cliente AND COALESCE(pr.ativo, true) = true;
      RETURN;
    ELSIF _rule.estrategia = 'by_role' THEN
      IF _rule.perfil IS NULL THEN RETURN; END IF;
      RETURN QUERY
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.user_roles ur
          JOIN public.profiles pr ON pr.user_id = ur.user_id
         WHERE ur.role = _rule.perfil AND pr.cliente_id = v_os_cliente
           AND COALESCE(pr.ativo, true) = true;
      RETURN;
    ELSE
      RETURN;
    END IF;
  END IF;
END$function$

CREATE OR REPLACE FUNCTION platform_private.platform_read_global_product_catalog_core(p_search text, p_limit integer, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_search text;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'platform_catalog_forbidden';
  END IF;
  -- Signed session iat only; no user_metadata/app_metadata authorization or GUC ticket.
  IF pg_catalog.jsonb_typeof(auth.jwt()->'iat') IS DISTINCT FROM 'number'
     OR COALESCE(auth.jwt()->>'iat', '') !~ '^[0-9]{1,12}$' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'platform_catalog_forbidden';
  END IF;
  IF (auth.jwt()->>'iat')::bigint <= 0
     OR NOT COALESCE(platform_private.platform_actor_access_ready(v_actor), false)
     OR NOT COALESCE(public.has_role(v_actor, 'superadmin'::public.app_role), false)
     OR NOT COALESCE(public.is_platform_superadmin(v_actor), false) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'platform_catalog_forbidden';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 50
     OR p_offset IS NULL OR p_offset < 0 OR p_offset > 1000000
     OR p_search IS NULL OR pg_catalog.char_length(p_search) > 120 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'platform_catalog_invalid_query';
  END IF;
  v_search := pg_catalog.lower(pg_catalog.btrim(p_search));
  -- Literal substring: %, _, quotes are data, not wildcard/filter syntax.
  -- One snapshot, deterministic tie-breaker; only an extra sentinel is read.
  WITH bounded AS MATERIALIZED (
    SELECT p.id, p.codigo, p.nome, p.tipo, p.ativo, p.b2b_enabled, p.updated_at
    FROM public.produtos p
    WHERE v_search = ''
       OR pg_catalog.strpos(pg_catalog.lower(p.nome), v_search) > 0
       OR pg_catalog.strpos(pg_catalog.lower(COALESCE(p.codigo, '')), v_search) > 0
    ORDER BY pg_catalog.lower(p.nome) COLLATE "C", p.id
    LIMIT (p_limit + 1) OFFSET p_offset
  ), page AS (
    SELECT b.id, b.codigo, b.nome, b.tipo, b.ativo, b.b2b_enabled, b.updated_at
    FROM bounded b
    ORDER BY pg_catalog.lower(b.nome) COLLATE "C", b.id LIMIT p_limit
  )
  SELECT pg_catalog.jsonb_build_object(
    'items', COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r)
      ORDER BY pg_catalog.lower(r.nome) COLLATE "C", r.id) FROM page r), '[]'::jsonb),
    'has_more', (SELECT pg_catalog.count(*) > p_limit FROM bounded)
  ) INTO v_result;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public._sync_planning_from_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_planning_id uuid;
  v_total int;
  v_done int;
  v_in_prod int;
BEGIN
  v_partner_order_id := COALESCE(NEW.partner_order_id, OLD.partner_order_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO v_planning_id FROM public.production_planning WHERE partner_order_id = v_partner_order_id;
  IF v_planning_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status IN ('finalizada','entregue','pronto_entrega')),
         COUNT(*) FILTER (WHERE status IN ('em_producao','em_cq','envase','programada'))
    INTO v_total, v_done, v_in_prod
  FROM public.ordens_servico WHERE partner_order_id = v_partner_order_id;

  IF v_total = 0 THEN RETURN NEW; END IF;

  IF v_done = v_total THEN
    UPDATE public.production_planning SET status='produzido', updated_at=now()
      WHERE id=v_planning_id AND status <> 'produzido';
  ELSIF v_in_prod > 0 THEN
    UPDATE public.production_planning SET status='em_producao', updated_at=now()
      WHERE id=v_planning_id AND status NOT IN ('em_producao','produzido','entregue');
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public._rpc_avancar_esteira_laboratorio_internal(p_os_id uuid, p_origem_os text, p_etapa_destino text, p_programacao_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_role public.app_role;
    v_profile_id UUID;
    v_status_atual TEXT;
    v_lote_id UUID;
    v_etapa_anterior_os TEXT;
    v_tabela_os TEXT;
    v_validacao jsonb;
    v_cq_atual TEXT;
    v_status_alvo TEXT;
BEGIN
    SELECT role INTO v_user_role FROM public.user_roles WHERE user_id = auth.uid() LIMIT 1;
    SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1;

    IF p_origem_os IN ('manual','b2b') THEN v_tabela_os := 'ordens_servico';
    ELSE v_tabela_os := 'ordens_servico_onfarm';
    END IF;

    -- Status alvo canônico por etapa. 'criar_entrega' NAO tem status alvo:
    -- criar a entrega deixa a OS em pronto_entrega ate a confirmacao fisica.
    v_status_alvo := CASE p_etapa_destino
        WHEN 'assumir_producao' THEN 'em_producao'
        WHEN 'enviar_cq'        THEN 'em_cq'
        WHEN 'enviar_envase'    THEN 'envase'
        WHEN 'concluir_envase'  THEN 'pronto_entrega'
        WHEN 'gerar_estoque'    THEN 'pronto_entrega'
        WHEN 'reservar_estoque' THEN 'pronto_entrega'
        WHEN 'enviar_entrega'   THEN 'entregue'
        WHEN 'finalizar_os'     THEN 'finalizada'
        ELSE NULL
    END;

    EXECUTE format('SELECT status::text FROM %I WHERE id = $1 FOR UPDATE', v_tabela_os)
    INTO v_status_atual USING p_os_id;

    IF v_status_atual IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Ordem de serviço não encontrada.');
    END IF;

    -- IDEMPOTÊNCIA SERVER-SIDE (Gate 5): se a OS já está no status alvo da
    -- etapa, o replay é absorvido SEM novo evento de auditoria e SEM efeito.
    IF v_status_alvo IS NOT NULL AND v_status_atual = v_status_alvo THEN
        RETURN jsonb_build_object(
            'success', true,
            'replay', true,
            'message', 'Etapa já aplicada anteriormente.'
        );
    END IF;

    SELECT * INTO v_validacao FROM public.rpc_validar_integridade_esteira(p_os_id, p_origem_os, p_etapa_destino);
    IF NOT (v_validacao->>'permitido')::BOOLEAN THEN
        RETURN jsonb_build_object('success', false, 'message', (v_validacao->'bloqueios'->>0));
    END IF;

    v_etapa_anterior_os := v_status_atual;

    IF p_programacao_id IS NOT NULL AND p_programacao_id <> '00000000-0000-0000-0000-000000000000'::uuid THEN
        SELECT id INTO v_lote_id FROM public.lotes WHERE programacao_id = p_programacao_id FOR UPDATE;
    ELSE
        IF p_origem_os IN ('manual','b2b') THEN
            SELECT l.id INTO v_lote_id FROM public.lotes l JOIN public.programacao_producao pp ON l.programacao_id = pp.id WHERE pp.ordem_servico_id = p_os_id LIMIT 1;
        ELSE
            SELECT l.id INTO v_lote_id FROM public.lotes l JOIN public.programacao_producao pp ON l.programacao_id = pp.id WHERE pp.ordem_servico_onfarm_id = p_os_id LIMIT 1;
        END IF;
    END IF;

    CASE p_etapa_destino
        WHEN 'assumir_producao' THEN
            PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'em_producao');
            IF p_programacao_id IS NOT NULL THEN
                UPDATE public.programacao_producao SET status = 'em_producao', responsavel_id = v_profile_id WHERE id = p_programacao_id;
            END IF;
        WHEN 'gerar_lote' THEN NULL;
        WHEN 'enviar_cq' THEN
            PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'em_cq');
            UPDATE public.lotes SET status = 'aguardando_cq' WHERE id = v_lote_id;
        WHEN 'aprovar_cq', 'reprovar_cq' THEN
            IF v_lote_id IS NULL THEN
                RETURN jsonb_build_object('success', false, 'message', 'Nenhum lote localizado para registrar o CQ.');
            END IF;
            PERFORM pg_advisory_xact_lock(hashtext('cq_lote:' || v_lote_id::text));

            SELECT resultado::text INTO v_cq_atual
              FROM public.controle_qualidade
             WHERE lote_id = v_lote_id
             ORDER BY created_at DESC, seq DESC
             LIMIT 1;

            IF p_etapa_destino = 'aprovar_cq' THEN
                -- replay de CQ aprovado: nao duplica laudo NEM evento
                IF v_cq_atual IS NOT DISTINCT FROM 'aprovado' THEN
                    UPDATE public.lotes SET status = 'aprovado' WHERE id = v_lote_id;
                    RETURN jsonb_build_object('success', true, 'replay', true,
                        'message', 'CQ já registrado como aprovado.');
                END IF;
                UPDATE public.lotes SET status = 'aprovado' WHERE id = v_lote_id;
                INSERT INTO public.controle_qualidade (lote_id, resultado, responsavel_id)
                VALUES (v_lote_id, 'aprovado', v_profile_id);
            ELSE
                IF v_cq_atual IS NOT DISTINCT FROM 'reprovado' THEN
                    UPDATE public.lotes SET status = 'reprovado' WHERE id = v_lote_id;
                    RETURN jsonb_build_object('success', true, 'replay', true,
                        'message', 'CQ já registrado como reprovado.');
                END IF;
                UPDATE public.lotes SET status = 'reprovado' WHERE id = v_lote_id;
                INSERT INTO public.controle_qualidade (lote_id, resultado, responsavel_id)
                VALUES (v_lote_id, 'reprovado', v_profile_id);
            END IF;
        WHEN 'enviar_envase' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'envase');
        WHEN 'concluir_envase' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'pronto_entrega');
        WHEN 'gerar_estoque', 'reservar_estoque' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'pronto_entrega');
        -- GATE 4: criar_entrega NAO altera o status da OS para 'entregue'.
        WHEN 'criar_entrega' THEN NULL;
        WHEN 'enviar_entrega' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'entregue');
        WHEN 'finalizar_os' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'finalizada');
        ELSE
    END CASE;

    INSERT INTO public.laboratorio_esteira_eventos (os_id, origem_os, programacao_id, etapa_anterior, etapa_nova, acao, usuario_id)
    VALUES (p_os_id, p_origem_os, p_programacao_id, v_etapa_anterior_os, p_etapa_destino, p_etapa_destino, auth.uid());

    RETURN jsonb_build_object('success', true, 'replay', false, 'message', 'Etapa avançada com sucesso');
END;
$function$

CREATE OR REPLACE FUNCTION public.check_os_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  status_order text[] := ARRAY['aberta', 'aprovada', 'programada', 'em_producao', 'em_cq', 'envase', 'aguardando_reserva', 'pronto_entrega', 'entregue', 'finalizada'];
  old_idx int;
  new_idx int;
  cq_count int;
  v_lote_id uuid;
BEGIN
  IF TG_TABLE_NAME='ordens_servico' AND OLD.status::text='programada' AND NEW.status::text='em_cq'
   AND EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='manual_cq_send_v1' AND target=NEW.id)
   AND EXISTS(SELECT 1 FROM public.programacao_producao p JOIN public.lotes l ON l.programacao_id=p.id JOIN public.clientes c ON c.id=NEW.cliente_id
    WHERE p.ordem_servico_id=NEW.id AND p.ordem_servico_onfarm_id IS NULL AND p.organization_id=platform_private.h15_actor_organization()
    AND l.organization_id=p.organization_id AND NEW.organization_id=p.organization_id AND c.organization_id=p.organization_id AND l.status::text='em_producao')
  THEN RETURN NEW; END IF;
  -- Se o status não mudou, permite
  IF (OLD.status::text = NEW.status::text) THEN
    RETURN NEW;
  END IF;

  -- Se o novo status é 'cancelada', permite
  IF (NEW.status::text = 'cancelada') THEN
    RETURN NEW;
  END IF;

  -- Validação específica: Bloquear avanço para 'envase' se o CQ não estiver aprovado
  IF (NEW.status::text = 'envase') THEN
    -- Encontrar o lote associado a esta OS OnFarm
    -- A relação é OS -> Programação -> Lote
    SELECT l.id INTO v_lote_id
    FROM public.lotes l
    JOIN public.programacao_producao pp ON l.programacao_id = pp.id
    WHERE pp.ordem_servico_onfarm_id = NEW.id
    LIMIT 1;

    -- Se não encontrar por ordem_servico_onfarm_id, tenta pelo ordem_servico_id (caso seja OS padrão)
    IF v_lote_id IS NULL THEN
        SELECT l.id INTO v_lote_id
        FROM public.lotes l
        JOIN public.programacao_producao pp ON l.programacao_id = pp.id
        WHERE pp.ordem_servico_id = NEW.id
        LIMIT 1;
    END IF;

    IF v_lote_id IS NOT NULL THEN
        -- Verificar se existe controle de qualidade aprovado para este lote
        -- Assumindo que o enum de resultado do CQ possui 'aprovado'
        SELECT count(*) INTO cq_count
        FROM public.controle_qualidade
        WHERE lote_id = v_lote_id AND resultado::text = 'aprovado';

        IF cq_count = 0 THEN
            RAISE EXCEPTION 'Não é possível avançar para ENVASE: O lote vinculado a esta Ordem de Serviço ainda não possui um laudo de Controle de Qualidade APROVADO.'
            USING ERRCODE = 'check_violation';
        END IF;
    ELSE
        -- Se não há lote/programação, mas tentou ir para envase, pode ser inconsistência de dados
        -- Mas se o fluxo operacional permite envase sem lote em casos raros, poderíamos ignorar.
        -- Para garantir segurança, vamos exigir o lote se estiver na fase de produção.
        RAISE EXCEPTION 'Não é possível avançar para ENVASE: Nenhum lote de produção foi localizado para esta Ordem de Serviço.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Encontra os índices na esteira
  SELECT i INTO old_idx FROM unnest(status_order) WITH ORDINALITY AS t(val, i) WHERE val = OLD.status::text;
  SELECT i INTO new_idx FROM unnest(status_order) WITH ORDINALITY AS t(val, i) WHERE val = NEW.status::text;

  -- Validações:
  -- 1. Se o status antigo ou novo não estão na lista (e não é cancelamento), lança erro
  IF old_idx IS NULL OR new_idx IS NULL THEN
    RAISE EXCEPTION 'Status inválido ou transição não permitida para o fluxo operacional.';
  END IF;

  -- 2. Permite apenas avançar 1 posição por vez
  IF new_idx <> old_idx + 1
     AND NOT (new_idx = old_idx + 2 AND status_order[old_idx + 1] = 'aguardando_reserva') THEN
    RAISE EXCEPTION 'Transição de status inválida na esteira de produção: % -> %. A próxima etapa obrigatória é %.', 
      OLD.status::text, NEW.status::text, status_order[old_idx + 1];
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_checkin_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status status_registro_consultor;
  v_natureza natureza_registro_consultor;
  v_registro_id uuid;
  v_is_admin boolean;
BEGIN
  v_registro_id := COALESCE(NEW.registro_consultor_id, OLD.registro_consultor_id);
  IF v_registro_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT status, COALESCE(natureza_registro, 'ocorrencia'::natureza_registro_consultor)
    INTO v_status, v_natureza
    FROM public.registros_consultor
   WHERE id = v_registro_id;

  IF v_natureza <> 'visita'::natureza_registro_consultor THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_is_admin := public.has_role(auth.uid(), 'administrador'::app_role);

  -- Only block UPDATE/DELETE on finalized (INSERT is allowed for the
  -- finish RPC which fires within the same transaction before status flips)
  IF TG_OP IN ('UPDATE','DELETE')
     AND v_status = 'finalizado'::status_registro_consultor
     AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Check-ins da visita % são imutáveis (visita finalizada).', v_registro_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_dossier_block(p_dossier_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_row public.microorganism_regulatory_dossiers;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF nullif(btrim(coalesce(p_reason,'')),'') IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_JUSTIFICATION_REQUIRED' USING ERRCODE='22023';
  END IF;
  PERFORM set_config('app.regulatory_formal_op','on', true);
  UPDATE public.microorganism_regulatory_dossiers
     SET status = 'BLOCKED', blocked_reason = p_reason, updated_by = auth.uid()
   WHERE id = p_dossier_id AND deleted_at IS NULL RETURNING * INTO v_row;
  PERFORM set_config('app.regulatory_formal_op','', true);
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_FOUND' USING ERRCODE='22023'; END IF;
  RETURN to_jsonb(v_row);
END $function$

