CREATE OR REPLACE FUNCTION public.rpc_claim_communication_outbox(p_batch_size integer, p_worker_id text, p_lease_seconds integer DEFAULT 60)
 RETURNS SETOF comunicacao_outbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch int := GREATEST(1, LEAST(COALESCE(p_batch_size,10), 100));
  v_lease int := GREATEST(5, LEAST(COALESCE(p_lease_seconds,60), 900));
  v_worker text := NULLIF(trim(COALESCE(p_worker_id,'')), '');
  v_role text;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege';
  END IF;
  IF v_worker IS NULL OR length(v_worker) > 80 THEN
    RAISE EXCEPTION 'worker_id inválido';
  END IF;

  RETURN QUERY
  WITH candidatos AS (
    SELECT id FROM public.comunicacao_outbox
     WHERE ((status = 'pending' AND next_attempt_at <= now())
         OR (status = 'processing' AND lease_expires_at IS NOT NULL AND lease_expires_at < now()))
     ORDER BY next_attempt_at ASC
     LIMIT v_batch FOR UPDATE SKIP LOCKED
  ),
  updated AS (
    UPDATE public.comunicacao_outbox o
       SET status = 'processing', locked_at = now(), locked_by = v_worker,
           lease_expires_at = now() + make_interval(secs => v_lease),
           attempts = o.attempts + 1
      FROM candidatos c WHERE o.id = c.id RETURNING o.*
  )
  SELECT * FROM updated;
END$function$

CREATE OR REPLACE FUNCTION public.rpc_resolve_outbox_address(p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.comunicacao_outbox%rowtype; v_role text; v_email text;
  v_phone_raw text; v_phone text; v_ok boolean; v_hash text; v_redacted text;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege'; END IF;
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status NOT IN ('processing') THEN
    RETURN jsonb_build_object('ok',false,'outcome','skipped','reason','not_processing'); END IF;
  v_ok := public._comunicacao_can_deliver(r.recipient_user_id, r.recipient_cliente_id, r.canal);
  IF NOT v_ok THEN
    RETURN jsonb_build_object('ok',false,'outcome','skipped','reason','opt_out_or_unverified'); END IF;
  IF r.canal = 'in_app' THEN
    RETURN jsonb_build_object('ok',true,'canal','in_app',
      'user_id',r.recipient_user_id,'cliente_id',r.recipient_cliente_id); END IF;
  IF r.canal = 'email' THEN
    IF r.recipient_user_id IS NOT NULL THEN
      SELECT lower(nullif(trim(email),'')) INTO v_email FROM public.profiles WHERE user_id = r.recipient_user_id;
    ELSE
      SELECT lower(nullif(trim(email),'')) INTO v_email FROM public.clientes WHERE id = r.recipient_cliente_id;
    END IF;
    IF v_email IS NULL OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
      RETURN jsonb_build_object('ok',false,'outcome','cancelled','reason','invalid_email'); END IF;
    v_hash := encode(extensions.digest(v_email,'sha256'),'hex');
    v_redacted := left(split_part(v_email,'@',1),2) || '***@' || split_part(v_email,'@',2);
    RETURN jsonb_build_object('ok',true,'canal','email','address',v_email,
      'address_hash',v_hash,'redacted',v_redacted,
      'user_id',r.recipient_user_id,'cliente_id',r.recipient_cliente_id);
  END IF;
  IF r.canal = 'whatsapp' THEN
    IF r.recipient_user_id IS NOT NULL THEN
      SELECT telefone INTO v_phone_raw FROM public.profiles WHERE user_id = r.recipient_user_id;
    ELSE
      SELECT COALESCE(telefone, (telefones)[1]) INTO v_phone_raw FROM public.clientes WHERE id = r.recipient_cliente_id;
    END IF;
    v_phone_raw := regexp_replace(COALESCE(v_phone_raw,''), '[^0-9]', '', 'g');
    IF length(v_phone_raw) IN (10,11) THEN v_phone := '+55' || v_phone_raw;
    ELSIF length(v_phone_raw) BETWEEN 12 AND 15 THEN v_phone := '+' || v_phone_raw;
    ELSE RETURN jsonb_build_object('ok',false,'outcome','cancelled','reason','invalid_phone'); END IF;
    v_hash := encode(extensions.digest(v_phone,'sha256'),'hex');
    v_redacted := left(v_phone,4) || repeat('*', GREATEST(0, length(v_phone)-6)) || right(v_phone,2);
    RETURN jsonb_build_object('ok',true,'canal','whatsapp','address',v_phone,
      'address_hash',v_hash,'redacted',v_redacted,
      'user_id',r.recipient_user_id,'cliente_id',r.recipient_cliente_id);
  END IF;
  RETURN jsonb_build_object('ok',false,'outcome','cancelled','reason','unsupported_canal');
END$function$

CREATE OR REPLACE FUNCTION public.rpc_service_clear_provider_secret(p_slot text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
DECLARE
  v_col text;
  v_existing uuid;
BEGIN
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  CASE p_slot
    WHEN 'smtp_password'          THEN v_col := 'secret_smtp_password';
    WHEN 'whatsapp_access_token'  THEN v_col := 'secret_whatsapp_access_token';
    WHEN 'whatsapp_app_secret'    THEN v_col := 'secret_whatsapp_app_secret';
    WHEN 'whatsapp_verify_token'  THEN v_col := 'secret_whatsapp_verify_token';
    ELSE RAISE EXCEPTION 'invalid_slot' USING ERRCODE = '22023';
  END CASE;

  EXECUTE format('SELECT %I FROM public.communication_provider_settings WHERE id = 1', v_col)
    INTO v_existing;

  IF v_existing IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_existing;
    EXECUTE format(
      'UPDATE public.communication_provider_settings SET %I = NULL, updated_at = now(), updated_by = $1 WHERE id = 1',
      v_col
    ) USING p_actor;
  END IF;

  INSERT INTO public.communication_provider_settings_audit(actor_id, action, secret_field, changed_fields)
  VALUES (p_actor, 'clear_secret', p_slot, ARRAY[v_col]);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_service_set_provider_secret(p_slot text, p_value text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
DECLARE
  v_col text;
  v_name text;
  v_existing uuid;
  v_new uuid;
BEGIN
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_value IS NULL OR length(p_value) = 0 THEN
    RAISE EXCEPTION 'empty_value' USING ERRCODE = '22023';
  END IF;

  CASE p_slot
    WHEN 'smtp_password'          THEN v_col := 'secret_smtp_password';         v_name := 'comm_smtp_password';
    WHEN 'whatsapp_access_token'  THEN v_col := 'secret_whatsapp_access_token'; v_name := 'comm_whatsapp_access_token';
    WHEN 'whatsapp_app_secret'    THEN v_col := 'secret_whatsapp_app_secret';   v_name := 'comm_whatsapp_app_secret';
    WHEN 'whatsapp_verify_token'  THEN v_col := 'secret_whatsapp_verify_token'; v_name := 'comm_whatsapp_verify_token';
    ELSE RAISE EXCEPTION 'invalid_slot' USING ERRCODE = '22023';
  END CASE;

  EXECUTE format('SELECT %I FROM public.communication_provider_settings WHERE id = 1', v_col)
    INTO v_existing;

  IF v_existing IS NOT NULL THEN
    PERFORM vault.update_secret(v_existing, p_value, v_name || '_' || extract(epoch from now())::bigint::text, NULL);
    v_new := v_existing;
  ELSE
    v_new := vault.create_secret(p_value, v_name || '_' || extract(epoch from now())::bigint::text, NULL);
  END IF;

  EXECUTE format(
    'UPDATE public.communication_provider_settings SET %I = $1, updated_at = now(), updated_by = $2 WHERE id = 1',
    v_col
  ) USING v_new, p_actor;

  INSERT INTO public.communication_provider_settings_audit(actor_id, action, secret_field, changed_fields)
  VALUES (p_actor, 'set_secret', p_slot, ARRAY[v_col]);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.update_global_product_metadata_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid; v_old public.produtos%ROWTYPE; v_new public.produtos%ROWTYPE;
  v_existing public.catalog_platform_admin_audit%ROWTYPE;
  v_patch jsonb:='{}'::jsonb; v_before jsonb:='{}'::jsonb; v_after jsonb:='{}'::jsonb;
  v_request jsonb; v_receipt jsonb; v_audit uuid; v_field text; v_text text;
  v_fields constant text[]:=ARRAY['nome','descricao','modo_acao','funcao_completa','modo_aplicacao'];
BEGIN
  -- Direct core calls have EXACTLY the wrapper's authorization/validation; no
  -- caller/GUC ticket can bypass these checks. service_role without actor denied.
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at)
    OR p_idempotency_key IS NULL OR p_reason IS NULL OR pg_catalog.char_length(pg_catalog.btrim(p_reason)) NOT BETWEEN 10 AND 500
    OR pg_catalog.jsonb_typeof(p_patch) IS DISTINCT FROM 'object' OR p_patch='{}'::jsonb THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_metadata_invalid';
  END IF;
  FOR v_field IN SELECT pg_catalog.jsonb_object_keys(p_patch) LOOP
    IF NOT (v_field=ANY(v_fields)) OR pg_catalog.jsonb_typeof(p_patch->v_field) NOT IN ('string','null') THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_metadata_invalid';
    END IF;
    v_text:=p_patch->>v_field;
    IF v_field='nome' THEN
      IF v_text IS NULL OR pg_catalog.char_length(pg_catalog.btrim(v_text)) NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_metadata_invalid';
      END IF;
      v_text:=pg_catalog.btrim(v_text);
    ELSIF pg_catalog.char_length(v_text)>10000 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_metadata_invalid';
    END IF;
    v_patch:=v_patch || pg_catalog.jsonb_build_object(v_field,v_text);
  END LOOP;
  -- Serialize globally unique correlation BEFORE product lock. Same key on
  -- different actor/target cannot expose a replay; comparison happens after auth.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_idempotency_key::text,0));
  SELECT * INTO v_old FROM public.produtos WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_metadata_unavailable'; END IF;
  v_request:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,
    'patch',v_patch,'reason',pg_catalog.btrim(p_reason));
  SELECT * INTO v_existing FROM public.catalog_platform_admin_audit WHERE correlation_id=p_idempotency_key;
  IF FOUND THEN
    IF v_existing.operation<>'update_global_product_metadata' OR v_existing.actor_id<>v_actor
      OR v_existing.counts_after->'request' IS DISTINCT FROM v_request THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_metadata_conflict';
    END IF;
    RETURN (v_existing.counts_after->'receipt') || pg_catalog.jsonb_build_object('idempotent',true);
  END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_metadata_conflict';
  END IF;
  FOR v_field IN SELECT pg_catalog.jsonb_object_keys(v_patch) LOOP
    IF pg_catalog.to_jsonb(v_old)->v_field IS NOT DISTINCT FROM v_patch->v_field THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_metadata_no_change';
    END IF;
    v_before:=v_before || pg_catalog.jsonb_build_object(v_field,pg_catalog.to_jsonb(v_old)->v_field);
  END LOOP;
  UPDATE public.produtos SET
    nome=CASE WHEN v_patch?'nome' THEN v_patch->>'nome' ELSE nome END,
    descricao=CASE WHEN v_patch?'descricao' THEN v_patch->>'descricao' ELSE descricao END,
    modo_acao=CASE WHEN v_patch?'modo_acao' THEN v_patch->>'modo_acao' ELSE modo_acao END,
    funcao_completa=CASE WHEN v_patch?'funcao_completa' THEN v_patch->>'funcao_completa' ELSE funcao_completa END,
    modo_aplicacao=CASE WHEN v_patch?'modo_aplicacao' THEN v_patch->>'modo_aplicacao' ELSE modo_aplicacao END,
    updated_at=pg_catalog.clock_timestamp()
  WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_new;
  IF NOT FOUND OR v_new.id IS DISTINCT FROM p_id OR v_new.updated_at IS NOT DISTINCT FROM v_old.updated_at
    OR (pg_catalog.to_jsonb(v_old)-(v_fields||ARRAY['updated_at'])) IS DISTINCT FROM
       (pg_catalog.to_jsonb(v_new)-(v_fields||ARRAY['updated_at'])) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_metadata_confirmation_failed';
  END IF;
  FOR v_field IN SELECT pg_catalog.jsonb_object_keys(v_patch) LOOP
    IF pg_catalog.to_jsonb(v_new)->v_field IS DISTINCT FROM v_patch->v_field THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_metadata_confirmation_failed';
    END IF;
    v_after:=v_after || pg_catalog.jsonb_build_object(v_field,pg_catalog.to_jsonb(v_new)->v_field);
  END LOOP;
  FOREACH v_field IN ARRAY v_fields LOOP
    IF NOT (v_patch?v_field) AND pg_catalog.to_jsonb(v_old)->v_field IS DISTINCT FROM pg_catalog.to_jsonb(v_new)->v_field THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_metadata_confirmation_failed';
    END IF;
  END LOOP;
  v_audit:=pg_catalog.gen_random_uuid();
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'idempotent',false,'audit_id',v_audit);
  INSERT INTO public.catalog_platform_admin_audit(id,operation,actor_id,reason,correlation_id,status,counts_before,counts_after,completed_at)
  VALUES(v_audit,'update_global_product_metadata',v_actor,pg_catalog.btrim(p_reason),p_idempotency_key,'completed',
    pg_catalog.jsonb_build_object('values',v_before),pg_catalog.jsonb_build_object('values',v_after,'request',v_request,'receipt',v_receipt),pg_catalog.clock_timestamp());
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.create_organization_core(_nome text, _nome_fantasia text, _cnpj text, _email text, _plan_key text, _rascunho boolean DEFAULT false, _dados jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid; v_cnpj text; v_plan uuid; v_status text; v_patch jsonb; v_dados jsonb := '{}'::jsonb; k text; v text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING errcode='42501'; END IF;
  IF _nome IS NULL OR length(btrim(_nome))<2 OR length(_nome)>200 THEN RAISE EXCEPTION 'platform_invalid: nome/razão social obrigatório' USING ERRCODE='22023'; END IF;
  IF length(coalesce(_nome_fantasia,''))>200 THEN RAISE EXCEPTION 'platform_invalid: nome fantasia muito longo' USING ERRCODE='22023'; END IF;
  IF _email IS NULL OR length(_email)>255 OR btrim(_email)!~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN RAISE EXCEPTION 'platform_invalid: e-mail corporativo inválido' USING ERRCODE='22023'; END IF;
  v_cnpj:=platform_private.cnpj_normalizar(_cnpj); IF v_cnpj IS NOT NULL AND NOT platform_private.cnpj_valido(v_cnpj) THEN RAISE EXCEPTION 'platform_invalid: CNPJ inválido (dígitos verificadores)' USING ERRCODE='22023'; END IF;
  IF v_cnpj IS NULL AND NOT coalesce(_rascunho,false) THEN RAISE EXCEPTION 'platform_invalid: sem CNPJ, crie como rascunho' USING ERRCODE='22023'; END IF;
  BEGIN
    v_patch := platform_private.org_cadastro_patch(_dados);
  EXCEPTION WHEN raise_exception THEN
    RAISE EXCEPTION 'platform_invalid: %', replace(SQLERRM,'org_invalid: ','') USING ERRCODE='22023';
  END;
  FOR k, v IN SELECT key, value #>> '{}' FROM jsonb_each(v_patch) LOOP
    IF v <> '' THEN v_dados := v_dados || jsonb_build_object(k, v); END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['telefone','cep','logradouro','numero','bairro','cidade','uf'] LOOP
    IF NOT v_dados ? k THEN RAISE EXCEPTION 'platform_invalid: % obrigatório', k USING ERRCODE='22023'; END IF;
  END LOOP;
  IF v_cnpj IS NOT NULL AND EXISTS(SELECT 1 FROM public.organizations WHERE cnpj_normalizado=v_cnpj) THEN RAISE EXCEPTION 'platform_duplicate: CNPJ já cadastrado' USING errcode='23505'; END IF;
  SELECT p.id INTO v_plan FROM public.saas_plans p WHERE p.key=_plan_key AND p.active; IF v_plan IS NULL THEN RAISE EXCEPTION 'platform_invalid: plano inexistente ou inativo' USING ERRCODE='22023'; END IF;
  v_status:=CASE WHEN coalesce(_rascunho,false) THEN 'rascunho' ELSE 'aguardando_ativacao' END;
  PERFORM platform_private.issue_ticket('org_create','00000000-0000-0000-0000-000000000000'::uuid);
  INSERT INTO public.organizations(nome,razao_social,nome_fantasia,cnpj,cnpj_normalizado,email_corporativo,status,ativo,onboarding_dados,fuso_horario)
  VALUES(btrim(_nome),btrim(_nome),nullif(btrim(coalesce(_nome_fantasia,'')),''),v_cnpj,v_cnpj,lower(btrim(_email)),v_status,true,v_dados,v_dados->>'fuso_horario') RETURNING id INTO v_id;
  INSERT INTO public.organization_status_audit(organization_id,status_anterior,status_novo,ator_id,motivo) VALUES(v_id,NULL,v_status,auth.uid(),'criação pela plataforma'); RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_touch_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.updated_at := GREATEST(pg_catalog.clock_timestamp(), OLD.updated_at + interval '1 microsecond');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_entities_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.operation LIKE '%\_global\_microorganism%' OR OLD.operation LIKE '%\_global\_culture%'
    OR NEW.operation LIKE '%\_global\_microorganism%' OR NEW.operation LIKE '%\_global\_culture%' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entities_audit_immutable';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
