$function$

CREATE OR REPLACE FUNCTION public.guard_financial_document_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_org uuid; v_parent_org uuid; v_uid uuid := auth.uid();
  v_path text; v_bucket text; v_parts text[]; v_soft_delete boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
      OR NEW.owner_type IS DISTINCT FROM OLD.owner_type
      OR NEW.owner_id IS DISTINCT FROM OLD.owner_id
      OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by THEN
      RAISE EXCEPTION 'financial_document_identity_immutable' USING ERRCODE = '42501';
    END IF;
    v_soft_delete := OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL
      AND (to_jsonb(NEW) - ARRAY['deleted_at','deleted_by','delete_reason'])
        = (to_jsonb(OLD) - ARRAY['deleted_at','deleted_by','delete_reason']);
    IF (NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
      OR NEW.deleted_by IS DISTINCT FROM OLD.deleted_by
      OR NEW.delete_reason IS DISTINCT FROM OLD.delete_reason) AND NOT v_soft_delete THEN
      RAISE EXCEPTION 'financial_document_tombstone_immutable' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'financial_document_tenant_required' USING ERRCODE = '42501';
  END IF;
  IF v_uid IS NOT NULL THEN
    v_org := public.h15_actor_organization();
    IF v_org IS NULL OR v_org <> NEW.organization_id OR NOT public.is_financial_staff(v_uid) THEN
      RAISE EXCEPTION 'financial_document_actor_denied' USING ERRCODE = '42501';
    END IF;
    IF TG_OP = 'INSERT' AND NEW.uploaded_by IS DISTINCT FROM v_uid THEN
      RAISE EXCEPTION 'financial_document_author_denied' USING ERRCODE = '42501';
    END IF;
    IF v_soft_delete AND (NEW.deleted_by IS DISTINCT FROM v_uid
      OR length(btrim(coalesce(NEW.delete_reason, ''))) NOT BETWEEN 1 AND 500) THEN
      RAISE EXCEPTION 'financial_document_tombstone_denied' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT (current_setting('role', true) = 'service_role'
    OR (current_setting('role', true) = 'none' AND session_user = 'postgres')) THEN
    RAISE EXCEPTION 'financial_document_actor_required' USING ERRCODE = '42501';
  END IF;
  CASE NEW.owner_type
    WHEN 'RECEIVABLE' THEN SELECT organization_id INTO v_parent_org FROM public.accounts_receivable WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'PAYABLE' THEN SELECT organization_id INTO v_parent_org FROM public.accounts_payable WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'DELIVERY' THEN SELECT organization_id INTO v_parent_org FROM public.entregas WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'FISCAL_INVOICE' THEN SELECT organization_id INTO v_parent_org FROM public.fiscal_invoices WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'PAYMENT_RECEIVABLE' THEN SELECT organization_id INTO v_parent_org FROM public.receivable_payments WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'PAYMENT_PAYABLE' THEN SELECT organization_id INTO v_parent_org FROM public.payable_payments WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'FINANCIAL_RECEIPT' THEN SELECT organization_id, storage_path, storage_bucket INTO v_parent_org, v_path, v_bucket FROM public.financial_receipts WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'REPORT_EXPORT' THEN SELECT organization_id, storage_path, storage_bucket INTO v_parent_org, v_path, v_bucket FROM public.financial_report_exports WHERE id = NEW.owner_id FOR SHARE;
    ELSE RAISE EXCEPTION 'financial_document_owner_denied' USING ERRCODE = '42501';
  END CASE;
  IF v_parent_org IS NULL OR v_parent_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'financial_document_owner_denied' USING ERRCODE = '42501';
  END IF;
  IF NEW.fiscal_invoice_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fiscal_invoices WHERE id = NEW.fiscal_invoice_id AND organization_id = NEW.organization_id
  ) THEN RAISE EXCEPTION 'financial_document_fiscal_reference_denied' USING ERRCODE = '42501'; END IF;
  IF NEW.fiscal_event_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fiscal_events WHERE id = NEW.fiscal_event_id AND organization_id = NEW.organization_id
  ) THEN RAISE EXCEPTION 'financial_document_fiscal_reference_denied' USING ERRCODE = '42501'; END IF;
  -- Preserve canonical tombstoning of an unchanged legacy locator. Owner/tenant
  -- and identity still must be valid; NULL-tenant legacy never passes.
  IF v_soft_delete THEN RETURN NEW; END IF;
  IF NOT coalesce(public.storage1_path_strict(NEW.storage_path), false) THEN
    RAISE EXCEPTION 'financial_document_path_denied' USING ERRCODE = '42501';
  END IF;
  v_parts := string_to_array(NEW.storage_path, '/');
  IF NEW.owner_type IN ('FINANCIAL_RECEIPT','REPORT_EXPORT') THEN
    IF v_path IS NULL OR NEW.storage_path IS DISTINCT FROM v_path
      OR v_parts[1] <> NEW.organization_id::text
      OR v_bucket IS DISTINCT FROM (CASE WHEN NEW.owner_type = 'FINANCIAL_RECEIPT' THEN 'financial-receipts' ELSE 'financial-reports' END) THEN
      RAISE EXCEPTION 'financial_document_path_denied' USING ERRCODE = '42501';
    END IF;
  ELSIF array_length(v_parts, 1) <> 3 OR v_parts[1] <> NEW.owner_type
    OR v_parts[2] <> NEW.owner_id::text OR length(v_parts[3]) = 0 THEN
    RAISE EXCEPTION 'financial_document_path_denied' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_micro_normalize(p jsonb, p_create boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE k text; v_out jsonb:='{}'::jsonb; v_num numeric;
  v_text constant jsonb:='{"nome_cientifico":300,"concentracao_label":120,"fornecedor":200,"meio_cultivo":5000,"funcao_agronomica":5000,"observacoes":5000,"descricao":5000}';
BEGIN
  IF p IS NULL OR pg_catalog.jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  FOR k IN SELECT pg_catalog.jsonb_object_keys(p) LOOP
    IF k = 'nome' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR pg_catalog.char_length(pg_catalog.btrim(p->>k)) NOT BETWEEN 1 AND 200 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,pg_catalog.btrim(p->>k));
    ELSIF k = 'tipo' THEN
      -- tipo define prefixo do código gerado no servidor: somente na criação.
      IF NOT p_create OR pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string'
        OR NOT ((p->>k) = ANY(pg_catalog.enum_range(NULL::public.tipo_microrganismo)::text[])) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,p->>k);
    ELSIF k = 'producao_on_farm' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,p->k);
    ELSIF k = 'concentracao_ufc_ml' THEN
      IF pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::numeric);
      ELSE
        IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
        v_num:=(p->>k)::numeric;
        -- Limite alinhado ao front: <= 9007199254740991 (Number.MAX_SAFE_INTEGER) e até 2 casas, sem notação exponencial.
        IF v_num <= 0 OR v_num > 9007199254740991 OR pg_catalog.scale(v_num) > 2 OR (p->>k) ~* 'e' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
        v_out:=v_out||pg_catalog.jsonb_build_object(k,v_num);
      END IF;
    ELSIF v_text ? k THEN
      IF pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::text);
      ELSIF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR pg_catalog.char_length(p->>k) > (v_text->>k)::int THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid';
      ELSE v_out:=v_out||pg_catalog.jsonb_build_object(k,NULLIF(pg_catalog.btrim(p->>k),''));
      END IF;
    ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid';
    END IF;
  END LOOP;
  IF p_create AND NOT (v_out ? 'nome' AND v_out ? 'tipo' AND v_out ? 'producao_on_farm') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  IF NOT p_create AND v_out = '{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_culture_normalize(p jsonb, p_create boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE k text; v_out jsonb:='{}'::jsonb;
BEGIN
  IF p IS NULL OR pg_catalog.jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  FOR k IN SELECT pg_catalog.jsonb_object_keys(p) LOOP
    IF k = 'nome' AND pg_catalog.jsonb_typeof(p->k)='string' AND pg_catalog.char_length(pg_catalog.btrim(p->>k)) BETWEEN 1 AND 120 THEN
      v_out:=v_out||pg_catalog.jsonb_build_object(k,pg_catalog.btrim(p->>k));
    ELSIF k = 'descricao' AND pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::text);
    ELSIF k = 'descricao' AND pg_catalog.jsonb_typeof(p->k)='string' AND pg_catalog.char_length(p->>k) <= 2000 THEN
      v_out:=v_out||pg_catalog.jsonb_build_object(k,NULLIF(pg_catalog.btrim(p->>k),''));
    ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid';
    END IF;
  END LOOP;
  IF (p_create AND NOT v_out ? 'nome') OR (NOT p_create AND v_out='{}'::jsonb) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_entity_replay(p_actor uuid, p_operation text, p_request jsonb, p_reason text, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_existing public.catalog_platform_admin_audit%ROWTYPE;
BEGIN
  IF p_key IS NULL OR p_reason IS NULL OR pg_catalog.char_length(pg_catalog.btrim(p_reason)) NOT BETWEEN 10 AND 500 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_key::text,0));
  SELECT * INTO v_existing FROM public.catalog_platform_admin_audit WHERE correlation_id=p_key;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_existing.actor_id IS DISTINCT FROM p_actor OR v_existing.operation IS DISTINCT FROM p_operation
    OR v_existing.counts_after->'request' IS DISTINCT FROM p_request THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_conflict'; END IF;
  RETURN (v_existing.counts_after->'receipt')||pg_catalog.jsonb_build_object('idempotent',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_b2b_credit_exposure(p_partner_id uuid, p_new_order_amount numeric DEFAULT 0, p_exclude_order_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  PERFORM platform_private.assert_b2b_partner_scope(v_uid, p_partner_id);
  IF p_new_order_amount IS NULL OR p_new_order_amount < 0 OR p_new_order_amount::text IN ('NaN','Infinity','-Infinity') THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;
  IF p_exclude_order_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.partner_orders po WHERE po.id=p_exclude_order_id AND po.partner_id=p_partner_id
  ) THEN
    RAISE EXCEPTION 'forbidden_order' USING ERRCODE = '42501';
  END IF;
  RETURN public.fn_b2b_credit_exposure(p_partner_id, p_new_order_amount, p_exclude_order_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_aprovar_os_v1(p_os_id uuid, p_origem text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_origin text; v_status text; v_org uuid;
BEGIN
 -- Normalização não consulta dados. Alias inválido/inexistente negado igualmente.
 BEGIN v_origin:=public.fn_cockpit_norm_origem(p_origem); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END;
 IF v_origin='b2b' THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=private.assert_os_approval_scope(p_os_id,v_origin);
 IF v_origin='manual' THEN SELECT status::text INTO v_status FROM public.ordens_servico WHERE id=p_os_id;
 ELSE SELECT status::text INTO v_status FROM public.ordens_servico_onfarm WHERE id=p_os_id; END IF;
 IF v_status='aprovada' THEN RETURN jsonb_build_object('success',true,'replay',true,'status','aprovada'); END IF;
 IF v_status IS DISTINCT FROM 'aberta' THEN RETURN jsonb_build_object('success',false,'message','Somente OS aberta pode ser aprovada separadamente.'); END IF;
 IF v_origin='manual' THEN UPDATE public.ordens_servico SET status='aprovada' WHERE id=p_os_id;
 ELSE UPDATE public.ordens_servico_onfarm SET status='aprovada' WHERE id=p_os_id; END IF;
 PERFORM private.assert_os_approval_scope(p_os_id,v_origin);
 RETURN jsonb_build_object('success',true,'replay',false,'status','aprovada','message','OS aprovada; programação e fabricação não iniciadas.');
END $function$

CREATE OR REPLACE FUNCTION public.rpc_planejamento_publicar_v1(p_planning_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_pl public.production_planning%ROWTYPE;
 v_prev public.production_planning_publications%ROWTYPE; v_result jsonb; v_count int;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'nao_autenticado' USING ERRCODE='42501'; END IF;
 IF NOT(public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN RAISE EXCEPTION 'permissao_negada' USING ERRCODE='42501'; END IF;
 IF p_planning_id IS NULL THEN RAISE EXCEPTION 'planejamento_invalido' USING ERRCODE='22023'; END IF;
 IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key))<8 THEN RAISE EXCEPTION 'chave_idempotencia_obrigatoria' USING ERRCODE='22023'; END IF;
 -- Nunca devolver recibo de origem interna bloqueada, nem em replay.
 -- Escopo antes de status/recibo: ID inexistente e cross-tenant dão a mesma negação.
 IF public.h15_actor_organization() IS NULL THEN RAISE EXCEPTION 'LAB_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT pl.* INTO v_pl FROM public.production_planning pl
 WHERE pl.id=p_planning_id AND platform_private.lab_partner_order_authorized(pl.partner_order_id) FOR UPDATE;
 IF v_pl.id IS NULL THEN RAISE EXCEPTION 'LAB_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=v_pl.partner_order_id AND internal_origin_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'B2B_INTERNAL_DOWNSTREAM_UNVERIFIED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('planejamento_publicar:'||p_planning_id::text));
 SELECT * INTO v_prev FROM public.production_planning_publications WHERE idempotency_key=btrim(p_idempotency_key);
 IF FOUND THEN
  IF v_prev.planning_id<>p_planning_id THEN RAISE EXCEPTION 'chave_idempotencia_conflitante' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('ok',true,'replay',true,'planning_id',v_prev.planning_id,'os_created',v_prev.os_created,'resultado',v_prev.resultado);
 END IF;
 SELECT * INTO v_prev FROM public.production_planning_publications WHERE planning_id=p_planning_id;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'replay',true,'planning_id',v_prev.planning_id,'os_created',v_prev.os_created,'resultado',v_prev.resultado); END IF;
 v_result:=public.publish_planning_to_lab(p_planning_id); v_count:=coalesce((v_result->>'os_created')::int,0);
 INSERT INTO public.production_planning_publications(planning_id,partner_order_id,idempotency_key,os_created,resultado,performed_by)
 VALUES(p_planning_id,v_pl.partner_order_id,btrim(p_idempotency_key),v_count,v_result,v_uid);
 RETURN jsonb_build_object('ok',true,'replay',false,'planning_id',p_planning_id,'os_created',v_count,'resultado',v_result);
END $function$

CREATE OR REPLACE FUNCTION public.reject_partner_order(p_order_id uuid, p_approval_notes text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_pid uuid; v_prev partner_order_status; v_partner_user uuid; v_numero text;
BEGIN

  IF NOT public.b2b_phase1_order_visible(p_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_approval_notes IS NULL OR length(trim(p_approval_notes)) = 0 THEN
    RAISE EXCEPTION 'reason_required';
  END IF;

  SELECT partner_id, status, numero INTO v_pid, v_prev, v_numero
    FROM public.partner_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;

  IF v_prev IN ('reprovado','cancelado') THEN
    RAISE EXCEPTION 'already_processed: pedido já está em status %', v_prev;
  END IF;

  IF v_prev = 'aprovado' THEN
    RAISE EXCEPTION 'already_approved: pedido já aprovado não pode ser reprovado';
  END IF;

  IF v_prev NOT IN ('aguardando_aprovacao_credito','em_analise_comercial','solicitado','rascunho') THEN
    RAISE EXCEPTION 'invalid_status_transition: %', v_prev;
  END IF;

  UPDATE public.partner_orders
     SET status = 'reprovado',
         approved_by = v_uid,
         approved_at = now(),
         approval_notes = p_approval_notes,
         ready_for_production = false,
         updated_at = now()
   WHERE id = p_order_id
     AND status = v_prev;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'concurrent_update: status do pedido mudou durante a reprovação';
  END IF;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'rejected',
          jsonb_build_object('status', v_prev),
          jsonb_build_object('status','reprovado','approval_notes',p_approval_notes));

  FOR v_partner_user IN SELECT user_id FROM public.partner_users WHERE partner_id = v_pid LOOP
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_partner_user, 'pedido_b2b_reprovado',
            'Pedido ' || v_numero || ' necessita revisão',
            'Seu pedido necessita revisão comercial. Motivo: ' || p_approval_notes,
            '/portal-parceiro/pedidos');
  END LOOP;
END;
$function$

