CREATE OR REPLACE FUNCTION public.fn_assign_receipt_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year int;
  v_seq int;
  v_code text;
BEGIN
  v_year := EXTRACT(YEAR FROM COALESCE(NEW.payment_date, CURRENT_DATE))::int;
  -- lock the table portion for this year and compute next seq
  PERFORM 1 FROM public.financial_receipts WHERE receipt_year = v_year FOR UPDATE;
  SELECT COALESCE(MAX(receipt_seq), 0) + 1 INTO v_seq
    FROM public.financial_receipts WHERE receipt_year = v_year;
  NEW.receipt_year := v_year;
  NEW.receipt_seq := v_seq;
  NEW.receipt_number := 'REC-' || v_year::text || '-' || lpad(v_seq::text, 6, '0');
  IF NEW.authenticity_code IS NULL THEN
    v_code := upper(substr(encode(extensions.digest(NEW.id::text || gen_random_uuid()::text || clock_timestamp()::text, 'sha256'), 'hex'), 1, 12));
    NEW.authenticity_code := substr(v_code,1,4) || '-' || substr(v_code,5,4) || '-' || substr(v_code,9,4);
  END IF;
  IF NEW.public_verification_token IS NULL THEN
    NEW.public_verification_token := gen_random_uuid();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.read_global_cultures_core(p_search text, p_limit integer, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_search text; v_items jsonb; v_count int;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR p_offset IS NULL OR p_offset NOT BETWEEN 0 AND 1000000
    OR pg_catalog.char_length(COALESCE(p_search,'')) > 120 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  v_search:=pg_catalog.btrim(COALESCE(p_search,''));
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',c.id,'nome',c.nome,'ativo',c.ativo) ORDER BY c.nome,c.id),'[]'::jsonb), count(*)
  INTO v_items, v_count FROM (SELECT id,nome,ativo FROM public.culturas
    WHERE v_search='' OR pg_catalog.strpos(pg_catalog.lower(nome),pg_catalog.lower(v_search))>0
    ORDER BY nome,id LIMIT p_limit+1 OFFSET p_offset) c;
  RETURN pg_catalog.jsonb_build_object('items',CASE WHEN v_count>p_limit THEN v_items - p_limit ELSE v_items END,'has_more',v_count>p_limit);
END;
$function$

