CREATE OR REPLACE FUNCTION public.gerar_codigo_lote(_ano integer DEFAULT (EXTRACT(year FROM now()))::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_prefix text := 'LT-' || _ano::text || '-';
  v_next int;
BEGIN
  IF _ano IS NULL THEN
    RAISE EXCEPTION 'LOTE_ANO_INVALIDO';
  END IF;

  -- Serializa o cálculo sequencial por ano dentro da transação chamadora.
  PERFORM pg_advisory_xact_lock(hashtext('gerar_codigo_lote:' || _ano::text));

  SELECT COALESCE(MAX(NULLIF(regexp_replace(split_part(codigo_lote, '-', 3), '\D', '', 'g'), '')::int), 0) + 1
    INTO v_next
    FROM public.lotes
   WHERE codigo_lote LIKE v_prefix || '%';

  RETURN v_prefix || lpad(v_next::text, 4, '0');
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.transition_subscription_core(_organization_id uuid, _action text, _reason text, _correlation_id uuid, _plan_version_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_sub public.organization_subscriptions%ROWTYPE;
  v_version public.saas_plan_versions%ROWTYPE;
  v_now timestamptz := now();
  v_target public.saas_subscription_status;
  v_existing uuid;
  v_existing_org uuid;
  v_existing_action text;
  v_existing_reason text;
  v_existing_version text;
BEGIN
  -- (1) Ator: papel superadmin (modelo live) + perfil real ativo.
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id = auth.uid() AND p.ativo IS TRUE AND p.senha_provisoria IS NOT TRUE) THEN
    RAISE EXCEPTION 'platform_forbidden: perfil do ator inativo' USING ERRCODE='42501';
  END IF;
  IF _reason IS NULL OR length(btrim(_reason)) < 5 OR _correlation_id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: motivo e correlação obrigatórios' USING ERRCODE='22023';
  END IF;
  IF _action IS NULL OR _action NOT IN ('start_trial','change_plan','mark_past_due','suspend','reactivate_manual','cancel','expire_trial','activate_subscription') THEN
    RAISE EXCEPTION 'platform_invalid: ação inválida' USING ERRCODE='22023';
  END IF;

  -- (5) Contrato de payload por ação, validado ANTES de qualquer replay.
  IF _action = 'activate_subscription' AND _plan_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'platform_invalid: regularização não aceita versão; use Alterar plano separadamente' USING ERRCODE='22023';
  END IF;
  IF _action IN ('change_plan','start_trial') AND _plan_version_id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: versão obrigatória' USING ERRCODE='22023';
  END IF;
  IF _action <> 'change_plan' AND _action <> 'start_trial' AND _plan_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'platform_invalid: versão só é aceita em change_plan/start_trial' USING ERRCODE='22023';
  END IF;

  -- (3) Lock da ORGANIZAÇÃO antes de seleção e de qualquer replay:
  -- serializa transições concorrentes da mesma empresa.
  PERFORM 1 FROM public.organizations o WHERE o.id = _organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform_invalid: empresa inexistente' USING ERRCODE='22023';
  END IF;

  v_now := clock_timestamp();

  -- Idempotência vinculada: mesma correlação só é reutilizada com MESMA
  -- organização, ação, motivo e versão coerente com a ação.
  SELECT h.subscription_id, h.organization_id, h.action, h.reason,
         h.new_values->>'plan_version_id'
  INTO v_existing, v_existing_org, v_existing_action, v_existing_reason, v_existing_version
  FROM public.organization_subscription_history h
  WHERE h.correlation_id = _correlation_id;
  IF v_existing IS NOT NULL THEN
    IF v_existing_org IS DISTINCT FROM _organization_id
       OR v_existing_action IS DISTINCT FROM _action
       OR v_existing_reason IS DISTINCT FROM btrim(_reason)
       OR (_plan_version_id IS NOT NULL
           AND nullif(v_existing_version, '')::uuid IS DISTINCT FROM _plan_version_id)
       OR (_plan_version_id IS NULL AND v_existing_action = 'change_plan') THEN
      RAISE EXCEPTION 'platform_conflict: correlação já utilizada em outra operação' USING ERRCODE='PT409';
    END IF;
    RETURN v_existing;
  END IF;

  -- (3) Corrente primeiro; EXPIRED só como fallback e somente para activate.
  SELECT * INTO v_sub
  FROM public.organization_subscriptions s
  WHERE s.organization_id = _organization_id
    AND s.status IN ('TRIAL','ACTIVE','PAST_DUE','SUSPENDED')
  ORDER BY s.started_at DESC, s.created_at DESC, s.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_sub.id IS NULL AND _action = 'activate_subscription' THEN
    -- Fallback EXPIRED: somente a assinatura MAIS RECENTE da empresa, e só
    -- se a origem TRIAL→EXPIRED estiver comprovada no histórico. Uma
    -- CANCELLED (ou qualquer outra) mais nova bloqueia a ressurreição.
    SELECT * INTO v_sub
    FROM public.organization_subscriptions s
    WHERE s.organization_id = _organization_id
    ORDER BY s.started_at DESC, s.created_at DESC, s.id DESC
    LIMIT 1
    FOR UPDATE;
    IF v_sub.id IS NOT NULL AND (
      v_sub.status <> 'EXPIRED'
      OR NOT EXISTS (
        SELECT 1 FROM public.organization_subscription_history h
        WHERE h.subscription_id = v_sub.id
          AND h.previous_status = 'TRIAL' AND h.new_status = 'EXPIRED'
      )
    ) THEN
      RAISE EXCEPTION 'platform_conflict: assinatura expirada sem origem em trial comprovada' USING ERRCODE='PT409';
    END IF;
  END IF;

  IF _plan_version_id IS NOT NULL THEN
    SELECT * INTO v_version
    FROM public.saas_plan_versions v
    WHERE v.id = _plan_version_id
      AND v.status = 'PUBLISHED'
      AND v.effective_from <= v_now
      AND (v.effective_to IS NULL OR v.effective_to > v_now)
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'platform_invalid: versão inexistente, não publicada ou fora de vigência' USING ERRCODE='22023';
    END IF;
  END IF;

  IF _action = 'start_trial' THEN
    IF v_sub.id IS NOT NULL OR _plan_version_id IS NULL THEN
      RAISE EXCEPTION 'platform_conflict: trial exige empresa sem assinatura corrente e versão vigente' USING ERRCODE='PT409';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.organization_subscriptions s
      WHERE s.organization_id = _organization_id
        AND (
          s.status = 'TRIAL'
          OR EXISTS (
            SELECT 1 FROM public.organization_subscription_history h
            WHERE h.subscription_id = s.id
              AND (h.action = 'start_trial' OR h.new_status = 'TRIAL')
          )
        )
    ) THEN
      RAISE EXCEPTION 'platform_conflict: trial já utilizado' USING ERRCODE='PT409';
    END IF;

    PERFORM platform_private.issue_ticket('saas_subscription_write', _organization_id);
    PERFORM set_config('app.saas_change_reason', btrim(_reason), true);
    PERFORM set_config('app.saas_change_action', _action, true);
    PERFORM set_config('app.saas_correlation_id', _correlation_id::text, true);

    INSERT INTO public.organization_subscriptions(
      organization_id,plan_id,plan_version_id,status,started_at,trial_ends_at,
      price_snapshot,currency_snapshot,billing_cycle,billing_cycle_snapshot,
      limits_snapshot,features_snapshot,state_changed_at,last_correlation_id,created_by
    )
    VALUES(
      _organization_id,v_version.plan_id,v_version.id,'TRIAL',v_now,
      v_now + interval '14 days',v_version.price_amount,v_version.currency,
      v_version.billing_cycle,v_version.billing_cycle,v_version.limits_snapshot,
      v_version.features_snapshot,v_now,_correlation_id,auth.uid()
    )
    RETURNING * INTO v_sub;
    RETURN v_sub.id;
  END IF;

  IF v_sub.id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: assinatura corrente inexistente' USING ERRCODE='22023';
  END IF;

  -- Assinatura legada (sem versão) só sai desse estado por change_plan.
  IF v_sub.plan_version_id IS NULL AND _action <> 'change_plan' THEN
    RAISE EXCEPTION 'platform_conflict: assinatura legada exige regularização explícita de versão (Alterar plano)' USING ERRCODE='PT409';
  END IF;

  -- (2) activate_subscription: valida a versão ATUAL da assinatura
  -- (publicada e vigente) e a empresa ativa; preserva TODOS os snapshots.
  IF _action = 'activate_subscription' THEN
    IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = _organization_id AND o.ativo IS TRUE AND o.status = 'ativa') THEN
      RAISE EXCEPTION 'platform_conflict: empresa inativa não pode ser regularizada' USING ERRCODE='PT409';
    END IF;
    IF v_sub.status NOT IN ('TRIAL','EXPIRED') THEN
      RAISE EXCEPTION 'platform_conflict: transição inválida' USING ERRCODE='PT409';
    END IF;
    -- (4) cancelamento agendado bloqueia a regularização nesta fase.
    IF v_sub.cancel_at IS NOT NULL THEN
      RAISE EXCEPTION 'platform_conflict: assinatura com cancelamento agendado; cancele a agenda antes de regularizar' USING ERRCODE='PT409';
    END IF;
    SELECT * INTO v_version
    FROM public.saas_plan_versions v
    WHERE v.id = v_sub.plan_version_id
      AND v.status = 'PUBLISHED'
      AND v.effective_from <= v_now
      AND (v.effective_to IS NULL OR v.effective_to > v_now)
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'platform_invalid: versão atual da assinatura não está publicada e vigente' USING ERRCODE='22023';
    END IF;
  END IF;

  IF (_action='mark_past_due' AND v_sub.status<>'ACTIVE')
     OR (_action='suspend' AND v_sub.status NOT IN('ACTIVE','PAST_DUE'))
     OR (_action='reactivate_manual' AND v_sub.status<>'SUSPENDED')
     OR (_action='cancel' AND v_sub.status NOT IN('TRIAL','ACTIVE','PAST_DUE','SUSPENDED'))
     OR (_action='expire_trial' AND (v_sub.status<>'TRIAL' OR v_sub.trial_ends_at IS NULL OR v_sub.trial_ends_at>v_now)) THEN
    RAISE EXCEPTION 'platform_conflict: transição inválida' USING ERRCODE='PT409';
  END IF;

  v_target := CASE _action
    WHEN 'mark_past_due' THEN 'PAST_DUE'::public.saas_subscription_status
    WHEN 'suspend' THEN 'SUSPENDED'::public.saas_subscription_status
    WHEN 'reactivate_manual' THEN 'ACTIVE'::public.saas_subscription_status
    WHEN 'cancel' THEN 'CANCELLED'::public.saas_subscription_status
    WHEN 'expire_trial' THEN 'EXPIRED'::public.saas_subscription_status
    WHEN 'activate_subscription' THEN 'ACTIVE'::public.saas_subscription_status
    ELSE v_sub.status
  END;

  PERFORM platform_private.issue_ticket('saas_subscription_write', _organization_id);
  PERFORM set_config('app.saas_change_reason', btrim(_reason), true);
  PERFORM set_config('app.saas_change_action', _action, true);
  PERFORM set_config('app.saas_correlation_id', _correlation_id::text, true);

  -- (4) activate_subscription NÃO toca current_period_start/end nem
  -- snapshots: conversão administrativa sem cobrança/expiração nova.
  UPDATE public.organization_subscriptions s
  SET plan_id = CASE WHEN _action='change_plan' THEN v_version.plan_id ELSE s.plan_id END,
      plan_version_id = CASE WHEN _action='change_plan' THEN v_version.id ELSE s.plan_version_id END,
      status = v_target,
      price_snapshot = CASE WHEN _action='change_plan' THEN v_version.price_amount ELSE s.price_snapshot END,
      currency_snapshot = CASE WHEN _action='change_plan' THEN v_version.currency ELSE s.currency_snapshot END,
      billing_cycle = CASE WHEN _action='change_plan' THEN v_version.billing_cycle ELSE s.billing_cycle END,
      billing_cycle_snapshot = CASE WHEN _action='change_plan' THEN v_version.billing_cycle ELSE s.billing_cycle_snapshot END,
      limits_snapshot = CASE WHEN _action='change_plan' THEN v_version.limits_snapshot ELSE s.limits_snapshot END,
      features_snapshot = CASE WHEN _action='change_plan' THEN v_version.features_snapshot ELSE s.features_snapshot END,
      suspended_at = CASE WHEN v_target='SUSPENDED' THEN coalesce(s.suspended_at,v_now) ELSE NULL END,
      cancelled_at = CASE WHEN v_target='CANCELLED' THEN coalesce(s.cancelled_at,v_now) ELSE NULL END,
      state_changed_at = v_now,
      last_correlation_id = _correlation_id
  WHERE s.id = v_sub.id;

  RETURN v_sub.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_b2b_guard_credit_approval_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (NEW.credit_approved_at IS DISTINCT FROM OLD.credit_approved_at)
     OR (NEW.credit_approved_by IS DISTINCT FROM OLD.credit_approved_by) THEN
    IF COALESCE(current_setting('arbio.b2b_credit_approval', true), 'off') <> 'on' THEN
      RAISE EXCEPTION 'credit_approval_fields_immutable: use approve_b2b_credit';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_b2b_guard_order_items_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id uuid := COALESCE(NEW.order_id, OLD.order_id);
  v_status public.partner_order_status;
BEGIN
  SELECT status INTO v_status FROM public.partner_orders WHERE id = v_order_id;
  IF v_status IS NOT NULL AND public.fn_b2b_status_is_approved_or_later(v_status) THEN
    RAISE EXCEPTION 'order_items_immutable_after_approval: pedido em status %', v_status
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION platform_private.create_global_microorganism_core(p_payload jsonb, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_new public.microrganismos%ROWTYPE; v_receipt jsonb; v_after jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  v:=platform_private.catalog_micro_normalize(p_payload,true);
  v_req:=pg_catalog.jsonb_build_object('payload',v,'reason',pg_catalog.btrim(p_reason));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'create_global_microorganism',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  -- Novo item INATIVO, fora do B2B, sem preço/dose/safra/produto; código pelo trigger do servidor.
  BEGIN
    INSERT INTO public.microrganismos (nome,tipo,nome_cientifico,concentracao_ufc_ml,concentracao_label,fornecedor,producao_on_farm,
      meio_cultivo,funcao_agronomica,observacoes,descricao,ativo,b2b_enabled,codigo,dose_ml_ha,valor_dose_brl,valor_litro_brl,preco_tabela,
      safra_referencia,product_id)
    VALUES (v->>'nome',(v->>'tipo')::public.tipo_microrganismo,v->>'nome_cientifico',(v->>'concentracao_ufc_ml')::numeric,v->>'concentracao_label',
      v->>'fornecedor',(v->>'producao_on_farm')::boolean,v->>'meio_cultivo',v->>'funcao_agronomica',v->>'observacoes',v->>'descricao',
      false,false,NULL,NULL,NULL,NULL,NULL,NULL,NULL)
    RETURNING * INTO v_new;
  EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='catalog_entity_duplicate';
  END;
  IF v_new.id IS NULL OR v_new.codigo IS NULL OR v_new.ativo OR v_new.b2b_enabled OR v_new.valor_dose_brl IS NOT NULL
    OR v_new.dose_ml_ha IS NOT NULL OR v_new.safra_referencia IS NOT NULL
    OR v_new.valor_litro_brl IS NOT NULL OR v_new.preco_tabela IS NOT NULL OR v_new.product_id IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_after:=platform_private.read_global_microorganism_detail_core(v_new.id);
  v_receipt:=pg_catalog.jsonb_build_object('id',v_new.id,'codigo',v_new.codigo,'ativo',false,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'create_global_microorganism',p_reason,p_idempotency_key,v_req,v_receipt,'{}'::jsonb,v_after);
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.update_global_microorganism_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_old public.microrganismos%ROWTYPE; v_new public.microrganismos%ROWTYPE;
  v_before jsonb; v_after jsonb; v_receipt jsonb; v_keys text[];
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  v:=platform_private.catalog_micro_normalize(p_patch,false);
  v_req:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'patch',v,'reason',pg_catalog.btrim(p_reason));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'update_global_microorganism',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  SELECT * INTO v_old FROM public.microrganismos WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entity_unavailable'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_conflict'; END IF;
  v_before:=platform_private.read_global_microorganism_detail_core(p_id);
  SELECT pg_catalog.array_agg(k) INTO v_keys FROM pg_catalog.jsonb_object_keys(v) k;
  BEGIN
    UPDATE public.microrganismos SET
      nome=CASE WHEN v ? 'nome' THEN v->>'nome' ELSE nome END,
      nome_cientifico=CASE WHEN v ? 'nome_cientifico' THEN v->>'nome_cientifico' ELSE nome_cientifico END,
      concentracao_ufc_ml=CASE WHEN v ? 'concentracao_ufc_ml' THEN (v->>'concentracao_ufc_ml')::numeric ELSE concentracao_ufc_ml END,
      concentracao_label=CASE WHEN v ? 'concentracao_label' THEN v->>'concentracao_label' ELSE concentracao_label END,
      fornecedor=CASE WHEN v ? 'fornecedor' THEN v->>'fornecedor' ELSE fornecedor END,
      producao_on_farm=CASE WHEN v ? 'producao_on_farm' THEN (v->>'producao_on_farm')::boolean ELSE producao_on_farm END,
      meio_cultivo=CASE WHEN v ? 'meio_cultivo' THEN v->>'meio_cultivo' ELSE meio_cultivo END,
      funcao_agronomica=CASE WHEN v ? 'funcao_agronomica' THEN v->>'funcao_agronomica' ELSE funcao_agronomica END,
      observacoes=CASE WHEN v ? 'observacoes' THEN v->>'observacoes' ELSE observacoes END,
      descricao=CASE WHEN v ? 'descricao' THEN v->>'descricao' ELSE descricao END
    WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_new;
  EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='catalog_entity_duplicate';
  END;
  -- Confirma linha/ID/versão e que NENHUMA coluna fora da whitelist mudou — inclusive preços (valor_dose_brl,
  -- valor_litro_brl, preco_tabela), dose, B2B, código, produto e ativo. Se algum trigger (ex.: guard de preço
  -- canônico) recalcular campo protegido, a edição descritiva aborta integralmente (rollback da transação).
  IF NOT FOUND OR v_new.id IS DISTINCT FROM p_id OR v_new.updated_at <= v_old.updated_at
    OR (pg_catalog.to_jsonb(v_old) - v_keys - 'updated_at')
       IS DISTINCT FROM (pg_catalog.to_jsonb(v_new) - v_keys - 'updated_at') THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_after:=platform_private.read_global_microorganism_detail_core(p_id);
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'ativo',v_new.ativo,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'update_global_microorganism',p_reason,p_idempotency_key,v_req,v_receipt,v_before,v_after);
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_registrar_pdf_termo_v1(p_termo_id uuid, p_pdf_path text, p_pdf_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_t public.entrega_termos%ROWTYPE;
BEGIN
  SELECT * INTO v_t FROM public.entrega_termos WHERE id = p_termo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'termo_nao_encontrado'; END IF;
  IF v_t.status <> 'assinado' THEN RAISE EXCEPTION 'termo_nao_assinado'; END IF;
  IF coalesce(trim(p_pdf_path),'') = '' OR coalesce(trim(p_pdf_hash),'') = '' THEN
    RAISE EXCEPTION 'pdf_path_e_hash_obrigatorios';
  END IF;

  IF v_t.pdf_path IS NOT NULL THEN
    IF v_t.pdf_path = p_pdf_path AND v_t.pdf_hash = p_pdf_hash THEN
      RETURN jsonb_build_object('success', true, 'replay', true, 'pdf_path', v_t.pdf_path);
    END IF;
    RAISE EXCEPTION 'pdf_ja_registrado';
  END IF;

  UPDATE public.entrega_termos
     SET pdf_path = p_pdf_path, pdf_hash = p_pdf_hash, pdf_gerado_em = now()
   WHERE id = p_termo_id;

  RETURN jsonb_build_object('success', true, 'replay', false, 'pdf_path', p_pdf_path);
END $function$

CREATE OR REPLACE FUNCTION public.fn_create_programacao_on_os_classica_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status::text NOT IN ('aberta','aprovada','programada') THEN
    RETURN NEW;
  END IF;
  IF NEW.produto_id IS NULL AND NEW.microrganismo_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM public.programacao_producao WHERE ordem_servico_id = NEW.id) THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.programacao_producao
    (produto_id, microrganismo_id, volume_necessario, data_programada, status, ordem_servico_id)
  VALUES
    (NEW.produto_id, NEW.microrganismo_id, NEW.volume_total_ml,
     COALESCE(NEW.data_programada, CURRENT_DATE), 'aguardando', NEW.id);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.set_global_microorganism_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_old public.microrganismos%ROWTYPE; v_new public.microrganismos%ROWTYPE; v_receipt jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_ativo IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  v_req:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'ativo',p_ativo,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'set_global_microorganism_status',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  SELECT * INTO v_old FROM public.microrganismos WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entity_unavailable'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_conflict'; END IF;
  IF v_old.ativo = p_ativo THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_no_change'; END IF;
  -- Arquivar = ativo false; nunca exclui. b2b_enabled/preços não são tocados.
  UPDATE public.microrganismos SET ativo=p_ativo WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_new;
  IF NOT FOUND OR v_new.ativo IS DISTINCT FROM p_ativo OR v_new.updated_at <= v_old.updated_at
    OR (pg_catalog.to_jsonb(v_old) - ARRAY['ativo','updated_at'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(v_new) - ARRAY['ativo','updated_at']) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'ativo',v_new.ativo,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_microorganism_status',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('ativo',v_old.ativo,'updated_at',v_old.updated_at),
    pg_catalog.jsonb_build_object('ativo',v_new.ativo,'updated_at',v_new.updated_at));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_create_programacao_on_os_onfarm_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF NEW.status::text NOT IN ('aberta','aprovada','programada') THEN RETURN NEW; END IF;
 IF NEW.produto_id IS NULL AND NEW.microrganismo_id IS NULL THEN RETURN NEW; END IF;
 PERFORM platform_private.lab_assert_manufacturable(NEW.produto_id,NEW.microrganismo_id);
 IF EXISTS(SELECT 1 FROM public.programacao_producao WHERE ordem_servico_onfarm_id=NEW.id) THEN RETURN NEW; END IF;
 INSERT INTO public.programacao_producao(produto_id,microrganismo_id,volume_necessario,data_programada,status,ordem_servico_onfarm_id)
 VALUES(NEW.produto_id,NEW.microrganismo_id,NEW.volume_total_ml,coalesce(NEW.data_recomendada,CURRENT_DATE),'aguardando',NEW.id);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_cancelar_v1(p_entrega_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_entrega public.entregas%ROWTYPE;
  v_item public.estoque_produto%ROWTYPE;
  v_mov public.estoque_movimentacoes%ROWTYPE;
  v_origem text;
  v_estorno jsonb;
  v_reserva jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'ENTREGA_NAO_AUTENTICADO' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT (
    public.has_role(v_uid, 'administrador'::public.app_role)
    OR public.has_role(v_uid, 'gestor'::public.app_role)
    OR public.has_role(v_uid, 'administrativo'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_SEM_PERMISSAO' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_entrega_id IS NULL OR v_motivo IS NULL THEN
    RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_PARAMETROS_INVALIDOS' USING ERRCODE = 'check_violation';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('entrega_cancelar:' || p_entrega_id::text));
  SELECT * INTO v_entrega FROM public.entregas WHERE id = p_entrega_id FOR UPDATE;

  IF v_entrega.id IS NULL THEN
    RAISE EXCEPTION 'ENTREGA_NAO_ENCONTRADA' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_entrega.status::text = 'cancelada' THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'entrega_id', v_entrega.id, 'message', 'Entrega ja estava cancelada.');
  END IF;
  IF v_entrega.status::text = 'entregue' THEN
    RAISE EXCEPTION 'ENTREGA_CONFIRMADA_EXIGE_DEVOLUCAO' USING ERRCODE = 'check_violation';
  END IF;
  IF v_entrega.status::text NOT IN ('separado', 'em_rota') THEN
    RAISE EXCEPTION 'ENTREGA_STATUS_NAO_CANCELAVEL' USING ERRCODE = 'check_violation';
  END IF;

  v_origem := CASE WHEN v_entrega.ordem_servico_onfarm_id IS NOT NULL THEN 'onfarm' ELSE 'manual' END;

  IF v_entrega.estoque_produto_id IS NOT NULL THEN
    SELECT * INTO v_item FROM public.estoque_produto WHERE id = v_entrega.estoque_produto_id FOR UPDATE;
    IF v_item.id IS NULL THEN
      RAISE EXCEPTION 'ENTREGA_ESTOQUE_NAO_ENCONTRADO' USING ERRCODE = 'no_data_found';
    END IF;

    SELECT m.* INTO v_mov
      FROM public.estoque_movimentacoes m
     WHERE m.estoque_produto_id = v_item.id
       AND m.referencia_tipo = 'entrega'
       AND m.referencia_id = v_entrega.id
       AND m.acao IN ('expedicao', 'entrega')
       AND NOT EXISTS (SELECT 1 FROM public.estoque_movimentacoes r WHERE r.movimentacao_origem_id = m.id)
     ORDER BY m.created_at DESC, m.id DESC
     LIMIT 1
     FOR UPDATE;

    IF v_mov.id IS NOT NULL THEN
      v_estorno := public.rpc_estoque_operar_v1(
        'estorno_expedicao', v_item.id, NULL,
        'entrega-cancel-estorno:' || v_entrega.id::text,
        jsonb_build_object(
          'origem', 'rpc_entrega_cancelar_v1', 'referencia_tipo', 'entrega',
          'referencia_id', v_entrega.id, 'movimentacao_origem_id', v_mov.id, 'motivo', v_motivo
        )
      );
      SELECT * INTO v_item FROM public.estoque_produto WHERE id = v_entrega.estoque_produto_id FOR UPDATE;
    END IF;

    IF v_item.status::text = 'reservado' THEN
      v_reserva := public.rpc_cockpit_cancelar_reserva_v1(
        v_item.id,
        COALESCE(v_entrega.ordem_servico_onfarm_id, v_entrega.ordem_servico_id),
        v_origem,
        'Cancelamento da entrega ' || v_entrega.id::text || ': ' || v_motivo
      );
    ELSIF v_item.status::text NOT IN ('disponivel', 'estornado') THEN
      RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_ESTOQUE_INCONSISTENTE: status %', v_item.status USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  PERFORM set_config('app.entrega_cancelamento_id', v_entrega.id::text, true);
  UPDATE public.entregas
     SET status = 'cancelada'::public.status_entrega, motivo_cancelamento = v_motivo
   WHERE id = v_entrega.id;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (
    COALESCE(v_entrega.ordem_servico_onfarm_id, v_entrega.ordem_servico_id),
    v_origem, v_entrega.lote_id, 'entrega_criada', 'entrega_cancelada',
    'cancelar_entrega_v1', v_uid, 'Cancelamento atomico. Motivo: ' || v_motivo
  );

  RETURN jsonb_build_object(
    'success', true, 'replay', false, 'entrega_id', v_entrega.id,
    'estoque_estornado', v_estorno IS NOT NULL,
    'reserva_liberada', v_reserva IS NOT NULL,
    'message', 'Entrega cancelada e estoque recomposto.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_envase_avanca_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prog_id uuid;
  v_os_onfarm_id uuid;
  v_os_id uuid;
BEGIN
  SELECT programacao_id INTO v_prog_id FROM public.lotes WHERE id = NEW.lote_id;
  IF v_prog_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ordem_servico_onfarm_id, ordem_servico_id
    INTO v_os_onfarm_id, v_os_id
    FROM public.programacao_producao
    WHERE id = v_prog_id;

  -- Ensure lote is marked as aprovado (envase only passes if CQ aprovado)
  UPDATE public.lotes SET status = 'aprovado' WHERE id = NEW.lote_id AND status::text <> 'aprovado';
  UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id AND status::text <> 'aprovado';

  IF v_os_onfarm_id IS NOT NULL THEN
    UPDATE public.ordens_servico_onfarm
      SET status = 'pronto_entrega'
      WHERE id = v_os_onfarm_id
        AND status::text = 'envase';
  END IF;

  IF v_os_id IS NOT NULL THEN
    UPDATE public.ordens_servico
      SET status = 'pronto_entrega'
      WHERE id = v_os_id
        AND status::text = 'envase';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_envase_material_imutavel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Escape controlado apenas para manutenção/fixtures (nunca anon/authenticated).
  IF COALESCE(current_setting('app.estoque_purge_fixture', true), '') = 'on'
     AND current_user NOT IN ('anon','authenticated') THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ENVASE_IMUTAVEL: o envase % do lote % nao pode ser excluido. Registre um estorno/novo envase.', OLD.id, OLD.lote_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.lote_id IS DISTINCT FROM OLD.lote_id
     OR NEW.quantidade IS DISTINCT FROM OLD.quantidade
     OR NEW.volume_por_unidade IS DISTINCT FROM OLD.volume_por_unidade THEN
    RAISE EXCEPTION 'ENVASE_IMUTAVEL: lote/quantidade/volume_por_unidade do envase % nao podem ser alterados apos o registro.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_gerar_termo_v1(p_entrega_id uuid, p_template_versao text DEFAULT 'termo-entrega-v1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_snap jsonb;
  v_hash text;
  v_cob text;
  v_id uuid;
  v_versao integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sessao_invalida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'sem_permissao'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('entrega_termo:' || p_entrega_id::text, 0));
  -- Tenant explícito: ator canônico ativo/pronto (h15) e entrega+cliente da mesma empresa.
  IF NOT public.is_delivery_staff(v_uid) OR NOT platform_private.entrega_termo_tenant_ok(p_entrega_id) THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;

  IF EXISTS (SELECT 1 FROM public.entrega_termos WHERE entrega_id = p_entrega_id AND status = 'assinado') THEN
    RAISE EXCEPTION 'termo_ja_assinado';
  END IF;

  v_snap := public.fn_entrega_build_snapshot_v1(p_entrega_id);
  v_cob := public.fn_entrega_cobertura_v1(p_entrega_id);
  v_hash := encode(extensions.digest(p_template_versao || '|' || v_snap::text, 'sha256'), 'hex');

  SELECT id INTO v_id FROM public.entrega_termos
   WHERE entrega_id = p_entrega_id AND status = 'rascunho' LIMIT 1;

  IF v_id IS NOT NULL THEN
    UPDATE public.entrega_termos
       SET snapshot = v_snap, snapshot_hash = v_hash, cobertura = v_cob,
           template_versao = p_template_versao, comprovante_id = (SELECT comprovante_id FROM public.entregas WHERE id = p_entrega_id)
     WHERE id = v_id
     RETURNING versao INTO v_versao;
  ELSE
    SELECT coalesce(max(versao), 0) + 1 INTO v_versao
      FROM public.entrega_termos WHERE entrega_id = p_entrega_id;
    INSERT INTO public.entrega_termos
      (entrega_id, comprovante_id, versao, template_versao, status, snapshot, snapshot_hash, cobertura, created_by,
       substitui_termo_id)
    VALUES (p_entrega_id, (SELECT comprovante_id FROM public.entregas WHERE id = p_entrega_id),
            v_versao, p_template_versao, 'rascunho', v_snap, v_hash, v_cob, v_uid,
            (SELECT id FROM public.entrega_termos WHERE entrega_id = p_entrega_id
              AND status IN ('cancelado','substituido') ORDER BY versao DESC LIMIT 1))
    RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'termo_id', v_id, 'versao', v_versao,
                            'snapshot_hash', v_hash, 'cobertura', v_cob);
END $function$

CREATE OR REPLACE FUNCTION public.fn_entrega_marcar_cancelamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status::text = 'cancelada'
     AND (TG_OP = 'INSERT' OR OLD.status::text IS DISTINCT FROM 'cancelada') THEN
    IF auth.uid() IS NOT NULL
       AND current_setting('app.entrega_cancelamento_id', true) IS DISTINCT FROM NEW.id::text THEN
      RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_EXIGE_RPC'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    NEW.cancelada_em := COALESCE(NEW.cancelada_em, now());
    NEW.cancelada_por := COALESCE(NEW.cancelada_por, auth.uid());
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_estoque_produto_guard()
