CREATE OR REPLACE FUNCTION public.fn_financial_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old jsonb; v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN v_old := to_jsonb(OLD); v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'DELETE' THEN v_old := to_jsonb(OLD);
  END IF;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES (TG_TABLE_NAME, COALESCE((NEW).id, (OLD).id), TG_OP, v_old, v_new, auth.uid());

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_certificate_ref_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_certificate_id uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.certificate_ref IS NOT DISTINCT FROM OLD.certificate_ref THEN
    RETURN NEW;
  END IF;

  IF NULLIF(BTRIM(NEW.certificate_ref), '') IS NULL THEN
    NEW.certificate_ref := NULL;
    RETURN NEW;
  END IF;

  IF NEW.certificate_ref !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    RAISE EXCEPTION 'certificate_ref_invalid' USING ERRCODE = '22023';
  END IF;

  v_certificate_id := NEW.certificate_ref::uuid;

  IF NOT EXISTS (
    SELECT 1
    FROM public.fiscal_certificates fc
    WHERE fc.id = v_certificate_id
      AND fc.company_settings_id = NEW.id
      AND fc.environment = 'HOMOLOGATION'
      AND fc.status = 'AVAILABLE'
      AND fc.is_active = true
      AND fc.valid_until > now()
  ) THEN
    RAISE EXCEPTION 'certificate_ref_not_active_homologation' USING ERRCODE = '22023';
  END IF;

  NEW.certificate_ref := v_certificate_id::text;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.create_global_culture_core(p_payload jsonb, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_new public.culturas%ROWTYPE; v_receipt jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  v:=platform_private.catalog_culture_normalize(p_payload,true);
  v_req:=pg_catalog.jsonb_build_object('payload',v,'reason',pg_catalog.btrim(p_reason));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'create_global_culture',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  -- Unicidade case-insensitive serializada (tabela sem UNIQUE).
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-culture-name',0));
  IF EXISTS (SELECT 1 FROM public.culturas WHERE pg_catalog.lower(pg_catalog.btrim(nome))=pg_catalog.lower(v->>'nome')) THEN
    RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='catalog_entity_duplicate'; END IF;
  INSERT INTO public.culturas (nome,descricao,ativo) VALUES (v->>'nome',v->>'descricao',false) RETURNING * INTO v_new;
  IF v_new.id IS NULL OR v_new.ativo THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',v_new.id,'ativo',false,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'create_global_culture',p_reason,p_idempotency_key,v_req,v_receipt,'{}'::jsonb,
    platform_private.read_global_culture_detail_core(v_new.id));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.storage2_salvar_aplicacao_legacy_closed(p_aplicacao_id uuid, p_payload jsonb, p_rectify_id uuid DEFAULT NULL::uuid, p_evidencias jsonb DEFAULT '[]'::jsonb, p_evidencias_manter uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
                                                                                                                                                                        DECLARE
                                                                                                                                                                          v_uid uuid := auth.uid();
                                                                                                                                                                            v_os_id uuid := NULLIF(p_payload->>'ordem_servico_id','')::uuid;
                                                                                                                                                                              v_os_onfarm_id uuid := NULLIF(p_payload->>'ordem_servico_onfarm_id','')::uuid;
                                                                                                                                                                                v_cliente_id uuid; v_produto_os uuid;
                                                                                                                                                                                  v_produto_payload uuid := NULLIF(p_payload->>'produto_usado_id','')::uuid;
                                                                                                                                                                                    v_lote_id uuid := NULLIF(p_payload->>'lote_usado_id','')::uuid; v_lote_produto uuid;
                                                                                                                                                                                      v_original public.aplicacoes%ROWTYPE; v_parent_id uuid; v_versao integer := 1;
                                                                                                                                                                                        v_motivo text := NULLIF(btrim(p_payload->>'motivo_retificacao'),'');
                                                                                                                                                                                          v_dose numeric := NULLIF(p_payload->>'dose_aplicada','')::numeric;
                                                                                                                                                                                            v_area numeric := NULLIF(p_payload->>'area_aplicada_ha','')::numeric;
                                                                                                                                                                                              v_hora_inicio timestamptz := NULLIF(p_payload->>'hora_inicio','')::timestamptz;
                                                                                                                                                                                                v_hora_fim timestamptz := NULLIF(p_payload->>'hora_fim','')::timestamptz;
                                                                                                                                                                                                  v_ev jsonb; v_ev_id uuid; v_manter uuid;
                                                                                                                                                                                                  BEGIN
                                                                                                                                                                                                    IF v_uid IS NULL THEN RAISE EXCEPTION 'Autenticacao obrigatoria' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                      IF p_aplicacao_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Identificador e dados da aplicacao sao obrigatorios' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                        IF jsonb_typeof(COALESCE(p_evidencias,'[]'::jsonb)) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Evidencias invalidas' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                          IF EXISTS (SELECT 1 FROM public.aplicacoes WHERE id=p_aplicacao_id AND created_by=v_uid) THEN RETURN jsonb_build_object('success',true,'created',false,'id',p_aplicacao_id); END IF;
                                                                                                                                                                                                            IF num_nonnulls(v_os_id,v_os_onfarm_id)<>1 THEN RAISE EXCEPTION 'Informe exatamente uma ordem de servico' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                              IF v_os_id IS NOT NULL THEN SELECT cliente_id,produto_id INTO v_cliente_id,v_produto_os FROM public.ordens_servico WHERE id=v_os_id FOR UPDATE;
                                                                                                                                                                                                                ELSE SELECT cliente_id,produto_id INTO v_cliente_id,v_produto_os FROM public.ordens_servico_onfarm WHERE id=v_os_onfarm_id FOR UPDATE; END IF;
                                                                                                                                                                                                                  IF v_cliente_id IS NULL THEN RAISE EXCEPTION 'Ordem de servico inexistente ou sem cliente' USING ERRCODE='23503'; END IF;
                                                                                                                                                                                                                    IF v_produto_os IS NULL THEN RAISE EXCEPTION 'A ordem de servico nao possui produto definido' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                      IF NOT public.can_user_create_aplicacao_for_cliente(v_cliente_id) THEN RAISE EXCEPTION 'Sem permissao para registrar aplicacao deste cliente' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                        IF v_produto_payload IS DISTINCT FROM v_produto_os THEN RAISE EXCEPTION 'Produto informado nao pertence a ordem de servico' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                          IF v_lote_id IS NOT NULL THEN SELECT produto_id INTO v_lote_produto FROM public.lotes WHERE id=v_lote_id; IF v_lote_produto IS DISTINCT FROM v_produto_os THEN RAISE EXCEPTION 'Lote informado nao pertence ao produto da ordem' USING ERRCODE='22023'; END IF; END IF;
                                                                                                                                                                                                                            IF v_dose IS NULL OR v_dose<=0 OR v_area IS NULL OR v_area<=0 THEN RAISE EXCEPTION 'Dose e area devem ser maiores que zero' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                              IF v_hora_inicio IS NOT NULL AND v_hora_fim IS NOT NULL AND v_hora_fim<v_hora_inicio THEN RAISE EXCEPTION 'Horario final nao pode ser anterior ao inicial' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                                IF p_rectify_id IS NOT NULL THEN
                                                                                                                                                                                                                                    SELECT * INTO v_original FROM public.aplicacoes WHERE id=p_rectify_id FOR UPDATE;
                                                                                                                                                                                                                                        IF v_original.id IS NULL OR NOT v_original.is_latest THEN RAISE EXCEPTION 'Somente a versao vigente pode ser retificada' USING ERRCODE='40001'; END IF;
                                                                                                                                                                                                                                            IF NOT public.can_user_access_aplicacao(p_rectify_id) THEN RAISE EXCEPTION 'Sem acesso a aplicacao original' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                                                IF v_original.ordem_servico_id IS DISTINCT FROM v_os_id OR v_original.ordem_servico_onfarm_id IS DISTINCT FROM v_os_onfarm_id THEN RAISE EXCEPTION 'A ordem de servico nao pode ser alterada na retificacao' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                                                    IF v_motivo IS NULL OR char_length(v_motivo) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Motivo da retificacao deve ter entre 5 e 1000 caracteres' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                                                        v_parent_id:=COALESCE(v_original.parent_id,v_original.id); v_versao:=v_original.versao+1;
                                                                                                                                                                                                                                                            UPDATE public.aplicacoes SET is_latest=false WHERE id=v_original.id;
                                                                                                                                                                                                                                                              ELSE v_parent_id:=NULL; v_motivo:=NULL; END IF;
                                                                                                                                                                                                                                                                INSERT INTO public.aplicacoes (id,ordem_servico_id,ordem_servico_onfarm_id,data_aplicacao,hora_inicio,hora_fim,responsavel_id,responsavel,modo_aplicacao,produto_usado_id,lote_usado_id,dose_aplicada,volume_calda_l_ha,volume_total_aplicado_ml,area_aplicada_ha,equipamento,equipamento_modelo,bico_tipo,pressao_bar,temperatura_c,umidade_pct,vento_kmh,condicoes_climaticas,latitude,longitude,resultado_inicial,observacoes,created_by,parent_id,versao,motivo_retificacao,is_latest)
                                                                                                                                                                                                                                                                  VALUES (p_aplicacao_id,v_os_id,v_os_onfarm_id,COALESCE(NULLIF(p_payload->>'data_aplicacao','')::date,CURRENT_DATE),v_hora_inicio,v_hora_fim,NULLIF(p_payload->>'responsavel_id','')::uuid,NULLIF(btrim(p_payload->>'responsavel'),''),NULLIF(btrim(p_payload->>'modo_aplicacao'),''),v_produto_payload,v_lote_id,v_dose,NULLIF(p_payload->>'volume_calda_l_ha','')::numeric,NULLIF(p_payload->>'volume_total_aplicado_ml','')::numeric,v_area,NULLIF(btrim(p_payload->>'equipamento'),''),NULLIF(btrim(p_payload->>'equipamento_modelo'),''),NULLIF(btrim(p_payload->>'bico_tipo'),''),NULLIF(p_payload->>'pressao_bar','')::numeric,NULLIF(p_payload->>'temperatura_c','')::numeric,NULLIF(p_payload->>'umidade_pct','')::numeric,NULLIF(p_payload->>'vento_kmh','')::numeric,NULLIF(btrim(p_payload->>'condicoes_climaticas'),''),NULLIF(p_payload->>'latitude','')::numeric,NULLIF(p_payload->>'longitude','')::numeric,NULLIF(btrim(p_payload->>'resultado_inicial'),''),NULLIF(btrim(p_payload->>'observacoes'),''),v_uid,v_parent_id,v_versao,v_motivo,true);
                                                                                                                                                                                                                                                                    FOR v_ev IN SELECT value FROM jsonb_array_elements(COALESCE(p_evidencias,'[]'::jsonb)) LOOP
                                                                                                                                                                                                                                                                        IF (v_ev->>'storage_path') NOT LIKE v_cliente_id::text||'/'||p_aplicacao_id::text||'/%' THEN RAISE EXCEPTION 'Caminho de evidencia nao pertence a aplicacao' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                                                                            INSERT INTO public.aplicacao_evidencias(aplicacao_id,tipo,url,storage_path,legenda,mime,tamanho_bytes,created_by,versao_origem_id) VALUES(p_aplicacao_id,v_ev->>'tipo',NULL,v_ev->>'storage_path',NULLIF(btrim(v_ev->>'legenda'),''),v_ev->>'mime',NULLIF(v_ev->>'tamanho_bytes','')::bigint,v_uid,p_aplicacao_id) RETURNING id INTO v_ev_id;
                                                                                                                                                                                                                                                                                INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,v_ev_id);
                                                                                                                                                                                                                                                                                  END LOOP;
                                                                                                                                                                                                                                                                                    IF p_rectify_id IS NOT NULL THEN FOREACH v_manter IN ARRAY COALESCE(p_evidencias_manter,'{}'::uuid[]) LOOP
                                                                                                                                                                                                                                                                                        IF NOT EXISTS(SELECT 1 FROM public.aplicacao_evidencias_vinculos WHERE aplicacao_id=p_rectify_id AND evidencia_id=v_manter) THEN RAISE EXCEPTION 'Evidencia herdada nao pertence a versao anterior' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                                                                                            INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,v_manter) ON CONFLICT DO NOTHING;
                                                                                                                                                                                                                                                                                              END LOOP; END IF;
                                                                                                                                                                                                                                                                                                RETURN jsonb_build_object('success',true,'created',true,'id',p_aplicacao_id,'versao',v_versao);
                                                                                                                                                                                                                                                                                                END;
                                                                                                                                                                                                                                                                                                $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_sefaz_tx_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_run_invoice   uuid;
  v_run_state     text;
  v_event_invoice uuid;
  v_event_state   text;
BEGIN
  -- H7G-001: autorização sempre amarrada ao invoice do próprio XML run.
  IF NEW.service = 'NFeAutorizacao4' THEN
    IF NEW.xml_run_id IS NULL THEN
      RAISE EXCEPTION 'SEFAZ_RUN_REQUIRED';
    END IF;
    SELECT fiscal_invoice_id, state INTO v_run_invoice, v_run_state
      FROM public.fiscal_xml_runs WHERE id = NEW.xml_run_id;
    IF v_run_invoice IS NULL THEN
      RAISE EXCEPTION 'SEFAZ_RUN_NOT_FOUND';
    END IF;
    IF v_run_state IS DISTINCT FROM 'SIGNED' THEN
      RAISE EXCEPTION 'SEFAZ_DOCUMENT_NOT_SIGNED';
    END IF;
    IF NEW.fiscal_invoice_id IS DISTINCT FROM v_run_invoice THEN
      RAISE EXCEPTION 'SEFAZ_INVOICE_RUN_MISMATCH';
    END IF;
  END IF;

  IF NEW.xml_run_id IS NOT NULL AND NEW.service <> 'NFeAutorizacao4' THEN
    SELECT fiscal_invoice_id INTO v_run_invoice
      FROM public.fiscal_xml_runs WHERE id = NEW.xml_run_id;
    IF NEW.fiscal_invoice_id IS DISTINCT FROM v_run_invoice THEN
      RAISE EXCEPTION 'SEFAZ_INVOICE_RUN_MISMATCH';
    END IF;
  END IF;

  -- H7G-002: evento sempre amarrado a um evento fiscal preparado e assinado.
  IF NEW.service = 'NFeRecepcaoEvento4' THEN
    IF NEW.fiscal_event_id IS NULL THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_REQUIRED';
    END IF;
    SELECT fiscal_invoice_id, state INTO v_event_invoice, v_event_state
      FROM public.v_fiscal_sefaz_event_state WHERE event_id = NEW.fiscal_event_id;
    IF v_event_invoice IS NULL THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_NOT_FOUND';
    END IF;
    IF v_event_state NOT IN ('SIGNED','REJECTED') THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_NOT_SIGNED';
    END IF;
    IF NEW.fiscal_invoice_id IS DISTINCT FROM v_event_invoice THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_INVOICE_MISMATCH';
    END IF;
  ELSIF NEW.fiscal_event_id IS NOT NULL THEN
    RAISE EXCEPTION 'SEFAZ_EVENT_SERVICE_MISMATCH';
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.update_global_culture_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_old public.culturas%ROWTYPE; v_new public.culturas%ROWTYPE;
  v_before jsonb; v_receipt jsonb; v_keys text[];
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  v:=platform_private.catalog_culture_normalize(p_patch,false);
  v_req:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'patch',v,'reason',pg_catalog.btrim(p_reason));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'update_global_culture',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-culture-name',0));
  SELECT * INTO v_old FROM public.culturas WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entity_unavailable'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_conflict'; END IF;
  IF v ? 'nome' AND EXISTS (SELECT 1 FROM public.culturas WHERE id<>p_id
      AND pg_catalog.lower(pg_catalog.btrim(nome))=pg_catalog.lower(v->>'nome')) THEN
    RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='catalog_entity_duplicate'; END IF;
  v_before:=platform_private.read_global_culture_detail_core(p_id);
  SELECT pg_catalog.array_agg(k) INTO v_keys FROM pg_catalog.jsonb_object_keys(v) k;
  UPDATE public.culturas SET
    nome=CASE WHEN v ? 'nome' THEN v->>'nome' ELSE nome END,
    descricao=CASE WHEN v ? 'descricao' THEN v->>'descricao' ELSE descricao END
  WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_new;
  IF NOT FOUND OR v_new.id IS DISTINCT FROM p_id OR v_new.updated_at <= v_old.updated_at
    OR (pg_catalog.to_jsonb(v_old) - v_keys - 'updated_at') IS DISTINCT FROM (pg_catalog.to_jsonb(v_new) - v_keys - 'updated_at') THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'ativo',v_new.ativo,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'update_global_culture',p_reason,p_idempotency_key,v_req,v_receipt,v_before,
    platform_private.read_global_culture_detail_core(p_id));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_h6b_reconciliacao_valor_faturavel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_canon jsonb;
BEGIN
  IF NEW.status = 'reconciliada' AND NEW.valor_faturavel_max IS NULL THEN
    v_canon := public.fn_entrega_valor_faturavel_v1(NEW.entrega_id);
    IF (v_canon->>'valor') IS NOT NULL THEN
      NEW.valor_faturavel_max  := round((v_canon->>'valor')::numeric, 2);
      NEW.valor_faturavel_origem := v_canon->>'origem';
      NEW.valor_faturavel_metodo := v_canon->'metodo';
    ELSE
      NEW.valor_faturavel_origem := 'indisponivel';
      NEW.valor_faturavel_metodo := v_canon;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.set_global_culture_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_old public.culturas%ROWTYPE; v_new public.culturas%ROWTYPE; v_receipt jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_ativo IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  v_req:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'ativo',p_ativo,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'set_global_culture_status',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  SELECT * INTO v_old FROM public.culturas WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entity_unavailable'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_conflict'; END IF;
  IF v_old.ativo = p_ativo THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_no_change'; END IF;
  -- desativada_em/desativada_por carimbados pelo trigger existente tg_culturas_stamp_desativacao.
  UPDATE public.culturas SET ativo=p_ativo WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_new;
  IF NOT FOUND OR v_new.ativo IS DISTINCT FROM p_ativo OR v_new.updated_at <= v_old.updated_at
    OR (pg_catalog.to_jsonb(v_old) - ARRAY['ativo','updated_at','desativada_em','desativada_por'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(v_new) - ARRAY['ativo','updated_at','desativada_em','desativada_por']) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'ativo',v_new.ativo,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_culture_status',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('ativo',v_old.ativo,'updated_at',v_old.updated_at,'desativada_em',v_old.desativada_em,'desativada_por',v_old.desativada_por),
    pg_catalog.jsonb_build_object('ativo',v_new.ativo,'updated_at',v_new.updated_at,'desativada_em',v_new.desativada_em,'desativada_por',v_new.desativada_por));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_provision_user_profile_v1(p_user_id uuid, p_email text, p_nome text, p_roles app_role[], p_cliente_ids uuid[] DEFAULT ARRAY[]::uuid[], p_principal_cliente_id uuid DEFAULT NULL::uuid, p_partner_id uuid DEFAULT NULL::uuid, p_partner_papel text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_cargo text DEFAULT NULL::text, p_cpf_cnpj text DEFAULT NULL::text, p_crea text DEFAULT NULL::text, p_especialidade text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_profile_count integer;
  v_role_count integer;
  v_cliente_count integer;
  v_partner_role_count integer;
BEGIN
  PERFORM platform_private.require_service_role();
  IF p_user_id IS NULL OR p_email IS NULL OR p_nome IS NULL THEN
    RAISE EXCEPTION 'invalid_user_payload' USING ERRCODE = '22023';
  END IF;

  v_role_count := COALESCE(cardinality(p_roles), 0);
  IF v_role_count = 0 OR v_role_count > 13 THEN
    RAISE EXCEPTION 'invalid_roles' USING ERRCODE = '22023';
  END IF;

  IF 'superadmin'::public.app_role = ANY(p_roles) THEN
    RAISE EXCEPTION 'superadmin_role_reserved' USING ERRCODE = '42501';
  END IF;

  IF v_role_count <> (SELECT count(DISTINCT r) FROM unnest(p_roles) AS r) THEN
    RAISE EXCEPTION 'duplicate_roles' USING ERRCODE = '22023';
  END IF;

  p_cliente_ids := COALESCE(p_cliente_ids, ARRAY[]::uuid[]);
  v_cliente_count := cardinality(p_cliente_ids);
  IF v_cliente_count > 100
     OR v_cliente_count <> (SELECT count(DISTINCT c) FROM unnest(p_cliente_ids) AS c) THEN
    RAISE EXCEPTION 'invalid_customer_links' USING ERRCODE = '22023';
  END IF;

  IF 'cliente_produtor'::public.app_role = ANY(p_roles) AND v_cliente_count = 0 THEN
    RAISE EXCEPTION 'producer_requires_customer' USING ERRCODE = '23514';
  END IF;

  IF p_principal_cliente_id IS NOT NULL
     AND NOT (p_principal_cliente_id = ANY(p_cliente_ids)) THEN
    RAISE EXCEPTION 'invalid_primary_customer' USING ERRCODE = '23514';
  END IF;

  IF v_cliente_count > 0 AND (
    SELECT count(*) FROM public.clientes c WHERE c.id = ANY(p_cliente_ids)
  ) <> v_cliente_count THEN
    RAISE EXCEPTION 'customer_not_found' USING ERRCODE = '23503';
  END IF;

  SELECT count(*) INTO v_partner_role_count
  FROM unnest(p_roles) AS r
  WHERE r IN ('parceiro_b2b'::public.app_role, 'parceiro_b2b_tecnico'::public.app_role);

  IF v_partner_role_count > 1 AND NOT EXISTS(SELECT 1 FROM platform_private.b2b_provisioning_receipts r WHERE r.user_id=p_user_id AND r.status='claimed' AND r.external_roles=p_roles AND r.partner_id=p_partner_id) THEN RAISE EXCEPTION 'c2_receipt_required' USING ERRCODE='42501'; END IF;

  IF v_partner_role_count >= 1 THEN
    IF p_partner_id IS NULL OR p_partner_papel NOT IN ('gestor', 'tecnico') THEN
      RAISE EXCEPTION 'invalid_partner_link' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.partner_accounts pa WHERE pa.id = p_partner_id) THEN
      RAISE EXCEPTION 'partner_not_found' USING ERRCODE = '23503';
    END IF;
  ELSIF p_partner_id IS NOT NULL OR p_partner_papel IS NOT NULL THEN
    RAISE EXCEPTION 'unexpected_partner_link' USING ERRCODE = '23514';
  END IF;

  SELECT count(*) INTO v_profile_count
  FROM public.profiles p
  WHERE p.user_id = p_user_id;

  IF v_profile_count <> 1
     OR EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.user_clientes uc WHERE uc.user_id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.partner_users pu WHERE pu.user_id = p_user_id) THEN
    RAISE EXCEPTION 'user_not_ready_for_provisioning' USING ERRCODE = '23514';
  END IF;

  UPDATE public.profiles
     SET nome = p_nome,
         email = p_email,
         telefone = NULLIF(p_telefone, ''),
         cargo = NULLIF(p_cargo, ''),
         cpf_cnpj = NULLIF(p_cpf_cnpj, ''),
         crea = NULLIF(p_crea, ''),
         especialidade = NULLIF(p_especialidade, '')
   WHERE user_id = p_user_id;

  IF v_cliente_count > 0 THEN
    INSERT INTO public.user_clientes (user_id, cliente_id, principal)
    SELECT p_user_id, c,
           c = COALESCE(p_principal_cliente_id, p_cliente_ids[1])
    FROM unnest(p_cliente_ids) AS c;
  END IF;

  INSERT INTO public.user_roles (user_id, role)
  SELECT p_user_id, r FROM unnest(p_roles) AS r;

  IF v_partner_role_count >= 1 THEN
    INSERT INTO public.partner_users (user_id, partner_id, papel, tenant_id)
    VALUES (p_user_id, p_partner_id, p_partner_papel,(SELECT organization_id FROM public.profiles WHERE user_id=p_user_id));
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_h7j_fiscal_invoice_delete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text := coalesce(OLD.normalized_status, OLD.status, 'DRAFT');
BEGIN
  IF v_status <> 'DRAFT'
     OR OLD.status <> 'DRAFT'
     OR OLD.access_key IS NOT NULL
     OR OLD.invoice_number IS NOT NULL
     OR OLD.authorized_at IS NOT NULL
     OR OLD.canceled_at IS NOT NULL
     OR OLD.rejected_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'FISCAL_DOCUMENT_DELETE_FORBIDDEN: documento fiscal com trilha (status=%) nao pode ser excluido.', v_status;
  END IF;

  IF EXISTS (SELECT 1 FROM public.fiscal_events e WHERE e.fiscal_invoice_id = OLD.id) THEN
    RAISE EXCEPTION 'FISCAL_DOCUMENT_DELETE_FORBIDDEN: documento fiscal possui eventos registrados.';
  END IF;

  IF to_regclass('public.fiscal_sefaz_transmissions') IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.fiscal_sefaz_transmissions t WHERE t.fiscal_invoice_id = OLD.id) THEN
      RAISE EXCEPTION 'FISCAL_DOCUMENT_DELETE_FORBIDDEN: documento fiscal possui transmissoes SEFAZ.';
    END IF;
  END IF;

  IF to_regclass('public.fiscal_number_reservations') IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.fiscal_number_reservations r WHERE r.fiscal_invoice_id = OLD.id) THEN
      RAISE EXCEPTION 'FISCAL_DOCUMENT_DELETE_FORBIDDEN: documento fiscal possui numeracao reservada.';
    END IF;
  END IF;

  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_recalc_payable_installment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst public.accounts_payable_installments%ROWTYPE;
  v_total_pago numeric(14,2);
  v_total_desc numeric(14,2);
  v_total_juros numeric(14,2);
  v_total_multa numeric(14,2);
  v_status text;
  v_inst_id uuid := COALESCE(NEW.installment_id, OLD.installment_id);
  v_parent_id uuid;
  v_open int; v_partial int; v_paid int; v_canc int; v_total int;
BEGIN
  SELECT * INTO v_inst FROM public.accounts_payable_installments WHERE id = v_inst_id;
  IF NOT FOUND THEN RETURN COALESCE(NEW, OLD); END IF;

  SELECT COALESCE(SUM(amount_paid),0), COALESCE(SUM(discount_amount),0),
         COALESCE(SUM(interest_amount),0), COALESCE(SUM(penalty_amount),0)
    INTO v_total_pago, v_total_desc, v_total_juros, v_total_multa
    FROM public.payable_payments WHERE installment_id = v_inst_id;

  IF (v_total_pago + v_total_desc) >= (v_inst.original_amount + v_total_juros + v_total_multa) THEN v_status := 'PAID';
  ELSIF v_total_pago > 0 THEN v_status := 'PARTIAL';
  ELSE v_status := CASE WHEN v_inst.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date THEN 'OVERDUE' ELSE 'OPEN' END;
  END IF;

  UPDATE public.accounts_payable_installments
    SET paid_amount = v_total_pago, discount_amount = v_total_desc,
        interest_amount = v_total_juros, penalty_amount = v_total_multa,
        status = v_status,
        paid_at = CASE WHEN v_status='PAID' THEN now() ELSE NULL END
    WHERE id = v_inst_id;

  v_parent_id := v_inst.payable_id;
  SELECT count(*) FILTER (WHERE status='OPEN'),
         count(*) FILTER (WHERE status='PARTIAL'),
         count(*) FILTER (WHERE status='PAID'),
         count(*) FILTER (WHERE status='CANCELED'),
         count(*)
    INTO v_open, v_partial, v_paid, v_canc, v_total
    FROM public.accounts_payable_installments WHERE payable_id = v_parent_id;

  UPDATE public.accounts_payable SET status = CASE
    WHEN v_canc = v_total THEN 'CANCELED'
    WHEN (v_paid + v_canc) = v_total AND v_paid > 0 THEN 'PAID'
    WHEN v_paid > 0 OR v_partial > 0 THEN 'PARTIAL'
    WHEN EXISTS (SELECT 1 FROM public.accounts_payable_installments WHERE payable_id = v_parent_id AND status='OVERDUE') THEN 'OVERDUE'
    ELSE 'OPEN'
  END WHERE id = v_parent_id AND status <> 'CANCELED';

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.fn_recalc_receivable_installment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst public.accounts_receivable_installments%ROWTYPE;
  v_total_recebido numeric(14,2);
  v_total_desc numeric(14,2);
  v_total_juros numeric(14,2);
  v_total_multa numeric(14,2);
  v_status text;
  v_inst_id uuid := COALESCE(NEW.installment_id, OLD.installment_id);
  v_parent_id uuid;
  v_open int;
  v_partial int;
  v_paid int;
  v_canc int;
  v_total int;
BEGIN
  SELECT * INTO v_inst FROM public.accounts_receivable_installments WHERE id = v_inst_id;
  IF NOT FOUND THEN RETURN COALESCE(NEW, OLD); END IF;

  SELECT COALESCE(SUM(amount_received),0), COALESCE(SUM(discount_amount),0),
         COALESCE(SUM(interest_amount),0), COALESCE(SUM(penalty_amount),0)
    INTO v_total_recebido, v_total_desc, v_total_juros, v_total_multa
    FROM public.receivable_payments WHERE installment_id = v_inst_id;

  IF (v_total_recebido + v_total_desc) >= (v_inst.original_amount + v_total_juros + v_total_multa) THEN
    v_status := 'PAID';
  ELSIF v_total_recebido > 0 THEN
    v_status := 'PARTIAL';
  ELSE
    v_status := CASE WHEN v_inst.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date THEN 'OVERDUE' ELSE 'OPEN' END;
  END IF;

  UPDATE public.accounts_receivable_installments
    SET received_amount = v_total_recebido,
        discount_amount = v_total_desc,
        interest_amount = v_total_juros,
        penalty_amount = v_total_multa,
        status = v_status,
        paid_at = CASE WHEN v_status = 'PAID' THEN now() ELSE NULL END
    WHERE id = v_inst_id;

  -- Recalcular pai
  v_parent_id := v_inst.receivable_id;
  SELECT count(*) FILTER (WHERE status='OPEN'),
         count(*) FILTER (WHERE status='PARTIAL'),
         count(*) FILTER (WHERE status='PAID'),
         count(*) FILTER (WHERE status='CANCELED'),
         count(*)
    INTO v_open, v_partial, v_paid, v_canc, v_total
    FROM public.accounts_receivable_installments WHERE receivable_id = v_parent_id;

  UPDATE public.accounts_receivable SET status = CASE
    WHEN v_canc = v_total THEN 'CANCELED'
    WHEN (v_paid + v_canc) = v_total AND v_paid > 0 THEN 'PAID'
    WHEN v_paid > 0 OR v_partial > 0 THEN 'PARTIAL'
    WHEN EXISTS (SELECT 1 FROM public.accounts_receivable_installments WHERE receivable_id = v_parent_id AND status='OVERDUE') THEN 'OVERDUE'
    ELSE 'OPEN'
  END WHERE id = v_parent_id AND status <> 'CANCELED';

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.fn_cq_autoria_servidor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_profile uuid;
BEGIN
  -- Sem excecao por GUC: autoria e imutabilidade valem em todas as chamadas.
  IF TG_OP = 'INSERT' THEN
    IF v_uid IS NOT NULL THEN
      SELECT id INTO v_profile FROM public.profiles WHERE user_id = v_uid LIMIT 1;
      IF v_profile IS NOT NULL THEN
        IF NEW.responsavel_id IS NOT NULL AND NEW.responsavel_id IS DISTINCT FROM v_profile THEN
          RAISE EXCEPTION 'CQ_AUTORIA_FORJADA: responsavel_id informado (%) difere do perfil do usuario autenticado.', NEW.responsavel_id
            USING ERRCODE = 'check_violation';
        END IF;
        NEW.responsavel_id := v_profile;
      ELSIF NEW.responsavel_id IS NOT NULL THEN
        RAISE EXCEPTION 'CQ_AUTORIA_FORJADA: usuario autenticado sem perfil nao pode informar responsavel_id.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.responsavel_id IS DISTINCT FROM OLD.responsavel_id THEN
    RAISE EXCEPTION 'CQ_AUTORIA_IMUTAVEL: responsavel_id da analise % nao pode ser alterado.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.seq IS DISTINCT FROM OLD.seq
     OR NEW.lote_id IS DISTINCT FROM OLD.lote_id THEN
    RAISE EXCEPTION 'CQ_TRILHA_IMUTAVEL: created_at/seq/lote_id da analise % nao podem ser alterados.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notify_lab_on_programacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE org uuid; prod text; cli text; BEGIN
 IF NEW.status::text<>'aguardando' THEN RETURN NEW; END IF;
 org:=platform_private.notification_source_org('programacao_producao',NEW.id);
 IF org IS NULL THEN RETURN NEW; END IF;
 SELECT nome INTO prod FROM public.produtos WHERE id=NEW.produto_id;
 SELECT c.nome INTO cli FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=org WHERE o.id=NEW.ordem_servico_id;
 INSERT INTO public.notificacoes_operacionais(usuario_id,tipo,titulo,mensagem,link,source_type,source_id)
 SELECT DISTINCT ur.user_id,'nova_demanda_producao','Nova demanda de produção',coalesce(prod,'Bioinsumo')||coalesce(' · '||cli,'')||coalesce(' · '||round(NEW.volume_necessario/1000.0,1)::text||' L',''),'/pcp?coluna=aguardando','programacao_producao',NEW.id
 FROM public.user_roles ur WHERE ur.role IN ('producao','administrador','gestor') AND platform_private.notification_user_ok(ur.user_id,org);
