CREATE OR REPLACE FUNCTION public.fn_validate_envase_volume()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_produzido numeric;
  v_envasado numeric;
  v_novo numeric;
  v_codigo text;
  v_saldo numeric;
BEGIN
  IF NEW.quantidade IS NULL OR NEW.quantidade <= 0 THEN
    RAISE EXCEPTION 'A quantidade do envase deve ser maior que zero.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.volume_por_unidade IS NULL OR NEW.volume_por_unidade <= 0 THEN
    RAISE EXCEPTION 'O volume por unidade deve ser maior que zero.' USING ERRCODE = 'check_violation';
  END IF;

  -- H5-B01/B02: serializa qualquer INSERT de envase (inclusive direto via RLS) pela linha do lote.
  -- Ordem de lock compatível com rpc_cockpit_registrar_envase_v1 (programacao -> lote).
  SELECT volume_produzido, codigo_lote INTO v_produzido, v_codigo
  FROM public.lotes WHERE id = NEW.lote_id FOR UPDATE;

  IF v_codigo IS NULL AND v_produzido IS NULL THEN
    RAISE EXCEPTION 'Lote % inexistente para envase.', NEW.lote_id USING ERRCODE = 'check_violation';
  END IF;

  IF v_produzido IS NULL OR v_produzido <= 0 THEN
    RAISE EXCEPTION 'O lote % não possui volume produzido informado. Registre a produção antes de envasar.', COALESCE(v_codigo,'(desconhecido)')
      USING ERRCODE = 'check_violation';
  END IF;

  v_envasado := public.lote_volume_envasado(NEW.lote_id);
  v_novo := COALESCE(NEW.volume_por_unidade,0) * COALESCE(NEW.quantidade,0);
  v_saldo := v_produzido - v_envasado;

  IF (v_envasado + v_novo) > v_produzido THEN
    RAISE EXCEPTION 'Envase excede o volume produzido do lote %. Produzido: % L, já envasado: % L, saldo disponível: % L, solicitado: % L.',
      COALESCE(v_codigo,'(desconhecido)'),
      ROUND(v_produzido/1000.0, 2),
      ROUND(v_envasado/1000.0, 2),
      ROUND(v_saldo/1000.0, 2),
      ROUND(v_novo/1000.0, 2)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_estoque_movimentacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb := public.fn_estoque_ctx_read();
  v_acao text;
  v_dir text;
  v_usuario uuid;
  v_old_status text;
  v_new_status text;
  v_qtd numeric;
  v_mudou boolean;
  v_key text := v_ctx->>'idempotency_key';
  v_meta jsonb := COALESCE(v_ctx->'metadata', '{}'::jsonb);
  v_seq int;
BEGIN
  -- Uma operação do motor pode tocar mais de uma linha (reserva parcial).
  -- O lançamento principal fica com a chave da operação; os complementares
  -- recebem chave derivada determinística e são marcados como desdobramento.
  IF v_key IS NOT NULL THEN
    SELECT count(*) INTO v_seq
      FROM public.estoque_movimentacoes
     WHERE idempotency_key = v_key OR left(idempotency_key,length(v_key)+1) = v_key || '#';
    IF v_seq > 0 THEN
      v_meta := v_meta || jsonb_build_object('desdobramento', true, 'operacao_key', v_key);
      v_key := v_key || '#' || v_seq::text;
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.estoque_movimentacoes
      (estoque_produto_id, acao, quantidade, status_novo, lote_id, usuario_id,
       saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
       volume_anterior, volume_posterior, unidade, direcao,
       origem, referencia_tipo, referencia_id, motivo, idempotency_key, request_fingerprint,
       movimentacao_origem_id, os_id, os_tipo, cliente_id, metadata)
    VALUES (
      NEW.id,
      COALESCE(v_ctx->>'acao', 'entrada'),
      NULLIF(NEW.quantidade, 0), NEW.status::text, NEW.lote_id,
      COALESCE(auth.uid(), (v_ctx->>'usuario_id')::uuid),
      0, COALESCE(NEW.quantidade, 0),
      0, COALESCE(NEW.quantidade_reservada, 0),
      0, COALESCE(NEW.volume_total, 0),
      COALESCE(v_ctx->>'unidade', 'un'), 'entrada',
      COALESCE(v_ctx->>'origem', 'trigger'),
      v_ctx->>'referencia_tipo', (v_ctx->>'referencia_id')::uuid,
      v_ctx->>'motivo', v_key, v_ctx->>'request_fingerprint',
      (v_ctx->>'movimentacao_origem_id')::uuid,
      NEW.reservado_para_os_id, NEW.reservado_para_os_tipo, NEW.reservado_para_cliente_id,
      v_meta
    );
    RETURN NEW;
  END IF;

  v_mudou := (OLD.status IS DISTINCT FROM NEW.status)
          OR (COALESCE(OLD.quantidade,0) IS DISTINCT FROM COALESCE(NEW.quantidade,0))
          OR (COALESCE(OLD.quantidade_reservada,0) IS DISTINCT FROM COALESCE(NEW.quantidade_reservada,0))
          OR (COALESCE(OLD.volume_total,0) IS DISTINCT FROM COALESCE(NEW.volume_total,0));
  IF NOT v_mudou THEN RETURN NEW; END IF;

  v_old_status := OLD.status::text;
  v_new_status := NEW.status::text;

  v_acao := COALESCE(v_ctx->>'acao', CASE
    WHEN v_new_status = 'reservado'  AND v_old_status = 'expedido'  THEN 'estorno_expedicao'
    WHEN v_new_status = 'reservado'  AND v_old_status <> 'reservado' THEN 'reserva'
    WHEN v_new_status = 'expedido'   AND v_old_status <> 'expedido'  THEN 'expedicao'
    WHEN v_new_status = 'estornado'                                  THEN 'estorno_expedicao'
    WHEN v_old_status = 'reservado'  AND v_new_status = 'disponivel' THEN 'cancelamento_reserva'
    WHEN v_old_status = v_new_status THEN 'ajuste'
    ELSE 'edicao'
  END);

  v_dir := COALESCE(v_ctx->>'direcao', CASE
    WHEN COALESCE(NEW.quantidade,0) > COALESCE(OLD.quantidade,0) THEN 'entrada'
    WHEN COALESCE(NEW.quantidade,0) < COALESCE(OLD.quantidade,0) THEN 'saida'
    WHEN v_acao IN ('expedicao','descarte','perda','consumo','entrega') THEN 'saida'
    WHEN v_acao IN ('estorno_expedicao','devolucao') THEN 'entrada'
    ELSE 'neutro'
  END);

  v_usuario := COALESCE(auth.uid(), (v_ctx->>'usuario_id')::uuid,
    CASE WHEN v_new_status = 'expedido' THEN NEW.expedido_por ELSE NEW.reservado_por END);

  v_qtd := NULLIF(ABS(COALESCE(NEW.quantidade,0) - COALESCE(OLD.quantidade,0)), 0);
  IF v_qtd IS NULL THEN
    v_qtd := NULLIF(ABS(COALESCE(NEW.quantidade_reservada,0) - COALESCE(OLD.quantidade_reservada,0)), 0);
  END IF;
  IF v_qtd IS NULL THEN
    v_qtd := NULLIF(COALESCE(NEW.quantidade_reservada, NEW.quantidade, 0), 0);
  END IF;

  INSERT INTO public.estoque_movimentacoes
    (estoque_produto_id, acao, quantidade, status_anterior, status_novo,
     os_id, os_tipo, cliente_id, lote_id, usuario_id, observacao,
     saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
     volume_anterior, volume_posterior, unidade, direcao,
     origem, referencia_tipo, referencia_id, motivo,
     idempotency_key, request_fingerprint, movimentacao_origem_id, metadata)
  VALUES (
    NEW.id, v_acao, v_qtd, v_old_status, v_new_status,
    NEW.reservado_para_os_id, NEW.reservado_para_os_tipo, NEW.reservado_para_cliente_id,
    NEW.lote_id, v_usuario, COALESCE(v_ctx->>'observacao', NEW.observacao_reserva),
    COALESCE(OLD.quantidade,0), COALESCE(NEW.quantidade,0),
    COALESCE(OLD.quantidade_reservada,0), COALESCE(NEW.quantidade_reservada,0),
    COALESCE(OLD.volume_total,0), COALESCE(NEW.volume_total,0),
    COALESCE(v_ctx->>'unidade','un'), v_dir,
    COALESCE(v_ctx->>'origem','trigger'),
    v_ctx->>'referencia_tipo', (v_ctx->>'referencia_id')::uuid, v_ctx->>'motivo',
    v_key, v_ctx->>'request_fingerprint',
    (v_ctx->>'movimentacao_origem_id')::uuid,
    v_meta
  );

  IF v_acao = 'reserva' THEN
    INSERT INTO public.notificacoes_operacionais (usuario_id, tipo, titulo, mensagem, link)
    SELECT ur.user_id, 'nova_reserva', 'Nova reserva de estoque',
           'Item reservado aguardando expedição.', '/estoque'
      FROM public.user_roles ur JOIN public.profiles pr ON pr.user_id=ur.user_id AND pr.ativo IS TRUE JOIN public.lotes l ON l.id=NEW.lote_id AND l.organization_id=pr.organization_id JOIN public.organizations o ON o.id=pr.organization_id AND o.ativo IS TRUE WHERE ur.role = 'administrativo'::app_role AND l.organization_id IS NOT NULL;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_consultor_atribuido_op()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cliente_nome text;
BEGIN
  IF NEW.consultor_atribuido IS NULL THEN
    RETURN NEW;
  END IF;

  IF (TG_OP = 'INSERT')
     OR (TG_OP = 'UPDATE' AND COALESCE(OLD.consultor_atribuido::text,'') IS DISTINCT FROM NEW.consultor_atribuido::text) THEN

    SELECT nome INTO v_cliente_nome FROM public.clientes WHERE id = NEW.cliente_id;

    INSERT INTO public.notificacoes_operacionais (usuario_id, tipo, titulo, mensagem, link)
    VALUES (
      NEW.consultor_atribuido,
      CASE WHEN NEW.urgencia = 'critica' THEN 'urgencia_critica' ELSE 'nova_solicitacao' END,
      CASE WHEN NEW.urgencia = 'critica' THEN 'Solicitação CRÍTICA atribuída' ELSE 'Nova solicitação atribuída' END,
      'Cliente ' || COALESCE(v_cliente_nome,'') || ' — ' || COALESCE(NEW.tipo_demanda,''),
      '/solicitacoes?id=' || NEW.id::text
    );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_dossier_new_version(p_microorganism_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid; v_next int;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF nullif(btrim(coalesce(p_reason,'')),'') IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_JUSTIFICATION_REQUIRED' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('regulatory_dossier:'||p_microorganism_id::text, 0));

  IF EXISTS (SELECT 1 FROM public.microorganism_regulatory_dossiers
              WHERE microorganism_id = p_microorganism_id
                AND status IN ('DRAFT','PENDING_REVIEW') AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'REGULATORY_OPEN_VERSION_EXISTS' USING ERRCODE='55006';
  END IF;

  SELECT coalesce(max(version),0)+1 INTO v_next
    FROM public.microorganism_regulatory_dossiers WHERE microorganism_id = p_microorganism_id;

  INSERT INTO public.microorganism_regulatory_dossiers
    (microorganism_id, version, status, created_by, updated_by, blocked_reason)
  VALUES (p_microorganism_id, v_next, 'DRAFT', auth.uid(), auth.uid(), NULL)
  RETURNING id INTO v_id;

  INSERT INTO public.microorganism_regulatory_checklist (dossier_id, item_key, state)
  SELECT v_id, k, 'PENDING' FROM unnest(ARRAY[
    'FINALIDADE_REGULATORIA','CEPA','FORMULACAO','GARANTIA_ROTULO','REGISTRO_MAPA',
    'TITULAR_FABRICANTE','NCM_CEST_TIPI','GTIN','UNIDADE_CONVERSAO','ORIGEM',
    'CFOP','TRIBUTACAO']) k;

  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_ncm_candidate_add(p_dossier_id uuid, p_ncm text, p_justification text, p_cest text DEFAULT NULL::text, p_confidence text DEFAULT 'LOW'::text, p_source_key text DEFAULT NULL::text, p_source_url text DEFAULT NULL::text, p_consulted_at date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid; v_status text; v_source uuid; v_conf text;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  SELECT status INTO v_status FROM public.microorganism_regulatory_dossiers
   WHERE id = p_dossier_id AND deleted_at IS NULL;
  IF v_status IS NULL THEN RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_FOUND' USING ERRCODE = '22023'; END IF;
  IF v_status NOT IN ('DRAFT', 'PENDING_REVIEW') THEN
    RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_EDITABLE' USING ERRCODE = '55006';
  END IF;

  IF length(btrim(coalesce(p_justification, ''))) < 20 THEN
    RAISE EXCEPTION 'REGULATORY_JUSTIFICATION_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF p_consulted_at IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_NCM_CONSULTED_AT_REQUIRED' USING ERRCODE = '22023';
  END IF;

  v_conf := public.fn_regulatory_confidence_normalize(p_confidence);
  IF v_conf IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_NCM_CONFIDENCE_INVALID'
      USING ERRCODE = '22023',
            HINT = 'Confianca deve ser LOW, MEDIUM, HIGH ou CONDITIONAL.';
  END IF;

  SELECT id INTO v_source FROM public.fiscal_official_sources
   WHERE source_key = p_source_key AND is_active;

  IF v_source IS NULL AND NOT public.fn_fiscal_official_url_allowlisted(p_source_url) THEN
    RAISE EXCEPTION 'REGULATORY_NCM_SOURCE_REQUIRED'
      USING ERRCODE = '22023',
            HINT = 'Informe fonte oficial cadastrada e ativa (source_key) ou URL oficial allowlisted (.gov.br).';
  END IF;

  INSERT INTO public.microorganism_ncm_candidates
    (dossier_id, ncm, cest, justification, confidence, source_id, source_url, consulted_at, created_by)
  VALUES (p_dossier_id, p_ncm, p_cest, p_justification, v_conf,
          v_source, p_source_url, p_consulted_at, auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_registrar_clima_manual_v1(p_fazenda_id uuid, p_data_hora timestamp with time zone DEFAULT now(), p_temperatura numeric DEFAULT NULL::numeric, p_umidade numeric DEFAULT NULL::numeric, p_chuva_mm numeric DEFAULT 0, p_vento_kmh numeric DEFAULT NULL::numeric, p_radiacao_solar numeric DEFAULT NULL::numeric)
 RETURNS clima_dados
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result public.clima_dados;
begin
  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;
  if not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN'; end if;
  if p_fazenda_id is null or p_data_hora is null then raise exception 'INVALID_INPUT'; end if;
  if not exists (select 1 from public.fazendas f where f.id = p_fazenda_id) then
    raise exception 'FARM_NOT_FOUND';
  end if;
  if p_temperatura is not null and not (p_temperatura between -80 and 65) then raise exception 'INVALID_TEMPERATURE'; end if;
  if p_umidade is not null and not (p_umidade between 0 and 100) then raise exception 'INVALID_HUMIDITY'; end if;
  if p_chuva_mm is not null and p_chuva_mm < 0 then raise exception 'INVALID_RAIN'; end if;
  if p_vento_kmh is not null and p_vento_kmh < 0 then raise exception 'INVALID_WIND'; end if;
  if p_radiacao_solar is not null and p_radiacao_solar < 0 then raise exception 'INVALID_RADIATION'; end if;

  insert into public.clima_dados (
    fazenda_id, data_hora, temperatura, umidade, chuva_mm, vento_kmh,
    radiacao_solar, tipo_dado, fonte, coletado_em
  ) values (
    p_fazenda_id, p_data_hora, p_temperatura, p_umidade, coalesce(p_chuva_mm, 0),
    p_vento_kmh, p_radiacao_solar, 'manual', 'manual', now()
  ) returning * into v_result;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_solicitacao_atribuida()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tipo TEXT;
  v_cliente_nome TEXT;
BEGIN
  -- Only notify on transition to 'atribuida' or when consultor_atribuido changes
  IF (TG_OP = 'UPDATE' AND OLD.consultor_atribuido IS DISTINCT FROM NEW.consultor_atribuido AND NEW.consultor_atribuido IS NOT NULL)
     OR (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'checkin_realizado') THEN

    SELECT nome INTO v_cliente_nome FROM public.clientes WHERE id = NEW.cliente_id;

    -- Notify the client portal
    IF NEW.status = 'checkin_realizado' THEN
      INSERT INTO public.portal_notificacoes (cliente_id, titulo, mensagem, tipo)
      VALUES (
        NEW.cliente_id,
        'Consultor chegou na sua área',
        COALESCE('Atendimento de "' || NEW.tipo_demanda || '" — check-in realizado.', 'Check-in realizado.'),
        'informativo'
      );
    ELSIF NEW.status = 'atribuida' OR (OLD.consultor_atribuido IS NULL AND NEW.consultor_atribuido IS NOT NULL) THEN
      INSERT INTO public.portal_notificacoes (cliente_id, titulo, mensagem, tipo)
      VALUES (
        NEW.cliente_id,
        'Sua solicitação foi atribuída',
        'Um consultor técnico foi designado para a sua solicitação "' || NEW.tipo_demanda || '".',
        'informativo'
      );
    END IF;
  END IF;

  -- Notify on creation
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.portal_notificacoes (cliente_id, titulo, mensagem, tipo)
    VALUES (
      NEW.cliente_id,
      'Solicitação recebida',
      'Sua solicitação "' || NEW.tipo_demanda || '" foi registrada e está em triagem.',
      'informativo'
    );
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.partner_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_partner_id uuid;
  v_acao text;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_acao := 'create';
    v_new := to_jsonb(NEW);
    v_partner_id := CASE
      WHEN TG_TABLE_NAME = 'partner_accounts' THEN (v_new->>'id')::uuid
      ELSE (v_new->>'partner_id')::uuid
    END;
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    v_partner_id := CASE
      WHEN TG_TABLE_NAME = 'partner_accounts' THEN (v_new->>'id')::uuid
      ELSE (v_new->>'partner_id')::uuid
    END;
    IF TG_TABLE_NAME = 'partner_accounts' AND (v_old->>'ativo')::boolean = true AND (v_new->>'ativo')::boolean = false THEN
      v_acao := 'delete';
    ELSIF TG_TABLE_NAME = 'partner_accounts' AND (v_old->>'ativo')::boolean = false AND (v_new->>'ativo')::boolean = true THEN
      v_acao := 'restore';
    ELSIF TG_TABLE_NAME = 'partner_product_prices' THEN
      v_acao := 'price_change';
    ELSE
      v_acao := 'update';
    END IF;
  ELSE
    RETURN NULL;
  END IF;

  INSERT INTO public.partner_audit_logs(partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_partner_id, auth.uid(), v_acao, v_old, v_new);

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.partner_orders_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_acao text;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_acao := 'order_created';
    v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      v_acao := CASE WHEN NEW.status = 'cancelado' THEN 'order_cancelled' ELSE 'status_changed' END;
    ELSE
      v_acao := 'order_updated';
    END IF;
  ELSE
    RETURN NULL;
  END IF;
  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (COALESCE(NEW.id, OLD.id), COALESCE(NEW.partner_id, OLD.partner_id), auth.uid(), v_acao, v_old, v_new);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.b2b_read_simulations(p_partner_id uuid DEFAULT NULL::uuid, p_simulation_id uuid DEFAULT NULL::uuid, p_items boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); tech boolean; result jsonb;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 tech:=public.has_role(u,'parceiro_b2b_tecnico');
 IF p_items THEN
  IF p_simulation_id IS NULL OR NOT platform_private.b2b_phase1_simulation_visible(p_simulation_id) THEN RAISE EXCEPTION 'scope_denied' USING ERRCODE='42501'; END IF;
  SELECT coalesce(jsonb_agg(CASE WHEN tech THEN to_jsonb(i)-ARRAY['valor_unitario_cheio','subtotal','preco_tabela_snapshot','preco_unitario','desconto_percentual'] ELSE to_jsonb(i) END ORDER BY i.created_at),'[]'::jsonb) INTO result FROM public.partner_simulation_items i WHERE i.simulation_id=p_simulation_id;
 ELSE
  SELECT coalesce(jsonb_agg((CASE WHEN tech THEN to_jsonb(s)-ARRAY['total_cheio'] ELSE to_jsonb(s) END)||jsonb_build_object('items_count',(SELECT count(*) FROM public.partner_simulation_items i WHERE i.simulation_id=s.id)) ORDER BY s.created_at DESC),'[]'::jsonb) INTO result
  FROM public.partner_simulations s WHERE (p_partner_id IS NULL OR s.partner_id=p_partner_id) AND (p_simulation_id IS NULL OR s.id=p_simulation_id)
   AND platform_private.b2b_phase1_simulation_visible(s.id)
   AND (tech OR public.is_platform_superadmin(u) OR public.has_role(u,'administrador') OR public.has_role(u,'gestor_comercial') OR public.has_role(u,'parceiro_b2b'));
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION platform_private.manual_cq_v1(p_os_id uuid, p_programacao_id uuid, p_cq jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 uid uuid:=auth.uid(); org uuid; os public.ordens_servico%ROWTYPE; pp public.programacao_producao%ROWTYPE;
 lot public.lotes%ROWTYPE; cq public.controle_qualidade%ROWTYPE; ref public.cq_parametros_referencia%ROWTYPE;
 key text; phase text; outcome text; v_ph numeric; concentration numeric; refid uuid;
 payload jsonb; receipt public.cockpit_operacao_idempotencia%ROWTYPE; receipt_key text; digest text;
 result jsonb; cqid uuid; profileid uuid;
BEGIN
 PERFORM pg_catalog.set_config('lock_timeout','3s',true);
 org:=platform_private.h15_actor_organization();
 IF uid IS NULL OR org IS NULL OR public.technical_actor_ready(uid) IS NOT TRUE
 OR public._saas_user_has_feature(uid,'ordens_producao') IS NOT TRUE
 OR public._saas_user_has_feature(uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(uid,'administrador') OR public.has_role(uid,'gestor') OR public.has_role(uid,'producao')) IS NOT TRUE
 THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF p_os_id IS NULL OR p_programacao_id IS NULL OR current_setting('transaction_isolation')<>'read committed' THEN
 RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 phase:=CASE WHEN p_cq IS NULL THEN 'enviar_cq' ELSE 'registrar_cq' END;
 IF p_cq IS NOT NULL THEN
  IF jsonb_typeof(p_cq) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'CQ_PAYLOAD_INVALID'; END IF;
  FOR key IN SELECT jsonb_object_keys(p_cq) LOOP
   IF key NOT IN ('lote_id','resultado','ph','concentracao','aparencia','odor','contaminacao','referencia_id','dados_sinteticos') THEN RAISE EXCEPTION 'CQ_PAYLOAD_INVALID'; END IF;
  END LOOP;
  IF p_cq->'dados_sinteticos' IS DISTINCT FROM 'true'::jsonb OR p_cq->>'resultado' NOT IN ('aprovado','reprovado')
   OR jsonb_typeof(p_cq->'ph') IS DISTINCT FROM 'number' OR jsonb_typeof(p_cq->'concentracao') IS DISTINCT FROM 'number'
   OR jsonb_typeof(p_cq->'lote_id') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'CQ_PAYLOAD_INVALID'; END IF;
  outcome:=p_cq->>'resultado'; v_ph:=(p_cq->>'ph')::numeric; concentration:=(p_cq->>'concentracao')::numeric;
  IF outcome IS NULL OR v_ph::text IN ('NaN','Infinity','-Infinity') OR v_ph<0 OR v_ph>14
   OR concentration::text IN ('NaN','Infinity','-Infinity') OR concentration<0 OR concentration>1e30 THEN RAISE EXCEPTION 'CQ_VALUES_INVALID'; END IF;
  FOREACH key IN ARRAY ARRAY['aparencia','odor','contaminacao'] LOOP
   IF jsonb_typeof(p_cq->key) IS DISTINCT FROM 'string' OR length(btrim(p_cq->>key)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'CQ_PAYLOAD_INVALID'; END IF;
  END LOOP;
  IF p_cq ? 'referencia_id' AND jsonb_typeof(p_cq->'referencia_id') NOT IN ('null','string') THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END IF;
  BEGIN refid:=nullif(p_cq->>'referencia_id','')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END;
  payload:=p_cq||jsonb_build_object('aparencia',btrim(p_cq->>'aparencia'),'odor',btrim(p_cq->>'odor'),'contaminacao',btrim(p_cq->>'contaminacao'),'referencia_id',refid);
 ELSE payload:='{}'::jsonb; END IF;
 -- Same lock order / phantom fences as reviewed lot generation. No legacy assert-only delegation.
 LOCK TABLE public.platform_org_admin_invites,public.ordens_servico_onfarm IN SHARE MODE;
 LOCK TABLE public.saas_plan_versions,public.saas_plan_version_features,public.saas_features,public.saas_modules IN SHARE MODE;
 PERFORM pg_advisory_xact_lock(hashtext('cockpit_lote:'||p_programacao_id::text));
 SELECT * INTO os FROM public.ordens_servico WHERE id=p_os_id FOR UPDATE;
 IF os.id IS NULL OR os.organization_id IS DISTINCT FROM org THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=uid ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=uid ORDER BY role::text FOR SHARE;
 PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
 PERFORM 1 FROM public.organization_subscriptions WHERE organization_id=org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.organization_feature_overrides WHERE organization_id=org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.clientes WHERE id=os.cliente_id FOR SHARE;
 PERFORM 1 FROM public.fazendas WHERE id=os.fazenda_id FOR SHARE;
 PERFORM 1 FROM public.talhoes WHERE id=os.talhao_id FOR SHARE;
 PERFORM 1 FROM public.produtos WHERE id=os.produto_id FOR SHARE;
 PERFORM 1 FROM public.microrganismos WHERE id=os.microrganismo_id FOR SHARE;
 PERFORM 1 FROM public.programacao_producao WHERE id=p_programacao_id OR ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.lotes WHERE programacao_id=p_programacao_id ORDER BY id FOR UPDATE;
 IF public.technical_actor_ready(uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM org
 OR public._saas_user_has_feature(uid,'ordens_producao') IS NOT TRUE OR public._saas_user_has_feature(uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(uid,'administrador') OR public.has_role(uid,'gestor') OR public.has_role(uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=os.cliente_id AND c.organization_id=org)
 OR EXISTS(SELECT 1 FROM public.ordens_servico_onfarm WHERE id=p_os_id)
 OR (os.fazenda_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fazendas f WHERE f.id=os.fazenda_id AND f.organization_id=org AND f.cliente_id=os.cliente_id AND f.ativo))
 OR (os.talhao_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.talhoes t WHERE t.id=os.talhao_id AND t.organization_id=org AND t.fazenda_id=os.fazenda_id AND t.ativo))
 THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF os.origem='b2b' OR os.partner_order_id IS NOT NULL OR os.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id)
 OR EXISTS(SELECT 1 FROM public.entregas WHERE ordem_servico_id=p_os_id)
 OR EXISTS(SELECT 1 FROM public.aplicacoes WHERE ordem_servico_id=p_os_id)
 OR (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id)<>1
 OR (SELECT count(*) FROM public.lotes WHERE programacao_id=p_programacao_id)<>1
 THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO pp FROM public.programacao_producao WHERE id=p_programacao_id;
 SELECT * INTO lot FROM public.lotes WHERE programacao_id=p_programacao_id;
 IF pp.id IS NULL OR pp.organization_id IS DISTINCT FROM org OR pp.ordem_servico_id IS DISTINCT FROM p_os_id OR pp.ordem_servico_onfarm_id IS NOT NULL
 OR lot.organization_id IS DISTINCT FROM org OR lot.produto_id IS DISTINCT FROM pp.produto_id OR lot.microrganismo_id IS DISTINCT FROM pp.microrganismo_id
 OR pp.produto_id IS DISTINCT FROM os.produto_id OR pp.microrganismo_id IS DISTINCT FROM os.microrganismo_id
 OR pp.data_programada IS NULL OR pp.volume_necessario IS DISTINCT FROM os.volume_total_ml
 OR lot.volume_produzido IS NULL OR lot.volume_produzido<=0 OR lot.volume_produzido::text IN ('NaN','Infinity','-Infinity')
 OR pp.responsavel_id IS NOT NULL OR nullif(btrim(pp.responsavel),'') IS NOT NULL
 OR platform_private.lab_item_is_manufacturable(pp.produto_id,pp.microrganismo_id) IS NOT TRUE
 OR EXISTS(SELECT 1 FROM public.envase WHERE lote_id=lot.id) OR EXISTS(SELECT 1 FROM public.estoque_produto WHERE lote_id=lot.id)
 OR NOT EXISTS(SELECT 1 FROM public.laboratorio_esteira_eventos e WHERE e.lote_id=lot.id AND e.os_id=os.id AND e.programacao_id=pp.id AND e.origem_os='manual' AND e.acao='gerar_lote')
 THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF p_cq IS NOT NULL AND (p_cq->>'lote_id') IS DISTINCT FROM lot.id::text THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('cq_lote:'||lot.id::text));
 PERFORM 1 FROM public.controle_qualidade WHERE lote_id=lot.id ORDER BY seq FOR UPDATE;
 -- Resolve the canonical item, never infer/create a product->microorganism link.
 IF p_cq IS NOT NULL THEN
  LOCK TABLE public.cq_parametros_referencia IN SHARE MODE;
  IF (SELECT count(*) FROM public.cq_parametros_referencia r WHERE r.ativo IS TRUE AND
   ((pp.produto_id IS NOT NULL AND r.produto_id=pp.produto_id) OR
    (pp.produto_id IS NULL AND pp.microrganismo_id IS NOT NULL AND r.produto_id IS NULL AND r.microrganismo_id=pp.microrganismo_id)))>1
   THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END IF;
  SELECT r.* INTO ref FROM public.cq_parametros_referencia r WHERE r.ativo IS TRUE AND
   ((pp.produto_id IS NOT NULL AND r.produto_id=pp.produto_id) OR
    (pp.produto_id IS NULL AND pp.microrganismo_id IS NOT NULL AND r.produto_id IS NULL AND r.microrganismo_id=pp.microrganismo_id));
 END IF;
 IF p_cq IS NOT NULL AND refid IS DISTINCT FROM ref.id THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END IF;
 IF p_cq IS NOT NULL AND outcome='aprovado' AND ref.id IS NULL THEN RAISE EXCEPTION 'CQ_REFERENCE_REQUIRED'; END IF;
 IF ref.id IS NOT NULL AND (ref.ph_min IS NULL OR ref.ph_max IS NULL OR ref.concentracao_min_ufc_ml IS NULL
 OR ref.ph_min::text IN ('NaN','Infinity','-Infinity') OR ref.ph_max::text IN ('NaN','Infinity','-Infinity') OR ref.concentracao_min_ufc_ml::text IN ('NaN','Infinity','-Infinity')
 OR ref.ph_min<0 OR ref.ph_max>14 OR ref.ph_min>ref.ph_max OR ref.concentracao_min_ufc_ml<0
 OR nullif(btrim(ref.aparencia_esperada),'') IS NULL OR nullif(btrim(ref.odor_esperado),'') IS NULL OR nullif(btrim(ref.contaminacao_esperada),'') IS NULL)
 THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END IF;
 IF p_cq IS NOT NULL AND outcome='aprovado' AND ref.id IS NOT NULL AND
 ((ref.ph_min IS NOT NULL AND v_ph<ref.ph_min) OR (ref.ph_max IS NOT NULL AND v_ph>ref.ph_max)
 OR (ref.concentracao_min_ufc_ml IS NOT NULL AND concentration<ref.concentracao_min_ufc_ml)
 OR (nullif(btrim(ref.aparencia_esperada),'') IS NOT NULL AND btrim(p_cq->>'aparencia')<>btrim(ref.aparencia_esperada))
 OR (nullif(btrim(ref.odor_esperado),'') IS NOT NULL AND btrim(p_cq->>'odor')<>btrim(ref.odor_esperado))
 OR (nullif(btrim(ref.contaminacao_esperada),'') IS NOT NULL AND btrim(p_cq->>'contaminacao')<>btrim(ref.contaminacao_esperada))) THEN RAISE EXCEPTION 'CQ_REFERENCE_FAILED'; END IF;
 receipt_key:='manual_cq_v1:'||phase||':'||lot.id::text;
 payload:=payload||jsonb_build_object('os_id',os.id,'programacao_id',pp.id,'lote_id',lot.id,'referencia_snapshot',CASE WHEN p_cq IS NULL OR ref.id IS NULL THEN NULL ELSE to_jsonb(ref) END);
 digest:=md5(payload::text);
 SELECT * INTO receipt FROM public.cockpit_operacao_idempotencia WHERE idempotency_key=receipt_key FOR UPDATE;
 IF receipt.idempotency_key IS NOT NULL THEN
  IF receipt.usuario_id IS DISTINCT FROM uid OR receipt.payload_hash IS DISTINCT FROM digest OR receipt.alvo_id IS DISTINCT FROM lot.id OR receipt.status<>'completed'
   OR os.status::text<>'em_cq' OR lot.status::text NOT IN ('aguardando_cq','aprovado','reprovado')
   OR (p_cq IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.controle_qualidade c WHERE c.id=(receipt.resultado->>'cq_id')::uuid AND c.lote_id=lot.id AND c.organization_id=org AND c.resultado::text=outcome AND c.ph=v_ph AND c.concentracao=concentration AND c.aparencia=payload->>'aparencia' AND c.odor=payload->>'odor' AND c.contaminacao=payload->>'contaminacao'))
  THEN RAISE EXCEPTION 'CQ_REPLAY_DIVERGENT'; END IF;
  RETURN receipt.resultado||jsonb_build_object('replay',true);
 END IF;
 SELECT id INTO profileid FROM public.profiles WHERE user_id=uid AND ativo AND organization_id=org;
 IF p_cq IS NULL THEN
  IF os.status::text<>'programada' OR pp.status::text<>'aguardando' OR lot.status::text<>'em_producao'
   OR EXISTS(SELECT 1 FROM public.controle_qualidade WHERE lote_id=lot.id) THEN RAISE EXCEPTION 'CQ_STATE_INVALID'; END IF;
  INSERT INTO platform_private.authz_tickets(txid,scope,target) VALUES(txid_current(),'manual_cq_send_v1',lot.id),(txid_current(),'manual_cq_send_v1',os.id),(txid_current(),'manual_cq_send_v1',pp.id);
  -- Ticket-specific transition reflects a pre-existing lot; never simulates production intermediate steps.
  UPDATE public.ordens_servico SET status='em_cq' WHERE id=os.id;
 ELSE
  IF os.status::text<>'em_cq' OR pp.status::text<>'aguardando_cq' OR lot.status::text<>'aguardando_cq'
   OR EXISTS(SELECT 1 FROM public.controle_qualidade WHERE lote_id=lot.id)
   OR NOT EXISTS(SELECT 1 FROM public.cockpit_operacao_idempotencia WHERE idempotency_key='manual_cq_v1:enviar_cq:'||lot.id::text AND status='completed') THEN RAISE EXCEPTION 'CQ_STATE_INVALID'; END IF;
  cqid:=gen_random_uuid();
  INSERT INTO platform_private.authz_tickets(txid,scope,target) VALUES(txid_current(),'manual_cq_'||outcome||'_v1',lot.id),(txid_current(),'manual_cq_'||outcome||'_v1',pp.id),(txid_current(),'manual_cq_insert_v1',cqid);
  INSERT INTO public.controle_qualidade(id,lote_id,ph,concentracao,aparencia,odor,contaminacao,responsavel,responsavel_id,resultado,organization_id)
  VALUES(cqid,lot.id,v_ph,concentration,payload->>'aparencia',payload->>'odor',payload->>'contaminacao','DADOS FICTICIOS SEM VALOR COMERCIAL',profileid,outcome::public.resultado_cq,org);
  UPDATE public.lotes SET status=outcome::public.status_lote WHERE id=lot.id;
  IF outcome='aprovado' THEN UPDATE public.programacao_producao SET status='aprovado' WHERE id=pp.id; END IF;
 END IF;
 IF (SELECT status::text FROM public.ordens_servico WHERE id=os.id)<>'em_cq'
 OR (SELECT status::text FROM public.lotes WHERE id=lot.id)<>(CASE WHEN p_cq IS NULL THEN 'aguardando_cq' ELSE outcome END)
 OR (SELECT status::text FROM public.programacao_producao WHERE id=pp.id)<>(CASE WHEN outcome='aprovado' THEN 'aprovado' ELSE 'aguardando_cq' END)
 OR public.technical_actor_ready(uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM org THEN RAISE EXCEPTION 'CQ_POSTCONDITION_FAILED'; END IF;
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,lote_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 VALUES(os.id,'manual',pp.id,lot.id,os.status::text,CASE WHEN p_cq IS NULL THEN 'aguardando_cq' ELSE outcome END,phase,uid,'DADOS FICTICIOS SEM VALOR COMERCIAL; sem producao fisica/venda/uso agricola. '||payload::text);
 result:=jsonb_build_object('success',true,'replay',false,'lote_id',lot.id,'cq_id',cqid,'status','em_cq','resultado',outcome);
 INSERT INTO public.cockpit_operacao_idempotencia(idempotency_key,operacao,usuario_id,resultado,payload_hash,alvo_id,status)
 VALUES(receipt_key,phase,uid,result,digest,lot.id,'completed');
 DELETE FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope IN ('manual_cq_send_v1','manual_cq_aprovado_v1','manual_cq_reprovado_v1','manual_cq_insert_v1');
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.regulatory_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_actor uuid; v_id uuid;
BEGIN
  BEGIN v_actor := auth.uid(); EXCEPTION WHEN OTHERS THEN v_actor := NULL; END;
  IF TG_OP = 'DELETE' THEN
    v_id := OLD.id;
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values)
    VALUES (TG_TABLE_NAME, v_id, 'DELETE', v_actor, public.mask_sensitive_jsonb(to_jsonb(OLD)));
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', v_actor,
            public.mask_sensitive_jsonb(to_jsonb(OLD)), public.mask_sensitive_jsonb(to_jsonb(NEW)));
    RETURN NEW;
  ELSE
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', v_actor, public.mask_sensitive_jsonb(to_jsonb(NEW)));
    RETURN NEW;
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.tg_block_production_link_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_os_status text;
BEGIN
  SELECT status::text INTO v_os_status FROM public.ordens_servico WHERE id = OLD.ordem_servico_id;
  IF v_os_status IS NOT NULL AND v_os_status <> 'aberta' THEN
    RAISE EXCEPTION 'Vínculo de produção não pode ser excluído após início/finalização da produção.';
  END IF;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_sod_override(p_dossier_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_row public.microorganism_regulatory_dossiers;
BEGIN
  IF NOT public.has_role(auth.uid(), 'administrador'::app_role) THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 40 THEN
    RAISE EXCEPTION 'REGULATORY_OVERRIDE_JUSTIFICATION_WEAK' USING ERRCODE = '22023';
  END IF;

  UPDATE public.microorganism_regulatory_dossiers
     SET sod_override_active = true,
         sod_override_by = auth.uid(),
         sod_override_at = now(),
         sod_override_reason = p_reason,
         updated_by = auth.uid()
   WHERE id = p_dossier_id AND deleted_at IS NULL AND status IN ('DRAFT', 'PENDING_REVIEW')
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_FOUND' USING ERRCODE = '22023';
  END IF;
  RETURN jsonb_build_object('dossier_id', v_row.id, 'sod_override_active', true);
END $function$

CREATE OR REPLACE FUNCTION public.set_codigo_produto()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prefixo TEXT;
BEGIN
  IF NEW.codigo IS NULL OR btrim(NEW.codigo) = '' THEN
    v_prefixo := public.prefixo_para_produto(NEW.tipo::text);
    IF v_prefixo IS NULL THEN
      RAISE EXCEPTION 'Tipo de produto sem prefixo definido: %', NEW.tipo;
    END IF;
    NEW.codigo := public.proximo_codigo(v_prefixo, 'produtos');
  ELSE
    NEW.codigo := btrim(NEW.codigo);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_codigo_visita()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ano int;
BEGIN
  IF NEW.codigo_visita IS NULL OR NEW.codigo_visita = '' THEN
    v_ano := EXTRACT(YEAR FROM COALESCE(NEW.data_vistoria, NEW.created_at, now()))::int;
    NEW.codigo_visita := public.gerar_codigo_visita(v_ano);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_comprovante_exigir_arquivo_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF NEW.arquivo_path IS NULL THEN
    IF NEW.assinatura_tipo = 'fisica_anexada' THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'O comprovante físico exige um arquivo anexado.';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM storage.objects AS o
    WHERE o.bucket_id = 'entrega-documentos'
      AND o.name = NEW.arquivo_path
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'Arquivo do comprovante não encontrado ou sem acesso no armazenamento.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalc_risk_on_ar_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_partner uuid;
BEGIN
  SELECT ar.partner_id INTO v_partner
  FROM public.accounts_receivable ar
  WHERE ar.id = COALESCE(NEW.receivable_id, OLD.receivable_id)
    AND ar.origin_type = 'B2B_ORDER';
  IF v_partner IS NOT NULL THEN
    PERFORM public.recalc_partner_risk_score(v_partner);
  END IF;
  RETURN NEW;
END;
$function$

