CREATE OR REPLACE FUNCTION public.sync_os_onfarm_downstream()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prog_id uuid;
  v_lote_id uuid;
BEGIN
  IF (OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_prog_id FROM public.programacao_producao
   WHERE ordem_servico_onfarm_id = NEW.id ORDER BY created_at DESC LIMIT 1;

  IF v_prog_id IS NULL
     AND NEW.status::text IN ('aprovada','programada','em_producao','em_cq','envase','pronto_entrega','entregue','finalizada')
     AND NEW.produto_id IS NOT NULL THEN
    INSERT INTO public.programacao_producao
      (produto_id, volume_necessario, data_programada, status, ordem_servico_onfarm_id)
    VALUES
      (NEW.produto_id, NEW.volume_total_ml,
       COALESCE(NEW.data_recomendada, CURRENT_DATE), 'aguardando', NEW.id)
    RETURNING id INTO v_prog_id;
  END IF;

  IF v_prog_id IS NOT NULL THEN
    SELECT id INTO v_lote_id FROM public.lotes
      WHERE programacao_id = v_prog_id ORDER BY created_at DESC LIMIT 1;
  END IF;

  CASE NEW.status::text
    WHEN 'aprovada' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aguardando' WHERE id = v_prog_id;
      END IF;
    WHEN 'programada' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao
          SET status = 'aguardando',
              data_programada = COALESCE(NEW.data_recomendada, data_programada, CURRENT_DATE)
          WHERE id = v_prog_id;
      END IF;
    WHEN 'em_producao' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'em_producao' WHERE id = v_prog_id;
      END IF;
      IF v_lote_id IS NULL AND NEW.produto_id IS NOT NULL THEN
        INSERT INTO public.lotes (codigo_lote, produto_id, programacao_id, status, volume_produzido, data_producao)
        VALUES (public.gerar_codigo_lote(), NEW.produto_id, v_prog_id,
                'em_producao', NEW.volume_total_ml, CURRENT_DATE);
      END IF;
    WHEN 'em_cq' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aguardando_cq' WHERE id = v_prog_id;
      END IF;
      IF v_lote_id IS NOT NULL THEN
        UPDATE public.lotes SET status = 'aguardando_cq' WHERE id = v_lote_id;
      END IF;
    WHEN 'envase' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id;
      END IF;
    ELSE
      NULL;
  END CASE;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_evidencia_estado_editavel_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_id uuid; v_status text; v_comp_status text;
BEGIN
 IF TG_OP='UPDATE' AND NEW.entrega_id IS DISTINCT FROM OLD.entrega_id THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Não é permitido transferir evidências entre entregas.';
 END IF;
 IF TG_OP='DELETE' THEN v_id:=OLD.entrega_id; ELSE v_id:=NEW.entrega_id; END IF;
 SELECT e.status,e.comprovante_status INTO v_status,v_comp_status
 FROM public.entregas e WHERE e.id=v_id FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Entrega não encontrada ou sem acesso.';
 END IF;
 IF v_status='cancelada' OR v_comp_status IN ('confirmado','dispensado') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='As evidências desta entrega estão encerradas e não podem ser alteradas.';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_volumes_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.operation LIKE '%\_global\_volume%' OR (TG_OP='UPDATE' AND NEW.operation LIKE '%\_global\_volume%') THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_volumes_audit_immutable';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_talhao_safra_atual()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_next_id uuid;
  v_next_cultura uuid;
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.status = 'em_andamento' THEN
    UPDATE public.talhoes
      SET safra_atual_id = NEW.id,
          cultura_id = NEW.cultura_id
      WHERE id = NEW.talhao_id;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'em_andamento' AND NEW.status <> 'em_andamento' THEN
    SELECT id, cultura_id INTO v_next_id, v_next_cultura
      FROM public.talhao_safras
      WHERE talhao_id = NEW.talhao_id AND status = 'em_andamento' AND id <> NEW.id
      ORDER BY data_plantio DESC LIMIT 1;
    UPDATE public.talhoes
      SET safra_atual_id = v_next_id,
          cultura_id = COALESCE(v_next_cultura, cultura_id)
      WHERE id = NEW.talhao_id;
  END IF;

  IF TG_OP = 'DELETE' AND OLD.status = 'em_andamento' THEN
    SELECT id, cultura_id INTO v_next_id, v_next_cultura
      FROM public.talhao_safras
      WHERE talhao_id = OLD.talhao_id AND status = 'em_andamento' AND id <> OLD.id
      ORDER BY data_plantio DESC LIMIT 1;
    UPDATE public.talhoes
      SET safra_atual_id = v_next_id
      WHERE id = OLD.talhao_id;
    RETURN OLD;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_volume_normalize(p jsonb, p_create boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE k text; v_out jsonb:='{}'::jsonb; v_num numeric; v_int numeric;
BEGIN
  IF p IS NULL OR pg_catalog.jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  FOR k IN SELECT pg_catalog.jsonb_object_keys(p) LOOP
    IF k = 'volume_ml' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR (p->>k) !~ '^[0-9]{1,7}(\.[0-9]{1,3})?$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_num:=(p->>k)::numeric;
      IF v_num <= 0 OR v_num > 1000000 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_num);
    ELSIF k = 'preco_brl' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR (p->>k) !~ '^[0-9]{1,9}(\.[0-9]{1,2})?$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_num:=(p->>k)::numeric;
      -- > 0: preço zero ativo faria o sync anular o pai; preço desconhecido não é cadastrado.
      IF v_num <= 0 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_num);
    ELSIF k = 'rotulo' THEN
      IF pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::text);
      ELSIF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR pg_catalog.char_length(pg_catalog.btrim(p->>k)) > 60 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid';
      ELSE v_out:=v_out||pg_catalog.jsonb_build_object(k,NULLIF(pg_catalog.btrim(p->>k),''));
      END IF;
    ELSIF k = 'ordem' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_int:=(p->>k)::numeric;
      IF v_int <> pg_catalog.trunc(v_int) OR v_int < 0 OR v_int > 9999 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_int::int);
    ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid';
    END IF;
  END LOOP;
  IF p_create AND NOT (v_out ? 'volume_ml' AND v_out ? 'preco_brl') THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  IF NOT p_create AND v_out = '{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  RETURN v_out;
END;
$function$

