CREATE OR REPLACE FUNCTION platform_private.catalog_volume_settle(p_tipo text, p_item uuid, p_before jsonb, p_touches_active boolean, p_confirmed boolean, p_allow_reprice boolean, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_after jsonb; v_strip text[]:=ARRAY['valor_litro_brl','valor_dose_brl','valor_ha_brl','updated_at'];
  v_pb jsonb; v_pa jsonb; v_repriced boolean;
BEGIN
  v_after:=platform_private.catalog_volume_parent(p_tipo,p_item,false);
  IF (v_after - v_strip) IS DISTINCT FROM (p_before - v_strip) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_parent_protected_changed'; END IF;
  v_pb:=platform_private.catalog_volume_pricing(p_before); v_pa:=platform_private.catalog_volume_pricing(v_after);
  v_repriced:=(v_pb - 'updated_at') IS DISTINCT FROM (v_pa - 'updated_at');
  IF v_repriced AND NOT p_allow_reprice THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_unexpected_repricing'; END IF;
  IF (p_touches_active OR v_repriced) AND NOT COALESCE(p_confirmed,false) THEN
    IF p_token IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_confirmation_failed'; END IF;
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='catalog_volume_confirmation_required',
      DETAIL=pg_catalog.jsonb_build_object('token',p_token,'repriced',v_repriced,
        'parent_before',v_pb - 'updated_at','parent_after',v_pa - 'updated_at')::text;
  END IF;
  RETURN pg_catalog.jsonb_build_object('repriced',v_repriced,'parent_before',v_pb,'parent_after',v_pa);
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_fiscal_certificates_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_action text;
  v_old    jsonb;
  v_new    jsonb;
BEGIN
  v_action := TG_OP;
  IF TG_OP = 'INSERT' THEN
    v_old := '{}'::jsonb;
    v_new := jsonb_build_object(
      'source_type', NEW.source_type,
      'environment', NEW.environment,
      'status',      NEW.status,
      'display_name',NEW.display_name,
      'fingerprint_sha256', NEW.fingerprint_sha256,
      'valid_until', NEW.valid_until,
      'is_active',   NEW.is_active
    );
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := jsonb_build_object('status', OLD.status, 'is_active', OLD.is_active, 'valid_until', OLD.valid_until);
    v_new := jsonb_build_object('status', NEW.status, 'is_active', NEW.is_active, 'valid_until', NEW.valid_until);
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.fiscal_audit_log (
    table_name, record_id, action, changed_by, old_values, new_values
  ) VALUES (
    'fiscal_certificates', COALESCE(NEW.id, OLD.id), v_action, auth.uid(), v_old, v_new
  );
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cq_aprovado_avanca_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prog_id uuid;
  v_os_onfarm_id uuid;
  v_os_id uuid;
BEGIN
  IF EXISTS(SELECT 1 FROM public.lotes l JOIN public.programacao_producao p ON p.id=l.programacao_id WHERE l.id=NEW.lote_id AND p.ordem_servico_id IS NOT NULL) THEN RETURN NEW; END IF;
  IF NEW.resultado::text <> 'aprovado' THEN
    RETURN NEW;
  END IF;

  SELECT programacao_id INTO v_prog_id FROM public.lotes WHERE id = NEW.lote_id;
  IF v_prog_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ordem_servico_onfarm_id, ordem_servico_id
    INTO v_os_onfarm_id, v_os_id
    FROM public.programacao_producao
    WHERE id = v_prog_id;

  -- Mirror status on programacao and lote
  UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id;
  UPDATE public.lotes SET status = 'aprovado' WHERE id = NEW.lote_id;

  -- Advance OS On-Farm if it is at em_producao or em_cq
  IF v_os_onfarm_id IS NOT NULL THEN
    UPDATE public.ordens_servico_onfarm
      SET status = 'envase'
      WHERE id = v_os_onfarm_id
        AND status::text IN ('em_producao','em_cq');
  END IF;

  -- Advance legacy OS if it is at em_producao or em_cq
  IF v_os_id IS NOT NULL THEN
    UPDATE public.ordens_servico
      SET status = 'envase'
      WHERE id = v_os_id
        AND status::text IN ('em_producao','em_cq');
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_fiscal_xml_runs_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: execucoes de XML sao append-only; DELETE proibido.';
  END IF;

  IF coalesce(current_setting('app.fiscal_xml_engine', true),'off') <> 'on' THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: atualize execucoes apenas via rpc_fiscal_xml_record_v1.';
  END IF;

  IF NEW.id <> OLD.id
     OR NEW.fiscal_invoice_id <> OLD.fiscal_invoice_id
     OR NEW.idempotency_key <> OLD.idempotency_key
     OR NEW.run_version <> OLD.run_version
     OR NEW.payload_sha256 <> OLD.payload_sha256
     OR NEW.payload::text <> OLD.payload::text
     OR NEW.access_key <> OLD.access_key
     OR NEW.environment_code <> OLD.environment_code
     OR NEW.engine_version <> OLD.engine_version
     OR NEW.prepared_at <> OLD.prepared_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.previous_run_id IS DISTINCT FROM OLD.previous_run_id THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: campos congelados nao podem ser alterados.';
  END IF;

  IF OLD.unsigned_sha256 IS NOT NULL AND NEW.unsigned_sha256 IS DISTINCT FROM OLD.unsigned_sha256 THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: hash do XML nao assinado ja registrado.';
  END IF;
  IF OLD.signed_sha256 IS NOT NULL AND NEW.signed_sha256 IS DISTINCT FROM OLD.signed_sha256 THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: hash do XML assinado ja registrado.';
  END IF;
  IF OLD.unsigned_path IS NOT NULL AND NEW.unsigned_path IS DISTINCT FROM OLD.unsigned_path THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: caminho do XML nao assinado ja registrado.';
  END IF;
  IF OLD.signed_path IS NOT NULL AND NEW.signed_path IS DISTINCT FROM OLD.signed_path THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: caminho do XML assinado ja registrado.';
  END IF;

  IF OLD.state IN ('SIGNED','FAILED') AND NEW.state <> OLD.state THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_TERMINAL: execucao % ja esta em estado terminal %.', OLD.id, OLD.state;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_notify_payment_terms_pending()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_should_notify boolean := false;
  v_msg text;
BEGIN
  IF NEW.requires_financial_approval IS DISTINCT FROM true
     OR NEW.financial_approval_status IS DISTINCT FROM 'pending' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_should_notify := true;
  ELSE
    -- Só notifica quando entra em pending vindo de outro estado
    IF COALESCE(OLD.requires_financial_approval, false) = false
       OR COALESCE(OLD.financial_approval_status, 'not_required') <> 'pending' THEN
      v_should_notify := true;
    END IF;
  END IF;

  IF NOT v_should_notify THEN
    RETURN NEW;
  END IF;

  v_msg := format('Pedido B2B %s aguarda aprovação da condição de pagamento.', COALESCE(NEW.numero,''));

  PERFORM public._notify_role(
    'financeiro'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );
  PERFORM public._notify_role(
    'administrador'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );
  PERFORM public._notify_role(
    'gestor_comercial'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );

  -- Notifica também o criador do pedido, se identificado
  IF NEW.created_by IS NOT NULL THEN
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link, lido)
    VALUES (
      NEW.created_by,
      'b2b_payment_terms_pending',
      'Aprovação financeira pendente',
      v_msg,
      '/comercial/pedidos-b2b',
      false
    );
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.change_global_volume(p_operation text, p_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb, p_ativo boolean, p_confirm_token text, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_tipo text; v_item uuid; v_parent jsonb; v_token text;
  v_old public.catalogo_volumes%ROWTYPE; v_before jsonb; v_settle jsonb; v_row jsonb; v_receipt jsonb; v_n int;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at)
    OR (p_confirm_token IS NOT NULL AND p_confirm_token !~ '^[0-9a-f]{64}$')
    OR (p_operation='set_global_volume_status' AND p_ativo IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  IF p_operation='update_global_volume' THEN v:=platform_private.catalog_volume_normalize(p_patch,false);
  ELSIF p_operation='set_global_volume_status' THEN v:=pg_catalog.jsonb_build_object('ativo',p_ativo);
  ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  v_req:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'change',v,'confirm_token',p_confirm_token,
    'reason',pg_catalog.btrim(p_reason));
  -- Replay idempotente (mesma chave + mesmo pedido, incluindo token) devolve o recibo original, mesmo que o estado tenha mudado.
  v_replay:=platform_private.catalog_entity_replay(v_actor,p_operation,v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  SELECT item_tipo, COALESCE(produto_id,microrganismo_id) INTO v_tipo, v_item FROM public.catalogo_volumes WHERE id=p_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_volume_unavailable'; END IF;
  v_parent:=platform_private.catalog_volume_parent(v_tipo,v_item,true);   -- lock do pai antes da linha (serializa irmãs)
  SELECT * INTO v_old FROM public.catalogo_volumes WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR v_old.item_tipo IS DISTINCT FROM v_tipo OR COALESCE(v_old.produto_id,v_old.microrganismo_id) IS DISTINCT FROM v_item THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_conflict'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_conflict'; END IF;
  IF p_operation='set_global_volume_status' AND v_old.ativo = p_ativo THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_conflict'; END IF;
  -- Token recalculado sob lock do pai, ANTES da mutação. Token enviado e divergente => prévia desatualizada.
  v_token:=platform_private.catalog_volume_preview_token(v_actor,p_operation,p_id,v,p_reason,v_old.updated_at,v_tipo,v_item,v_parent);
  IF p_confirm_token IS NOT NULL AND p_confirm_token IS DISTINCT FROM v_token THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_preview_stale'; END IF;
  v_before:=platform_private.catalog_volume_row(p_id);
  -- Overflow em derivados ou na coluna de preço do pai (limite depende do tipo do pai e da dose/ha reais) =>
  -- 22003 de domínio; a transação inteira é revertida (linha, pai e ledger intactos). 55000/40001 passam inalterados.
  BEGIN
  UPDATE public.catalogo_volumes SET
    volume_ml=CASE WHEN v ? 'volume_ml' THEN (v->>'volume_ml')::numeric ELSE volume_ml END,
    preco_brl=CASE WHEN v ? 'preco_brl' THEN (v->>'preco_brl')::numeric ELSE preco_brl END,
    rotulo=CASE WHEN v ? 'rotulo' THEN v->>'rotulo' ELSE rotulo END,
    ordem=CASE WHEN v ? 'ordem' THEN (v->>'ordem')::int ELSE ordem END,
    ativo=CASE WHEN v ? 'ativo' THEN (v->>'ativo')::boolean ELSE ativo END
  WHERE id=p_id AND updated_at=p_expected_updated_at;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n <> 1 THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_conflict'; END IF;
  PERFORM platform_private.catalog_volume_assert_row(p_id,v_tipo,v_item);
  v_row:=platform_private.catalog_volume_row(p_id);
  IF (v_row->>'updated_at')::timestamptz <= v_old.updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_confirmation_failed'; END IF;
  -- Toca linha ativa (antes ou depois) ou reprecifica o pai => sem token: 55000 com prévia (rollback integral);
  -- com token válido (já conferido acima): segue.
  v_settle:=platform_private.catalog_volume_settle(v_tipo,v_item,v_parent,v_old.ativo OR (v_row->>'ativo')::boolean,
    p_confirm_token IS NOT NULL,true,v_token);
  EXCEPTION WHEN numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='catalog_volume_price_out_of_range';
  END;
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'item_tipo',v_tipo,'item_id',v_item,'ativo',(v_row->>'ativo')::boolean,
    'updated_at',v_row->'updated_at','repriced',v_settle->'repriced','idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,p_operation,p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('volume',v_before,'parent',v_settle->'parent_before'),
    pg_catalog.jsonb_build_object('volume',v_row,'parent',v_settle->'parent_after'));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_partner_orders_credit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb;
  v_amount numeric(14,2);
  v_should_check boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('rascunho') THEN v_should_check := true; END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.credit_approved_by IS NOT NULL
       AND NEW.status = 'em_analise_comercial'
       AND OLD.status = 'aguardando_aprovacao_credito'
       AND NEW.total IS NOT DISTINCT FROM OLD.total THEN
      NEW.credit_block_reason := NULL;
      RETURN NEW;
    END IF;

    IF NEW.credit_approved_by IS NOT NULL AND OLD.credit_approved_by IS NULL THEN
      NEW.credit_block_reason := NULL;
      RETURN NEW;
    END IF;

    IF OLD.credit_approved_by IS NOT NULL
       AND NEW.status = 'aprovado'
       AND OLD.status = 'em_analise_comercial'
       AND NEW.total IS NOT DISTINCT FROM OLD.total THEN
      RETURN NEW;
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status
       AND NEW.status IN ('em_analise_comercial','aprovado') THEN
      v_should_check := true;
    ELSIF (NEW.total IS DISTINCT FROM OLD.total
        OR NEW.final_amount_with_interest IS DISTINCT FROM OLD.final_amount_with_interest)
       AND NEW.status IN ('em_analise_comercial','aprovado','aguardando_aprovacao_credito') THEN
      v_should_check := true;
    END IF;
  END IF;

  IF NOT v_should_check THEN RETURN NEW; END IF;

  -- Serializa a avaliacao de credito por parceiro dentro da transacao corrente.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || NEW.partner_id::text, 0));

  v_amount := ROUND(COALESCE(NEW.final_amount_with_interest, NEW.total, 0), 2);
  v := public.fn_b2b_credit_exposure(NEW.partner_id, v_amount, NEW.id);

  IF (v->>'block_if_overdue')::boolean AND (v->>'tem_vencidos')::boolean THEN
    NEW.status := 'aguardando_aprovacao_credito';
    NEW.credit_block_reason := 'inadimplencia';
    RETURN NEW;
  END IF;

  IF COALESCE((v->>'credit_limit')::numeric,0) > 0
     AND (v->>'exposicao_projetada')::numeric > (v->>'credit_limit')::numeric THEN
    NEW.status := 'aguardando_aprovacao_credito';
    NEW.credit_block_reason := CASE
      WHEN (v->>'credit_limit_action') = 'approval_required' THEN 'limite_excedido'
      ELSE 'limite_excedido_bloqueado'
    END;
  END IF;

  RETURN NEW;
END $function$

