CREATE OR REPLACE FUNCTION public.trg_clientes_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    old_val JSONB := NULL;
    new_val JSONB := NULL;
    v_diff JSONB := '{}'::jsonb;
BEGIN
    IF (TG_OP = 'UPDATE') THEN
        old_val := to_jsonb(OLD);
        new_val := to_jsonb(NEW);
        SELECT jsonb_object_agg(key, value) INTO v_diff FROM jsonb_each(new_val) WHERE new_val->key IS DISTINCT FROM old_val->key;
    ELSIF (TG_OP = 'INSERT') THEN
        new_val := to_jsonb(NEW);
    ELSIF (TG_OP = 'DELETE') THEN
        old_val := to_jsonb(OLD);
    END IF;

    INSERT INTO public.clientes_audit_log (cliente_id, action, changed_by, old_data, new_data, diff)
    VALUES (COALESCE(NEW.id, OLD.id), TG_OP, auth.uid(), old_val, new_val, v_diff);

    RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_dossier_submit(p_dossier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_status text; v_row public.microorganism_regulatory_dossiers;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  SELECT status INTO v_status FROM public.microorganism_regulatory_dossiers
   WHERE id = p_dossier_id AND deleted_at IS NULL FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_FOUND' USING ERRCODE='22023'; END IF;
  IF v_status <> 'DRAFT' THEN
    RAISE EXCEPTION 'REGULATORY_INVALID_TRANSITION' USING ERRCODE='55006';
  END IF;
  UPDATE public.microorganism_regulatory_dossiers
     SET status = 'PENDING_REVIEW', updated_by = auth.uid()
   WHERE id = p_dossier_id RETURNING * INTO v_row;
  RETURN to_jsonb(v_row);
END $function$

CREATE OR REPLACE FUNCTION platform_private.create_global_volume_core(p_item_tipo text, p_item_id uuid, p_payload jsonb, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_before jsonb; v_settle jsonb; v_id uuid; v_row jsonb; v_receipt jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  v:=platform_private.catalog_volume_normalize(p_payload,true);
  v_req:=pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'item_id',p_item_id,'payload',v,'reason',pg_catalog.btrim(p_reason));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'create_global_volume',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  v_before:=platform_private.catalog_volume_parent(p_item_tipo,p_item_id,true);
  -- Overflow de derivados/preços do pai (p.ex. numeric(10,2) histórico) = rejeição de domínio atômica (sem ampliar tipos).
  BEGIN
  INSERT INTO public.catalogo_volumes (item_tipo,produto_id,microrganismo_id,volume_ml,rotulo,preco_brl,moeda,ativo,ordem)
  VALUES (p_item_tipo, CASE WHEN p_item_tipo='produto' THEN p_item_id END, CASE WHEN p_item_tipo='microrganismo' THEN p_item_id END,
    (v->>'volume_ml')::numeric, v->>'rotulo', (v->>'preco_brl')::numeric, 'BRL', false, COALESCE((v->>'ordem')::int,0))
  RETURNING id INTO v_id;
  PERFORM platform_private.catalog_volume_assert_row(v_id,p_item_tipo,p_item_id);
  -- Nasce inativa: qualquer alteração no pai é falha (não apaga preço legado silenciosamente).
  v_settle:=platform_private.catalog_volume_settle(p_item_tipo,p_item_id,v_before,false,false,false,NULL);
  EXCEPTION WHEN numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='catalog_volume_price_out_of_range';
  END;
  v_row:=platform_private.catalog_volume_row(v_id);
  v_receipt:=pg_catalog.jsonb_build_object('id',v_id,'item_tipo',p_item_tipo,'item_id',p_item_id,'ativo',false,'updated_at',v_row->'updated_at',
    'repriced',false,'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'create_global_volume',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('volume','{}'::jsonb,'parent',v_settle->'parent_before'),
    pg_catalog.jsonb_build_object('volume',v_row,'parent',v_settle->'parent_after'));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_entrega_sync_partner_order_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_total int; v_delivered int;
BEGIN
  SELECT os.partner_order_id INTO v_partner_order_id
    FROM public.ordens_servico os WHERE os.id = COALESCE(NEW.ordem_servico_id, OLD.ordem_servico_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE e.status = 'entregue')
    INTO v_total, v_delivered
    FROM public.entregas e
    JOIN public.ordens_servico os ON os.id = e.ordem_servico_id
   WHERE os.partner_order_id = v_partner_order_id;

  IF v_total > 0 AND v_delivered = v_total THEN
    UPDATE public.partner_orders SET status = 'entregue', updated_at = now()
      WHERE id = v_partner_order_id AND status <> 'entregue';
    UPDATE public.production_planning SET status = 'entregue', updated_at = now()
      WHERE partner_order_id = v_partner_order_id;
    INSERT INTO public.production_timeline_events (partner_order_id, event_type, meta)
    VALUES (v_partner_order_id, 'entrega_realizada', jsonb_build_object('total', v_total));
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_mestre_guard_preco_canonico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_litro numeric;
  v_tiers integer;
BEGIN
  IF COALESCE(current_setting('arbio.catalogo_sync', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'produtos' THEN
    SELECT litro, tiers INTO v_litro, v_tiers FROM public.fn_catalogo_litro_canonico(NEW.id, NULL);
    IF COALESCE(v_tiers,0) = 0 THEN RETURN NEW; END IF;
    IF v_tiers = 1 AND COALESCE(v_litro,0) > 0 THEN
      NEW.valor_litro_brl := v_litro;
      NEW.valor_dose_brl  := round(v_litro / 10.0, 2);
      NEW.valor_ha_brl    := CASE WHEN COALESCE(NEW.dose_ml_ha,0) > 0
                                  THEN round(v_litro * (NEW.dose_ml_ha / 1000.0), 2) END;
    ELSE
      NEW.valor_litro_brl := NULL; NEW.valor_dose_brl := NULL; NEW.valor_ha_brl := NULL;
    END IF;
  ELSE
    SELECT litro, tiers INTO v_litro, v_tiers FROM public.fn_catalogo_litro_canonico(NULL, NEW.id);
    IF COALESCE(v_tiers,0) = 0 THEN RETURN NEW; END IF;
    IF v_tiers = 1 AND COALESCE(v_litro,0) > 0 THEN
      NEW.valor_litro_brl := v_litro;
      NEW.valor_dose_brl  := round(v_litro / 10.0, 2);
    ELSE
      NEW.valor_litro_brl := NULL; NEW.valor_dose_brl := NULL;
    END IF;
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_partner_order_timeline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, actor_id, meta)
    VALUES (NEW.id, 'pedido_criado', NEW.created_at, NEW.created_by, '{}'::jsonb);
  ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'aprovado' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'pedido_aprovado', now(), '{}'::jsonb);
    ELSIF NEW.status = 'em_producao' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'producao_iniciada', now(), '{}'::jsonb);
    ELSIF NEW.status IN ('produzido','aguardando_entrega') THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'producao_finalizada', now(), '{}'::jsonb);
    ELSIF NEW.status = 'entregue' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'entrega_realizada', now(), '{}'::jsonb);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_service_ibs_cbs_save(p_service_id uuid, payload jsonb, expected_revision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_id uuid; v_stamp timestamptz; v_new text; v_count integer;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'FISCAL_UNAUTHENTICATED' USING ERRCODE='42501'; END IF;
 IF NOT (platform_private.platform_actor_access_ready(v_uid) AND public.is_platform_superadmin(v_uid)) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE' USING ERRCODE='55000'; END IF;
 IF NOT (platform_private.platform_actor_access_ready(v_uid) AND public.is_platform_superadmin(v_uid)) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM public._fiscal_rtc_assert_payload(payload,'item');
 SELECT count(*) INTO v_count FROM public.service_fiscal_profiles WHERE service_id=p_service_id AND is_active IS TRUE;
 IF v_count=0 THEN RAISE EXCEPTION 'FISCAL_ITEM_NOT_FOUND' USING ERRCODE='PT404'; END IF;
 IF v_count<>1 THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 SELECT id,updated_at INTO v_id,v_stamp FROM public.service_fiscal_profiles WHERE service_id=p_service_id AND is_active IS TRUE FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_ITEM_NOT_FOUND' USING ERRCODE='PT404'; END IF;
 IF expected_revision IS NULL OR expected_revision IS DISTINCT FROM v_stamp::text THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 UPDATE public.service_fiscal_profiles SET ibs_cbs_configuration=payload,updated_at=greatest(clock_timestamp(),v_stamp+interval '1 microsecond'),updated_by=v_uid
 WHERE id=v_id AND is_active IS TRUE AND updated_at=v_stamp RETURNING updated_at::text INTO v_new;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 RETURN jsonb_build_object('configuration',payload,'revision',v_new);
END; $function$

CREATE OR REPLACE FUNCTION public.validate_estoque_reserva()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status::text = 'reservado' AND (OLD.status IS DISTINCT FROM NEW.status OR OLD.status::text <> 'reservado') THEN
    IF NEW.reservado_para_os_id IS NULL THEN
      RAISE EXCEPTION 'Reserva requer uma OS vinculada.' USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.reservado_para_os_tipo = 'b2b' THEN
      IF NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva B2B requer um parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.reservado_para_cliente_id IS NULL AND NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva requer um cliente ou parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    IF NEW.quantidade_reservada IS NULL OR NEW.quantidade_reservada <= 0 THEN
      RAISE EXCEPTION 'Informe uma quantidade reservada maior que zero.' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.quantidade IS NOT NULL AND NEW.quantidade_reservada > NEW.quantidade THEN
      RAISE EXCEPTION 'Quantidade reservada (%) excede o estoque disponível (%).', NEW.quantidade_reservada, NEW.quantidade
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.reservado_em IS NULL THEN NEW.reservado_em := now(); END IF;
    IF NEW.reservado_por IS NULL THEN NEW.reservado_por := auth.uid(); END IF;
  END IF;

  IF NEW.status::text = 'disponivel' AND OLD.status::text = 'reservado' THEN
    NEW.reservado_para_os_id := NULL;
    NEW.reservado_para_os_tipo := NULL;
    NEW.reservado_para_cliente_id := NULL;
    NEW.reservado_para_partner_id := NULL;
    NEW.reservado_para_partner_order_id := NULL;
    NEW.quantidade_reservada := NULL;
    NEW.reservado_por := NULL;
    NEW.reservado_em := NULL;
    NEW.observacao_reserva := NULL;
  END IF;

  IF NEW.status::text = 'expedido' AND OLD.status::text <> 'expedido' THEN
    IF NEW.expedido_em IS NULL THEN NEW.expedido_em := now(); END IF;
    IF NEW.expedido_por IS NULL THEN NEW.expedido_por := auth.uid(); END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_partner_user_client_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Preenche user_role automaticamente se vazio
  IF NEW.user_role IS NULL THEN
    NEW.user_role := public.get_b2b_user_role_for_partner(NEW.user_id, NEW.partner_id);
  END IF;

  -- Usuário deve pertencer ao parceiro
  IF NOT public.is_valid_b2b_partner_user(NEW.user_id, NEW.partner_id) THEN
    RAISE EXCEPTION 'Usuário % não é um usuário B2B válido do parceiro %', NEW.user_id, NEW.partner_id;
  END IF;

  -- Cliente deve estar vinculado ao parceiro (ativo) em partner_clients
  IF NOT EXISTS (
    SELECT 1 FROM public.partner_clients pc
    WHERE pc.partner_id = NEW.partner_id
      AND pc.cliente_id = NEW.cliente_id
      AND pc.active = true
  ) THEN
    RAISE EXCEPTION 'Cliente % não está vinculado ao parceiro %', NEW.cliente_id, NEW.partner_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_estoque_entrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Reservas parciais (têm quantidade_reservada preenchida) seguem normalmente
  IF NEW.quantidade_reservada IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Exigir envase para o lote
  IF NOT EXISTS (SELECT 1 FROM public.envase WHERE lote_id = NEW.lote_id) THEN
    RAISE EXCEPTION 'Não é possível criar entrada no estoque: o lote ainda não possui registro de envase.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Bloquear duplicidade por envase_id (não mais por lote)
  IF NEW.envase_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE envase_id = NEW.envase_id
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe entrada de estoque para este envase.'
      USING ERRCODE = 'unique_violation';
  END IF;

  -- Compat: se a entrada vier sem envase_id, manter a regra antiga de 1 por lote
  IF NEW.envase_id IS NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE lote_id = NEW.lote_id
      AND envase_id IS NULL
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe uma entrada de estoque agregada para este lote.'
      USING ERRCODE = 'unique_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_responsavel_producao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_ok boolean;
BEGIN
  IF NEW.responsavel_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO v_user_id
  FROM public.profiles
  WHERE id = NEW.responsavel_id;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Responsável inválido: perfil não encontrado'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_user_id
      AND role::text IN ('administrador','gestor','operador_onfarm','producao')
  ) INTO v_ok;

  IF NOT v_ok THEN
    RAISE EXCEPTION 'Responsável inválido: perfil sem permissão para produção do laboratório'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_item_readiness(p_scope text, p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_res jsonb;
BEGIN
  IF v_uid IS NULL
     OR NOT (public.has_role(v_uid,'administrador'::app_role)
          OR public.has_role(v_uid,'gestor'::app_role)
          OR public.has_role(v_uid,'financeiro'::app_role)) THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501';
  END IF;

  IF p_scope = 'PRODUCT' THEN
    SELECT gate INTO v_res FROM public.v_product_fiscal_readiness
    WHERE product_id = p_item_id LIMIT 1;
  ELSIF p_scope = 'MICROORGANISM' THEN
    SELECT gate INTO v_res FROM public.v_microorganism_fiscal_readiness
    WHERE microorganism_id = p_item_id LIMIT 1;
  ELSE
    RAISE EXCEPTION 'FISCAL_INVALID_SCOPE' USING ERRCODE='22023';
  END IF;

  RETURN COALESCE(
    v_res,
    public.fn_fiscal_item_profile_gate_eval(
      p_scope, public.fn_fiscal_company_crt(), NULL, NULL, NULL, NULL,
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL));
END
$function$

CREATE OR REPLACE FUNCTION platform_private.b2b_save_technical_simulation(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); p uuid; s uuid; i jsonb; iid uuid; kind text; qty numeric; nm text; cl uuid;
BEGIN
 IF u IS NULL OR NOT public.has_role(u,'parceiro_b2b_tecnico') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;
 p:=(p_payload->>'partner_id')::uuid;
 IF NOT platform_private.b2b_phase1_partner_visible(p,true) THEN RAISE EXCEPTION 'scope_denied' USING ERRCODE='42501'; END IF;
 IF NOT public._saas_user_has_feature(u,'simulacoes') THEN RAISE EXCEPTION 'feature_not_entitled' USING ERRCODE='42501'; END IF;
 IF coalesce(p_payload->>'status','rascunho') NOT IN ('rascunho','enviada_gestor') THEN RAISE EXCEPTION 'invalid_status'; END IF;
 IF jsonb_typeof(p_payload->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'items')=0 THEN RAISE EXCEPTION 'empty_simulation'; END IF;
 cl:=nullif(p_payload->>'cliente_id','')::uuid;
 IF cl IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM public.partner_user_clients puc WHERE puc.cliente_id=cl AND puc.user_id=u AND puc.partner_id=p AND puc.active=true) OR EXISTS (SELECT 1 FROM public.partner_technician_clients ptc WHERE ptc.cliente_id=cl AND ptc.technician_user_id=u AND ptc.partner_id=p AND ptc.active=true)) THEN RAISE EXCEPTION 'client_scope_denied' USING ERRCODE='42501'; END IF;
 INSERT INTO public.partner_simulations(partner_id,created_by,titulo,observacoes,cultura,area_total_ha,objetivo_tecnico,status,total_cheio,valid_until,cliente_id)
 VALUES(p,u,left(p_payload->>'titulo',200),left(p_payload->>'observacoes',4000),left(p_payload->>'cultura',200),(p_payload->>'area_total_ha')::numeric,left(p_payload->>'objetivo_tecnico',2000),'rascunho',0,(p_payload->>'valid_until')::date,cl) RETURNING id INTO s;
 FOR i IN SELECT * FROM jsonb_array_elements(p_payload->'items') LOOP
  iid:=(i->>'item_id')::uuid; kind:=i->>'item_tipo'; qty:=(i->>'quantidade')::numeric;
  IF qty IS NULL OR qty<=0 OR qty::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'invalid_qty'; END IF;
  IF kind='produto' THEN SELECT nome INTO nm FROM public.produtos WHERE id=iid AND ativo AND b2b_enabled;
  ELSIF kind='microrganismo' THEN SELECT nome INTO nm FROM public.microrganismos WHERE id=iid AND ativo AND b2b_enabled;
  ELSE RAISE EXCEPTION 'invalid_item'; END IF;
  IF nm IS NULL THEN RAISE EXCEPTION 'product_unavailable'; END IF;
  IF coalesce(i->>'unidade_medida','hectare') NOT IN ('hectare','litro','dose','unidade') THEN RAISE EXCEPTION 'invalid_unit'; END IF;
  IF i->>'unidade_medida'='unidade' AND coalesce((i->>'volume_ml')::numeric,0)<=0 THEN RAISE EXCEPTION 'invalid_volume'; END IF;
  INSERT INTO public.partner_simulation_items(simulation_id,item_tipo,item_id,nome,quantidade,valor_unitario_cheio,subtotal,unidade_medida,volume_ml,area_ha)
  VALUES(s,kind,iid,nm,qty,0,0,coalesce(i->>'unidade_medida','hectare'),(i->>'volume_ml')::numeric,(i->>'area_ha')::numeric);
 END LOOP;
 IF p_payload->>'status'='enviada_gestor' THEN PERFORM public.send_partner_simulation_to_manager_secure(s); END IF;
 RETURN s;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_operation_policy_publish(p_policy_id uuid, p_justification text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p public.fiscal_operation_policies%ROWTYPE; ov public.fiscal_rule_sod_overrides%ROWTYPE;
BEGIN
  IF NOT public.fn_regulatory_can_approve('FISCAL') THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao para publicar politica de operacao.';
  END IF;
  SELECT * INTO p FROM public.fiscal_operation_policies WHERE id = p_policy_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_OPERATION_POLICY_NOT_FOUND: %', p_policy_id; END IF;
  IF p.policy_status <> 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_OPERATION_POLICY_NOT_DRAFT: apenas rascunho pode ser publicado (status=%)', p.policy_status;
  END IF;
  IF p.cfop IS NULL OR p.nature_operation IS NULL OR p.direction IS NULL
     OR p.source_id IS NULL OR nullif(btrim(coalesce(p.legal_basis,'')),'') IS NULL THEN
    RAISE EXCEPTION 'FISCAL_OPERATION_POLICY_INCOMPLETE: CFOP, natureza, sentido, base legal e fonte oficial sao obrigatorios.';
  END IF;
  IF p.prepared_by IS NOT NULL AND p.prepared_by = auth.uid() THEN
    SELECT * INTO ov FROM public.fiscal_rule_sod_overrides
     WHERE scope = 'OPERATION_POLICY' AND target_id = p.id AND consumed_at IS NULL
     ORDER BY granted_at DESC LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'FISCAL_SEGREGATION_OF_DUTIES: quem preparou a politica nao pode publica-la.';
    END IF;
    UPDATE public.fiscal_rule_sod_overrides SET consumed_at = now(), consumed_by = auth.uid() WHERE id = ov.id;
  END IF;

  UPDATE public.fiscal_operation_policies
     SET policy_status = 'PUBLISHED', published_by = auth.uid(), published_at = now(),
         document_model = '55', notes = coalesce(nullif(btrim(coalesce(p_justification,'')),''), notes),
         updated_by = auth.uid(), updated_at = now()
   WHERE id = p_policy_id;

  RETURN jsonb_build_object('policyId', p_policy_id, 'status','PUBLISHED', 'cfop', p.cfop);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_preflight_v1(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_user      uuid := auth.uid();
  v_inv       public.fiscal_invoices;
  v_blockers  jsonb := '[]'::jsonb;
  v_warnings  jsonb := '[]'::jsonb;
  v_env       text := NULL;
  v_validate  jsonb;
  v_sum       numeric(14,2);
  v_diff      numeric(14,2);
  v_tolerance numeric := 0.01;
  v_dups      integer;
  v_miss      jsonb;
  v_pend      jsonb;
  v_cfs       public.company_fiscal_settings;
  v_cfp       public.customer_fiscal_profiles;
  r           RECORD;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(p_invoice_id);

  IF v_user IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT (public.has_role(v_user, 'administrador'::app_role)
          OR public.has_role(v_user, 'financeiro'::app_role)
          OR public.has_role(v_user, 'gestor'::app_role)) THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem competencia fiscal.' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_inv FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: %', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  -- 1) Ambiente (fail-closed; produção sempre recusada pelo gate).
  BEGIN
    v_env := public.fn_fiscal_environment_gate_v1('PREFLIGHT');
  EXCEPTION WHEN OTHERS THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code', split_part(SQLERRM, ':', 1),
      'section', 'AMBIENTE',
      'field', 'environment',
      'message', SQLERRM,
      'action', 'Revisar configuracao do emitente/ambiente com a contabilidade.');
  END;

  -- 2) Regras de documento/itens/tributos, explodidas POR CAMPO.
  BEGIN
    v_validate := public.rpc_fiscal_draft_validate_homologation(p_invoice_id);
  EXCEPTION WHEN OTHERS THEN
    v_validate := jsonb_build_object('status','BLOCKED','reason', SQLERRM);
  END;

  IF coalesce(v_validate->>'status','BLOCKED') = 'BLOCKED'
     AND coalesce(jsonb_array_length(v_validate->'missing'), 0) = 0 THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','FISCAL_DOCUMENT_BLOCKED','section','DOCUMENTO','field','document',
      'message', coalesce(v_validate->>'reason','Documento fiscal bloqueado para homologacao.'),
      'action','Revisar a situacao do documento antes de transmitir.');
  END IF;

  FOR v_miss IN
    SELECT value FROM jsonb_array_elements(coalesce(v_validate->'missing','[]'::jsonb))
  LOOP
    v_blockers := v_blockers || jsonb_build_object(
      'code', 'FISCAL_FIELD_REQUIRED',
      'section', CASE
                   WHEN v_miss->>'field' LIKE 'item%' THEN 'ITENS'
                   WHEN v_miss->>'field' LIKE 'customer%' THEN 'DESTINATARIO'
                   WHEN v_miss->>'field' IN ('company','certificate') THEN 'EMITENTE'
                   ELSE 'DOCUMENTO'
                 END,
      'field', v_miss->>'field',
      'itemSequence', v_miss->'item_sequence',
      'message', v_miss->>'message',
      'action', 'Preencher o campo indicado no cadastro de origem.');
  END LOOP;

  -- 3) Pendências do EMITENTE (reutiliza a função canônica de prontidão).
  SELECT * INTO v_cfs FROM (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) company_fiscal_settings WHERE is_active LIMIT 1;
  IF FOUND THEN
    FOR v_pend IN
      SELECT value FROM jsonb_array_elements(
        coalesce(public.fn_fiscal_emitter_pendencies_row(v_cfs), '[]'::jsonb))
    LOOP
      IF coalesce(v_pend->>'severity','BLOCK') = 'BLOCK' THEN
        v_blockers := v_blockers || jsonb_build_object(
          'code', v_pend->>'code', 'section','EMITENTE',
          'field', v_pend->>'field', 'message', v_pend->>'message',
          'action','Completar o cadastro do emitente.');
      ELSE
        v_warnings := v_warnings || jsonb_build_object(
          'code', v_pend->>'code', 'section','EMITENTE',
          'field', v_pend->>'field', 'message', v_pend->>'message',
          'action','Conferir manualmente com a contabilidade.');
      END IF;
    END LOOP;
  END IF;

  -- 4) Pendências do DESTINATÁRIO (documento/IE/UF/município/endereço).
  IF v_inv.customer_id IS NOT NULL THEN
    SELECT * INTO v_cfp FROM public.customer_fiscal_profiles
     WHERE customer_id = v_inv.customer_id LIMIT 1;
    IF FOUND THEN
      FOR v_pend IN
        SELECT value FROM jsonb_array_elements(
          coalesce(public.fn_fiscal_recipient_pendencies_row(v_cfp), '[]'::jsonb))
      LOOP
        IF coalesce(v_pend->>'severity','BLOCK') = 'BLOCK' THEN
          v_blockers := v_blockers || jsonb_build_object(
            'code', v_pend->>'code', 'section','DESTINATARIO',
            'field', v_pend->>'field', 'message', v_pend->>'message',
            'action','Completar o perfil fiscal do destinatario.');
        ELSE
          v_warnings := v_warnings || jsonb_build_object(
            'code', v_pend->>'code', 'section','DESTINATARIO',
            'field', v_pend->>'field', 'message', v_pend->>'message',
            'action','Conferir o perfil fiscal do destinatario.');
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- 5) Sanidade aritmética item a item (unidade, quantidade, valores).
  FOR r IN
    SELECT item_sequence, quantity, unit_value, commercial_unit,
           net_value, gross_value, discount_value
      FROM (SELECT * FROM public.fiscal_invoice_items WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_invoice_items
     WHERE fiscal_invoice_id = p_invoice_id
     ORDER BY item_sequence
  LOOP
    IF r.quantity IS NULL OR r.quantity <= 0 THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','FISCAL_ITEM_QUANTITY_INVALID','section','ITENS','field','quantity',
        'itemSequence', r.item_sequence,
        'message', format('Item %s com quantidade invalida.', r.item_sequence),
        'action','Corrigir a quantidade do item.');
    END IF;
    IF r.commercial_unit IS NULL OR btrim(r.commercial_unit) = '' THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','FISCAL_ITEM_UNIT_MISSING','section','ITENS','field','commercial_unit',
        'itemSequence', r.item_sequence,
        'message', format('Item %s sem unidade comercial.', r.item_sequence),
        'action','Definir a unidade comercial do item.');
    END IF;
    IF r.unit_value IS NULL OR r.unit_value < 0 THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','FISCAL_ITEM_UNIT_VALUE_INVALID','section','ITENS','field','unit_value',
        'itemSequence', r.item_sequence,
        'message', format('Item %s com valor unitario invalido.', r.item_sequence),
        'action','Corrigir o valor unitario do item.');
    END IF;
    IF r.net_value IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','FISCAL_ITEM_NET_VALUE_MISSING','section','ITENS','field','net_value',
        'itemSequence', r.item_sequence,
        'message', format('Item %s sem valor liquido calculado.', r.item_sequence),
        'action','Recalcular o documento fiscal.');
    ELSIF r.quantity IS NOT NULL AND r.unit_value IS NOT NULL
          AND abs(r.net_value - (r.quantity * r.unit_value - coalesce(r.discount_value,0))) > v_tolerance THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','FISCAL_ITEM_TOTAL_MISMATCH','section','ITENS','field','net_value',
        'itemSequence', r.item_sequence,
        'message', format('Item %s: liquido diverge de quantidade x unitario - desconto.', r.item_sequence),
        'action','Recalcular o documento a partir do snapshot de origem.');
    END IF;
  END LOOP;

  -- 6) Coerência aritmética dos totais (tolerância documentada de R$ 0,01).
  SELECT coalesce(sum(coalesce(net_value, gross_value, quantity * unit_value)), 0)::numeric(14,2)
    INTO v_sum
    FROM (SELECT * FROM public.fiscal_invoice_items WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_invoice_items WHERE fiscal_invoice_id = p_invoice_id;

  IF v_inv.total_amount IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','FISCAL_TOTAL_MISSING','section','TOTAIS','field','total_amount',
      'message','Total do documento nao informado.','action','Recalcular o documento.');
  ELSE
    v_diff := abs(v_inv.total_amount - v_sum);
    IF v_diff > v_tolerance THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','FISCAL_TOTAL_MISMATCH','section','TOTAIS','field','total_amount',
        'message', format('Total do documento (%s) diverge da soma dos itens (%s).', v_inv.total_amount, v_sum),
        'action','Recalcular o documento a partir do snapshot de origem.');
    END IF;
  END IF;

  -- 7) Duplicidade ativa por origem (mesma regra do índice ux_fiscal_invoice_scope_nfe).
  IF v_inv.source_id IS NOT NULL AND v_inv.document_model = 'NFE' THEN
    SELECT count(*) INTO v_dups FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) f
     WHERE f.source_type = v_inv.source_type
       AND f.source_id = v_inv.source_id
       AND f.document_model = 'NFE'
       AND f.id <> v_inv.id
       AND f.status <> 'CANCELED';
    IF v_dups > 0 THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','FISCAL_DUPLICATE_ACTIVE_DOCUMENT','section','ORIGEM','field','source_id',
        'message','Ja existe documento fiscal ativo para esta origem.',
        'action','Cancelar ou reaproveitar o documento existente.');
    END IF;
  END IF;

  -- 8) Pré-requisito externo: certificado de homologação para transmitir.
  IF NOT EXISTS (
    SELECT 1 FROM (SELECT * FROM public.fiscal_certificates WHERE public.h15_company_access(company_settings_id)) fc
     JOIN (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) cs ON cs.id = fc.company_settings_id
    WHERE fc.environment = 'HOMOLOGATION' AND fc.is_active AND fc.status = 'AVAILABLE'
  ) THEN
    v_warnings := v_warnings || jsonb_build_object(
      'code','EXTERNAL_PREREQUISITE_MISSING','section','CERTIFICADO','field','certificate',
      'message','Certificado de homologacao indisponivel: transmissao nao pode ser executada.',
      'action','Provisionar certificado A1 de homologacao antes do smoke SEFAZ.');
  END IF;

  RETURN jsonb_build_object(
    'invoiceId', p_invoice_id,
    'preflightVersion', 'h7k-v1',
    'environment', coalesce(v_env, 'UNKNOWN'),
    'status', CASE WHEN jsonb_array_length(v_blockers) > 0 THEN 'BLOCKED'
                   WHEN jsonb_array_length(v_warnings) > 0 THEN 'READY_WITH_PREREQUISITES'
                   ELSE 'READY' END,
    'canTransmit', (jsonb_array_length(v_blockers) = 0 AND jsonb_array_length(v_warnings) = 0),
    'blockers', v_blockers,
    'warnings', v_warnings,
    'fields', (
      SELECT coalesce(jsonb_object_agg(f.field, f.msgs), '{}'::jsonb)
        FROM (
          SELECT b->>'field' AS field, jsonb_agg(b->>'message') AS msgs
            FROM jsonb_array_elements(v_blockers) b
           WHERE b->>'field' IS NOT NULL
           GROUP BY b->>'field'
        ) f
    ),
    'itemsTotal', v_sum,
    'documentTotal', v_inv.total_amount,
    'toleranceBRL', v_tolerance,
    'evaluatedAt', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._assert_visita_editavel(p_registro_id uuid)
 RETURNS registros_consultor
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_ok boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_reg FROM public.registros_consultor WHERE id = p_registro_id;
  IF v_reg.id IS NULL THEN RAISE EXCEPTION 'registro_nao_encontrado' USING ERRCODE = 'P0002'; END IF;

  v_ok := COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false)
       OR COALESCE(v_reg.created_by = v_uid, false)
       OR COALESCE(v_reg.consultor_responsavel = v_uid, false)
       OR COALESCE(public.is_active_visit_participant(v_uid, p_registro_id), false);

  IF v_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_technical_visit_editable_status(v_reg.status::text) THEN
    RAISE EXCEPTION 'visita_nao_editavel' USING ERRCODE = '42501';
  END IF;

  RETURN v_reg;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.c1b_catalog_visibility_scope(p_partner uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v_owner uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 v_actor := platform_private.h15_actor_organization();
 IF v_actor IS NULL AND NOT public.is_platform_superadmin(auth.uid()) THEN
  RAISE EXCEPTION 'catalog_actor_unavailable' USING ERRCODE='42501'; END IF;
 IF p_partner IS NULL THEN
  SELECT o.partner_account_id INTO p_partner FROM public.organizations o WHERE o.id=v_actor;
 END IF;
 IF p_partner IS NOT NULL THEN
  SELECT pa.commercial_owner_organization_id INTO v_owner FROM public.partner_accounts pa
   JOIN public.organizations o ON o.id=pa.commercial_owner_organization_id AND o.ativo IS TRUE AND o.status='ativa'
   WHERE pa.id=p_partner AND pa.ativo IS TRUE AND pa.deleted_at IS NULL;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'catalog_commercial_owner_unavailable' USING ERRCODE='42501'; END IF;
 END IF;
 IF v_actor IS NULL AND v_owner IS NULL THEN RAISE EXCEPTION 'catalog_scope_unavailable' USING ERRCODE='42501'; END IF;
 RETURN array_remove(ARRAY[v_actor,v_owner],NULL);
END $function$

CREATE OR REPLACE FUNCTION platform_private.catalog_b2b_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.operation = 'set_global_b2b_enabled' OR NEW.operation = 'set_global_b2b_enabled' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_b2b_audit_immutable';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public._comunicacao_build_snapshot(_event_key text, _source_id uuid, _payload jsonb, _user_id uuid, _cliente_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_codigo_os text; v_data_prevista text; v_nome_dest text;
  v_titulo text; v_mensagem text; v_target_role text;
BEGIN
  IF _user_id IS NOT NULL THEN
    SELECT nome INTO v_nome_dest FROM public.profiles WHERE user_id = _user_id LIMIT 1;
  ELSIF _cliente_id IS NOT NULL THEN
    SELECT nome INTO v_nome_dest FROM public.clientes WHERE id = _cliente_id LIMIT 1;
  END IF;
  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    SELECT o.numero_os, to_char(o.data_programada, 'DD/MM/YYYY')
      INTO v_codigo_os, v_data_prevista
      FROM public.ordens_servico o WHERE o.id = _source_id;
    RETURN jsonb_build_object(
      'nome_destinatario', COALESCE(v_nome_dest,''),
      'codigo_os', COALESCE(v_codigo_os,''),
      'data_prevista', COALESCE(v_data_prevista,'')
    );
  END IF;
  IF _event_key = 'administrative_important_update' THEN
    v_titulo := left(COALESCE(_payload ->> 'titulo',''), 200);
    v_mensagem := left(COALESCE(_payload ->> 'mensagem',''), 2000);
    v_target_role := _payload ->> 'target_role';
    RETURN jsonb_build_object(
      'nome_destinatario', COALESCE(v_nome_dest,''),
      'titulo', v_titulo, 'mensagem', v_mensagem,
      'target_role', COALESCE(v_target_role,'')
    );
  END IF;
  RETURN '{}'::jsonb;
END$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_tax_preview_v1(p_invoice_id uuid, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  inv public.fiscal_invoices%ROWTYPE;
  emit public.company_fiscal_settings%ROWTYPE;
  dest public.customer_fiscal_profiles%ROWTYPE;
  it record; ov jsonb; rule public.fiscal_tax_rules%ROWTYPE;
  ctx jsonb; res jsonb; item_taxes jsonb; out_items jsonb := '[]'::jsonb;
  ref_date date; kinds text[]; k text;
  v_prod numeric; v_icms_own numeric; v_ipi numeric; v_base_st numeric; v_st_val numeric;
  v_inputs jsonb; v_manual text;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(p_invoice_id);

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.fn_fiscal_can_operate() THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao para simular tributos.' USING ERRCODE = '42501';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'items_array_required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO inv FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: %', p_invoice_id; END IF;
  IF inv.document_model IS DISTINCT FROM 'NFE' THEN
    RAISE EXCEPTION 'FISCAL_MODEL_UNSUPPORTED: preview de servicos ainda indisponivel.';
  END IF;
  IF inv.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_DRAFT: preview disponivel apenas em rascunho (status=%)', inv.status;
  END IF;

  SELECT * INTO emit FROM (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EMITTER_NOT_CONFIGURED: emitente nao cadastrado.'; END IF;
  IF coalesce(emit.nfe_environment_code,'2') = '1' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_BLOCKED: ambiente de producao bloqueado.';
  END IF;

  SELECT * INTO dest FROM public.customer_fiscal_profiles WHERE customer_id = inv.customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_RECIPIENT_PROFILE_MISSING: perfil fiscal do destinatario nao cadastrado.'; END IF;

  ref_date := coalesce(inv.issue_date, current_date);

  FOR it IN SELECT * FROM (SELECT * FROM public.fiscal_invoice_items WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_invoice_items WHERE fiscal_invoice_id = p_invoice_id ORDER BY item_sequence
  LOOP
    SELECT e INTO ov FROM jsonb_array_elements(p_items) e
     WHERE (e->>'item_sequence')::int = it.item_sequence LIMIT 1;

    v_inputs := coalesce(ov->'tax_input_snapshot', it.tax_input_snapshot, '{}'::jsonb);
    IF NOT public.fn_fiscal_tax_input_valid(v_inputs) THEN
      RAISE EXCEPTION 'tax_input_snapshot_invalid:%', it.item_sequence USING ERRCODE = '22023';
    END IF;

    v_prod := public.fn_fiscal_round(coalesce(
      nullif(ov->>'gross_value','')::numeric,
      it.gross_value, it.quantity * it.unit_value));

    res := public.fn_fiscal_compute_item_taxes_v1(
      emit, dest, coalesce(inv.direction,'OUT'), inv.sales_channel, ref_date, it.ncm_snapshot,
      v_prod,
      public.fn_fiscal_round(coalesce(nullif(ov->>'discount_value','')::numeric, it.discount_value, 0)),
      public.fn_fiscal_round(coalesce(it.freight_value,0)),
      public.fn_fiscal_round(coalesce(it.insurance_value,0)),
      public.fn_fiscal_round(coalesce(it.other_value,0)),
      v_inputs, auth.uid());
    item_taxes := res->'taxes';

    out_items := out_items || jsonb_build_object(
      'itemSequence', it.item_sequence,
      'description', it.description,
      'taxOrder', res->'taxOrder',
      'policy', res->'policy',
      'chained', res->'chained',
      'itemTotals', res->'itemTotals',
      'components', jsonb_build_object(
        'produto', v_prod,
        'desconto', public.fn_fiscal_round(coalesce(nullif(ov->>'discount_value','')::numeric, it.discount_value, 0)),
        'frete', public.fn_fiscal_round(coalesce(it.freight_value,0)),
        'seguro', public.fn_fiscal_round(coalesce(it.insurance_value,0)),
        'outras', public.fn_fiscal_round(coalesce(it.other_value,0))),
      'taxes', item_taxes);
  END LOOP;

  RETURN jsonb_build_object(
    'engineVersion','F3.4',
    'preview', true,
    'persisted', false,
    'items', out_items);
END $function$

CREATE OR REPLACE FUNCTION platform_private.read_global_b2b_state_core(p_item_tipo text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_out jsonb;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_item_tipo IS NULL OR p_item_tipo NOT IN ('produto','microrganismo') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_b2b_invalid'; END IF;
  IF p_item_tipo='produto' THEN
    SELECT pg_catalog.jsonb_build_object('item_tipo','produto','id',p.id,'nome',p.nome,'codigo',p.codigo,
      'ativo',COALESCE(p.ativo,false),'b2b_enabled',p.b2b_enabled,'updated_at',p.updated_at)
      INTO v_out FROM public.produtos p WHERE p.id=p_id;
  ELSE
    SELECT pg_catalog.jsonb_build_object('item_tipo','microrganismo','id',m.id,'nome',m.nome,'codigo',m.codigo,
      'ativo',m.ativo,'b2b_enabled',m.b2b_enabled,'updated_at',m.updated_at)
      INTO v_out FROM public.microrganismos m WHERE m.id=p_id;
  END IF;
  IF v_out IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_b2b_unavailable'; END IF;
  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.set_global_b2b_enabled_core(p_item_tipo text, p_id uuid, p_expected_updated_at timestamp with time zone, p_b2b_enabled boolean, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid:=gen_random_uuid();
  v_op public.produtos%ROWTYPE; v_np public.produtos%ROWTYPE;
  v_om public.microrganismos%ROWTYPE; v_nm public.microrganismos%ROWTYPE;
  v_old jsonb; v_new jsonb; v_old_ativo boolean; v_old_b2b boolean; v_old_ver timestamptz; v_new_ver timestamptz;
  v_vols_before jsonb; v_vols_after jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_item_tipo IS NULL OR p_item_tipo NOT IN ('produto','microrganismo') OR p_id IS NULL OR p_b2b_enabled IS NULL
    OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_b2b_invalid'; END IF;
  v_req:=pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'id',p_id,'expected_updated_at',p_expected_updated_at,
    'b2b_enabled',p_b2b_enabled,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  -- Motivo/chave validados e replay autorizado ANTES de qualquer efeito (lock por chave).
  v_replay:=platform_private.catalog_entity_replay(v_actor,'set_global_b2b_enabled',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  -- Serialização por item (mesmo lock de linha usado pelos writers de status/apresentações).
  IF p_item_tipo='produto' THEN
    SELECT * INTO v_op FROM public.produtos WHERE id=p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_b2b_unavailable'; END IF;
    v_old:=pg_catalog.to_jsonb(v_op); v_old_ativo:=COALESCE(v_op.ativo,false); v_old_b2b:=v_op.b2b_enabled; v_old_ver:=v_op.updated_at;
  ELSE
    SELECT * INTO v_om FROM public.microrganismos WHERE id=p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_b2b_unavailable'; END IF;
    v_old:=pg_catalog.to_jsonb(v_om); v_old_ativo:=v_om.ativo; v_old_b2b:=v_om.b2b_enabled; v_old_ver:=v_om.updated_at;
  END IF;
  IF v_old_ver IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_b2b_conflict'; END IF;
  IF v_old_b2b = p_b2b_enabled THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_b2b_no_change'; END IF;
  IF p_b2b_enabled AND NOT v_old_ativo THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_b2b_requires_active'; END IF;

  -- Apresentações do item: provamos que não mudam (sem sync de preço disparado aqui).
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(cv) ORDER BY cv.id),'[]'::jsonb) INTO v_vols_before
    FROM public.catalogo_volumes cv
   WHERE (p_item_tipo='produto' AND cv.produto_id=p_id) OR (p_item_tipo='microrganismo' AND cv.microrganismo_id=p_id);

  IF p_item_tipo='produto' THEN
    UPDATE public.produtos SET b2b_enabled=p_b2b_enabled WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_np;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_b2b_confirmation_failed'; END IF;
    v_new:=pg_catalog.to_jsonb(v_np); v_new_ver:=v_np.updated_at;
  ELSE
    UPDATE public.microrganismos SET b2b_enabled=p_b2b_enabled WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_nm;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_b2b_confirmation_failed'; END IF;
    v_new:=pg_catalog.to_jsonb(v_nm); v_new_ver:=v_nm.updated_at;
  END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(cv) ORDER BY cv.id),'[]'::jsonb) INTO v_vols_after
    FROM public.catalogo_volumes cv
   WHERE (p_item_tipo='produto' AND cv.produto_id=p_id) OR (p_item_tipo='microrganismo' AND cv.microrganismo_id=p_id);

  -- Confirmação: somente b2b_enabled/updated_at mudaram; versão estritamente crescente.
  -- (produtos usa update_updated_at_column = now(); se a versão não cresce, falha fechada.)
  IF (v_new->>'b2b_enabled')::boolean IS DISTINCT FROM p_b2b_enabled
    OR v_new_ver IS NULL OR v_new_ver <= v_old_ver
    OR (v_old - ARRAY['b2b_enabled','updated_at']) IS DISTINCT FROM (v_new - ARRAY['b2b_enabled','updated_at'])
    OR v_vols_before IS DISTINCT FROM v_vols_after THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_b2b_confirmation_failed'; END IF;

  v_receipt:=pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'id',p_id,'ativo',v_old_ativo,'b2b_enabled',p_b2b_enabled,
    'updated_at',v_new_ver,'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_b2b_enabled',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'id',p_id,'ativo',v_old_ativo,'b2b_enabled',v_old_b2b,'updated_at',v_old_ver),
    pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'id',p_id,'ativo',v_old_ativo,'b2b_enabled',p_b2b_enabled,'updated_at',v_new_ver));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public._comunicacao_can_deliver(_user_id uuid, _cliente_id uuid, _canal comunicacao_canal)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p public.comunicacao_preferencias%rowtype;
BEGIN
  IF _user_id IS NOT NULL THEN
    SELECT * INTO p FROM public.comunicacao_preferencias WHERE user_id = _user_id AND canal = _canal;
  ELSIF _cliente_id IS NOT NULL THEN
    SELECT * INTO p FROM public.comunicacao_preferencias WHERE cliente_id = _cliente_id AND canal = _canal;
  ELSE
    RETURN false;
  END IF;
  IF _canal = 'in_app' THEN RETURN COALESCE(p.enabled, true); END IF;
  IF NOT COALESCE(p.enabled, true) THEN RETURN false; END IF;
  IF _canal = 'whatsapp' AND p.whatsapp_opt_out_at IS NOT NULL THEN RETURN false; END IF;
  IF _canal = 'whatsapp' AND (p.whatsapp_opt_in_at IS NULL OR NOT COALESCE(p.telefone_verificado,false)) THEN
    RETURN false;
  END IF;
  IF _canal = 'email' AND NOT COALESCE(p.email_verificado,false) THEN RETURN false; END IF;
  IF _canal = 'push' AND _user_id IS NULL THEN RETURN false; END IF;
  RETURN true;
END$function$

CREATE OR REPLACE FUNCTION public.platform_finish_admin_access(p_actor_id uuid, p_invite_id uuid, p_operation_id uuid, p_lease_token uuid, p_outcome text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE;
BEGIN
 PERFORM platform_private.require_service_role();
 IF NOT public.is_platform_superadmin(p_actor_id) OR p_outcome NOT IN ('completed','failed','ambiguous') THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id FOR UPDATE;
 IF j.access_operation_id IS DISTINCT FROM p_operation_id OR j.lease_token IS DISTINCT FROM p_lease_token OR j.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'stale_lease' USING ERRCODE='55P03'; END IF;
 UPDATE public.platform_org_admin_invites SET access_operation_status=p_outcome,lease_token=NULL,lease_expires_at=NULL,access_expires_at=CASE WHEN j.access_operation_kind='temporary_password' THEN now()+interval '24 hours' ELSE NULL END,access_valid_after=CASE WHEN j.access_operation_kind='temporary_password' AND p_outcome='completed' THEN clock_timestamp() ELSE access_valid_after END,email_last_attempt_at=CASE WHEN j.access_operation_kind='password_link' THEN j.access_requested_at ELSE email_last_attempt_at END,email_next_attempt_at=j.access_requested_at+interval '5 minutes',email_accepted_at=CASE WHEN j.access_operation_kind='password_link' AND p_outcome='completed' THEN now() ELSE email_accepted_at END,updated_at=now() WHERE id=j.id;
 INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,new_values) VALUES(j.organization_id,j.user_id,j.id,p_actor_id,CASE WHEN p_outcome='completed' THEN 'access_completed' ELSE 'access_failed' END,CASE WHEN p_outcome='completed' THEN 'succeeded' ELSE 'failed' END,'Gestão segura de acesso','platform_invite_org_admin',p_operation_id,jsonb_build_object('kind',j.access_operation_kind,'outcome',p_outcome));
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION platform_private.catalog_family_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.operation = 'set_global_product_family' OR NEW.operation = 'set_global_product_family' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_family_audit_immutable';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_family_label_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.classe_catalogo IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.classe_catalogo IS NOT DISTINCT FROM OLD.classe_catalogo
     AND NEW.familia_catalogo IS NOT DISTINCT FROM OLD.familia_catalogo THEN
    RETURN NEW;
  END IF;
  IF NEW.familia_catalogo IS NULL
     OR NOT platform_private.catalog_family_label_check(NEW.familia_catalogo, NEW.classe_catalogo) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'catalog_label_not_active';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_audit_base_reduction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid;
  v_old jsonb := coalesce(CASE WHEN TG_OP = 'UPDATE' THEN OLD.tax_input_snapshot END, '{}'::jsonb);
  v_new jsonb := coalesce(NEW.tax_input_snapshot, '{}'::jsonb);
  v_snap jsonb := coalesce(NEW.tax_snapshot, '{}'::jsonb);
  v_taxes jsonb;
  v_kind text;
  v_oldpct jsonb;
  v_newpct jsonb;
  v_tax jsonb;
BEGIN
  BEGIN v_actor := auth.uid(); EXCEPTION WHEN OTHERS THEN v_actor := NULL; END;

  v_taxes := v_snap->'taxes';
  IF v_taxes IS NULL OR jsonb_typeof(v_taxes) <> 'object' THEN
    v_taxes := '{}'::jsonb;
  END IF;

  -- Materializacao do calculo: registra a reducao efetivamente aplicada, com a
  -- regra, a versao e o fundamento legal vindos do snapshot REAL.
  IF TG_OP = 'UPDATE' AND NEW.tax_snapshot IS DISTINCT FROM OLD.tax_snapshot THEN
    FOR v_kind IN SELECT jsonb_object_keys(v_taxes) LOOP
      v_tax := coalesce(v_taxes -> v_kind, '{}'::jsonb);
      CONTINUE WHEN coalesce((v_tax->>'baseReductionPct')::numeric, 0) = 0;
      INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values, new_values)
      VALUES (
        'fiscal_invoice_items', NEW.id, 'BASE_REDUCTION_APPLIED', v_actor,
        jsonb_build_object('taxKind', v_kind,
          'baseReductionPct', (coalesce(OLD.tax_snapshot,'{}'::jsonb)->'taxes'->v_kind->>'baseReductionPct')),
        jsonb_build_object(
          'taxKind', v_kind,
          'baseReductionPct', v_tax->>'baseReductionPct',
          'reason', coalesce(v_tax->>'baseReductionReason', v_new -> v_kind ->> 'baseReductionReason'),
          'fiscalInvoiceId', NEW.fiscal_invoice_id,
          'itemId', NEW.id,
          'changedAt', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SSZ'),
          'appliedBy', v_tax->>'baseReductionAppliedBy',
          'appliedAt', v_tax->>'baseReductionAppliedAt',
          'ruleId', v_tax->>'ruleId',
          'ruleKey', v_tax->>'ruleKey',
          'ruleVersion', v_tax->>'ruleVersion',
          'legalBasis', v_tax->>'legalBasis',
          'legalVersion', v_tax->>'legalVersion',
          'baseReductionMode', v_tax->>'baseReductionMode',
          'baseReductionSource', v_tax->>'baseReductionSource'));
    END LOOP;
  END IF;

  IF v_old = v_new THEN RETURN NEW; END IF;

  FOR v_kind IN
    SELECT DISTINCT k FROM (
      SELECT jsonb_object_keys(v_old) AS k
      UNION SELECT jsonb_object_keys(v_new)
    ) s
  LOOP
    v_oldpct := v_old -> v_kind -> 'baseReductionPct';
    v_newpct := v_new -> v_kind -> 'baseReductionPct';
    CONTINUE WHEN v_oldpct IS NOT DISTINCT FROM v_newpct;

    v_tax := coalesce(v_taxes -> v_kind, '{}'::jsonb);

    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values, new_values)
    VALUES (
      'fiscal_invoice_items', NEW.id, 'BASE_REDUCTION_CHANGE', v_actor,
      jsonb_build_object(
        'taxKind', v_kind,
        'baseReductionPct', v_oldpct,
        'reason', v_old -> v_kind ->> 'baseReductionReason'),
      jsonb_build_object(
        'taxKind', v_kind,
        'baseReductionPct', v_newpct,
        'reason', v_new -> v_kind ->> 'baseReductionReason',
        'fiscalInvoiceId', NEW.fiscal_invoice_id,
        'itemId', NEW.id,
        'changedAt', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SSZ'),
        'ruleId', v_tax->>'ruleId',
        'ruleKey', v_tax->>'ruleKey',
        'ruleVersion', v_tax->>'ruleVersion',
        'legalBasis', v_tax->>'legalBasis',
        'legalVersion', v_tax->>'legalVersion',
        'baseReductionMode', v_tax->>'baseReductionMode'
      )
    );
  END LOOP;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._validate_planning_integrity(p_partner_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_ready boolean;
  v_n_items int;
  v_bad_qty int;
BEGIN
  SELECT status::text, ready_for_production INTO v_status, v_ready
  FROM public.partner_orders WHERE id = p_partner_order_id;

  IF v_status IS NULL THEN RAISE EXCEPTION 'order_not_found'; END IF;
  IF v_status <> 'aprovado' OR v_ready IS NOT TRUE THEN RAISE EXCEPTION 'order_not_approved'; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE COALESCE(quantidade,0) <= 0)
    INTO v_n_items, v_bad_qty
  FROM public.partner_order_items WHERE order_id = p_partner_order_id;

  IF v_n_items = 0 THEN RAISE EXCEPTION 'no_items'; END IF;
  IF v_bad_qty > 0 THEN RAISE EXCEPTION 'invalid_quantity'; END IF;
END
$function$

CREATE OR REPLACE FUNCTION platform_private.set_global_product_family_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_familia text, p_classe text, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid := gen_random_uuid();
  v_op public.produtos%ROWTYPE; v_np public.produtos%ROWTYPE; v_old jsonb; v_new jsonb;
  v_vols_before jsonb; v_vols_after jsonb; v_classe text := NULLIF(pg_catalog.btrim(COALESCE(p_classe,'')), '');
BEGIN
  v_actor := platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) OR p_idempotency_key IS NULL
     OR p_familia IS NULL OR p_familia NOT IN ('biologico','quimico','fertilizante_adubo') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_family_invalid';
  END IF;
  v_req := pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,
    'familia_catalogo',p_familia,'classe_catalogo',v_classe,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  v_replay := platform_private.catalog_entity_replay(v_actor,'set_global_product_family',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  -- Revalidação mutante APÓS o replay: só nova execução exige rótulo ativo (com lock).
  IF NOT (v_classe IS NULL OR platform_private.catalog_family_label_check(p_familia, v_classe)) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_family_invalid';
  END IF;

  SELECT * INTO v_op FROM public.produtos WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_family_unavailable'; END IF;
  IF v_op.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_family_conflict'; END IF;
  IF v_op.familia_catalogo IS NOT DISTINCT FROM p_familia AND v_op.classe_catalogo IS NOT DISTINCT FROM v_classe THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_family_no_change'; END IF;
  v_old := pg_catalog.to_jsonb(v_op);
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(cv) ORDER BY cv.id),'[]'::jsonb) INTO v_vols_before
    FROM public.catalogo_volumes cv WHERE cv.produto_id=p_id;

  UPDATE public.produtos SET familia_catalogo=p_familia, classe_catalogo=v_classe
   WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_np;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_family_confirmation_failed'; END IF;
  v_new := pg_catalog.to_jsonb(v_np);
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(cv) ORDER BY cv.id),'[]'::jsonb) INTO v_vols_after
    FROM public.catalogo_volumes cv WHERE cv.produto_id=p_id;
  -- Somente família/classe/versão mudam (ativo, B2B, preços, dose, tipo, código, owner intactos).
  IF v_np.familia_catalogo IS DISTINCT FROM p_familia OR v_np.classe_catalogo IS DISTINCT FROM v_classe
     OR v_np.updated_at IS NULL OR v_np.updated_at <= v_op.updated_at
     OR (v_old - ARRAY['familia_catalogo','classe_catalogo','updated_at']) IS DISTINCT FROM (v_new - ARRAY['familia_catalogo','classe_catalogo','updated_at'])
     OR v_vols_before IS DISTINCT FROM v_vols_after THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_family_confirmation_failed'; END IF;

  v_receipt := pg_catalog.jsonb_build_object('id',p_id,'familia_catalogo',p_familia,'classe_catalogo',v_classe,
    'updated_at',v_np.updated_at,'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_product_family',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('id',p_id,'familia_catalogo',v_op.familia_catalogo,'classe_catalogo',v_op.classe_catalogo,'updated_at',v_op.updated_at),
    pg_catalog.jsonb_build_object('id',p_id,'familia_catalogo',p_familia,'classe_catalogo',v_classe,'updated_at',v_np.updated_at));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.add_b2b_payment_terms_note_secure(p_partner_order_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_terms_id uuid;
BEGIN

  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;
  IF NOT (public.has_role(v_uid,'administrador')
       OR public.has_role(v_uid,'financeiro')
       OR public.has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_note IS NULL OR btrim(p_note) = '' THEN
    RAISE EXCEPTION 'note_required';
  END IF;

  SELECT payment_terms_id INTO v_terms_id FROM public.partner_orders WHERE id = p_partner_order_id;
  IF v_terms_id IS NULL THEN RAISE EXCEPTION 'payment_terms_not_defined'; END IF;

  UPDATE public.partner_order_payment_terms
     SET approval_notes = CASE
       WHEN approval_notes IS NULL OR approval_notes = ''
         THEN p_note
         ELSE approval_notes || E'\n---\n' || p_note
       END,
         updated_at = now()
   WHERE id = v_terms_id;

  INSERT INTO public.partner_order_audit_logs(order_id, acao, usuario_id, dados_novos)
  VALUES (p_partner_order_id, 'payment_terms_note_added', v_uid,
          jsonb_build_object('note', p_note));

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_microorganism_profile_with_audit(p_profile_id uuid, p_checklist jsonb, p_aprovado_sem_fonte boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_micro_id uuid;
  v_b2b_enabled boolean := false;
  v_has_sources boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required';
  END IF;
  IF NOT (
    has_role(v_uid, 'administrador'::app_role)
    OR has_role(v_uid, 'gestor'::app_role)
    OR has_role(v_uid, 'consultor_tecnico'::app_role)
    OR has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT microrganismo_id INTO v_micro_id FROM microorganism_technical_profiles WHERE id = p_profile_id;
  IF v_micro_id IS NULL THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  SELECT COALESCE(b2b_enabled, false) INTO v_b2b_enabled FROM microrganismos WHERE id = v_micro_id;

  SELECT EXISTS(
    SELECT 1 FROM catalog_technical_sources
    WHERE (entidade_tipo = 'microrganismo' AND entidade_id = v_micro_id)
       OR (entidade_tipo = 'ficha_microrganismo' AND entidade_id = p_profile_id)
  ) INTO v_has_sources;

  PERFORM public.validate_catalog_approval_checklist('micro', p_checklist, v_b2b_enabled, v_has_sources, p_aprovado_sem_fonte);

  UPDATE microorganism_technical_profiles
  SET status_validacao = 'aprovado',
      validado_por = v_uid,
      validado_em = now(),
      updated_by = v_uid,
      updated_at = now()
  WHERE id = p_profile_id;

  INSERT INTO catalog_technical_audit_logs (entidade_tipo, entidade_id, acao, usuario_id, dados_novos)
  VALUES (
    'ficha_microrganismo',
    p_profile_id,
    CASE WHEN p_aprovado_sem_fonte THEN 'aprovacao_tecnica_sem_fonte' ELSE 'aprovacao_tecnica' END,
    v_uid,
    jsonb_build_object(
      'checklist_aprovacao', p_checklist,
      'aprovado_por', v_uid,
      'aprovado_em', now(),
      'aprovado_sem_fonte', p_aprovado_sem_fonte
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_b2b_payment_terms_secure(p_partner_order_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_terms_id uuid;
  v_created_by uuid;
  v_numero text;
BEGIN

  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF NOT (public.has_role(v_uid,'administrador')
       OR public.has_role(v_uid,'financeiro')
       OR public.has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  SELECT po.payment_terms_id, po.created_by, po.numero
    INTO v_terms_id, v_created_by, v_numero
  FROM public.partner_orders po
  WHERE po.id = p_partner_order_id;

  IF v_terms_id IS NULL THEN
    RAISE EXCEPTION 'payment_terms_not_defined';
  END IF;

  UPDATE public.partner_order_payment_terms
     SET approval_status = 'approved',
         approved_by = v_uid,
         approved_at = now(),
         approval_notes = COALESCE(p_notes, approval_notes),
         updated_at = now()
   WHERE id = v_terms_id;

  UPDATE public.partner_orders
     SET financial_approval_status = 'approved',
         payment_condition_status = 'approved',
         updated_at = now()
   WHERE id = p_partner_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, acao, usuario_id, dados_novos)
  VALUES (p_partner_order_id, 'payment_terms_approved', v_uid,
          jsonb_build_object('notes', p_notes));

  -- Notifica comercial (criador)
  IF v_created_by IS NOT NULL THEN
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_created_by, 'b2b_payment_terms',
            'Condição financeira aprovada',
            format('Pedido %s teve a condição de pagamento aprovada.', COALESCE(v_numero,'B2B')),
            '/comercial/pedidos-b2b');
  END IF;

  RETURN jsonb_build_object('success', true, 'status', 'approved');
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_product_profile_with_audit(p_profile_id uuid, p_checklist jsonb, p_aprovado_sem_fonte boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_prod_id uuid;
  v_b2b_enabled boolean := false;
  v_has_sources boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required';
  END IF;
  IF NOT (
    has_role(v_uid, 'administrador'::app_role)
    OR has_role(v_uid, 'gestor'::app_role)
    OR has_role(v_uid, 'consultor_tecnico'::app_role)
    OR has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT produto_id INTO v_prod_id FROM product_technical_profiles WHERE id = p_profile_id;
  IF v_prod_id IS NULL THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  SELECT COALESCE(b2b_enabled, false) INTO v_b2b_enabled FROM produtos WHERE id = v_prod_id;

  SELECT EXISTS(
    SELECT 1 FROM catalog_technical_sources
    WHERE (entidade_tipo = 'produto' AND entidade_id = v_prod_id)
       OR (entidade_tipo = 'ficha_produto' AND entidade_id = p_profile_id)
  ) INTO v_has_sources;

  PERFORM public.validate_catalog_approval_checklist('produto', p_checklist, v_b2b_enabled, v_has_sources, p_aprovado_sem_fonte);

  UPDATE product_technical_profiles
  SET status_validacao = 'aprovado',
      validado_por = v_uid,
      validado_em = now(),
      updated_by = v_uid,
      updated_at = now()
  WHERE id = p_profile_id;

  INSERT INTO catalog_technical_audit_logs (entidade_tipo, entidade_id, acao, usuario_id, dados_novos)
  VALUES (
    'ficha_produto',
    p_profile_id,
    CASE WHEN p_aprovado_sem_fonte THEN 'aprovacao_tecnica_sem_fonte' ELSE 'aprovacao_tecnica' END,
    v_uid,
    jsonb_build_object(
      'checklist_aprovacao', p_checklist,
      'aprovado_por', v_uid,
      'aprovado_em', now(),
      'aprovado_sem_fonte', p_aprovado_sem_fonte
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_partner_order(p_order_id uuid, p_approval_notes text DEFAULT NULL::text, p_estimated_delivery_date date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_pid uuid; v_prev partner_order_status; v_partner_user uuid; v_numero text;
  v_final_status partner_order_status; v_final_ready boolean; v_block text;
  v_amount numeric(14,2); v_credit_ok timestamptz; v_credit jsonb; v_reason text;
BEGIN

  IF NOT (public.b2b_phase1_order_visible(p_order_id) OR EXISTS (
    SELECT 1 FROM public.partner_orders po WHERE po.id=p_order_id
      AND platform_private.c2p1_settings_allowed(po.partner_id,true))) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT partner_id, status, numero,
         ROUND(COALESCE(final_amount_with_interest, total, 0),2), credit_approved_at
    INTO v_pid, v_prev, v_numero, v_amount, v_credit_ok
    FROM public.partner_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
  IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_order_id AND c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1') THEN RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501'; END IF;

  IF v_prev = 'aguardando_cotacao' THEN
    RAISE EXCEPTION 'quote_required: defina o preco da cotacao antes de aprovar';
  END IF;
  IF NOT public.fn_b2b_order_priceable(p_order_id) THEN
    RAISE EXCEPTION 'order_not_priceable_quote_required';
  END IF;

  IF v_prev IN ('aprovado','reprovado','cancelado') THEN
    RAISE EXCEPTION 'already_processed: pedido já está em status %', v_prev;
  END IF;

  IF v_prev = 'aguardando_aprovacao_credito' THEN
    RAISE EXCEPTION 'credit_pending: aprove o crédito antes da análise comercial';
  END IF;

  IF v_prev NOT IN ('em_analise_comercial','solicitado','rascunho') THEN
    RAISE EXCEPTION 'invalid_status_transition: %', v_prev;
  END IF;

  -- H4-001/H4-003: reavaliar credito na aprovacao, com lock por parceiro.
  -- C2 single credit lock domain: same bigint key as create_partner_order_secure and tg_partner_orders_credit_guard.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || v_pid::text, 0));
  -- Re-validate authority after a possible wait (READ COMMITTED: each statement sees revocations committed meanwhile).
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF NOT (public.b2b_phase1_order_visible(p_order_id) OR EXISTS (SELECT 1 FROM public.partner_orders po WHERE po.id=p_order_id
      AND platform_private.c2p1_settings_allowed(po.partner_id,true))) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  v_credit := public.fn_b2b_credit_exposure(v_pid, 0, NULL);
  v_reason := COALESCE(v_credit->>'reason_code','OK');

  IF v_credit_ok IS NULL THEN
    IF v_reason IN ('LIMIT_EXCEEDED_BLOCK','OVERDUE_BLOCK') THEN
      UPDATE public.partner_orders
         SET credit_block_reason = v_reason, updated_at = now()
       WHERE id = p_order_id;
      RAISE EXCEPTION 'credit_block_on_approval: %', v_reason;
    ELSIF v_reason = 'LIMIT_EXCEEDED_APPROVAL' THEN
      -- fail-closed: exige aprovacao financeira formal (approve_b2b_credit).
      UPDATE public.partner_orders
         SET credit_block_reason = v_reason, updated_at = now()
       WHERE id = p_order_id;
      RAISE EXCEPTION 'credit_approval_required: %', v_reason;
    END IF;
  END IF;

  UPDATE public.partner_orders
     SET status = 'aprovado', approved_by = v_uid, approved_at = now(),
         approval_notes = NULLIF(p_approval_notes,''),
         estimated_delivery_date = COALESCE(p_estimated_delivery_date, estimated_delivery_date),
         ready_for_production = CASE WHEN c2_external_origin_snapshot IS NOT NULL THEN false ELSE true END, updated_at = now()
   WHERE id = p_order_id AND status = v_prev;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'concurrent_update: status do pedido mudou durante a aprovação';
  END IF;

  SELECT status, ready_for_production, credit_block_reason
    INTO v_final_status, v_final_ready, v_block
    FROM public.partner_orders WHERE id = p_order_id;

  IF v_final_status <> 'aprovado' OR (v_final_ready IS NOT TRUE AND NOT EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_order_id AND c2_external_origin_snapshot IS NOT NULL AND internal_economic_snapshot IS NOT NULL)) THEN
    RAISE EXCEPTION 'credit_block: %', COALESCE(v_block, 'aprovacao_credito_pendente');
  END IF;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'approved',
          jsonb_build_object('status', v_prev),
          jsonb_build_object('status','aprovado','approval_notes',p_approval_notes,
                             'estimated_delivery_date',p_estimated_delivery_date,
                             'credit_reason_code', v_reason));

  FOR v_partner_user IN SELECT r FROM platform_private.c2_order_partner_recipients(v_pid) r LOOP -- c2_ord_recipients
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_partner_user, 'pedido_b2b_aprovado',
            'Pedido ' || v_numero || ' aprovado',
            CASE WHEN EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_order_id AND c2_external_origin_snapshot IS NOT NULL)
            THEN 'Seu pedido recebeu aprovação comercial. Planejamento de produção ainda não liberado.'
            ELSE 'Seu pedido foi aprovado e seguirá para planejamento de produção.' END,
            '/portal-parceiro/pedidos');
  END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION public.aprovar_ficha_versao(p_versao_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_versao public.ficha_tecnica_versoes%ROWTYPE;
  v_sql text;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador') OR public.has_role(auth.uid(), 'gestor')) THEN
    RAISE EXCEPTION 'Sem permissão para aprovar versões';
  END IF;

  SELECT * INTO v_versao FROM public.ficha_tecnica_versoes WHERE id = p_versao_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Versão não encontrada'; END IF;
  IF v_versao.status <> 'pendente' THEN RAISE EXCEPTION 'Versão não está pendente'; END IF;

  -- Aplica ao profile correto
  IF v_versao.entidade_tipo = 'produto' THEN
    v_sql := format(
      'UPDATE public.product_technical_profiles SET %I = $1, updated_at = now() WHERE produto_id = $2',
      v_versao.campo
    );
    EXECUTE v_sql USING v_versao.conteudo_novo, v_versao.entidade_id;
  ELSE
    v_sql := format(
      'UPDATE public.microorganism_technical_profiles SET %I = $1, updated_at = now() WHERE microrganismo_id = $2',
      v_versao.campo
    );
    EXECUTE v_sql USING v_versao.conteudo_novo, v_versao.entidade_id;
  END IF;

  -- Marca anteriores como substituidas
  UPDATE public.ficha_tecnica_versoes
  SET status = 'substituida'
  WHERE entidade_tipo = v_versao.entidade_tipo
    AND entidade_id = v_versao.entidade_id
    AND campo = v_versao.campo
    AND status = 'aprovada';

  UPDATE public.ficha_tecnica_versoes
  SET status = 'aprovada',
      revisado_por = auth.uid(),
      revisado_em = now()
  WHERE id = p_versao_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.catalog_family_labels_read(p_familia text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid := auth.uid(); v_result jsonb;
BEGIN
  IF v_uid IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id = v_uid AND p.ativo = true) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_label_read_forbidden';
  END IF;
  IF p_familia IS NULL OR p_familia NOT IN ('biologico','quimico','fertilizante_adubo') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_family_invalid';
  END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'familia', l.familia, 'rotulo', l.rotulo, 'rotulo_exibicao', l.rotulo_exibicao)
    ORDER BY pg_catalog.lower(l.rotulo_exibicao) COLLATE "C", l.id), '[]'::jsonb)
  INTO v_result
  FROM public.catalog_family_labels l
  WHERE l.familia = p_familia AND l.ativo = true;
  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.archive_partner_simulation_secure(p_simulation_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN

  IF NOT public.b2b_phase1_simulation_visible(p_simulation_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Simulação não encontrada'; END IF;
  IF v_sim.status = 'convertida_pedido' THEN RAISE EXCEPTION 'Simulação já convertida em pedido não pode ser arquivada'; END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND v_sim.partner_id = v_partner_id THEN v_allowed := true;
  END IF;
  IF NOT v_allowed THEN RAISE EXCEPTION 'Sem permissão para arquivar esta simulação'; END IF;

  UPDATE partner_simulations SET status = 'arquivada', updated_at = now() WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_sim.partner_id, v_uid, 'simulation_archived',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'arquivada', 'reason', p_reason));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_archived', v_sim.partner_id, v_uid,
    v_sim.cliente_id, p_simulation_id, NULL, NULL,
    jsonb_build_object('reason', p_reason));
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_inserir_alvos(p_kind text, p_parent_id uuid, p_alvos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_item JSONB;
  v_nome TEXT;
  v_tipo TEXT;
  v_prio INT;
  v_desc TEXT;
  v_norm TEXT;
  v_cat_id UUID;
  v_criados INT := 0;
  v_vinculados INT := 0;
  v_ignorados INT := 0;
  v_exists BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  IF NOT (
    public.has_role(v_uid, 'administrador'::app_role)
    OR public.has_role(v_uid, 'gestor'::app_role)
    OR public.has_role(v_uid, 'consultor_tecnico'::app_role)
    OR public.has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para inserir alvos';
  END IF;

  IF p_kind NOT IN ('produto', 'micro') THEN
    RAISE EXCEPTION 'p_kind inválido (use produto ou micro)';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_alvos) LOOP
    v_nome := trim(coalesce(v_item->>'nome', ''));
    v_tipo := coalesce(v_item->>'tipo', 'praga');
    v_prio := coalesce((v_item->>'prioridade')::INT, 5);
    v_desc := NULLIF(trim(coalesce(v_item->>'descricao', '')), '');

    IF v_nome = '' THEN
      v_ignorados := v_ignorados + 1;
      CONTINUE;
    END IF;

    v_norm := public.normalizar_alvo(v_nome);

    -- upsert no catalogo
    INSERT INTO public.catalogo_alvos (nome, nome_normalizado, tipo, descricao, criado_por)
    VALUES (v_nome, v_norm, v_tipo, v_desc, v_uid)
    ON CONFLICT (nome_normalizado, tipo) DO UPDATE SET ativo = true
    RETURNING id INTO v_cat_id;

    IF FOUND AND (SELECT created_at = updated_at FROM public.catalogo_alvos WHERE id = v_cat_id) THEN
      v_criados := v_criados + 1;
    END IF;

    -- evita duplicar na ficha
    IF p_kind = 'produto' THEN
      SELECT EXISTS(
        SELECT 1 FROM public.product_target_recommendations
        WHERE produto_id = p_parent_id AND ativo = true
          AND (catalogo_alvo_id = v_cat_id OR public.normalizar_alvo(alvo_nome) = v_norm)
      ) INTO v_exists;

      IF v_exists THEN
        v_ignorados := v_ignorados + 1;
      ELSE
        INSERT INTO public.product_target_recommendations
          (produto_id, alvo_nome, alvo_tipo, descricao, prioridade, ativo, catalogo_alvo_id)
        VALUES (p_parent_id, v_nome, v_tipo, v_desc, v_prio, true, v_cat_id);
        v_vinculados := v_vinculados + 1;
      END IF;
    ELSE
      SELECT EXISTS(
        SELECT 1 FROM public.microorganism_targets
        WHERE microrganismo_id = p_parent_id AND ativo = true
          AND (catalogo_alvo_id = v_cat_id OR public.normalizar_alvo(alvo_nome) = v_norm)
      ) INTO v_exists;

      IF v_exists THEN
        v_ignorados := v_ignorados + 1;
      ELSE
        INSERT INTO public.microorganism_targets
          (microrganismo_id, alvo_nome, alvo_tipo, descricao, prioridade, ativo, catalogo_alvo_id)
        VALUES (p_parent_id, v_nome, v_tipo, v_desc, v_prio, true, v_cat_id);
        v_vinculados := v_vinculados + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'criados_no_catalogo', v_criados,
    'vinculados', v_vinculados,
    'ignorados', v_ignorados
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_create_catalog_label(p_familia text, p_rotulo text, p_rotulo_exibicao text, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid := gen_random_uuid();
  v_id uuid; v_rotulo text := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_rotulo, '')));
  v_exib text := pg_catalog.btrim(COALESCE(p_rotulo_exibicao, ''));
BEGIN
  v_actor := platform_private.catalog_metadata_require_actor();
  IF p_familia IS NULL OR p_familia NOT IN ('biologico','quimico','fertilizante_adubo')
     OR v_rotulo !~ '^[a-z0-9][a-z0-9_]{1,39}$'
     OR pg_catalog.char_length(v_exib) < 2 OR pg_catalog.char_length(v_exib) > 80
     OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_invalid';
  END IF;
  v_req := pg_catalog.jsonb_build_object('familia', p_familia, 'rotulo', v_rotulo,
    'rotulo_exibicao', v_exib, 'reason', pg_catalog.btrim(COALESCE(p_reason, '')));
  v_replay := platform_private.catalog_entity_replay(v_actor, 'create_catalog_label', v_req, p_reason, p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  INSERT INTO public.catalog_family_labels (familia, rotulo, rotulo_exibicao, created_by)
  VALUES (p_familia, v_rotulo, v_exib, v_actor)
  RETURNING id INTO v_id;

  v_receipt := pg_catalog.jsonb_build_object('id', v_id, 'familia', p_familia, 'rotulo', v_rotulo,
    'rotulo_exibicao', v_exib, 'ativo', true, 'idempotency_key', p_idempotency_key, 'audit_id', v_audit, 'idempotent', false);
  PERFORM platform_private.catalog_entity_audit(v_actor, 'create_catalog_label', p_reason, p_idempotency_key,
    v_req, v_receipt, 'null'::jsonb, v_receipt);
  RETURN v_receipt;
END $function$

CREATE OR REPLACE FUNCTION public.can_user_access_alerta(p_alerta_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_alerta record;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  IF public.has_role(v_uid, 'cliente_produtor'::app_role)
     OR public.has_role(v_uid, 'financeiro'::app_role) THEN
    RETURN false;
  END IF;

  IF public.has_role(v_uid, 'administrador'::app_role)
     OR public.has_role(v_uid, 'gestor'::app_role)
     OR public.has_role(v_uid, 'administrativo'::app_role) THEN
    RETURN true;
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN RETURN false; END IF;

  IF public.has_role(v_uid, 'consultor_tecnico'::app_role)
     OR public.has_role(v_uid, 'tecnico_agronomo'::app_role) THEN
    RETURN v_alerta.consultor_id = v_uid
        OR v_alerta.responsavel_id = v_uid
        OR v_alerta.criado_por = v_uid;
  END IF;

  IF public.has_role(v_uid, 'producao'::app_role)
     OR public.has_role(v_uid, 'operador_onfarm'::app_role) THEN
    RETURN v_alerta.origem IN ('laboratorio','cq','estoque','entrega');
  END IF;

  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_user_access_cliente(_cliente_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_is_admin boolean;
    v_is_gestor boolean;
    v_is_adm_sys boolean;
    v_is_financeiro boolean;
    v_is_comercial boolean;
    v_is_producao boolean;
    v_is_aplicador boolean;
    v_is_onfarm boolean;
    v_is_consultor boolean;
    v_is_tecnico boolean;
    v_is_cliente boolean;
    v_is_b2b boolean;
    v_is_b2b_tec boolean;
    v_partner_id uuid;
BEGIN
    IF v_user_id IS NULL OR _cliente_id IS NULL THEN
        RETURN FALSE;
    END IF;

    v_is_admin := COALESCE(has_role(v_user_id, 'administrador'::app_role), false);
    v_is_gestor := COALESCE(has_role(v_user_id, 'gestor'::app_role), false);
    v_is_adm_sys := COALESCE(has_role(v_user_id, 'administrativo'::app_role), false);
    v_is_financeiro := COALESCE(has_role(v_user_id, 'financeiro'::app_role), false);
    v_is_comercial := COALESCE(has_role(v_user_id, 'gestor_comercial'::app_role), false);
    v_is_producao := COALESCE(has_role(v_user_id, 'producao'::app_role), false);
    v_is_aplicador := COALESCE(has_role(v_user_id, 'aplicador'::app_role), false);
    v_is_onfarm := COALESCE(has_role(v_user_id, 'operador_onfarm'::app_role), false);
    v_is_consultor := COALESCE(has_role(v_user_id, 'consultor_tecnico'::app_role), false);
    v_is_tecnico := COALESCE(has_role(v_user_id, 'tecnico_agronomo'::app_role), false);
    v_is_cliente := COALESCE(has_role(v_user_id, 'cliente_produtor'::app_role), false);
    v_is_b2b := COALESCE(has_role(v_user_id, 'parceiro_b2b'::app_role), false);
    v_is_b2b_tec := COALESCE(has_role(v_user_id, 'parceiro_b2b_tecnico'::app_role), false);

    IF v_is_admin OR v_is_gestor OR v_is_adm_sys OR v_is_financeiro
       OR v_is_comercial OR v_is_producao OR v_is_aplicador OR v_is_onfarm THEN
        RETURN TRUE;
    END IF;

    IF v_is_cliente THEN
        RETURN COALESCE(_cliente_id = ANY(get_cliente_ids_for_user(v_user_id)), false);
    END IF;

    -- HARDENING: carteira ativa e vigente é obrigatória para papéis técnicos.
    IF v_is_consultor OR v_is_tecnico THEN
        RETURN COALESCE(
          public.has_active_user_cliente_access(
            v_user_id, _cliente_id, ARRAY['read','execute','manage']
          ), false);
    END IF;

    IF v_is_b2b_tec THEN
        v_partner_id := public.get_user_partner_id();
        RETURN COALESCE((
          EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.technician_user_id = v_user_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
          )), false);
    END IF;

    IF v_is_b2b THEN
        v_partner_id := public.get_user_partner_id();
        RETURN COALESCE((
          EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
          ) OR EXISTS (
            SELECT 1 FROM public.partner_clients pc
            WHERE pc.cliente_id = _cliente_id
              AND pc.partner_id = v_partner_id
              AND pc.active = true
          )), false);
    END IF;

    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_user_access_estoque_embalagem(p_embalagem_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_cli uuid; v_status text; v_entrega uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  SELECT cliente_id, status, entrega_id INTO v_cli, v_status, v_entrega
    FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF public.has_role(v_uid,'administrador'::app_role)
     OR public.has_role(v_uid,'gestor'::app_role)
     OR public.has_role(v_uid,'producao'::app_role)
     OR public.has_role(v_uid,'operador_onfarm'::app_role)
     OR public.has_role(v_uid,'administrativo'::app_role) THEN
    RETURN true;
  END IF;
  IF public.has_role(v_uid,'financeiro'::app_role) THEN
    RETURN v_entrega IS NOT NULL;
  END IF;
  IF public.has_role(v_uid,'consultor_tecnico'::app_role)
     OR public.has_role(v_uid,'tecnico_agronomo'::app_role) THEN
    RETURN v_cli IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.user_clientes WHERE user_id=v_uid AND cliente_id=v_cli);
  END IF;
  IF public.has_role(v_uid,'cliente_produtor'::app_role) THEN
    RETURN v_status='entregue' AND v_cli IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.user_clientes WHERE user_id=v_uid AND cliente_id=v_cli);
  END IF;
  RETURN false;
END $function$

CREATE OR REPLACE FUNCTION platform_private.catalog_composition_row_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_fam text;
BEGIN
  SELECT p.familia_catalogo INTO v_fam FROM public.produtos p WHERE p.id = NEW.produto_id;
  IF NOT platform_private.catalog_composition_type_allowed(v_fam, NEW.tipo_componente) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='catalog_composition_family_conflict'; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_user_access_produto_etiqueta(p_etiqueta_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cliente_id uuid;
  v_gerada_por uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  -- Perfis internos com acesso total
  IF public.has_role(v_uid,'administrador'::app_role)
     OR public.has_role(v_uid,'gestor'::app_role)
     OR public.has_role(v_uid,'producao'::app_role)
     OR public.has_role(v_uid,'operador_onfarm'::app_role)
     OR public.has_role(v_uid,'administrativo'::app_role)
     OR public.has_role(v_uid,'financeiro'::app_role)
  THEN
    RETURN true;
  END IF;

  SELECT cliente_id, gerada_por
    INTO v_cliente_id, v_gerada_por
    FROM public.produto_etiquetas
   WHERE id = p_etiqueta_id;

  IF NOT FOUND THEN RETURN false; END IF;

  -- Cliente produtor: apenas etiquetas dos seus clientes
  IF public.has_role(v_uid,'cliente_produtor'::app_role) THEN
    IF v_cliente_id IS NULL THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM public.user_clientes uc
       WHERE uc.user_id = v_uid AND uc.cliente_id = v_cliente_id
    );
  END IF;

  -- Consultor/técnico: regra conservadora — apenas se gerada por ele
  -- ou se estiver vinculado ao cliente em user_clientes
  IF public.has_role(v_uid,'consultor_tecnico'::app_role)
     OR public.has_role(v_uid,'tecnico_agronomo'::app_role)
  THEN
    IF v_gerada_por = v_uid THEN RETURN true; END IF;
    IF v_cliente_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.user_clientes uc
       WHERE uc.user_id = v_uid AND uc.cliente_id = v_cliente_id
    ) THEN
      RETURN true;
    END IF;
    RETURN false;
  END IF;

  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_composition_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.operation = 'set_global_product_composition' OR NEW.operation = 'set_global_product_composition' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_composition_audit_immutable'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.set_global_product_composition_core(p_produto_id uuid, p_expected_updated_at timestamp with time zone, p_status text, p_itens jsonb, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid := gen_random_uuid();
  v_op public.produtos%ROWTYPE; v_np public.produtos%ROWTYPE; v_e jsonb; v_i int := 0; v_n int;
  v_before jsonb; v_after jsonb; v_form_before text; v_form_after text; v_vol_before text; v_vol_after text;
  v_old_status text; v_keys text[] := ARRAY['base','componente_nome','microrganismo_id','natureza','ordem','quantidade','tipo_componente','unidade'];
BEGIN
  v_actor := platform_private.catalog_metadata_require_actor();
  IF p_produto_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) OR p_idempotency_key IS NULL
     OR p_status IS NULL OR p_status NOT IN ('rascunho','completo')
     OR p_itens IS NULL OR pg_catalog.jsonb_typeof(p_itens) <> 'array' OR pg_catalog.jsonb_array_length(p_itens) > 50
     OR (p_status = 'completo' AND pg_catalog.jsonb_array_length(p_itens) = 0) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_invalid'; END IF;
  -- Formato estrito de cada item (chaves exatas, tipos JSON, ordem 1..n sequencial). Valores finais validados pelos CHECKs.
  FOR v_e IN SELECT e FROM pg_catalog.jsonb_array_elements(p_itens) e LOOP
    v_i := v_i + 1;
    IF pg_catalog.jsonb_typeof(v_e) <> 'object'
       OR (SELECT pg_catalog.array_agg(k ORDER BY k) FROM pg_catalog.jsonb_object_keys(v_e) k) IS DISTINCT FROM v_keys
       OR pg_catalog.jsonb_typeof(v_e->'ordem') <> 'number' OR (v_e->>'ordem') <> v_i::text
       OR pg_catalog.jsonb_typeof(v_e->'quantidade') NOT IN ('number','null')
       OR pg_catalog.jsonb_typeof(v_e->'tipo_componente') <> 'string' OR pg_catalog.jsonb_typeof(v_e->'natureza') <> 'string'
       OR pg_catalog.jsonb_typeof(v_e->'microrganismo_id') NOT IN ('string','null')
       OR pg_catalog.jsonb_typeof(v_e->'componente_nome') NOT IN ('string','null')
       OR pg_catalog.jsonb_typeof(v_e->'unidade') NOT IN ('string','null') OR pg_catalog.jsonb_typeof(v_e->'base') NOT IN ('string','null')
       OR (v_e->>'microrganismo_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND v_e->>'microrganismo_id' IS NOT NULL
       OR (p_status = 'completo' AND v_e->>'quantidade' IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_invalid'; END IF;
    -- No máximo 6 casas decimais (numeric(24,6) arredondaria silenciosamente).
    IF v_e->>'quantidade' IS NOT NULL AND pg_catalog.scale((v_e->>'quantidade')::numeric) > 6 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_invalid'; END IF;
  END LOOP;
  v_req := pg_catalog.jsonb_build_object('produto_id',p_produto_id,'expected_updated_at',p_expected_updated_at,'status',p_status,
    'itens',p_itens,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  v_replay := platform_private.catalog_entity_replay(v_actor,'set_global_product_composition',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  SELECT * INTO v_op FROM public.produtos WHERE id = p_produto_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_composition_unavailable'; END IF;
  IF v_op.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_composition_conflict'; END IF;
  IF v_op.familia_catalogo IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_requires_family'; END IF;

  -- Família transacional (após lock) e regras cruzadas com a receita.
  FOR v_e IN SELECT e FROM pg_catalog.jsonb_array_elements(p_itens) e LOOP
    IF NOT platform_private.catalog_composition_type_allowed(v_op.familia_catalogo, v_e->>'tipo_componente') THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='catalog_composition_family_conflict'; END IF;
    IF v_e->>'tipo_componente' = 'microrganismo' THEN
      -- Nova associação exige micro ativo; micro já declarado (mesmo arquivado depois) pode ser mantido.
      IF NOT EXISTS (SELECT 1 FROM public.microrganismos m WHERE m.id = (v_e->>'microrganismo_id')::uuid
          AND (m.ativo OR EXISTS (SELECT 1 FROM public.produto_composicao_declaracoes d
                 WHERE d.produto_id = p_produto_id AND d.microrganismo_id = m.id))) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_micro_unavailable'; END IF;
      IF EXISTS (SELECT 1 FROM public.formulacoes f WHERE f.produto_id = p_produto_id
          AND f.microrganismo_id = (v_e->>'microrganismo_id')::uuid AND f.concentracao IS NOT NULL) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='catalog_composition_duplicate_measure'; END IF;
    END IF;
  END LOOP;

  SELECT c.status INTO v_old_status FROM public.produto_composicao_conjuntos c WHERE c.produto_id = p_produto_id FOR UPDATE;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordem',d.ordem,'tipo_componente',d.tipo_componente,
      'microrganismo_id',d.microrganismo_id,'componente_nome',d.componente_nome,'quantidade',d.quantidade,'unidade',d.unidade,
      'base',d.base,'natureza',d.natureza) ORDER BY d.ordem), '[]'::jsonb) INTO v_before
    FROM public.produto_composicao_declaracoes d WHERE d.produto_id = p_produto_id;
  SELECT md5(COALESCE(string_agg(pg_catalog.to_jsonb(f)::text, ',' ORDER BY f.id), '')) INTO v_form_before FROM public.formulacoes f WHERE f.produto_id = p_produto_id;
  SELECT md5(COALESCE(string_agg(pg_catalog.to_jsonb(v)::text, ',' ORDER BY v.id), '')) INTO v_vol_before FROM public.catalogo_volumes v WHERE v.produto_id = p_produto_id;

  INSERT INTO public.produto_composicao_conjuntos (produto_id, status, updated_by) VALUES (p_produto_id, p_status, v_actor)
  ON CONFLICT (produto_id) DO UPDATE SET status = EXCLUDED.status, updated_by = EXCLUDED.updated_by;
  DELETE FROM public.produto_composicao_declaracoes d WHERE d.produto_id = p_produto_id;
  INSERT INTO public.produto_composicao_declaracoes (produto_id, ordem, tipo_componente, microrganismo_id, componente_nome, quantidade, unidade, base, natureza)
  SELECT p_produto_id, (e->>'ordem')::smallint, e->>'tipo_componente', (e->>'microrganismo_id')::uuid, e->>'componente_nome',
         (e->>'quantidade')::numeric, e->>'unidade', e->>'base', e->>'natureza'
  FROM pg_catalog.jsonb_array_elements(p_itens) e;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordem',d.ordem,'tipo_componente',d.tipo_componente,
      'microrganismo_id',d.microrganismo_id,'componente_nome',d.componente_nome,'quantidade',d.quantidade,'unidade',d.unidade,
      'base',d.base,'natureza',d.natureza) ORDER BY d.ordem), '[]'::jsonb) INTO v_after
    FROM public.produto_composicao_declaracoes d WHERE d.produto_id = p_produto_id;
  IF v_after = v_before AND v_old_status IS NOT DISTINCT FROM p_status THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_no_change'; END IF;

  -- Versão monotônica do produto; demais colunas, receita e apresentações intactas.
  UPDATE public.produtos SET updated_at = updated_at WHERE id = p_produto_id AND updated_at = p_expected_updated_at RETURNING * INTO v_np;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_composition_confirmation_failed'; END IF;
  SELECT md5(COALESCE(string_agg(pg_catalog.to_jsonb(f)::text, ',' ORDER BY f.id), '')) INTO v_form_after FROM public.formulacoes f WHERE f.produto_id = p_produto_id;
  SELECT md5(COALESCE(string_agg(pg_catalog.to_jsonb(v)::text, ',' ORDER BY v.id), '')) INTO v_vol_after FROM public.catalogo_volumes v WHERE v.produto_id = p_produto_id;
  IF v_n <> pg_catalog.jsonb_array_length(p_itens) OR v_np.updated_at IS NULL OR v_np.updated_at <= v_op.updated_at
     OR (pg_catalog.to_jsonb(v_op) - 'updated_at') IS DISTINCT FROM (pg_catalog.to_jsonb(v_np) - 'updated_at')
     OR v_form_before IS DISTINCT FROM v_form_after OR v_vol_before IS DISTINCT FROM v_vol_after THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_composition_confirmation_failed'; END IF;

  v_receipt := pg_catalog.jsonb_build_object('produto_id',p_produto_id,'status',p_status,'itens',v_n,'updated_at',v_np.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_product_composition',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('produto_id',p_produto_id,'status',v_old_status,'itens',v_before,'updated_at',v_op.updated_at),
    pg_catalog.jsonb_build_object('produto_id',p_produto_id,'status',p_status,'itens',v_after,'updated_at',v_np.updated_at));
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.conclude_provisional_password_server(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE;
BEGIN
 PERFORM platform_private.require_service_role();
 IF p_user_id IS NULL OR public.is_platform_superadmin(p_user_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE user_id=p_user_id ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
 PERFORM platform_private.issue_ticket('pwd_conclude',p_user_id);
 UPDATE public.profiles SET senha_provisoria=false WHERE user_id=p_user_id AND senha_provisoria IS TRUE;
 IF NOT FOUND THEN RAISE EXCEPTION 'platform_primeiro_acesso_nao_pendente' USING ERRCODE='22023'; END IF;
 UPDATE public.platform_org_admin_invites SET status='ativo',concluido_em=now(),access_valid_after=clock_timestamp(),access_expires_at=NULL,access_operation_status='completed' WHERE user_id=p_user_id;
 DELETE FROM platform_private.provisional_password_state WHERE user_id=p_user_id;
 IF j.id IS NOT NULL THEN INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key) VALUES(j.organization_id,p_user_id,j.id,p_user_id,'password_self_completed','succeeded','Senha pessoal definida pelo titular','platform_complete_first_access',gen_random_uuid()); END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.fn_b2b_order_billing_eligibility(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_order record; v_terms record; v_quote int; v_noprice int; v_ap text; v_fin text;
BEGIN
  SELECT * INTO v_order FROM public.partner_orders WHERE id = p_partner_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('eligible',false,'reason_code','ORDER_NOT_FOUND'); END IF;

  IF v_order.status IN ('cancelado','reprovado','reprovado_sem_itens') THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','ORDER_CANCELED_OR_REJECTED','status',v_order.status);
  END IF;
  IF v_order.status IN ('rascunho','pendente','solicitado','em_analise_comercial',
                        'aguardando_aprovacao_credito','aguardando_ajuste_comercial',
                        'aguardando_itens','aguardando_cotacao') THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','ORDER_NOT_APPROVED','status',v_order.status);
  END IF;

  v_fin := COALESCE(v_order.financial_approval_status,'not_required');
  IF v_fin = 'pending' THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','FINANCIAL_APPROVAL_PENDING');
  END IF;
  IF v_fin = 'rejected' THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','FINANCIAL_APPROVAL_REJECTED');
  END IF;

  SELECT count(*) FILTER (WHERE COALESCE(pricing_mode_snapshot,'') = 'quote_only'),
         count(*) FILTER (WHERE COALESCE(preco_unitario_final_snapshot, preco_unitario, 0) <= 0)
    INTO v_quote, v_noprice
    FROM public.partner_order_items WHERE order_id = p_partner_order_id;
  IF COALESCE(v_quote,0) > 0 THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','QUOTE_ONLY_ITEMS','count',v_quote);
  END IF;
  IF COALESCE(v_noprice,0) > 0 THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','ITEM_WITHOUT_FINAL_PRICE','count',v_noprice);
  END IF;

  -- H6C-001: condição canônica é a vinculada ao pedido; nunca "a mais recente".
  IF v_order.payment_terms_id IS NULL THEN
    IF EXISTS (SELECT 1 FROM public.partner_order_payment_terms t
                WHERE t.partner_order_id = p_partner_order_id) THEN
      RETURN jsonb_build_object('eligible',false,'reason_code','PAYMENT_TERMS_NOT_LINKED');
    END IF;
    RETURN jsonb_build_object('eligible',false,'reason_code','PAYMENT_TERMS_NOT_DEFINED');
  END IF;

  SELECT * INTO v_terms FROM public.partner_order_payment_terms
   WHERE id = v_order.payment_terms_id AND partner_order_id = p_partner_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','PAYMENT_TERMS_INVALID',
                              'payment_terms_id', v_order.payment_terms_id);
  END IF;

  v_ap := COALESCE(v_terms.approval_status,'pending');
  IF NOT (v_ap = 'approved'
          OR (v_ap = 'not_required' AND v_fin = 'not_required'
              AND COALESCE(v_order.requires_financial_approval,false) = false)) THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','PAYMENT_TERMS_NOT_APPROVED',
                              'approval_status', v_ap, 'payment_terms_id', v_terms.id);
  END IF;

  IF COALESCE(v_terms.final_amount,0) <= 0 THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','NO_FINAL_AMOUNT');
  END IF;

  RETURN jsonb_build_object('eligible',true,'reason_code','OK',
    'final_amount',v_terms.final_amount,'payment_terms_id',v_terms.id,
    'approval_status', v_ap, 'financial_approval_status', v_fin);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_avancar_etapa_esteira(p_origem text, p_os_id uuid, p_programacao_id uuid, p_etapa_destino text, p_usuario_id uuid DEFAULT auth.uid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_os_atual record;
  v_programacao record;
  v_lote_id uuid;
  v_cq_aprovado boolean;
  v_etapa_anterior text;
  v_tabela text;
BEGIN
  -- Determinar tabela de origem
  IF p_origem = 'onfarm' THEN
    v_tabela := 'ordens_servico_onfarm';
  ELSE
    v_tabela := 'ordens_servico';
  END IF;

  -- 1. Lock na OS para evitar processamento paralelo
  EXECUTE format('SELECT * FROM %I WHERE id = $1 FOR UPDATE', v_tabela)
  INTO v_os_atual
  USING p_os_id;

  IF v_os_atual.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de serviço não encontrada');
  END IF;

  v_etapa_anterior := v_os_atual.status;

  -- 2. Lock na Programação (se fornecida)
  IF p_programacao_id IS NOT NULL THEN
    SELECT * INTO v_programacao FROM programacao_producao WHERE id = p_programacao_id FOR UPDATE;
  END IF;

  -- 3. Validações de Regra de Negócio por Etapa
  CASE p_etapa_destino
    WHEN 'assumir_producao' THEN
      IF v_programacao.status = 'em_producao' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Esta demanda já está sendo produzida');
      END IF;

      UPDATE programacao_producao 
      SET status = 'em_producao', responsavel_id = p_usuario_id 
      WHERE id = p_programacao_id;

    WHEN 'enviar_cq' THEN
      SELECT id INTO v_lote_id FROM lotes WHERE programacao_id = p_programacao_id;
      IF v_lote_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Gere o lote antes de enviar para CQ');
      END IF;

    WHEN 'aprovar_cq' THEN
      SELECT id INTO v_lote_id FROM lotes WHERE programacao_id = p_programacao_id;
      UPDATE controle_qualidade SET resultado = 'aprovado' WHERE lote_id = v_lote_id;

    WHEN 'reprovar_cq' THEN
      SELECT id INTO v_lote_id FROM lotes WHERE programacao_id = p_programacao_id;
      UPDATE controle_qualidade SET resultado = 'reprovado' WHERE lote_id = v_lote_id;

    WHEN 'enviar_envase' THEN
      SELECT id INTO v_lote_id FROM lotes WHERE programacao_id = p_programacao_id;
      SELECT (resultado = 'aprovado') INTO v_cq_aprovado FROM controle_qualidade WHERE lote_id = v_lote_id ORDER BY created_at DESC, seq DESC LIMIT 1;

      IF NOT COALESCE(v_cq_aprovado, false) THEN
        RETURN jsonb_build_object('success', false, 'message', 'CQ precisa estar aprovado para enviar ao envase');
      END IF;

    WHEN 'concluir_envase' THEN
      SELECT id INTO v_lote_id FROM lotes WHERE programacao_id = p_programacao_id;
      IF NOT EXISTS (SELECT 1 FROM envase WHERE lote_id = v_lote_id) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Registre o envase antes de concluir esta etapa');
      END IF;

    ELSE
      -- Outras etapas genéricas ou customizadas
  END CASE;

  -- 4. Atualizar status na OS
  EXECUTE format('UPDATE %I SET status = $1 WHERE id = $2', v_tabela)
  USING p_etapa_destino, p_os_id;

  -- 5. Registrar Auditoria
  INSERT INTO laboratorio_esteira_eventos (
    origem_os, os_id, programacao_id, lote_id, etapa_anterior, etapa_nova, acao, usuario_id
  ) VALUES (
    p_origem, p_os_id, p_programacao_id, v_lote_id, v_etapa_anterior, p_etapa_destino, 'avanco_esteira_v2', p_usuario_id
  );

  RETURN jsonb_build_object('success', true, 'message', 'Etapa avançada com sucesso');
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.global_product_fiscal_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT platform_private.global_product_fiscal_write_ready() THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.is_active IS NOT TRUE THEN RAISE EXCEPTION 'FISCAL_HISTORY_IMMUTABLE' USING ERRCODE='42501'; END IF;
  IF NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'FISCAL_IDENTITY_IMMUTABLE'; END IF;
  -- Server-owned CAS token for ALL direct editor and IBS/CBS updates.
  -- Strictly newer even inside one transaction; caller timestamps are ignored.
  -- The existing AFTER fiscal audit observes this token in the same transaction.
  NEW.updated_at:=greatest(clock_timestamp(),OLD.updated_at+interval '1 microsecond');
 ELSE NEW.updated_at:=clock_timestamp(); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.global_product_fiscal_statement_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_WHEN<>'BEFORE' OR TG_LEVEL<>'STATEMENT' OR TG_OP NOT IN ('INSERT','UPDATE') OR TG_RELID<>'public.product_fiscal_profiles'::regclass THEN RAISE EXCEPTION 'invalid_fiscal_guard_context' USING ERRCODE='42501'; END IF;
 IF current_setting('role',true) IN ('anon','authenticated') AND auth.uid() IS NULL THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE' USING ERRCODE='PT503'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_catalogo_preco_canonico(p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_litro   numeric(18,6);
  v_distint integer;
  v_dose_ha numeric;
  v_unit    numeric(18,6);
BEGIN
  IF num_nonnulls(p_product_id, p_microrganismo_id) <> 1 THEN RETURN NULL; END IF;
  IF p_unit_type IS NULL OR p_unit_type NOT IN ('hectare','litro','dose','unidade') THEN RETURN NULL; END IF;

  SELECT count(DISTINCT round(cv.preco_litro_brl,2)), min(round(cv.preco_litro_brl,2))
    INTO v_distint, v_litro
  FROM public.catalogo_volumes cv
  WHERE cv.ativo = true
    AND cv.preco_litro_brl IS NOT NULL
    AND cv.produto_id IS NOT DISTINCT FROM p_product_id
    AND cv.microrganismo_id IS NOT DISTINCT FROM p_microrganismo_id;

  IF COALESCE(v_distint,0) <> 1 OR COALESCE(v_litro,0) <= 0 THEN
    RETURN NULL;
  END IF;

  IF p_unit_type = 'unidade' THEN
    IF COALESCE(p_volume_ml,0) <= 0 THEN RETURN NULL; END IF;
    SELECT round(cv.preco_brl,2) INTO v_unit
    FROM public.catalogo_volumes cv
    WHERE cv.ativo = true
      AND cv.volume_ml = p_volume_ml
      AND cv.produto_id IS NOT DISTINCT FROM p_product_id
      AND cv.microrganismo_id IS NOT DISTINCT FROM p_microrganismo_id
    ORDER BY cv.volume_ml
    LIMIT 1;
    RETURN COALESCE(v_unit, round(v_litro * (p_volume_ml / 1000.0), 2));
  END IF;

  IF p_unit_type = 'litro' THEN RETURN v_litro; END IF;
  IF p_unit_type = 'dose'  THEN RETURN round(v_litro / 10.0, 2); END IF;

  -- hectare
  IF p_product_id IS NOT NULL THEN
    SELECT pr.dose_ml_ha INTO v_dose_ha FROM public.produtos pr WHERE pr.id = p_product_id;
  ELSE
    SELECT mo.dose_ml_ha INTO v_dose_ha FROM public.microrganismos mo WHERE mo.id = p_microrganismo_id;
  END IF;
  IF COALESCE(v_dose_ha,0) <= 0 THEN RETURN NULL; END IF;
  RETURN round(v_litro * (v_dose_ha / 1000.0), 2);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_cockpit_assert_b2b_liberado(p_partner_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
  IF p_partner_order_id IS NULL THEN RETURN; END IF;

  SELECT status::text AS status,
         coalesce(financial_status, '')          AS fin,
         coalesce(financial_approval_status, '') AS fin_apr,
         coalesce(payment_condition_status, '')  AS pay,
         partner_id
    INTO r
    FROM public.partner_orders
   WHERE id = p_partner_order_id;

  IF r IS NULL THEN RAISE EXCEPTION 'COCKPIT_B2B_PEDIDO_NAO_ENCONTRADO'; END IF;
  IF r.partner_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_B2B_PARCEIRO_INVALIDO'; END IF;

  IF r.status IN ('rascunho','pendente','solicitado','em_analise_comercial',
                  'aguardando_cotacao','aguardando_aprovacao_credito',
                  'aguardando_ajuste_comercial','aguardando_itens') THEN
    RAISE EXCEPTION 'COCKPIT_B2B_APROVACAO_PENDENTE';
  END IF;
  IF r.status IN ('reprovado','reprovado_sem_itens','cancelado') THEN
    RAISE EXCEPTION 'COCKPIT_B2B_PEDIDO_BLOQUEADO';
  END IF;
  IF r.fin_apr IN ('pendente','rejeitado','bloqueado')
     OR r.fin IN ('bloqueado','inadimplente')
     OR r.pay IN ('pendente','rejeitado') THEN
    RAISE EXCEPTION 'COCKPIT_B2B_FINANCEIRO_BLOQUEADO';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.global_product_fiscal_ibs_save(p_product_id uuid, payload jsonb, expected_revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current_row public.product_fiscal_profiles; result public.product_fiscal_profiles; BEGIN
 IF NOT platform_private.global_product_fiscal_write_ready() THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Lock the same existing gate BEFORE the row; role revokers use this gate too.
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE'; END IF;
 IF NOT platform_private.global_product_fiscal_write_ready() THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM public._fiscal_rtc_assert_payload(payload,'item');
 SELECT * INTO current_row FROM public.product_fiscal_profiles WHERE product_id=p_product_id AND is_active IS TRUE FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_ITEM_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 IF expected_revision IS NULL OR expected_revision<>current_row.updated_at::text THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='40001'; END IF;
 UPDATE public.product_fiscal_profiles SET ibs_cbs_configuration=payload WHERE id=current_row.id AND product_id=p_product_id AND is_active IS TRUE AND updated_at=current_row.updated_at RETURNING * INTO result;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='40001'; END IF;
 RETURN jsonb_build_object('configuration',result.ibs_cbs_configuration,'revision',result.updated_at::text);
END $function$

CREATE OR REPLACE FUNCTION public.fn_cockpit_assert_operador()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED';
  END IF;
  IF NOT (
    public.has_role(auth.uid(), 'administrador'::app_role)
    OR public.has_role(auth.uid(), 'gestor'::app_role)
    OR public.has_role(auth.uid(), 'producao'::app_role)
    OR public.has_role(auth.uid(), 'operador_onfarm'::app_role)
  ) THEN
    RAISE EXCEPTION 'COCKPIT_FORBIDDEN';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cockpit_assert_operador_origem(p_origem text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_origem text := public.fn_cockpit_norm_origem(p_origem);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED'; END IF;

  IF public.has_role(v_uid, 'administrador'::app_role)
     OR public.has_role(v_uid, 'gestor'::app_role) THEN
    RETURN v_origem;
  END IF;

  -- produção: fluxo industrial (manual/onfarm/b2b), sem privilégio de override
  IF public.has_role(v_uid, 'producao'::app_role) THEN
    RETURN v_origem;
  END IF;

  -- operador on-farm: alçada restrita à própria origem
  IF public.has_role(v_uid, 'operador_onfarm'::app_role) THEN
    IF v_origem <> 'onfarm' THEN
      RAISE EXCEPTION 'COCKPIT_FORBIDDEN_ORIGEM';
    END IF;
    RETURN v_origem;
  END IF;

  RAISE EXCEPTION 'COCKPIT_FORBIDDEN';
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.require_provisioned_admin_target(p_actor uuid, p_invite uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE;
BEGIN
 PERFORM platform_private.require_service_role();
 IF p_actor IS NULL OR NOT public.is_platform_superadmin(p_actor) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite;
 IF NOT FOUND OR j.user_id IS NULL OR j.user_id=p_actor OR public.is_platform_superadmin(j.user_id) OR j.status NOT IN ('ativo','pendente') OR NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id AND p.ativo IS TRUE AND o.ativo IS TRUE) OR NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=j.user_id AND r.role='administrador'::public.app_role) OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=j.user_id AND u.raw_app_meta_data->>'provisioning_request_id'=j.request_id::text) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.fn_entrega_assert_confirmador(p_origem text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_origem text := public.fn_cockpit_norm_origem(p_origem);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED'; END IF;

  IF public.has_role(v_uid, 'administrador'::app_role)
     OR public.has_role(v_uid, 'gestor'::app_role)
     OR public.has_role(v_uid, 'administrativo'::app_role)
     OR public.has_role(v_uid, 'producao'::app_role) THEN
    RETURN v_origem;
  END IF;

  IF public.has_role(v_uid, 'operador_onfarm'::app_role) THEN
    IF v_origem <> 'onfarm' THEN RAISE EXCEPTION 'COCKPIT_FORBIDDEN_ORIGEM'; END IF;
    RETURN v_origem;
  END IF;

  RAISE EXCEPTION 'COCKPIT_FORBIDDEN';
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_org_admin_access_state(p_actor_id uuid, p_invite_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE; pending boolean; exp timestamptz; active boolean;
BEGIN
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,p_invite_id);
 PERFORM platform_private.require_service_role(); IF NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id;
 IF NOT FOUND OR j.user_id IS NULL OR j.user_id=p_actor_id OR public.is_platform_superadmin(j.user_id) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 SELECT p.senha_provisoria,p.ativo,s.expires_at INTO pending,active,exp FROM public.profiles p LEFT JOIN platform_private.provisional_password_state s ON s.user_id=p.user_id WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id;
 RETURN jsonb_build_object('pending_password',pending,'provisional_expires_at',exp,'active',active,'last_sent_at',j.email_accepted_at,'next_attempt_at',greatest(j.email_next_attempt_at,j.access_requested_at+interval '5 minutes'),'status',j.status,'operation_status',j.access_operation_status,'user_id',j.user_id);
END $function$

CREATE OR REPLACE FUNCTION platform_private.catalog_tenant_actor(p_mode text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_claims jsonb := NULLIF(current_setting('request.jwt.claims', true), '')::jsonb;
  v_org uuid;
BEGIN
  IF v_uid IS NULL OR v_claims IS NULL OR v_claims->>'role' IS DISTINCT FROM 'authenticated'
     OR (v_claims->>'sub') IS DISTINCT FROM v_uid::text
     OR NULLIF(v_claims->>'exp','') IS NULL OR (v_claims->>'exp') !~ '^[0-9]{1,12}$'
     OR to_timestamp((v_claims->>'exp')::bigint) <= now()
     OR (NULLIF(v_claims->>'iat','') IS NOT NULL AND ((v_claims->>'iat') !~ '^[0-9]{1,12}$'
         OR to_timestamp((v_claims->>'iat')::bigint) > now() + interval '60 seconds')) THEN
    RAISE EXCEPTION 'catalog_visibility_auth_required' USING ERRCODE='42501';
  END IF;
  IF public.is_platform_superadmin(v_uid) THEN
    RAISE EXCEPTION 'catalog_visibility_platform_actor_denied' USING ERRCODE='42501';
  END IF;
  v_org := platform_private.h15_actor_organization();
  IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=v_org AND o.ativo IS TRUE AND o.status='ativa') THEN
    RAISE EXCEPTION 'catalog_visibility_tenant_unavailable' USING ERRCODE='42501';
  END IF;
  IF p_mode IN ('mutate','read_catalog','read_management') AND NOT public._saas_user_has_feature(v_uid, 'catalogo_precos') THEN
    RAISE EXCEPTION 'catalog_visibility_feature_unavailable' USING ERRCODE='42501';
  END IF;
  IF p_mode='mutate' THEN
    IF NOT (platform_private.has_role(v_uid,'administrador'::public.app_role) OR platform_private.has_role(v_uid,'gestor'::public.app_role)) THEN
      RAISE EXCEPTION 'catalog_visibility_role_denied' USING ERRCODE='42501'; END IF;
  ELSIF p_mode='read_catalog' THEN
    IF NOT public.can_view_catalog_internal(v_uid) THEN
      RAISE EXCEPTION 'catalog_visibility_role_denied' USING ERRCODE='42501'; END IF;
  ELSIF p_mode NOT IN ('read_management','read_selection_cultura','read_prefs') OR p_mode IS NULL THEN
    RAISE EXCEPTION 'catalog_visibility_mode_invalid' USING ERRCODE='22023';
  END IF;
  RETURN v_org;
END; $function$

CREATE OR REPLACE FUNCTION platform_private.catalog_tenant_set_visibility_core(p_entity_type text, p_entity_id uuid, p_hidden boolean, p_expected_version integer, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_reason text := btrim(COALESCE(p_reason,''));
  v_hash text;
  v_prev public.catalog_tenant_visibility%ROWTYPE;
  v_ledger public.catalog_tenant_visibility_ledger%ROWTYPE;
  v_ativo boolean;
  v_new_version integer;
  v_result jsonb;
BEGIN
  v_org := platform_private.catalog_tenant_actor('mutate');
  IF p_entity_type IS NULL OR p_entity_type NOT IN ('produto','microrganismo','cultura') OR p_entity_id IS NULL
     OR p_hidden IS NULL OR p_idempotency_key IS NULL OR p_expected_version IS NULL OR p_expected_version < 0 THEN
    RAISE EXCEPTION 'catalog_visibility_invalid_payload' USING ERRCODE='22023'; END IF;
  IF char_length(v_reason) NOT BETWEEN 5 AND 500 THEN
    RAISE EXCEPTION 'catalog_visibility_reason_required' USING ERRCODE='22023'; END IF;
  v_hash := md5(concat_ws('|', p_entity_type, p_entity_id::text, p_hidden::text, p_expected_version::text, v_reason));

  -- Ordem fixa de locks: (1) ator+empresa+chave — serializa replay/conflito da MESMA chave mesmo em itens
  -- distintos; (2) empresa+item — serializa primeira gravação/CAS. Sempre nesta ordem (sem deadlock cruzado).
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(':','ctvk',v_uid::text,v_org::text,p_idempotency_key::text),0));
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(':','ctv',v_org::text,p_entity_type,p_entity_id::text),0));

  SELECT * INTO v_ledger FROM public.catalog_tenant_visibility_ledger
   WHERE actor_id=v_uid AND organization_id=v_org AND idempotency_key=p_idempotency_key;
  IF FOUND THEN
    IF v_ledger.payload_hash <> v_hash THEN
      RAISE EXCEPTION 'catalog_visibility_idempotency_conflict' USING ERRCODE='22023'; END IF;
    RETURN v_ledger.result || jsonb_build_object('replayed', true);
  END IF;

  -- Item global existente; inativo não pode ser exibido (preferência não reativa).
  IF p_entity_type='produto' THEN SELECT ativo INTO v_ativo FROM public.produtos WHERE id=p_entity_id;
  ELSIF p_entity_type='microrganismo' THEN SELECT ativo INTO v_ativo FROM public.microrganismos WHERE id=p_entity_id;
  ELSE SELECT ativo INTO v_ativo FROM public.culturas WHERE id=p_entity_id; END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'catalog_visibility_item_not_found' USING ERRCODE='P0002'; END IF;
  IF v_ativo IS NOT TRUE AND p_hidden IS FALSE THEN
    RAISE EXCEPTION 'catalog_visibility_item_inactive' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_prev FROM public.catalog_tenant_visibility
   WHERE organization_id=v_org AND entity_type=p_entity_type
     AND COALESCE(produto_id,microrganismo_id,cultura_id)=p_entity_id FOR UPDATE;
  IF COALESCE(v_prev.version,0) <> p_expected_version THEN
    RAISE EXCEPTION 'catalog_visibility_version_conflict' USING ERRCODE='PT409'; END IF;
  IF v_prev.id IS NOT NULL AND v_prev.hidden = p_hidden THEN
    RAISE EXCEPTION 'catalog_visibility_no_change' USING ERRCODE='22023'; END IF;
  IF v_prev.id IS NULL AND p_hidden IS FALSE THEN
    RAISE EXCEPTION 'catalog_visibility_no_change' USING ERRCODE='22023'; END IF;

  v_new_version := p_expected_version + 1;
  IF v_prev.id IS NULL THEN
    INSERT INTO public.catalog_tenant_visibility(organization_id,entity_type,produto_id,microrganismo_id,cultura_id,hidden,version,reason,updated_by)
    VALUES (v_org,p_entity_type,
      CASE WHEN p_entity_type='produto' THEN p_entity_id END,
      CASE WHEN p_entity_type='microrganismo' THEN p_entity_id END,
      CASE WHEN p_entity_type='cultura' THEN p_entity_id END,
      p_hidden,v_new_version,v_reason,v_uid);
  ELSE
    UPDATE public.catalog_tenant_visibility SET hidden=p_hidden, version=v_new_version, reason=v_reason,
      updated_by=v_uid, updated_at=now()
     WHERE id=v_prev.id AND version=p_expected_version;
    IF NOT FOUND THEN RAISE EXCEPTION 'catalog_visibility_version_conflict' USING ERRCODE='PT409'; END IF;
  END IF;

  v_result := jsonb_build_object('entity_type',p_entity_type,'entity_id',p_entity_id,'hidden',p_hidden,
    'version',v_new_version,'replayed',false);
  INSERT INTO public.catalog_tenant_visibility_ledger(organization_id,actor_id,idempotency_key,payload_hash,entity_type,entity_id,
    before_state,after_state,reason,result)
  VALUES (v_org,v_uid,p_idempotency_key,v_hash,p_entity_type,p_entity_id,
    CASE WHEN v_prev.id IS NULL THEN NULL ELSE jsonb_build_object('hidden',v_prev.hidden,'version',v_prev.version) END,
    jsonb_build_object('hidden',p_hidden,'version',v_new_version),v_reason,v_result);
  RETURN v_result;
END; $function$

CREATE OR REPLACE FUNCTION public.fn_entrega_confirmar_engine_v1(p_entrega_id uuid, p_os_id uuid, p_origem text, p_recebedor jsonb DEFAULT '{}'::jsonb, p_opcoes jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_os_id uuid;
  v_ent record;
  v_est public.estoque_produto%ROWTYPE;
  v_pendentes int; v_total_entregue numeric; v_total_reservado numeric;
  v_finalizada boolean := false; v_avanco jsonb;
  v_recebedor_nome text;
  v_entregue_em timestamptz;
  v_faturamento text := nullif(btrim(coalesce(p_opcoes->>'faturamento','')), '');
  v_motivo_nb text := nullif(btrim(coalesce(p_opcoes->>'motivo_nao_faturavel','')), '');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED'; END IF;
  IF p_entrega_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS'; END IF;

  PERFORM public.fn_estoque_ctx_open(jsonb_build_object(
    'acao','entrega','origem','fn_entrega_confirmar_engine_v1','usuario_id', v_uid::text));

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_entrega:' || p_entrega_id::text));

  SELECT e.id, e.status::text AS status, e.estoque_produto_id,
         coalesce(e.quantidade_entregue, 0) AS qtd, e.partner_order_id,
         e.ordem_servico_id, e.ordem_servico_onfarm_id
    INTO v_ent
    FROM public.entregas e
   WHERE e.id = p_entrega_id
   FOR UPDATE;

  IF v_ent.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_NAO_ENCONTRADA'; END IF;

  -- Origem: explícita quando informada; derivada do vínculo caso contrário.
  IF nullif(btrim(coalesce(p_origem,'')), '') IS NOT NULL THEN
    v_origem := public.fn_cockpit_norm_origem(p_origem);
  ELSIF v_ent.ordem_servico_onfarm_id IS NOT NULL THEN
    v_origem := 'onfarm';
  ELSIF v_ent.partner_order_id IS NOT NULL THEN
    v_origem := 'b2b';
  ELSE
    v_origem := 'manual';
  END IF;

  v_origem := public.fn_entrega_assert_confirmador(v_origem);

  v_os_id := CASE WHEN v_origem = 'onfarm' THEN v_ent.ordem_servico_onfarm_id
                  ELSE v_ent.ordem_servico_id END;

  IF p_os_id IS NOT NULL AND v_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_OS';
  END IF;

  IF v_ent.status = 'cancelada' THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_CANCELADA'; END IF;
  IF v_ent.status = 'entregue' THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'finalizada', false,
      'entrega_id', p_entrega_id,
      'message', 'Entrega já confirmada anteriormente.');
  END IF;

  IF v_origem = 'b2b' AND v_ent.partner_order_id IS NOT NULL THEN
    PERFORM public.fn_cockpit_assert_b2b_liberado(v_ent.partner_order_id);
  END IF;

  IF v_ent.estoque_produto_id IS NOT NULL THEN
    SELECT * INTO v_est FROM public.estoque_produto WHERE id = v_ent.estoque_produto_id FOR UPDATE;
    IF v_est.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_ESTOQUE_NAO_ENCONTRADO'; END IF;
    IF v_est.status::text <> 'expedido' THEN
      IF v_os_id IS NOT NULL THEN
        IF v_est.reservado_para_os_id IS DISTINCT FROM v_os_id THEN
          RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ESTOQUE';
        END IF;
        IF coalesce(v_est.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
          RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ORIGEM';
        END IF;
      END IF;
      IF v_ent.qtd > coalesce(v_est.quantidade, 0) THEN
        RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_EXCEDE_RESERVA';
      END IF;
    END IF;
  END IF;

  -- Recebedor físico é OBRIGATÓRIO e distinto de confirmado_por.
  v_recebedor_nome := nullif(btrim(coalesce(p_recebedor->>'nome','')), '');
  IF v_recebedor_nome IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_RECEBEDOR_OBRIGATORIO';
  END IF;

  v_entregue_em := coalesce(nullif(btrim(coalesce(p_opcoes->>'entregue_em','')), '')::timestamptz, now());

  UPDATE public.entregas
     SET status = 'entregue'::public.status_entrega,
         entregue_em = v_entregue_em,
         recebido_por_nome = v_recebedor_nome,
         recebido_por_cargo = coalesce(nullif(btrim(coalesce(p_recebedor->>'cargo','')), ''), recebido_por_cargo),
         recebido_por_documento = coalesce(nullif(btrim(coalesce(p_recebedor->>'documento','')), ''), recebido_por_documento),
         observacoes_confirmacao = coalesce(nullif(btrim(coalesce(p_recebedor->>'observacoes','')), ''), observacoes_confirmacao),
         confirmado_por = v_uid,
         financial_status = CASE WHEN v_faturamento = 'bill_later' THEN 'PENDING_BILLING'
                                 ELSE financial_status END
   WHERE id = p_entrega_id;

  IF v_est.id IS NOT NULL THEN
    UPDATE public.estoque_produto
       SET status = 'expedido'::public.status_estoque, expedido_por = v_uid,
           expedido_em = now(), updated_at = now()
     WHERE id = v_est.id AND status <> 'expedido'::public.status_estoque;

    IF FOUND THEN
      INSERT INTO public.estoque_movimentacoes
        (estoque_produto_id, acao, quantidade, status_anterior, status_novo, os_id, os_tipo, usuario_id, lote_id, observacao)
      VALUES (v_est.id, 'expedicao', v_ent.qtd, 'reservado', 'expedido',
              v_os_id, v_origem, v_uid, v_est.lote_id, 'Baixa por confirmação de entrega');
    END IF;
  END IF;

  IF v_os_id IS NOT NULL THEN
    v_avanco := public._rpc_avancar_esteira_laboratorio_internal(v_os_id, v_origem, 'enviar_entrega', NULL);

    INSERT INTO public.laboratorio_esteira_eventos
      (os_id, origem_os, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
    VALUES (v_os_id, v_origem, 'em_entrega', 'entregue', 'confirmar_entrega_v1', v_uid,
            format('Confirmação transacional da entrega %s (recebedor: %s)', p_entrega_id, v_recebedor_nome));

    IF v_origem = 'onfarm' THEN
      SELECT count(*) FILTER (WHERE status::text NOT IN ('entregue','cancelada')),
             coalesce(sum(quantidade_entregue) FILTER (WHERE status::text = 'entregue'), 0)
        INTO v_pendentes, v_total_entregue
        FROM public.entregas WHERE ordem_servico_onfarm_id = v_os_id;
    ELSE
      SELECT count(*) FILTER (WHERE status::text NOT IN ('entregue','cancelada')),
             coalesce(sum(quantidade_entregue) FILTER (WHERE status::text = 'entregue'), 0)
        INTO v_pendentes, v_total_entregue
        FROM public.entregas WHERE ordem_servico_id = v_os_id;
    END IF;

    SELECT coalesce(sum(quantidade_reservada), 0) INTO v_total_reservado
      FROM public.estoque_produto
     WHERE reservado_para_os_id = v_os_id
       AND coalesce(reservado_para_os_tipo, v_origem) = v_origem
       AND status <> 'estornado'::public.status_estoque;

    IF v_pendentes = 0 AND v_total_reservado > 0 AND v_total_entregue >= v_total_reservado THEN
      v_avanco := public._rpc_avancar_esteira_laboratorio_internal(v_os_id, v_origem, 'finalizar_os', NULL);
      IF coalesce((v_avanco->>'success')::boolean, false) THEN
        v_finalizada := true;
        INSERT INTO public.laboratorio_esteira_eventos
          (os_id, origem_os, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
        VALUES (v_os_id, v_origem, 'entregue', 'finalizada', 'finalizacao_automatica_por_entrega', v_uid,
                'Cobertura completa: OS finalizada na mesma transação da confirmação de entrega.');
      END IF;
    END IF;
  END IF;

  IF v_faturamento = 'not_billable' THEN
    IF v_motivo_nb IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_MOTIVO_NAO_FATURAVEL_OBRIGATORIO'; END IF;
    PERFORM public.fn_mark_entrega_not_billable(p_entrega_id, v_motivo_nb);
  END IF;

  RETURN jsonb_build_object('success', true, 'replay', false, 'finalizada', v_finalizada,
    'entrega_id', p_entrega_id, 'os_id', v_os_id, 'origem', v_origem,
    'parcial', (coalesce(v_pendentes, 0) > 0 OR coalesce(v_total_entregue, 0) < coalesce(v_total_reservado, 0)),
    'total_entregue', coalesce(v_total_entregue, 0), 'total_reservado', coalesce(v_total_reservado, 0),
    'message', CASE WHEN v_finalizada THEN 'Entrega confirmada — OS finalizada.'
                    ELSE 'Entrega confirmada.' END);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_valor_faturavel_v1(p_entrega_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_e public.entregas%ROWTYPE;
  v_po public.partner_orders%ROWTYPE;
  v_t public.partner_order_payment_terms%ROWTYPE;
  v_fin text;
  v_ap text;
  v_total_snapshot numeric;
  v_origem text;
  v_base numeric;
  v_aceito numeric;
  v_valor numeric;
  v_conf int;
  v_itens jsonb;
  v_ident jsonb;
BEGIN
  SELECT * INTO v_e FROM public.entregas WHERE id = p_entrega_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('origem','indisponivel','motivo','entrega_nao_encontrada');
  END IF;

  SELECT count(*)::int INTO v_conf
    FROM public.entrega_conferencia_itens WHERE entrega_id = p_entrega_id;

  -- ------------------- caminho B2B (snapshot canônico) -------------------
  IF v_e.partner_order_id IS NOT NULL THEN
    SELECT * INTO v_po FROM public.partner_orders WHERE id = v_e.partner_order_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('origem','indisponivel','motivo','pedido_b2b_nao_encontrado');
    END IF;

    v_fin := COALESCE(v_po.financial_approval_status, 'not_required');
    v_ident := jsonb_build_object(
      'partner_order_id', v_po.id,
      'payment_terms_id', v_po.payment_terms_id,
      'financial_approval_status', v_fin,
      'order_status', v_po.status);

    IF v_po.payment_terms_id IS NOT NULL THEN
      -- identidade imutável da condição econômica
      SELECT * INTO v_t FROM public.partner_order_payment_terms
       WHERE id = v_po.payment_terms_id;
      IF NOT FOUND OR v_t.partner_order_id IS DISTINCT FROM v_po.id THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','termo_canonico_invalido')
               || v_ident;
      END IF;

      v_ap := COALESCE(v_t.approval_status, 'pending');
      v_ident := v_ident || jsonb_build_object('approval_status', v_ap);

      IF v_ap = 'approved' THEN
        NULL; -- liberado
      ELSIF v_ap = 'not_required'
            AND v_fin = 'not_required'
            AND COALESCE(v_po.requires_financial_approval, false) = false THEN
        NULL; -- liberado: nenhuma aprovação exigida em nenhum nível
      ELSE
        -- pending / rejected / adjustment_requested / incoerência => fail-closed.
        -- Proibido fallback silencioso para outro termo ou para o pedido.
        RETURN jsonb_build_object('origem','bloqueado','motivo','condicao_b2b_nao_liberada')
               || v_ident;
      END IF;

      v_total_snapshot := v_t.final_amount;
      v_origem := 'B2B_PAYMENT_TERMS_SNAPSHOT';
    ELSE
      -- legado: sem condição vinculada ao pedido.
      IF EXISTS (SELECT 1 FROM public.partner_order_payment_terms t
                  WHERE t.partner_order_id = v_po.id) THEN
        -- existe termo, mas não é o canônico do pedido => nunca usar "o mais novo"
        RETURN jsonb_build_object('origem','bloqueado','motivo','termo_nao_vinculado_ao_pedido')
               || v_ident;
      END IF;
      IF v_fin IN ('pending','rejected') THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','aprovacao_financeira_'||v_fin)
               || v_ident;
      END IF;
      IF COALESCE(v_po.status,'') IN ('cancelado','reprovado','reprovado_sem_itens',
                                      'rascunho','pendente','solicitado','em_analise_comercial',
                                      'aguardando_aprovacao_credito','aguardando_ajuste_comercial',
                                      'aguardando_itens','aguardando_cotacao') THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','pedido_nao_faturavel')
               || v_ident;
      END IF;
      v_total_snapshot := COALESCE(v_po.final_amount_with_interest, v_po.total);
      v_origem := 'B2B_ORDER_SNAPSHOT_LEGACY';
    END IF;

    IF v_total_snapshot IS NULL OR v_total_snapshot <= 0 THEN
      RETURN jsonb_build_object('origem','indisponivel','motivo','snapshot_b2b_ausente')
             || v_ident;
    END IF;

    -- base econômica do pedido = soma dos subtotais snapshot dos itens
    SELECT COALESCE(sum(COALESCE(i.subtotal,
             COALESCE(i.preco_unitario_final_snapshot, i.preco_unitario, 0) * COALESCE(i.quantidade,0))), 0)
      INTO v_base
      FROM public.partner_order_items i WHERE i.order_id = v_po.id;

    IF v_conf = 0 OR v_base <= 0 THEN
      RETURN jsonb_build_object('origem', v_origem, 'valor', round(v_total_snapshot,2),
        'metodo', jsonb_build_object('tipo','integral','total_snapshot', round(v_total_snapshot,2),
                                     'base_itens', round(COALESCE(v_base,0),2)))
             || v_ident;
    END IF;

    -- participação econômica aceita POR PRODUTO (volume conferido aceito / volume conferido)
    WITH conf AS (
      SELECT ee.produto_id AS produto_id, ci.status AS status,
             COALESCE(ee.volume,0) * COALESCE(ci.quantidade,1) AS vol
        FROM public.entrega_conferencia_itens ci
        JOIN public.estoque_embalagens ee ON ee.id = ci.embalagem_id
       WHERE ci.entrega_id = p_entrega_id
    ), ratio AS (
      SELECT produto_id,
             CASE WHEN SUM(vol) > 0
                  THEN LEAST(1, round(COALESCE(SUM(vol) FILTER (WHERE status='aceito'), 0) / SUM(vol), 6))
                  ELSE 0 END AS r
        FROM conf GROUP BY produto_id
    ), itens AS (
      SELECT i.product_id AS product_id,
             COALESCE(i.subtotal,
               COALESCE(i.preco_unitario_final_snapshot, i.preco_unitario, 0) * COALESCE(i.quantidade,0)) AS sub,
             COALESCE(r.r, 0) AS r
        FROM public.partner_order_items i
        LEFT JOIN ratio r ON r.produto_id = i.product_id
       WHERE i.order_id = v_po.id
    )
    SELECT COALESCE(sum(sub * r),0),
           COALESCE(jsonb_agg(jsonb_build_object('produto_id', product_id,
                     'subtotal_snapshot', round(sub,2), 'ratio_aceito', r,
                     'base_aceita_item', round(sub * r, 2))
                    ORDER BY product_id), '[]'::jsonb)
      INTO v_aceito, v_itens
      FROM itens;

    IF abs(v_aceito - v_base) <= 0.01 THEN
      v_valor := round(v_total_snapshot, 2);
    ELSE
      -- alocação do ajuste histórico do pedido (juros/desconto de nível pedido)
      -- proporcional à participação econômica aceita dos itens.
      v_valor := round(v_total_snapshot * (v_aceito / v_base), 2);
    END IF;

    RETURN jsonb_build_object('origem', v_origem, 'valor', v_valor,
      'metodo', jsonb_build_object('tipo','participacao_economica_aceita_x_snapshot',
        'total_snapshot', round(v_total_snapshot,2),
        'base_itens', round(v_base,2), 'base_aceita', round(v_aceito,2),
        'fator', round(v_aceito / NULLIF(v_base,0), 6), 'itens', v_itens))
           || v_ident;
  END IF;

  -- ---------------- caminho OS / base de faturamento histórica -------------
  IF v_e.os_faturamento_base_id IS NOT NULL THEN
    SELECT b.valor_total_faturavel INTO v_total_snapshot
      FROM public.os_faturamento_base b WHERE b.id = v_e.os_faturamento_base_id;
    IF v_total_snapshot IS NOT NULL AND v_total_snapshot > 0 THEN
      RETURN jsonb_build_object('origem','OS_FATURAMENTO_BASE_SNAPSHOT',
        'valor', round(v_total_snapshot,2),
        'metodo', jsonb_build_object('tipo','os_base','os_faturamento_base_id', v_e.os_faturamento_base_id));
    END IF;
  END IF;

  RETURN jsonb_build_object('origem','indisponivel','motivo','sem_fonte_historica_confiavel');
END
$function$

CREATE OR REPLACE FUNCTION public.platform_claim_email_confirmation(p_actor_id uuid, p_op_id uuid, p_confirm_ambiguous boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.platform_org_admin_email_changes%ROWTYPE; t uuid:=gen_random_uuid();
BEGIN
 PERFORM platform_private.require_service_role(); IF NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE id=p_op_id FOR UPDATE;
 IF FOUND THEN PERFORM platform_private.require_provisioned_admin_target(p_actor_id,c.invite_id); END IF;
 IF NOT FOUND OR c.status NOT IN ('requested','failed') OR c.user_id IS NULL OR c.user_id=p_actor_id OR public.is_platform_superadmin(c.user_id) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 IF c.confirmation_next_attempt_at>clock_timestamp() OR c.confirmation_lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'email_confirmation_cooldown' USING ERRCODE='55P03'; END IF;
 IF c.confirmation_delivery_status IN ('sending','ambiguous') AND NOT p_confirm_ambiguous THEN RAISE EXCEPTION 'email_ambiguous_confirmation_required' USING ERRCODE='55P03'; END IF;
 IF c.attempt_count>=20 THEN RAISE EXCEPTION 'email_confirmation_rate_limit' USING ERRCODE='53400'; END IF;
 UPDATE public.platform_org_admin_email_changes SET status='requested',confirmation_lease=t,confirmation_lease_expires_at=clock_timestamp()+interval '2 minutes',confirmation_next_attempt_at=clock_timestamp()+interval '5 minutes',confirmation_expires_at=clock_timestamp()+interval '24 hours',confirmation_delivery_status='sending',attempt_count=attempt_count+1,updated_at=now() WHERE id=c.id;
 INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,new_values) VALUES(c.organization_id,c.user_id,c.invite_id,p_actor_id,'email_change_requested','requested','Reenvio de confirmação pelo titular','email_confirmation_claim',c.idempotency_key,jsonb_build_object('ambiguous_retry_confirmed',coalesce(p_confirm_ambiguous,false),'attempt',c.attempt_count+1));
 RETURN t;
END $function$

CREATE OR REPLACE FUNCTION public.platform_complete_org_admin_email_change(p_actor_id uuid, p_op_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.platform_org_admin_email_changes%ROWTYPE; j public.platform_org_admin_invites%ROWTYPE;
BEGIN
 PERFORM platform_private.require_service_role(); IF NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE id=p_op_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,c.invite_id);
 IF c.status='completed' THEN RETURN jsonb_build_object('status','completed','idempotent',true); END IF;
 IF c.status NOT IN ('requested','auth_updated','failed') OR c.confirmation_sent_at IS NULL OR c.user_id IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=c.user_id AND lower(u.email)=c.new_email AND u.email_confirmed_at IS NOT NULL AND COALESCE(u.email_change,'')='') THEN RAISE EXCEPTION 'email_confirmation_required' USING ERRCODE='55000'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=c.invite_id FOR UPDATE;
 IF j.user_id IS DISTINCT FROM c.user_id OR lower(j.email)<>c.old_email OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=c.user_id AND organization_id=c.organization_id) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 UPDATE public.profiles SET email=c.new_email WHERE user_id=c.user_id AND organization_id=c.organization_id;
 UPDATE public.platform_org_admin_invites SET email=c.new_email,access_valid_after=clock_timestamp(),updated_at=now() WHERE id=j.id;
 UPDATE public.platform_org_admin_email_changes SET status='completed',completed_at=now(),last_error_code=NULL,updated_at=now() WHERE id=c.id;
 INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values) VALUES(c.organization_id,c.user_id,c.invite_id,p_actor_id,'email_change_completed','succeeded',c.reason,'auth_confirmed_reconciliation',c.idempotency_key,jsonb_build_object('email','***'),jsonb_build_object('email','***'));
 RETURN jsonb_build_object('status','completed','idempotent',false);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_tax_input_valid(_input jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  k text; v jsonb; ik text; pct numeric;
  allowed_kinds text[] := ARRAY['ICMS','ICMS_ST','FCP','FCP_ST','DIFAL','PIS','COFINS','IPI'];
BEGIN
  IF _input IS NULL THEN RETURN true; END IF;
  IF jsonb_typeof(_input) <> 'object' THEN RETURN false; END IF;

  FOR k, v IN SELECT * FROM jsonb_each(_input) LOOP
    IF NOT (k = ANY(allowed_kinds)) THEN RETURN false; END IF;
    IF jsonb_typeof(v) <> 'object' THEN RETURN false; END IF;
    FOR ik IN SELECT jsonb_object_keys(v) LOOP
      IF ik NOT IN ('baseReductionPct','baseReductionReason') THEN RETURN false; END IF;
    END LOOP;
    IF NOT (v ? 'baseReductionPct') THEN RETURN false; END IF;
    IF jsonb_typeof(v->'baseReductionPct') <> 'number' THEN RETURN false; END IF;
    pct := (v->>'baseReductionPct')::numeric;
    IF pct < 0 OR pct > 100 THEN RETURN false; END IF;
    IF v ? 'baseReductionReason' THEN
      IF jsonb_typeof(v->'baseReductionReason') <> 'string' THEN RETURN false; END IF;
      IF length(v->>'baseReductionReason') > 240 THEN RETURN false; END IF;
    END IF;
  END LOOP;

  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_service_load_provider_runtime_config()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
DECLARE
  cfg public.communication_provider_settings%ROWTYPE;
  smtp_pw text;
  wa_tok text;
  wa_app text;
  wa_vt  text;
  result jsonb;
BEGIN
  -- Fail-closed: apenas service_role pode ler os segredos.
  IF current_setting('request.jwt.claim.role', true) IS NOT NULL
     AND current_setting('request.jwt.claim.role', true) <> 'service_role' THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO cfg FROM public.communication_provider_settings WHERE id = 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('present', false);
  END IF;

  IF cfg.secret_smtp_password IS NOT NULL THEN
    SELECT decrypted_secret INTO smtp_pw FROM vault.decrypted_secrets WHERE id = cfg.secret_smtp_password;
  END IF;
  IF cfg.secret_whatsapp_access_token IS NOT NULL THEN
    SELECT decrypted_secret INTO wa_tok FROM vault.decrypted_secrets WHERE id = cfg.secret_whatsapp_access_token;
  END IF;
  IF cfg.secret_whatsapp_app_secret IS NOT NULL THEN
    SELECT decrypted_secret INTO wa_app FROM vault.decrypted_secrets WHERE id = cfg.secret_whatsapp_app_secret;
  END IF;
  IF cfg.secret_whatsapp_verify_token IS NOT NULL THEN
    SELECT decrypted_secret INTO wa_vt FROM vault.decrypted_secrets WHERE id = cfg.secret_whatsapp_verify_token;
  END IF;

  result := jsonb_build_object(
    'present', true,
    'test_mode_enabled', cfg.test_mode_enabled,
    'allowed_emails', to_jsonb(cfg.allowed_emails),
    'allowed_phones', to_jsonb(cfg.allowed_phones),
    'delivery_enabled', cfg.delivery_enabled,
    'email_delivery_enabled', cfg.email_delivery_enabled,
    'whatsapp_delivery_enabled', cfg.whatsapp_delivery_enabled,
    'inapp_delivery_enabled', cfg.inapp_delivery_enabled,
    'whatsapp_webhook_enabled', cfg.whatsapp_webhook_enabled,
    'smtp_host', cfg.smtp_host,
    'smtp_port', cfg.smtp_port,
    'smtp_user', cfg.smtp_user,
    'smtp_from', cfg.smtp_from,
    'smtp_password', smtp_pw,
    'whatsapp_phone_number_id', cfg.whatsapp_phone_number_id,
    'whatsapp_api_version', cfg.whatsapp_api_version,
    'whatsapp_access_token', wa_tok,
    'whatsapp_app_secret', wa_app,
    'whatsapp_verify_token', wa_vt
  );
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_apportion_v1(p_total numeric, p_weights numeric[])
 RETURNS numeric[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  n int := coalesce(array_length(p_weights,1),0);
  total_c bigint;
  sum_w numeric := 0;
  out_c bigint[] := '{}';
  frac numeric[] := '{}';
  i int; assigned bigint := 0; rest bigint; idx int; best int; best_frac numeric;
  used boolean[] := '{}';
  res numeric[] := '{}';
BEGIN
  IF n = 0 THEN RETURN '{}'::numeric[]; END IF;
  IF coalesce(p_total,0) < 0 THEN
    RAISE EXCEPTION 'FISCAL_APPORTION_NEGATIVE_TOTAL' USING ERRCODE = '22023';
  END IF;
  total_c := round(coalesce(p_total,0) * 100)::bigint;
  FOR i IN 1..n LOOP
    IF coalesce(p_weights[i],0) < 0 THEN
      RAISE EXCEPTION 'FISCAL_APPORTION_NEGATIVE_WEIGHT' USING ERRCODE = '22023';
    END IF;
    sum_w := sum_w + coalesce(p_weights[i],0);
  END LOOP;

  IF total_c = 0 THEN
    FOR i IN 1..n LOOP res := res || 0::numeric; END LOOP;
    RETURN res;
  END IF;

  FOR i IN 1..n LOOP
    IF sum_w > 0 THEN
      out_c := out_c || floor(total_c * coalesce(p_weights[i],0) / sum_w)::bigint;
      frac  := frac  || ((total_c * coalesce(p_weights[i],0) / sum_w) - floor(total_c * coalesce(p_weights[i],0) / sum_w));
    ELSE
      out_c := out_c || floor(total_c / n)::bigint;
      frac  := frac  || ((total_c::numeric / n) - floor(total_c::numeric / n));
    END IF;
    used := used || false;
    assigned := assigned + out_c[i];
  END LOOP;

  rest := total_c - assigned;
  WHILE rest > 0 LOOP
    best := NULL; best_frac := -1;
    FOR i IN 1..n LOOP
      IF NOT used[i] AND frac[i] > best_frac THEN best := i; best_frac := frac[i]; END IF;
    END LOOP;
    IF best IS NULL THEN
      FOR i IN 1..n LOOP used[i] := false; END LOOP;
      CONTINUE;
    END IF;
    out_c[best] := out_c[best] + 1;
    used[best] := true;
    rest := rest - 1;
  END LOOP;

  FOR i IN 1..n LOOP res := res || (out_c[i]::numeric / 100); END LOOP;
  RETURN res;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_compute_item_taxes_v1(p_emit company_fiscal_settings, p_dest customer_fiscal_profiles, p_direction text, p_sales_channel text, p_ref_date date, p_ncm text, p_prod numeric, p_desconto numeric, p_frete numeric, p_seguro numeric, p_outras numeric, p_inputs jsonb, p_manual_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  pol public.fiscal_operation_policies%ROWTYPE;
  rule public.fiscal_tax_rules%ROWTYPE;
  kinds text[]; k text; ctx jsonb; res jsonb; item_taxes jsonb := '{}'::jsonb;
  v_prod numeric := public.fn_fiscal_round(coalesce(p_prod,0));
  v_icms_own numeric := 0; v_ipi numeric := 0; v_base_st numeric := NULL; v_st_val numeric := 0;
  v_fcp_own numeric := 0; v_fcp_st numeric := 0;
  v_difal_dest numeric := 0; v_difal_orig numeric := 0; v_fcp_dest numeric := 0;
  has_difal boolean := false;
BEGIN
  pol := public.fn_fiscal_resolve_operation(
    coalesce(p_direction,'OUT'), p_emit.state, coalesce(p_dest.fiscal_state, p_emit.state), p_emit.crt,
    p_dest.final_consumer, p_dest.taxpayer_indicator, p_ncm, null, p_sales_channel, p_ref_date);

  kinds := ARRAY['ICMS']::text[];
  IF coalesce(p_emit.ipi_taxpayer,false) THEN kinds := array_append(kinds,'IPI'); END IF;
  IF coalesce(p_emit.icms_st_responsible,false) THEN kinds := array_append(kinds,'ICMS_ST'); END IF;
  IF coalesce(p_emit.fcp_applicable,false) THEN
    kinds := array_append(kinds,'FCP');
    IF coalesce(p_emit.icms_st_responsible,false) THEN kinds := array_append(kinds,'FCP_ST'); END IF;
  END IF;
  IF coalesce(p_emit.difal_responsible,false)
     AND upper(coalesce(p_dest.fiscal_state,'')) <> upper(coalesce(p_emit.state,''))
     AND coalesce(p_dest.final_consumer,true) THEN
    kinds := array_append(kinds,'DIFAL');
  END IF;
  kinds := kinds || ARRAY['PIS','COFINS']::text[];

  FOREACH k IN ARRAY kinds LOOP
    ctx := jsonb_build_object(
      'produto', v_prod,
      'frete',    public.fn_fiscal_round(coalesce(p_frete,0)),
      'seguro',   public.fn_fiscal_round(coalesce(p_seguro,0)),
      'outras',   public.fn_fiscal_round(coalesce(p_outras,0)),
      'desconto', public.fn_fiscal_round(coalesce(p_desconto,0)),
      'ipi', v_ipi, 'icmsSt', v_st_val, 'icmsOwnValue', v_icms_own, 'baseST', v_base_st);

    rule := public.fn_fiscal_resolve_tax_rule(k, p_emit.crt, p_emit.state,
      coalesce(p_dest.fiscal_state, p_emit.state), p_ncm, null,
      p_dest.final_consumer, p_dest.taxpayer_indicator, p_ref_date);

    IF coalesce(rule.base_reduction_mode,'NONE') = 'MANUAL' THEN
      ctx := ctx || jsonb_build_object(
        'manualBaseReductionPct', coalesce(p_inputs,'{}'::jsonb)->k->>'baseReductionPct',
        'manualReason',           coalesce(p_inputs,'{}'::jsonb)->k->>'baseReductionReason',
        'manualBy', p_manual_by::text,
        'manualAt', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SSZ'));
    END IF;

    res := public.fn_fiscal_apply_tax_v2(rule, ctx);
    item_taxes := item_taxes || jsonb_build_object(k, res || jsonb_build_object('contextIn', ctx));

    IF k = 'ICMS'    THEN v_icms_own := (res->>'value')::numeric; END IF;
    IF k = 'IPI'     THEN v_ipi := (res->>'value')::numeric; END IF;
    IF k = 'ICMS_ST' THEN
      v_st_val  := (res->>'value')::numeric;
      v_base_st := (res->'params'->>'baseST')::numeric;
    END IF;
    IF k = 'FCP'     THEN v_fcp_own := (res->>'value')::numeric; END IF;
    IF k = 'FCP_ST'  THEN v_fcp_st := (res->>'value')::numeric; END IF;
    IF k = 'DIFAL'   THEN
      has_difal := true;
      v_difal_dest := coalesce((res->'params'->>'valueDestination')::numeric,0);
      v_difal_orig := coalesce((res->'params'->>'valueOrigin')::numeric,0);
      v_fcp_dest   := coalesce((res->'params'->>'fcpValue')::numeric,0);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'taxOrder', to_jsonb(kinds),
    'hasDifal', has_difal,
    'policy', jsonb_build_object(
      'id', pol.id, 'cfop', pol.cfop, 'natureOperation', pol.nature_operation,
      'legalVersion', pol.legal_version, 'legalBasis', pol.legal_basis, 'sourceId', pol.source_id),
    'chained', jsonb_build_object(
      'icmsOwnValue', v_icms_own, 'ipi', v_ipi, 'icmsSt', v_st_val, 'baseST', v_base_st),
    'itemTotals', jsonb_build_object(
      'vFCP', v_fcp_own, 'vFCPST', v_fcp_st,
      'vICMSUFDest', v_difal_dest, 'vICMSUFRemet', v_difal_orig, 'vFCPUFDest', v_fcp_dest),
    'taxes', item_taxes);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_assert_debtor_recipient(_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  inv public.fiscal_invoices%ROWTYPE;
  elig jsonb; v_debtor uuid; v_expected uuid;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(_invoice_id);

  SELECT * INTO inv FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = _invoice_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: %', _invoice_id;
  END IF;

  IF coalesce(inv.source_type,'') NOT IN ('PARTNER_ORDER','ENTREGA') THEN
    RAISE EXCEPTION 'FISCAL_SOURCE_TYPE_UNSUPPORTED: escopo % nao suportado nesta fase.', coalesce(inv.source_type,'-');
  END IF;

  elig := public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id);
  v_debtor := nullif(elig->>'debtorPartnerId','')::uuid;

  IF v_debtor IS NULL THEN
    RAISE EXCEPTION 'FISCAL_DEBTOR_RECIPIENT_MISMATCH: parceiro devedor nao resolvido para a origem % .', inv.source_type
      USING HINT = 'Somente o parceiro B2B devedor pode figurar como destinatario; produtor final vinculado nunca e devedor.';
  END IF;

  v_expected := public.fn_fiscal_partner_fiscal_customer(v_debtor);

  IF v_expected IS NULL THEN
    RAISE EXCEPTION 'FISCAL_DEBTOR_RECIPIENT_MISMATCH: parceiro devedor sem cliente fiscal (partner_accounts.client_id) cadastrado.'
      USING HINT = 'Vincule a conta do parceiro ao cliente fiscal antes de faturar.';
  END IF;

  IF inv.customer_id IS NULL THEN
    RAISE EXCEPTION 'FISCAL_DEBTOR_RECIPIENT_MISMATCH: documento sem destinatario (customer_id) definido.';
  END IF;

  IF inv.customer_id <> v_expected THEN
    RAISE EXCEPTION 'FISCAL_DEBTOR_RECIPIENT_MISMATCH: destinatario do documento nao corresponde ao cliente fiscal do parceiro devedor.'
      USING HINT = 'Emissao bloqueada sem qualquer efeito colateral. Corrija o destinatario ou o devedor.';
  END IF;

  IF inv.debtor_partner_id IS NOT NULL AND inv.debtor_partner_id <> v_debtor THEN
    RAISE EXCEPTION 'FISCAL_DEBTOR_RECIPIENT_MISMATCH: debtor_partner_id do documento diverge do devedor da origem.';
  END IF;

  IF inv.debtor_customer_id IS NOT NULL AND inv.debtor_customer_id <> v_expected THEN
    RAISE EXCEPTION 'FISCAL_DEBTOR_RECIPIENT_MISMATCH: debtor_customer_id do documento diverge do cliente fiscal do parceiro devedor.';
  END IF;

  RETURN jsonb_build_object(
    'debtorPartnerId', v_debtor,
    'recipientCustomerId', v_expected,
    'sourceType', inv.source_type,
    'orderId', elig->>'orderId');
END $function$

CREATE OR REPLACE FUNCTION platform_private.b2b_phase1_partner_visible(p_partner uuid, p_technical boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s record; u uuid:=auth.uid(); BEGIN
 IF u IS NULL OR p_partner IS NULL THEN RETURN false; END IF;
 IF public.is_platform_superadmin(u) THEN RETURN true; END IF;
 IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=u AND role IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor')) THEN
  RETURN public.is_valid_b2b_partner_user(u,p_partner)
   AND (public.has_role(u,'parceiro_b2b') OR (p_technical AND public.has_role(u,'parceiro_b2b_tecnico')));
 END IF;
 SELECT * INTO s FROM platform_private.b2b_actor_scope(u);
 RETURN s.profile_ok AND s.partner_valid AND s.org_partner=p_partner;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_assert_staging_marker(p_operation text DEFAULT 'GENERIC'::text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE m public.fiscal_environment_marker;
BEGIN
  SELECT * INTO m FROM public.fiscal_environment_marker WHERE id;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'FISCAL_ENV_NOT_READY: FISCAL_ENV_MARKER_MISSING — ambiente fiscal nao identificado (operacao=%).', p_operation;
  END IF;
  IF m.environment_label <> 'STAGING' OR m.production_emission_allowed THEN
    RAISE EXCEPTION
      'FISCAL_PRODUCTION_DISABLED: FISCAL_ENV_MARKER_BLOCKED — emissao fiscal produtiva desabilitada (operacao=%).', p_operation;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_emitter_pendencies_row(r company_fiscal_settings)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE out jsonb := '[]'::jsonb; ie_state text;
BEGIN
  IF current_setting('role', true) = 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.organizations o
      WHERE o.id = r.organization_id AND o.ativo IS TRUE
    ) THEN
      RAISE EXCEPTION 'H15_ORGANIZATION_FORBIDDEN' USING ERRCODE='42501';
    END IF;
  ELSE
    PERFORM public.h15_require_staff();
    IF r.organization_id IS DISTINCT FROM public.h15_actor_organization() THEN
      RAISE EXCEPTION 'H15_COMPANY_FORBIDDEN' USING ERRCODE='42501';
    END IF;
  END IF;

  IF NOT public.fn_fiscal_cnpj_is_valid(r.cnpj) THEN
    out := out || jsonb_build_object('code','EMITTER_CNPJ_INVALID','field','cnpj','severity','BLOCK','message','CNPJ ausente ou com digito verificador invalido.');
  END IF;
  IF nullif(btrim(coalesce(r.legal_name,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_LEGAL_NAME_MISSING','field','legal_name','severity','BLOCK','message','Razao social obrigatoria.');
  END IF;
  IF r.crt IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_CRT_MISSING','field','crt','severity','BLOCK','message','CRT (1,2,3,4) obrigatorio.');
  END IF;
  IF nullif(btrim(coalesce(r.primary_cnae,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_CNAE_MISSING','field','primary_cnae','severity','BLOCK','message','CNAE principal obrigatorio.');
  END IF;
  IF r.pis_cofins_regime IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_PIS_COFINS_REGIME_MISSING','field','pis_cofins_regime','severity','BLOCK','message','Regime de PIS/COFINS obrigatorio para calculo.');
  END IF;
  IF NOT public.fn_fiscal_cep_is_valid(r.postal_code) THEN
    out := out || jsonb_build_object('code','EMITTER_CEP_INVALID','field','postal_code','severity','BLOCK','message','CEP deve ter 8 digitos.');
  END IF;
  IF public.fn_fiscal_uf_ibge_code(r.state) IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_UF_INVALID','field','state','severity','BLOCK','message','UF invalida.');
  ELSIF NOT public.fn_fiscal_ibge_municipio_coerente(r.municipality_ibge_code, r.state) THEN
    out := out || jsonb_build_object('code','EMITTER_IBGE_INCOHERENT','field','municipality_ibge_code','severity','BLOCK','message','Codigo IBGE do municipio ausente ou incoerente com a UF.');
  END IF;
  IF nullif(btrim(coalesce(r.street,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.number,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.neighborhood,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.city,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ADDRESS_INCOMPLETE','field','address','severity','BLOCK','message','Endereco completo obrigatorio (logradouro, numero, bairro, municipio).');
  END IF;
  IF coalesce(r.country_code,'') NOT IN ('1058','BR') THEN
    out := out || jsonb_build_object('code','EMITTER_COUNTRY_MISSING','field','country_code','severity','BLOCK','message','Pais obrigatorio (1058 - Brasil).');
  END IF;
  ie_state := public.fn_fiscal_ie_check(r.state, r.state_registration);
  IF ie_state IN ('MISSING','INVALID_LENGTH','INVALID_DV','INVALID_FORMAT','INVALID_UF') THEN
    out := out || jsonb_build_object('code','EMITTER_IE_INVALID','field','state_registration','severity','BLOCK','message','Inscricao estadual invalida para a UF: '||ie_state);
  ELSIF ie_state = 'VALID_LENGTH_DV_NOT_IMPLEMENTED' THEN
    out := out || jsonb_build_object('code','EMITTER_IE_DV_NOT_IMPLEMENTED','field','state_registration','severity','WARN','message','IE com formato compativel; digito verificador desta UF nao e verificado automaticamente.');
  END IF;
  IF r.nfe_series_number IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_SERIES_MISSING','field','nfe_series_number','severity','BLOCK','message','Serie da NF-e (1-999) obrigatoria.');
  END IF;
  IF r.nfe_environment_code IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ENVIRONMENT_MISSING','field','nfe_environment_code','severity','BLOCK','message','Ambiente tpAmb (2 homologacao / 1 producao) obrigatorio.');
  END IF;
  IF jsonb_array_length(r.uf_accreditations) = 0 THEN
    out := out || jsonb_build_object('code','EMITTER_ACCREDITATION_MISSING','field','uf_accreditations','severity','BLOCK','message','Credenciamento por UF nao registrado.');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fiscal_certificates c
    WHERE c.id::text = r.certificate_ref AND c.company_settings_id = r.id
      AND c.environment = 'HOMOLOGATION' AND c.status = 'AVAILABLE'
      AND c.is_active IS TRUE AND c.revoked_at IS NULL
      AND c.valid_from <= now() AND c.valid_until > now()) THEN
    out := out || jsonb_build_object('code','EMITTER_CERTIFICATE_MISSING','field','certificate_ref','severity','BLOCK','message','Certificado ausente, indisponivel, revogado, vencido ou de outra empresa.');
  END IF;
  IF r.accounting_validated_at IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ACCOUNTING_NOT_VALIDATED','field','accounting_validated_at','severity','BLOCK','message','Validacao contabil pendente.');
  END IF;
  IF coalesce(r.nfe_environment_code,'2') = '1' THEN
    out := out || jsonb_build_object('code','EMITTER_PRODUCTION_BLOCKED_F3','field','nfe_environment_code','severity','BLOCK',
      'message','Ambiente de producao (tpAmb=1) bloqueado na fase F3: teto e READY_HOMOLOGATION ate fluxo controlado de homologacao SEFAZ.');
  END IF;
  RETURN out;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_emitter_pendencies(_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE r public.company_fiscal_settings%ROWTYPE;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_company(_id);

  SELECT * INTO r FROM (SELECT * FROM public.company_fiscal_settings WHERE organization_id = public.h15_actor_organization()) company_fiscal_settings WHERE id = _id;
  IF NOT FOUND THEN
    RETURN jsonb_build_array(jsonb_build_object('code','EMITTER_NOT_FOUND','field','id','severity','BLOCK'));
  END IF;
  RETURN public.fn_fiscal_emitter_pendencies_row(r);
END $function$

CREATE OR REPLACE FUNCTION public.register_my_login_redirect_secure(p_context text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_available jsonb;
BEGIN
  IF v_uid IS NULL OR NOT platform_private.platform_actor_access_ready(v_uid) OR public.h15_actor_organization() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_context IS NULL OR p_context NOT IN ('b2b','technical','producer','admin') THEN
    RAISE EXCEPTION 'invalid context %', p_context;
  END IF;

  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'c2_guard_unavailable'; END IF;
  v_available := public.get_my_available_portal_contexts();

  IF NOT (v_available->'available_contexts' ? p_context) THEN
    INSERT INTO public.user_context_access_logs (
      user_id, context_code, action, previous_context, metadata
    ) VALUES (
      v_uid, p_context, 'access_denied', NULL,
      jsonb_build_object('reason','context_not_available','source','login_redirect')
    );

    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'context_not_available',
      'context', p_context
    );
  END IF;

  -- Metadata fixa; frontend não escolhe.
  INSERT INTO public.user_context_access_logs (
    user_id, context_code, action, previous_context, metadata
  ) VALUES (
    v_uid, p_context, 'login_redirect', NULL,
    jsonb_build_object('source','auto')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'context', p_context,
    'action', 'login_redirect'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_claim_admin_access(p_actor_id uuid, p_invite_id uuid, p_operation_id uuid, p_kind text, p_confirm_ambiguous boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE; t uuid:=gen_random_uuid();
BEGIN
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,p_invite_id);
 PERFORM platform_private.require_service_role();
 IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) OR p_kind NOT IN ('temporary_password','password_link') OR p_operation_id IS NULL THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id FOR UPDATE;
 IF NOT FOUND OR j.user_id IS NULL OR j.user_id=p_actor_id OR public.is_platform_superadmin(j.user_id) OR j.status NOT IN ('ativo','pendente') OR NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id AND p.ativo AND o.ativo) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.platform_org_admin_email_changes c WHERE c.invite_id=j.id AND c.status IN ('requested','auth_updated','failed')) THEN RAISE EXCEPTION 'email_change_pending' USING ERRCODE='55P03'; END IF;
 IF j.access_operation_status IN ('ambiguous','processing') AND j.access_operation_id IS DISTINCT FROM p_operation_id AND NOT coalesce(p_confirm_ambiguous,false) THEN RAISE EXCEPTION 'access_ambiguous_requires_confirmation' USING ERRCODE='55P03'; END IF;
 IF j.access_operation_id=p_operation_id THEN
  IF j.access_operation_kind<>p_kind THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='40001'; END IF;
  IF j.access_operation_status IN ('completed','ambiguous') THEN RETURN jsonb_build_object('idempotent',true,'status',j.access_operation_status); END IF;
 END IF;
 IF (j.lease_expires_at>clock_timestamp()) OR j.status='processando' OR j.email_delivery_status='sending' OR (j.access_requested_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'access_cooldown_or_busy' USING ERRCODE='55P03'; END IF;
 IF (SELECT count(*) FROM public.platform_org_admin_audit WHERE actor_user_id=p_actor_id AND action='access_requested' AND created_at>now()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'access_rate_limit' USING ERRCODE='53400'; END IF;
 UPDATE public.platform_org_admin_invites SET access_operation_id=p_operation_id,access_operation_kind=p_kind,access_operation_status='processing',access_requested_at=clock_timestamp(),access_valid_after=CASE WHEN p_kind='temporary_password' THEN clock_timestamp() ELSE access_valid_after END,lease_token=t,lease_expires_at=clock_timestamp()+interval '2 minutes',updated_at=now() WHERE id=j.id;
 IF p_kind='temporary_password' THEN
  UPDATE public.profiles SET senha_provisoria=true WHERE user_id=j.user_id;
  INSERT INTO platform_private.provisional_password_state(user_id,desde,expires_at) VALUES(j.user_id,now(),now()+interval '24 hours') ON CONFLICT(user_id) DO UPDATE SET desde=now(),expires_at=now()+interval '24 hours',pwd_digest=NULL;
 END IF;
 INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,new_values) VALUES(j.organization_id,j.user_id,j.id,p_actor_id,'access_requested','requested','Gestão segura de acesso','platform_invite_org_admin',p_operation_id,jsonb_build_object('kind',p_kind,'ambiguous_retry_confirmed',coalesce(p_confirm_ambiguous,false)));
 RETURN jsonb_build_object('user_id',j.user_id,'email',j.email,'nome',j.nome,'lease_token',t,'organization_id',j.organization_id,'status',j.status);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_environment_gate_v1(p_operation text DEFAULT 'GENERIC'::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_count integer;
  v_env   text;
BEGIN
  IF current_setting('role',true) = 'service_role' THEN IF (SELECT count(*) FROM public.company_fiscal_settings WHERE is_active) <> 1 THEN RAISE EXCEPTION 'H15_SERVICE_EMITTER_AMBIGUOUS' USING ERRCODE='42501'; END IF; ELSE PERFORM public.h15_require_staff(); END IF;

  PERFORM public.fn_fiscal_assert_staging_marker(p_operation);

  SELECT count(*) INTO v_count FROM (SELECT * FROM public.company_fiscal_settings WHERE (organization_id = public.h15_actor_organization() OR current_setting('role',true) = 'service_role')) company_fiscal_settings WHERE is_active;
  IF v_count = 0 THEN
    RAISE EXCEPTION
      'FISCAL_ENV_NOT_READY: FISCAL_EMITTER_NOT_CONFIGURED — nenhum emitente fiscal ativo (operacao=%).', p_operation;
  END IF;
  IF v_count > 1 THEN
    RAISE EXCEPTION
      'FISCAL_ENV_NOT_READY: FISCAL_EMITTER_AMBIGUOUS — % emitentes ativos (operacao=%).', v_count, p_operation;
  END IF;

  SELECT btrim(coalesce(nfe_environment_code, '')) INTO v_env
    FROM (SELECT * FROM public.company_fiscal_settings WHERE (organization_id = public.h15_actor_organization() OR current_setting('role',true) = 'service_role')) company_fiscal_settings WHERE is_active LIMIT 1;

  IF v_env IS NULL OR v_env NOT IN ('1', '2') THEN
    RAISE EXCEPTION
      'FISCAL_ENV_NOT_READY: FISCAL_ENVIRONMENT_INVALID — tpAmb ausente/invalido (operacao=%).', p_operation;
  END IF;
  IF v_env = '1' THEN
    RAISE EXCEPTION
      'FISCAL_PRODUCTION_DISABLED: FISCAL_PRODUCTION_BLOCKED — emissao em producao desabilitada (operacao=%).', p_operation;
  END IF;

  RETURN v_env;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_partner_fiscal_customer(_partner_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_customer uuid; n_share int;
BEGIN
  IF _partner_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT pa.client_id INTO v_customer
    FROM public.partner_accounts pa
   WHERE pa.id = _partner_id
     AND pa.deleted_at IS NULL;

  IF v_customer IS NULL THEN
    RETURN NULL;
  END IF;

  -- Duplicidade: mais de um parceiro ativo apontando para o mesmo cliente fiscal
  -- torna o destinatário ambíguo. Nunca escolher em silêncio.
  SELECT count(*) INTO n_share
    FROM public.partner_accounts pa
   WHERE pa.client_id = v_customer
     AND pa.deleted_at IS NULL
     AND coalesce(pa.ativo, true);

  IF n_share > 1 THEN
    RAISE EXCEPTION
      'FISCAL_DEBTOR_RECIPIENT_MISMATCH: % contas de parceiro ativas compartilham o mesmo cliente fiscal; destinatario ambiguo.', n_share
      USING HINT = 'Regularize o cadastro comercial antes de faturar. O motor fiscal nunca desempata devedor automaticamente.';
  END IF;

  RETURN v_customer;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_recipient_pendencies_row(r customer_fiscal_profiles)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE out jsonb := '[]'::jsonb; ie_state text; doc text;
BEGIN
  doc := public.fn_fiscal_digits(r.cpf_cnpj);
  IF r.person_type IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_PERSON_TYPE_MISSING','field','person_type','severity','BLOCK','message','Tipo de pessoa (PF/PJ/ESTRANGEIRO) obrigatorio.');
  ELSIF r.person_type = 'PJ' AND NOT public.fn_fiscal_cnpj_is_valid(doc) THEN
    out := out || jsonb_build_object('code','RECIPIENT_CNPJ_INVALID','field','cpf_cnpj','severity','BLOCK','message','CNPJ do destinatario invalido.');
  ELSIF r.person_type = 'PF' AND NOT public.fn_fiscal_cpf_is_valid(doc) THEN
    out := out || jsonb_build_object('code','RECIPIENT_CPF_INVALID','field','cpf_cnpj','severity','BLOCK','message','CPF do destinatario invalido.');
  ELSIF r.person_type = 'ESTRANGEIRO' AND coalesce(r.country_code,'1058') IN ('1058','BR') THEN
    out := out || jsonb_build_object('code','RECIPIENT_FOREIGN_COUNTRY_REQUIRED','field','country_code','severity','BLOCK','message','Destinatario estrangeiro exige pais diferente de Brasil.');
  END IF;

  IF nullif(btrim(coalesce(r.legal_name,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_NAME_MISSING','field','legal_name','severity','BLOCK','message','Razao social / nome do destinatario obrigatorio.');
  END IF;
  IF r.taxpayer_indicator IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_TAXPAYER_INDICATOR_MISSING','field','taxpayer_indicator','severity','BLOCK','message','Indicador de IE do destinatario (indIEDest) obrigatorio.');
  END IF;
  IF coalesce(r.foreign_customer_indicator,false) = false THEN
    IF public.fn_fiscal_uf_ibge_code(r.fiscal_state) IS NULL THEN
      out := out || jsonb_build_object('code','RECIPIENT_UF_INVALID','field','fiscal_state','severity','BLOCK','message','UF do destinatario invalida.');
    ELSIF NOT public.fn_fiscal_ibge_municipio_coerente(r.fiscal_municipality_ibge_code, r.fiscal_state) THEN
      out := out || jsonb_build_object('code','RECIPIENT_IBGE_INCOHERENT','field','fiscal_municipality_ibge_code','severity','BLOCK','message','Codigo IBGE do municipio ausente ou incoerente com a UF.');
    END IF;
    IF NOT public.fn_fiscal_cep_is_valid(r.fiscal_postal_code) THEN
      out := out || jsonb_build_object('code','RECIPIENT_CEP_INVALID','field','fiscal_postal_code','severity','BLOCK','message','CEP do destinatario deve ter 8 digitos.');
    END IF;
    IF nullif(btrim(coalesce(r.fiscal_street,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_number,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_neighborhood,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_city,'')),'') IS NULL THEN
      out := out || jsonb_build_object('code','RECIPIENT_ADDRESS_INCOMPLETE','field','address','severity','BLOCK','message','Endereco fiscal completo obrigatorio.');
    END IF;
    IF coalesce(r.icms_taxpayer,false) THEN
      ie_state := public.fn_fiscal_ie_check(r.fiscal_state, r.state_registration);
      IF ie_state IN ('MISSING','INVALID_LENGTH','INVALID_DV','INVALID_FORMAT','INVALID_UF','ISENTO') THEN
        out := out || jsonb_build_object('code','RECIPIENT_IE_INVALID','field','state_registration','severity','BLOCK','message','Destinatario contribuinte exige IE valida: '||ie_state);
      ELSIF ie_state = 'VALID_LENGTH_DV_NOT_IMPLEMENTED' THEN
        out := out || jsonb_build_object('code','RECIPIENT_IE_DV_NOT_IMPLEMENTED','field','state_registration','severity','WARN','message','IE com formato compativel; DV desta UF nao e verificado automaticamente.');
      END IF;
    END IF;
  END IF;
  IF nullif(btrim(coalesce(r.fiscal_email,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_FISCAL_EMAIL_MISSING','field','fiscal_email','severity','WARN','message','E-mail fiscal ausente; DANFE/XML nao poderao ser enviados automaticamente.');
  END IF;
  RETURN out;
END $function$

CREATE OR REPLACE FUNCTION platform_private.external_provisioning_scope(p_actor uuid, p_roles app_role[], p_partner uuid, p_clients uuid[], p_primary uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid; snapshot jsonb; partner_snapshot jsonb; p_role public.app_role;
BEGIN
 SELECT organization_id INTO org FROM public.profiles WHERE user_id=p_actor FOR UPDATE;
 IF p_actor IS NULL OR org IS NULL OR platform_private.platform_actor_access_ready(p_actor) IS NOT TRUE
 OR public.has_role(p_actor,'administrador') IS NOT TRUE OR public.is_platform_superadmin(p_actor) IS TRUE
 THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org AND ativo IS TRUE AND status='ativa' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF p_roles IS NULL OR cardinality(p_roles) NOT BETWEEN 1 AND 3 OR array_position(p_roles,NULL) IS NOT NULL OR cardinality(p_roles)<>(SELECT count(DISTINCT r) FROM unnest(p_roles) r) OR EXISTS(SELECT 1 FROM unnest(p_roles) r WHERE r NOT IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor')) THEN RAISE EXCEPTION 'c2_invalid_roles' USING ERRCODE='22023'; END IF;
 IF p_partner IS NOT NULL THEN
 IF NOT ('parceiro_b2b'=ANY(p_roles) OR 'parceiro_b2b_tecnico'=ANY(p_roles)) THEN RAISE EXCEPTION 'c2_partner_role_required'; END IF;
 IF p_partner IS NULL OR (NOT ('cliente_produtor'=ANY(p_roles)) AND (cardinality(p_clients) IS DISTINCT FROM 0 OR p_primary IS NOT NULL))
 OR NOT EXISTS(SELECT 1 FROM platform_private.entitlements_for_user(p_actor) WHERE feature_key='catalogo_precos') THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.partner_accounts WHERE id=p_partner FOR SHARE;
 SELECT jsonb_build_object('id',id,'updated_at',updated_at) INTO partner_snapshot FROM public.partner_accounts
 WHERE id=p_partner AND commercial_owner_organization_id=org AND ativo IS TRUE AND deleted_at IS NULL;
 IF partner_snapshot IS NULL THEN RAISE EXCEPTION 'external_provisioning_forbidden'; END IF;
 END IF;
 IF 'cliente_produtor'=ANY(p_roles) THEN
 IF cardinality(p_clients) NOT BETWEEN 1 AND 100
 OR p_clients IS NULL OR array_position(p_clients,NULL) IS NOT NULL
 OR cardinality(p_clients)<>(SELECT count(DISTINCT id) FROM unnest(p_clients) id)
 OR p_primary IS NULL OR NOT (p_primary=ANY(p_clients)) THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 -- Explicit portal creation, never derive portal authority from technical user_clientes.
 PERFORM 1 FROM public.clientes WHERE id=ANY(p_clients) ORDER BY id FOR SHARE;
 IF (SELECT count(*) FROM public.clientes WHERE id=ANY(p_clients) AND organization_id=org AND status_cliente='ativo')<>cardinality(p_clients) THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',id,'updated_at',updated_at) ORDER BY id) INTO snapshot FROM public.clientes WHERE id=ANY(p_clients);
 END IF;
 IF 'cliente_produtor'=ANY(p_roles) THEN PERFORM 1 FROM public.fazendas WHERE cliente_id=ANY(p_clients) ORDER BY id FOR SHARE; END IF;
 IF platform_private.platform_actor_access_ready(p_actor) IS NOT TRUE OR public.has_role(p_actor,'administrador') IS NOT TRUE THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF 'cliente_produtor'=ANY(p_roles) AND EXISTS(SELECT 1 FROM unnest(p_clients) cid WHERE NOT EXISTS(SELECT 1 FROM public.fazendas f WHERE f.cliente_id=cid AND f.organization_id=org AND f.ativo)) THEN RAISE EXCEPTION 'c2_producer_farm_required'; END IF;
 IF p_partner IS NULL AND p_roles IS DISTINCT FROM ARRAY['cliente_produtor']::public.app_role[] THEN RAISE EXCEPTION 'c2_partner_required'; END IF;
 snapshot:=jsonb_build_object('partner',partner_snapshot,'clients',snapshot,'roles',to_jsonb(p_roles));
 IF snapshot IS NULL THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('organization_id',org,'snapshot',snapshot);
END $function$

CREATE OR REPLACE FUNCTION platform_private.b2b_claim_provisioning(p_partner uuid, p_key uuid, p_email text, p_nome text, p_roles app_role[], p_clients uuid[] DEFAULT ARRAY[]::uuid[], p_primary uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ctx jsonb; r platform_private.b2b_provisioning_receipts; stamp timestamptz; issued bigint; invitation jsonb; inserted integer;
BEGIN
 -- Same first lock as live statement triggers: gate → receipt/profile → rows.
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;

 ctx:=platform_private.external_provisioning_scope(auth.uid(),p_roles,p_partner,p_clients,p_primary);
 IF p_key IS NULL OR p_email IS NULL OR p_nome IS NULL OR length(trim(p_nome)) NOT BETWEEN 1 AND 200
 OR length(p_email)>254 OR lower(trim(p_email)) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
  RAISE EXCEPTION 'b2b_provisioning_invalid' USING ERRCODE='22023'; END IF;
 issued:=(auth.jwt()->>'iat')::bigint;
 IF issued IS NULL OR issued<=0 OR to_timestamp(issued)>clock_timestamp()+interval '1 minute' THEN
 RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 SELECT updated_at INTO STRICT stamp FROM public.profiles WHERE user_id=auth.uid() FOR UPDATE;
 PERFORM 1 FROM public.platform_org_admin_invites WHERE user_id=auth.uid() ORDER BY id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_array(id,access_operation_id,access_operation_status,status,access_valid_after) ORDER BY id),'[]'::jsonb) INTO invitation FROM public.platform_org_admin_invites WHERE user_id=auth.uid();
 INSERT INTO platform_private.b2b_provisioning_receipts(actor_id,organization_id,partner_id,idempotency_key,email,nome,actor_stamp,actor_iat,actor_invite_fence,external_role,external_roles,cliente_ids,principal_cliente_id,target_snapshot)
 VALUES(auth.uid(),(ctx->>'organization_id')::uuid,p_partner,p_key,lower(trim(p_email)),trim(p_nome),stamp,issued,invitation,p_roles[1],p_roles,p_clients,p_primary,ctx->'snapshot')
 ON CONFLICT(actor_id,idempotency_key) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 SELECT * INTO STRICT r FROM platform_private.b2b_provisioning_receipts
 WHERE actor_id=auth.uid() AND idempotency_key=p_key FOR UPDATE;
 IF ROW(r.organization_id,r.partner_id,r.email,r.nome,r.actor_stamp,r.actor_iat,r.actor_invite_fence,r.external_roles,r.cliente_ids,r.principal_cliente_id,r.target_snapshot) IS DISTINCT FROM
 ROW((ctx->>'organization_id')::uuid,p_partner,lower(trim(p_email)),trim(p_nome),stamp,issued,invitation,p_roles,p_clients,p_primary,ctx->'snapshot') THEN
  RAISE EXCEPTION 'b2b_provisioning_conflict' USING ERRCODE='42501'; END IF;
 -- Never renew/reclaim a timed-out lease: Auth may already exist. Reconcile by ID.
 RETURN jsonb_build_object('contract','C2_MULTIPROFILE_V1','external_roles',r.external_roles,'actor_id',r.actor_id,'partner_id',r.partner_id,'readers_ready',true,'provisioning_ready',true,'producer_links_valid','cliente_produtor'=ANY(r.external_roles),'claim_id',r.id,'user_id',r.user_id,'fence',r.fence,'status',r.status,
  'lease_valid',r.lease_until>clock_timestamp(),'acquired',inserted=1,'organization_id',r.organization_id);
END $function$

CREATE OR REPLACE FUNCTION public.fn_mark_entrega_not_billable(_entrega_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
BEGIN
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para marcar entrega como sem cobrança.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) = 0 THEN
    RAISE EXCEPTION 'Motivo é obrigatório.' USING ERRCODE='check_violation';
  END IF;

  SELECT * INTO v_entrega FROM public.entregas WHERE id = _entrega_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada.'; END IF;
  IF v_entrega.receivable_id IS NOT NULL THEN
    RAISE EXCEPTION 'Entrega já foi faturada.' USING ERRCODE='check_violation';
  END IF;

  UPDATE public.entregas
    SET financial_status = 'NOT_BILLABLE',
        not_billable_reason = _reason
    WHERE id = _entrega_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES ('entregas', _entrega_id, 'MARK_NOT_BILLABLE',
    jsonb_build_object('financial_status', v_entrega.financial_status),
    jsonb_build_object('financial_status', 'NOT_BILLABLE', 'reason', _reason),
    v_uid);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_scenario_coverage()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  emit public.company_fiscal_settings%ROWTYPE;
  sc record; total int := 0; covered int := 0;
  gaps jsonb := '[]'::jsonb; ref_date date := current_date;
  ok boolean; k text; kinds text[]; code text; msg text;
  rule public.fiscal_tax_rules%ROWTYPE;
  ctx jsonb; res jsonb;
  v_icms numeric; v_ipi numeric; v_st numeric; v_base_st numeric;
  n_micro_active int; n_micro_ready int; n_micro_draft int;
  n_micro_blocked int; n_micro_inactive int;
  n_ncm int; n_recip int; n_channel int;
BEGIN
  PERFORM public.h15_require_staff();

  SELECT * INTO emit FROM (SELECT * FROM public.company_fiscal_settings WHERE organization_id = public.h15_actor_organization()) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('total',0,'covered',0,'gaps',
      jsonb_build_array(jsonb_build_object('code','EMITTER_NOT_CONFIGURED','scope','EMITENTE')));
  END IF;

  -- Inventário de microrganismos: ativos, prontos, rascunhos, bloqueados, inativos.
  SELECT count(*) FILTER (WHERE coalesce(m.ativo,true)),
         count(*) FILTER (WHERE NOT coalesce(m.ativo,true))
    INTO n_micro_active, n_micro_inactive
    FROM public.microrganismos m;

  SELECT
    count(*) FILTER (WHERE coalesce(p.profile_status,'DRAFT') = 'VALIDATED'
                       AND p.accounting_validated_at IS NOT NULL
                       AND coalesce(p.is_active,false)),
    count(*) FILTER (WHERE coalesce(p.profile_status,'DRAFT') = 'BLOCKED')
    INTO n_micro_ready, n_micro_blocked
    FROM public.microorganism_fiscal_profiles p
    JOIN public.microrganismos m ON m.id = p.microorganism_id
   WHERE coalesce(m.ativo,true);

  n_micro_ready   := coalesce(n_micro_ready,0);
  n_micro_blocked := coalesce(n_micro_blocked,0);
  n_micro_draft   := greatest(coalesce(n_micro_active,0) - n_micro_ready - n_micro_blocked, 0);

  -- Cenários reais: destinatário pronto × canal realmente usado × NCM oficial vigente.
  -- Nenhum cenário artificial com NCM NULL; nenhum produto cartesiano irrelevante.
  FOR sc IN
    WITH recipients AS (
      SELECT DISTINCT
             p.customer_id,
             upper(coalesce(p.fiscal_state, emit.state)) AS dest_uf,
             coalesce(p.final_consumer,true) AS final_consumer,
             coalesce(p.taxpayer_indicator,'9') AS ind
        FROM public.customer_fiscal_profiles p
       WHERE p.nfe_readiness_status = 'READY'
    ),
    channels AS (
      SELECT DISTINCT coalesce(fi.sales_channel,'B2B_PARTNER') AS channel
        FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi
       WHERE fi.document_model = 'NFE'
      UNION
      SELECT 'B2B_PARTNER'
    ),
    ncms AS (
      SELECT DISTINCT public.fn_fiscal_digits(mp.ncm) AS ncm
        FROM public.microorganism_fiscal_profiles mp
        JOIN public.microrganismos m ON m.id = mp.microorganism_id
       WHERE coalesce(m.ativo,true)
         AND coalesce(mp.is_active,false)
         AND coalesce(mp.profile_status,'DRAFT') = 'VALIDATED'
         AND mp.accounting_validated_at IS NOT NULL
         AND nullif(btrim(coalesce(mp.ncm,'')),'') IS NOT NULL
         AND EXISTS (
           SELECT 1 FROM public.microorganism_regulatory_dossiers d
            WHERE d.microorganism_id = m.id
              AND d.deleted_at IS NULL
              AND d.status = 'VALIDATED'
              AND coalesce(d.effective_from, current_date) <= current_date
              AND (d.effective_to IS NULL OR d.effective_to >= current_date)
              AND nullif(btrim(coalesce(d.published_ncm,'')),'') IS NOT NULL)
    )
    SELECT r.dest_uf, r.final_consumer, r.ind, c.channel, n.ncm
      FROM recipients r CROSS JOIN channels c CROSS JOIN ncms n
  LOOP
    total := total + 1;
    ok := true;

    -- Política de operação
    BEGIN
      PERFORM public.fn_fiscal_resolve_operation('OUT', emit.state, sc.dest_uf, emit.crt,
        sc.final_consumer, sc.ind, sc.ncm, null, sc.channel, ref_date);
    EXCEPTION WHEN OTHERS THEN
      msg := coalesce(SQLERRM,'');
      code := CASE WHEN msg LIKE '%AMBIGUOUS%' THEN 'AMBIGUOUS' ELSE 'NOT_FOUND' END;
      ok := false;
      gaps := gaps || jsonb_build_object('scope','OPERACAO','destUf',sc.dest_uf,
        'finalConsumer',sc.final_consumer,'indIEDest',sc.ind,'channel',sc.channel,
        'ncm',sc.ncm,'code',code);
    END;

    kinds := ARRAY['ICMS']::text[];
    IF coalesce(emit.ipi_taxpayer,false) THEN kinds := array_append(kinds,'IPI'); END IF;
    IF coalesce(emit.icms_st_responsible,false) THEN kinds := array_append(kinds,'ICMS_ST'); END IF;
    IF coalesce(emit.fcp_applicable,false) THEN
      kinds := array_append(kinds,'FCP');
      IF coalesce(emit.icms_st_responsible,false) THEN kinds := array_append(kinds,'FCP_ST'); END IF;
    END IF;
    IF coalesce(emit.difal_responsible,false) AND sc.dest_uf <> upper(coalesce(emit.state,''))
       AND sc.final_consumer THEN kinds := array_append(kinds,'DIFAL'); END IF;
    kinds := kinds || ARRAY['PIS','COFINS']::text[];

    -- Contexto sintético NEUTRO, encadeado como no motor real. Sem persistência.
    v_icms := 0; v_ipi := 0; v_st := 0; v_base_st := NULL;

    FOREACH k IN ARRAY kinds LOOP
      code := NULL;
      BEGIN
        rule := public.fn_fiscal_resolve_tax_rule(k, emit.crt, emit.state, sc.dest_uf,
          sc.ncm, null, sc.final_consumer, sc.ind, ref_date);
      EXCEPTION WHEN OTHERS THEN
        msg := coalesce(SQLERRM,'');
        code := CASE
          WHEN msg LIKE '%ENGINE_UNAVAILABLE%' THEN 'ENGINE_UNAVAILABLE'
          WHEN msg LIKE '%AMBIGUOUS%'          THEN 'AMBIGUOUS'
          WHEN msg LIKE '%NOT_FOUND%'          THEN 'NOT_FOUND'
          ELSE 'INCOMPLETE' END;
      END;

      IF code IS NULL THEN
        ctx := jsonb_build_object(
          'produto', 1000, 'frete', 0, 'seguro', 0, 'outras', 0, 'desconto', 0,
          'ipi', v_ipi, 'icmsSt', v_st, 'icmsOwnValue', v_icms, 'baseST', v_base_st);
        code := public.fn_fiscal_rule_validate_synthetic(k, rule, ctx);

        IF code = 'OK' THEN
          BEGIN
            res := public.fn_fiscal_apply_tax_v2(rule, ctx);
            IF k = 'ICMS'    THEN v_icms := (res->>'value')::numeric; END IF;
            IF k = 'IPI'     THEN v_ipi  := (res->>'value')::numeric; END IF;
            IF k = 'ICMS_ST' THEN
              v_st := (res->>'value')::numeric;
              v_base_st := (res->'params'->>'baseST')::numeric;
            END IF;
          EXCEPTION WHEN OTHERS THEN
            code := 'INCOMPLETE';
          END;
        END IF;
      END IF;

      IF code <> 'OK' THEN
        ok := false;
        gaps := gaps || jsonb_build_object('scope','TRIBUTO','taxKind',k,'destUf',sc.dest_uf,
          'channel',sc.channel,'ncm',sc.ncm,'code',code);
      END IF;
    END LOOP;

    IF ok THEN covered := covered + 1; END IF;
  END LOOP;

  SELECT count(DISTINCT customer_id) INTO n_recip
    FROM public.customer_fiscal_profiles WHERE nfe_readiness_status = 'READY';

  n_channel := (SELECT count(*) FROM (
                  SELECT DISTINCT coalesce(fi.sales_channel,'B2B_PARTNER') ch
                    FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi WHERE fi.document_model='NFE'
                  UNION SELECT 'B2B_PARTNER') q);

  n_ncm := CASE WHEN coalesce(n_recip,0) = 0 OR coalesce(n_channel,0) = 0
                THEN 0 ELSE total / greatest(n_recip * n_channel, 1) END;

  RETURN jsonb_build_object(
    'total', total, 'covered', covered,
    'dimensions', jsonb_build_object(
      'readyRecipients', coalesce(n_recip,0),
      'activeChannels', coalesce(n_channel,0),
      'officialNcms', coalesce(n_ncm,0)),
    'microorganisms', jsonb_build_object(
      'active', coalesce(n_micro_active,0),
      'ready', n_micro_ready,
      'draft', n_micro_draft,
      'blocked', n_micro_blocked,
      'inactive', coalesce(n_micro_inactive,0)),
    'gapCodes', jsonb_build_array('NOT_FOUND','AMBIGUOUS','INCOMPLETE','ENGINE_UNAVAILABLE'),
    'gaps', (SELECT coalesce(jsonb_agg(DISTINCT g),'[]'::jsonb) FROM jsonb_array_elements(gaps) g));
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_partner_lifecycle(p_partner_id uuid, p_user_id uuid, p_roles text[], p_action text, p_expected text, p_key uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 actor uuid:=auth.uid(); org uuid; before_state jsonb; after_state jsonb;
 existing_receipt record; fingerprint text; requested text[]; current_roles text[];
 link public.partner_users%ROWTYPE; result jsonb; partner_owner uuid;
BEGIN
 -- Authority is ALWAYS the caller subject, never a payload actor or owner.
 IF actor IS NULL OR actor=p_user_id OR p_partner_id IS NULL OR p_user_id IS NULL
 OR platform_private.platform_actor_access_ready(actor) IS NOT TRUE
 OR public.has_role(actor,'administrador'::public.app_role) IS NOT TRUE
 OR public.is_platform_superadmin(actor) IS TRUE
 OR public.is_platform_superadmin(p_user_id) IS TRUE THEN
  RAISE EXCEPTION 'c2_forbidden' USING ERRCODE='42501'; END IF;
 org:=public.h15_actor_organization();
 IF org IS NULL OR p_key IS NULL OR p_expected IS NULL
 OR length(p_expected)<>32 OR p_expected !~ '^[a-f0-9]{32}$'
 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 2 AND 500
 OR p_action IS NULL OR p_action NOT IN ('assign','revoke_roles','unlink','reactivate')
 OR p_roles IS NULL OR array_position(p_roles,NULL) IS NOT NULL
 OR EXISTS(SELECT 1 FROM unnest(p_roles) r WHERE r NOT IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor'))
 OR cardinality(p_roles)<>(SELECT count(DISTINCT r) FROM unnest(p_roles) r) THEN
  RAISE EXCEPTION 'c2_invalid_input' USING ERRCODE='22023'; END IF;
 SELECT array_agg(r ORDER BY r) INTO requested FROM unnest(p_roles) r;
 requested:=COALESCE(requested,ARRAY[]::text[]);
 fingerprint:=md5(jsonb_build_object('partner',p_partner_id,'user',p_user_id,
   'roles',requested,'action',p_action,'expected',p_expected,'reason',btrim(p_reason))::text);
 -- Preauthorization before waiting. Historical revoked links are still editable
 -- by their proven owner, but never usable to authorize portal data.
 IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id
   WHERE p.user_id=p_user_id AND p.organization_id=org AND p.ativo AND o.ativo AND o.status='ativa'
   AND platform_private.platform_actor_access_ready(p.user_id))
 OR NOT EXISTS(SELECT 1 FROM public.partner_accounts pa JOIN public.organizations o ON o.id=pa.commercial_owner_organization_id
   WHERE pa.id=p_partner_id AND pa.commercial_owner_organization_id=org AND pa.ativo
   AND pa.deleted_at IS NULL AND o.ativo AND o.status='ativa') THEN
  RAISE EXCEPTION 'c2_forbidden' USING ERRCODE='42501'; END IF;
 -- Same lock order as the existing statement gate, BEFORE profile/role/link locks.
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'c2_guard_unavailable' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR SHARE;
 PERFORM 1 FROM public.partner_accounts WHERE id=p_partner_id FOR SHARE;
 PERFORM 1 FROM public.profiles WHERE user_id IN(actor,p_user_id) ORDER BY user_id FOR UPDATE;
 PERFORM 1 FROM public.user_roles WHERE user_id IN(actor,p_user_id) ORDER BY user_id,role FOR UPDATE;
 SELECT * INTO link FROM public.partner_users WHERE user_id=p_user_id FOR UPDATE;
 IF link.id IS NOT NULL AND (link.partner_id IS DISTINCT FROM p_partner_id OR link.tenant_id IS DISTINCT FROM org) THEN
  RAISE EXCEPTION 'c2_cross_partner' USING ERRCODE='42501'; END IF;
 SELECT commercial_owner_organization_id INTO partner_owner FROM public.partner_accounts WHERE id=p_partner_id AND ativo AND deleted_at IS NULL;
 IF partner_owner IS DISTINCT FROM org OR public.h15_actor_organization() IS DISTINCT FROM org
 OR platform_private.platform_actor_access_ready(actor) IS NOT TRUE
 OR public.has_role(actor,'administrador'::public.app_role) IS NOT TRUE
 OR public.is_platform_superadmin(actor) OR public.is_platform_superadmin(p_user_id)
 OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_user_id AND organization_id=org AND ativo
   AND platform_private.platform_actor_access_ready(user_id))
 OR NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=org AND ativo AND status='ativa') THEN
  RAISE EXCEPTION 'c2_forbidden' USING ERRCODE='42501'; END IF;
 -- Replay before state/roles validation: a subsequent revocation cannot cause
 -- the same committed attempt to grant again or become a false conflict.
 SELECT * INTO existing_receipt FROM public.partner_audit_logs
  WHERE acao='c2_partner_lifecycle' AND usuario_id=actor
    AND dados_novos->>'key'=p_key::text LIMIT 1;
 IF FOUND THEN
  IF existing_receipt.dados_novos->>'fingerprint' IS DISTINCT FROM fingerprint THEN
   RAISE EXCEPTION 'c2_replay_conflict' USING ERRCODE='PT409'; END IF;
  RETURN existing_receipt.dados_novos->'receipt';
 END IF;
 SELECT COALESCE(array_agg(role::text ORDER BY role::text),ARRAY[]::text[]) INTO current_roles FROM public.user_roles WHERE user_id=p_user_id;
 IF EXISTS(SELECT 1 FROM unnest(current_roles) r WHERE r NOT IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor')) THEN
  RAISE EXCEPTION 'c2_internal_identity_closed' USING ERRCODE='42501'; END IF;
 before_state:=jsonb_build_object('user',p_user_id,'partner',p_partner_id,'org',org,
   'roles',current_roles,'link',CASE WHEN link.id IS NULL THEN NULL ELSE to_jsonb(link) END,
   'profile_stamp',(SELECT updated_at FROM public.profiles WHERE user_id=p_user_id));
 IF md5(before_state::text)<>p_expected THEN RAISE EXCEPTION 'c2_version_conflict' USING ERRCODE='PT409'; END IF;
 IF p_action IN ('unlink','reactivate') AND requested IS DISTINCT FROM current_roles THEN
  RAISE EXCEPTION 'c2_roles_must_be_preserved' USING ERRCODE='22023'; END IF;
 IF p_action='revoke_roles' AND EXISTS(SELECT 1 FROM unnest(requested) r WHERE NOT r=ANY(current_roles)) THEN
  RAISE EXCEPTION 'c2_revocation_cannot_grant' USING ERRCODE='42501'; END IF;
 IF p_action='assign' AND link.id IS NOT NULL AND link.revoked_at IS NOT NULL THEN
  RAISE EXCEPTION 'c2_explicit_reactivation_required' USING ERRCODE='42501'; END IF;
 IF p_action IN ('unlink','reactivate') AND link.id IS NULL THEN
  RAISE EXCEPTION 'c2_link_missing' USING ERRCODE='22023'; END IF;
 IF p_action='reactivate' AND link.revoked_at IS NULL THEN
  RAISE EXCEPTION 'c2_not_revoked' USING ERRCODE='22023'; END IF;
 -- This slice does not create/transfer clients or adopt an Auth identity.
 -- Producer requires an explicit live client AND property, never UUID alone.
 IF 'cliente_produtor'=ANY(requested) AND p_action='assign' THEN
  PERFORM 1 FROM public.user_clientes WHERE user_id=p_user_id ORDER BY id FOR SHARE;
  PERFORM 1 FROM public.clientes c WHERE EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p_user_id AND uc.cliente_id=c.id) ORDER BY c.id FOR SHARE;
  PERFORM 1 FROM public.fazendas f WHERE EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p_user_id AND uc.cliente_id=f.cliente_id) ORDER BY f.id FOR SHARE;
  IF NOT EXISTS(SELECT 1 FROM public.user_clientes uc JOIN public.clientes c ON c.id=uc.cliente_id
    JOIN public.fazendas f ON f.cliente_id=c.id
    WHERE uc.user_id=p_user_id AND uc.is_active AND uc.revoked_at IS NULL
      AND uc.valid_from<=now() AND (uc.valid_until IS NULL OR uc.valid_until>=now())
      AND c.organization_id=org AND c.status_cliente='ativo'
      AND f.organization_id=org AND f.ativo) THEN
   RAISE EXCEPTION 'c2_producer_link_required' USING ERRCODE='42501'; END IF;
 END IF;
 IF p_action='assign' AND link.id IS NULL AND NOT ('parceiro_b2b'=ANY(requested) OR 'parceiro_b2b_tecnico'=ANY(requested)) THEN
  RAISE EXCEPTION 'c2_partner_role_required' USING ERRCODE='22023'; END IF;
 IF p_action IN ('assign','revoke_roles') THEN
  DELETE FROM public.user_roles WHERE user_id=p_user_id AND role::text=ANY(current_roles) AND NOT role::text=ANY(requested);
  INSERT INTO public.user_roles(user_id,role) SELECT p_user_id,r::public.app_role FROM unnest(requested) r
   WHERE NOT r=ANY(current_roles) ON CONFLICT(user_id,role) DO NOTHING;
 END IF;
 IF p_action='assign' AND link.id IS NULL THEN
  INSERT INTO public.partner_users(user_id,partner_id,papel,tenant_id)
   VALUES(p_user_id,p_partner_id,CASE WHEN 'parceiro_b2b'=ANY(requested) THEN 'gestor' ELSE 'tecnico' END,org);
 ELSIF p_action IN ('assign','revoke_roles') AND link.id IS NOT NULL
   AND ('parceiro_b2b'=ANY(requested) OR 'parceiro_b2b_tecnico'=ANY(requested)) THEN
  UPDATE public.partner_users SET papel=CASE WHEN 'parceiro_b2b'=ANY(requested) THEN 'gestor' ELSE 'tecnico' END WHERE id=link.id;
 ELSIF p_action='unlink' THEN
  UPDATE public.partner_users SET revoked_at=clock_timestamp(),revoked_by=actor,revoke_reason=btrim(p_reason) WHERE id=link.id AND revoked_at IS NULL;
 ELSIF p_action='reactivate' THEN
  UPDATE public.partner_users SET revoked_at=NULL,revoked_by=NULL,revoke_reason=NULL,valid_from=clock_timestamp() WHERE id=link.id;
 END IF;
 -- No role INSERT on reactivation/unlink. Independent producer remains untouched.
 SELECT jsonb_build_object('user',p_user_id,'partner',p_partner_id,'org',org,'roles',requested,
   'link',(SELECT to_jsonb(pu) FROM public.partner_users pu WHERE pu.user_id=p_user_id),
   'profile_stamp',(SELECT updated_at FROM public.profiles WHERE user_id=p_user_id)) INTO after_state;
 result:=jsonb_build_object('ok',true,'user_id',p_user_id,'partner_id',p_partner_id,
   'version',md5(after_state::text),'action',p_action,'reader_activation',false);
 INSERT INTO public.partner_audit_logs(partner_id,usuario_id,acao,dados_anteriores,dados_novos)
 VALUES(p_partner_id,actor,'c2_partner_lifecycle',before_state,
   jsonb_build_object('key',p_key,'fingerprint',fingerprint,'reason',btrim(p_reason),'state',after_state,'receipt',result));
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION platform_private.lab_partner_order_authorized(p_order_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_org uuid;
BEGIN
 IF v_uid IS NULL OR NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN RETURN false; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.partner_orders o JOIN public.partner_accounts p ON p.id=o.partner_id
 WHERE o.id=p_order_id AND p.commercial_owner_organization_id=v_org AND p.ativo IS TRUE AND p.deleted_at IS NULL
 AND (p.client_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=p.client_id AND c.organization_id=v_org)));
END $function$

CREATE OR REPLACE FUNCTION public.fn_run_financial_inconsistency_check()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rows jsonb;
  v_count integer;
  v_by_severity jsonb;
  v_sample jsonb;
  v_alert_id uuid;
BEGIN
  SELECT COALESCE(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
    INTO v_rows
    FROM public.fn_financial_inconsistencies() r;

  v_count := jsonb_array_length(v_rows);

  IF v_count = 0 THEN
    INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
    VALUES ('system', gen_random_uuid(), 'inconsistency_check',
            jsonb_build_object('count', 0, 'run_at', now()), NULL);
    RETURN NULL;
  END IF;

  SELECT jsonb_object_agg(severity, qtd)
    INTO v_by_severity
    FROM (
      SELECT (elem->>'severity') AS severity, count(*)::int AS qtd
        FROM jsonb_array_elements(v_rows) elem
       GROUP BY 1
    ) s;

  SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
    INTO v_sample
    FROM (
      SELECT elem FROM jsonb_array_elements(v_rows) elem LIMIT 10
    ) t;

  INSERT INTO public.financial_inconsistency_alerts (total_count, by_severity, sample)
  VALUES (v_count, COALESCE(v_by_severity, '{}'::jsonb), v_sample)
  RETURNING id INTO v_alert_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('financial_inconsistency_alerts', v_alert_id, 'inconsistency_check',
          jsonb_build_object('count', v_count, 'by_severity', v_by_severity), NULL);

  RETURN v_alert_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_revert_recurring_generation(p_log_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log public.recurring_generation_log%ROWTYPE;
  v_status TEXT;
BEGIN
  -- 1. Verifica permissão
  IF NOT public.is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  -- 2. Busca o log
  SELECT * INTO v_log FROM public.recurring_generation_log l WHERE l.id = p_log_id
    AND EXISTS (SELECT 1 FROM public.recurring_financial_templates t WHERE t.id=l.template_id
      AND t.organization_id=platform_private.h15_actor_organization()) FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Log de geração não encontrado';
  END IF;

  IF v_log.status <> 'SUCCESS' THEN
    RAISE EXCEPTION 'Apenas gerações com sucesso podem ser revertidas';
  END IF;

  -- 3. Verifica se o título gerado ainda pode ser excluído (status deve ser OPEN)
  IF v_log.generated_entity_type = 'RECEIVABLE' THEN
    SELECT status INTO v_status FROM public.accounts_receivable WHERE id = v_log.generated_entity_id;
    IF v_status <> 'OPEN' THEN
      RAISE EXCEPTION 'Título de receita não pode ser revertido pois não está mais Aberto (Status: %)', v_status;
    END IF;

    -- Deleta o título (o trigger de auditoria do accounts_receivable cuidará do log de DELETE)
    DELETE FROM public.accounts_receivable WHERE id = v_log.generated_entity_id;

  ELSIF v_log.generated_entity_type = 'PAYABLE' THEN
    SELECT status INTO v_status FROM public.accounts_payable WHERE id = v_log.generated_entity_id;
    IF v_status <> 'OPEN' THEN
      RAISE EXCEPTION 'Título de despesa não pode ser revertido pois não está mais Aberto (Status: %)', v_status;
    END IF;

    DELETE FROM public.accounts_payable WHERE id = v_log.generated_entity_id;
  END IF;

  -- 4. Log de auditoria da reversão
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, old_data, performed_by, reason)
  VALUES ('RECURRING_TEMPLATE', v_log.template_id, 'RECURRING_GENERATION_REVERSED', to_jsonb(v_log), auth.uid(), 'Reversão manual solicitada pelo gestor');

  -- 5. Remove o log para permitir nova geração na mesma data (o trigger de log_audit registrará DELETED)
  DELETE FROM public.recurring_generation_log WHERE id = p_log_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.fn_reverse_payment(_payment_id uuid, _kind text, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := platform_private.h15_actor_organization();
  v_new_id uuid;
  v_row record;
  v_inst_status text;
  v_prev record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão obrigatória.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Apenas administrador, gestor ou financeiro podem estornar uma baixa.'
      USING ERRCODE='insufficient_privilege';
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) < 5 THEN
    RAISE EXCEPTION 'Informe um motivo (mín. 5 caracteres) para o estorno.'
      USING ERRCODE='check_violation';
  END IF;
  IF _kind IS NULL OR _kind NOT IN ('receivable','payable') THEN
    RAISE EXCEPTION 'Tipo inválido: %', _kind;
  END IF;

  IF v_org IS NULL THEN RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
  IF _kind='receivable' THEN
    IF NOT EXISTS (SELECT 1 FROM public.receivable_payments WHERE id=_payment_id AND organization_id=v_org) THEN
      RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.payable_payments WHERE id=_payment_id AND organization_id=v_org) THEN
      RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
  END IF;
  -- lock determinístico por intencao de reversao (mesma baixa original)
  PERFORM pg_advisory_xact_lock(hashtextextended('fin_reverse:' || _kind || ':' || _payment_id::text, 0));

  IF _kind = 'receivable' THEN
    SELECT * INTO v_row FROM public.receivable_payments WHERE id = _payment_id AND organization_id=v_org FOR UPDATE;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'Pagamento não encontrado.'; END IF;
    IF v_row.is_reversal THEN RAISE EXCEPTION 'Não é possível estornar um registro de estorno.'; END IF;

    -- replay estavel: mesma intencao -> devolve reversao existente
    SELECT id, reversal_reason INTO v_prev FROM public.receivable_payments
     WHERE reversed_payment_id = _payment_id AND is_reversal = true;
    IF v_prev.id IS NOT NULL THEN
      IF trim(COALESCE(v_prev.reversal_reason,'')) IS DISTINCT FROM trim(_reason) THEN
        RAISE EXCEPTION 'FIN_IDEMPOTENCY_CONFLICT: baixa já estornada com motivo divergente.'
          USING ERRCODE='check_violation';
      END IF;
      RETURN v_prev.id;
    END IF;

    SELECT status INTO v_inst_status FROM public.accounts_receivable_installments WHERE id = v_row.installment_id;
    IF v_inst_status = 'CANCELED' THEN
      RAISE EXCEPTION 'Não é possível estornar baixa de parcela cancelada.';
    END IF;

    INSERT INTO public.receivable_payments(
      organization_id, installment_id, payment_date, payment_method_id, bank_account_id,
      amount_received, discount_amount, interest_amount, penalty_amount,
      notes, created_by, is_reversal, reversed_payment_id, reversal_reason
    ) VALUES (
      v_org, v_row.installment_id, (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date, v_row.payment_method_id, v_row.bank_account_id,
      -v_row.amount_received, -COALESCE(v_row.discount_amount,0),
      -COALESCE(v_row.interest_amount,0), -COALESCE(v_row.penalty_amount,0),
      '[ESTORNO] '||_reason, v_uid, true, _payment_id, _reason
    ) RETURNING id INTO v_new_id;

  ELSE
    SELECT * INTO v_row FROM public.payable_payments WHERE id = _payment_id AND organization_id=v_org FOR UPDATE;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'Pagamento não encontrado.'; END IF;
    IF v_row.is_reversal THEN RAISE EXCEPTION 'Não é possível estornar um registro de estorno.'; END IF;

    SELECT id, reversal_reason INTO v_prev FROM public.payable_payments
     WHERE reversed_payment_id = _payment_id AND is_reversal = true;
    IF v_prev.id IS NOT NULL THEN
      IF trim(COALESCE(v_prev.reversal_reason,'')) IS DISTINCT FROM trim(_reason) THEN
        RAISE EXCEPTION 'FIN_IDEMPOTENCY_CONFLICT: baixa já estornada com motivo divergente.'
          USING ERRCODE='check_violation';
      END IF;
      RETURN v_prev.id;
    END IF;

    SELECT status INTO v_inst_status FROM public.accounts_payable_installments WHERE id = v_row.installment_id;
    IF v_inst_status = 'CANCELED' THEN
      RAISE EXCEPTION 'Não é possível estornar baixa de parcela cancelada.';
    END IF;

    INSERT INTO public.payable_payments(
      organization_id, installment_id, payment_date, payment_method_id, bank_account_id,
      amount_paid, discount_amount, interest_amount, penalty_amount,
      notes, created_by, is_reversal, reversed_payment_id, reversal_reason
    ) VALUES (
      v_org, v_row.installment_id, (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date, v_row.payment_method_id, v_row.bank_account_id,
      -v_row.amount_paid, -COALESCE(v_row.discount_amount,0),
      -COALESCE(v_row.interest_amount,0), -COALESCE(v_row.penalty_amount,0),
      '[ESTORNO] '||_reason, v_uid, true, _payment_id, _reason
    ) RETURNING id INTO v_new_id;
  END IF;

  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
  VALUES (
    CASE WHEN _kind='receivable' THEN 'receivable_payments' ELSE 'payable_payments' END,
    v_new_id, 'PAYMENT_REVERSAL_CREATED',
    jsonb_build_object('reversed_payment_id', _payment_id, 'reason', _reason),
    v_uid
  );

  RETURN v_new_id;
END $function$

CREATE OR REPLACE FUNCTION public.publish_planning_to_lab(p_planning_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pl public.production_planning%ROWTYPE;
  v_result jsonb;
  v_count int;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
  IF NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT * INTO v_pl FROM public.production_planning WHERE id = p_planning_id FOR UPDATE;
  IF v_pl.id IS NULL THEN RAISE EXCEPTION 'planning_not_found'; END IF;

  IF v_pl.status IN ('em_producao','produzido','entregue') THEN
    RAISE EXCEPTION 'already_published';
  END IF;

  IF v_pl.planned_start_date IS NOT NULL AND v_pl.planned_finish_date IS NOT NULL
     AND v_pl.planned_finish_date < v_pl.planned_start_date THEN
    RAISE EXCEPTION 'invalid_dates';
  END IF;

  PERFORM public._validate_planning_integrity(v_pl.partner_order_id);

  v_result := public.generate_production_orders_from_partner(v_pl.partner_order_id);
  v_count := COALESCE((v_result->>'os_created')::int, 0);

  IF v_count = 0 AND NOT EXISTS (
    SELECT 1 FROM public.production_order_link WHERE planning_id = v_pl.id
  ) THEN
    RAISE EXCEPTION 'LAB_NO_MANUFACTURABLE_ITEMS' USING ERRCODE='23514', HINT='Químicos e fertilizantes permanecem no catálogo e nas solicitações, sem fabricação.';
  END IF;

  INSERT INTO public.laboratorio_esteira_eventos (os_id, origem_os, acao, etapa_nova, usuario_id, observacao)
  SELECT os.id, COALESCE(os.origem,'b2b'), 'demanda_publicada', 'recebido_no_lab', v_uid,
         'Planejamento publicado no Cockpit'
  FROM public.ordens_servico os
  WHERE os.partner_order_id = v_pl.partner_order_id
    AND platform_private.lab_item_is_manufacturable(os.produto_id,os.microrganismo_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.laboratorio_esteira_eventos e
      WHERE e.os_id = os.id AND e.acao = 'demanda_publicada'
    );

  -- Advance OS status aprovada -> programada so the treadmill transitions are valid.
  UPDATE public.ordens_servico
     SET status = 'programada'
   WHERE partner_order_id = v_pl.partner_order_id
     AND status::text = 'aprovada'
     AND platform_private.lab_item_is_manufacturable(produto_id,microrganismo_id);

  UPDATE public.production_planning
     SET status = 'planejado', updated_at = now()
   WHERE id = v_pl.id AND status IN ('aguardando_planejamento','replanejar');

  INSERT INTO public.production_timeline_events (partner_order_id, event_type, actor_id, meta)
  VALUES (v_pl.partner_order_id, 'planejamento_publicado', v_uid,
          jsonb_build_object('planning_id', v_pl.id, 'os_created', v_count));

  INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_pl.partner_order_id, v_pl.partner_id, v_uid, 'planejamento_publicado',
          jsonb_build_object('planning_id', v_pl.id, 'os_created', v_count));

  PERFORM public.refresh_esteira_laboratorio();

  RETURN jsonb_build_object('ok', true, 'planning_id', v_pl.id, 'os_created', v_count,'non_lab_items',v_result->'non_lab_items');
END
$function$

CREATE OR REPLACE FUNCTION public.trg_os_sync_partner_order_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_partner_order_id uuid; v_total int; v_done int; v_in_prod int;
 v_new_status public.partner_order_status; v_old_status public.partner_order_status; v_nonlab int;
BEGIN
 v_partner_order_id:=coalesce(NEW.partner_order_id,OLD.partner_order_id);
 IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
 SELECT count(*),count(*) FILTER(WHERE status IN ('pronto_entrega','entregue','finalizada')),
 count(*) FILTER(WHERE status IN ('em_producao','em_cq','envase','programada')) INTO v_total,v_done,v_in_prod
 FROM public.ordens_servico WHERE partner_order_id=v_partner_order_id;
 SELECT count(*) INTO v_nonlab FROM public.partner_order_items i WHERE i.order_id=v_partner_order_id
 AND NOT platform_private.lab_item_is_manufacturable(i.product_id,i.microrganismo_id);
 SELECT status INTO v_old_status FROM public.partner_orders WHERE id=v_partner_order_id;
 IF v_total>0 AND v_done=v_total AND v_nonlab=0 THEN v_new_status:='produzido';
 ELSIF v_in_prod>0 THEN v_new_status:='em_producao';
 ELSE v_new_status:=v_old_status; END IF;
 -- Pedido misto nunca é declarado integralmente produzido apenas por conclusão das OS biológicas.
 IF v_new_status IS DISTINCT FROM v_old_status THEN
  UPDATE public.partner_orders SET status=v_new_status,updated_at=now() WHERE id=v_partner_order_id;
  UPDATE public.production_planning SET status=v_new_status::text::public.production_planning_status,updated_at=now() WHERE partner_order_id=v_partner_order_id;
  INSERT INTO public.production_timeline_events(partner_order_id,event_type,meta) VALUES(v_partner_order_id,
  CASE WHEN v_new_status='produzido' THEN 'producao_finalizada' ELSE 'producao_iniciada' END,jsonb_build_object('from',v_old_status,'to',v_new_status));
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.lab_visit_recommendation_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid; v_status text;
BEGIN
 FOR v_id IN SELECT DISTINCT id FROM unnest(ARRAY[
   CASE WHEN TG_OP<>'INSERT' THEN OLD.registro_consultor_id END,
   CASE WHEN TG_OP<>'DELETE' THEN NEW.registro_consultor_id END]) id WHERE id IS NOT NULL ORDER BY id LOOP
   SELECT status::text INTO v_status FROM public.registros_consultor WHERE id=v_id FOR UPDATE;
   IF v_status='convertido_os' THEN RAISE EXCEPTION 'VISIT07_REVIEW_REQUIRED' USING ERRCODE='23514',HINT='Visita já encaminhada; preserve a seleção e revise pelo fluxo técnico autorizado.'; END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.generate_production_orders_from_partner(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_planning_id uuid;
  v_partner_id uuid;
  v_order_numero text;
  v_order_status text;
  v_ready boolean;
  v_partner_nome text;
  v_grp RECORD;
  v_item RECORD;
  v_os_id uuid;
  v_numero text;
  v_count int := 0;
  v_nonlab_count int := 0;
  v_uid uuid := auth.uid();
  v_ids uuid[] := ARRAY[]::uuid[];
  v_anchor_item_id uuid;
BEGIN
 IF NOT platform_private.lab_partner_order_authorized(p_partner_order_id) THEN
  RAISE EXCEPTION 'LAB_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND internal_origin_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'B2B_INTERNAL_DOWNSTREAM_UNVERIFIED' USING ERRCODE='42501'; END IF;

  -- H5-B01: serializa geração concorrente por pedido (idempotência de resultado)
  PERFORM pg_advisory_xact_lock(hashtext('generate_production_orders_from_partner:' || p_partner_order_id::text));

  SELECT po.partner_id, po.numero, po.status::text, po.ready_for_production
    INTO v_partner_id, v_order_numero, v_order_status, v_ready
  FROM public.partner_orders po
  WHERE po.id = p_partner_order_id;

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'Pedido B2B não encontrado';
  END IF;

  IF v_order_status IN ('cancelado','reprovado','faturado','entregue') THEN
    RAISE EXCEPTION 'Pedido B2B não pode gerar produção (status: %)', v_order_status;
  END IF;

  -- Fase 7: bloqueia produção enquanto aprovação financeira exigida está pendente/rejeitada
   IF EXISTS (
     SELECT 1 FROM public.partner_orders po2
     WHERE po2.id = p_partner_order_id
       AND po2.requires_financial_approval = true
       AND po2.financial_approval_status IN ('pending','rejected')
   ) THEN
     RAISE EXCEPTION 'financial_approval_required_before_production';
   END IF;

   IF v_order_status <> 'aprovado' OR v_ready IS NOT TRUE THEN
    RAISE EXCEPTION 'Pedido B2B ainda não está aprovado para produção.';
  END IF;

  SELECT id INTO v_planning_id FROM public.production_planning WHERE partner_order_id = p_partner_order_id;
  IF v_planning_id IS NULL THEN
    RAISE EXCEPTION 'Planejamento não encontrado para o pedido %', p_partner_order_id;
  END IF;

  SELECT COALESCE(nome_fantasia, razao_social) INTO v_partner_nome FROM public.partner_accounts WHERE id = v_partner_id;

  SELECT count(*) INTO v_nonlab_count FROM public.partner_order_items poi
   WHERE poi.order_id=p_partner_order_id
     AND NOT platform_private.lab_item_is_manufacturable(poi.product_id,poi.microrganismo_id);

  FOR v_grp IN
    WITH itens AS (
      SELECT poi.id,
             poi.product_id,
             poi.quantidade,
             COALESCE(poi.unidade_medida,'unidade') AS unidade_medida,
             poi.preco_tabela_snapshot,
             poi.preco_unitario,
             poi.produto_nome_snapshot,
             poi.produto_codigo_snapshot,
             poi.created_at,
             cv.volume_ml AS vasilhame_volume_ml
      FROM public.partner_order_items poi
      LEFT JOIN LATERAL (
        SELECT cv2.volume_ml
          FROM public.catalogo_volumes cv2
         WHERE cv2.item_tipo = 'produto'
           AND cv2.produto_id = poi.product_id
           AND cv2.ativo = true
         ORDER BY (cv2.preco_brl = COALESCE(poi.preco_tabela_snapshot, poi.preco_unitario)) DESC,
                  ABS(cv2.preco_brl - COALESCE(poi.preco_tabela_snapshot, poi.preco_unitario)) ASC
         LIMIT 1
      ) cv ON true
      WHERE poi.order_id = p_partner_order_id
        AND poi.product_id IS NOT NULL
        AND platform_private.lab_item_is_manufacturable(poi.product_id,poi.microrganismo_id)
        AND COALESCE(poi.unidade_medida,'unidade') <> 'hectare'
        AND NOT EXISTS (
          SELECT 1 FROM public.production_order_link l WHERE l.partner_order_item_id = poi.id
        )
    )
    SELECT product_id,
           MIN(produto_nome_snapshot) AS produto_nome,
           MIN(produto_codigo_snapshot) AS produto_codigo,
           SUM(
             CASE unidade_medida
               WHEN 'ml'    THEN quantidade
               WHEN 'litro' THEN quantidade * 1000
               WHEN 'unidade' THEN quantidade * vasilhame_volume_ml
               WHEN 'dose'    THEN quantidade * vasilhame_volume_ml
               ELSE NULL
             END
           ) AS volume_total_ml,
           bool_or(
             unidade_medida IN ('unidade','dose') AND vasilhame_volume_ml IS NULL
           ) AS faltou_vasilhame,
           array_agg(id ORDER BY created_at, id) AS item_ids,
           (array_agg(id ORDER BY created_at, id))[1] AS anchor_id
    FROM itens
    GROUP BY product_id
  LOOP
    IF v_grp.faltou_vasilhame THEN
      RAISE EXCEPTION 'Produto % (%) está em unidade/dose mas não tem vasilhame ativo no catálogo. Configure o vasilhame antes de gerar produção.',
        COALESCE(v_grp.produto_nome,'?'), COALESCE(v_grp.produto_codigo,'?');
    END IF;

    IF v_grp.volume_total_ml IS NULL OR v_grp.volume_total_ml <= 0 THEN
      RAISE EXCEPTION 'Não foi possível calcular o volume do produto % (%).',
        COALESCE(v_grp.produto_nome,'?'), COALESCE(v_grp.produto_codigo,'?');
    END IF;

    v_anchor_item_id := v_grp.anchor_id;
    v_numero := 'OS-B2B-' || to_char(now(),'YYYYMMDD') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,6);

    INSERT INTO public.ordens_servico (
      cliente_id, fazenda_id, talhao_id, produto_id, volume_total_ml, area_hectares,
      prioridade, status, tipo_item, numero_os,
      partner_order_id, partner_order_item_id, origem
    ) VALUES (
      NULL, NULL, NULL, v_grp.product_id, v_grp.volume_total_ml, NULL,
      'media','aberta','produto', v_numero,
      p_partner_order_id, v_anchor_item_id, 'b2b'
    ) RETURNING id INTO v_os_id;

    INSERT INTO public.production_order_link (
      partner_order_id, partner_order_item_id, planning_id, ordem_servico_id, created_by
    )
    SELECT p_partner_order_id, unnest(v_grp.item_ids), v_planning_id, v_os_id, v_uid;

    v_ids := array_append(v_ids, v_os_id);
    v_count := v_count + 1;
  END LOOP;

  FOR v_item IN
    SELECT poi.* FROM public.partner_order_items poi
    WHERE poi.order_id = p_partner_order_id
      AND platform_private.lab_item_is_manufacturable(poi.product_id,poi.microrganismo_id)
      AND NOT EXISTS (SELECT 1 FROM public.production_order_link l WHERE l.partner_order_item_id = poi.id)
      AND (
        poi.product_id IS NULL
        OR COALESCE(poi.unidade_medida,'unidade') = 'hectare'
      )
  LOOP
    v_numero := 'OS-B2B-' || to_char(now(),'YYYYMMDD') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,6);

    INSERT INTO public.ordens_servico (
      cliente_id, fazenda_id, talhao_id, produto_id, microrganismo_id, volume_total_ml, area_hectares,
      prioridade, status, tipo_item, numero_os,
      partner_order_id, partner_order_item_id, origem
    ) VALUES (
      NULL, NULL, NULL, v_item.product_id, v_item.microrganismo_id, NULL,
      CASE WHEN COALESCE(v_item.unidade_medida,'unidade') = 'hectare' THEN v_item.quantidade ELSE NULL END,
      'media','aberta',
      CASE WHEN v_item.product_id IS NULL THEN 'microrganismo' ELSE 'produto' END,
      v_numero,
      p_partner_order_id, v_item.id, 'b2b'
    ) RETURNING id INTO v_os_id;

    INSERT INTO public.production_order_link (
      partner_order_id, partner_order_item_id, planning_id, ordem_servico_id, created_by
    ) VALUES (p_partner_order_id, v_item.id, v_planning_id, v_os_id, v_uid);

    v_ids := array_append(v_ids, v_os_id);
    v_count := v_count + 1;
  END LOOP;

  IF v_count = 0 THEN
    RETURN jsonb_build_object('ok', true, 'os_created', 0, 'planning_id', v_planning_id,
                              'non_lab_items',v_nonlab_count, 'message', 'Nenhuma nova OS biológica gerada; itens não laboratoriais permanecem no pedido.');
  END IF;

  UPDATE public.production_planning
     SET status = 'planejado', updated_at = now()
   WHERE id = v_planning_id AND status = 'aguardando_planejamento';

  INSERT INTO public.production_timeline_events (partner_order_id, event_type, actor_id, meta)
  VALUES (p_partner_order_id, 'op_gerada', v_uid, jsonb_build_object('os_count', v_count, 'planning_id', v_planning_id));

  INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (
    p_partner_order_id, v_partner_id, v_uid, 'op_gerada',
    jsonb_build_object(
      'planning_id', v_planning_id,
      'os_count', v_count,
      'ordens_servico_ids', to_jsonb(v_ids),
      'created_at', now()
    )
  );

  RETURN jsonb_build_object('ok', true, 'os_created', v_count, 'planning_id', v_planning_id, 'ordens_servico_ids', to_jsonb(v_ids), 'non_lab_items',v_nonlab_count);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_run_recurring_generation()
 RETURNS TABLE(template_id uuid, status text, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r RECORD; v_id UUID;
BEGIN
  -- H9-D1: sessão interna/cron (sem JWT) preservada; chamada autenticada exige staff financeiro.
  IF auth.uid() IS NOT NULL AND NOT public.is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
      HINT = 'H9-D1: execução da geração recorrente restrita ao staff financeiro.';
  END IF;

  FOR r IN
    SELECT id, next_generation_date
    FROM public.recurring_financial_templates
    WHERE organization_id IS NOT NULL
      AND (auth.uid() IS NULL OR organization_id = platform_private.h15_actor_organization())
      AND active = true AND auto_generate = true
      AND next_generation_date IS NOT NULL
      AND next_generation_date <= CURRENT_DATE
      AND (end_date IS NULL OR next_generation_date <= end_date)
  LOOP
    BEGIN
      v_id := public.fn_generate_recurring_title(r.id, r.next_generation_date, false);
      template_id := r.id;
      status := CASE WHEN v_id IS NULL THEN 'SKIPPED' ELSE 'SUCCESS' END;
      message := NULL;
      RETURN NEXT;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.recurring_generation_log(template_id, reference_date, status, error_message)
      VALUES (r.id, r.next_generation_date, 'FAILED', SQLERRM);
      INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
      VALUES ('RECURRING_TEMPLATE', r.id, 'RECURRING_GENERATION_FAILED',
              jsonb_build_object('reference_date', r.next_generation_date), auth.uid(), SQLERRM);
      template_id := r.id; status := 'FAILED'; message := SQLERRM;
      RETURN NEXT;
    END;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.generate_b2b_receivable_secure_impl(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_order record;
  v_partner record;
  v_settings record;
  v_terms record;
  v_receivable_id uuid;
  v_category_id uuid;
  v_payment_method_id uuid;
  v_existing uuid;
  v_sch record;
  v_ari_id uuid;
  v_installments_json jsonb := '[]'::jsonb;
  v_system_call boolean := (v_uid IS NULL);
  v_gate jsonb;
  v_fiscal jsonb;
  v_uf text;
  v_org uuid;
  v_org_count integer; -- b2b_f1_financial_tenant
BEGIN
  IF NOT v_system_call THEN
    IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'financeiro') OR has_role(v_uid,'gestor') OR has_role(v_uid,'gestor_comercial')) THEN
      INSERT INTO public.partner_order_audit_logs(order_id, usuario_id, acao, dados_novos)
        VALUES (p_partner_order_id, v_uid, 'financeiro_permissao_negada', jsonb_build_object('motivo','sem permissão'));
      RAISE EXCEPTION 'Sem permissão para gerar cobrança B2B';
    END IF;
  END IF;

  SELECT * INTO v_order FROM public.partner_orders WHERE id = p_partner_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado'; END IF;

  -- Deterministic partner ownership, never caller-supplied organization.
  SELECT count(*), min(o.id::text)::uuid INTO v_org_count,v_org
    FROM public.organizations o WHERE o.partner_account_id=v_order.partner_id;
  -- c2_ord_owner_tenant: cliente comercial sem tenant próprio fatura no tenant dono.
  IF v_org_count = 0 THEN
    SELECT count(*), min(o.id::text)::uuid INTO v_org_count, v_org
      FROM public.partner_accounts pa JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id
     WHERE pa.id = v_order.partner_id AND pa.ativo IS TRUE AND pa.deleted_at IS NULL
       AND o.ativo IS TRUE AND o.status = 'ativa';
  END IF;
  IF v_org_count <> 1 OR v_org IS NULL THEN
    RAISE EXCEPTION 'B2B_FINANCIAL_TENANT_AMBIGUOUS' USING ERRCODE='42501';
  END IF;
  IF v_uid IS NOT NULL THEN
    -- c2_ord_internal_scope: emissor interno é limitado por h15 = tenant do título (abaixo);
    -- quem tem papel B2B externo continua passando pelo assert canônico.
    IF public.has_role(v_uid,'parceiro_b2b'::app_role) OR public.has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN
      PERFORM platform_private.assert_b2b_partner_scope(v_uid,v_order.partner_id);
    END IF;
    IF NOT public.is_platform_superadmin(v_uid) AND public.h15_actor_organization() IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'B2B_FINANCIAL_TENANT_MISMATCH' USING ERRCODE='42501';
    END IF;
  END IF;

  IF v_order.c2_external_origin_snapshot IS NOT NULL THEN
    PERFORM platform_private.c2_external_origin_assert(v_order.c2_external_origin_snapshot,v_order.partner_id,v_order.cliente_id);
    IF v_org::text IS DISTINCT FROM v_order.c2_external_origin_snapshot->>'creditor_organization_id' THEN RAISE EXCEPTION 'C2_EXTERNAL_CREDITOR_DRIFT' USING ERRCODE='42501'; END IF;
  END IF;

  -- GATE Fase C: elegibilidade server-side
  v_gate := public.fn_b2b_order_billing_eligibility(p_partner_order_id);
  IF NOT (v_gate->>'eligible')::boolean THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
      VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_bloqueado_gate', v_gate);
    RAISE EXCEPTION 'billing_not_eligible:%', v_gate->>'reason_code';
  END IF;

  -- H6C-001: condicao canonica vinculada ao pedido (nunca a mais recente).
  SELECT * INTO v_terms FROM public.partner_order_payment_terms
    WHERE id = NULLIF(v_gate->>'payment_terms_id','')::uuid
      AND partner_order_id = p_partner_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'payment_terms_not_canonical'; END IF;

  SELECT receivable_id INTO v_existing FROM public.partner_order_financial_links WHERE partner_order_id = p_partner_order_id;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
      VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_duplicidade_bloqueada', jsonb_build_object('receivable_id', v_existing));
    RETURN jsonb_build_object('receivable_id', v_existing, 'partner_order_id', p_partner_order_id, 'duplicado', true);
  END IF;

  SELECT * INTO v_partner FROM public.partner_accounts WHERE id = v_order.partner_id;
  SELECT * INTO v_settings FROM public.partner_financial_settings WHERE partner_id = v_order.partner_id;
  IF NOT FOUND THEN
    -- c2_ord_p1_no_provision: only the existing P1 CAS RPC creates settings.
    RAISE EXCEPTION 'B2B_FINANCIAL_SETTINGS_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;

  -- External manual billing must honor configured delivery prerequisite too.
  IF v_order.c2_external_origin_snapshot IS NOT NULL AND v_settings.billing_trigger='na_entrega' AND v_order.status IS DISTINCT FROM 'entregue' THEN
    RAISE EXCEPTION 'C2_EXTERNAL_DELIVERY_REQUIRED' USING ERRCODE='42501';
  END IF;

  v_uf := to_jsonb(v_partner) ->> 'uf';

  -- Derivação fiscal (fail-closed; nunca NOT_REQUIRED silencioso)
  v_fiscal := public.fn_fiscal_requirement_resolve(
    'b2b_partner', 'venda_mercadoria', v_uf, 'partner_order', p_partner_order_id, CURRENT_DATE);

  -- c2_ord_strict_refs: financial_categories/payment_methods são catálogos globais por desenho (sem organization_id, RLS is_financial_staff; sem DDL de tenant
  -- no schema canônico); resolução estrita, sem fallback de tipo/inativo, falha explícita.
  SELECT id INTO v_category_id FROM public.financial_categories
   WHERE upper(btrim(type)) = 'RECEITA' AND active IS TRUE
   ORDER BY created_at ASC, id ASC LIMIT 1;
  IF v_category_id IS NULL THEN
    RAISE EXCEPTION 'B2B_REVENUE_CATEGORY_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  IF NULLIF(btrim(COALESCE(v_settings.default_payment_method,'')),'') IS NULL THEN
    RAISE EXCEPTION 'B2B_PAYMENT_METHOD_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  IF (SELECT count(*) FROM public.payment_methods pm
       WHERE pm.active IS TRUE AND lower(btrim(pm.name)) = lower(btrim(v_settings.default_payment_method))) <> 1 THEN
    RAISE EXCEPTION 'B2B_PAYMENT_METHOD_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  SELECT pm.id INTO v_payment_method_id FROM public.payment_methods pm
   WHERE pm.active IS TRUE AND lower(btrim(pm.name)) = lower(btrim(v_settings.default_payment_method));
  IF v_partner.client_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.clientes cl WHERE cl.id = v_partner.client_id AND cl.organization_id = v_org) THEN
    RAISE EXCEPTION 'B2B_CUSTOMER_TENANT_MISMATCH' USING ERRCODE='42501';
  END IF;

  INSERT INTO public.accounts_receivable(
    organization_id, origin_type, origin_id, customer_id, partner_id, description,
    category_id, total_amount, issue_date, first_due_date, installment_count,
    status, fiscal_invoice_required, fiscal_invoice_status,
    fiscal_requirement_source, fiscal_policy_id, fiscal_exemption_id,
    payment_method_id, notes, created_by
  ) VALUES (
    v_org, 'B2B_ORDER', p_partner_order_id,
    NULLIF(v_partner.client_id, NULL), v_order.partner_id,
    format('Pedido B2B %s - %s', v_order.numero, COALESCE(v_partner.nome_fantasia, v_partner.razao_social)),
    v_category_id, v_terms.final_amount, CURRENT_DATE, v_terms.first_due_date, v_terms.installment_count,
    'OPEN',
    (v_fiscal->>'required')::boolean,
    v_fiscal->>'status',
    v_fiscal->>'source',
    NULLIF(v_fiscal->>'policy_id','')::uuid,
    NULLIF(v_fiscal->>'exemption_id','')::uuid,
    v_payment_method_id,
    format(E'Condição: %s (%s)\nDesconto: %s%%  Juros: %s%% a.m. x %s meses\nTabela: %s  Líquido: %s  Final: %s\nFiscal: %s (%s)',
           v_terms.plan_name_snapshot, v_terms.plan_code_snapshot,
           v_terms.discount_percent_snapshot, v_terms.monthly_interest_percent_snapshot, v_terms.months_count_snapshot,
           v_terms.table_amount, v_terms.net_amount_after_discount, v_terms.final_amount,
           v_fiscal->>'status', v_fiscal->>'source'),
    COALESCE(v_uid, v_order.created_by)
  ) RETURNING id INTO v_receivable_id;

  -- b2b_f1_fresh_title: no deletion; formal financial history protection preserved.

  FOR v_sch IN
    SELECT * FROM public.partner_order_payment_schedule
     WHERE partner_order_id = p_partner_order_id AND payment_terms_id = v_terms.id
     ORDER BY installment_number
  LOOP
    -- b2b_f1_reuse_installments: generic title trigger already created them.
    IF (SELECT count(*) FROM public.accounts_receivable_installments
         WHERE receivable_id=v_receivable_id AND installment_number=v_sch.installment_number
           AND organization_id=v_org) <> 1 THEN
      RAISE EXCEPTION 'B2B_INSTALLMENT_CARDINALITY_INVALID' USING ERRCODE='23514';
    END IF;
    UPDATE public.accounts_receivable_installments
       SET due_date=v_sch.due_date, original_amount=v_sch.amount,
           interest_amount=COALESCE(v_sch.interest_amount,0), net_amount=v_sch.amount
     WHERE receivable_id=v_receivable_id AND installment_number=v_sch.installment_number
       AND organization_id=v_org
     RETURNING id INTO v_ari_id;

    UPDATE public.partner_order_payment_schedule
       SET status = 'generated', receivable_installment_id = v_ari_id
     WHERE id = v_sch.id;

    v_installments_json := v_installments_json || jsonb_build_array(jsonb_build_object(
      'installment_number', v_sch.installment_number,
      'due_date', v_sch.due_date,
      'amount', v_sch.amount
    ));
  END LOOP;

  INSERT INTO public.partner_order_financial_links(
    partner_order_id, partner_id, receivable_id, financial_status, billing_trigger, created_by
  ) VALUES (
    p_partner_order_id, v_order.partner_id, v_receivable_id, 'gerado', v_settings.billing_trigger, v_uid
  );

  UPDATE public.partner_orders SET
    financial_status = 'gerado',
    receivable_generated = true,
    receivable_generated_at = now(),
    receivable_generated_by = v_uid,
    payment_due_date = v_terms.first_due_date,
    payment_method = COALESCE(v_settings.default_payment_method,'pix')
  WHERE id = p_partner_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_gerado_com_plano',
    jsonb_build_object(
      'receivable_id', v_receivable_id,
      'plan_code', v_terms.plan_code_snapshot,
      'plan_name', v_terms.plan_name_snapshot,
      'table_amount', v_terms.table_amount,
      'discount_amount', v_terms.discount_amount,
      'net_amount', v_terms.net_amount_after_discount,
      'interest_amount', v_terms.financial_interest_amount,
      'final_amount', v_terms.final_amount,
      'first_due_date', v_terms.first_due_date,
      'installment_count', v_terms.installment_count,
      'fiscal', v_fiscal,
      'gate', v_gate,
      'installments', v_installments_json
    ));

  RETURN jsonb_build_object(
    'receivable_id', v_receivable_id,
    'partner_order_id', p_partner_order_id,
    'valor', v_terms.final_amount,
    'vencimento', v_terms.first_due_date,
    'installment_count', v_terms.installment_count,
    'fiscal_invoice_required', (v_fiscal->>'required')::boolean,
    'fiscal_invoice_status', v_fiscal->>'status',
    'fiscal_requirement_source', v_fiscal->>'source',
    'status', 'OPEN'
  );
END 
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_reference_entry_normalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.search_text := lower(translate(
    coalesce(NEW.code,'') || ' ' || coalesce(NEW.description,''),
    'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇáàâãäéèêëíìîïóòôõöúùûüç',
    'AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc'
  ));
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_b2b_technician_client_detail_secure(p_cliente_id uuid)
 RETURNS TABLE(cliente_id uuid, nome text, razao_social text, nome_fantasia text, tipo_pessoa text, documento_mascarado text, telefone text, email text, cidade text, estado text, bairro text, logradouro text, observacoes text, total_simulacoes bigint, ultima_simulacao_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_comercial boolean;
  v_is_gestor boolean;
  v_is_tecnico boolean;
  v_user_partner uuid;
  v_allowed boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  v_is_admin := public.has_role(v_uid, 'administrador'::app_role);
  v_is_comercial := public.has_role(v_uid, 'gestor_comercial'::app_role);
  v_is_gestor := public.has_role(v_uid, 'parceiro_b2b'::app_role);
  v_is_tecnico := public.has_role(v_uid, 'parceiro_b2b_tecnico'::app_role);

  IF v_is_admin OR v_is_comercial THEN
    v_allowed := true;
  ELSIF v_is_gestor THEN
    v_user_partner := public.get_user_partner_id();
    SELECT EXISTS(
      SELECT 1 FROM public.partner_technician_clients ptc
      WHERE ptc.cliente_id = p_cliente_id AND ptc.partner_id = v_user_partner AND ptc.active = true
    ) INTO v_allowed;
  ELSIF v_is_tecnico THEN
    v_user_partner := public.get_user_partner_id();
    SELECT EXISTS(
      SELECT 1 FROM public.partner_technician_clients ptc
      WHERE ptc.cliente_id = p_cliente_id
        AND ptc.technician_user_id = v_uid
        AND ptc.partner_id = v_user_partner
        AND ptc.active = true
    ) INTO v_allowed;
  END IF;

  IF NOT v_allowed THEN RAISE EXCEPTION 'forbidden'; END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.nome,
    c.razao_social,
    c.nome_fantasia,
    c.tipo_pessoa,
    CASE
      WHEN c.cpf_cnpj IS NULL THEN NULL
      WHEN length(regexp_replace(c.cpf_cnpj, '\D', '', 'g')) = 11
        THEN '***.' || substring(regexp_replace(c.cpf_cnpj, '\D', '', 'g'), 4, 3) || '.***-**'
      WHEN length(regexp_replace(c.cpf_cnpj, '\D', '', 'g')) = 14
        THEN '**.' || substring(regexp_replace(c.cpf_cnpj, '\D', '', 'g'), 3, 3) || '.***/****-**'
      ELSE '***'
    END,
    c.telefone,
    c.email,
    c.endereco_municipio,
    c.endereco_estado,
    c.endereco_bairro,
    c.endereco_logradouro,
    c.observacoes,
    COALESCE((SELECT COUNT(*) FROM public.partner_simulations ps WHERE ps.cliente_id = c.id), 0),
    (SELECT MAX(ps.created_at) FROM public.partner_simulations ps WHERE ps.cliente_id = c.id)
  FROM public.clientes c
  WHERE c.id = p_cliente_id;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.catalog_visit_reference_guard_current12()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_id uuid; v_col text; v_ok boolean;
BEGIN
 v_org:=platform_private.catalog_tenant_actor('read_prefs');
 IF NOT COALESCE(public.can_view_technical_visit(auth.uid(),NEW.registro_consultor_id),false) THEN
  RAISE EXCEPTION 'sem_permissao' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND OLD.registro_consultor_id IS DISTINCT FROM NEW.registro_consultor_id
  AND NOT COALESCE(public.can_view_technical_visit(auth.uid(),OLD.registro_consultor_id),false) THEN
  RAISE EXCEPTION 'sem_permissao' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.registros_consultor WHERE id=NEW.registro_consultor_id FOR UPDATE;
 IF NOT COALESCE(public.can_view_technical_visit(auth.uid(),NEW.registro_consultor_id),false) THEN
  RAISE EXCEPTION 'sem_permissao' USING ERRCODE='42501'; END IF;
 PERFORM public._assert_visita_editavel(NEW.registro_consultor_id);
 FOR v_col IN SELECT unnest(ARRAY['produto_biologico_sugerido_id','microrganismo_id']) LOOP
  IF TG_OP='UPDATE' AND NEW.registro_consultor_id=OLD.registro_consultor_id
   AND to_jsonb(NEW)->>v_col IS NOT DISTINCT FROM to_jsonb(OLD)->>v_col THEN CONTINUE; END IF;
  v_id:=NULLIF(to_jsonb(NEW)->>v_col,'')::uuid;
  IF v_id IS NULL THEN CONTINUE; END IF;
  IF v_col='microrganismo_id' THEN
   SELECT EXISTS(SELECT 1 FROM public.microrganismos m WHERE m.id=v_id AND m.ativo AND to_jsonb(m)->>'owner_organization_id' IS NULL) INTO v_ok;
  ELSE
   SELECT EXISTS(SELECT 1 FROM public.produtos p WHERE p.id=v_id AND p.ativo AND to_jsonb(p)->>'owner_organization_id' IS NULL) INTO v_ok;
  END IF;
  IF NOT v_ok OR EXISTS(SELECT 1 FROM public.catalog_tenant_visibility v WHERE v.organization_id=v_org
   AND v.entity_type=CASE WHEN v_col='microrganismo_id' THEN 'microrganismo' ELSE 'produto' END
   AND COALESCE(v.produto_id,v.microrganismo_id)=v_id AND v.hidden) THEN
   RAISE EXCEPTION 'catalog_visit_item_unavailable' USING ERRCODE='42501'; END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.get_partner_catalog_tecnico_secure()
 RETURNS TABLE(item_id uuid, item_tipo text, nome text, codigo text, descricao_curta text, tipo text, nome_cientifico text, funcao text, dose_ml_ha numeric, valor_dose_brl numeric, valor_litro_brl numeric, valor_ha_brl numeric, preco_tabela_dose numeric, preco_tabela_litro numeric, preco_tabela_ha numeric, unidade_preco_principal text, resumo_curto text, explicacao_b2b text, beneficios_principais text, ficha_status text, ficha_aprovada boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_visibility_scope uuid[];
  v_uid uuid := auth.uid();
  v_super boolean; v_is_tec boolean; v_is_partner boolean; v_is_internal boolean;
  v_partner uuid; v_show_fin boolean := false; s record; r record;
  v_pid uuid; v_mid uuid; j_ha jsonb; j_li jsonb; j_do jsonb;
  n_ha numeric; n_li numeric; n_do numeric;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
  v_super := public.is_platform_superadmin(v_uid);
  v_is_tec := public.has_role(v_uid,'parceiro_b2b_tecnico'::app_role);
  v_is_partner := public.has_role(v_uid,'parceiro_b2b'::app_role);
  v_is_internal := public.has_role(v_uid,'administrador'::app_role) OR public.has_role(v_uid,'gestor_comercial'::app_role);

  IF NOT v_super THEN
    IF NOT (v_is_tec OR v_is_partner OR v_is_internal) THEN
      RAISE EXCEPTION 'forbidden_role' USING ERRCODE='42501';
    END IF;
    SELECT * INTO s FROM platform_private.b2b_actor_scope(v_uid);
    IF NOT s.profile_ok THEN RAISE EXCEPTION 'inactive_scope' USING ERRCODE='42501'; END IF;
    IF v_is_tec OR v_is_partner THEN
      IF s.user_partner_count <> 1 OR s.org_partner IS NULL OR s.user_partner IS DISTINCT FROM s.org_partner
         OR NOT s.partner_valid THEN
        RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
      END IF;
      v_partner := s.org_partner;
      v_show_fin := v_is_partner AND NOT v_is_tec;
    END IF;
    IF NOT s.has_catalog THEN RAISE EXCEPTION 'feature_not_entitled' USING ERRCODE='42501'; END IF;
  END IF;

  v_visibility_scope := platform_private.c1b_catalog_visibility_scope(v_partner);
  FOR r IN
    SELECT p.id, 'produto'::text AS itipo, p.nome, p.codigo, p.tipo::text AS ptipo,
           NULL::text AS nome_cientifico, p.funcao_completa AS funcao, p.dose_ml_ha,
           ptp.status_validacao, ptp.resumo_curto, ptp.explicacao_b2b, ptp.beneficio_combinado AS beneficios, p.descricao
      FROM public.produtos p JOIN public.product_technical_profiles ptp ON ptp.produto_id = p.id
     WHERE p.ativo = true AND p.b2b_enabled = true AND NOT EXISTS (SELECT 1 FROM public.catalog_tenant_visibility cv WHERE cv.organization_id=ANY(v_visibility_scope) AND cv.entity_type='produto' AND cv.hidden IS TRUE AND cv.produto_id=p.id) AND ptp.status_validacao = 'aprovado'
    UNION ALL
    SELECT m.id, 'microrganismo'::text, m.nome, m.codigo, m.tipo::text,
           m.nome_cientifico, m.funcao_agronomica, m.dose_ml_ha,
           mtp.status_validacao, mtp.resumo_curto, mtp.explicacao_b2b, mtp.beneficios_agronomicos, m.descricao
      FROM public.microrganismos m JOIN public.microorganism_technical_profiles mtp ON mtp.microrganismo_id = m.id
     WHERE m.ativo = true AND m.b2b_enabled = true AND NOT EXISTS (SELECT 1 FROM public.catalog_tenant_visibility cv WHERE cv.organization_id=ANY(v_visibility_scope) AND cv.entity_type='microrganismo' AND cv.hidden IS TRUE AND cv.microrganismo_id=m.id) AND mtp.status_validacao = 'aprovado'
  LOOP
    n_ha := NULL; n_li := NULL; n_do := NULL;
    IF v_show_fin THEN
      v_pid := CASE WHEN r.itipo='produto' THEN r.id END;
      v_mid := CASE WHEN r.itipo='microrganismo' THEN r.id END;
      j_ha := public.fn_resolve_commercial_price('partner', v_partner, NULL, NULL, v_pid, v_mid, 'hectare', NULL, current_date);
      j_li := public.fn_resolve_commercial_price('partner', v_partner, NULL, NULL, v_pid, v_mid, 'litro',   NULL, current_date);
      j_do := public.fn_resolve_commercial_price('partner', v_partner, NULL, NULL, v_pid, v_mid, 'dose',    NULL, current_date);
      n_ha := CASE WHEN COALESCE((j_ha->>'ok')::boolean,false) AND NOT COALESCE((j_ha->>'quote_required')::boolean,false) THEN NULLIF((j_ha->>'final_unit_price')::numeric,0) END;
      n_li := CASE WHEN COALESCE((j_li->>'ok')::boolean,false) AND NOT COALESCE((j_li->>'quote_required')::boolean,false) THEN NULLIF((j_li->>'final_unit_price')::numeric,0) END;
      n_do := CASE WHEN COALESCE((j_do->>'ok')::boolean,false) AND NOT COALESCE((j_do->>'quote_required')::boolean,false) THEN NULLIF((j_do->>'final_unit_price')::numeric,0) END;
    END IF;
    item_id := r.id; item_tipo := r.itipo; nome := r.nome; codigo := r.codigo;
    descricao_curta := COALESCE(r.resumo_curto, r.descricao);
    tipo := r.ptipo; nome_cientifico := r.nome_cientifico; funcao := r.funcao; dose_ml_ha := r.dose_ml_ha;
    valor_dose_brl := ROUND(n_do,2); valor_litro_brl := ROUND(n_li,2); valor_ha_brl := ROUND(n_ha,2);
    preco_tabela_dose := ROUND(n_do,2); preco_tabela_litro := ROUND(n_li,2); preco_tabela_ha := ROUND(n_ha,2);
    unidade_preco_principal := CASE WHEN n_ha IS NOT NULL THEN 'hectare' WHEN n_li IS NOT NULL THEN 'litro'
                                    WHEN n_do IS NOT NULL THEN 'dose_100ml' ELSE 'sob_consulta' END;
    resumo_curto := r.resumo_curto; explicacao_b2b := r.explicacao_b2b; beneficios_principais := r.beneficios;
    ficha_status := r.status_validacao; ficha_aprovada := true;
    RETURN NEXT;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_b2b_user_client_detail_secure(p_cliente_id uuid, p_scope text DEFAULT 'meus_produtores'::text)
 RETURNS TABLE(cliente_id uuid, nome text, razao_social text, nome_fantasia text, tipo_pessoa text, documento_mascarado text, telefone text, email text, cidade text, estado text, assignment_type text, can_create_simulation boolean, assigned_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
  v_ok boolean := false;
  v_scope text := COALESCE(p_scope, 'meus_produtores');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;

  IF v_scope NOT IN ('meus_produtores','equipe','admin') THEN
    RAISE EXCEPTION 'invalid scope';
  END IF;

  IF has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN
    v_scope := 'meus_produtores';
    v_ok := EXISTS(SELECT 1 FROM public.partner_user_clients puc
                   WHERE puc.user_id = v_uid AND puc.cliente_id = p_cliente_id AND puc.active = true);
  ELSIF has_role(v_uid,'parceiro_b2b'::app_role) THEN
    v_partner := get_user_partner_id();
    IF v_scope = 'meus_produtores' THEN
      v_ok := EXISTS(SELECT 1 FROM public.partner_user_clients puc
                     WHERE puc.user_id = v_uid
                       AND puc.cliente_id = p_cliente_id
                       AND puc.partner_id = v_partner
                       AND puc.active = true);
    ELSIF v_scope = 'equipe' THEN
      v_ok := EXISTS(SELECT 1 FROM public.partner_clients pc
                     WHERE pc.partner_id = v_partner AND pc.cliente_id = p_cliente_id AND pc.active = true);
    END IF;
  ELSIF has_role(v_uid,'administrador'::app_role) OR has_role(v_uid,'gestor_comercial'::app_role) THEN
    IF v_scope IN ('admin','equipe') THEN
      v_ok := true;
    END IF;
  END IF;

  IF NOT v_ok THEN RAISE EXCEPTION 'access denied'; END IF;

  RETURN QUERY
  SELECT c.id, c.nome, c.razao_social, c.nome_fantasia, c.tipo_pessoa,
    CASE WHEN c.cpf_cnpj IS NULL THEN NULL
         ELSE repeat('*', greatest(length(c.cpf_cnpj)-4,0)) || right(c.cpf_cnpj,4)
    END,
    c.telefone, c.email,
    c.endereco_municipio, c.endereco_estado,
    (SELECT assignment_type FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1),
    (SELECT can_create_simulation FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1),
    (SELECT assigned_at FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1)
  FROM public.clientes c
  WHERE c.id = p_cliente_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_b2b_user_client_simulations_secure(p_cliente_id uuid)
 RETURNS TABLE(id uuid, titulo text, status text, total_cheio numeric, created_at timestamp with time zone, created_by uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
  v_is_admin boolean := has_role(v_uid,'administrador'::app_role) OR has_role(v_uid,'gestor_comercial'::app_role);
  v_is_gest boolean := has_role(v_uid,'parceiro_b2b'::app_role);
  v_is_tec boolean := has_role(v_uid,'parceiro_b2b_tecnico'::app_role);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF NOT (v_is_admin OR v_is_gest OR v_is_tec) THEN RAISE EXCEPTION 'access denied'; END IF;

  IF v_is_admin THEN
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
      ORDER BY s.created_at DESC
      LIMIT 100;
    RETURN;
  END IF;

  v_partner := public.get_user_partner_id();
  IF v_partner IS NULL THEN RAISE EXCEPTION 'partner nao identificado'; END IF;

  -- Cliente precisa estar vinculado ao usuário
  IF NOT EXISTS (
    SELECT 1 FROM public.partner_user_clients
    WHERE partner_id = v_partner
      AND cliente_id = p_cliente_id
      AND user_id = v_uid
      AND active = true
  ) THEN
    RAISE EXCEPTION 'cliente nao vinculado';
  END IF;

  IF v_is_tec THEN
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
        AND s.partner_id = v_partner
        AND s.created_by = v_uid
      ORDER BY s.created_at DESC
      LIMIT 100;
  ELSE
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
        AND s.partner_id = v_partner
      ORDER BY s.created_at DESC
      LIMIT 100;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION private.assert_os_approval_scope(p_os_id uuid, p_origin text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_uid uuid:=auth.uid(); v_org uuid; v_os record; v_pp public.programacao_producao%ROWTYPE;
BEGIN
 v_org:=platform_private.h15_actor_organization();
 -- Alçada antes de lookup/status/replay. NULL não é permissão.
 IF v_uid IS NULL OR v_org IS NULL OR public.technical_actor_ready(v_uid) IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')) IS NOT TRUE
 OR p_os_id IS NULL OR p_origin NOT IN ('manual','onfarm') OR p_origin IS NULL THEN
 RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=p_origin) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Mesmo ordenamento do caminho direto: lock da OS antes dos filhos, sem advisory invertido.
 IF p_origin='manual' THEN
 SELECT o.organization_id,o.id,o.cliente_id,o.fazenda_id,o.talhao_id,o.produto_id,o.microrganismo_id,o.origem,o.partner_order_id,o.partner_order_item_id INTO v_os FROM public.ordens_servico o WHERE id=p_os_id FOR UPDATE;
 ELSE
 SELECT NULL::uuid organization_id,o.id,o.cliente_id,o.fazenda_id,o.talhao_id,o.produto_id,o.microrganismo_id,'onfarm'::text origem,NULL::uuid partner_order_id,NULL::uuid partner_order_item_id INTO v_os FROM public.ordens_servico_onfarm o WHERE id=p_os_id FOR UPDATE;
 END IF;
 IF v_os.id IS NULL OR (p_origin='manual' AND v_os.organization_id IS DISTINCT FROM v_org) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=v_uid OR id IN (SELECT responsavel_id FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id) ORDER BY user_id FOR SHARE;
 PERFORM 1 FROM public.organizations WHERE id=v_org FOR SHARE;
 -- Lock existing role rows; canonical has_role remains authority, never client claims.
 PERFORM 1 FROM public.user_roles WHERE user_id=v_uid ORDER BY role::text FOR SHARE;
 PERFORM 1 FROM public.clientes WHERE id=v_os.cliente_id FOR SHARE;
 PERFORM 1 FROM public.fazendas WHERE id=v_os.fazenda_id FOR SHARE;
 PERFORM 1 FROM public.talhoes WHERE id=v_os.talhao_id FOR SHARE;
 PERFORM 1 FROM public.produtos WHERE id=v_os.produto_id FOR SHARE;
 PERFORM 1 FROM public.microrganismos WHERE id=v_os.microrganismo_id FOR SHARE;
 PERFORM 1 FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id ORDER BY id FOR UPDATE;
 IF platform_private.h15_actor_organization() IS DISTINCT FROM v_org OR public.technical_actor_ready(v_uid) IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=p_origin) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Efeitos comerciais/planejamento ainda não homologados: não autorizar por alias.
 IF v_os.origem='b2b' OR v_os.partner_order_id IS NOT NULL OR v_os.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id)
 OR platform_private.lab_item_is_manufacturable(v_os.produto_id,v_os.microrganismo_id) IS NOT TRUE THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Aprovação não cria programação nem inventa data. Ausência exige revisão do fluxo atual.
 IF (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id)<>1 THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_pp FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id;
 IF v_pp.organization_id IS DISTINCT FROM v_org OR v_pp.status::text IS DISTINCT FROM 'aguardando'
 OR v_pp.produto_id IS DISTINCT FROM v_os.produto_id OR v_pp.microrganismo_id IS DISTINCT FROM v_os.microrganismo_id
 OR NOT (((p_origin='manual' AND v_pp.ordem_servico_id=p_os_id AND v_pp.ordem_servico_onfarm_id IS NULL)
 OR (p_origin='onfarm' AND v_pp.ordem_servico_onfarm_id=p_os_id AND v_pp.ordem_servico_id IS NULL)) IS TRUE)
 OR (v_pp.responsavel_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles pr WHERE pr.id=v_pp.responsavel_id AND pr.organization_id=v_org AND pr.ativo IS TRUE))
 OR EXISTS(SELECT 1 FROM public.lotes WHERE programacao_id=v_pp.id) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN v_org;
END $function$

CREATE OR REPLACE FUNCTION private.guard_os_separate_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_origin text; v_org uuid;
BEGIN
 IF TG_OP='INSERT' THEN
 -- Criação normal exclusivamente aberta, inclusive pelo serviço/DEFINER.
 -- NULL e qualquer estado avançado não podem saltar a aprovação humana.
 -- Sem whitelist service_role, flags GUC ou reparo de históricos.
 IF NEW.status::text IS DISTINCT FROM 'aberta' THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
 END IF;
 IF NEW.status::text IS DISTINCT FROM 'aprovada' THEN RETURN NEW; END IF;
 v_origin:=CASE TG_TABLE_NAME WHEN 'ordens_servico' THEN 'manual' WHEN 'ordens_servico_onfarm' THEN 'onfarm' END;
 IF TG_WHEN='BEFORE' THEN
 -- Um único UPDATE não pode substituir a identidade/referências e aprovar o estado anterior.
 IF (to_jsonb(NEW)-ARRAY['status','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at']) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=private.assert_os_approval_scope(OLD.id,v_origin);
 RETURN NEW;
 END IF;
 IF OLD.status::text='aberta' THEN
 v_org:=private.assert_os_approval_scope(NEW.id,v_origin);
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 SELECT NEW.id,v_origin,pp.id,'aberta','aprovada','aprovar_os',auth.uid(),jsonb_build_object(
 'organization_id',v_org,'before',jsonb_build_object('status',OLD.status,'volume',OLD.volume_total_ml,'data_os',to_jsonb(OLD)->'data_programada'),
 'after',jsonb_build_object('status',NEW.status,'volume',NEW.volume_total_ml,'data_os',to_jsonb(NEW)->'data_programada'),
 'programacao',jsonb_build_object('id',pp.id,'status',pp.status,'data',pp.data_programada,'volume',pp.volume_necessario),
 'actor',auth.uid(),'at',clock_timestamp(),'manufacturing_started',false,'commercial_completed',false)::text
 FROM public.programacao_producao pp WHERE pp.ordem_servico_id=NEW.id OR pp.ordem_servico_onfarm_id=NEW.id;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.get_financial_report_data(p_report_type text, p_start_date date, p_end_date date, p_customer_id uuid DEFAULT NULL::uuid, p_category_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_regime text DEFAULT 'CASH'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_filters jsonb; v_rows jsonb; v_summary jsonb;
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'Datas inicial e final são obrigatórias'; END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'Data final não pode ser menor que data inicial'; END IF;
  v_filters := jsonb_build_object(
    'start_date', p_start_date, 'end_date', p_end_date,
    'customer_id', p_customer_id, 'category_id', p_category_id,
    'cost_center_id', p_cost_center_id, 'status', p_status, 'regime', p_regime
  );
  CASE upper(p_report_type)
    WHEN 'MONTHLY_FINANCIAL' THEN
      v_summary := get_report_monthly_financial(p_start_date, p_end_date, p_cost_center_id, p_regime);
    WHEN 'ACCOUNTS_RECEIVABLE' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_receivables(v_filters) t;
    WHEN 'ACCOUNTS_PAYABLE' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_payables(v_filters) t;
    WHEN 'CASHFLOW' THEN
      v_summary := get_financial_cashflow(p_start_date, p_end_date, 'PROJECTED', 'DAY');
    WHEN 'DRE' THEN
      v_summary := get_financial_dre_summary(p_start_date, p_end_date, p_regime, p_cost_center_id);
    WHEN 'INADIMPLENCIA' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_delinquency(p_end_date) t;
    WHEN 'FISCAL_PENDING' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_nfe_pending(v_filters) t;
    WHEN 'DELIVERY_BILLING' THEN
      v_summary := (SELECT to_jsonb(x) FROM get_report_deliveries_billing_status(p_start_date, p_end_date) x);
    WHEN 'CUSTOMER_STATEMENT' THEN
      IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Cliente é obrigatório para extrato'; END IF;
      v_summary := get_report_customer_statement(p_customer_id, p_start_date, p_end_date);
    WHEN 'ACCOUNTABILITY_STATEMENT' THEN
      IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Cliente é obrigatório para prestação de contas'; END IF;
      v_summary := get_report_accountability(jsonb_build_object(
        'customer_id', p_customer_id, 'from', p_start_date, 'to', p_end_date));
    ELSE RAISE EXCEPTION 'Tipo de relatório inválido: %', p_report_type;
  END CASE;
  PERFORM log_report_view(p_report_type, v_filters);
  RETURN jsonb_build_object(
    'report_type', p_report_type, 'filters', v_filters,
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'rows', COALESCE(v_rows, '[]'::jsonb),
    'generated_at', now()
  );
END$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_catalog_import_v1(p_catalog_type text, p_source_name text, p_source_version text, p_entries jsonb, p_source_reference text DEFAULT NULL::text, p_published_at date DEFAULT NULL::date, p_effective_from date DEFAULT NULL::date, p_checksum text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_status text;
  v_count integer;
BEGIN
  IF v_uid IS NULL OR NOT public.has_role(v_uid, 'administrador'::app_role) THEN
    RAISE EXCEPTION 'CATALOG_FORBIDDEN';
  END IF;
  IF p_entries IS NULL OR jsonb_typeof(p_entries) <> 'array' OR jsonb_array_length(p_entries) = 0 THEN
    RAISE EXCEPTION 'CATALOG_EMPTY_PAYLOAD';
  END IF;

  SELECT id, status INTO v_id, v_status
    FROM public.fiscal_reference_catalogs
   WHERE catalog_type = p_catalog_type AND source_version = p_source_version;

  IF v_status = 'SUPERSEDED' THEN
    RAISE EXCEPTION 'CATALOG_SUPERSEDED_IMMUTABLE';
  END IF;

  INSERT INTO public.fiscal_reference_catalogs (
    catalog_type, source_name, source_reference, source_version,
    published_at, effective_from, checksum, status, metadata, imported_by
  ) VALUES (
    p_catalog_type, p_source_name, p_source_reference, p_source_version,
    p_published_at, p_effective_from, p_checksum, 'DRAFT', coalesce(p_metadata,'{}'::jsonb), v_uid
  )
  ON CONFLICT (catalog_type, source_version) DO UPDATE
    SET source_name = EXCLUDED.source_name,
        source_reference = EXCLUDED.source_reference,
        published_at = EXCLUDED.published_at,
        effective_from = EXCLUDED.effective_from,
        checksum = EXCLUDED.checksum,
        metadata = EXCLUDED.metadata,
        updated_at = now()
  RETURNING id INTO v_id;

  INSERT INTO public.fiscal_reference_entries (catalog_id, code, description, parent_code, valid_from, valid_to, is_active, metadata)
  SELECT v_id, x.code, x.description, x.parent_code, x.valid_from, x.valid_to,
         coalesce(x.is_active, true), coalesce(x.metadata, '{}'::jsonb)
  FROM jsonb_to_recordset(p_entries) AS x(
    code text, description text, parent_code text,
    valid_from date, valid_to date, is_active boolean, metadata jsonb
  )
  WHERE x.code IS NOT NULL AND x.description IS NOT NULL
  ON CONFLICT (catalog_id, code) DO UPDATE
    SET description = EXCLUDED.description,
        parent_code = EXCLUDED.parent_code,
        valid_from = EXCLUDED.valid_from,
        valid_to = EXCLUDED.valid_to,
        is_active = EXCLUDED.is_active,
        metadata = EXCLUDED.metadata,
        updated_at = now();

  GET DIAGNOSTICS v_count = ROW_COUNT;

  INSERT INTO public.fiscal_audit_log (table_name, record_id, action, changed_by, new_values)
  VALUES ('fiscal_reference_catalogs', v_id, 'CATALOG_IMPORTED', v_uid,
          jsonb_build_object('catalog_type', p_catalog_type, 'source_name', p_source_name,
                             'source_version', p_source_version, 'checksum', p_checksum,
                             'entries', v_count));
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION cf_user_guards_v1.acquire_invitation_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_LEVEL<>'STATEMENT' OR TG_RELID<>'public.platform_org_admin_invites'::regclass THEN
  RAISE EXCEPTION 'invalid_user_guard_context' USING ERRCODE='42501'; END IF;
 IF current_setting('role',true) IN ('anon','authenticated') AND auth.uid() IS NULL THEN
  RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION cf_user_guards_v1.touch_invitation_profiles()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old_id uuid; new_id uuid; item uuid;
BEGIN
 IF TG_LEVEL<>'ROW' OR TG_RELID<>'public.platform_org_admin_invites'::regclass THEN
  RAISE EXCEPTION 'invalid_user_guard_context' USING ERRCODE='42501'; END IF;
 IF TG_OP<>'INSERT' THEN old_id:=OLD.user_id; END IF;
 IF TG_OP<>'DELETE' THEN new_id:=NEW.user_id; END IF;
 FOR item IN SELECT DISTINCT x FROM unnest(ARRAY[old_id,new_id]) x WHERE x IS NOT NULL ORDER BY x
 LOOP UPDATE public.profiles SET updated_at=updated_at WHERE user_id=item; END LOOP;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.get_report_accountability(_scope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r jsonb;
        _customer uuid := NULLIF(_scope->>'customer_id','')::uuid;
        _from date := (_scope->>'from')::date;
        _to date := (_scope->>'to')::date;
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  SELECT jsonb_build_object(
    'scope', _scope,
    'summary', public.get_report_customer_statement(_customer, _from, _to)
  ) INTO r;
  RETURN r;
END;$function$

CREATE OR REPLACE FUNCTION platform_private.external_provisioning_scope(p_actor uuid, p_role app_role, p_partner uuid, p_clients uuid[], p_primary uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid; snapshot jsonb;
BEGIN
 SELECT organization_id INTO org FROM public.profiles WHERE user_id=p_actor FOR UPDATE;
 IF p_actor IS NULL OR org IS NULL OR platform_private.platform_actor_access_ready(p_actor) IS NOT TRUE
 OR public.has_role(p_actor,'administrador') IS NOT TRUE OR public.is_platform_superadmin(p_actor) IS TRUE
 THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org AND ativo IS TRUE AND status='ativa' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF p_role = 'parceiro_b2b' THEN
 IF p_partner IS NULL OR cardinality(p_clients) IS DISTINCT FROM 0 OR p_primary IS NOT NULL
 OR NOT EXISTS(SELECT 1 FROM platform_private.entitlements_for_user(p_actor) WHERE feature_key='catalogo_precos') THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.partner_accounts WHERE id=p_partner FOR SHARE;
 SELECT jsonb_build_object('id',id,'updated_at',updated_at) INTO snapshot FROM public.partner_accounts
 WHERE id=p_partner AND commercial_owner_organization_id=org AND ativo IS TRUE AND deleted_at IS NULL;
 ELSE
 IF p_role IS DISTINCT FROM 'cliente_produtor' OR p_partner IS NOT NULL OR cardinality(p_clients) NOT BETWEEN 1 AND 100
 OR p_clients IS NULL OR array_position(p_clients,NULL) IS NOT NULL
 OR cardinality(p_clients)<>(SELECT count(DISTINCT id) FROM unnest(p_clients) id)
 OR p_primary IS NULL OR NOT (p_primary=ANY(p_clients)) THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 -- Explicit portal creation, never derive portal authority from technical user_clientes.
 PERFORM 1 FROM public.clientes WHERE id=ANY(p_clients) ORDER BY id FOR SHARE;
 IF (SELECT count(*) FROM public.clientes WHERE id=ANY(p_clients) AND organization_id=org AND status_cliente='ativo')<>cardinality(p_clients) THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',id,'updated_at',updated_at) ORDER BY id) INTO snapshot FROM public.clientes WHERE id=ANY(p_clients);
 END IF;
 IF platform_private.platform_actor_access_ready(p_actor) IS NOT TRUE OR public.has_role(p_actor,'administrador') IS NOT TRUE THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF snapshot IS NULL THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('organization_id',org,'snapshot',snapshot);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_set_communication_template_metadata(p_template_id uuid, p_provider_template_name text, p_language_code text, p_parameter_mapping jsonb, p_provider_template_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.comunicacao_templates%rowtype;
  v_mapping jsonb := COALESCE(p_parameter_mapping,'[]'::jsonb);
  v_len int; v_vars_len int; v_item jsonb; v_idx int; v_var text;
  v_seen_vars text[] := ARRAY[]::text[];
  v_seen_idx int[] := ARRAY[]::int[];
  v_ever_approved boolean; v_prev text; v_new text := p_provider_template_status;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE='insufficient_privilege';
  END IF;
  SELECT * INTO r FROM public.comunicacao_templates WHERE id = p_template_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'template não encontrado'; END IF;
  IF r.canal = 'whatsapp' THEN
    IF p_provider_template_name IS NULL OR length(trim(p_provider_template_name)) = 0 THEN
      RAISE EXCEPTION 'whatsapp: provider_template_name obrigatório'; END IF;
    IF length(p_provider_template_name) > 512 THEN RAISE EXCEPTION 'excede 512'; END IF;
    IF p_language_code IS NULL OR p_language_code !~ '^[a-z]{2}(_[A-Z]{2})?$' THEN
      RAISE EXCEPTION 'language_code inválido'; END IF;
    IF jsonb_typeof(v_mapping) <> 'array' THEN RAISE EXCEPTION 'mapping array'; END IF;
    v_len := jsonb_array_length(v_mapping);
    IF v_len > 64 THEN RAISE EXCEPTION 'mapping >64'; END IF;
    v_vars_len := COALESCE(array_length(r.variaveis, 1), 0);
    FOR i IN 0 .. v_len - 1 LOOP
      v_item := v_mapping -> i;
      IF jsonb_typeof(v_item) <> 'object' THEN RAISE EXCEPTION 'item % não objeto', i+1; END IF;
      IF jsonb_typeof(v_item->'index') <> 'number' THEN RAISE EXCEPTION 'index[%] inválido', i+1; END IF;
      v_idx := (v_item->>'index')::int;
      IF v_idx <= 0 OR v_idx > v_len THEN RAISE EXCEPTION 'index fora 1..N'; END IF;
      IF v_idx = ANY(v_seen_idx) THEN RAISE EXCEPTION 'index dup: %', v_idx; END IF;
      v_seen_idx := array_append(v_seen_idx, v_idx);
      IF jsonb_typeof(v_item->'variavel') <> 'string' THEN RAISE EXCEPTION 'variavel[%] inválida', i+1; END IF;
      v_var := v_item->>'variavel';
      IF length(v_var) = 0 THEN RAISE EXCEPTION 'variavel vazia'; END IF;
      IF v_var = ANY(v_seen_vars) THEN RAISE EXCEPTION 'variavel dup: %', v_var; END IF;
      IF v_vars_len > 0 AND NOT (v_var = ANY(r.variaveis)) THEN
        RAISE EXCEPTION 'variavel % não declarada', v_var; END IF;
      v_seen_vars := array_append(v_seen_vars, v_var);
    END LOOP;
    IF v_len > 0 THEN
      FOR i IN 1 .. v_len LOOP
        IF NOT (i = ANY(v_seen_idx)) THEN RAISE EXCEPTION 'falta index %', i; END IF;
      END LOOP;
    END IF;
    IF v_vars_len = 0 AND v_len <> 0 THEN RAISE EXCEPTION 'sem variaveis exige mapping=[]'; END IF;
    IF v_new IS NOT NULL AND v_new NOT IN ('draft','pending','approved','rejected','paused','disabled') THEN
      RAISE EXCEPTION 'status inválido'; END IF;
    IF v_new = 'approved' AND v_len <> v_vars_len THEN
      RAISE EXCEPTION 'approved exige mapping completo'; END IF;
    v_prev := r.provider_template_status;
    v_ever_approved := v_prev IN ('approved','paused','disabled');
    IF v_ever_approved AND p_provider_template_name IS DISTINCT FROM r.provider_template_name THEN
      RAISE EXCEPTION 'nome imutável após aprovação'; END IF;
    IF v_new IS NOT NULL AND v_new IS DISTINCT FROM COALESCE(v_prev,'draft') THEN
      IF NOT (
        (COALESCE(v_prev,'draft') IN ('draft') AND v_new IN ('draft','pending')) OR
        (v_prev = 'pending' AND v_new IN ('draft','pending','approved','rejected')) OR
        (v_prev = 'approved' AND v_new IN ('approved','paused','disabled')) OR
        (v_prev = 'paused' AND v_new IN ('approved','paused','disabled')) OR
        (v_prev = 'rejected' AND v_new IN ('draft','pending','rejected')) OR
        (v_prev = 'disabled' AND v_new IN ('disabled'))
      ) THEN RAISE EXCEPTION 'transição inválida % → %', COALESCE(v_prev,'draft'), v_new; END IF;
    END IF;
  ELSE
    IF p_provider_template_name IS NOT NULL OR p_language_code IS NOT NULL
       OR v_new IS NOT NULL OR jsonb_array_length(v_mapping) > 0 THEN
      RAISE EXCEPTION 'metadados WA não aceitos para canal %', r.canal; END IF;
  END IF;
  UPDATE public.comunicacao_templates
     SET provider_template_name = p_provider_template_name,
         language_code = p_language_code,
         parameter_mapping = v_mapping,
         provider_template_status = v_new,
         updated_by = auth.uid()
   WHERE id = p_template_id;
  PERFORM public._comunicacao_write_audit('template.set_metadata','comunicacao_templates', p_template_id,
    to_jsonb(r), (SELECT to_jsonb(t) FROM public.comunicacao_templates t WHERE t.id = p_template_id));
  RETURN jsonb_build_object('ok',true);
END$function$

CREATE OR REPLACE FUNCTION public.b2b_finish_provisioning(p_claim uuid, p_fence uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r platform_private.b2b_provisioning_receipts; actor public.profiles; target public.profiles; invitation jsonb; ctx jsonb; rs public.app_role[];
BEGIN
 PERFORM platform_private.require_service_role();
 -- Acquire before receipt/profile locks, never wait for the trigger gate afterward.
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 SELECT * INTO r FROM platform_private.b2b_provisioning_receipts WHERE id=p_claim FOR UPDATE;
 IF r.id IS NULL OR r.fence IS DISTINCT FROM p_fence OR r.user_id IS DISTINCT FROM p_user THEN
  RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 rs:=COALESCE(r.external_roles,ARRAY[r.external_role]);
 PERFORM 1 FROM public.platform_org_admin_invites WHERE user_id=r.actor_id ORDER BY id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_array(id,access_operation_id,access_operation_status,status,access_valid_after) ORDER BY id),'[]'::jsonb) INTO invitation FROM public.platform_org_admin_invites WHERE user_id=r.actor_id;
 IF invitation IS DISTINCT FROM r.actor_invite_fence OR EXISTS(SELECT 1 FROM public.platform_org_admin_invites i WHERE i.user_id=r.actor_id AND (i.access_operation_status='processing' OR i.status='processando' OR (i.access_valid_after IS NOT NULL AND to_timestamp(r.actor_iat)<=i.access_valid_after))) THEN
 RAISE EXCEPTION 'b2b_provisioning_actor_revoked' USING ERRCODE='42501'; END IF;
 SELECT * INTO actor FROM public.profiles WHERE user_id=r.actor_id FOR UPDATE;
 IF r.external_roles IS NULL THEN ctx:=platform_private.external_provisioning_scope(r.actor_id,r.external_role,r.partner_id,r.cliente_ids,r.principal_cliente_id); ELSE ctx:=platform_private.external_provisioning_scope(r.actor_id,rs,r.partner_id,r.cliente_ids,r.principal_cliente_id); END IF;
 IF ctx->'snapshot' IS DISTINCT FROM r.target_snapshot THEN RAISE EXCEPTION 'external_provisioning_target_changed' USING ERRCODE='42501'; END IF;
 IF actor.organization_id IS DISTINCT FROM r.organization_id OR actor.updated_at IS DISTINCT FROM r.actor_stamp
 OR NOT platform_private.platform_actor_access_ready(r.actor_id)
 OR NOT public.has_role(r.actor_id,'administrador'::public.app_role)
 OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=r.organization_id AND o.ativo IS TRUE AND o.status='ativa')
 THEN
  RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF r.status='completed' THEN
 IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=r.user_id AND lower(email)=r.email AND raw_app_meta_data->>'b2b_provisioning_receipt'=r.id::text) THEN RAISE EXCEPTION 'b2b_provisioning_target_conflict'; END IF;
 RETURN jsonb_build_object('success',true,'user_id',r.user_id,'replay',true);
 END IF;
 IF r.status<>'claimed' THEN
  RAISE EXCEPTION 'b2b_provisioning_stale' USING ERRCODE='42501'; END IF;
 SELECT * INTO target FROM public.profiles WHERE user_id=p_user FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=r.user_id AND lower(u.email)=r.email
   AND u.raw_app_meta_data->>'b2b_provisioning_receipt'=r.id::text)
 OR target.user_id IS NULL OR target.organization_id IS NOT NULL OR target.cliente_id IS NOT NULL
 OR lower(target.email) IS DISTINCT FROM r.email
 OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user)
 OR EXISTS(SELECT 1 FROM public.partner_users WHERE user_id=p_user)
 OR EXISTS(SELECT 1 FROM public.user_clientes WHERE user_id=p_user) THEN
  RAISE EXCEPTION 'b2b_provisioning_target_conflict' USING ERRCODE='42501'; END IF;
 -- Existing server-only first-access contract; recovery proof required, no operator password.
 UPDATE public.profiles SET organization_id=r.organization_id,nome=r.nome,ativo=true,senha_provisoria=true WHERE user_id=p_user;
 PERFORM public.admin_provision_user_profile_v1(p_user,r.email,r.nome,rs,r.cliente_ids,r.principal_cliente_id,r.partner_id,CASE WHEN r.partner_id IS NULL THEN NULL WHEN 'parceiro_b2b'=ANY(rs) THEN 'gestor' ELSE 'tecnico' END);
 UPDATE public.user_clientes SET is_active=true,assigned_by=r.actor_id WHERE user_id=p_user;

 INSERT INTO platform_private.provisional_password_state(user_id,desde,expires_at)
 VALUES(p_user,clock_timestamp(),NULL);
 UPDATE platform_private.b2b_provisioning_receipts SET status='completed' WHERE id=r.id;
 RETURN jsonb_build_object('success',true,'user_id',p_user,'first_access_pending',true);
END $function$

CREATE OR REPLACE FUNCTION platform_private.b2b_claim_provisioning(p_partner uuid, p_key uuid, p_email text, p_nome text, p_role app_role DEFAULT 'parceiro_b2b'::app_role, p_clients uuid[] DEFAULT ARRAY[]::uuid[], p_primary uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ctx jsonb; r platform_private.b2b_provisioning_receipts; stamp timestamptz; issued bigint; invitation jsonb; inserted integer;
BEGIN
 -- Same first lock as live statement triggers: gate → receipt/profile → rows.
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 IF p_role = 'parceiro_b2b' THEN
 PERFORM public.b2b_provisioning_preflight(p_partner,p_role::text,'gestor'); END IF;
 ctx:=platform_private.external_provisioning_scope(auth.uid(),p_role,p_partner,p_clients,p_primary);
 IF p_key IS NULL OR p_email IS NULL OR p_nome IS NULL OR length(trim(p_nome)) NOT BETWEEN 1 AND 200
 OR length(p_email)>254 OR lower(trim(p_email)) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
  RAISE EXCEPTION 'b2b_provisioning_invalid' USING ERRCODE='22023'; END IF;
 issued:=(auth.jwt()->>'iat')::bigint;
 IF issued IS NULL OR issued<=0 OR to_timestamp(issued)>clock_timestamp()+interval '1 minute' THEN
 RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 SELECT updated_at INTO STRICT stamp FROM public.profiles WHERE user_id=auth.uid() FOR UPDATE;
 PERFORM 1 FROM public.platform_org_admin_invites WHERE user_id=auth.uid() ORDER BY id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_array(id,access_operation_id,access_operation_status,status,access_valid_after) ORDER BY id),'[]'::jsonb) INTO invitation FROM public.platform_org_admin_invites WHERE user_id=auth.uid();
 INSERT INTO platform_private.b2b_provisioning_receipts(actor_id,organization_id,partner_id,idempotency_key,email,nome,actor_stamp,actor_iat,actor_invite_fence,external_role,cliente_ids,principal_cliente_id,target_snapshot)
 VALUES(auth.uid(),(ctx->>'organization_id')::uuid,p_partner,p_key,lower(trim(p_email)),trim(p_nome),stamp,issued,invitation,p_role,p_clients,p_primary,ctx->'snapshot')
 ON CONFLICT(actor_id,idempotency_key) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 SELECT * INTO STRICT r FROM platform_private.b2b_provisioning_receipts
 WHERE actor_id=auth.uid() AND idempotency_key=p_key FOR UPDATE;
 IF ROW(r.organization_id,r.partner_id,r.email,r.nome,r.actor_stamp,r.actor_iat,r.actor_invite_fence,r.external_role,r.cliente_ids,r.principal_cliente_id,r.target_snapshot) IS DISTINCT FROM
 ROW((ctx->>'organization_id')::uuid,p_partner,lower(trim(p_email)),trim(p_nome),stamp,issued,invitation,p_role,p_clients,p_primary,ctx->'snapshot') THEN
  RAISE EXCEPTION 'b2b_provisioning_conflict' USING ERRCODE='42501'; END IF;
 -- Never renew/reclaim a timed-out lease: Auth may already exist. Reconcile by ID.
 RETURN jsonb_build_object('claim_id',r.id,'user_id',r.user_id,'fence',r.fence,'status',r.status,
  'lease_valid',r.lease_until>clock_timestamp(),'acquired',inserted=1,'organization_id',r.organization_id);
END $function$

CREATE OR REPLACE FUNCTION public.create_partner_order_secure(p_partner_id uuid, p_observacoes text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb, p_requested_delivery_date date DEFAULT NULL::date, p_payment_plan_id uuid DEFAULT NULL::uuid, p_first_due_date date DEFAULT NULL::date, p_installment_count integer DEFAULT NULL::integer, p_expected_cart_hash text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean; v_is_finance boolean; v_is_gestor boolean; v_is_internal boolean;
  v_is_partner boolean; v_is_partner_tech boolean; v_user_partner uuid;
  v_order_id uuid; v_numero text; v_plan record; v_cart jsonb; v_line jsonb;
  v_quote boolean; v_table numeric(14,2); v_disc numeric(14,2); v_net numeric(14,2);
  v_interest numeric(14,2); v_final numeric(14,2); v_hash text;
  v_installments integer; v_first_due date; v_terms_id uuid;
  v_status partner_order_status; v_fin_status text; v_approval_status text;
  v_credit jsonb; v_block_reason text := NULL;
  v_inst numeric(14,2); v_accum numeric(14,2) := 0;
  v_amount_i numeric(14,2); v_principal_i numeric(14,2); v_interest_i numeric(14,2);
  v_due_i date; v_admin record; i integer;
  v_idem text; v_prev_idem record; v_result jsonb;
  v_items_canon text; v_req_fp text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  PERFORM platform_private.c2_order_actor_scope(v_uid, p_partner_id); -- c2_ord_scope
  PERFORM platform_private.c2_owner_order_guard(v_uid, p_partner_id, p_payment_plan_id); -- c2_ord_guard
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'empty_cart'; END IF;
  IF p_payment_plan_id IS NULL THEN RAISE EXCEPTION 'payment_plan_required'; END IF;

  -- assinatura autoritativa obrigatoria para TODOS os chamadores
  IF NULLIF(btrim(COALESCE(p_expected_cart_hash,'')),'') IS NULL THEN
    RAISE EXCEPTION 'cart_hash_required';
  END IF;
  v_idem := NULLIF(btrim(COALESCE(p_idempotency_key,'')),'');
  IF v_idem IS NULL THEN RAISE EXCEPTION 'idempotency_key_required'; END IF;
  IF length(v_idem) > 120 THEN RAISE EXCEPTION 'invalid_idempotency_key'; END IF;

  -- ---------------------------------------------------------------
  -- request fingerprint canônico: reqfp_v2
  -- Cobre todos os parâmetros materialmente capazes de alterar o
  -- pedido resultante. Itens são normalizados (tipo|id|quantidade
  -- numérica canônica) e ordenados deterministicamente; textos são
  -- normalizados por btrim. cart_hash continua validado à parte.
  -- ---------------------------------------------------------------
  SELECT COALESCE(string_agg(t, ';' ORDER BY t), '')
    INTO v_items_canon
    FROM (
      SELECT lower(COALESCE(btrim(l->>'item_tipo'), '-')) || '|' ||
             lower(COALESCE(btrim(l->>'item_id'), '-'))   || '|' ||
             COALESCE(trim(to_char(COALESCE(NULLIF(btrim(l->>'quantidade'),'')::numeric, 0),
                                   'FM9999999990.000000')), '0') AS t
        FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) AS l
    ) s;

  v_req_fp := encode(sha256(convert_to(
      'reqfp_v2'
      || '|partner='   || p_partner_id::text
      || '|plan='      || COALESCE(p_payment_plan_id::text,'-')
      || '|delivery='  || COALESCE(p_requested_delivery_date::text,'-')
      || '|firstdue='  || COALESCE(p_first_due_date::text,'-')
      || '|inst='      || COALESCE(p_installment_count::text,'-')
      || '|obs='       || COALESCE(btrim(p_observacoes),'-')
      || '|items='     || v_items_canon
    ,'UTF8')),'hex');

  v_is_admin        := has_role(v_uid,'administrador'::app_role);
  v_is_finance      := has_role(v_uid,'financeiro'::app_role);
  v_is_gestor       := has_role(v_uid,'gestor_comercial'::app_role);
  v_is_internal     := v_is_admin OR v_is_finance OR v_is_gestor;
  v_is_partner      := has_role(v_uid,'parceiro_b2b'::app_role);
  v_is_partner_tech := has_role(v_uid,'parceiro_b2b_tecnico'::app_role);
  v_user_partner    := public.get_user_partner_id();

  IF has_role(v_uid,'cliente_produtor'::app_role) AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'PRODUCER_DIRECT_NOT_ENABLED';
  END IF;

  IF v_is_partner_tech AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'partner_tech_cannot_create_order';
  END IF;

  IF NOT v_is_internal THEN
    IF NOT v_is_partner OR v_user_partner IS NULL OR v_user_partner <> p_partner_id THEN
      RAISE EXCEPTION 'forbidden_partner';
    END IF;
  END IF;

  PERFORM 1 FROM public.partner_accounts WHERE id = p_partner_id AND ativo = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'partner_not_found'; END IF;

  -- idempotencia (lock deterministico #1: parceiro+chave)
  PERFORM platform_private.c2_attempt_dispatch_guard(v_uid,p_partner_id,v_idem);
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:' || p_partner_id::text || ':' || v_idem, 0));
  -- c2_attempt_closure_v2: a espera no lock pode atravessar revogações; revalida a
  -- autorização canônica APÓS o lock e antes de revelar replay ou criar (ponto de
  -- linearização = esta instrução; revogação confirmada depois dela não é observada).
  PERFORM platform_private.c2_partner_order_attempt_authz(v_uid, p_partner_id);
  IF NOT EXISTS(SELECT 1 FROM platform_private.partner_order_attempt_journal j JOIN public.profiles p ON p.user_id=j.actor_id AND p.organization_id=j.organization_id AND p.ativo WHERE j.actor_id=v_uid AND j.partner_id=p_partner_id AND j.idempotency_key=v_idem) THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  -- Fechamento durável sob ESTE MESMO lock: recusa envio tardio antes de qualquer efeito.
  -- (Corpos antigos em voo são cobertos pelo trigger c2_attempt_closure_guard.)
  IF EXISTS (SELECT 1 FROM platform_private.partner_order_idempotency_closures c
              WHERE c.partner_id = p_partner_id AND c.idempotency_key = v_idem) THEN
    RAISE EXCEPTION 'idempotency_key_closed';
  END IF;
  SELECT * INTO v_prev_idem FROM public.partner_order_idempotency
   WHERE partner_id = p_partner_id AND idempotency_key = v_idem;
  IF FOUND THEN
    -- linhas históricas sem fingerprint não podem ser reexecutadas em
    -- silêncio apenas com cart_hash: fail-safe, sem criar pedido.
    IF v_prev_idem.request_fingerprint IS NULL THEN
      RAISE EXCEPTION 'idempotency_legacy_unverifiable';
    END IF;
    IF v_prev_idem.cart_hash IS DISTINCT FROM p_expected_cart_hash THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    IF v_prev_idem.request_fingerprint IS DISTINCT FROM v_req_fp THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    RETURN v_prev_idem.result_snapshot;
  END IF;

  SELECT * INTO v_plan FROM public.commercial_payment_plans WHERE id = p_payment_plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF NOT public.fn_b2b_plan_selectable(v_plan.id) THEN RAISE EXCEPTION 'plan_not_selectable'; END IF;
  IF v_plan.active = false THEN RAISE EXCEPTION 'plan_inactive'; END IF;
  IF v_plan.monthly_interest_percent < 0 THEN RAISE EXCEPTION 'invalid_interest_rate'; END IF;
  IF v_plan.discount_percent > 40 AND NOT v_is_admin THEN RAISE EXCEPTION 'discount_exceeds_limit'; END IF;

  v_credit := public.fn_b2b_credit_exposure(p_partner_id, 0, NULL);
  IF COALESCE((v_credit->>'block_if_overdue')::boolean,false)
     AND COALESCE((v_credit->>'tem_vencidos')::boolean,false) THEN
    RAISE EXCEPTION 'credit_blocked_overdue';
  END IF;

  IF NOT v_is_internal THEN
    v_installments := GREATEST(COALESCE(v_plan.installment_count,1),1);
  ELSE
    IF p_installment_count IS NOT NULL AND p_installment_count <= 0 THEN
      RAISE EXCEPTION 'invalid_installment_count';
    END IF;
    v_installments := GREATEST(COALESCE(p_installment_count, v_plan.installment_count, 1), 1);
  END IF;

  v_cart  := public.fn_resolve_b2b_cart(p_partner_id, p_payment_plan_id, p_items, current_date);
  v_quote := COALESCE((v_cart->>'quote_required')::boolean,false);
  v_table := (v_cart->>'table_amount')::numeric;
  v_disc  := (v_cart->>'discount_amount')::numeric;
  v_net   := (v_cart->>'net_amount')::numeric;
  v_final := CASE WHEN v_quote THEN 0
                  ELSE public.fn_b2b_apply_interest(v_net, v_plan.interest_type,
                         v_plan.monthly_interest_percent, v_plan.months_count) END;

  v_hash := public.fn_b2b_cart_hash(p_partner_id, p_payment_plan_id, v_cart, v_final);
  IF p_expected_cart_hash <> v_hash THEN
    RAISE EXCEPTION 'price_changed';
  END IF;

  IF v_quote THEN v_table := 0; v_disc := 0; v_net := 0; END IF;
  v_interest := ROUND(v_final - v_net, 2);

  IF NOT v_quote AND v_plan.minimum_order_amount IS NOT NULL AND v_table < v_plan.minimum_order_amount THEN
    RAISE EXCEPTION 'below_minimum_order_amount';
  END IF;

  IF p_first_due_date IS NOT NULL AND p_first_due_date < current_date THEN
    RAISE EXCEPTION 'invalid_due_date';
  END IF;
  v_first_due := COALESCE(p_first_due_date, current_date + v_plan.max_days);

  IF v_plan.requires_financial_approval OR v_plan.requires_guarantee THEN
    v_fin_status := 'pending'; v_approval_status := 'pending';
  ELSE
    v_fin_status := 'not_required'; v_approval_status := 'not_required';
  END IF;

  IF v_first_due > current_date + v_plan.max_days THEN
    IF NOT v_is_internal OR NOT (v_plan.requires_financial_approval OR v_plan.requires_guarantee) THEN
      v_first_due := current_date + v_plan.max_days;
    ELSE
      v_fin_status := 'pending'; v_approval_status := 'pending';
    END IF;
  END IF;

  IF v_quote THEN
    v_status := 'aguardando_cotacao'::partner_order_status;
  ELSE
    -- lock deterministico #2: credito do parceiro
    PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || p_partner_id::text, 0));
    v_credit := public.fn_b2b_credit_exposure(p_partner_id, v_final, NULL);

    IF COALESCE((v_credit->>'block_if_overdue')::boolean,false)
       AND COALESCE((v_credit->>'tem_vencidos')::boolean,false) THEN
      RAISE EXCEPTION 'credit_blocked_overdue';
    END IF;

    IF COALESCE((v_credit->>'credit_limit')::numeric,0) > 0
       AND (v_credit->>'exposicao_projetada')::numeric > (v_credit->>'credit_limit')::numeric THEN
      IF COALESCE(v_credit->>'credit_limit_action','block') = 'approval_required' THEN
        v_status := 'aguardando_aprovacao_credito'::partner_order_status;
        v_block_reason := 'limite_excedido';
      ELSE
        RAISE EXCEPTION 'credit_limit_exceeded';
      END IF;
    ELSE
      v_status := 'em_analise_comercial'::partner_order_status;
    END IF;
  END IF;

  -- Issue only after canonical role/partner/plan/cart/hash/credit checks and idempotent replay.
  IF NOT v_is_internal AND platform_private.c2_owner_order_create_allowed(v_uid,p_partner_id) THEN
    PERFORM platform_private.issue_ticket('c2_external_order_create',p_partner_id);
  END IF;
  INSERT INTO public.partner_orders(
    partner_id, status, subtotal, desconto_total, total, observacoes, created_by,
    requested_delivery_date, ready_for_production, payment_plan_id, payment_condition_status,
    credit_block_reason
  ) VALUES (
    p_partner_id, v_status, 0, 0, 0, NULLIF(p_observacoes,''), v_uid,
    p_requested_delivery_date, false, p_payment_plan_id,
    CASE WHEN v_quote THEN 'quote_required' ELSE 'defined' END,
    v_block_reason
  ) RETURNING id, numero INTO v_order_id, v_numero;

  FOR v_line IN SELECT * FROM jsonb_array_elements(v_cart->'lines') LOOP
    INSERT INTO public.partner_order_items(
      order_id, product_id, microrganismo_id, quantidade, preco_unitario,
      desconto_percentual, subtotal, unidade_medida, volume_ml,
      produto_nome_snapshot, produto_codigo_snapshot,
      preco_tabela_snapshot, desconto_percentual_snapshot, preco_unitario_final_snapshot,
      pricing_mode_snapshot, price_source_snapshot, base_price_snapshot,
      condition_price_snapshot, plan_discount_percent_snapshot,
      unit_type_snapshot, volume_ml_snapshot, price_rule_id_snapshot
    ) VALUES (
      v_order_id,
      CASE WHEN v_line->>'item_tipo'='produto' THEN (v_line->>'item_id')::uuid END,
      CASE WHEN v_line->>'item_tipo'='microrganismo' THEN (v_line->>'item_id')::uuid END,
      (v_line->>'quantidade')::numeric,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'final_unit_price')::numeric, 0) END,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'plan_discount_percent')::numeric, 0) END,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'line_final_amount')::numeric, 0) END,
      v_line->>'unidade_medida',
      NULLIF(v_line->>'volume_ml','')::numeric,
      v_line->>'nome', v_line->>'codigo',
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'base_price')::numeric, 0) END,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'plan_discount_percent')::numeric, 0) END,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'final_unit_price')::numeric, 0) END,
      v_line->>'pricing_mode', v_line->>'price_source',
      CASE WHEN v_quote THEN NULL ELSE NULLIF(v_line->>'base_price','')::numeric END,
      CASE WHEN v_quote THEN NULL ELSE NULLIF(v_line->>'condition_price','')::numeric END,
      CASE WHEN v_quote THEN NULL ELSE NULLIF(v_line->>'plan_discount_percent','')::numeric END,
      v_line->>'unidade_medida',
      NULLIF(v_line->>'volume_ml','')::numeric,
      NULLIF(v_line->>'rule_id','')::uuid
    );
  END LOOP;

  IF NOT v_quote THEN
    INSERT INTO public.partner_order_payment_terms(
      partner_order_id, payment_plan_id, plan_name_snapshot, plan_code_snapshot,
      discount_percent_snapshot, monthly_interest_percent_snapshot, months_count_snapshot,
      installment_count, first_due_date, interest_type_snapshot,
      table_amount, discount_amount, net_amount_after_discount,
      financial_interest_amount, final_amount, approval_status, created_by,
      pricing_mode_snapshot, credit_decision_snapshot
    ) VALUES (
      v_order_id, v_plan.id, v_plan.name, v_plan.code,
      v_plan.discount_percent, v_plan.monthly_interest_percent, v_plan.months_count,
      v_installments, v_first_due, v_plan.interest_type,
      v_table, v_disc, v_net, v_interest, v_final, v_approval_status, v_uid,
      COALESCE(v_plan.pricing_mode,'discount_from_base'), v_credit
    ) RETURNING id INTO v_terms_id;

    IF v_installments = 1 THEN
      INSERT INTO public.partner_order_payment_schedule(
        partner_order_id, payment_terms_id, installment_number, due_date,
        amount, principal_amount, interest_amount)
      VALUES (v_order_id, v_terms_id, 1, v_first_due, v_final, v_net, v_interest);
    ELSE
      v_inst := ROUND(v_final / v_installments, 2);
      FOR i IN 1..v_installments LOOP
        IF i < v_installments THEN v_amount_i := v_inst; ELSE v_amount_i := ROUND(v_final - v_accum,2); END IF;
        v_accum := v_accum + v_amount_i;
        v_principal_i := ROUND(v_amount_i * (v_net / NULLIF(v_final,0)), 2);
        v_interest_i  := ROUND(v_amount_i - v_principal_i, 2);
        v_due_i := v_first_due + ((i-1)*30);
        INSERT INTO public.partner_order_payment_schedule(
          partner_order_id, payment_terms_id, installment_number, due_date,
          amount, principal_amount, interest_amount)
        VALUES (v_order_id, v_terms_id, i, v_due_i, v_amount_i, v_principal_i, v_interest_i);
      END LOOP;
    END IF;
  END IF;

  UPDATE public.partner_orders SET
    subtotal = v_table, desconto_total = v_disc, total = v_final,
    payment_terms_id = v_terms_id,
    table_amount = v_table, commercial_discount_amount = v_disc,
    net_amount_after_discount = v_net, financial_interest_amount = v_interest,
    final_amount_with_interest = v_final,
    requires_financial_approval = (NOT v_quote AND (v_plan.requires_financial_approval OR v_plan.requires_guarantee)),
    financial_approval_status = CASE WHEN v_quote THEN 'not_required' ELSE v_fin_status END
  WHERE id = v_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_order_id, p_partner_id, v_uid, 'created_via_rpc',
          jsonb_build_object('numero', v_numero, 'total', v_final,
                             'items', jsonb_array_length(p_items),
                             'pricing_mode', COALESCE(v_plan.pricing_mode,'discount_from_base'),
                             'quote_required', v_quote,
                             'cart_hash', v_hash,
                             'hash_validated', true,
                             'idempotency_key', v_idem,
                             'fingerprint_algo', 'reqfp_v2',
                             'credit_reason_code', v_credit->>'reason_code',
                             'requested_delivery_date', p_requested_delivery_date));

  IF NOT v_quote THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
    VALUES (v_order_id, p_partner_id, v_uid, 'payment_terms_defined',
            jsonb_build_object('payment_plan_id', v_plan.id, 'plan_code', v_plan.code,
              'table_amount', v_table, 'discount_amount', v_disc,
              'net_amount_after_discount', v_net, 'financial_interest_amount', v_interest,
              'final_amount', v_final, 'first_due_date', v_first_due,
              'installment_count', v_installments,
              'requires_financial_approval', (v_plan.requires_financial_approval OR v_plan.requires_guarantee)));
  END IF;

  IF COALESCE((v_credit->>'credit_limit')::numeric,0) <= 0 THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
    VALUES (v_order_id, p_partner_id, v_uid, 'credit_limit_not_defined',
            jsonb_build_object('reason_code', v_credit->>'reason_code',
                               'exposicao_projetada', v_credit->>'exposicao_projetada'));
  END IF;

  FOR v_admin IN
    SELECT r AS user_id FROM platform_private.c2_order_internal_recipients(p_partner_id) r -- c2_ord_recipients
  LOOP
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_admin.user_id,
            CASE WHEN v_quote THEN 'pedido_b2b_cotacao' ELSE 'pedido_b2b_novo' END,
            CASE WHEN v_quote THEN 'Cotação B2B ' || v_numero ELSE 'Novo pedido B2B ' || v_numero END,
            CASE WHEN v_quote THEN 'Pedido sob consulta aguardando cotação comercial.'
                 ELSE 'Novo pedido B2B aguardando análise comercial. Total: R$ ' || to_char(v_final,'FM999G999G990D00') END,
            '/comercial/pedidos-b2b');
  END LOOP;

  v_result := jsonb_build_object(
    'id', v_order_id, 'numero', v_numero,
    'status', v_status::text,
    'pricing_mode', COALESCE(v_plan.pricing_mode,'discount_from_base'),
    'quote_required', v_quote,
    'cart_hash', v_hash,
    'idempotency_key', v_idem,
    'subtotal', v_table, 'desconto_total', v_disc, 'total', v_final,
    'table_amount', v_table, 'discount_amount', v_disc,
    'net_amount_after_discount', v_net, 'financial_interest_amount', v_interest,
    'final_amount', v_final,
    'payment_terms_id', v_terms_id,
    'credit_reason_code', v_credit->>'reason_code',
    'credit_block_reason', v_block_reason,
    'requires_financial_approval', (NOT v_quote AND (v_plan.requires_financial_approval OR v_plan.requires_guarantee)),
    'financial_approval_status', CASE WHEN v_quote THEN 'not_required' ELSE v_fin_status END);

  INSERT INTO public.partner_order_idempotency(
    partner_id, idempotency_key, cart_hash, order_id, result_snapshot, created_by, request_fingerprint)
  VALUES (p_partner_id, v_idem, p_expected_cart_hash, v_order_id, v_result, v_uid, v_req_fp);

  DELETE FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='c2_external_order_create' AND target=p_partner_id;
  RETURN v_result;
END
$function$

CREATE OR REPLACE FUNCTION public.b2b_prepare_provisioning_compensation(p_claim uuid, p_fence uuid, p_user uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r platform_private.b2b_provisioning_receipts;
BEGIN
 PERFORM platform_private.require_service_role();
 -- Acquire before receipt/profile locks, never wait for the trigger gate afterward.
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 SELECT * INTO r FROM platform_private.b2b_provisioning_receipts WHERE id=p_claim FOR UPDATE;
 IF r.id IS NULL OR r.fence IS DISTINCT FROM p_fence OR r.user_id IS DISTINCT FROM p_user THEN
  RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF r.status='completed' THEN RETURN 'completed'; END IF;
 IF r.status='aborted' THEN RETURN 'aborted'; END IF;
 UPDATE platform_private.b2b_provisioning_receipts SET status='compensating' WHERE id=r.id;
 RETURN 'compensating';
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_catalog_publish_v1(p_catalog_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_type text;
  v_prev uuid;
BEGIN
  IF v_uid IS NULL OR NOT public.has_role(v_uid, 'administrador'::app_role) THEN
    RAISE EXCEPTION 'CATALOG_FORBIDDEN';
  END IF;

  SELECT catalog_type INTO v_type FROM public.fiscal_reference_catalogs WHERE id = p_catalog_id;
  IF v_type IS NULL THEN
    RAISE EXCEPTION 'CATALOG_NOT_FOUND';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fiscal_reference_entries WHERE catalog_id = p_catalog_id) THEN
    RAISE EXCEPTION 'CATALOG_WITHOUT_ENTRIES';
  END IF;

  SELECT id INTO v_prev FROM public.fiscal_reference_catalogs
   WHERE catalog_type = v_type AND status = 'ACTIVE' AND id <> p_catalog_id;

  IF v_prev IS NOT NULL THEN
    UPDATE public.fiscal_reference_catalogs
       SET status = 'SUPERSEDED', effective_to = current_date, updated_at = now()
     WHERE id = v_prev;
    INSERT INTO public.fiscal_audit_log (table_name, record_id, action, changed_by, new_values)
    VALUES ('fiscal_reference_catalogs', v_prev, 'CATALOG_SUPERSEDED', v_uid,
            jsonb_build_object('catalog_type', v_type, 'superseded_by', p_catalog_id));
  END IF;

  UPDATE public.fiscal_reference_catalogs
     SET status = 'ACTIVE',
         effective_from = coalesce(effective_from, current_date),
         updated_at = now()
   WHERE id = p_catalog_id;

  INSERT INTO public.fiscal_audit_log (table_name, record_id, action, changed_by, new_values)
  VALUES ('fiscal_reference_catalogs', p_catalog_id, 'CATALOG_PUBLISHED', v_uid,
          jsonb_build_object('catalog_type', v_type));
END;
$function$

CREATE OR REPLACE FUNCTION public.b2b_complete_provisioning_compensation(p_claim uuid, p_fence uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r platform_private.b2b_provisioning_receipts;
BEGIN
 PERFORM platform_private.require_service_role();
 -- Acquire before receipt/profile locks, never wait for the trigger gate afterward.
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 SELECT * INTO r FROM platform_private.b2b_provisioning_receipts WHERE id=p_claim FOR UPDATE;
 IF r.id IS NULL OR r.fence IS DISTINCT FROM p_fence OR r.user_id IS DISTINCT FROM p_user OR r.status<>'compensating' THEN
 RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 -- Auth deletion's cascades must have completed; never pretend cleanup succeeded.
 IF EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_user)
 OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user)
 OR EXISTS(SELECT 1 FROM auth.users WHERE id=p_user) THEN
  RAISE EXCEPTION 'b2b_compensation_pending' USING ERRCODE='42501'; END IF;
 -- Live schema has NO Auth FK on these two links. Delete only exact receipt
 -- descendants after proven own Auth removal; unrelated links fail closed.
 IF EXISTS(SELECT 1 FROM public.partner_users WHERE user_id=p_user AND
 (r.partner_id IS NULL OR partner_id IS DISTINCT FROM r.partner_id OR tenant_id IS DISTINCT FROM r.organization_id OR papel IS DISTINCT FROM (CASE WHEN 'parceiro_b2b'=ANY(COALESCE(r.external_roles,ARRAY[r.external_role])) THEN 'gestor' ELSE 'tecnico' END)))
 OR EXISTS(SELECT 1 FROM public.user_clientes WHERE user_id=p_user AND
 (NOT (cliente_id=ANY(r.cliente_ids)) OR assigned_by IS DISTINCT FROM r.actor_id)) THEN
 RAISE EXCEPTION 'b2b_compensation_pending' USING ERRCODE='42501'; END IF;
 DELETE FROM public.partner_users WHERE user_id=r.user_id AND partner_id=r.partner_id AND tenant_id=r.organization_id AND papel=(CASE WHEN 'parceiro_b2b'=ANY(COALESCE(r.external_roles,ARRAY[r.external_role])) THEN 'gestor' ELSE 'tecnico' END);
 DELETE FROM public.user_clientes WHERE user_id=r.user_id AND cliente_id=ANY(r.cliente_ids) AND assigned_by=r.actor_id;
 UPDATE platform_private.b2b_provisioning_receipts SET status='aborted'
 WHERE id=p_claim AND fence=p_fence AND user_id=p_user AND status='compensating';
 IF NOT FOUND THEN RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.producer_request_mutation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid := auth.uid(); v_org uuid;
BEGIN
 -- Não concede acesso: internos continuam sujeitos às policies existentes.
 IF NOT platform_private.has_role(v_actor,'cliente_produtor'::public.app_role) THEN RETURN NEW; END IF;
 IF NOT public.technical_actor_ready(v_actor)
 OR NOT public.technical_refs_in_actor_tenant(NEW.cliente_id,NEW.fazenda_id,NEW.talhao_id)
 OR NOT (NEW.cliente_id = ANY(public.get_cliente_ids_for_user(v_actor)))
 OR NOT EXISTS (SELECT 1 FROM public.clientes c WHERE c.id=NEW.cliente_id AND c.status_cliente::text='ativo') THEN
   RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PRODUCER_REQUEST_SCOPE_DENIED';
 END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.user_id IS DISTINCT FROM v_actor
   OR (NEW.created_by IS NOT NULL AND NEW.created_by IS DISTINCT FROM v_actor)
   OR NEW.status IS DISTINCT FROM 'pendente'
   OR NEW.origem_solicitacao IS DISTINCT FROM 'portal_produtor'
   OR NEW.consultor_atribuido IS NOT NULL OR NEW.tipo_demanda='retorno_tecnico'
   OR NEW.data_prevista_atendimento IS NOT NULL OR NEW.duracao_estimada IS NOT NULL
   OR NEW.registro_origem_id IS NOT NULL OR NEW.external_event_id IS NOT NULL
   OR NEW.confirmacao_produtor IS DISTINCT FROM 'pendente'
   OR NULLIF(NEW.numero_solicitacao,'') IS NOT NULL THEN
     RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PRODUCER_REQUEST_FIELDS_DENIED';
   END IF;
   NEW.created_by := v_actor;
   NEW.created_at := statement_timestamp(); NEW.updated_at := NEW.created_at;
   RETURN NEW;
 END IF;
 -- UPDATE atual do portal é somente resposta à agenda; protege também campos futuros.
 IF (to_jsonb(NEW)-ARRAY['confirmacao_produtor','updated_at']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['confirmacao_produtor','updated_at'])
 OR OLD.tipo_demanda IS DISTINCT FROM 'retorno_tecnico'
 OR OLD.status IS NULL OR OLD.status IN ('concluida','cancelada')
 OR NEW.confirmacao_produtor IS NULL
 OR NEW.confirmacao_produtor NOT IN ('confirmada','remarcacao_solicitada') THEN
   RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PRODUCER_REQUEST_UPDATE_DENIED';
 END IF;
 -- Não notificar atribuições históricas estrangeiras/inativas ou sem carteira comprovada.
 v_org := platform_private.h15_actor_organization();
 IF NOT EXISTS (
   SELECT 1 FROM public.profiles p WHERE p.user_id=OLD.consultor_atribuido
   AND p.organization_id=v_org AND p.ativo IS TRUE
   AND (platform_private.has_role(p.user_id,'administrador'::public.app_role)
     OR platform_private.has_role(p.user_id,'gestor'::public.app_role)
     OR ((platform_private.has_role(p.user_id,'consultor_tecnico'::public.app_role)
       OR platform_private.has_role(p.user_id,'tecnico_agronomo'::public.app_role))
       AND EXISTS (SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p.user_id
       AND uc.cliente_id=OLD.cliente_id AND uc.is_active IS TRUE AND uc.revoked_at IS NULL
       AND (uc.valid_from IS NULL OR uc.valid_from<=now())
       AND (uc.valid_until IS NULL OR uc.valid_until>=now())
       AND uc.access_level::text IN ('read','execute','manage'))))
 ) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PRODUCER_REQUEST_RECIPIENT_DENIED'; END IF;
 NEW.updated_at := statement_timestamp();
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.insert_partner_catalog_access_log_internal(p_action text, p_partner_id uuid, p_user_id uuid, p_cliente_id uuid DEFAULT NULL::uuid, p_simulation_id uuid DEFAULT NULL::uuid, p_order_id uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_id uuid;
  v_allowed text[] := ARRAY[
    'b2b_user_client_assigned','b2b_user_client_unassigned','producer_view',
    'catalog_view','item_view','ficha_view','ficha_download',
    'simulation_created','simulation_sent_to_manager','simulation_archived',
    'simulation_converted_to_order'
  ];
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'user_id obrigatório'; END IF;
  IF NOT (p_action = ANY(v_allowed)) THEN
    RAISE EXCEPTION 'action inválida: %', p_action;
  END IF;
  SELECT role::text INTO v_role FROM public.user_roles WHERE user_id = p_user_id LIMIT 1;
  INSERT INTO public.partner_catalog_access_logs
    (user_id, role, action, partner_id, cliente_id, simulation_id, order_id, target_user_id, details)
  VALUES
    (p_user_id, v_role, p_action, p_partner_id, p_cliente_id, p_simulation_id, p_order_id, p_target_user_id, COALESCE(p_details,'{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.lab_request_replanning(p_os_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_planning_id uuid;
  v_partner_id uuid;
  v_uid uuid := auth.uid();
BEGIN
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN RAISE EXCEPTION 'reason_required'; END IF;
  IF NOT (public.has_role(v_uid,'administrador'::app_role)
          OR public.has_role(v_uid,'producao'::app_role)
          OR public.has_role(v_uid,'gestor'::app_role)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT partner_order_id INTO v_partner_order_id FROM public.ordens_servico WHERE id = p_os_id FOR UPDATE;
  IF v_partner_order_id IS NULL THEN RAISE EXCEPTION 'order_not_found'; END IF;

  SELECT id, partner_id INTO v_planning_id, v_partner_id
  FROM public.production_planning WHERE partner_order_id = v_partner_order_id FOR UPDATE;
  IF v_planning_id IS NULL THEN RAISE EXCEPTION 'planning_not_found'; END IF;

  INSERT INTO public.laboratorio_esteira_eventos (os_id, acao, etapa_nova, usuario_id, observacao)
  VALUES (p_os_id, 'replanejamento_solicitado', 'replanejar', v_uid, p_motivo);

  UPDATE public.production_planning
     SET status = 'replanejar', updated_at = now(),
         production_notes = COALESCE(production_notes || E'\n', '') ||
                            '[' || to_char(now(),'DD/MM/YYYY HH24:MI') || '] Replanejamento: ' || p_motivo
   WHERE id = v_planning_id;

  INSERT INTO public.production_timeline_events (partner_order_id, event_type, actor_id, meta)
  VALUES (v_partner_order_id, 'replanejamento_solicitado', v_uid,
          jsonb_build_object('planning_id', v_planning_id, 'os_id', p_os_id, 'motivo', p_motivo));

  INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_partner_order_id, v_partner_id, v_uid, 'replanejamento_solicitado',
          jsonb_build_object('planning_id', v_planning_id, 'os_id', p_os_id, 'motivo', p_motivo));

  PERFORM public.refresh_esteira_laboratorio();

  RETURN jsonb_build_object('ok', true, 'planning_id', v_planning_id);
END
$function$

CREATE OR REPLACE FUNCTION public.log_my_access_denied_secure(p_context text, p_route_group text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ctx text;
  v_group text;
  v_contexts jsonb;
  v_authorized boolean;
  v_check_failed boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'not_authenticated');
  END IF;

  v_ctx := lower(coalesce(p_context, ''));
  IF v_ctx NOT IN ('b2b', 'technical', 'producer') THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'invalid_context');
  END IF;

  IF v_ctx IN ('b2b', 'technical') THEN
    BEGIN
      v_contexts := public.get_my_available_portal_contexts();
    EXCEPTION WHEN OTHERS THEN
      v_check_failed := true;
    END;
    IF v_check_failed THEN
      RETURN jsonb_build_object('ok', false, 'error_code', 'authorization_check_failed');
    END IF;
    v_authorized := CASE
      WHEN v_ctx = 'b2b' THEN coalesce((v_contexts->>'has_b2b_access')::boolean, false)
      WHEN v_ctx = 'technical' THEN coalesce((v_contexts->>'has_technical_access')::boolean, false)
      ELSE false
    END;
  ELSE
    BEGIN
      v_authorized := public.has_role(v_uid, 'cliente_produtor'::public.app_role);
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'error_code', 'authorization_check_failed');
    END;
  END IF;

  IF v_authorized THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'context_is_authorized');
  END IF;

  v_group := lower(coalesce(p_route_group, ''));
  v_group := regexp_replace(v_group, '[^a-z0-9_\-/]', '', 'g');
  IF length(v_group) > 64 THEN
    v_group := substring(v_group from 1 for 64);
  END IF;
  IF v_group = '' THEN
    v_group := NULL;
  END IF;

  INSERT INTO public.user_context_access_logs(
    user_id, action, context_code, metadata
  )
  VALUES (
    v_uid,
    'access_denied',
    v_ctx,
    jsonb_build_object('route_group', v_group)
  );

  RETURN jsonb_build_object('ok', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error_code', 'log_failed');
END;
$function$

CREATE OR REPLACE FUNCTION public.log_partner_catalog_access_secure(p_action text, p_item_tipo text DEFAULT NULL::text, p_item_id uuid DEFAULT NULL::uuid, p_cliente_id uuid DEFAULT NULL::uuid, p_simulation_id uuid DEFAULT NULL::uuid, p_order_id uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT '{}'::jsonb, p_partner_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_partner_id uuid;
  v_role text;
  v_log_id uuid;
  v_details jsonb;
  v_allowed_actions text[] := ARRAY[
    'b2b_user_client_assigned','b2b_user_client_unassigned','producer_view',
    'catalog_view','item_view','ficha_view','ficha_download',
    'simulation_created','simulation_sent_to_manager','simulation_archived',
    'simulation_converted_to_order'
  ];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  IF NOT (p_action = ANY(v_allowed_actions)) THEN
    RAISE EXCEPTION 'Ação de log inválida: %', p_action;
  END IF;

  IF has_role(v_uid, 'administrador') THEN
    v_role := 'administrador';
    v_partner_id := p_partner_id;
  ELSIF has_role(v_uid, 'gestor_comercial') THEN
    v_role := 'gestor_comercial';
    v_partner_id := p_partner_id;
  ELSIF has_role(v_uid, 'parceiro_b2b') THEN
    v_role := 'parceiro_b2b';
    v_partner_id := get_user_partner_id();
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') THEN
    v_role := 'parceiro_b2b_tecnico';
    v_partner_id := get_user_partner_id();
  ELSE
    RAISE EXCEPTION 'Sem permissão para registrar log B2B';
  END IF;

  v_details := COALESCE(p_details, '{}'::jsonb);
  IF p_item_tipo IS NOT NULL THEN
    v_details := v_details || jsonb_build_object('item_tipo', p_item_tipo);
  END IF;
  IF p_item_id IS NOT NULL THEN
    v_details := v_details || jsonb_build_object('item_id', p_item_id);
  END IF;

  INSERT INTO partner_catalog_access_logs (
    user_id, role, action, partner_id, cliente_id,
    simulation_id, order_id, target_user_id, details
  ) VALUES (
    v_uid, v_role, p_action, v_partner_id, p_cliente_id,
    p_simulation_id, p_order_id, p_target_user_id, v_details
  ) RETURNING id INTO v_log_id;

  RETURN v_log_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.partner_order_sla_status(p_order_id uuid)
 RETURNS TABLE(fase text, fase_inicio timestamp with time zone, horas_decorridas numeric, prazo_horas integer, atrasada boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order RECORD; v_planning RECORD; v_fase text; v_inicio timestamptz;
BEGIN
  SELECT po.id, po.status, po.approved_at INTO v_order
    FROM partner_orders po WHERE po.id = p_order_id;
  IF NOT FOUND OR v_order.approved_at IS NULL THEN RETURN; END IF;

  SELECT pp.status, pp.updated_at INTO v_planning
    FROM production_planning pp WHERE pp.partner_order_id = p_order_id
    ORDER BY pp.created_at DESC LIMIT 1;

  IF v_planning.status = 'entregue' THEN RETURN; END IF;
  IF v_planning.status = 'produzido' THEN v_fase := 'entrega';
  ELSIF v_planning.status = 'em_producao' THEN v_fase := 'em_producao';
  ELSE v_fase := 'planejamento';
  END IF;

  SELECT MAX(event_at) INTO v_inicio
    FROM production_timeline_events
    WHERE partner_order_id = p_order_id
      AND event_type = CASE v_fase
        WHEN 'planejamento' THEN 'planejamento_criado'
        WHEN 'em_producao' THEN 'producao_iniciada'
        WHEN 'entrega' THEN 'envase_concluido'
        ELSE event_type END;

  IF v_inicio IS NULL THEN
    v_inicio := COALESCE(v_planning.updated_at, v_order.approved_at);
  END IF;

  RETURN QUERY
  SELECT v_fase, v_inicio,
         EXTRACT(EPOCH FROM (now() - v_inicio))/3600.0,
         c.prazo_horas,
         c.ativo AND EXTRACT(EPOCH FROM (now() - v_inicio))/3600.0 > c.prazo_horas
    FROM partner_order_sla_config c WHERE c.fase = v_fase;
END; $function$

CREATE OR REPLACE FUNCTION public.partner_reset_prices_to_default(p_partner_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_d numeric(5,2);
  v_count integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  SELECT desconto_padrao INTO v_d FROM public.partner_accounts WHERE id = p_partner_id AND ativo = true AND deleted_at IS NULL FOR UPDATE;
  IF v_d IS NULL THEN RAISE EXCEPTION 'partner_not_found' USING ERRCODE='42501'; END IF;

  UPDATE public.partner_product_prices
     SET desconto_percentual = v_d,
         preco_final = ROUND(preco_tabela * (1 - v_d/100.0), 2),
         updated_at = now()
   WHERE partner_id = p_partner_id
     AND ativo = true
     AND desconto_percentual IS DISTINCT FROM v_d;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.proximo_codigo(_prefixo text, _tabela text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_max INT;
  v_seed INT;
  v_next INT;
BEGIN
  IF _prefixo IS NULL OR _prefixo = '' THEN
    RAISE EXCEPTION 'prefixo obrigatório';
  END IF;

  INSERT INTO public.codigo_sequencias(prefixo, proximo_numero)
  VALUES (_prefixo, 1)
  ON CONFLICT (prefixo) DO NOTHING;

  -- adquire row lock no contador
  UPDATE public.codigo_sequencias
    SET proximo_numero = proximo_numero
    WHERE prefixo = _prefixo
    RETURNING proximo_numero INTO v_seed;

  -- garante alinhamento com o MAX(N) atual da tabela alvo
  IF _tabela = 'produtos' THEN
    SELECT COALESCE(MAX((regexp_match(codigo, '^' || _prefixo || '-(\d+)$'))[1]::int), 0) + 1
      INTO v_max FROM public.produtos;
  ELSIF _tabela = 'microrganismos' THEN
    SELECT COALESCE(MAX((regexp_match(codigo, '^' || _prefixo || '-(\d+)$'))[1]::int), 0) + 1
      INTO v_max FROM public.microrganismos;
  ELSE
    RAISE EXCEPTION 'tabela inválida: %', _tabela;
  END IF;

  v_next := GREATEST(v_seed, v_max);

  UPDATE public.codigo_sequencias
    SET proximo_numero = v_next + 1,
        updated_at = now()
    WHERE prefixo = _prefixo;

  RETURN _prefixo || '-' || v_next;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.c2p1_assignment_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'C2P1_ASSIGNMENT_DELETE_CLOSED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id IN (public.h15_actor_organization(),
 (SELECT commercial_owner_organization_id FROM public.partner_accounts WHERE id=NEW.partner_id),
 (SELECT organization_id FROM public.clientes WHERE id=NEW.customer_id)) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id IN (NEW.partner_id,CASE WHEN TG_OP='UPDATE' THEN OLD.partner_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.clientes WHERE id IN (NEW.customer_id,CASE WHEN TG_OP='UPDATE' THEN OLD.customer_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 IF TG_OP='UPDATE' AND NOT platform_private.c2p1_assignment_allowed(OLD.buyer_scope,OLD.partner_id,OLD.customer_id)
 THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NOT platform_private.c2p1_assignment_allowed(NEW.buyer_scope,NEW.partner_id,NEW.customer_id)
 THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.recalc_partner_order_production(p_partner_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_planning_id   uuid;
  v_partner_id    uuid;
  v_numero        text;
  v_total         int;
  v_em_producao   int;
  v_produzidos    int;
  v_entregues     int;
  v_new_status    production_planning_status;
  v_old_status    production_planning_status;
BEGIN
  SELECT pp.id, pp.status, po.partner_id, po.numero
    INTO v_planning_id, v_old_status, v_partner_id, v_numero
  FROM public.production_planning pp
  JOIN public.partner_orders     po ON po.id = pp.partner_order_id
  WHERE pp.partner_order_id = p_partner_order_id;

  IF v_planning_id IS NULL THEN
    RETURN;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE os.status IN ('em_producao','em_cq','envase','pronto_entrega','entregue','finalizada')),
    COUNT(*) FILTER (WHERE os.status IN ('pronto_entrega','entregue','finalizada')),
    COUNT(*) FILTER (WHERE os.status IN ('entregue','finalizada'))
  INTO v_total, v_em_producao, v_produzidos, v_entregues
  FROM public.production_order_link l
  JOIN public.ordens_servico os ON os.id = l.ordem_servico_id
  WHERE l.partner_order_id = p_partner_order_id;

  IF v_total = 0 THEN
    v_new_status := 'aguardando_planejamento';
  ELSIF v_entregues = v_total THEN
    v_new_status := 'entregue';
  ELSIF v_produzidos = v_total THEN
    v_new_status := 'produzido';
  ELSIF v_em_producao > 0 THEN
    v_new_status := 'em_producao';
  ELSE
    v_new_status := 'planejado';
  END IF;

  IF v_new_status IS DISTINCT FROM v_old_status THEN
    UPDATE public.production_planning
       SET status = v_new_status,
           updated_at = now()
     WHERE id = v_planning_id;

    INSERT INTO public.production_timeline_events (partner_order_id, event_type, meta)
    VALUES (
      p_partner_order_id,
      CASE v_new_status
        WHEN 'planejado'   THEN 'op_gerada'
        WHEN 'em_producao' THEN 'producao_iniciada'
        WHEN 'produzido'   THEN 'producao_finalizada'
        WHEN 'entregue'    THEN 'entrega_realizada'
        ELSE 'status_alterado'
      END,
      jsonb_build_object(
        'from', v_old_status::text,
        'to',   v_new_status::text,
        'total_ops', v_total,
        'em_producao', v_em_producao,
        'produzidos', v_produzidos,
        'entregues', v_entregues
      )
    );

    IF v_new_status IN ('em_producao','produzido','entregue') THEN
      INSERT INTO public.notificacoes_operacionais (usuario_id, tipo, titulo, mensagem, link)
      SELECT pu.user_id,
             'pedido_b2b',
             CASE v_new_status
               WHEN 'em_producao' THEN 'Pedido ' || v_numero || ' em produção'
               WHEN 'produzido'   THEN 'Pedido ' || v_numero || ' pronto para expedição'
               WHEN 'entregue'    THEN 'Pedido ' || v_numero || ' entregue'
             END,
             CASE v_new_status
               WHEN 'em_producao' THEN 'A produção do seu pedido foi iniciada.'
               WHEN 'produzido'   THEN 'Produção concluída. Aguardando envase e expedição.'
               WHEN 'entregue'    THEN 'Seu pedido foi entregue.'
             END,
             '/portal-parceiro/pedidos'
        FROM public.partner_users pu
       WHERE pu.partner_id = v_partner_id;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_b2b_payment_terms_secure(p_partner_order_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_terms_id uuid;
  v_created_by uuid;
  v_numero text;
BEGIN

  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF NOT (public.has_role(v_uid,'administrador')
       OR public.has_role(v_uid,'financeiro')
       OR public.has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required';
  END IF;

  SELECT po.payment_terms_id, po.created_by, po.numero
    INTO v_terms_id, v_created_by, v_numero
  FROM public.partner_orders po
  WHERE po.id = p_partner_order_id;

  IF v_terms_id IS NULL THEN
    RAISE EXCEPTION 'payment_terms_not_defined';
  END IF;

  UPDATE public.partner_order_payment_terms
     SET approval_status = 'rejected',
         approved_by = v_uid,
         approved_at = now(),
         approval_notes = p_reason,
         updated_at = now()
   WHERE id = v_terms_id;

  UPDATE public.partner_orders
     SET financial_approval_status = 'rejected',
         payment_condition_status = 'rejected',
         updated_at = now()
   WHERE id = p_partner_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, acao, usuario_id, dados_novos)
  VALUES (p_partner_order_id, 'payment_terms_rejected', v_uid,
          jsonb_build_object('reason', p_reason));

  IF v_created_by IS NOT NULL THEN
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_created_by, 'b2b_payment_terms',
            'Condição financeira reprovada',
            format('Pedido %s teve a condição de pagamento reprovada: %s',
                   COALESCE(v_numero,'B2B'), p_reason),
            '/comercial/pedidos-b2b');
  END IF;

  RETURN jsonb_build_object('success', true, 'status', 'rejected');
END;
$function$

CREATE OR REPLACE FUNCTION public.request_b2b_payment_terms_adjustment_secure(p_partner_order_id uuid, p_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_terms_id uuid;
  v_created_by uuid;
  v_numero text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;
  IF NOT (public.has_role(v_uid,'administrador')
       OR public.has_role(v_uid,'financeiro')
       OR public.has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_notes IS NULL OR btrim(p_notes) = '' THEN
    RAISE EXCEPTION 'notes_required';
  END IF;

  SELECT po.payment_terms_id, po.created_by, po.numero
    INTO v_terms_id, v_created_by, v_numero
  FROM public.partner_orders po
  WHERE po.id = p_partner_order_id;

  IF v_terms_id IS NULL THEN RAISE EXCEPTION 'payment_terms_not_defined'; END IF;

  UPDATE public.partner_order_payment_terms
     SET approval_status = 'pending',
         approval_notes = p_notes,
         updated_at = now()
   WHERE id = v_terms_id;

  UPDATE public.partner_orders
     SET financial_approval_status = 'pending',
         payment_condition_status = 'adjustment_requested',
         updated_at = now()
   WHERE id = p_partner_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, acao, usuario_id, dados_novos)
  VALUES (p_partner_order_id, 'payment_terms_adjustment_requested', v_uid,
          jsonb_build_object('notes', p_notes));

  IF v_created_by IS NOT NULL THEN
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_created_by, 'b2b_payment_terms',
            'Ajuste na condição solicitado',
            format('Pedido %s precisa de ajuste na condição de pagamento: %s',
                   COALESCE(v_numero,'B2B'), p_notes),
            '/comercial/pedidos-b2b');
  END IF;

  RETURN jsonb_build_object('success', true, 'status', 'adjustment_requested');
END;
$function$

CREATE OR REPLACE FUNCTION public.request_partner_order_items(p_order_id uuid, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_pid uuid; v_prev partner_order_status; v_numero text; v_partner_user uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_motivo IS NULL OR length(trim(p_motivo)) = 0 THEN
    RAISE EXCEPTION 'reason_required';
  END IF;

  SELECT partner_id, status, numero INTO v_pid, v_prev, v_numero
    FROM public.partner_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;

  IF v_prev NOT IN ('em_analise_comercial','solicitado','rascunho') THEN
    RAISE EXCEPTION 'invalid_status_transition: %', v_prev;
  END IF;

  UPDATE public.partner_orders
     SET status = 'aguardando_itens',
         itens_pendentes_motivo = p_motivo,
         itens_pendentes_solicitado_em = now(),
         itens_pendentes_solicitado_por = v_uid,
         itens_pendentes_resolvido_em = NULL,
         updated_at = now()
   WHERE id = p_order_id
     AND status = v_prev;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'concurrent_update: status do pedido mudou';
  END IF;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'request_items',
          jsonb_build_object('status', v_prev),
          jsonb_build_object('status','aguardando_itens','motivo',p_motivo));

  FOR v_partner_user IN SELECT user_id FROM public.partner_users WHERE partner_id = v_pid LOOP
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_partner_user, 'pedido_b2b_itens_pendentes',
            'Pedido ' || v_numero || ' — itens pendentes',
            COALESCE(p_motivo, 'O Comercial solicitou que você complete o pedido com os itens necessários.'),
            '/portal-parceiro/pedidos');
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_assumir_alerta(p_alerta_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alerta record;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
  END IF;
  IF NOT public.can_user_access_alerta(p_alerta_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden');
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'alerta_nao_encontrado');
  END IF;

  UPDATE public.alertas_operacionais
    SET responsavel_id = auth.uid()
    WHERE id = p_alerta_id;

  BEGIN
    INSERT INTO public.alertas_acoes (alerta_id, user_id, acao, observacao)
      VALUES (p_alerta_id, auth.uid(), 'assumir', 'Alerta assumido');
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  PERFORM public.rpc_recalcular_prioridade_alerta(p_alerta_id);
  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.tenant_email_validate_config(p_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE v_key text; v text;
BEGIN
 IF p_config IS NULL OR jsonb_typeof(p_config)<>'object'
 OR (SELECT count(*) FROM jsonb_object_keys(p_config))<>7
 OR NOT p_config ?& ARRAY['host','port','tls_mode','username','from_email','reply_to','from_name'] THEN
  RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023';
 END IF;
 FOREACH v_key IN ARRAY ARRAY['host','tls_mode','username','from_email','reply_to','from_name'] LOOP
  IF jsonb_typeof(p_config->v_key)<>'string' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
  v:=p_config->>v_key;
  IF length(v)>255 OR v ~ '[[:cntrl:]]' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 END LOOP;
 v:=p_config->>'host';
 IF length(v)>253 OR v !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$'
 OR v ~ '(^|\.)(localhost|local|internal|lan|home|test|invalid|example|onion)$'
 OR v ~ '(^|\.)(metadata|metadata\.google\.internal)$' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p_config->'port')<>'number' OR (p_config->>'port')!~ '^[0-9]{1,5}$'
 OR (p_config->>'port')::int NOT BETWEEN 1 AND 65535 OR (p_config->>'port')::int=25
 OR p_config->>'tls_mode' NOT IN ('implicit_tls','starttls_required')
 OR length(p_config->>'username')=0 OR length(p_config->>'from_name')=0
 OR (p_config->>'from_email') !~ '^[A-Za-z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)+$'
 OR ((p_config->>'reply_to')<>'' AND (p_config->>'reply_to') !~ '^[A-Za-z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)+$') THEN
  RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_gerar_etiquetas_embalagens_lote(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ids uuid[] := COALESCE(
    (SELECT array_agg((x)::uuid) FROM jsonb_array_elements_text(COALESCE(p_payload->'embalagem_ids','[]'::jsonb)) AS t(x)),
    ARRAY[]::uuid[]);
  v_tipo text := COALESCE(NULLIF(p_payload->>'tipo_etiqueta',''), 'principal');
  v_template text := NULLIF(p_payload->>'template_codigo','');
  v_emb uuid;
  v_existing uuid;
  v_res jsonb;
  v_geradas jsonb := '[]'::jsonb;
  v_reaproveitadas jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF array_length(v_ids,1) IS NULL THEN
    RAISE EXCEPTION 'label_batch_empty: informe ao menos uma embalagem';
  END IF;
  IF array_length(v_ids,1) > 500 THEN
    RAISE EXCEPTION 'label_batch_too_large: máximo de 500 embalagens por execução';
  END IF;

  FOREACH v_emb IN ARRAY v_ids LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('etiqueta_embalagem:' || v_emb::text, 0));

    SELECT id INTO v_existing FROM public.produto_etiquetas
     WHERE embalagem_id = v_emb AND tipo_etiqueta = v_tipo AND status <> 'cancelada'
     LIMIT 1;

    IF v_existing IS NOT NULL THEN
      -- idempotente: já existe etiqueta ativa desse tipo para a embalagem
      v_reaproveitadas := v_reaproveitadas || jsonb_build_object('embalagem_id', v_emb, 'etiqueta_id', v_existing);
      CONTINUE;
    END IF;

    v_res := public.rpc_gerar_etiqueta_produto(jsonb_strip_nulls(jsonb_build_object(
      'embalagem_id', v_emb,
      'tipo_etiqueta', v_tipo,
      'template_codigo', v_template
    )));

    v_geradas := v_geradas || jsonb_build_object(
      'embalagem_id', v_emb,
      'etiqueta_id', v_res->>'etiqueta_id',
      'codigo_etiqueta', v_res->>'codigo_etiqueta');
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'tipo_etiqueta', v_tipo,
    'total_solicitado', array_length(v_ids,1),
    'total_geradas', jsonb_array_length(v_geradas),
    'total_reaproveitadas', jsonb_array_length(v_reaproveitadas),
    'geradas', v_geradas,
    'reaproveitadas', v_reaproveitadas
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.return_catalog_profile_to_review(p_kind text, p_profile_id uuid, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_exists boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required';
  END IF;
  IF NOT (
    has_role(v_uid, 'administrador'::app_role)
    OR has_role(v_uid, 'gestor'::app_role)
    OR has_role(v_uid, 'consultor_tecnico'::app_role)
    OR has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_kind NOT IN ('micro','produto') THEN
    RAISE EXCEPTION 'invalid_kind';
  END IF;
  IF p_motivo IS NULL OR length(btrim(p_motivo)) < 5 THEN
    RAISE EXCEPTION 'motivo_too_short';
  END IF;

  IF p_kind = 'micro' THEN
    SELECT EXISTS(SELECT 1 FROM microorganism_technical_profiles WHERE id = p_profile_id) INTO v_exists;
    IF NOT v_exists THEN RAISE EXCEPTION 'profile_not_found'; END IF;
    UPDATE microorganism_technical_profiles
    SET status_validacao = 'em_revisao',
        updated_by = v_uid,
        updated_at = now()
    WHERE id = p_profile_id;
    INSERT INTO catalog_technical_audit_logs (entidade_tipo, entidade_id, acao, usuario_id, dados_novos)
    VALUES ('ficha_microrganismo', p_profile_id, 'retorno_ajuste', v_uid,
      jsonb_build_object('motivo_retorno_ajuste', btrim(p_motivo)));
  ELSE
    SELECT EXISTS(SELECT 1 FROM product_technical_profiles WHERE id = p_profile_id) INTO v_exists;
    IF NOT v_exists THEN RAISE EXCEPTION 'profile_not_found'; END IF;
    UPDATE product_technical_profiles
    SET status_validacao = 'em_revisao',
        updated_by = v_uid,
        updated_at = now()
    WHERE id = p_profile_id;
    INSERT INTO catalog_technical_audit_logs (entidade_tipo, entidade_id, acao, usuario_id, dados_novos)
    VALUES ('ficha_produto', p_profile_id, 'retorno_ajuste', v_uid,
      jsonb_build_object('motivo_retorno_ajuste', btrim(p_motivo)));
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.respond_b2b_order_quote_secure(p_order_id uuid, p_lines jsonb, p_first_due_date date DEFAULT NULL::date, p_installment_count integer DEFAULT NULL::integer, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean; v_is_gestor boolean;
  v_order record; v_plan record;
  v_line jsonb; v_item record; v_price numeric(14,4);
  v_count_lines integer; v_count_distinct integer; v_count_items integer;
  v_prev jsonb;
  v_table numeric(14,2); v_net numeric(14,2); v_final numeric(14,2); v_interest numeric(14,2);
  v_installments integer; v_first_due date; v_terms_id uuid;
  v_fin_status text; v_approval_status text;
  v_inst numeric(14,2); v_accum numeric(14,2) := 0;
  v_amount_i numeric(14,2); v_principal_i numeric(14,2); v_interest_i numeric(14,2);
  v_due_i date; i integer; v_final_status text; v_block_reason text := NULL;
  v_partner_user record; v_credit jsonb; v_new_status partner_order_status;
BEGIN

  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF; PERFORM platform_private.b2b_internal_assert_origin((SELECT internal_origin_snapshot FROM public.partner_orders WHERE id=p_order_id),(SELECT partner_id FROM public.partner_orders WHERE id=p_order_id),(SELECT cliente_id FROM public.partner_orders WHERE id=p_order_id)); IF NOT public.b2b_phase1_order_visible(p_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;

  v_is_admin  := has_role(v_uid,'administrador'::app_role);
  v_is_gestor := has_role(v_uid,'gestor_comercial'::app_role);
  IF NOT (v_is_admin OR v_is_gestor) THEN
    RAISE EXCEPTION 'forbidden_quote_response';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'quote_incomplete';
  END IF;

  -- locks em ordem deterministica: (1) pedido/cotacao
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_quote:' || p_order_id::text, 0));

  SELECT * INTO v_order FROM public.partner_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
  IF v_order.status <> 'aguardando_cotacao'::partner_order_status THEN
    RAISE EXCEPTION 'order_not_in_quote_state';
  END IF;
  IF EXISTS(SELECT 1 FROM public.partner_order_payment_terms WHERE partner_order_id=p_order_id) THEN RAISE EXCEPTION 'B2B_INTERNAL_QUOTE_REVISION_UNAVAILABLE' USING ERRCODE='42501'; END IF; IF v_order.payment_plan_id IS NULL THEN RAISE EXCEPTION 'payment_plan_required'; END IF;

  -- (2) credito do parceiro
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || v_order.partner_id::text, 0));

  SELECT * INTO v_plan FROM public.commercial_payment_plans WHERE id = v_order.payment_plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF; IF NOT public.fn_b2b_plan_selectable(v_plan.id) THEN RAISE EXCEPTION 'plan_not_selectable'; END IF;
  IF v_plan.active = false THEN RAISE EXCEPTION 'plan_inactive'; END IF;

  SELECT count(*) INTO v_count_items FROM public.partner_order_items WHERE order_id = p_order_id;
  IF v_count_items = 0 THEN RAISE EXCEPTION 'empty_cart'; END IF;

  SELECT count(*), count(DISTINCT (l->>'item_id')::uuid)
    INTO v_count_lines, v_count_distinct
    FROM jsonb_array_elements(p_lines) l;
  IF v_count_lines <> v_count_distinct THEN RAISE EXCEPTION 'quote_duplicate_line'; END IF;
  IF v_count_distinct <> v_count_items THEN RAISE EXCEPTION 'quote_incomplete'; END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'item_id', poi.id, 'preco_unitario', poi.preco_unitario,
           'subtotal', poi.subtotal,
           'pricing_mode_snapshot', poi.pricing_mode_snapshot,
           'price_source_snapshot', poi.price_source_snapshot)), '[]'::jsonb)
    INTO v_prev
    FROM public.partner_order_items poi WHERE poi.order_id = p_order_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    BEGIN
      v_price := NULLIF(v_line->>'unit_price','')::numeric;
    EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'invalid_quote_price'; END;
    IF v_price IS NULL OR v_price <= 0 OR v_price > 10000000 THEN
      RAISE EXCEPTION 'invalid_quote_price';
    END IF;
    IF v_price <> ROUND(v_price, 4) THEN RAISE EXCEPTION 'invalid_quote_price_scale'; END IF;

    SELECT * INTO v_item FROM public.partner_order_items
     WHERE id = (v_line->>'item_id')::uuid AND order_id = p_order_id
     FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'quote_item_not_found'; END IF;

    UPDATE public.partner_order_items SET
      preco_unitario                 = v_price,
      desconto_percentual            = 0,
      subtotal                       = ROUND(v_item.quantidade * v_price, 2),
      preco_tabela_snapshot          = v_price,
      desconto_percentual_snapshot   = 0,
      preco_unitario_final_snapshot  = v_price,
      pricing_mode_snapshot          = 'fixed_item_price',
      price_source_snapshot          = 'quote_manual',
      base_price_snapshot            = v_price,
      condition_price_snapshot       = v_price,
      plan_discount_percent_snapshot = 0
    WHERE id = v_item.id;
  END LOOP;

  SELECT COALESCE(SUM(subtotal),0)::numeric(14,2) INTO v_table
    FROM public.partner_order_items WHERE order_id = p_order_id;
  v_net := v_table;

  IF v_plan.minimum_order_amount IS NOT NULL AND v_table < v_plan.minimum_order_amount THEN
    RAISE EXCEPTION 'below_minimum_order_amount';
  END IF;

  v_final := public.fn_b2b_apply_interest(v_net, v_plan.interest_type,
               v_plan.monthly_interest_percent, v_plan.months_count);
  v_interest := ROUND(v_final - v_net, 2);

  IF p_installment_count IS NOT NULL AND p_installment_count <= 0 THEN
    RAISE EXCEPTION 'invalid_installment_count';
  END IF;
  v_installments := GREATEST(COALESCE(p_installment_count, v_plan.installment_count, 1), 1);

  IF p_first_due_date IS NOT NULL AND p_first_due_date < current_date THEN
    RAISE EXCEPTION 'invalid_due_date';
  END IF;
  v_first_due := COALESCE(p_first_due_date, current_date + v_plan.max_days);

  IF v_plan.requires_financial_approval OR v_plan.requires_guarantee THEN
    v_fin_status := 'pending'; v_approval_status := 'pending';
  ELSE
    v_fin_status := 'not_required'; v_approval_status := 'not_required';
  END IF;

  IF v_first_due > current_date + v_plan.max_days THEN
    IF NOT (v_plan.requires_financial_approval OR v_plan.requires_guarantee) THEN
      v_first_due := current_date + v_plan.max_days;
    ELSE
      v_fin_status := 'pending'; v_approval_status := 'pending';
    END IF;
  END IF;

  -- ---- DECISAO DE CREDITO SOBRE O TOTAL RECEM-COTADO -----------------
  -- o proprio pedido e excluido da exposicao para nao ser contado duas vezes
  v_credit := public.fn_b2b_credit_exposure(v_order.partner_id, v_final, p_order_id);

  IF COALESCE((v_credit->>'block_if_overdue')::boolean,false)
     AND COALESCE((v_credit->>'tem_vencidos')::boolean,false) THEN
    RAISE EXCEPTION 'credit_blocked_overdue';
  END IF;

  IF COALESCE((v_credit->>'credit_limit')::numeric,0) > 0
     AND (v_credit->>'exposicao_projetada')::numeric > (v_credit->>'credit_limit')::numeric THEN
    IF COALESCE(v_credit->>'credit_limit_action','block') = 'approval_required' THEN
      v_new_status := 'aguardando_aprovacao_credito'::partner_order_status;
      v_block_reason := 'limite_excedido';
    ELSE
      RAISE EXCEPTION 'credit_limit_exceeded';
    END IF;
  ELSE
    v_new_status := 'em_analise_comercial'::partner_order_status;
  END IF;

  DELETE FROM public.partner_order_payment_schedule WHERE partner_order_id = p_order_id;
  DELETE FROM public.partner_order_payment_terms WHERE partner_order_id = p_order_id;

  INSERT INTO public.partner_order_payment_terms(
    partner_order_id, payment_plan_id, plan_name_snapshot, plan_code_snapshot,
    discount_percent_snapshot, monthly_interest_percent_snapshot, months_count_snapshot,
    installment_count, first_due_date, interest_type_snapshot,
    table_amount, discount_amount, net_amount_after_discount,
    financial_interest_amount, final_amount, approval_status, created_by,
    pricing_mode_snapshot, credit_decision_snapshot
  ) VALUES (
    p_order_id, v_plan.id, v_plan.name, v_plan.code,
    0, v_plan.monthly_interest_percent, v_plan.months_count,
    v_installments, v_first_due, v_plan.interest_type,
    v_table, 0, v_net, v_interest, v_final, v_approval_status, v_uid,
    'fixed_item_price', v_credit
  ) RETURNING id INTO v_terms_id;

  IF v_installments = 1 THEN
    INSERT INTO public.partner_order_payment_schedule(
      partner_order_id, payment_terms_id, installment_number, due_date,
      amount, principal_amount, interest_amount)
    VALUES (p_order_id, v_terms_id, 1, v_first_due, v_final, v_net, v_interest);
  ELSE
    v_inst := ROUND(v_final / v_installments, 2);
    FOR i IN 1..v_installments LOOP
      IF i < v_installments THEN v_amount_i := v_inst; ELSE v_amount_i := ROUND(v_final - v_accum,2); END IF;
      v_accum := v_accum + v_amount_i;
      v_principal_i := ROUND(v_amount_i * (v_net / NULLIF(v_final,0)), 2);
      v_interest_i  := ROUND(v_amount_i - v_principal_i, 2);
      v_due_i := v_first_due + ((i-1)*30);
      INSERT INTO public.partner_order_payment_schedule(
        partner_order_id, payment_terms_id, installment_number, due_date,
        amount, principal_amount, interest_amount)
      VALUES (p_order_id, v_terms_id, i, v_due_i, v_amount_i, v_principal_i, v_interest_i);
    END LOOP;
  END IF;

  UPDATE public.partner_orders SET
    status = v_new_status,
    payment_condition_status = 'defined',
    credit_block_reason = v_block_reason,
    subtotal = v_table, desconto_total = 0, total = v_final,
    payment_terms_id = v_terms_id,
    table_amount = v_table, commercial_discount_amount = 0,
    net_amount_after_discount = v_net, financial_interest_amount = v_interest,
    final_amount_with_interest = v_final,
    requires_financial_approval = (v_plan.requires_financial_approval OR v_plan.requires_guarantee),
    financial_approval_status = v_fin_status
  WHERE id = p_order_id;

  SELECT status::text INTO v_final_status FROM public.partner_orders WHERE id = p_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_order.partner_id, v_uid, 'quote_responded',
          jsonb_build_object('items', v_prev,
                             'table_amount', v_order.table_amount,
                             'total', v_order.total,
                             'status', 'aguardando_cotacao'),
          jsonb_build_object('table_amount', v_table, 'final_amount', v_final,
                             'installment_count', v_installments,
                             'first_due_date', v_first_due,
                             'status', v_final_status,
                             'credit_block_reason', v_block_reason,
                             'credit_decision', v_credit,
                             'motivo', NULLIF(p_motivo,'')));

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (p_order_id, v_order.partner_id, v_uid, 'payment_terms_defined',
          jsonb_build_object('payment_plan_id', v_plan.id, 'plan_code', v_plan.code,
            'table_amount', v_table, 'discount_amount', 0,
            'net_amount_after_discount', v_net, 'financial_interest_amount', v_interest,
            'final_amount', v_final, 'first_due_date', v_first_due,
            'installment_count', v_installments,
            'credit_reason_code', v_credit->>'reason_code',
            'source', 'quote_response'));

  FOR v_partner_user IN
    SELECT pu.user_id FROM public.partner_users pu WHERE pu.partner_id = v_order.partner_id
  LOOP
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_partner_user.user_id, 'pedido_b2b_cotacao_respondida',
            'Cotação respondida — pedido ' || v_order.numero,
            'A cotação do seu pedido foi respondida. Total: R$ ' || to_char(v_final,'FM999G999G990D00'),
            '/portal-parceiro/pedidos');
  END LOOP;

  RETURN jsonb_build_object(
    'id', p_order_id,
    'numero', v_order.numero,
    'status', v_final_status,
    'credit_block_reason', v_block_reason,
    'credit_reason_code', v_credit->>'reason_code',
    'table_amount', v_table,
    'net_amount_after_discount', v_net,
    'financial_interest_amount', v_interest,
    'final_amount', v_final,
    'installment_count', v_installments,
    'first_due_date', v_first_due,
    'payment_terms_id', v_terms_id,
    'requires_financial_approval', (v_plan.requires_financial_approval OR v_plan.requires_guarantee),
    'financial_approval_status', v_fin_status);
END $function$

