CREATE OR REPLACE FUNCTION public.rpc_cc_upsert_item_price(p_id uuid, p_assignment_id uuid, p_plan_id uuid, p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric, p_min_quantity numeric, p_pricing_mode text, p_condition_price numeric, p_discount_percent numeric, p_valid_from date, p_valid_until date, p_is_exception boolean, p_motivo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_before jsonb;
BEGIN
 IF NOT platform_private.c2p1_item_allowed(p_assignment_id,p_plan_id,p_buyer_scope,p_partner_id,p_customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF p_is_exception AND (p_motivo IS NULL OR length(btrim(p_motivo))=0) THEN
    RAISE EXCEPTION 'motivo_required_for_exception';
  END IF;
  PERFORM public.fn_cc_validate_item_input(p_plan_id, p_pricing_mode, p_condition_price, p_discount_percent);

  IF p_id IS NULL THEN
    INSERT INTO public.commercial_condition_item_prices
      (assignment_id,plan_id,buyer_scope,partner_id,customer_id,product_id,microrganismo_id,
       unit_type,volume_ml,min_quantity,pricing_mode,condition_price,discount_percent,
       valid_from,valid_until,is_exception,motivo,created_by,updated_by)
    VALUES (p_assignment_id,p_plan_id,p_buyer_scope,p_partner_id,p_customer_id,p_product_id,p_microrganismo_id,
       p_unit_type,p_volume_ml,COALESCE(p_min_quantity,0),p_pricing_mode,p_condition_price,p_discount_percent,
       COALESCE(p_valid_from,CURRENT_DATE),p_valid_until,COALESCE(p_is_exception,false),p_motivo,auth.uid(),auth.uid())
    RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('item_price',v_id,'create',NULL,
      to_jsonb((SELECT i FROM public.commercial_condition_item_prices i WHERE i.id=v_id)),p_motivo);
  ELSE
    SELECT to_jsonb(i) INTO v_before FROM public.commercial_condition_item_prices i WHERE i.id=p_id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id) FOR UPDATE;
    IF v_before IS NULL THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF (v_before->>'status') NOT IN ('draft','pending_approval') THEN RAISE EXCEPTION 'item_price_not_editable'; END IF;
    UPDATE public.commercial_condition_item_prices
       SET assignment_id=p_assignment_id, plan_id=p_plan_id, buyer_scope=p_buyer_scope,
           partner_id=p_partner_id, customer_id=p_customer_id, product_id=p_product_id,
           microrganismo_id=p_microrganismo_id, unit_type=p_unit_type, volume_ml=p_volume_ml,
           min_quantity=COALESCE(p_min_quantity,0), pricing_mode=p_pricing_mode,
           condition_price=p_condition_price, discount_percent=p_discount_percent,
           valid_from=COALESCE(p_valid_from,valid_from), valid_until=p_valid_until,
           is_exception=COALESCE(p_is_exception,false), motivo=p_motivo, updated_by=auth.uid()
     WHERE id=p_id RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('item_price',v_id,'update',v_before,
      to_jsonb((SELECT i FROM public.commercial_condition_item_prices i WHERE i.id=v_id)),p_motivo);
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_admin_communication_health_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_by_status jsonb;
  v_by_canal jsonb;
  v_by_event jsonb;
  v_by_canal_status jsonb;
  v_pending int;
  v_dlq int;
  v_processing int;
  v_oldest_pending_age_s int;
  v_oldest_locked_age_s int;
  v_success_24h int;
  v_failed_24h int;
  v_success_rate numeric;
  v_avg_attempts_sent numeric;
  v_avg_attempts_terminal numeric;
  v_max_attempts int;
  v_avg_latency_ms numeric;
  v_p95_latency_ms numeric;
  v_realtime_ready boolean;
  v_last_replay_at timestamptz;
  v_last_worker_activity timestamptz;
  v_last_sent_at timestamptz;
  v_worker_status text;
  v_worker_age_s int;
  v_flag_delivery boolean;
  v_flag_email boolean;
  v_flag_wa boolean;
  v_flag_inapp boolean;
  v_flag_webhook boolean;
  v_flag_test_mode boolean;
  v_prov_email jsonb;
  v_prov_wa jsonb;
  v_prov jsonb;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();

  SELECT jsonb_object_agg(status,cnt) INTO v_by_status
    FROM (SELECT status::text AS status, count(*) AS cnt
            FROM public.comunicacao_outbox GROUP BY status) s;

  SELECT jsonb_object_agg(canal,cnt) INTO v_by_canal
    FROM (SELECT canal::text AS canal, count(*) AS cnt
            FROM public.comunicacao_outbox GROUP BY canal) c;

  SELECT jsonb_object_agg(event_key, stats) INTO v_by_event
  FROM (
    SELECT e.event_key AS event_key,
           jsonb_build_object(
             'total', count(*),
             'sent', count(*) FILTER (WHERE o.status='sent'),
             'pending', count(*) FILTER (WHERE o.status='pending'),
             'failed', count(*) FILTER (WHERE o.status='failed'),
             'dead_letter', count(*) FILTER (WHERE o.status='dead_letter')
           ) AS stats
      FROM public.comunicacao_outbox o
      JOIN public.comunicacao_eventos e ON e.id = o.event_id
     WHERE o.created_at > now() - interval '7 days'
     GROUP BY e.event_key
  ) x;

  SELECT jsonb_object_agg(key, cnt) INTO v_by_canal_status
  FROM (
    SELECT (canal::text || '.' || status::text) AS key, count(*) AS cnt
      FROM public.comunicacao_outbox
     WHERE created_at > now() - interval '7 days'
     GROUP BY 1
  ) y;

  SELECT count(*) INTO v_pending FROM public.comunicacao_outbox WHERE status='pending';
  SELECT count(*) INTO v_dlq FROM public.comunicacao_outbox WHERE status='dead_letter';
  SELECT count(*) INTO v_processing FROM public.comunicacao_outbox WHERE status='processing';

  SELECT COALESCE(EXTRACT(EPOCH FROM (now() - min(created_at)))::int, 0)
    INTO v_oldest_pending_age_s
    FROM public.comunicacao_outbox WHERE status='pending';

  SELECT COALESCE(EXTRACT(EPOCH FROM (now() - min(locked_at)))::int, 0)
    INTO v_oldest_locked_age_s
    FROM public.comunicacao_outbox WHERE status='processing' AND locked_at IS NOT NULL;

  SELECT count(*) INTO v_success_24h
    FROM public.comunicacao_outbox
   WHERE status='sent' AND sent_at > now() - interval '24 hours';
  SELECT count(*) INTO v_failed_24h
    FROM public.comunicacao_outbox
   WHERE status IN ('failed','dead_letter') AND updated_at > now() - interval '24 hours';

  v_success_rate := CASE WHEN (v_success_24h + v_failed_24h) = 0 THEN NULL
                         ELSE round(v_success_24h::numeric / (v_success_24h + v_failed_24h) * 100, 2) END;

  SELECT round(avg(attempts)::numeric, 2), max(attempts)
    INTO v_avg_attempts_sent, v_max_attempts
    FROM public.comunicacao_outbox
   WHERE status='sent' AND sent_at > now() - interval '24 hours';

  SELECT round(avg(attempts)::numeric, 2)
    INTO v_avg_attempts_terminal
    FROM public.comunicacao_outbox
   WHERE status IN ('failed','dead_letter') AND updated_at > now() - interval '24 hours';

  SELECT round(avg(EXTRACT(EPOCH FROM (sent_at - created_at))*1000)::numeric, 0),
         round((percentile_cont(0.95) WITHIN GROUP (ORDER BY EXTRACT(EPOCH FROM (sent_at - created_at))*1000))::numeric, 0)
    INTO v_avg_latency_ms, v_p95_latency_ms
    FROM public.comunicacao_outbox
   WHERE status='sent' AND sent_at > now() - interval '24 hours' AND sent_at IS NOT NULL;

  SELECT EXISTS (
    SELECT 1 FROM pg_publication_tables
     WHERE pubname='supabase_realtime'
       AND schemaname='public'
       AND tablename IN ('notificacoes_operacionais','portal_notificacoes')
    HAVING count(*) >= 2
  ) INTO v_realtime_ready;

  SELECT max(created_at) INTO v_last_replay_at
    FROM public.comunicacao_dlq_replay_audit;

  SELECT GREATEST(
    COALESCE((SELECT max(locked_at) FROM public.comunicacao_outbox WHERE locked_at IS NOT NULL), 'epoch'),
    COALESCE((SELECT max(sent_at)   FROM public.comunicacao_outbox WHERE sent_at   IS NOT NULL), 'epoch'),
    COALESCE((SELECT max(updated_at) FROM public.comunicacao_outbox
               WHERE status IN ('failed','dead_letter','processing','sent')), 'epoch')
  ) INTO v_last_worker_activity;

  IF v_last_worker_activity IS NULL OR v_last_worker_activity = 'epoch'::timestamptz THEN
    v_worker_status := 'unknown';
    v_worker_age_s := NULL;
    v_last_worker_activity := NULL;
  ELSE
    v_worker_age_s := EXTRACT(EPOCH FROM (now() - v_last_worker_activity))::int;
    v_worker_status := CASE
      WHEN v_worker_age_s <= 300 THEN 'active'
      WHEN v_worker_age_s <= 1800 THEN 'idle'
      ELSE 'stale'
    END;
  END IF;

  SELECT max(sent_at) INTO v_last_sent_at FROM public.comunicacao_outbox WHERE sent_at IS NOT NULL;

  SELECT
    COALESCE(delivery_enabled, false),
    COALESCE(email_delivery_enabled, false),
    COALESCE(whatsapp_delivery_enabled, false),
    COALESCE(inapp_delivery_enabled, false),
    COALESCE(whatsapp_webhook_enabled, false),
    COALESCE(test_mode_enabled, false)
  INTO v_flag_delivery, v_flag_email, v_flag_wa, v_flag_inapp, v_flag_webhook, v_flag_test_mode
  FROM public.communication_provider_settings
  ORDER BY updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_flag_delivery IS NULL THEN v_flag_delivery := false; END IF;
  IF v_flag_email IS NULL THEN v_flag_email := false; END IF;
  IF v_flag_wa IS NULL THEN v_flag_wa := false; END IF;
  IF v_flag_inapp IS NULL THEN v_flag_inapp := false; END IF;
  IF v_flag_webhook IS NULL THEN v_flag_webhook := false; END IF;
  IF v_flag_test_mode IS NULL THEN v_flag_test_mode := false; END IF;

  SELECT jsonb_build_object(
           'configured', (smtp_host IS NOT NULL AND smtp_from IS NOT NULL AND secret_smtp_password IS NOT NULL),
           'enabled', COALESCE(email_delivery_enabled, false)
         )
    INTO v_prov_email
    FROM public.communication_provider_settings
    ORDER BY updated_at DESC NULLS LAST LIMIT 1;

  SELECT jsonb_build_object(
           'configured', (whatsapp_phone_number_id IS NOT NULL AND secret_whatsapp_access_token IS NOT NULL),
           'enabled', COALESCE(whatsapp_delivery_enabled, false),
           'webhook_configured', (secret_whatsapp_verify_token IS NOT NULL AND secret_whatsapp_app_secret IS NOT NULL),
           'webhook_enabled', COALESCE(whatsapp_webhook_enabled, false)
         )
    INTO v_prov_wa
    FROM public.communication_provider_settings
    ORDER BY updated_at DESC NULLS LAST LIMIT 1;

  v_prov := jsonb_build_object(
    'email', COALESCE(v_prov_email, jsonb_build_object('configured', false, 'enabled', false)),
    'whatsapp', COALESCE(v_prov_wa, jsonb_build_object('configured', false, 'enabled', false, 'webhook_configured', false, 'webhook_enabled', false)),
    'in_app', jsonb_build_object('configured', true, 'enabled', v_flag_inapp)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'flags', jsonb_build_object(
      'delivery_enabled', v_flag_delivery,
      'email_enabled', v_flag_email,
      'whatsapp_enabled', v_flag_wa,
      'in_app_enabled', v_flag_inapp,
      'whatsapp_webhook_enabled', v_flag_webhook,
      'test_mode_enabled', v_flag_test_mode
    ),
    'providers', v_prov,
    'queue', jsonb_build_object(
      'by_status', COALESCE(v_by_status,'{}'::jsonb),
      'by_canal',  COALESCE(v_by_canal,'{}'::jsonb),
      'by_event_key_7d', COALESCE(v_by_event,'{}'::jsonb),
      'by_canal_status_7d', COALESCE(v_by_canal_status,'{}'::jsonb),
      'pending', v_pending,
      'processing', v_processing,
      'dead_letter', v_dlq,
      'oldest_pending_age_seconds', v_oldest_pending_age_s,
      'oldest_processing_age_seconds', v_oldest_locked_age_s
    ),
    'throughput_24h', jsonb_build_object(
      'sent', v_success_24h,
      'failed_or_dlq', v_failed_24h,
      'success_rate_pct', v_success_rate,
      'avg_attempts_sent', v_avg_attempts_sent,
      'avg_attempts_terminal', v_avg_attempts_terminal,
      'max_attempts', v_max_attempts,
      'avg_latency_ms', v_avg_latency_ms,
      'p95_latency_ms', v_p95_latency_ms
    ),
    'worker', jsonb_build_object(
      'status', v_worker_status,
      'last_activity_at', v_last_worker_activity,
      'last_activity_age_seconds', v_worker_age_s,
      'last_sent_at', v_last_sent_at
    ),
    'realtime', jsonb_build_object('ready', COALESCE(v_realtime_ready, false)),
    'dlq_admin', jsonb_build_object('last_replay_at', v_last_replay_at)
  );
END;$function$

CREATE OR REPLACE FUNCTION platform_private.tenant_email_settings_save(p_expected_version bigint, p_config jsonb, p_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_version bigint; v_secret uuid;
BEGIN
 v_org:=platform_private.tenant_email_actor_org();
 IF v_org IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.tenant_email_require_review();
 IF p_expected_version IS NULL OR p_expected_version<0 OR p_expected_version>9007199254740991 THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM platform_private.tenant_email_validate_config(p_config);
 IF p_password IS NOT NULL AND (length(p_password)<1 OR length(p_password)>4096 OR p_password ~ '[[:cntrl:]]') THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 -- Serializes first insertion and updates; hash collision only causes extra serialization.
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 -- Prevent revoke/inactivation during a queued operation from writing.
 IF platform_private.tenant_email_actor_org() IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.tenant_email_require_review();
 SELECT version INTO v_version FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 v_version:=coalesce(v_version,0);
 IF p_expected_version<>v_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT secret_id INTO v_secret FROM platform_private.communication_tenant_email_secret_refs WHERE organization_id=v_org;
 IF v_secret IS NULL AND p_password IS NULL THEN RAISE EXCEPTION 'SMTP_CREDENTIAL_REQUIRED' USING ERRCODE='22023'; END IF;
 IF p_password IS NOT NULL THEN
  IF v_secret IS NULL THEN
   v_secret:=vault.create_secret(p_password,'tenant_email_'||v_org::text,'');
   INSERT INTO platform_private.communication_tenant_email_secret_refs VALUES(v_org,v_secret);
  ELSE
   PERFORM vault.update_secret(v_secret,p_password,'tenant_email_'||v_org::text,'');
  END IF;
 END IF;
 INSERT INTO public.communication_tenant_email_settings(organization_id,config,version,credential_configured)
 VALUES(v_org,p_config,v_version+1,true)
 ON CONFLICT(organization_id) DO UPDATE SET config=EXCLUDED.config,version=EXCLUDED.version,
 credential_configured=true,state='DRAFT',sender_verified=false,dispatch_enabled=false,updated_at=now();
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action)
 VALUES(v_org,auth.uid(),v_version+1,CASE WHEN p_password IS NULL THEN 'draft_saved' ELSE 'credential_rotated' END);
 RETURN platform_private.tenant_email_settings_get();
EXCEPTION
 WHEN SQLSTATE '42501' THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501';
 WHEN SQLSTATE '40001' THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 WHEN SQLSTATE '22023' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023';
 WHEN OTHERS THEN RAISE EXCEPTION 'SMTP_INTERNAL' USING ERRCODE='P0001';
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cc_delete_item_price(p_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before jsonb;
BEGIN
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  SELECT to_jsonb(i) INTO v_before FROM public.commercial_condition_item_prices i WHERE i.id=p_id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id) FOR UPDATE;
  IF v_before IS NULL THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF (v_before->>'status') <> 'draft' THEN RAISE EXCEPTION 'only_draft_can_be_deleted'; END IF;
  DELETE FROM public.commercial_condition_item_prices WHERE id=p_id;
  PERFORM public.fn_cc_audit('item_price',p_id,'delete',v_before,NULL,p_motivo);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_admin_communication_outbox_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_by_status jsonb;
  v_by_canal jsonb;
  v_dlq_count bigint;
  v_pending_count bigint;
  v_last_dlq_at timestamptz;
  v_avg_attempts numeric;
  v_avg_latency_ms numeric;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();

  SELECT jsonb_object_agg(status, cnt) INTO v_by_status FROM (
    SELECT status::text AS status, count(*) AS cnt
      FROM public.comunicacao_outbox
     GROUP BY status
  ) s;

  SELECT jsonb_object_agg(canal, cnt) INTO v_by_canal FROM (
    SELECT canal::text AS canal, count(*) AS cnt
      FROM public.comunicacao_outbox
     GROUP BY canal
  ) c;

  SELECT count(*), max(updated_at) INTO v_dlq_count, v_last_dlq_at
    FROM public.comunicacao_outbox WHERE status = 'dead_letter';

  SELECT count(*) INTO v_pending_count
    FROM public.comunicacao_outbox WHERE status = 'pending';

  SELECT COALESCE(avg(attempts),0) INTO v_avg_attempts
    FROM public.comunicacao_outbox
   WHERE status IN ('sent','dead_letter');

  SELECT COALESCE(avg(EXTRACT(EPOCH FROM (sent_at - created_at)) * 1000), 0)
    INTO v_avg_latency_ms
    FROM public.comunicacao_outbox
   WHERE status = 'sent' AND sent_at IS NOT NULL;

  RETURN jsonb_build_object(
    'by_status', COALESCE(v_by_status, '{}'::jsonb),
    'by_canal', COALESCE(v_by_canal, '{}'::jsonb),
    'dead_letter_count', COALESCE(v_dlq_count, 0),
    'pending_count', COALESCE(v_pending_count, 0),
    'last_dead_letter_at', v_last_dlq_at,
    'avg_attempts_terminal', round(COALESCE(v_avg_attempts,0)::numeric, 2),
    'avg_latency_ms_sent', round(COALESCE(v_avg_latency_ms,0)::numeric, 0)
  );
END$function$

CREATE OR REPLACE FUNCTION public.rpc_cc_publish_item_prices(p_ids uuid[], p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_rule uuid; v_count int := 0;
BEGIN
  IF NOT public.fn_cc_can_publish(auth.uid()) THEN RAISE EXCEPTION 'not_authorized_publish'; END IF;
  IF p_ids IS NULL OR array_length(p_ids,1) IS NULL THEN RAISE EXCEPTION 'no_items'; END IF;

  IF EXISTS(SELECT 1 FROM unnest(p_ids) x(id) WHERE x.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i WHERE i.id=x.id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id))) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  FOR r IN SELECT * FROM public.commercial_condition_item_prices
            WHERE id = ANY(p_ids) AND status IN ('draft','pending_approval') FOR UPDATE
  LOOP
    IF NOT platform_private.c2p1_assignment_allowed(r.buyer_scope,r.partner_id,r.customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF NOT platform_private.c2p1_item_allowed(r.assignment_id,r.plan_id,r.buyer_scope,r.partner_id,r.customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM public.commercial_payment_plan_assignments a WHERE a.plan_id=r.plan_id AND a.buyer_scope=r.buyer_scope AND a.partner_id IS NOT DISTINCT FROM r.partner_id AND a.customer_id IS NOT DISTINCT FROM r.customer_id AND (r.assignment_id IS NULL OR a.id=r.assignment_id) AND a.status='published' ORDER BY a.id FOR SHARE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION 'assignment_not_published'; END IF;
    IF r.buyer_scope = 'default' THEN RAISE EXCEPTION 'default_scope_not_publishable'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.commercial_payment_plan_assignments a
                    WHERE (r.assignment_id IS NULL OR a.id=r.assignment_id) AND a.status='published' AND a.plan_id=r.plan_id
                      AND a.buyer_scope=r.buyer_scope
                      AND a.partner_id IS NOT DISTINCT FROM r.partner_id
                      AND a.customer_id IS NOT DISTINCT FROM r.customer_id) THEN
      RAISE EXCEPTION 'assignment_not_published';
    END IF;

    UPDATE public.commercial_price_rules
       SET active=false, updated_by=auth.uid(), updated_at=now()
     WHERE active
       AND plan_id = r.plan_id AND buyer_scope = r.buyer_scope
       AND partner_id IS NOT DISTINCT FROM r.partner_id
       AND customer_id IS NOT DISTINCT FROM r.customer_id
       AND product_id IS NOT DISTINCT FROM r.product_id
       AND microrganismo_id IS NOT DISTINCT FROM r.microrganismo_id
       AND unit_type = r.unit_type
       AND volume_ml IS NOT DISTINCT FROM r.volume_ml;

    INSERT INTO public.commercial_price_rules
      (buyer_scope,partner_id,customer_id,plan_id,product_id,microrganismo_id,unit_type,volume_ml,
       pricing_mode,condition_price,discount_percent,min_quantity,currency,valid_from,valid_until,active,motivo,
       created_by,updated_by)
    VALUES (r.buyer_scope,r.partner_id,r.customer_id,r.plan_id,r.product_id,r.microrganismo_id,
       r.unit_type,r.volume_ml,r.pricing_mode,
       CASE WHEN r.pricing_mode='fixed_item_price' THEN r.condition_price ELSE NULL END,
       CASE WHEN r.pricing_mode='discount_from_base' THEN r.discount_percent ELSE NULL END,
       COALESCE(r.min_quantity,0),
       COALESCE(r.currency,'BRL'),r.valid_from,r.valid_until,true,
       COALESCE(p_motivo, r.motivo), auth.uid(), auth.uid())
    RETURNING id INTO v_rule;

    UPDATE public.commercial_condition_item_prices
       SET status='published', published_by=auth.uid(), published_at=now(),
           published_rule_id=v_rule, updated_by=auth.uid()
     WHERE id = r.id;

    PERFORM public.fn_cc_audit('item_price', r.id, 'publish', to_jsonb(r),
      jsonb_build_object('price_rule_id', v_rule), p_motivo);
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('published', v_count);
END $function$

