CREATE OR REPLACE FUNCTION public.rpc_admin_reorder_commercial_plans(p_orders jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_item jsonb;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF jsonb_typeof(p_orders) <> 'array' THEN RAISE EXCEPTION 'orders_payload_invalid'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('cpp_reorder'));

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_orders) LOOP
    IF (v_item->>'sort_order')::integer < 0 THEN RAISE EXCEPTION 'sort_order_invalid'; END IF;
    UPDATE public.commercial_payment_plans
       SET sort_order = (v_item->>'sort_order')::integer, updated_by = auth.uid()
     WHERE id = (v_item->>'id')::uuid;
  END LOOP;

  PERFORM public._cpp_audit('commercial_plan_reordered', NULL, NULL, jsonb_build_object('orders', p_orders), NULL);
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_substituir_etiqueta_produto(p_etiqueta_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_old public.produto_etiquetas%ROWTYPE;
  v_res jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 5 THEN
    RAISE EXCEPTION 'Motivo obrigatório para substituição (mínimo 5 caracteres)';
  END IF;

  SELECT * INTO v_old FROM public.produto_etiquetas WHERE id = p_etiqueta_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Etiqueta não encontrada'; END IF;
  IF v_old.status = 'cancelada' THEN RAISE EXCEPTION 'Etiqueta já cancelada'; END IF;
  IF v_old.substituida_por_id IS NOT NULL THEN RAISE EXCEPTION 'Etiqueta já substituída'; END IF;

  v_res := public.rpc_gerar_etiqueta_produto(jsonb_build_object(
    'lote_id', v_old.lote_id,
    'produto_id', v_old.produto_id,
    'envase_id', v_old.envase_id,
    'envase_item_id', v_old.envase_item_id,
    'estoque_item_id', v_old.estoque_item_id,
    'entrega_id', v_old.entrega_id,
    'entrega_item_id', v_old.entrega_item_id,
    'cliente_id', v_old.cliente_id,
    'fazenda_id', v_old.fazenda_id,
    'tipo_etiqueta', v_old.tipo_etiqueta,
    'volume', v_old.volume,
    'unidade', v_old.unidade,
    'quantidade_embalagens', v_old.quantidade_embalagens,
    'conservacao', v_old.conservacao,
    'uso_recomendado', v_old.uso_recomendado,
    'observacoes', v_old.observacoes,
    'substitui_etiqueta_id', v_old.id
  ));

  PERFORM public.rpc_cancelar_etiqueta_produto(p_etiqueta_id, 'Substituída: ' || trim(p_motivo));

  RETURN jsonb_build_object(
    'success', true,
    'etiqueta_anterior_id', p_etiqueta_id,
    'nova_etiqueta_id', v_res->>'etiqueta_id',
    'novo_codigo', v_res->>'codigo_etiqueta'
  );
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_test_claim(p_mode text, p_version bigint, p_key uuid, p_confirm boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; r platform_private.tenant_smtp_test_receipts; s public.communication_tenant_email_settings;
 v_id uuid:=gen_random_uuid(); v_out uuid:=gen_random_uuid(); v_event uuid:=gen_random_uuid(); v_fence uuid:=gen_random_uuid(); v_key text;
BEGIN
 v_org:=platform_private.tenant_email_actor_org();
 IF v_org IS NULL OR platform_private.tenant_smtp_test_actor(auth.uid()) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_mode IS NULL OR p_mode NOT IN ('connection','send') OR p_version IS NULL OR p_version<1 OR p_version>9007199254740991 OR p_key IS NULL
 OR (p_mode='send' AND p_confirm IS DISTINCT FROM true) THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 IF platform_private.tenant_email_actor_org() IS DISTINCT FROM v_org OR platform_private.tenant_smtp_test_actor(auth.uid()) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE approved AND id)
 OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR NOT s.credential_configured THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid() AND request_key=p_key;
 IF FOUND THEN
  IF r.version<>p_version OR r.mode<>p_mode THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
  RETURN jsonb_build_object('replay',true,'code',coalesce(r.code,'SMTP_BUSY'),'version',r.version,'mode',r.mode,'dispatch_enabled',false,'sender_verified',false);
 END IF;
 -- Any abandoned/uncertain send blocks ALL future sends, even after version rotation.
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND
 (state<>'complete' OR (p_mode='send' AND mode='send' AND code='smtp_send_ambiguous'))) THEN RAISE EXCEPTION 'SMTP_BUSY' USING ERRCODE='40001'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '60 seconds') THEN RAISE EXCEPTION 'SMTP_COOLDOWN' USING ERRCODE='40001'; END IF;
 IF p_mode='send' AND NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid()
 AND version=p_version AND mode='connection' AND code='smtp_connection_ok' AND state='complete' AND completed_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
 v_key:='tenant-smtp:'||v_org||':'||auth.uid()||':'||p_key;
 INSERT INTO public.comunicacao_eventos(id,event_key,source_type,source_id,created_by,idempotency_key,status,processed_at,payload)
 VALUES(v_event,'tenant.smtp.diagnostic','tenant_smtp_diagnostic_v1',v_org,auth.uid(),v_key,'processed',clock_timestamp(),'{}');
 INSERT INTO platform_private.tenant_smtp_test_insert_tickets VALUES(v_out,txid_current(),auth.uid(),v_org);
 INSERT INTO public.comunicacao_outbox(id,event_id,template_chave,template_versao,template_snapshot,canal,recipient_user_id,status,attempts,max_attempts,locked_by,lease_expires_at,idempotency_key)
 VALUES(v_out,v_event,'tenant_smtp_diagnostic_v1',1,'{}','email',auth.uid(),'processing',1,1,'tenant-smtp-test',NULL,v_key);
 IF NOT EXISTS(SELECT 1 FROM public.comunicacao_outbox WHERE id=v_out) THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE'; END IF;
 DELETE FROM platform_private.tenant_smtp_test_insert_tickets WHERE outbox_id=v_out;
 INSERT INTO platform_private.tenant_smtp_test_receipts(id,organization_id,actor_id,version,actor_iat,mode,request_key,fence,outbox_id,state)
 VALUES(v_id,v_org,auth.uid(),p_version,coalesce((auth.jwt()->>'iat')::bigint,0),p_mode,p_key,v_fence,v_out,'claimed');
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),p_version,'smtp_test_'||p_mode||'_claimed');
 RETURN jsonb_build_object('replay',false,'job_id',v_id,'fence',v_fence);
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2p1_snapshot_allowed(p_entity text, p_id uuid, p_data jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_data IS NULL THEN RETURN true; END IF;
 IF jsonb_typeof(p_data)<>'object' THEN RETURN false; END IF;
 IF p_entity='assignment' THEN
 RETURN (p_data->>'id')::uuid=p_id AND platform_private.c2p1_assignment_allowed(p_data->>'buyer_scope',(p_data->>'partner_id')::uuid,(p_data->>'customer_id')::uuid);
 ELSIF p_entity='item_price' THEN
 IF NOT (p_data ? 'buyer_scope') THEN
 -- Publication output contains only server-produced rule ID: verify full chain.
 RETURN EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i JOIN public.commercial_price_rules r ON r.id=i.published_rule_id
 WHERE i.id=p_id AND r.id=(p_data->>'price_rule_id')::uuid AND r.plan_id=i.plan_id AND r.buyer_scope=i.buyer_scope
 AND r.partner_id IS NOT DISTINCT FROM i.partner_id AND r.customer_id IS NOT DISTINCT FROM i.customer_id
 AND r.product_id IS NOT DISTINCT FROM i.product_id AND r.microrganismo_id IS NOT DISTINCT FROM i.microrganismo_id
 AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id));
 END IF;
 RETURN (p_data->>'id')::uuid=p_id AND platform_private.c2p1_item_allowed((p_data->>'assignment_id')::uuid,(p_data->>'plan_id')::uuid,p_data->>'buyer_scope',(p_data->>'partner_id')::uuid,(p_data->>'customer_id')::uuid);
 END IF;
 RETURN false;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_admin_set_commercial_plan_active(p_plan_id uuid, p_active boolean, p_motivo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old public.commercial_payment_plans%ROWTYPE;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  SELECT * INTO v_old FROM public.commercial_payment_plans WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF p_active AND v_old.superseded_by_id IS NOT NULL THEN RAISE EXCEPTION 'plan_superseded_cannot_activate'; END IF;

  UPDATE public.commercial_payment_plans
     SET active = p_active,
         is_default = CASE WHEN p_active THEN is_default ELSE false END,
         updated_by = auth.uid()
   WHERE id = p_plan_id;

  PERFORM public._cpp_audit(CASE WHEN p_active THEN 'commercial_plan_activated' ELSE 'commercial_plan_deactivated' END,
    p_plan_id, to_jsonb(v_old), jsonb_build_object('active', p_active), p_motivo);
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_admin_set_default_commercial_plan(p_plan_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old public.commercial_payment_plans%ROWTYPE; v_prev public.commercial_payment_plans%ROWTYPE;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('cpp_default_plan'));
  SELECT * INTO v_old FROM public.commercial_payment_plans WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF NOT public.fn_b2b_plan_selectable(p_plan_id) THEN RAISE EXCEPTION 'plan_not_selectable'; END IF;

  SELECT * INTO v_prev FROM public.commercial_payment_plans
   WHERE is_default AND id <> p_plan_id FOR UPDATE;

  UPDATE public.commercial_payment_plans SET is_default = false, updated_by = auth.uid()
   WHERE is_default AND id <> p_plan_id;
  UPDATE public.commercial_payment_plans SET is_default = true, updated_by = auth.uid()
   WHERE id = p_plan_id;

  IF v_prev.id IS NOT NULL THEN
    PERFORM public._cpp_audit(
      'commercial_plan_unset_default',
      v_prev.id,
      jsonb_build_object('is_default', true, 'code', v_prev.code, 'name', v_prev.name),
      jsonb_build_object('is_default', false, 'replaced_by_plan_id', p_plan_id),
      'substituido_por_novo_plano_padrao');
  END IF;

  PERFORM public._cpp_audit(
    'commercial_plan_set_default',
    p_plan_id,
    jsonb_build_object('is_default', v_old.is_default, 'code', v_old.code, 'name', v_old.name),
    jsonb_build_object('is_default', true, 'previous_default_plan_id', v_prev.id),
    NULL);
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_certificate_for_invoice_v1(_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inv public.fiscal_invoices%ROWTYPE;
  v_company uuid; v_cnpj text; v_cert uuid; v_count int;
BEGIN
  SELECT * INTO v_inv FROM public.fiscal_invoices WHERE id = _invoice_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND'; END IF;

  v_cnpj := regexp_replace(coalesce(nullif(btrim(v_inv.company_cnpj),''),
                                    v_inv.company_snapshot->>'cnpj',''), '[^0-9]', '', 'g');
  IF v_cnpj = '' THEN
    RAISE EXCEPTION 'FISCAL_CERTIFICATE_BINDING_UNRESOLVED: nota sem CNPJ do emitente.';
  END IF;

  SELECT count(*), min(id) INTO v_count, v_company
    FROM public.company_fiscal_settings
   WHERE regexp_replace(coalesce(cnpj,''),'[^0-9]','','g') = v_cnpj AND is_active;
  IF coalesce(v_count,0) <> 1 THEN
    RAISE EXCEPTION 'FISCAL_CERTIFICATE_BINDING_UNRESOLVED: emitente da nota nao resolvido de forma inequivoca.';
  END IF;

  SELECT count(*), min(id) INTO v_count, v_cert
    FROM public.fiscal_certificates
   WHERE company_settings_id = v_company
     AND environment = 'HOMOLOGATION'
     AND status = 'AVAILABLE'
     AND is_active IS TRUE
     AND revoked_at IS NULL
     AND (valid_until IS NULL OR valid_until > now());
  IF coalesce(v_count,0) = 0 THEN
    RAISE EXCEPTION 'CERTIFICATE_REQUIRED: emitente sem certificado de homologacao valido.';
  END IF;
  IF v_count > 1 THEN
    RAISE EXCEPTION 'FISCAL_CERTIFICATE_AMBIGUOUS: mais de um certificado ativo para o emitente.';
  END IF;

  RETURN jsonb_build_object('certificateId', v_cert, 'companySettingsId', v_company,
                            'environment','HOMOLOGATION');
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_calculate_service_invoice_v1(p_invoice_id uuid, p_idempotency_key text, p_persist boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  inv public.fiscal_invoices%ROWTYPE;
  emit public.company_fiscal_settings%ROWTYPE;
  prof public.service_fiscal_profiles%ROWTYPE;
  it record; ref_date date; n_items int := 0;
  v_base numeric; v_iss numeric; v_rate numeric;
  t_gross numeric := 0; t_disc numeric := 0; t_base numeric := 0; t_iss numeric := 0;
  t_iss_withheld numeric := 0; t_fed_withheld numeric := 0;
  wk text; w jsonb; w_rate numeric; w_val numeric; w_out jsonb;
  fed jsonb; items_out jsonb := '[]'::jsonb; item_taxes jsonb; totals jsonb;
  existing jsonb;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(p_invoice_id);

  IF NOT public.fn_fiscal_can_operate() THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao para calcular documento fiscal.';
  END IF;
  IF nullif(btrim(coalesce(p_idempotency_key,'')),'') IS NULL THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_KEY_REQUIRED: informe uma chave de idempotencia.';
  END IF;
  PERFORM public.fn_fiscal_assert_environment_homologation();

  SELECT * INTO inv FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: %', p_invoice_id; END IF;
  IF coalesce(inv.document_model,'') <> 'NFSE' THEN
    RAISE EXCEPTION 'FISCAL_MODEL_UNSUPPORTED: esta rotina calcula apenas NFS-e (servicos).';
  END IF;
  IF inv.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_DRAFT: calculo disponivel apenas em rascunho (status=%).', inv.status;
  END IF;

  IF p_persist THEN
    SELECT result INTO existing FROM (SELECT * FROM public.fiscal_calculation_runs WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_calculation_runs
      WHERE idempotency_key = p_idempotency_key AND fiscal_invoice_id = p_invoice_id
      ORDER BY created_at DESC LIMIT 1;
    IF existing IS NOT NULL THEN
      RETURN existing || jsonb_build_object('idempotentReplay', true);
    END IF;
    IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_calculation_runs WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_calculation_runs
                WHERE idempotency_key = p_idempotency_key AND fiscal_invoice_id <> p_invoice_id) THEN
      RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_SCOPE_MISMATCH: chave ja utilizada por outro documento fiscal.';
    END IF;
  END IF;

  SELECT * INTO emit FROM (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EMITTER_NOT_CONFIGURED: emitente nao cadastrado.'; END IF;
  IF coalesce(emit.nfe_environment_code,'2') = '1' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_BLOCKED: ambiente de producao bloqueado.';
  END IF;

  ref_date := coalesce(inv.issue_date, current_date);

  FOR it IN SELECT * FROM (SELECT * FROM public.fiscal_invoice_items WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_invoice_items
             WHERE fiscal_invoice_id = p_invoice_id ORDER BY item_sequence
  LOOP
    n_items := n_items + 1;
    IF coalesce(it.quantity,0) <= 0 OR coalesce(it.unit_value,0) < 0 THEN
      RAISE EXCEPTION 'FISCAL_ITEM_INVALID: item % com quantidade ou valor unitario invalido.', it.item_sequence;
    END IF;

    SELECT * INTO prof FROM public.service_fiscal_profiles
     WHERE (service_id = it.source_item_id OR source_reference = it.source_item_id::text)
       AND is_active ORDER BY updated_at DESC LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'FISCAL_SERVICE_PROFILE_MISSING: item % sem perfil fiscal de servico.', it.item_sequence;
    END IF;
    IF prof.profile_status <> 'VALIDATED' THEN
      RAISE EXCEPTION 'FISCAL_SERVICE_PROFILE_NOT_VALIDATED: item % com perfil em status %.', it.item_sequence, prof.profile_status;
    END IF;
    IF nullif(btrim(coalesce(prof.lc116_item,'')),'') IS NULL THEN
      RAISE EXCEPTION 'FISCAL_SERVICE_LC116_MISSING: item % sem enquadramento LC 116.', it.item_sequence;
    END IF;
    IF prof.iss_rate IS NULL OR prof.iss_rate < 0 OR prof.iss_rate > 100 THEN
      RAISE EXCEPTION 'FISCAL_SERVICE_ISS_RATE_INVALID: item % sem aliquota de ISS valida.', it.item_sequence;
    END IF;
    IF NOT public.fn_fiscal_service_withholding_valid_v1(prof.federal_withholding_defaults) THEN
      RAISE EXCEPTION 'FISCAL_SERVICE_WITHHOLDING_INVALID: retencoes federais do item % fora do contrato.', it.item_sequence;
    END IF;

    -- IBS/CBS so podem entrar quando a politica E o leiaute estiverem comprovados.
    IF coalesce(prof.ibs_cbs_configuration,'{}'::jsonb) <> '{}'::jsonb
       AND coalesce((prof.ibs_cbs_configuration->>'enabled')::boolean,false) THEN
      IF NOT (public.fn_fiscal_rtc_layout_supported_v1('NFSE','IBS',ref_date)
              AND public.fn_fiscal_rtc_layout_supported_v1('NFSE','CBS',ref_date)) THEN
        RAISE EXCEPTION 'FISCAL_RTC_LAYOUT_UNVALIDATED: leiaute IBS/CBS nao validado para NFS-e nesta vigencia.';
      END IF;
    END IF;

    v_base := public.fn_fiscal_round(
      coalesce(it.gross_value, it.quantity * it.unit_value) - coalesce(it.discount_value,0));
    IF v_base < 0 THEN
      RAISE EXCEPTION 'FISCAL_TAX_BASE_NEGATIVE: base negativa no item %.', it.item_sequence;
    END IF;
    v_rate := prof.iss_rate;
    v_iss  := public.fn_fiscal_round(v_base * v_rate / 100);

    fed := coalesce(prof.federal_withholding_defaults,'{}'::jsonb);
    w_out := '{}'::jsonb;
    FOREACH wk IN ARRAY ARRAY['pis','cofins','csll','irrf','inss'] LOOP
      w := fed->wk;
      IF w IS NOT NULL THEN
        w_rate := (w->>'rate')::numeric;
        w_val  := public.fn_fiscal_round(v_base * w_rate / 100);
        w_out  := w_out || jsonb_build_object(upper(wk), jsonb_build_object(
          'base', v_base, 'rate', w_rate, 'value', w_val,
          'withheld', coalesce((w->>'withheld')::boolean,false)));
        IF coalesce((w->>'withheld')::boolean,false) THEN
          t_fed_withheld := t_fed_withheld + w_val;
        END IF;
      END IF;
    END LOOP;

    item_taxes := jsonb_build_object(
      'ISS', jsonb_build_object(
        'taxKind','ISS','formula','SVC1/ISS','base', v_base, 'rate', v_rate,
        'value', v_iss, 'withheld', coalesce(prof.iss_withheld_default,false),
        'lc116Item', prof.lc116_item,
        'municipalTaxationCode', prof.municipal_taxation_code,
        'nationalTaxationCode', prof.national_taxation_code,
        'incidenceMunicipalityIbge', prof.incidence_municipality_ibge_code),
      'FEDERAL_WITHHOLDING', w_out);

    t_gross := t_gross + public.fn_fiscal_round(coalesce(it.gross_value, it.quantity * it.unit_value));
    t_disc  := t_disc  + public.fn_fiscal_round(coalesce(it.discount_value,0));
    t_base  := t_base  + v_base;
    t_iss   := t_iss   + v_iss;
    IF coalesce(prof.iss_withheld_default,false) THEN
      t_iss_withheld := t_iss_withheld + v_iss;
    END IF;

    items_out := items_out || jsonb_build_array(jsonb_build_object(
      'itemSequence', it.item_sequence, 'base', v_base, 'taxes', item_taxes));

    IF p_persist THEN
      UPDATE public.fiscal_invoice_items
         SET tax_snapshot = item_taxes,
             net_value = v_base,
             updated_at = now()
       WHERE id = it.id;
    END IF;
  END LOOP;

  IF n_items = 0 THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NO_ITEMS: documento sem itens.';
  END IF;

  totals := jsonb_build_object(
    'engineVersion','SVC1.0', 'documentModel','NFSE', 'roundingMode','HALF_UP_2',
    'itemCount', n_items,
    'vServ', public.fn_fiscal_round(t_gross),
    'vDesc', public.fn_fiscal_round(t_disc),
    'vBC',   public.fn_fiscal_round(t_base),
    'vISS',  public.fn_fiscal_round(t_iss),
    'vISSRetido', public.fn_fiscal_round(t_iss_withheld),
    'vRetFederais', public.fn_fiscal_round(t_fed_withheld),
    -- Liquido = servicos menos descontos e SOMENTE tributos efetivamente retidos.
    'vLiq', public.fn_fiscal_round(t_base - t_iss_withheld - t_fed_withheld),
    'ibsCbsApplied', false,
    'ibsCbsGate','FISCAL_RTC_LAYOUT_UNVALIDATED',
    'nationalTransmissionSupported', false,
    'items', items_out);

  IF p_persist THEN
    UPDATE public.fiscal_invoices
       SET tax_snapshot = totals - 'items',
           fiscal_totals_snapshot = totals - 'items',
           updated_at = now()
     WHERE id = p_invoice_id;

    INSERT INTO public.fiscal_calculation_runs
      (fiscal_invoice_id, idempotency_key, engine_version, result, created_by)
    VALUES (p_invoice_id, p_idempotency_key, 'SVC1.0', totals, auth.uid());

    INSERT INTO public.fiscal_audit_log (table_name, record_id, action, old_values, new_values, changed_by)
    VALUES ('fiscal_invoices', p_invoice_id, 'UPDATE',
            jsonb_build_object('taxSnapshot', inv.tax_snapshot),
            jsonb_build_object('engine','SVC1.0','vISS', t_iss, 'vLiq',
              public.fn_fiscal_round(t_base - t_iss_withheld - t_fed_withheld)),
            auth.uid());
  END IF;

  RETURN totals || jsonb_build_object('idempotentReplay', false, 'persisted', p_persist);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_admin_set_whatsapp_consent(p_cliente_id uuid, p_user_id uuid, p_acao text, p_source text, p_justificativa text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_now   timestamptz := now();
  v_src   text := COALESCE(NULLIF(btrim(p_source), ''), 'admin_ui');
  v_just  text := NULLIF(btrim(COALESCE(p_justificativa, '')), '');
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF v_actor IS NULL OR NOT public.has_role(v_actor, 'administrador'::public.app_role) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF (p_cliente_id IS NULL AND p_user_id IS NULL) OR (p_cliente_id IS NOT NULL AND p_user_id IS NOT NULL) THEN
    RAISE EXCEPTION 'exactly_one_of_cliente_or_user_required' USING ERRCODE = '22023';
  END IF;
  IF p_acao NOT IN ('opt_in','opt_out','verified') THEN
    RAISE EXCEPTION 'invalid_action' USING ERRCODE = '22023';
  END IF;
  IF length(v_src) > 60 THEN RAISE EXCEPTION 'invalid_source' USING ERRCODE='22023'; END IF;
  IF v_just IS NOT NULL AND length(v_just) > 500 THEN
    RAISE EXCEPTION 'invalid_justificativa' USING ERRCODE='22023';
  END IF;

  -- Trilha imutável (append-only). `source` embute justificativa quando presente.
  INSERT INTO public.comunicacao_consent_log(user_id, cliente_id, canal, acao, source, actor_id)
  VALUES (
    p_user_id, p_cliente_id, 'whatsapp'::public.comunicacao_canal, p_acao,
    CASE WHEN v_just IS NULL THEN v_src ELSE v_src || ':' || substr(v_just,1,120) END,
    v_actor
  );

  -- Estado atual (idempotente por (user_id|cliente_id, canal))
  INSERT INTO public.comunicacao_preferencias
    (user_id, cliente_id, canal, enabled,
     whatsapp_opt_in_at, whatsapp_opt_out_at, telefone_verificado, source)
  VALUES (
    p_user_id, p_cliente_id, 'whatsapp'::public.comunicacao_canal, true,
    CASE WHEN p_acao = 'opt_in'   THEN v_now ELSE NULL END,
    CASE WHEN p_acao = 'opt_out'  THEN v_now ELSE NULL END,
    CASE WHEN p_acao = 'verified' THEN true  ELSE false END,
    'admin'
  )
  ON CONFLICT (COALESCE(user_id, '00000000-0000-0000-0000-000000000000'::uuid),
               COALESCE(cliente_id, '00000000-0000-0000-0000-000000000000'::uuid),
               canal)
  DO UPDATE SET
    whatsapp_opt_in_at  = CASE WHEN p_acao='opt_in'  THEN v_now
                               WHEN p_acao='opt_out' THEN public.comunicacao_preferencias.whatsapp_opt_in_at
                               ELSE public.comunicacao_preferencias.whatsapp_opt_in_at END,
    whatsapp_opt_out_at = CASE WHEN p_acao='opt_out' THEN v_now
                               WHEN p_acao='opt_in'  THEN NULL
                               ELSE public.comunicacao_preferencias.whatsapp_opt_out_at END,
    telefone_verificado = CASE WHEN p_acao='verified' THEN true
                               ELSE public.comunicacao_preferencias.telefone_verificado END,
    enabled = CASE WHEN p_acao='opt_out' THEN public.comunicacao_preferencias.enabled ELSE true END,
    updated_at = v_now,
    source = 'admin';

  RETURN jsonb_build_object('ok', true, 'acao', p_acao, 'at', v_now);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_admin_update_commercial_plan_metadata(p_plan_id uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_sort_order integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old public.commercial_payment_plans%ROWTYPE;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  SELECT * INTO v_old FROM public.commercial_payment_plans WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF p_sort_order IS NOT NULL AND p_sort_order < 0 THEN RAISE EXCEPTION 'sort_order_invalid'; END IF;
  IF p_name IS NOT NULL AND btrim(p_name) = '' THEN RAISE EXCEPTION 'plan_name_required'; END IF;

  UPDATE public.commercial_payment_plans
     SET name = coalesce(btrim(p_name), name),
         description = coalesce(p_description, description),
         sort_order = coalesce(p_sort_order, sort_order),
         updated_by = auth.uid()
   WHERE id = p_plan_id;

  PERFORM public._cpp_audit('commercial_plan_metadata_updated', p_plan_id, to_jsonb(v_old),
    jsonb_build_object('name', p_name, 'description', p_description, 'sort_order', p_sort_order), NULL);
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_sefaz_transmit_record_v1(_transmission_id uuid, _state text, _patch jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row     public.fiscal_sefaz_transmissions;
  v_cur     public.fiscal_sefaz_transmissions;
  v_cstat   text;
  v_prot    text;
  v_outcome text;
  v_close_error text := NULL;
BEGIN
  IF _state NOT IN ('SENT','SUCCEEDED','FAILED','BLOCKED') THEN
    RAISE EXCEPTION 'FISCAL_TRANSMISSION_STATE_INVALID';
  END IF;

  SELECT * INTO v_cur FROM public.fiscal_sefaz_transmissions WHERE id = _transmission_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_TRANSMISSION_NOT_FOUND'; END IF;

  v_cstat := coalesce(_patch->>'protocolCStat', _patch->>'cStat', v_cur.c_stat);
  v_prot  := coalesce(_patch->>'nProt', v_cur.n_prot);

  IF _state IN ('FAILED','BLOCKED') THEN
    v_outcome := 'TRANSPORT_ERROR';
  ELSIF _state = 'SENT' THEN
    v_outcome := 'PENDING';
  ELSIF v_cstat IN ('100','150') AND v_prot IS NOT NULL THEN
    v_outcome := 'AUTHORIZED';
  ELSIF v_cstat IN ('135','136','155') THEN
    v_outcome := 'EVENT_REGISTERED';
  ELSIF v_cstat IN ('103','105','104','106','107','108','109','111','128') THEN
    v_outcome := CASE WHEN v_cur.service = 'NFeStatusServico4'
                      THEN 'SERVICE_INFO' ELSE 'PROCESSING' END;
  ELSE
    v_outcome := 'REJECTED';
  END IF;

  UPDATE public.fiscal_sefaz_transmissions SET
    state            = _state,
    outcome          = v_outcome,
    c_stat           = coalesce(_patch->>'cStat', c_stat),
    x_motivo         = coalesce(_patch->>'xMotivo', x_motivo),
    ch_nfe           = coalesce(_patch->>'chNFe', ch_nfe),
    n_prot           = coalesce(_patch->>'nProt', n_prot),
    n_rec            = coalesce(_patch->>'nRec', n_rec),
    ambiente_retorno = coalesce(_patch->>'tpAmb', ambiente_retorno),
    dh_recbto        = coalesce((_patch->>'dhRecbto')::timestamptz, dh_recbto),
    error_code       = coalesce(_patch->>'errorCode', error_code),
    response_summary = coalesce(_patch->'responseSummary', response_summary),
    completed_at     = CASE WHEN _state IN ('SUCCEEDED','FAILED','BLOCKED')
                            THEN now() ELSE completed_at END
  WHERE id = _transmission_id
  RETURNING * INTO v_row;

  IF v_row.ambiente_retorno IS NOT NULL AND v_row.ambiente_retorno <> '2' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;

  IF v_row.service = 'NFeRecepcaoEvento4' AND v_row.fiscal_event_id IS NOT NULL
     AND _state = 'SUCCEEDED' AND v_cstat IS NOT NULL THEN
    BEGIN
      PERFORM public.rpc_fiscal_event_sefaz_reconcile_v1(
        v_row.fiscal_event_id, v_row.id, v_cstat,
        coalesce(_patch->>'xMotivo', ''), v_row.n_prot, v_row.dh_recbto);
    EXCEPTION WHEN OTHERS THEN
      v_close_error := 'FISCAL_EVENT_RECONCILIATION_PENDING';
    END;
  END IF;

  -- H13: o fechamento documental nao pode descartar o retorno ja recebido.
  IF v_row.outcome = 'AUTHORIZED' AND v_row.fiscal_invoice_id IS NOT NULL
     AND v_row.ch_nfe IS NOT NULL AND v_row.n_prot IS NOT NULL THEN
    BEGIN
      PERFORM public.rpc_fiscal_invoice_apply_authorization_v1(
        v_row.fiscal_invoice_id, v_row.ch_nfe, v_row.n_prot, v_row.dh_recbto,
        v_row.c_stat, v_row.x_motivo, v_row.id);
    EXCEPTION WHEN OTHERS THEN
      v_close_error := 'FISCAL_AUTHORIZATION_CLOSE_PENDING';
    END;
  END IF;

  IF v_close_error IS NOT NULL THEN
    UPDATE public.fiscal_sefaz_transmissions
       SET error_code = v_close_error
     WHERE id = _transmission_id
    RETURNING * INTO v_row;
  END IF;

  RETURN jsonb_build_object(
    'transmissionId', v_row.id, 'state', v_row.state, 'outcome', v_row.outcome,
    'cStat', v_row.c_stat, 'xMotivo', v_row.x_motivo,
    'chNFe', v_row.ch_nfe, 'nProt', v_row.n_prot, 'nRec', v_row.n_rec,
    'reconciliationPending', v_close_error IS NOT NULL,
    'reconciliationCode', v_close_error);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_reserve_nfe_number_v1(p_invoice_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  inv public.fiscal_invoices%ROWTYPE;
  emit public.company_fiscal_settings%ROWTYPE;
  s public.fiscal_document_series%ROWTYPE;
  existing public.fiscal_number_reservations%ROWTYPE;
  n int; cnf text; key43 text; dv int; full_key text; cuf text;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(p_invoice_id);

  IF NOT public.fn_fiscal_can_operate() THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao para reservar numeracao.';
  END IF;
  IF nullif(btrim(coalesce(p_idempotency_key,'')),'') IS NULL THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_KEY_REQUIRED: informe uma chave de idempotencia.';
  END IF;

  -- F3.1-R1: gate de ambiente avaliado ANTES de qualquer leitura/efeito, fail-closed.
  PERFORM public.fn_fiscal_assert_environment_homologation();
  IF p_invoice_id IS NULL THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: documento nao informado.';
  END IF;

  SELECT * INTO inv FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: %', p_invoice_id; END IF;

  IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) r
              WHERE r.idempotency_key = p_idempotency_key
                AND r.fiscal_invoice_id <> p_invoice_id) THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_SCOPE_MISMATCH: chave de idempotencia ja utilizada por outro documento fiscal.'
      USING HINT = 'Gere uma chave exclusiva por documento. Reservas nunca sao compartilhadas entre documentos.';
  END IF;

  SELECT * INTO existing FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_number_reservations
   WHERE fiscal_invoice_id = p_invoice_id AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object('reservationId', existing.id, 'number', existing.number,
      'series', (SELECT series FROM (SELECT * FROM public.fiscal_document_series WHERE public.h15_company_access(company_id)) fiscal_document_series WHERE id = existing.series_id),
      'accessKey', existing.access_key, 'checkDigit', existing.check_digit,
      'tpEmis', existing.tp_emis, 'status', existing.status, 'idempotentReplay', true);
  END IF;

  IF inv.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_DRAFT: reserva permitida apenas em rascunho (status=%)', inv.status;
  END IF;
  IF coalesce(inv.tp_emis,1) <> 1 THEN
    RAISE EXCEPTION 'FISCAL_TPEMIS_UNSUPPORTED: apenas emissao normal (tpEmis=1) esta habilitada nesta fase.';
  END IF;
  IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) r
             WHERE r.fiscal_invoice_id = p_invoice_id AND r.status = 'RESERVED') THEN
    RAISE EXCEPTION 'FISCAL_NUMBER_ALREADY_RESERVED: documento ja possui reserva ativa.';
  END IF;
  IF inv.tax_snapshot IS NULL OR NOT (inv.tax_snapshot ? 'engineVersion') THEN
    RAISE EXCEPTION 'FISCAL_CALCULATION_REQUIRED: calcule os tributos antes de reservar numeracao.';
  END IF;

  IF NOT ((public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id))->>'eligible')::boolean THEN
    RAISE EXCEPTION 'FISCAL_NOT_ELIGIBLE: %',
      (public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id))->>'reasons';
  END IF;

  -- F3.1: devedor B2B x destinatario reavaliado na reserva.
  PERFORM public.fn_fiscal_assert_debtor_recipient(p_invoice_id);

  SELECT * INTO emit FROM (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EMITTER_NOT_CONFIGURED: emitente nao cadastrado.'; END IF;
  IF coalesce(emit.nfe_environment_code,'2') = '1' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_BLOCKED: ambiente de producao (tpAmb=1) bloqueado na fase F3; teto READY_HOMOLOGATION.';
  END IF;
  IF emit.nfe_readiness_status <> 'READY_HOMOLOGATION' THEN
    RAISE EXCEPTION 'FISCAL_EMITTER_NOT_READY: emitente com pendencias %', emit.nfe_readiness_pendencies;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('fiscal_series:' || emit.id::text || ':' ||
          coalesce(emit.nfe_series_number,0)::text || ':' || coalesce(emit.nfe_environment_code,'2')));

  SELECT * INTO s FROM (SELECT * FROM public.fiscal_document_series WHERE public.h15_company_access(company_id)) fiscal_document_series
   WHERE company_id = emit.id AND document_model = '55'
     AND series = emit.nfe_series_number AND environment_code = emit.nfe_environment_code
   FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.fiscal_document_series (company_id, series, environment_code, created_by)
    VALUES (emit.id, emit.nfe_series_number, emit.nfe_environment_code, auth.uid())
    RETURNING * INTO s;
    SELECT * INTO s FROM (SELECT * FROM public.fiscal_document_series WHERE public.h15_company_access(company_id)) fiscal_document_series WHERE id = s.id FOR UPDATE;
  END IF;
  IF s.status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'FISCAL_SERIES_BLOCKED: serie % bloqueada.', s.series;
  END IF;

  n := s.current_number + 1;
  IF n > 999999999 THEN RAISE EXCEPTION 'FISCAL_SERIES_EXHAUSTED: serie % esgotada.', s.series; END IF;

  cnf := lpad(((get_byte(extensions.gen_random_bytes(4),0)::bigint << 24
              | get_byte(extensions.gen_random_bytes(4),0)::bigint << 16
              | get_byte(extensions.gen_random_bytes(4),0)::bigint << 8
              | get_byte(extensions.gen_random_bytes(4),0)::bigint) % 100000000)::text, 8, '0');

  cuf := public.fn_fiscal_uf_ibge_code(emit.state);
  key43 := cuf
        || to_char(coalesce(inv.issue_date, current_date), 'YYMM')
        || public.fn_fiscal_digits(emit.cnpj)
        || '55'
        || lpad(s.series::text, 3, '0')
        || lpad(n::text, 9, '0')
        || coalesce(inv.tp_emis,1)::text
        || cnf;
  dv := public.fn_fiscal_access_key_dv(key43);
  full_key := key43 || dv::text;

  UPDATE public.fiscal_document_series SET current_number = n, updated_at = now() WHERE id = s.id;

  INSERT INTO public.fiscal_number_reservations
    (series_id, number, cnf, access_key, check_digit, status, fiscal_invoice_id,
     idempotency_key, reserved_by, tp_emis)
  VALUES (s.id, n, cnf, full_key, dv, 'RESERVED', p_invoice_id,
          p_idempotency_key, auth.uid(), coalesce(inv.tp_emis,1));

  UPDATE public.fiscal_invoices
     SET series = s.series::text, invoice_number = n::text, access_key = full_key, updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('number', n, 'series', s.series, 'accessKey', full_key,
                            'checkDigit', dv, 'tpEmis', coalesce(inv.tp_emis,1),
                            'status','RESERVED', 'idempotentReplay', false);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_anexar_comprovante_entrega(p_entrega_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
  v_comp_id uuid;
  v_rec_nome text := nullif(trim(coalesce(p_payload->>'recebedor_nome','')), '');
  v_hash text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão inválida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  SELECT * INTO v_entrega FROM public.entregas WHERE id = p_entrega_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada'; END IF;
  IF v_entrega.status = 'cancelada' THEN RAISE EXCEPTION 'Entrega cancelada'; END IF;
  IF v_entrega.assinatura_obrigatoria AND v_rec_nome IS NULL THEN
    RAISE EXCEPTION 'recebedor_nome é obrigatório';
  END IF;
  IF coalesce(p_payload->>'arquivo_path','') = '' THEN
    RAISE EXCEPTION 'arquivo_path é obrigatório';
  END IF;

  v_comp_id := v_entrega.comprovante_id;
  IF v_comp_id IS NULL THEN
    PERFORM public.rpc_gerar_formulario_entrega(p_entrega_id);
    SELECT comprovante_id INTO v_comp_id FROM public.entregas WHERE id = p_entrega_id;
  END IF;

  UPDATE public.entrega_comprovantes SET
    status = 'anexado',
    arquivo_path = p_payload->>'arquivo_path',
    arquivo_url = p_payload->>'arquivo_url',
    arquivo_nome = p_payload->>'arquivo_nome',
    arquivo_mime = p_payload->>'arquivo_mime',
    assinatura_coletada = true,
    assinatura_tipo = 'fisica_anexada',
    recebedor_nome = v_rec_nome,
    recebedor_documento = nullif(p_payload->>'recebedor_documento',''),
    recebedor_cargo = nullif(p_payload->>'recebedor_cargo',''),
    recebedor_telefone = nullif(p_payload->>'recebedor_telefone',''),
    data_assinatura = coalesce((p_payload->>'data_assinatura')::timestamptz, now()),
    anexado_por = v_uid,
    anexado_em = now(),
    updated_at = now()
  WHERE id = v_comp_id
  RETURNING validation_hash INTO v_hash;

  UPDATE public.entregas SET
    comprovante_status = 'anexado',
    assinatura_tipo = 'fisica_anexada',
    recebedor_nome = coalesce(v_rec_nome, recebedor_nome),
    recebedor_documento = coalesce(nullif(p_payload->>'recebedor_documento',''), recebedor_documento),
    recebedor_cargo = coalesce(nullif(p_payload->>'recebedor_cargo',''), recebedor_cargo),
    recebedor_telefone = coalesce(nullif(p_payload->>'recebedor_telefone',''), recebedor_telefone),
    comprovante_anexado_em = now(),
    comprovante_anexado_por = v_uid,
    updated_at = now()
  WHERE id = p_entrega_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', p_entrega_id, 'DELIVERY_PROOF_ATTACHED',
          jsonb_build_object('comprovante_id', v_comp_id, 'arquivo_path', p_payload->>'arquivo_path'), v_uid);

  RETURN jsonb_build_object('success', true, 'comprovante_id', v_comp_id, 'validation_hash', v_hash);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_aplicar_sla_alertas()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alerta record;
  v_config record;
  v_processados int := 0;
  v_configurados int := 0;
  v_vencidos int := 0;
  v_escalonados int := 0;
  v_reclassificados int := 0;
  v_sem_sla int := 0;
  v_grav_anterior text;
  v_uid uuid := auth.uid();
  v_is_service boolean := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role', false);
BEGIN
  IF NOT v_is_service THEN
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'permission_denied' USING HINT = 'Usuario nao autenticado';
    END IF;
    IF NOT (
      public.has_role(v_uid,'administrador'::app_role)
      OR public.has_role(v_uid,'gestor'::app_role)
      OR public.has_role(v_uid,'administrativo'::app_role)
    ) THEN
      RAISE EXCEPTION 'permission_denied' USING HINT = 'Perfil sem permissao para aplicar SLA';
    END IF;
  END IF;

  FOR v_alerta IN
    SELECT * FROM public.alertas_operacionais
    WHERE COALESCE(status,'aberto') NOT IN ('resolvido','ignorado','cancelado')
  LOOP
    v_processados := v_processados + 1;

    SELECT * INTO v_config FROM public.alertas_sla_config
      WHERE ativo = true AND tipo_alerta = v_alerta.tipo
      LIMIT 1;
    IF NOT FOUND THEN
      SELECT * INTO v_config FROM public.alertas_sla_config
        WHERE ativo = true AND origem = v_alerta.origem AND gravidade = v_alerta.gravidade
        LIMIT 1;
    END IF;
    IF NOT FOUND THEN
      SELECT * INTO v_config FROM public.alertas_sla_config
        WHERE ativo = true AND tipo_alerta IS NULL AND origem IS NULL AND gravidade = v_alerta.gravidade
        LIMIT 1;
    END IF;

    IF NOT FOUND OR v_config.prazo_resolucao_minutos = 0 THEN
      v_sem_sla := v_sem_sla + 1;
      CONTINUE;
    END IF;

    IF v_alerta.sla_config_id IS NULL THEN
      UPDATE public.alertas_operacionais
        SET sla_config_id = v_config.id,
            sla_primeira_resposta_em = CASE WHEN v_config.prazo_primeira_resposta_minutos IS NOT NULL
              THEN v_alerta.created_at + make_interval(mins => v_config.prazo_primeira_resposta_minutos)
              ELSE NULL END,
            sla_resolucao_em = v_alerta.created_at + make_interval(mins => v_config.prazo_resolucao_minutos)
        WHERE id = v_alerta.id;

      INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, prazo_primeira_resposta_em, prazo_resolucao_em)
        VALUES (v_alerta.id, v_config.id, 'sla_configurado',
          CASE WHEN v_config.prazo_primeira_resposta_minutos IS NOT NULL
            THEN v_alerta.created_at + make_interval(mins => v_config.prazo_primeira_resposta_minutos)
            ELSE NULL END,
          v_alerta.created_at + make_interval(mins => v_config.prazo_resolucao_minutos));

      v_configurados := v_configurados + 1;
      SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = v_alerta.id;
    END IF;

    IF NOT v_alerta.sla_vencido AND v_alerta.sla_resolucao_em IS NOT NULL AND now() > v_alerta.sla_resolucao_em THEN
      UPDATE public.alertas_operacionais
        SET sla_vencido = true, sla_vencido_em = now()
        WHERE id = v_alerta.id;
      INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, vencido_em)
        VALUES (v_alerta.id, v_config.id, 'sla_resolucao_vencido', now());
      v_vencidos := v_vencidos + 1;
      v_alerta.sla_vencido := true;
    END IF;

    IF NOT v_alerta.escalonado
       AND v_config.escalonar_apos_minutos IS NOT NULL
       AND v_alerta.created_at + make_interval(mins => v_config.escalonar_apos_minutos) < now() THEN
      UPDATE public.alertas_operacionais
        SET escalonado = true, escalonado_em = now()
        WHERE id = v_alerta.id;
      INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, escalonado_em, gestor_notificado)
        VALUES (v_alerta.id, v_config.id, 'escalonado', now(), v_config.notificar_gestor);
      v_escalonados := v_escalonados + 1;
      v_alerta.escalonado := true;

      IF v_config.nova_gravidade_apos_sla IS NOT NULL
         AND v_config.nova_gravidade_apos_sla <> v_alerta.gravidade
         AND v_alerta.tipo IS DISTINCT FROM 'aplicacao_nao_registrada' THEN
        v_grav_anterior := v_alerta.gravidade;
        UPDATE public.alertas_operacionais
          SET gravidade = v_config.nova_gravidade_apos_sla
          WHERE id = v_alerta.id;
        INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, gravidade_anterior, gravidade_nova)
          VALUES (v_alerta.id, v_config.id, 'prioridade_reclassificada', v_grav_anterior, v_config.nova_gravidade_apos_sla);
        v_reclassificados := v_reclassificados + 1;
      END IF;
    END IF;

    PERFORM public.rpc_recalcular_prioridade_alerta(v_alerta.id);
  END LOOP;

  RETURN jsonb_build_object(
    'total_processados', v_processados,
    'total_sla_configurados', v_configurados,
    'total_vencidos', v_vencidos,
    'total_escalonados', v_escalonados,
    'total_reclassificados', v_reclassificados,
    'total_sem_sla', v_sem_sla,
    'executado_em', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_arquivar_visita(p_registro_id uuid, p_expected_version integer, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_new_version integer;
  v_motivo text := NULLIF(btrim(COALESCE(p_motivo, '')), '');
BEGIN
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, false);

  IF v_reg.status::text = 'arquivado' THEN
    RETURN jsonb_build_object('ok', true, 'version', v_reg.version, 'status', 'arquivado', 'idempotent', true);
  END IF;

  IF v_reg.status::text <> 'rascunho' AND v_motivo IS NULL THEN
    RAISE EXCEPTION 'motivo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;

  -- a matriz de transições é validada pelo trigger de status do registro
  UPDATE public.registros_consultor
     SET status = 'arquivado', version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
   RETURNING version INTO v_new_version;

  PERFORM public._visita_log_status(
    p_registro_id, 'visita_arquivada', v_reg.status::text, 'arquivado', v_motivo, v_new_version);

  RETURN jsonb_build_object('ok', true, 'version', v_new_version, 'status', 'arquivado');
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.c2_owner_order_guard(_uid uuid, _partner uuid, _plan uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  -- Internos e superadmin seguem as regras existentes da função chamadora.
  IF public.is_platform_superadmin(_uid)
     OR public.has_role(_uid,'administrador'::public.app_role) OR public.has_role(_uid,'financeiro'::public.app_role)
     OR public.has_role(_uid,'gestor_comercial'::public.app_role) THEN
    RETURN;
  END IF;
  -- Parceiro com organização própria (fornecedor legado): comportamento inalterado.
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.partner_account_id = _partner) THEN RETURN; END IF;
  IF NOT platform_private.c2_owner_order_create_allowed(_uid,_partner) THEN
    RAISE EXCEPTION 'C2_OWNER_ORDER_CLOSED' USING ERRCODE='42501';
  END IF;
  IF _plan IS NULL OR NOT platform_private.c2_owner_plan_assigned(_partner,_plan) THEN
    RAISE EXCEPTION 'plan_not_assigned' USING ERRCODE='42501';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_invoice_store_protocoled_xml_v1(_invoice_id uuid, _transmission_id uuid, _access_key text, _protocol text, _storage_path text, _content_sha256 text, _content_bytes integer, _xml_run_id uuid DEFAULT NULL::uuid, _storage_bucket text DEFAULT 'fiscal-xml'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inv public.fiscal_invoices%ROWTYPE;
  v_doc public.fiscal_protocoled_documents%ROWTYPE;
  v_tx  public.fiscal_sefaz_transmissions%ROWTYPE;
  v_run uuid := _xml_run_id;
BEGIN
  IF coalesce(_access_key,'') !~ '^[0-9]{44}$'
     OR coalesce(_protocol,'') !~ '^[0-9]{1,20}$'
     OR lower(coalesce(_content_sha256,'')) !~ '^[0-9a-f]{64}$'
     OR coalesce(_content_bytes,0) <= 0
     OR nullif(btrim(coalesce(_storage_path,'')),'') IS NULL
     OR coalesce(_storage_bucket,'') <> 'fiscal-xml' THEN
    RAISE EXCEPTION 'FISCAL_PROTOCOLED_PAYLOAD_INVALID';
  END IF;

  SELECT * INTO v_inv FROM public.fiscal_invoices WHERE id = _invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND'; END IF;
  IF coalesce(v_inv.environment,'HOMOLOGATION') = 'PRODUCTION' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;
  IF v_inv.normalized_status <> 'AUTHORIZED' THEN
    RAISE EXCEPTION 'FISCAL_DOCUMENT_NOT_AUTHORIZED';
  END IF;
  IF coalesce(v_inv.access_key,'') <> _access_key THEN
    RAISE EXCEPTION 'FISCAL_AUTHORIZATION_CONFLICT: chave divergente da nota autorizada.';
  END IF;

  -- O protocolo tem de vir de uma transmissao autorizada ja persistida.
  IF _transmission_id IS NOT NULL THEN
    SELECT * INTO v_tx FROM public.fiscal_sefaz_transmissions WHERE id = _transmission_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_TRANSMISSION_NOT_FOUND'; END IF;
    IF v_tx.fiscal_invoice_id IS DISTINCT FROM _invoice_id
       OR coalesce(v_tx.ch_nfe,'') <> _access_key
       OR coalesce(v_tx.n_prot,'') <> _protocol
       OR coalesce(v_tx.outcome,'') <> 'AUTHORIZED'
       OR coalesce(v_tx.ambiente_retorno,'2') <> '2' THEN
      RAISE EXCEPTION 'FISCAL_AUTHORIZATION_CONFLICT: retorno divergente do protocolo informado.';
    END IF;
    v_run := coalesce(v_run, v_tx.xml_run_id);
  END IF;

  -- Replay idempotente: mesmo artefato => no-op.
  SELECT * INTO v_doc FROM public.fiscal_protocoled_documents
   WHERE fiscal_invoice_id = _invoice_id AND access_key = _access_key AND protocol = _protocol;
  IF FOUND THEN
    IF v_doc.content_sha256 <> lower(_content_sha256) OR v_doc.storage_path <> _storage_path THEN
      INSERT INTO public.fiscal_audit_log (table_name, record_id, action, old_values, new_values, changed_by)
      VALUES ('fiscal_protocoled_documents', v_doc.id, 'CONFLICT',
              jsonb_build_object('sha256', v_doc.content_sha256, 'path', v_doc.storage_path),
              jsonb_build_object('sha256', lower(_content_sha256), 'path', _storage_path), NULL);
      RAISE EXCEPTION 'FISCAL_PROTOCOLED_DOCUMENT_CONFLICT';
    END IF;
    RETURN jsonb_build_object('invoiceId', _invoice_id, 'documentId', v_doc.id,
      'stored', false, 'replay', true, 'protocoledXmlStored', true,
      'reconciliationStatus', (SELECT reconciliation_status FROM public.fiscal_invoices WHERE id = _invoice_id));
  END IF;

  -- Conflito duro: outro protocolo ja fechou a mesma chave.
  IF EXISTS (SELECT 1 FROM public.fiscal_protocoled_documents
              WHERE fiscal_invoice_id = _invoice_id AND access_key = _access_key
                AND protocol <> _protocol) THEN
    RAISE EXCEPTION 'FISCAL_PROTOCOLED_DOCUMENT_CONFLICT';
  END IF;

  INSERT INTO public.fiscal_protocoled_documents
    (fiscal_invoice_id, transmission_id, xml_run_id, access_key, protocol,
     storage_bucket, storage_path, content_sha256, content_bytes, authorized_at)
  VALUES (_invoice_id, _transmission_id, v_run, _access_key, _protocol,
          _storage_bucket, _storage_path, lower(_content_sha256), _content_bytes,
          coalesce(v_inv.authorized_at, now()))
  RETURNING * INTO v_doc;

  UPDATE public.fiscal_invoices
     SET reconciliation_status = 'RECONCILED', updated_at = now()
   WHERE id = _invoice_id;

  INSERT INTO public.fiscal_audit_log (table_name, record_id, action, old_values, new_values, changed_by)
  VALUES ('fiscal_invoices', _invoice_id, 'UPDATE',
          jsonb_build_object('reconciliationStatus', v_inv.reconciliation_status,
                             'protocoledXmlStored', false),
          jsonb_build_object('reconciliationStatus', 'RECONCILED',
                             'protocoledXmlStored', true,
                             'protocoledDocumentId', v_doc.id,
                             'accessKey', _access_key, 'protocol', _protocol,
                             'storagePath', _storage_path,
                             'contentSha256', lower(_content_sha256)), NULL);

  RETURN jsonb_build_object('invoiceId', _invoice_id, 'documentId', v_doc.id,
    'stored', true, 'replay', false, 'protocoledXmlStored', true,
    'reconciliationStatus', 'RECONCILED');
END $function$

CREATE OR REPLACE FUNCTION public.rpc_archive_communication_template(p_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_templates%rowtype;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO r FROM public.comunicacao_templates WHERE id = p_template_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'template não encontrado'; END IF;
  IF r.status = 'archived' THEN
    RETURN jsonb_build_object('ok',true,'already_archived',true);
  END IF;
  UPDATE public.comunicacao_templates
     SET status = 'archived', archived_at = now(), updated_by = auth.uid()
   WHERE id = p_template_id;
  PERFORM public._comunicacao_write_audit('template.archive','comunicacao_templates',p_template_id,
    to_jsonb(r), (SELECT to_jsonb(t) FROM public.comunicacao_templates t WHERE t.id = p_template_id));
  RETURN jsonb_build_object('ok',true);
END$function$

CREATE OR REPLACE FUNCTION public.rpc_associate_microorganism_fiscal_product(p_microorganism_id uuid, p_product_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, product_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_role(v_uid, 'administrador'::public.app_role)
    OR public.has_role(v_uid, 'financeiro'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  IF p_microorganism_id IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.microrganismos m WHERE m.id = p_microorganism_id) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_product_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.produtos p WHERE p.id = p_product_id) THEN
      RAISE EXCEPTION 'product_not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  RETURN QUERY
  UPDATE public.microrganismos m
     SET product_id = p_product_id
   WHERE m.id = p_microorganism_id
  RETURNING m.id, m.product_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_assign_visit_technician(p_registro_id uuid, p_user_id uuid, p_role text DEFAULT 'tecnico'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_reactivated boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_registro_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'parametros_obrigatorios' USING ERRCODE='22023';
  END IF;
  IF NOT public.can_manage_technical_visit(v_uid, p_registro_id) THEN
    RAISE EXCEPTION 'forbidden_gestao_equipe' USING ERRCODE='42501';
  END IF;

  SELECT id INTO v_id FROM public.technical_visit_assignments
    WHERE registro_consultor_id = p_registro_id AND user_id = p_user_id LIMIT 1;

  IF v_id IS NOT NULL THEN
    UPDATE public.technical_visit_assignments
       SET is_active = true,
           role = COALESCE(p_role, role),
           removed_at = NULL,
           removal_reason = NULL,
           assigned_by = v_uid,
           assigned_at = now(),
           updated_at = now()
     WHERE id = v_id;
    v_reactivated := true;
  ELSE
    INSERT INTO public.technical_visit_assignments
      (registro_consultor_id, user_id, role, is_active, assigned_by, assigned_at)
    VALUES (p_registro_id, p_user_id, COALESCE(p_role,'tecnico'), true, v_uid, now())
    RETURNING id INTO v_id;
  END IF;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, v_uid,
          CASE WHEN v_reactivated THEN 'tecnico_reativado' ELSE 'tecnico_atribuido' END,
          'Técnico ' || p_user_id::text || ' (' || COALESCE(p_role,'tecnico') || ') atribuído à visita');

  RETURN jsonb_build_object('id', v_id, 'reactivated', v_reactivated);
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_ativar_monitoramento_visita(p_registro_id uuid, p_expected_version integer, p_tipo text, p_data_referencia date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_id uuid;
  v_new_version integer;
BEGIN
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, false);

  IF p_tipo IS NULL OR btrim(p_tipo) = '' THEN
    RAISE EXCEPTION 'tipo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;

  SELECT id INTO v_id FROM public.monitoramento_avisos
   WHERE registro_consultor_id = p_registro_id AND tipo = p_tipo
     AND data_referencia IS NOT DISTINCT FROM p_data_referencia
   LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'id', v_id, 'version', v_reg.version, 'idempotent', true);
  END IF;

  INSERT INTO public.monitoramento_avisos (registro_consultor_id, tipo, data_referencia)
  VALUES (p_registro_id, p_tipo, p_data_referencia)
  RETURNING id INTO v_id;

  UPDATE public.registros_consultor
     SET version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
   RETURNING version INTO v_new_version;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao, metadata)
  VALUES (p_registro_id, auth.uid(), 'monitoramento_ativado', 'Plano de monitoramento: ' || p_tipo,
          jsonb_build_object('tipo', p_tipo, 'data_referencia', p_data_referencia, 'version', v_new_version));

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'version', v_new_version);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_atualizar_checklist_entrega(p_checklist_id uuid, p_concluido boolean, p_observacao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão inválida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  SELECT entrega_id INTO v_entrega_id FROM public.entrega_checklist WHERE id = p_checklist_id;
  IF v_entrega_id IS NULL THEN RAISE EXCEPTION 'Checklist não encontrado'; END IF;

  UPDATE public.entrega_checklist SET
    concluido = p_concluido,
    observacao = coalesce(p_observacao, observacao),
    concluido_por = CASE WHEN p_concluido THEN v_uid ELSE NULL END,
    concluido_em = CASE WHEN p_concluido THEN now() ELSE NULL END
  WHERE id = p_checklist_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', v_entrega_id, 'DELIVERY_CHECKLIST_UPDATED',
          jsonb_build_object('checklist_id', p_checklist_id, 'concluido', p_concluido), v_uid);

  RETURN jsonb_build_object('success', true);
END $function$

