CREATE OR REPLACE FUNCTION public.h15_invoice_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.company_fiscal_settings; creator_org uuid; k text; expected text; actual text;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.company_settings_id IS DISTINCT FROM OLD.company_settings_id OR NEW.created_by IS DISTINCT FROM OLD.created_by) THEN
 RAISE EXCEPTION 'H15_INVOICE_OWNERSHIP_IMMUTABLE' USING ERRCODE='23514'; END IF;
 SELECT * INTO c FROM public.company_fiscal_settings WHERE id=NEW.company_settings_id;
 SELECT organization_id INTO creator_org FROM public.profiles WHERE user_id=NEW.created_by;
 IF c.id IS NULL OR creator_org IS DISTINCT FROM c.organization_id THEN RAISE EXCEPTION 'H15_CREATOR_ORGANIZATION_MISMATCH' USING ERRCODE='23514'; END IF;
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN
 PERFORM public.h15_require_company(c.id);
 IF TG_OP='INSERT' AND NEW.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'H15_CREATOR_FORGED' USING ERRCODE='42501'; END IF;
 END IF;
 IF NEW.company_cnpj IS NOT NULL AND regexp_replace(NEW.company_cnpj,'[^0-9]','','g') IS DISTINCT FROM regexp_replace(c.cnpj,'[^0-9]','','g') THEN
 RAISE EXCEPTION 'H15_CNPJ_MISMATCH' USING ERRCODE='23514'; END IF;
 IF NEW.company_snapshot IS NOT NULL AND NEW.company_snapshot <> '{}'::jsonb THEN
 IF NOT (NEW.company_snapshot ? 'cnpj') OR NULLIF(NEW.company_snapshot->>'cnpj','') IS NULL THEN RAISE EXCEPTION 'H15_SNAPSHOT_CNPJ_REQUIRED' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(NEW.company_snapshot)<>'object' THEN RAISE EXCEPTION 'H15_SNAPSHOT_INVALID' USING ERRCODE='23514'; END IF;
 -- All identity fields supplied must agree; absent fields remain draft pendencies.
 FOR k IN SELECT jsonb_object_keys(NEW.company_snapshot) LOOP
 actual:=NEW.company_snapshot->>k;
 expected:=CASE k WHEN 'cnpj' THEN c.cnpj WHEN 'legalName' THEN c.legal_name WHEN 'ie' THEN c.state_registration WHEN 'uf' THEN c.state WHEN 'municipalityIbge' THEN c.municipality_ibge_code WHEN 'series' THEN c.nfe_series_number::text WHEN 'environment' THEN c.nfe_environment_code WHEN 'legal_name' THEN c.legal_name WHEN 'crt' THEN c.crt WHEN 'state_registration' THEN c.state_registration WHEN 'state' THEN c.state WHEN 'municipality_ibge_code' THEN c.municipality_ibge_code WHEN 'nfe_series' THEN c.nfe_series::text WHEN 'nfse_series' THEN c.nfse_series::text WHEN 'fiscal_environment' THEN c.fiscal_environment ELSE NULL END;
 IF k IN ('legalName','ie','uf','municipalityIbge','series','environment','cnpj','legal_name','crt','state_registration','state','municipality_ibge_code','nfe_series','nfse_series','fiscal_environment') AND actual IS DISTINCT FROM expected THEN
 RAISE EXCEPTION 'H15_SNAPSHOT_MISMATCH:%',k USING ERRCODE='23514'; END IF;
 END LOOP;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_generate_payable_installments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  i int;
  v_context platform_private.financial_initial_installments;
  v_inst jsonb;
  v_qtd int := NEW.installment_count;
  v_base numeric(14,2) := ROUND(NEW.total_amount / v_qtd, 2);
  v_acc numeric(14,2) := 0;
  v_amt numeric(14,2);
BEGIN
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_REQUIRED' USING ERRCODE='23514';
  END IF;
  DELETE FROM platform_private.financial_initial_installments
    WHERE transaction_id=txid_current() AND title_id=NEW.id AND kind='payable'
    RETURNING * INTO v_context;
  IF FOUND THEN
    IF v_context.actor_id IS DISTINCT FROM auth.uid() OR v_context.organization_id IS DISTINCT FROM NEW.organization_id
       OR NEW.created_by IS DISTINCT FROM v_context.actor_id OR NEW.origin_type <> 'MANUAL'
       OR platform_private.h15_actor_organization() IS DISTINCT FROM NEW.organization_id
       OR NOT public.is_financial_staff(auth.uid()) THEN
      RAISE EXCEPTION 'FIN_INITIAL_CONTEXT_DENIED' USING ERRCODE='42501';
    END IF;
    IF jsonb_array_length(v_context.installments) <> NEW.installment_count
       OR (SELECT sum((x->>'amount')::numeric) FROM jsonb_array_elements(v_context.installments) x) IS DISTINCT FROM NEW.total_amount THEN
      RAISE EXCEPTION 'FIN_TITLE_INVALID_SUM' USING ERRCODE='23514';
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_context.installments) LOOP
      INSERT INTO public.accounts_payable_installments(organization_id,payable_id,installment_number,due_date,original_amount,net_amount,status)
        VALUES(NEW.organization_id,NEW.id,(v_inst->>'installment_number')::int,(v_inst->>'due_date')::date,
          (v_inst->>'amount')::numeric,(v_inst->>'amount')::numeric,'OPEN');
    END LOOP;
    RETURN NEW;
  END IF;
  FOR i IN 1..v_qtd LOOP
    IF i < v_qtd THEN
      v_amt := v_base;
      v_acc := v_acc + v_amt;
    ELSE
      v_amt := NEW.total_amount - v_acc;
    END IF;
    INSERT INTO public.accounts_payable_installments
      (organization_id, payable_id, installment_number, due_date, original_amount, net_amount, status)
    VALUES
      (NEW.organization_id, NEW.id, i, (NEW.first_due_date + ((i-1) || ' months')::interval)::date, v_amt, v_amt, 'OPEN');
  END LOOP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.h15_related_company(p_table text, p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c uuid;
BEGIN
 CASE p_table
 WHEN 'company_fiscal_settings' THEN SELECT id INTO c FROM public.company_fiscal_settings WHERE id=p_id;
 WHEN 'fiscal_invoices' THEN SELECT company_settings_id INTO c FROM public.fiscal_invoices WHERE id=p_id;
 WHEN 'fiscal_certificates' THEN SELECT company_settings_id INTO c FROM public.fiscal_certificates WHERE id=p_id;
 WHEN 'fiscal_document_series' THEN SELECT company_id INTO c FROM public.fiscal_document_series WHERE id=p_id;
 WHEN 'fiscal_invoice_items' THEN SELECT i.company_settings_id INTO c FROM public.fiscal_invoice_items r JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id WHERE r.id=p_id;
 WHEN 'fiscal_events' THEN SELECT i.company_settings_id INTO c FROM public.fiscal_events r JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id WHERE r.id=p_id;
 WHEN 'fiscal_xml_runs' THEN SELECT i.company_settings_id INTO c FROM public.fiscal_xml_runs r JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id WHERE r.id=p_id;
 WHEN 'fiscal_number_reservations' THEN SELECT i.company_settings_id INTO c FROM public.fiscal_number_reservations r JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id WHERE r.id=p_id;
 WHEN 'fiscal_sefaz_transmissions' THEN
 SELECT coalesce(i.company_settings_id,xi.company_settings_id,ei.company_settings_id) INTO c
 FROM public.fiscal_sefaz_transmissions r
 LEFT JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id
 LEFT JOIN public.fiscal_xml_runs x ON x.id=r.xml_run_id
 LEFT JOIN public.fiscal_invoices xi ON xi.id=x.fiscal_invoice_id
 LEFT JOIN public.fiscal_events e ON e.id=r.fiscal_event_id
 LEFT JOIN public.fiscal_invoices ei ON ei.id=e.fiscal_invoice_id
 WHERE r.id=p_id;
 ELSE RAISE EXCEPTION 'H15_UNKNOWN_RELATION' USING ERRCODE='23514';
 END CASE;
 RETURN c;
END $function$

CREATE OR REPLACE FUNCTION public.h15_related_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE data jsonb:=to_jsonb(NEW); old_data jsonb; owner_company uuid; linked uuid; n integer; target uuid;
BEGIN
 IF TG_OP='UPDATE' THEN old_data:=to_jsonb(OLD);
 IF data->TG_ARGV[0] IS DISTINCT FROM old_data->TG_ARGV[0] THEN RAISE EXCEPTION 'H15_PARENT_IMMUTABLE' USING ERRCODE='23514'; END IF;
 END IF;
 target:=nullif(data->>TG_ARGV[0],'')::uuid;
 -- Only technical idempotency operations may have no invoice at all.
 IF TG_TABLE_NAME='fiscal_idempotency_keys' AND target IS NULL THEN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'H15_TECHNICAL_OPERATION_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
 END IF;
 IF TG_TABLE_NAME<>'fiscal_sefaz_transmissions' THEN
 owner_company:=public.h15_related_company(TG_ARGV[1],target);
 IF owner_company IS NULL THEN RAISE EXCEPTION 'H15_PARENT_REQUIRED' USING ERRCODE='23514'; END IF;
 END IF;
 -- Transmissions derive their issuer from the first non-null link, not argument zero.
 n:=0;
 WHILE n<TG_NARGS LOOP
 target:=nullif(data->>TG_ARGV[n],'')::uuid;
 IF target IS NOT NULL THEN
 linked:=public.h15_related_company(TG_ARGV[n+1],target);
 IF linked IS NULL THEN RAISE EXCEPTION 'H15_PARENT_REQUIRED' USING ERRCODE='23514'; END IF;
 IF owner_company IS NULL THEN owner_company:=linked; END IF;
 IF linked IS DISTINCT FROM owner_company THEN RAISE EXCEPTION 'H15_CROSS_COMPANY_REFERENCE:%',TG_ARGV[n] USING ERRCODE='23514'; END IF;
 END IF;
 n:=n+2;
 END LOOP;
 IF owner_company IS NULL THEN RAISE EXCEPTION 'H15_PARENT_REQUIRED' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='fiscal_sefaz_transmissions' AND TG_OP='UPDATE' THEN
 IF owner_company IS DISTINCT FROM public.h15_related_company('fiscal_sefaz_transmissions',OLD.id) THEN RAISE EXCEPTION 'H15_PARENT_IMMUTABLE' USING ERRCODE='23514'; END IF;
 END IF;
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN PERFORM public.h15_require_company(owner_company); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.recalc_partner_risk_score(p_partner_id uuid)
 RETURNS partner_risk_scores
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dias_atraso numeric := 0;
  v_vencidos int := 0;
  v_pct numeric := 0;
  v_freq int := 0;
  v_meses int := 0;
  v_limite numeric := 0;
  v_aberto numeric := 0;
  v_score int := 0;
  v_level text := 'baixo';
  v_row public.partner_risk_scores;
BEGIN
  -- H7O: dentro de trigger (pg_trigger_depth()>0) ou sessão interna (sem JWT) segue livre;
  -- chamada autenticada direta exige staff financeiro.
  IF pg_trigger_depth() = 0 AND auth.uid() IS NOT NULL AND NOT public.is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
      HINT = 'H7O: recálculo de score de risco restrito ao staff financeiro.';
  END IF;

  IF p_partner_id IS NULL THEN RAISE EXCEPTION 'partner_id required'; END IF;

  SELECT COALESCE(AVG(GREATEST(0, CURRENT_DATE - ari.due_date)),0)::numeric,
         COUNT(*) FILTER (WHERE ari.status='OVERDUE' OR (ari.status IN ('OPEN','PARTIAL') AND ari.due_date < CURRENT_DATE))
    INTO v_dias_atraso, v_vencidos
  FROM accounts_receivable ar
  JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
  WHERE ar.origin_type='B2B_ORDER' AND ar.partner_id = p_partner_id
    AND ari.status IN ('OPEN','PARTIAL','OVERDUE');

  SELECT COALESCE(credit_limit,0) INTO v_limite FROM partner_financial_settings WHERE partner_id = p_partner_id;
  v_limite := COALESCE(v_limite,0);

  SELECT COALESCE(SUM(ari.original_amount - ari.received_amount),0) INTO v_aberto
  FROM accounts_receivable ar
  JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
  WHERE ar.origin_type='B2B_ORDER' AND ar.partner_id = p_partner_id
    AND ari.status IN ('OPEN','PARTIAL','OVERDUE');

  v_pct := CASE WHEN v_limite > 0 THEN LEAST(100,(v_aberto/v_limite)*100) ELSE 0 END;

  SELECT COUNT(*) INTO v_freq FROM partner_orders
   WHERE partner_id = p_partner_id AND created_at >= now() - interval '30 days'
     AND status NOT IN ('cancelado','reprovado');

  SELECT GREATEST(0, EXTRACT(YEAR FROM age(now(), pa.created_at))*12 + EXTRACT(MONTH FROM age(now(), pa.created_at)))::int
    INTO v_meses FROM partner_accounts pa WHERE id = p_partner_id;

  -- score (peso): atraso 35, vencidos 25, util 20, freq -10, relacionamento -10
  v_score := LEAST(100, GREATEST(0,
      ROUND(LEAST(v_dias_atraso/90.0,1)*35)
    + ROUND(LEAST(v_vencidos/5.0,1)*25)
    + ROUND((v_pct/100.0)*20)
    - ROUND(LEAST(v_freq/10.0,1)*10)
    - ROUND(LEAST(COALESCE(v_meses,0)/24.0,1)*10)
  ));
  v_level := CASE
    WHEN v_score <= 30 THEN 'baixo'
    WHEN v_score <= 60 THEN 'medio'
    WHEN v_score <= 80 THEN 'alto'
    ELSE 'critico' END;

  INSERT INTO partner_risk_scores (partner_id, score, risk_level, dias_medio_atraso, titulos_vencidos, pct_credito_utilizado, freq_compras_30d, meses_relacionamento, calculado_em)
  VALUES (p_partner_id, v_score, v_level, v_dias_atraso, v_vencidos, v_pct, v_freq, COALESCE(v_meses,0), now())
  ON CONFLICT (partner_id) DO UPDATE SET
    score = EXCLUDED.score,
    risk_level = EXCLUDED.risk_level,
    dias_medio_atraso = EXCLUDED.dias_medio_atraso,
    titulos_vencidos = EXCLUDED.titulos_vencidos,
    pct_credito_utilizado = EXCLUDED.pct_credito_utilizado,
    freq_compras_30d = EXCLUDED.freq_compras_30d,
    meses_relacionamento = EXCLUDED.meses_relacionamento,
    calculado_em = now()
  RETURNING * INTO v_row;

  INSERT INTO financial_governance_audit_log(usuario_id, partner_id, acao, dados_novos)
  VALUES (auth.uid(), p_partner_id, 'score_recalculado', to_jsonb(v_row));

  RETURN v_row;
END;$function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_sender_challenge_claim(p_version bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; s public.communication_tenant_email_settings; c platform_private.tenant_smtp_sender_challenges; v_id uuid:=gen_random_uuid(); v_fence uuid:=gen_random_uuid();
BEGIN
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 IF p_version IS NULL OR p_version<1 OR p_version>9007199254740991 OR p_key IS NULL THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 PERFORM platform_private.tenant_smtp_f4_reconcile(v_org);
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND actor_id=auth.uid() AND request_key=p_key;
 IF FOUND THEN
  IF c.version<>p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
  RETURN jsonb_build_object('replay',true,'challenge_id',c.id,'state',c.state,'version',c.version);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_f4_gate WHERE id AND approved) OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE id AND approved)
 OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR NOT s.credential_configured THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND state IN ('claimed','executing'))
 OR EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND state<>'complete') THEN RAISE EXCEPTION 'SMTP_BUSY' USING ERRCODE='40001'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '60 seconds') THEN RAISE EXCEPTION 'SMTP_COOLDOWN' USING ERRCODE='40001'; END IF;
 IF (SELECT count(*) FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '24 hours')>=5 THEN RAISE EXCEPTION 'SMTP_QUOTA' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid() AND version=p_version
  AND mode='connection' AND code='smtp_connection_ok' AND state='complete' AND completed_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
 -- A new challenge supersedes every open one (single valid code per tenant).
 UPDATE platform_private.tenant_smtp_sender_challenges SET state='invalidated',code_hash=NULL,code_salt=NULL,closed_at=clock_timestamp()
  WHERE organization_id=v_org AND state IN ('sent','ambiguous');
 INSERT INTO platform_private.tenant_smtp_sender_challenges(id,organization_id,actor_id,version,from_email,request_key,fence,actor_iat,state)
 VALUES(v_id,v_org,auth.uid(),p_version,lower(s.config->>'from_email'),p_key,v_fence,coalesce((auth.jwt()->>'iat')::bigint,0),'claimed');
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),p_version,'sender_challenge_claimed');
 RETURN jsonb_build_object('replay',false,'challenge_id',v_id,'fence',v_fence);
END $function$

CREATE OR REPLACE FUNCTION public.h15_profile_organization_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF current_setting('role',true) IN ('authenticated','anon') THEN
 IF TG_OP='INSERT' THEN
 IF NEW.organization_id IS NOT NULL THEN RAISE EXCEPTION 'H15_ORGANIZATION_PROVISIONING_REQUIRED' USING ERRCODE='42501'; END IF;
 ELSIF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
 RAISE EXCEPTION 'H15_ORGANIZATION_PROVISIONING_REQUIRED' USING ERRCODE='42501';
 END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_certificate_revoke(p_certificate_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_user uuid := auth.uid();
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_company((SELECT company_settings_id FROM (SELECT * FROM public.fiscal_certificates WHERE public.h15_company_access(company_settings_id)) fiscal_certificates WHERE id=p_certificate_id));

  IF v_user IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_role(v_user, 'administrador'::app_role) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_certificates WHERE public.h15_company_access(company_settings_id)) fiscal_certificates WHERE id = p_certificate_id) THEN
    RAISE EXCEPTION 'certificate_not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.fiscal_certificates
  SET is_active = false,
      status = CASE WHEN status <> 'REVOKED' THEN 'REVOKED' ELSE status END,
      revoked_at = COALESCE(revoked_at, now()),
      revoked_by = COALESCE(revoked_by, v_user),
      revoke_reason = COALESCE(NULLIF(LEFT(COALESCE(p_reason, ''), 500), ''), revoke_reason),
      updated_at = now()
  WHERE id = p_certificate_id;

  UPDATE public.company_fiscal_settings
  SET certificate_ref = NULL,
      updated_at = now()
  WHERE certificate_ref = p_certificate_id::text;
END;
$function$

