CREATE OR REPLACE FUNCTION public.rpc_cancel_financial_installment(p_installment_id uuid, p_kind text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status text; v_has_payment boolean; v_table text;
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'Motivo é obrigatório (mín. 5 caracteres).' USING ERRCODE='check_violation';
  END IF;
  IF p_kind NOT IN ('receivable','payable') THEN
    RAISE EXCEPTION 'Tipo inválido: %', p_kind USING ERRCODE='check_violation';
  END IF;

  IF p_kind = 'receivable' THEN
    SELECT status INTO v_status FROM accounts_receivable_installments WHERE id = p_installment_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Parcela não encontrada.'; END IF;
    IF v_status IN ('PAID','PARTIAL') THEN
      SELECT EXISTS (
        SELECT 1 FROM receivable_payments rp
        WHERE rp.installment_id = p_installment_id AND COALESCE(rp.is_reversal,false) = false
          AND NOT EXISTS (SELECT 1 FROM receivable_payments r2 WHERE r2.reversed_payment_id = rp.id)
      ) INTO v_has_payment;
      IF v_has_payment THEN
        RAISE EXCEPTION 'Parcela possui recebimentos não estornados.' USING ERRCODE='check_violation';
      END IF;
    END IF;
    IF v_status = 'CANCELED' THEN RAISE EXCEPTION 'Parcela já cancelada.'; END IF;
    UPDATE accounts_receivable_installments SET status='CANCELED' WHERE id = p_installment_id;
    v_table := 'accounts_receivable_installments';
  ELSE
    SELECT status INTO v_status FROM accounts_payable_installments WHERE id = p_installment_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Parcela não encontrada.'; END IF;
    IF v_status IN ('PAID','PARTIAL') THEN
      SELECT EXISTS (
        SELECT 1 FROM payable_payments pp
        WHERE pp.installment_id = p_installment_id AND COALESCE(pp.is_reversal,false) = false
          AND NOT EXISTS (SELECT 1 FROM payable_payments r2 WHERE r2.reversed_payment_id = pp.id)
      ) INTO v_has_payment;
      IF v_has_payment THEN
        RAISE EXCEPTION 'Parcela possui pagamentos não estornados.' USING ERRCODE='check_violation';
      END IF;
    END IF;
    IF v_status = 'CANCELED' THEN RAISE EXCEPTION 'Parcela já cancelada.'; END IF;
    UPDATE accounts_payable_installments SET status='CANCELED' WHERE id = p_installment_id;
    v_table := 'accounts_payable_installments';
  END IF;

  INSERT INTO financial_audit_log(entity_type, entity_id, action, old_data, new_data, performed_by, reason)
  VALUES (v_table, p_installment_id, 'INSTALLMENT_CANCELED',
          jsonb_build_object('status', v_status),
          jsonb_build_object('status','CANCELED'), auth.uid(), p_reason);
END$function$

CREATE OR REPLACE FUNCTION public.rpc_cancelar_embalagem(p_embalagem_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_st text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(p_embalagem_id) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN RAISE EXCEPTION 'motivo obrigatório'; END IF;
  SELECT status INTO v_st FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF v_st = 'entregue' THEN RAISE EXCEPTION 'embalagem já entregue'; END IF;
  UPDATE public.estoque_embalagens SET status='cancelado', cancelado_em=now(), cancelado_por=v_uid, motivo_cancelamento=p_motivo WHERE id = p_embalagem_id;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_anterior, status_novo, user_id, observacao)
    VALUES (p_embalagem_id, 'cancelamento', v_st, 'cancelado', v_uid, p_motivo);
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, reason)
    VALUES ('estoque_embalagem', p_embalagem_id, 'EMB_CANCELLED', v_uid, p_motivo);
  RETURN jsonb_build_object('success', true);
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_order_actor_scope(_uid uuid, _partner uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s record; r text;
BEGIN
  -- C2_INTERNAL_ORDER_ENTRY_V1: exclusive internal commercial actor (admin/gestor_comercial,
  -- no external B2B role) may target only its own organization's portfolio.
  IF platform_private.b2b_internal_commercial_actor() AND auth.uid() IS NOT DISTINCT FROM _uid THEN
    r := platform_private.c2_internal_order_target_reason(_uid,_partner);
    IF r IS NOT NULL OR _partner IS NULL THEN
      RAISE EXCEPTION 'C2_INTERNAL_TARGET_DENIED:%', COALESCE(r,'target_required') USING ERRCODE='42501';
    END IF;
    RETURN;
  END IF;
  IF public.has_role(_uid,'parceiro_b2b_tecnico'::public.app_role) AND public.has_role(_uid,'parceiro_b2b'::public.app_role)
     AND NOT public.is_platform_superadmin(_uid) THEN
    IF _uid IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
    IF NOT platform_private.c2_owner_order_create_allowed(_uid,_partner) THEN
      RAISE EXCEPTION 'forbidden_financial_terms' USING ERRCODE='42501';
    END IF;
    SELECT * INTO s FROM platform_private.b2b_actor_scope(_uid);
    IF NOT s.profile_ok THEN RAISE EXCEPTION 'inactive_scope' USING ERRCODE='42501'; END IF;
    IF s.org_partner IS DISTINCT FROM _partner OR NOT s.partner_valid
       OR s.user_partner_count <> 1 OR s.user_partner IS DISTINCT FROM _partner THEN
      RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
    END IF;
    RETURN;
  END IF;
  PERFORM platform_private.assert_b2b_partner_scope(_uid,_partner);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cancel_communication_delivery(p_outbox_id uuid, p_worker_id text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_outbox%rowtype; v_role text;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege'; END IF;
  IF NULLIF(trim(COALESCE(p_worker_id,'')),'') IS NULL THEN RAISE EXCEPTION 'worker_id obrigatório'; END IF;
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'processing' THEN RAISE EXCEPTION 'não estava em processing'; END IF;
  IF r.locked_by IS DISTINCT FROM p_worker_id THEN RAISE EXCEPTION 'lease de outro'; END IF;
  UPDATE public.comunicacao_outbox
     SET status='cancelled', error_code='cancelled',
         error_message=left(COALESCE(p_reason,''),2000),
         locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
   WHERE id = p_outbox_id;
  RETURN jsonb_build_object('ok',true,'status','cancelled');
END$function$

CREATE OR REPLACE FUNCTION public.rpc_cancelar_etiqueta_produto(p_etiqueta_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN
    RAISE EXCEPTION 'Motivo obrigatório';
  END IF;
  IF NOT (
    public.has_role(v_uid,'administrador'::app_role)
    OR public.has_role(v_uid,'gestor'::app_role)
    OR public.has_role(v_uid,'producao'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para cancelar etiqueta';
  END IF;

  UPDATE public.produto_etiquetas
    SET status='cancelada',
        metadata = metadata || jsonb_build_object('cancelada_em', now(), 'cancelada_por', v_uid, 'motivo', p_motivo)
    WHERE id = p_etiqueta_id AND status <> 'cancelada';
  IF NOT FOUND THEN RAISE EXCEPTION 'Etiqueta não encontrada ou já cancelada'; END IF;

  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, descricao, user_id, metadata)
    VALUES (p_etiqueta_id, 'etiqueta_cancelada', p_motivo, v_uid, jsonb_build_object('motivo', p_motivo));

  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, reason)
    VALUES ('produto_etiqueta', p_etiqueta_id, 'LABEL_CANCELLED', v_uid, p_motivo);

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.c2_internal_order_entry_capability_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE uid uuid := auth.uid(); org uuid; r text; n integer; validated boolean; partners jsonb := '[]'::jsonb;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
  r := platform_private.c2_internal_order_target_reason(uid, NULL);
  IF r IS NULL THEN
    org := public.h15_actor_organization();
    -- Same issuer predicate as LIVE b2b_internal_order_snapshot_guard; read only, no lock.
    SELECT count(*), bool_and(c.configuration_status='VALIDATED' AND c.accounting_validated_at IS NOT NULL
             AND nullif(btrim(c.legal_name),'') IS NOT NULL AND nullif(btrim(c.cnpj),'') IS NOT NULL)
      INTO n, validated FROM public.company_fiscal_settings c WHERE c.organization_id=org AND c.is_active IS TRUE;
    IF n<>1 THEN r := 'issuer_ambiguous'; ELSIF validated IS NOT TRUE THEN r := 'issuer_not_validated'; END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object('partner_id',p.id,'razao_social',p.razao_social,
             'commercial_owner_organization_id',p.commercial_owner_organization_id) ORDER BY p.razao_social, p.id),'[]'::jsonb)
      INTO partners FROM public.partner_accounts p
     WHERE platform_private.c2_internal_order_target_reason(uid,p.id) IS NULL;
    IF r IS NULL AND jsonb_array_length(partners)=0 THEN r := 'no_partner_in_scope'; END IF;
    -- Same catalogue feature as the canonical reader (b2b_actor_scope.has_catalog / catalogo_precos).
    IF r IS NULL AND NOT EXISTS (SELECT 1 FROM platform_private.b2b_actor_scope(uid) x WHERE x.has_catalog IS TRUE) THEN r := 'catalog_feature_disabled'; END IF;
    -- Catalogue reader must be exactly the reviewed portfolio-aware body; any drift closes order entry.
    IF r IS NULL AND md5(pg_get_functiondef('public.get_partner_catalog_secure(uuid)'::regprocedure)) IS DISTINCT FROM 'b5684d350603d1db77ab9f1db0f4b253' THEN r := 'catalog_reader_pending'; END IF;
  END IF;
  RETURN jsonb_build_object('contract','C2_INTERNAL_ORDER_ENTRY_V1','organization_id',org,
    'profile_ok', r IS DISTINCT FROM 'inactive_scope' AND r IS DISTINCT FROM 'actor_not_allowed',
    'order_create', r IS NULL, 'reason', r,
    'partners', CASE WHEN org IS NULL THEN '[]'::jsonb ELSE partners END);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cc_archive_assignment(p_id uuid, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM 1 FROM public.commercial_payment_plan_assignments a WHERE a.id=p_id AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_publish(auth.uid()) THEN RAISE EXCEPTION 'not_authorized_publish'; END IF;
  IF p_motivo IS NULL OR length(btrim(p_motivo)) = 0 THEN RAISE EXCEPTION 'motivo_required'; END IF;
  UPDATE public.commercial_payment_plan_assignments
     SET status='archived', archived_by=auth.uid(), archived_at=now(), updated_by=auth.uid()
   WHERE id=p_id AND status <> 'archived';
  IF NOT FOUND THEN RAISE EXCEPTION 'invalid_transition'; END IF;
  PERFORM public.fn_cc_audit('assignment',p_id,'archive',NULL,NULL,p_motivo);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cc_bulk_adjust_apply(p_ids uuid[], p_percent numeric, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int; r record;
BEGIN
 IF p_ids IS NULL OR cardinality(p_ids)=0 OR EXISTS(SELECT 1 FROM unnest(p_ids) x(id) WHERE x.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i WHERE i.id=x.id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id))) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF p_motivo IS NULL OR length(btrim(p_motivo))=0 THEN RAISE EXCEPTION 'motivo_required'; END IF;
  PERFORM 1 FROM public.commercial_condition_item_prices i WHERE i.id=ANY(p_ids) AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id) ORDER BY i.id FOR UPDATE;
  IF p_ids IS NULL OR cardinality(p_ids)=0 OR EXISTS(SELECT 1 FROM unnest(p_ids) x(id) WHERE x.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i WHERE i.id=x.id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id))) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;

  UPDATE public.commercial_condition_item_prices i
     SET condition_price = CASE WHEN i.pricing_mode='fixed_item_price'
                                THEN round(i.condition_price*(1+p_percent/100.0),2) ELSE i.condition_price END,
         discount_percent = CASE WHEN i.pricing_mode='discount_from_base'
                                 THEN LEAST(100,GREATEST(0,round(i.discount_percent+p_percent,4))) ELSE i.discount_percent END,
         motivo = p_motivo, updated_by = auth.uid()
   WHERE i.id = ANY(p_ids) AND i.status IN ('draft','pending_approval');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  FOR r IN SELECT * FROM public.commercial_condition_item_prices WHERE id=ANY(p_ids) AND status IN ('draft','pending_approval') LOOP
    PERFORM public.fn_cc_audit('item_price',r.id,'bulk_adjust',NULL,to_jsonb(r),p_motivo);
  END LOOP;
  RETURN jsonb_build_object('updated', v_count);
END $function$

CREATE OR REPLACE FUNCTION platform_private.stock_p1_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_org uuid := public.h15_actor_organization();
 v_ref uuid;
 v_lote public.lotes%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND NOT platform_private.stock_p1_lote_owned(OLD.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 IF NOT platform_private.stock_p1_lote_owned(NEW.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_lote FROM public.lotes WHERE id=NEW.lote_id;
 -- Explicit lote ownership is required; parent references never assign ownership.
 IF v_lote.programacao_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.programacao_producao p
   WHERE p.id=v_lote.programacao_id AND p.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.envase_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.envase e WHERE e.id=NEW.envase_id
   AND e.lote_id=NEW.lote_id AND e.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_cliente_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.clientes c WHERE c.id=NEW.reservado_para_cliente_id AND c.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_partner_id IS NOT NULL AND NOT coalesce(public.b2b_phase1_partner_visible(NEW.reservado_para_partner_id,false),false) THEN
  RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF NEW.reservado_para_partner_order_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.partner_orders o WHERE o.id=NEW.reservado_para_partner_order_id
    AND o.partner_id=NEW.reservado_para_partner_id
    AND public.b2b_phase1_order_visible(o.id)
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_os_id IS NOT NULL THEN
  IF NEW.reservado_para_os_tipo IN ('onfarm','on_farm') THEN
   SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o
    JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.reservado_para_os_id;
  ELSIF NEW.reservado_para_os_tipo IN ('manual','b2b') THEN
   SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.reservado_para_os_id;
  ELSE
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF v_ref IS DISTINCT FROM v_org THEN
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_registrar_envase_v1(p_lote_id uuid, p_os_id uuid, p_origem text, p_programacao_id uuid, p_linhas jsonb, p_validade date, p_operador text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_permitir_parcial boolean DEFAULT false, p_motivo_parcial text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_ctx record;
  v_scope text;
  v_hash text;
  v_row record;
  v_produzido_ml numeric := 0; v_envasado_ml numeric := 0; v_saldo_ml numeric := 0;
  v_total_ml numeric := 0; v_demanda_ml numeric := 0; v_reservado_ml numeric := 0;
  v_pendente_ml numeric := 0;
  v_linha jsonb; v_tipo text; v_qtd integer; v_unit_ml numeric;
  v_reservadas integer; v_livres integer;
  v_envase_id uuid; v_estoque_id uuid;
  v_produto_id uuid; v_micro_id uuid; v_cq_ok boolean; v_lote_status text;
  v_lote_prog uuid;
  v_env_ct int := 0; v_est_ct int := 0; v_res_ml numeric := 0; v_liv_ml numeric := 0;
  v_avanco jsonb; v_result jsonb; v_estado text;
BEGIN
  PERFORM public.fn_estoque_ctx_open(jsonb_build_object('acao','entrada','origem','rpc_cockpit_registrar_envase_v1','usuario_id',auth.uid()::text));
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_lote_id IS NULL OR p_os_id IS NULL OR p_programacao_id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENVASE_PARAMS_INVALIDOS';
  END IF;
  IF p_validade IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENVASE_VALIDADE_OBRIGATORIA'; END IF;
  IF p_validade <= current_date THEN RAISE EXCEPTION 'COCKPIT_ENVASE_VALIDADE_INVALIDA'; END IF;
  IF p_linhas IS NULL OR jsonb_typeof(p_linhas) <> 'array' OR jsonb_array_length(p_linhas) = 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENVASE_SEM_LINHAS';
  END IF;

  -- idempotência: LOCK primeiro, leitura definitiva depois (claim atômico)
  IF nullif(btrim(coalesce(p_idempotency_key, '')), '') IS NOT NULL THEN
    v_scope := 'registrar_envase_v1:' || v_uid::text || ':' || btrim(p_idempotency_key);
    v_hash  := encode(extensions.digest(jsonb_build_object(
                 'lote', p_lote_id, 'os', p_os_id, 'origem', v_origem,
                 'prog', p_programacao_id, 'linhas', p_linhas,
                 'validade', p_validade, 'parcial', p_permitir_parcial)::text, 'sha256'), 'hex');
    PERFORM pg_advisory_xact_lock(hashtext(v_scope));

    SELECT * INTO v_row FROM public.cockpit_operacao_idempotencia
     WHERE idempotency_key = v_scope FOR UPDATE;

    IF v_row.idempotency_key IS NOT NULL THEN
      IF coalesce(v_row.payload_hash, '') <> v_hash THEN
        RAISE EXCEPTION 'COCKPIT_IDEMPOTENCY_CONFLICT';
      END IF;
      IF v_row.resultado IS NOT NULL THEN
        RETURN v_row.resultado || jsonb_build_object('replay', true);
      END IF;
      RAISE EXCEPTION 'COCKPIT_IDEMPOTENCY_IN_PROGRESS';
    END IF;

    INSERT INTO public.cockpit_operacao_idempotencia
      (idempotency_key, operacao, usuario_id, payload_hash, alvo_id, status)
    VALUES (v_scope, 'registrar_envase_v1', v_uid, v_hash, p_lote_id, 'in_progress');
  END IF;

  -- contexto canônico e coerência de vínculos
  SELECT * INTO v_ctx FROM public.fn_cockpit_ctx_programacao(p_programacao_id);
  IF v_ctx.os_id <> p_os_id THEN RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_PROGRAMACAO_OS'; END IF;
  IF v_ctx.origem <> v_origem THEN RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ORIGEM'; END IF;
  IF v_ctx.status_os IN ('cancelada','finalizada') THEN RAISE EXCEPTION 'COCKPIT_OS_ESTADO_TERMINAL'; END IF;
  PERFORM public.fn_cockpit_assert_b2b_liberado(v_ctx.partner_order_id);

  -- lock determinístico: programação e lote
  PERFORM 1 FROM public.programacao_producao WHERE id = p_programacao_id FOR UPDATE;

  SELECT coalesce(volume_produzido, 0), status::text, produto_id, microrganismo_id, programacao_id
    INTO v_produzido_ml, v_lote_status, v_produto_id, v_micro_id, v_lote_prog
    FROM public.lotes WHERE id = p_lote_id FOR UPDATE;

  IF v_lote_status IS NULL THEN RAISE EXCEPTION 'COCKPIT_LOTE_NAO_ENCONTRADO'; END IF;
  IF v_lote_prog IS DISTINCT FROM p_programacao_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_LOTE_PROGRAMACAO';
  END IF;
  IF (v_produto_id IS DISTINCT FROM v_ctx.produto_id)
     AND (v_micro_id IS DISTINCT FROM v_ctx.microrganismo_id) THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ITEM';
  END IF;
  IF v_lote_status = 'reprovado' THEN RAISE EXCEPTION 'COCKPIT_LOTE_REPROVADO_BLOQUEIA_ENVASE'; END IF;
  IF v_produzido_ml <= 0 THEN RAISE EXCEPTION 'COCKPIT_LOTE_SEM_VOLUME_PRODUZIDO'; END IF;

  SELECT (resultado::text = 'aprovado') INTO v_cq_ok
    FROM public.controle_qualidade WHERE lote_id = p_lote_id
   ORDER BY created_at DESC, seq DESC LIMIT 1;
  IF coalesce(v_cq_ok, false) IS NOT TRUE THEN RAISE EXCEPTION 'COCKPIT_ENVASE_EXIGE_CQ_APROVADO'; END IF;

  SELECT coalesce(sum(coalesce(volume_por_unidade,0) * coalesce(quantidade,0)), 0)
    INTO v_envasado_ml FROM public.envase WHERE lote_id = p_lote_id;
  v_saldo_ml := v_produzido_ml - v_envasado_ml;

  v_demanda_ml := coalesce(v_ctx.volume_necessario, 0);
  SELECT coalesce(sum(coalesce(volume_total,0)), 0) * 1000 INTO v_reservado_ml
    FROM public.estoque_produto
   WHERE reservado_para_os_id = p_os_id
     AND coalesce(reservado_para_os_tipo, v_origem) = v_origem
     AND status <> 'estornado'::public.status_estoque;
  v_pendente_ml := greatest(0, v_demanda_ml - v_reservado_ml);

  FOR v_linha IN SELECT * FROM jsonb_array_elements(p_linhas) LOOP
    v_tipo := v_linha->>'tipo_embalagem';
    IF (v_linha->>'quantidade') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'COCKPIT_QUANTIDADE_INVALIDA'; END IF;
    v_qtd := (v_linha->>'quantidade')::int;
    v_unit_ml := CASE v_tipo WHEN 'frasco_1L' THEN 1000 WHEN 'bombona_5L' THEN 5000
                             WHEN 'bombona_20L' THEN 20000 ELSE NULL END;
    IF v_unit_ml IS NULL THEN RAISE EXCEPTION 'COCKPIT_EMBALAGEM_INVALIDA'; END IF;
    IF v_qtd <= 0 THEN RAISE EXCEPTION 'COCKPIT_QUANTIDADE_INVALIDA'; END IF;
    v_total_ml := v_total_ml + (v_unit_ml * v_qtd);
  END LOOP;

  IF v_total_ml > v_saldo_ml THEN RAISE EXCEPTION 'COCKPIT_ENVASE_EXCEDE_PRODUZIDO'; END IF;

  FOR v_linha IN SELECT * FROM jsonb_array_elements(p_linhas) LOOP
    v_tipo := v_linha->>'tipo_embalagem';
    v_qtd  := (v_linha->>'quantidade')::int;
    v_unit_ml := CASE v_tipo WHEN 'frasco_1L' THEN 1000 WHEN 'bombona_5L' THEN 5000
                             WHEN 'bombona_20L' THEN 20000 END;

    INSERT INTO public.envase (lote_id, tipo_embalagem, volume_por_unidade, quantidade, data_envase, operador)
    VALUES (p_lote_id, v_tipo::public.tipo_embalagem, v_unit_ml, v_qtd, current_date, nullif(p_operador, ''))
    RETURNING id INTO v_envase_id;
    v_env_ct := v_env_ct + 1;

    v_reservadas := CASE WHEN v_pendente_ml > 0
                         THEN least(v_qtd, floor(v_pendente_ml / v_unit_ml)::int) ELSE 0 END;
    v_livres := v_qtd - v_reservadas;
    v_pendente_ml := v_pendente_ml - (v_reservadas * v_unit_ml);

    IF v_reservadas > 0 THEN
      INSERT INTO public.estoque_produto (
        produto_id, microrganismo_id, lote_id, envase_id, quantidade, volume_total,
        validade, status, reservado_para_os_id, reservado_para_os_tipo,
        reservado_para_cliente_id, reservado_para_partner_order_id,
        quantidade_reservada, reservado_por, reservado_em
      ) VALUES (
        v_produto_id, v_micro_id, p_lote_id, v_envase_id, v_reservadas,
        (v_unit_ml * v_reservadas) / 1000.0, p_validade, 'reservado'::public.status_estoque,
        p_os_id, v_origem, v_ctx.cliente_id, v_ctx.partner_order_id,
        v_reservadas, v_uid, now()
      ) RETURNING id INTO v_estoque_id;
      v_est_ct := v_est_ct + 1;
      v_res_ml := v_res_ml + (v_unit_ml * v_reservadas);

    END IF;

    IF v_livres > 0 THEN
      INSERT INTO public.estoque_produto (
        produto_id, microrganismo_id, lote_id, envase_id, quantidade, volume_total, validade, status
      ) VALUES (
        v_produto_id, v_micro_id, p_lote_id, v_envase_id, v_livres,
        (v_unit_ml * v_livres) / 1000.0, p_validade, 'disponivel'::public.status_estoque
      ) RETURNING id INTO v_estoque_id;
      v_est_ct := v_est_ct + 1;
      v_liv_ml := v_liv_ml + (v_unit_ml * v_livres);

    END IF;
  END LOOP;

  -- regra canônica de encerramento
  IF v_pendente_ml <= 0 THEN
    v_estado := 'completed';
  ELSIF p_permitir_parcial THEN
    IF NOT public.fn_cockpit_is_gestor() THEN RAISE EXCEPTION 'COCKPIT_ENVASE_PARCIAL_SEM_ALCADA'; END IF;
    IF nullif(btrim(coalesce(p_motivo_parcial, '')), '') IS NULL THEN
      RAISE EXCEPTION 'COCKPIT_ENVASE_PARCIAL_SEM_MOTIVO';
    END IF;
    v_estado := 'completed_override';
  ELSE
    v_estado := 'partial';
  END IF;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, programacao_id, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (p_os_id, v_origem, p_programacao_id, p_lote_id, 'em_envase',
          CASE WHEN v_estado = 'partial' THEN 'em_envase' ELSE 'estoque_gerado' END,
          'registrar_envase_v1', v_uid,
          format('Envase transacional [%s]: %s registros, %s entradas, reservado %s ml, livre %s ml, pendente %s ml. %s',
                 v_estado, v_env_ct, v_est_ct, v_res_ml, v_liv_ml, v_pendente_ml,
                 coalesce('Motivo: ' || nullif(btrim(coalesce(p_motivo_parcial, '')), ''), '')));

  IF v_estado <> 'partial' THEN
    v_avanco := public._rpc_avancar_esteira_laboratorio_internal(p_os_id, v_origem, 'concluir_envase', p_programacao_id);
  ELSE
    v_avanco := jsonb_build_object('success', false, 'motivo', 'COCKPIT_ENVASE_PARCIAL_NAO_AVANCA');
  END IF;

  v_result := jsonb_build_object(
    'success', true, 'replay', false, 'estado', v_estado,
    'envases', v_env_ct, 'entradas_estoque', v_est_ct,
    'volume_reservado_ml', v_res_ml, 'volume_livre_ml', v_liv_ml,
    'pendente_os_ml', v_pendente_ml, 'saldo_restante_ml', v_saldo_ml - v_total_ml,
    'avanco', v_avanco,
    'message', CASE WHEN v_estado = 'partial'
                    THEN 'Envase registrado — necessidade da OS ainda não coberta.'
                    ELSE 'Envase e estoque registrados em transação única.' END);

  IF v_scope IS NOT NULL THEN
    UPDATE public.cockpit_operacao_idempotencia
       SET resultado = v_result, status = 'done', updated_at = now()
     WHERE idempotency_key = v_scope;
  END IF;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.reservar_estoque_item(p_item_id uuid, p_qty numeric, p_os_id uuid, p_os_tipo text, p_cliente_id uuid DEFAULT NULL::uuid, p_partner_id uuid DEFAULT NULL::uuid, p_partner_order_id uuid DEFAULT NULL::uuid, p_observacao text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.estoque_produto%ROWTYPE;
  v_volume_reservado numeric;
  v_new_id uuid;
  v_parent_ctx jsonb;
BEGIN
  PERFORM platform_private.stock_motor_actor('reserva');
  IF p_qty IS NULL OR p_qty::text IN ('NaN','Infinity','-Infinity') OR p_qty <= 0 THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id,'partner_id',p_partner_id,'partner_order_id',p_partner_order_id));
  IF auth.uid() IS NULL OR NOT public.fn_estoque_pode_operar(auth.uid(), 'reserva') THEN
    RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO: perfil sem permissão para reservar estoque'
      USING ERRCODE = '42501';
  END IF;

  SELECT c.ctx INTO v_parent_ctx FROM platform_private.stock_motor_context c WHERE c.txid=txid_current() AND c.actor=auth.uid() AND c.item=p_item_id;
  IF v_parent_ctx IS NOT NULL AND (v_parent_ctx->>'acao' IS DISTINCT FROM 'reserva' OR v_parent_ctx->'reserve_args' IS DISTINCT FROM jsonb_strip_nulls(jsonb_build_object('os_id',p_os_id::text,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id::text,'partner_id',p_partner_id::text,'partner_order_id',p_partner_order_id::text,'observacao',p_observacao))) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  IF v_parent_ctx IS NULL THEN
   v_parent_ctx:=jsonb_build_object('acao','reserva','origem','reservar_estoque_item','usuario_id',auth.uid()::text,'metadata',jsonb_build_object('stock_request_item',p_item_id::text,'stock_request_actor',auth.uid()::text));
  END IF;
  PERFORM public.fn_estoque_ctx_force(v_parent_ctx);
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'Quantidade a reservar deve ser maior que zero.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_os_id IS NULL THEN
    RAISE EXCEPTION 'Reserva requer uma OS vinculada.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_item
  FROM public.estoque_produto
  WHERE id = p_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item de estoque % não encontrado.', p_item_id
      USING ERRCODE = 'no_data_found';
  END IF;

  PERFORM platform_private.stock_motor_item(p_item_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id,'partner_id',p_partner_id,'partner_order_id',p_partner_order_id));
  IF v_item.status::text <> 'disponivel' THEN
    RAISE EXCEPTION 'Item % não está disponível para reserva (status: %).', p_item_id, v_item.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_qty > COALESCE(v_item.quantidade, 0) THEN
    RAISE EXCEPTION 'Quantidade solicitada (%) excede o disponível (%) para esta embalagem.',
      p_qty, COALESCE(v_item.quantidade, 0)
      USING ERRCODE = 'check_violation';
  END IF;

  v_volume_reservado := CASE
    WHEN COALESCE(v_item.volume_total, 0) > 0 AND COALESCE(v_item.quantidade, 0) > 0
      THEN (p_qty * v_item.volume_total) / v_item.quantidade
    ELSE NULL
  END;

  IF p_qty = v_item.quantidade THEN
    UPDATE public.estoque_produto SET
      status = 'reservado',
      reservado_para_os_id = p_os_id,
      reservado_para_os_tipo = p_os_tipo,
      reservado_para_cliente_id = CASE WHEN p_os_tipo = 'b2b' THEN NULL ELSE p_cliente_id END,
      reservado_para_partner_id = CASE WHEN p_os_tipo = 'b2b' THEN p_partner_id ELSE NULL END,
      reservado_para_partner_order_id = CASE WHEN p_os_tipo = 'b2b' THEN p_partner_order_id ELSE NULL END,
      quantidade_reservada = p_qty,
      observacao_reserva = p_observacao
    WHERE id = p_item_id;
    v_new_id := p_item_id;
  ELSE
    INSERT INTO public.estoque_produto (
      produto_id, lote_id, microrganismo_id, envase_id,
      quantidade, volume_total, validade, status,
      reservado_para_os_id, reservado_para_os_tipo,
      reservado_para_cliente_id, reservado_para_partner_id, reservado_para_partner_order_id,
      quantidade_reservada, observacao_reserva
    ) VALUES (
      v_item.produto_id, v_item.lote_id, v_item.microrganismo_id, v_item.envase_id,
      p_qty, v_volume_reservado, v_item.validade, 'reservado',
      p_os_id, p_os_tipo,
      CASE WHEN p_os_tipo = 'b2b' THEN NULL ELSE p_cliente_id END,
      CASE WHEN p_os_tipo = 'b2b' THEN p_partner_id ELSE NULL END,
      CASE WHEN p_os_tipo = 'b2b' THEN p_partner_order_id ELSE NULL END,
      p_qty, p_observacao
    ) RETURNING id INTO v_new_id;

    UPDATE public.estoque_produto SET
      quantidade = v_item.quantidade - p_qty,
      volume_total = CASE
        WHEN COALESCE(v_item.volume_total, 0) > 0 THEN v_item.volume_total - v_volume_reservado
        ELSE volume_total
      END
    WHERE id = p_item_id;
  END IF;

  PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close();
  RETURN v_new_id;
EXCEPTION WHEN OTHERS THEN PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close(); RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_cc_publish_assignment(p_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM 1 FROM public.commercial_payment_plan_assignments a WHERE a.id=p_id AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_publish(auth.uid()) THEN RAISE EXCEPTION 'not_authorized_publish'; END IF;
  UPDATE public.commercial_payment_plan_assignments
     SET status='published', published_by=auth.uid(), published_at=now(), updated_by=auth.uid()
   WHERE id=p_id AND status IN ('draft','pending_approval');
  IF NOT FOUND THEN RAISE EXCEPTION 'invalid_transition'; END IF;
  PERFORM public.fn_cc_audit('assignment',p_id,'publish',NULL,NULL,p_motivo);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cc_submit_assignment(p_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM 1 FROM public.commercial_payment_plan_assignments a WHERE a.id=p_id AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  UPDATE public.commercial_payment_plan_assignments
     SET status='pending_approval', submitted_by=auth.uid(), submitted_at=now(), updated_by=auth.uid()
   WHERE id=p_id AND status='draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'invalid_transition'; END IF;
  PERFORM public.fn_cc_audit('assignment',p_id,'submit',NULL,NULL,p_motivo);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_rastreio_produto_interno(p_etiqueta_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.produto_etiquetas%ROWTYPE;
  v_lote jsonb; v_envase jsonb; v_cq jsonb; v_estoque jsonb; v_entrega jsonb; v_eventos jsonb;
  v_full boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;

  -- cliente_produtor jamais acessa rastreio interno completo
  IF public.has_role(v_uid,'cliente_produtor'::app_role)
     AND NOT (public.has_role(v_uid,'administrador'::app_role) OR public.has_role(v_uid,'gestor'::app_role)) THEN
    RAISE EXCEPTION 'Sem permissão para rastreio interno';
  END IF;

  IF NOT public.can_user_access_produto_etiqueta(p_etiqueta_id) THEN
    RAISE EXCEPTION 'Sem permissão para rastreio interno';
  END IF;

  SELECT * INTO v_row FROM public.produto_etiquetas WHERE id = p_etiqueta_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Etiqueta não encontrada'; END IF;

  v_full := public.has_role(v_uid,'administrador'::app_role)
         OR public.has_role(v_uid,'gestor'::app_role)
         OR public.has_role(v_uid,'producao'::app_role)
         OR public.has_role(v_uid,'operador_onfarm'::app_role)
         OR public.has_role(v_uid,'administrativo'::app_role);

  SELECT to_jsonb(l) INTO v_lote FROM public.lotes l WHERE l.id = v_row.lote_id;
  SELECT to_jsonb(e) INTO v_envase FROM public.envase e WHERE e.id = v_row.envase_id;
  SELECT to_jsonb(en) INTO v_entrega FROM public.entregas en WHERE en.id = v_row.entrega_id;
  SELECT jsonb_agg(to_jsonb(ev) ORDER BY ev.created_at DESC) INTO v_eventos
    FROM public.produto_etiqueta_eventos ev WHERE ev.etiqueta_id = p_etiqueta_id;

  IF v_full THEN
    SELECT jsonb_agg(to_jsonb(cq)) INTO v_cq FROM public.controle_qualidade cq WHERE cq.lote_id = v_row.lote_id;
    SELECT jsonb_agg(to_jsonb(ep)) INTO v_estoque FROM public.estoque_produto ep WHERE ep.lote_id = v_row.lote_id;
  ELSE
    v_cq := NULL;
    v_estoque := NULL;
  END IF;

  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id)
    VALUES (p_etiqueta_id, 'rastreio_visualizado', v_uid);

  RETURN jsonb_build_object(
    'etiqueta', to_jsonb(v_row),
    'lote', v_lote,
    'envase', v_envase,
    'controle_qualidade', v_cq,
    'estoque', v_estoque,
    'entrega', v_entrega,
    'eventos', v_eventos,
    'nivel', CASE WHEN v_full THEN 'completo' ELSE 'limitado' END
  );
END;
$function$

