CREATE OR REPLACE FUNCTION public.rpc_cc_upsert_assignment(p_id uuid, p_plan_id uuid, p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_valid_from date, p_valid_until date, p_motivo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_before jsonb;
BEGIN
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF NOT platform_private.c2p1_assignment_allowed(p_buyer_scope,p_partner_id,p_customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_id IS NULL THEN
    INSERT INTO public.commercial_payment_plan_assignments
      (plan_id,buyer_scope,partner_id,customer_id,valid_from,valid_until,motivo,created_by,updated_by)
    VALUES (p_plan_id,p_buyer_scope,p_partner_id,p_customer_id,
            COALESCE(p_valid_from,CURRENT_DATE),p_valid_until,p_motivo,auth.uid(),auth.uid())
    RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('assignment',v_id,'create',NULL,
      to_jsonb((SELECT a FROM public.commercial_payment_plan_assignments a WHERE a.id=v_id)),p_motivo);
  ELSE
    SELECT to_jsonb(a) INTO v_before FROM public.commercial_payment_plan_assignments a WHERE a.id=p_id AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id) FOR UPDATE;
    IF v_before IS NULL THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF (v_before->>'status') <> 'draft' THEN RAISE EXCEPTION 'assignment_not_editable'; END IF;
    UPDATE public.commercial_payment_plan_assignments
       SET plan_id=p_plan_id, buyer_scope=p_buyer_scope, partner_id=p_partner_id, customer_id=p_customer_id,
           valid_from=COALESCE(p_valid_from,valid_from), valid_until=p_valid_until,
           motivo=p_motivo, updated_by=auth.uid()
     WHERE id=p_id RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('assignment',v_id,'update',v_before,
      to_jsonb((SELECT a FROM public.commercial_payment_plan_assignments a WHERE a.id=v_id)),p_motivo);
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.fn_generate_receivable_installments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  i int;
  v_context platform_private.financial_initial_installments;
  v_inst jsonb;
  v_qtd int := NEW.installment_count;
  v_base numeric(14,2) := ROUND(NEW.total_amount / v_qtd, 2);
  v_acc numeric(14,2) := 0;
  v_amt numeric(14,2);
BEGIN
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;
  DELETE FROM platform_private.financial_initial_installments
    WHERE transaction_id=txid_current() AND title_id=NEW.id AND kind='receivable'
    RETURNING * INTO v_context;
  IF FOUND THEN
    IF v_context.actor_id IS DISTINCT FROM auth.uid() OR v_context.organization_id IS DISTINCT FROM NEW.organization_id
       OR NEW.created_by IS DISTINCT FROM v_context.actor_id OR NEW.origin_type <> 'MANUAL'
       OR platform_private.h15_actor_organization() IS DISTINCT FROM NEW.organization_id
       OR NOT public.is_financial_staff(auth.uid()) THEN
      RAISE EXCEPTION 'FIN_INITIAL_CONTEXT_DENIED' USING ERRCODE='42501';
    END IF;
    IF jsonb_array_length(v_context.installments) <> NEW.installment_count
       OR (SELECT sum((x->>'amount')::numeric) FROM jsonb_array_elements(v_context.installments) x) IS DISTINCT FROM NEW.total_amount THEN
      RAISE EXCEPTION 'FIN_TITLE_INVALID_SUM' USING ERRCODE='23514';
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_context.installments) LOOP
      INSERT INTO public.accounts_receivable_installments(organization_id,receivable_id,installment_number,due_date,original_amount,net_amount,status)
        VALUES(NEW.organization_id,NEW.id,(v_inst->>'installment_number')::int,(v_inst->>'due_date')::date,
          (v_inst->>'amount')::numeric,(v_inst->>'amount')::numeric,'OPEN');
    END LOOP;
    RETURN NEW;
  END IF;
  IF NEW.origin_type='B2B_ORDER' AND EXISTS(SELECT 1 FROM public.partner_orders o WHERE o.id=NEW.origin_id AND o.c2_external_origin_snapshot IS NOT NULL) THEN
    INSERT INTO public.accounts_receivable_installments(receivable_id,installment_number,due_date,original_amount,net_amount,status,organization_id,interest_amount)
    SELECT NEW.id,s.installment_number,s.due_date,s.amount,s.amount,'OPEN',NEW.organization_id,s.interest_amount
    FROM public.partner_order_payment_schedule s JOIN public.partner_orders o ON o.id=s.partner_order_id AND o.payment_terms_id=s.payment_terms_id
    WHERE o.id=NEW.origin_id ORDER BY s.installment_number;
    IF (SELECT count(*) FROM public.accounts_receivable_installments WHERE receivable_id=NEW.id)<>v_qtd THEN RAISE EXCEPTION 'B2B_INSTALLMENT_CARDINALITY_INVALID' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  FOR i IN 1..v_qtd LOOP
    IF i < v_qtd THEN
      v_amt := v_base;
      v_acc := v_acc + v_amt;
    ELSE
      v_amt := NEW.total_amount - v_acc;
    END IF;
    INSERT INTO public.accounts_receivable_installments
      (receivable_id, installment_number, due_date, original_amount, net_amount, status, organization_id)
    VALUES
      (NEW.id, i, (NEW.first_due_date + ((i-1) || ' months')::interval)::date, v_amt, v_amt, 'OPEN', NEW.organization_id);
  END LOOP;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION platform_private.stock_p1_movement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_org uuid:=public.h15_actor_organization(); v_lote uuid; v_ref uuid;
BEGIN
IF auth.uid() IS NULL OR v_org IS NULL THEN RAISE EXCEPTION 'ESTQ_MOV_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
SELECT e.lote_id INTO v_lote FROM public.estoque_produto e WHERE e.id=NEW.estoque_produto_id;
IF v_lote IS NULL OR NOT platform_private.stock_p1_lote_owned(v_lote) THEN RAISE EXCEPTION 'ESTQ_MOV_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
-- Only a new ledger row may inherit its verified stock's lote, never organization or legacy backfill.
IF NEW.lote_id IS NULL THEN NEW.lote_id:=v_lote; END IF;
IF NEW.lote_id IS DISTINCT FROM v_lote THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.cliente_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=NEW.cliente_id AND c.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.os_id IS NOT NULL THEN
 IF NEW.os_tipo IN ('manual','b2b') THEN SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.os_id;
 ELSIF NEW.os_tipo IN ('onfarm','on_farm') THEN SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.os_id;
 ELSE RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_ref IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
END IF;
IF NEW.movimentacao_origem_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes m WHERE m.id=NEW.movimentacao_origem_id AND m.estoque_produto_id=NEW.estoque_produto_id AND m.lote_id=NEW.lote_id) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.referencia_id IS NOT NULL THEN
 IF NEW.referencia_tipo='entrega' THEN
  IF NOT EXISTS(SELECT 1 FROM public.entregas e WHERE e.id=NEW.referencia_id AND e.organization_id=v_org AND (e.lote_id IS NULL OR e.lote_id=NEW.lote_id) AND (NEW.cliente_id IS NULL OR e.cliente_id=NEW.cliente_id)) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSIF NEW.referencia_tipo IN ('estoque','estoque_produto') THEN
  IF NEW.referencia_id IS DISTINCT FROM NEW.estoque_produto_id THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSIF NEW.referencia_tipo IN ('os','ordem_servico') THEN
  IF NEW.os_id IS NULL OR NEW.referencia_id IS DISTINCT FROM NEW.os_id THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSE RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
END IF;
RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_lane_source_reason(p_source uuid, p_cliente uuid, p_org uuid, p_recipient uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s record; c record;
BEGIN
 SELECT id,cliente_id,consultor_atribuido,status::text AS status INTO s FROM public.portal_solicitacoes WHERE id=p_source;
 IF NOT FOUND THEN RETURN 'source_missing'; END IF;
 IF s.cliente_id IS DISTINCT FROM p_cliente THEN RETURN 'source_client_changed'; END IF;
 IF s.consultor_atribuido IS NULL THEN RETURN 'source_unassigned'; END IF;
 IF s.consultor_atribuido IS DISTINCT FROM p_recipient THEN RETURN 'source_reassigned'; END IF;
 IF s.status IS NULL OR s.status NOT IN ('pendente','atribuida') THEN RETURN 'source_state_ineligible'; END IF;
 SELECT organization_id,status_cliente::text AS st INTO c FROM public.clientes WHERE id=p_cliente;
 IF NOT FOUND OR c.organization_id IS DISTINCT FROM p_org THEN RETURN 'client_tenant_changed'; END IF;
 IF c.st IS DISTINCT FROM 'ativo' THEN RETURN 'client_ineligible'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p_recipient AND uc.cliente_id=p_cliente
  AND uc.is_active IS TRUE AND uc.revoked_at IS NULL AND (uc.valid_from IS NULL OR uc.valid_from<=now())
  AND (uc.valid_until IS NULL OR uc.valid_until>=now()) AND uc.access_level::text IN ('read','execute','manage')) THEN RETURN 'recipient_portfolio_revoked'; END IF;
 IF platform_private.tenant_smtp_lane_recipient(p_org,p_recipient) IS NULL THEN RETURN 'recipient_unproven'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_cancelar_reserva_v1(p_item_id uuid, p_os_id uuid, p_origem text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_item public.estoque_produto%ROWTYPE;
  v_main public.estoque_produto%ROWTYPE;
  v_modo text;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
BEGIN
  PERFORM public.fn_estoque_ctx_open(jsonb_build_object('acao','cancelamento_reserva','origem','rpc_cockpit_cancelar_reserva_v1','usuario_id',auth.uid()::text));
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_item_id IS NULL OR p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_PARAMS_INVALIDOS'; END IF;
  IF v_motivo IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_MOTIVO_OBRIGATORIO'; END IF;

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_reserva:' || p_item_id::text));

  SELECT * INTO v_item FROM public.estoque_produto WHERE id = p_item_id FOR UPDATE;
  IF v_item.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_NAO_ENCONTRADA'; END IF;

  IF v_item.status::text = 'estornado' OR v_item.quantidade_reservada IS NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true,
      'message', 'Reserva já cancelada anteriormente.');
  END IF;
  IF v_item.status::text = 'expedido' THEN RAISE EXCEPTION 'COCKPIT_RESERVA_JA_EXPEDIDA'; END IF;

  -- coerência: a reserva precisa pertencer à MESMA OS/origem
  IF v_item.reservado_para_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_RESERVA_OS';
  END IF;
  IF coalesce(v_item.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_RESERVA_ORIGEM';
  END IF;

  -- override (cancelar reserva feita por outro operador) exige gestor
  IF v_item.reservado_por IS DISTINCT FROM v_uid AND NOT public.fn_cockpit_is_gestor() THEN
    RAISE EXCEPTION 'COCKPIT_RESERVA_OVERRIDE_SEM_ALCADA';
  END IF;

  -- saldo principal compatível (mesmo lote, envase, item e validade)
  SELECT * INTO v_main
    FROM public.estoque_produto
   WHERE lote_id = v_item.lote_id
     AND envase_id IS NOT DISTINCT FROM v_item.envase_id
     AND produto_id IS NOT DISTINCT FROM v_item.produto_id
     AND microrganismo_id IS NOT DISTINCT FROM v_item.microrganismo_id
     AND validade IS NOT DISTINCT FROM v_item.validade
     AND quantidade_reservada IS NULL
     AND status = 'disponivel'::public.status_estoque
     AND id <> v_item.id
   ORDER BY id LIMIT 1 FOR UPDATE;

  IF v_main.id IS NOT NULL THEN
    v_modo := 'estorno_para_saldo_principal';
    UPDATE public.estoque_produto
       SET quantidade = coalesce(v_main.quantidade,0) + coalesce(v_item.quantidade,0),
           volume_total = coalesce(v_main.volume_total,0) + coalesce(v_item.volume_total,0),
           updated_at = now()
     WHERE id = v_main.id;

    UPDATE public.estoque_produto
       SET status = 'estornado'::public.status_estoque, quantidade = 0, volume_total = 0,
           quantidade_reservada = 0, reservado_para_os_id = NULL, reservado_para_os_tipo = NULL,
           reservado_para_cliente_id = NULL, reservado_para_partner_id = NULL,
           reservado_para_partner_order_id = NULL,
           observacao_reserva = v_motivo || format(' — saldo devolvido ao registro %s', v_main.id),
           updated_at = now()
     WHERE id = v_item.id;

  ELSE
    v_modo := 'liberacao_no_proprio_registro';
    UPDATE public.estoque_produto
       SET status = 'disponivel'::public.status_estoque, quantidade_reservada = NULL,
           reservado_para_os_id = NULL, reservado_para_os_tipo = NULL,
           reservado_para_cliente_id = NULL, reservado_para_partner_id = NULL,
           reservado_para_partner_order_id = NULL,
           observacao_reserva = v_motivo, updated_at = now()
     WHERE id = v_item.id;

  END IF;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (p_os_id, v_origem, v_item.lote_id, 'estoque_reservado', 'estoque_disponivel',
          'cancelar_reserva_v1', v_uid, format('Cancelamento transacional (%s). Motivo: %s', v_modo, v_motivo));

  RETURN jsonb_build_object('success', true, 'replay', false, 'modo', v_modo,
    'message', 'Reserva cancelada e saldo devolvido em transação única.');
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_coletar_assinatura_digital_entrega(p_entrega_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
  v_comp_id uuid;
  v_rec_nome text := nullif(trim(coalesce(p_payload->>'recebedor_nome','')), '');
  v_hash text := nullif(p_payload->>'assinatura_hash','');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão inválida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  SELECT * INTO v_entrega FROM public.entregas WHERE id = p_entrega_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada'; END IF;
  IF v_entrega.status = 'cancelada' THEN RAISE EXCEPTION 'Entrega cancelada'; END IF;
  IF v_rec_nome IS NULL THEN RAISE EXCEPTION 'recebedor_nome é obrigatório'; END IF;
  IF v_hash IS NULL THEN RAISE EXCEPTION 'assinatura_hash é obrigatório'; END IF;

  v_comp_id := v_entrega.comprovante_id;
  IF v_comp_id IS NULL THEN
    PERFORM public.rpc_gerar_formulario_entrega(p_entrega_id);
    SELECT comprovante_id INTO v_comp_id FROM public.entregas WHERE id = p_entrega_id;
  END IF;

  UPDATE public.entrega_comprovantes SET
    status = 'assinatura_digital_coletada',
    assinatura_coletada = true,
    assinatura_tipo = 'digital_tela',
    assinatura_digital_png_path = nullif(p_payload->>'assinatura_digital_png_path',''),
    assinatura_digital_svg = nullif(p_payload->>'assinatura_digital_svg',''),
    assinatura_hash = v_hash,
    assinatura_ip = nullif(p_payload->>'assinatura_ip',''),
    assinatura_user_agent = nullif(p_payload->>'assinatura_user_agent',''),
    assinatura_capturada_em = now(),
    recebedor_nome = v_rec_nome,
    recebedor_documento = nullif(p_payload->>'recebedor_documento',''),
    recebedor_cargo = nullif(p_payload->>'recebedor_cargo',''),
    recebedor_telefone = nullif(p_payload->>'recebedor_telefone',''),
    data_assinatura = now(),
    validation_hash = encode(extensions.digest(p_entrega_id::text || v_hash || now()::text, 'sha256'), 'hex'),
    updated_at = now()
  WHERE id = v_comp_id;

  UPDATE public.entregas SET
    comprovante_status = 'assinatura_digital_coletada',
    assinatura_tipo = 'digital_tela',
    recebedor_nome = v_rec_nome,
    recebedor_documento = coalesce(nullif(p_payload->>'recebedor_documento',''), recebedor_documento),
    recebedor_cargo = coalesce(nullif(p_payload->>'recebedor_cargo',''), recebedor_cargo),
    recebedor_telefone = coalesce(nullif(p_payload->>'recebedor_telefone',''), recebedor_telefone),
    assinatura_digital_capturada_em = now(),
    assinatura_digital_capturada_por = v_uid,
    updated_at = now()
  WHERE id = p_entrega_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', p_entrega_id, 'DELIVERY_DIGITAL_SIGNATURE_CAPTURED',
          jsonb_build_object('comprovante_id', v_comp_id, 'hash', v_hash), v_uid);

  RETURN jsonb_build_object('success', true, 'comprovante_id', v_comp_id);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_confirmar_entrega_v1(p_entrega_id uuid, p_os_id uuid, p_origem text, p_recebedor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS'; END IF;
  IF coalesce(btrim(p_recebedor->>'nome'), '') = '' THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_RECEBEDOR_OBRIGATORIO';
  END IF;
  RETURN public.fn_entrega_confirmar_engine_v1(p_entrega_id, p_os_id, p_origem, p_recebedor, '{}'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_criar_entrega_v1(p_os_id uuid, p_origem text, p_estoque_produto_id uuid, p_quantidade numeric, p_dados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_est public.estoque_produto%ROWTYPE;
  v_existente record;
  v_id uuid;
  v_cliente_os uuid;
BEGIN
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_os_id IS NULL OR p_estoque_produto_id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS';
  END IF;
  IF coalesce(p_quantidade, 0) <= 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_INVALIDA';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_criar_entrega:' || p_os_id::text || ':' || p_estoque_produto_id::text));

  SELECT * INTO v_est
  FROM public.estoque_produto
  WHERE id = p_estoque_produto_id
  FOR UPDATE;

  IF v_est.id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_ESTOQUE_NAO_ENCONTRADO';
  END IF;

  IF v_origem = 'onfarm' THEN
    SELECT cliente_id INTO v_cliente_os
    FROM public.ordens_servico_onfarm
    WHERE id = p_os_id;
  ELSE
    SELECT cliente_id INTO v_cliente_os
    FROM public.ordens_servico
    WHERE id = p_os_id;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_OS_NAO_ENCONTRADA';
  END IF;

  IF v_est.status::text NOT IN ('reservado', 'expedido') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_STATUS_ESTOQUE_INVALIDO';
  END IF;
  IF v_est.reservado_para_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ESTOQUE';
  END IF;
  IF coalesce(v_est.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ORIGEM';
  END IF;
  IF p_quantidade > coalesce(v_est.quantidade, 0) THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_EXCEDE_RESERVA';
  END IF;
  IF v_est.reservado_para_cliente_id IS NOT NULL
     AND v_est.reservado_para_cliente_id IS DISTINCT FROM v_cliente_os THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_CLIENTE';
  END IF;
  IF nullif(p_dados->>'cliente_id','') IS NOT NULL
     AND nullif(p_dados->>'cliente_id','')::uuid IS DISTINCT FROM v_cliente_os THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_CLIENTE';
  END IF;

  SELECT e.id, e.status::text AS status INTO v_existente
  FROM public.entregas e
  WHERE e.estoque_produto_id = p_estoque_produto_id
    AND e.status::text <> 'cancelada'
    AND (
      (v_origem = 'onfarm' AND e.ordem_servico_onfarm_id = p_os_id)
      OR (v_origem <> 'onfarm' AND e.ordem_servico_id = p_os_id)
    )
  ORDER BY e.created_at DESC
  LIMIT 1;

  IF v_existente.id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'entrega_id', v_existente.id, 'status', v_existente.status, 'message', 'Entrega ja registrada para este item da OS.');
  END IF;


  IF coalesce(nullif(p_dados->>'tipo_entrega',''), 'motorista') NOT IN ('motorista','retirada') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_MODALIDADE_INVALIDA';
  END IF;
  IF coalesce(nullif(p_dados->>'endereco_origem',''), 'cadastro') NOT IN ('cadastro','personalizado') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_ENDERECO_ORIGEM_INVALIDA';
  END IF;
  IF v_est.volume_total IS NULL OR v_est.volume_total <= 0 OR v_est.volume_total::text IN ('NaN','Infinity','-Infinity')
     OR v_est.quantidade IS NULL OR v_est.quantidade <= 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_VOLUME_ESTOQUE_INVALIDO';
  END IF;

  INSERT INTO public.entregas (
    ordem_servico_id, ordem_servico_onfarm_id, estoque_produto_id,
    lote_id, produto_id, quantidade_entregue, status, cliente_id,
    data_saida, motorista, veiculo
  ) VALUES (
    CASE WHEN v_origem = 'onfarm' THEN NULL ELSE p_os_id END,
    CASE WHEN v_origem = 'onfarm' THEN p_os_id ELSE NULL END,
    p_estoque_produto_id,
    v_est.lote_id,
    v_est.produto_id,
    p_quantidade,
    'separado'::public.status_entrega,
    v_cliente_os,
    nullif(p_dados->>'data_saida','')::date,
    nullif(p_dados->>'motorista',''),
    nullif(p_dados->>'veiculo','')
  ) RETURNING id INTO v_id;


  -- Only newly created delivery: preserve replay semantics and never overwrite existing history.
  UPDATE public.entregas SET
    volume_entregue_ml = round((v_est.volume_total / v_est.quantidade) * p_quantidade * 1000, 6),
    tipo_entrega = coalesce(nullif(p_dados->>'tipo_entrega',''), 'motorista'),
    endereco_origem = coalesce(nullif(p_dados->>'endereco_origem',''), 'cadastro'),
    grupo_entrega_id = nullif(p_dados->>'grupo_entrega_id','')::uuid,
    hora_saida_prevista = nullif(p_dados->>'hora_saida_prevista','')::time,
    data_chegada_prevista = nullif(p_dados->>'data_chegada_prevista','')::date,
    hora_chegada_prevista = nullif(p_dados->>'hora_chegada_prevista','')::time,
    motorista_telefone = nullif(p_dados->>'motorista_telefone',''),
    motorista_documento = nullif(p_dados->>'motorista_documento',''),
    veiculo_placa = nullif(p_dados->>'veiculo_placa',''),
    veiculo_tipo = nullif(p_dados->>'veiculo_tipo',''),
    destinatario_nome = nullif(p_dados->>'destinatario_nome',''),
    destinatario_telefone = nullif(p_dados->>'destinatario_telefone',''),
    destinatario_whatsapp = nullif(p_dados->>'destinatario_whatsapp',''),
    endereco_logradouro = nullif(p_dados->>'endereco_logradouro',''),
    endereco_numero = nullif(p_dados->>'endereco_numero',''),
    endereco_complemento = nullif(p_dados->>'endereco_complemento',''),
    endereco_bairro = nullif(p_dados->>'endereco_bairro',''),
    endereco_cidade = nullif(p_dados->>'endereco_cidade',''),
    endereco_uf = nullif(p_dados->>'endereco_uf',''),
    endereco_cep = nullif(p_dados->>'endereco_cep',''),
    endereco_referencia = nullif(p_dados->>'endereco_referencia','')
  WHERE id = v_id;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, etapa_nova, acao, usuario_id, observacao)
  VALUES
    (p_os_id, v_origem, 'entrega_criada', 'criar_entrega_v1', v_uid,
     format('Entrega %s criada (motor transacional).', v_id));

  RETURN jsonb_build_object('success', true, 'replay', false, 'entrega_id', v_id, 'status', 'separado', 'message', 'Entrega registrada. Confirme a entrega para concluir a OS.');
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_lane_cancel_queued(p_org uuid, p_reason text, p_actor uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j platform_private.tenant_smtp_dispatch_jobs; n int:=0;
BEGIN
 FOR j IN SELECT * FROM platform_private.tenant_smtp_dispatch_jobs WHERE organization_id=p_org AND state='queued' FOR UPDATE LOOP
  PERFORM platform_private.tenant_smtp_lane_cancel(j,p_reason,p_actor); n:=n+1;
 END LOOP;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_f4_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; s public.communication_tenant_email_settings; c platform_private.tenant_smtp_sender_challenges; v_verified boolean; v_active boolean;
BEGIN
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org;
 v_verified:=platform_private.tenant_smtp_f4_verified(v_org);
 v_active:=EXISTS(SELECT 1 FROM platform_private.tenant_smtp_activation a WHERE a.organization_id=v_org AND a.active AND a.version=s.version);
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND actor_id=auth.uid() AND version=s.version ORDER BY created_at DESC LIMIT 1;
 RETURN jsonb_build_object('version',coalesce(s.version,0),'sender_verified',v_verified,
  'active',v_active,'dispatch_enabled',coalesce(platform_private.tenant_smtp_lane_ready(v_org),false)
   AND EXISTS(SELECT 1 FROM platform_private.tenant_smtp_lane_heartbeat WHERE id AND seen_at>clock_timestamp()-interval '10 minutes'),
  'challenge',CASE WHEN c.id IS NULL THEN NULL ELSE jsonb_build_object('id',c.id,
   'state',CASE WHEN c.state IN ('sent','ambiguous') AND c.expires_at<clock_timestamp() THEN 'expired' ELSE c.state END,
   'expires_at',c.expires_at,'attempts_left',5-c.attempts) END);
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_external_origin_assert(s jsonb, partner uuid, client uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE uid uuid:=auth.uid(); org uuid; p public.partner_accounts;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.partner_accounts WHERE id=partner FOR SHARE;
 org:=p.commercial_owner_organization_id;
 IF NOT FOUND OR p.ativo IS NOT TRUE OR p.deleted_at IS NOT NULL OR org IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=org AND o.ativo AND o.status='ativa')
 OR EXISTS(SELECT 1 FROM public.organizations o WHERE o.partner_account_id=partner)
 OR NOT platform_private.c2_external_origin_contract_valid(s)
 OR s->>'organization_id' IS DISTINCT FROM org::text OR s->>'partner_id' IS DISTINCT FROM partner::text
 THEN RAISE EXCEPTION 'C2_EXTERNAL_ORIGIN_DENIED' USING ERRCODE='42501'; END IF;
 IF client IS DISTINCT FROM p.client_id OR (client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=client AND c.organization_id=org))
 THEN RAISE EXCEPTION 'C2_EXTERNAL_CLIENT_DENIED' USING ERRCODE='42501'; END IF;
 -- Initial writes are authorized only inside the existing canonical create transaction.
 -- Subsequent administration uses P1's active internal owner authority, never buyer roles.
 IF platform_private.has_ticket('c2_external_order_create',partner) THEN
  IF s->>'actor_user_id' IS DISTINCT FROM uid::text OR NOT platform_private.c2_owner_order_create_allowed(uid,partner)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_CREATE_DENIED' USING ERRCODE='42501'; END IF;
  ELSE
  IF public.h15_actor_organization() IS DISTINCT FROM org OR NOT platform_private.c2p1_settings_allowed(partner,true)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_OWNER_DENIED' USING ERRCODE='42501'; END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_gerar_lote_v1(p_programacao_id uuid, p_os_id uuid, p_origem text, p_lote jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_uid uuid:=auth.uid(); v_org uuid; v_origin text; v_os record;
 v_pp public.programacao_producao%ROWTYPE; v_lot public.lotes%ROWTYPE;
 v_key text; v_count integer; v_id uuid; v_codigo text; v_volume numeric;
 v_tanque text; v_resp text; v_obs text; v_try integer:=0; v_constraint text;
BEGIN
 PERFORM pg_catalog.set_config('lock_timeout','3s',true);
 -- Cadeia viva (Auth/JWT iat, perfil ativo, empresa ativa, readiness, SaaS, papel) ANTES de qualquer leitura.
 -- Não reutiliza fn_cockpit_assert_operador_origem: ele só testa papel global.
 v_org:=platform_private.h15_actor_organization();
 IF v_uid IS NULL OR v_org IS NULL OR public.technical_actor_ready(v_uid) IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 BEGIN v_origin:=public.fn_cockpit_norm_origem(p_origem); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END;
 IF v_origin<>'manual' THEN RETURN jsonb_build_object('success',false,'message','Somente OS manual neste recorte.'); END IF;
 IF p_programacao_id IS NULL OR p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_LOTE_PARAMS_INVALIDOS'; END IF;
 IF p_lote IS NULL OR jsonb_typeof(p_lote)<>'object' THEN RAISE EXCEPTION 'COCKPIT_LOTE_PAYLOAD_INVALIDO'; END IF;
 -- Lista fechada: código, produto, microrganismo, tenant, custo e data nunca vêm do navegador.
 FOR v_key IN SELECT pg_catalog.jsonb_object_keys(p_lote) LOOP
  IF v_key='codigo_lote' THEN RAISE EXCEPTION 'COCKPIT_LOTE_CODIGO_NAO_ACEITO'; END IF;
  IF v_key NOT IN ('volume_produzido','responsavel_producao','tanque','observacoes_tecnicas') THEN RAISE EXCEPTION 'COCKPIT_LOTE_PAYLOAD_INVALIDO'; END IF;
 END LOOP;
 -- Volume em mL (mesma unidade de programacao_producao.volume_necessario e ordens_servico.volume_total_ml).
 IF pg_catalog.jsonb_typeof(p_lote->'volume_produzido') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'COCKPIT_LOTE_VOLUME_INVALIDO'; END IF;
 v_volume:=(p_lote->>'volume_produzido')::numeric;
 IF NOT (v_volume>0 AND v_volume<=100000000 AND v_volume=pg_catalog.round(v_volume,3) AND v_volume::text NOT IN ('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'COCKPIT_LOTE_VOLUME_INVALIDO'; END IF;
 FOREACH v_key IN ARRAY ARRAY['responsavel_producao','tanque','observacoes_tecnicas'] LOOP
  IF pg_catalog.jsonb_typeof(p_lote->v_key) NOT IN ('string','null') THEN RAISE EXCEPTION 'COCKPIT_LOTE_PAYLOAD_INVALIDO'; END IF;
 END LOOP;
 v_resp:=nullif(pg_catalog.btrim(p_lote->>'responsavel_producao'),'');
 v_tanque:=nullif(pg_catalog.btrim(p_lote->>'tanque'),'');
 v_obs:=nullif(pg_catalog.btrim(p_lote->>'observacoes_tecnicas'),'');
 IF pg_catalog.length(v_resp)>200 OR pg_catalog.length(v_tanque)>60 OR pg_catalog.length(v_obs)>2000 THEN RAISE EXCEPTION 'COCKPIT_LOTE_PAYLOAD_INVALIDO'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os='manual') THEN RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'COCKPIT_LOTE_ISOLATION_DENIED' USING ERRCODE='42501'; END IF;
 -- Mesmo conjunto de cercas revisado em rpc_programar_os_v1 (convites/onfarm/catálogo SaaS global).
 LOCK TABLE public.platform_org_admin_invites,public.ordens_servico_onfarm IN SHARE MODE;
 LOCK TABLE public.saas_plan_versions,public.saas_plan_version_features,public.saas_features,public.saas_modules IN SHARE MODE;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('cockpit_lote:'||p_programacao_id::text));
 SELECT o.organization_id,o.id,o.cliente_id,o.fazenda_id,o.talhao_id,o.produto_id,o.microrganismo_id,o.status::text status,o.partner_order_id,o.partner_order_item_id,o.origem
 INTO v_os FROM public.ordens_servico o WHERE o.id=p_os_id FOR UPDATE;
 IF v_os.id IS NULL OR v_os.organization_id IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=v_uid ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=v_uid ORDER BY role::text FOR SHARE;
 PERFORM 1 FROM public.organizations WHERE id=v_org FOR UPDATE;
 PERFORM 1 FROM public.organization_subscriptions WHERE organization_id=v_org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.organization_feature_overrides WHERE organization_id=v_org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.clientes WHERE id=v_os.cliente_id FOR SHARE;
 PERFORM 1 FROM public.fazendas WHERE id=v_os.fazenda_id FOR SHARE;
 PERFORM 1 FROM public.talhoes WHERE id=v_os.talhao_id FOR SHARE;
 PERFORM 1 FROM public.produtos WHERE id=v_os.produto_id FOR SHARE;
 PERFORM 1 FROM public.microrganismos WHERE id=v_os.microrganismo_id FOR SHARE;
 PERFORM 1 FROM public.programacao_producao WHERE id=p_programacao_id OR ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.lotes WHERE programacao_id=p_programacao_id ORDER BY id FOR UPDATE;
 -- Revalidação após locks: revogação/troca de tenant/assinatura concorrente vence a requisição.
 IF public.technical_actor_ready(v_uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE OR public._saas_user_has_feature(v_uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os='manual') THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=v_os.cliente_id AND c.organization_id=v_org)
 OR EXISTS(SELECT 1 FROM public.ordens_servico_onfarm WHERE id=p_os_id) THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF v_os.origem='b2b' OR v_os.partner_order_id IS NOT NULL OR v_os.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id) THEN
 RETURN jsonb_build_object('success',false,'message','Lote B2B indisponível até validação dos efeitos associados.'); END IF;
 SELECT count(*) INTO v_count FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id;
 IF v_count<>1 THEN RETURN jsonb_build_object('success',false,'message','Programação existente não comprovada; revisão necessária.'); END IF;
 SELECT * INTO v_pp FROM public.programacao_producao WHERE id=p_programacao_id;
 -- IDs divergentes, programação de outra OS ou de outro tenant: mesma negação, sem revelar existência.
 IF NOT ((v_pp.id IS NOT NULL AND v_pp.organization_id=v_org AND v_pp.ordem_servico_id=p_os_id AND v_pp.ordem_servico_onfarm_id IS NULL
 AND v_pp.produto_id IS NOT DISTINCT FROM v_os.produto_id AND v_pp.microrganismo_id IS NOT DISTINCT FROM v_os.microrganismo_id) IS TRUE) THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF ((v_pp.produto_id IS NOT NULL)::int+(v_pp.microrganismo_id IS NOT NULL)::int)<>1 THEN RAISE EXCEPTION 'COCKPIT_LOTE_ITEM_CANONICO_AUSENTE'; END IF;
 IF platform_private.lab_item_is_manufacturable(v_pp.produto_id,v_pp.microrganismo_id) IS NOT TRUE THEN
 RETURN jsonb_build_object('success',false,'message','Item não elegível ao laboratório biológico.'); END IF;
 IF v_pp.responsavel_id IS NOT NULL OR nullif(pg_catalog.btrim(v_pp.responsavel),'') IS NOT NULL THEN
 RETURN jsonb_build_object('success',false,'message','Responsável não nulo indisponível neste recorte.'); END IF;
 IF EXISTS(SELECT 1 FROM public.entregas WHERE ordem_servico_id=p_os_id) OR EXISTS(SELECT 1 FROM public.aplicacoes WHERE ordem_servico_id=p_os_id) THEN
 RETURN jsonb_build_object('success',false,'message','OS com entrega/aplicação já vinculada indisponível neste recorte.'); END IF;
 SELECT count(*) INTO v_count FROM public.lotes WHERE programacao_id=p_programacao_id;
 IF v_count>1 THEN RETURN jsonb_build_object('success',false,'message','Mais de um lote para a programação; revisão necessária.'); END IF;
 IF v_count=1 THEN
  SELECT * INTO v_lot FROM public.lotes WHERE programacao_id=p_programacao_id;
  -- Replay só é aceito quando o pedido e o lote/evento existentes coincidem; nenhum dado é alterado.
  IF v_os.status='programada' AND v_pp.status::text='aguardando' AND v_lot.organization_id=v_org AND v_lot.status::text='em_producao'
  AND v_lot.produto_id IS NOT DISTINCT FROM v_pp.produto_id AND v_lot.microrganismo_id IS NOT DISTINCT FROM v_pp.microrganismo_id
  AND v_lot.volume_produzido=v_volume AND v_lot.tanque IS NOT DISTINCT FROM v_tanque AND v_lot.responsavel_producao IS NOT DISTINCT FROM v_resp
  AND v_lot.observacoes_tecnicas IS NOT DISTINCT FROM v_obs AND NOT EXISTS(SELECT 1 FROM public.controle_qualidade WHERE lote_id=v_lot.id)
  AND NOT EXISTS(SELECT 1 FROM public.envase WHERE lote_id=v_lot.id)
  AND NOT EXISTS(SELECT 1 FROM public.estoque_produto WHERE lote_id=v_lot.id)
  AND (SELECT count(*) FROM public.laboratorio_esteira_eventos WHERE lote_id=v_lot.id)=1
  AND EXISTS(SELECT 1 FROM public.laboratorio_esteira_eventos WHERE lote_id=v_lot.id AND acao='gerar_lote'
    AND os_id=p_os_id AND origem_os='manual' AND programacao_id=p_programacao_id AND usuario_id=v_uid AND etapa_nova='lote_gerado') THEN
   RETURN jsonb_build_object('success',true,'replay',true,'lote_id',v_lot.id,'codigo_lote',v_lot.codigo_lote,'message',pg_catalog.format('Lote %s já registrado com os mesmos dados.',v_lot.codigo_lote));
  END IF;
  RETURN jsonb_build_object('success',false,'message','Já existe lote com dados diferentes para esta programação; nada foi alterado.');
 END IF;
 -- Primeira geração: OS programada e programação aguardando; esta ação não avança OS/programação nem cria CQ/envase.
 IF v_os.status IS DISTINCT FROM 'programada' OR v_pp.status::text IS DISTINCT FROM 'aguardando' OR v_pp.data_programada IS NULL
 OR v_pp.volume_necessario IS NULL OR v_pp.volume_necessario<=0 OR v_pp.volume_necessario::text IN ('NaN','Infinity','-Infinity')
 OR v_pp.volume_necessario IS DISTINCT FROM (SELECT volume_total_ml FROM public.ordens_servico WHERE id=p_os_id) THEN
 RETURN jsonb_build_object('success',false,'message','A OS deve estar programada e a programação aguardando; esta ação não programa nem avança etapas.'); END IF;
 LOOP
  v_try:=v_try+1; v_id:=pg_catalog.gen_random_uuid(); v_codigo:=public.gerar_codigo_lote(EXTRACT(YEAR FROM now())::int);
  BEGIN
   INSERT INTO platform_private.authz_tickets(txid,scope,target) VALUES(pg_catalog.txid_current(),'manual_lot_insert_v1',v_id);
   INSERT INTO public.lotes(id,programacao_id,codigo_lote,produto_id,microrganismo_id,volume_produzido,data_producao,responsavel_producao,tanque,observacoes_tecnicas,organization_id)
   VALUES(v_id,p_programacao_id,v_codigo,v_pp.produto_id,v_pp.microrganismo_id,v_volume,CURRENT_DATE,v_resp,v_tanque,v_obs,v_org) RETURNING id INTO v_id;
   DELETE FROM platform_private.authz_tickets WHERE txid=pg_catalog.txid_current() AND scope='manual_lot_insert_v1' AND target=v_id;
   EXIT;
  EXCEPTION WHEN unique_violation THEN
   GET STACKED DIAGNOSTICS v_constraint=CONSTRAINT_NAME;
   -- Concorrente fora deste RPC: falha fechada, sem replay presumido.
   IF v_constraint IS DISTINCT FROM 'lotes_codigo_lote_key' THEN RAISE EXCEPTION 'COCKPIT_LOTE_CONCORRENTE' USING ERRCODE='PT409'; END IF;
   IF v_try>=3 THEN RAISE EXCEPTION 'COCKPIT_LOTE_CODIGO_CONFLITO'; END IF;
  END;
 END LOOP;
 SELECT * INTO v_lot FROM public.lotes WHERE id=v_id;
 SELECT * INTO v_pp FROM public.programacao_producao WHERE id=p_programacao_id;
 IF (SELECT count(*) FROM public.lotes WHERE programacao_id=p_programacao_id)<>1 OR v_lot.organization_id IS DISTINCT FROM v_org
 OR v_lot.volume_produzido IS DISTINCT FROM v_volume OR v_lot.status::text IS DISTINCT FROM 'em_producao'
 OR v_pp.status::text IS DISTINCT FROM 'aguardando' OR v_pp.organization_id IS DISTINCT FROM v_org
 OR (SELECT status::text FROM public.ordens_servico WHERE id=p_os_id) IS DISTINCT FROM 'programada'
 OR EXISTS(SELECT 1 FROM public.controle_qualidade WHERE lote_id=v_id)
 OR public.technical_actor_ready(v_uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE OR public._saas_user_has_feature(v_uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_POSTCONDITION_FAILED'; END IF;
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,lote_id,etapa_nova,acao,usuario_id,observacao)
 VALUES(p_os_id,'manual',p_programacao_id,v_id,'lote_gerado','gerar_lote',v_uid,pg_catalog.format('Lote %s gerado (codigo canonico do servidor).',v_codigo));
 RETURN jsonb_build_object('success',true,'replay',false,'lote_id',v_id,'codigo_lote',v_codigo,'message',pg_catalog.format('Lote %s gerado com sucesso.',v_codigo));
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_activation_set(p_version bigint, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; s public.communication_tenant_email_settings; a platform_private.tenant_smtp_activation;
BEGIN
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 IF p_version IS NULL OR p_active IS NULL OR p_version<1 THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 IF platform_private.tenant_smtp_f4_actor_org() IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT * INTO a FROM platform_private.tenant_smtp_activation WHERE organization_id=v_org FOR UPDATE;
 IF p_active THEN
  IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_gate WHERE id AND approved)
  OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_f4_gate WHERE id AND approved)
  OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE id AND approved) THEN RAISE EXCEPTION 'SMTP_OPERATIONAL_NOT_READY' USING ERRCODE='42501'; END IF;
  IF NOT platform_private.tenant_smtp_f4_verified(v_org) OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR NOT s.credential_configured
  THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND mode='connection' AND version=s.version
   AND code='smtp_connection_ok' AND completed_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND state<>'complete')
  OR EXISTS(SELECT 1 FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND state IN ('claimed','executing'))
  OR EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_jobs WHERE organization_id=v_org AND state IN ('executing','authorized')) THEN RAISE EXCEPTION 'SMTP_BUSY' USING ERRCODE='40001'; END IF;
  IF a.organization_id IS NULL OR NOT a.active OR a.version<>s.version THEN
   INSERT INTO platform_private.tenant_smtp_activation(organization_id,active,version,from_email,changed_by,reason)
    VALUES(v_org,true,s.version,lower(s.config->>'from_email'),auth.uid(),'admin_activated')
    ON CONFLICT(organization_id) DO UPDATE SET active=true,version=EXCLUDED.version,from_email=EXCLUDED.from_email,changed_by=EXCLUDED.changed_by,reason=EXCLUDED.reason,changed_at=clock_timestamp();
   INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),s.version,'tenant_smtp_activated');
  END IF;
 ELSE
  IF a.organization_id IS NOT NULL AND a.active THEN
   UPDATE platform_private.tenant_smtp_activation SET active=false,version=s.version,from_email=lower(s.config->>'from_email'),changed_by=auth.uid(),reason='admin_paused',changed_at=clock_timestamp() WHERE organization_id=v_org;
   INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),s.version,'tenant_smtp_paused');
  END IF;
  PERFORM platform_private.tenant_smtp_lane_cancel_queued(v_org,'tenant_paused',auth.uid());
 END IF;
 RETURN platform_private.tenant_smtp_f4_status();
END $function$

CREATE OR REPLACE FUNCTION cf_user_guards_v1.acquire_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_LEVEL<>'STATEMENT' OR TG_RELID NOT IN ('public.profiles'::regclass,'public.user_roles'::regclass,'public.user_clientes'::regclass,'public.partner_users'::regclass,'auth.users'::regclass) THEN RAISE EXCEPTION 'invalid_user_guard_context' USING ERRCODE='42501'; END IF;
 IF current_setting('role',true) IN ('anon','authenticated') AND auth.uid() IS NULL THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_commercial_simulator(p_partner_id uuid, p_product_id uuid, p_quantidade numeric, p_desconto numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tabela numeric; v_final numeric; v_total numeric; v_custo numeric;
  v_source text := 'base'; v_source_label text := 'Preço base';
  v_campanha_nome text;
BEGIN
  IF NOT (public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- 1) Campanha ativa
  SELECT c.nome INTO v_campanha_nome
    FROM public.commercial_campaigns c
    JOIN public.commercial_campaign_partners cp ON cp.campaign_id = c.id AND cp.partner_id = p_partner_id
    JOIN public.commercial_campaign_products pp ON pp.campaign_id = c.id AND pp.product_id = p_product_id
   WHERE c.ativa = true AND CURRENT_DATE BETWEEN c.data_inicio AND c.data_fim
   ORDER BY c.data_inicio DESC LIMIT 1;

  IF v_campanha_nome IS NOT NULL THEN
    SELECT COALESCE(
      ppp.preco_tabela,
      p.valor_ha_brl,
      CASE WHEN p.valor_dose_brl IS NOT NULL AND p.dose_ml_ha IS NOT NULL AND p.dose_ml_ha > 0
           THEN ROUND(p.valor_dose_brl * (p.dose_ml_ha/100.0), 2) END,
      CASE WHEN p.valor_litro_brl IS NOT NULL AND p.dose_ml_ha IS NOT NULL AND p.dose_ml_ha > 0
           THEN ROUND((p.valor_litro_brl/10.0) * (p.dose_ml_ha/100.0), 2) END,
      0
    ) INTO v_tabela
      FROM public.produtos p
      LEFT JOIN public.partner_product_prices ppp
        ON ppp.product_id = p.id AND ppp.partner_id = p_partner_id AND ppp.is_current AND ppp.ativo
     WHERE p.id = p_product_id;
    v_source := 'campanha';
    v_source_label := 'Preço aplicado pela campanha: ' || v_campanha_nome;
  ELSE
    -- 2) Tabela do parceiro
    SELECT ppp.preco_tabela INTO v_tabela
      FROM public.partner_product_prices ppp
     WHERE ppp.product_id = p_product_id AND ppp.partner_id = p_partner_id
       AND ppp.is_current AND ppp.ativo
     LIMIT 1;
    IF v_tabela IS NOT NULL THEN
      v_source := 'tabela_parceiro';
      v_source_label := 'Preço aplicado pela tabela comercial do parceiro';
    ELSE
      -- 3) Base do cadastro do produto: valor_ha_brl, ou derivado de valor_dose_brl / valor_litro_brl
      SELECT COALESCE(
        p.valor_ha_brl,
        CASE WHEN p.valor_dose_brl IS NOT NULL AND p.dose_ml_ha IS NOT NULL AND p.dose_ml_ha > 0
             THEN ROUND(p.valor_dose_brl * (p.dose_ml_ha/100.0), 2) END,
        CASE WHEN p.valor_litro_brl IS NOT NULL AND p.dose_ml_ha IS NOT NULL AND p.dose_ml_ha > 0
             THEN ROUND((p.valor_litro_brl/10.0) * (p.dose_ml_ha/100.0), 2) END,
        0
      ) INTO v_tabela
        FROM public.produtos p WHERE p.id = p_product_id;
      v_source := 'base';
      v_source_label := 'Preço base do produto';
    END IF;
  END IF;

  v_tabela := COALESCE(v_tabela, 0);
  v_final := ROUND(v_tabela * (1 - COALESCE(p_desconto,0)/100), 2);
  v_total := ROUND(v_final * p_quantidade, 2);
  v_custo := ROUND(v_tabela * 0.55, 2);

  RETURN jsonb_build_object(
    'preco_tabela', v_tabela,
    'desconto_pct', COALESCE(p_desconto,0),
    'preco_final', v_final,
    'quantidade', p_quantidade,
    'valor_total', v_total,
    'custo_estimado_unitario', v_custo,
    'margem_unitaria', v_final - v_custo,
    'margem_pct', CASE WHEN v_final > 0 THEN ROUND(((v_final - v_custo)/v_final)*100, 2) ELSE 0 END,
    'rentabilidade_total', ROUND((v_final - v_custo) * p_quantidade, 2),
    'price_source', v_source,
    'price_source_label', v_source_label,
    'campanha_nome', v_campanha_nome
  );
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_f4_invalidate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.version IS DISTINCT FROM OLD.version OR NEW.config IS DISTINCT FROM OLD.config OR NEW.credential_configured IS DISTINCT FROM OLD.credential_configured THEN
  UPDATE platform_private.tenant_smtp_sender_verifications SET invalidated_at=clock_timestamp() WHERE organization_id=NEW.organization_id AND invalidated_at IS NULL;
  UPDATE platform_private.tenant_smtp_sender_challenges SET state='invalidated',code_hash=NULL,code_salt=NULL,closed_at=clock_timestamp()
   WHERE organization_id=NEW.organization_id AND state IN ('claimed','executing','sent','ambiguous');
  UPDATE platform_private.tenant_smtp_activation SET active=false,reason='config_changed',changed_by=auth.uid(),changed_at=clock_timestamp()
   WHERE organization_id=NEW.organization_id AND active;
  PERFORM platform_private.tenant_smtp_lane_cancel_queued(NEW.organization_id,'config_changed',auth.uid());
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_complete_communication_delivery(p_outbox_id uuid, p_worker_id text, p_provider_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_outbox%rowtype;
BEGIN
  IF NULLIF(trim(COALESCE(p_worker_id,'')),'') IS NULL THEN RAISE EXCEPTION 'worker_id obrigatório'; END IF;
  IF p_provider_message_id IS NOT NULL AND length(p_provider_message_id) > 200 THEN
    RAISE EXCEPTION 'provider_message_id excede 200';
  END IF;
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'processing' THEN RAISE EXCEPTION 'não estava em processing (status=%)', r.status; END IF;
  IF r.locked_by IS DISTINCT FROM p_worker_id THEN RAISE EXCEPTION 'lease de outro worker'; END IF;
  IF r.lease_expires_at IS NOT NULL AND r.lease_expires_at < now() THEN RAISE EXCEPTION 'lease expirado'; END IF;
  UPDATE public.comunicacao_outbox
     SET status = 'sent', sent_at = now(), provider_message_id = p_provider_message_id,
         locked_at = NULL, locked_by = NULL, lease_expires_at = NULL
   WHERE id = p_outbox_id;
  RETURN jsonb_build_object('ok',true);
END$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_nfe_readiness_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  emit public.company_fiscal_settings%ROWTYPE;
  rec_total int; rec_ready int; pol_pub int; rules_pub int; series_cnt int;
  cert_ok boolean; pend jsonb := '[]'::jsonb;
  cov jsonb; micro jsonb;
  m_active int; m_ready int; m_draft int; m_blocked int; m_inactive int;
  emitter_status text; overall text;
BEGIN
  PERFORM public.h15_require_staff();

  IF NOT public.fn_fiscal_can_read_internal() THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao de leitura fiscal.';
  END IF;

  SELECT * INTO emit FROM (SELECT * FROM public.company_fiscal_settings WHERE organization_id = public.h15_actor_organization()) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  SELECT count(*), count(*) FILTER (WHERE nfe_readiness_status = 'READY')
    INTO rec_total, rec_ready FROM public.customer_fiscal_profiles;
  SELECT count(*) INTO pol_pub FROM public.fiscal_operation_policies
   WHERE policy_status = 'PUBLISHED' AND document_model = '55';
  SELECT count(*) INTO rules_pub FROM public.fiscal_tax_rules WHERE status = 'PUBLISHED';
  SELECT count(*) INTO series_cnt FROM (SELECT * FROM public.fiscal_document_series WHERE public.h15_company_access(company_id)) fiscal_document_series WHERE status = 'ACTIVE';
  cert_ok := EXISTS (SELECT 1 FROM public.fiscal_certificates c
    WHERE c.id::text = emit.certificate_ref AND c.company_settings_id = emit.id
      AND c.environment = 'HOMOLOGATION' AND c.status = 'AVAILABLE'
      AND c.is_active IS TRUE AND c.revoked_at IS NULL
      AND c.valid_from <= now() AND c.valid_until > now());

  cov := public.fn_fiscal_scenario_coverage();
  micro := coalesce(cov->'microorganisms','{}'::jsonb);
  m_active   := coalesce((micro->>'active')::int,0);
  m_ready    := coalesce((micro->>'ready')::int,0);
  m_draft    := coalesce((micro->>'draft')::int,0);
  m_blocked  := coalesce((micro->>'blocked')::int,0);
  m_inactive := coalesce((micro->>'inactive')::int,0);

  -- Teto absoluto da F3: nunca READY_PRODUCTION.
  emitter_status := coalesce(emit.nfe_readiness_status,'NOT_READY');
  IF NOT cert_ok OR emitter_status = 'READY_PRODUCTION' THEN
    emitter_status := 'NOT_READY';
  END IF;
  IF coalesce(emit.nfe_environment_code,'2') = '1' THEN
    pend := pend || jsonb_build_object('section','HOMOLOGACAO','code','EMITTER_PRODUCTION_BLOCKED_F3',
      'severity','BLOCK','message','Ambiente de producao (tpAmb=1) bloqueado nesta fase. Teto: READY_HOMOLOGATION.');
  END IF;
  IF emit.id IS NOT NULL AND emit.sefaz_homologation_at IS NULL THEN
    pend := pend || jsonb_build_object('section','HOMOLOGACAO','code','SEFAZ_HOMOLOGATION_NOT_RECORDED',
      'severity','WARN','message','Homologacao SEFAZ ainda nao registrada. A transicao so ocorrera por RPC controlada em fase posterior.');
  END IF;

  IF emit.id IS NULL THEN
    pend := pend || jsonb_build_object('section','EMITENTE','code','EMITTER_NOT_CONFIGURED','severity','BLOCK','message','Emitente nao cadastrado.');
  ELSE
    pend := pend || coalesce((SELECT jsonb_agg(e || jsonb_build_object('section','EMITENTE'))
                              FROM jsonb_array_elements(emit.nfe_readiness_pendencies) e), '[]'::jsonb);
  END IF;

  IF rec_total = 0 THEN
    pend := pend || jsonb_build_object('section','DESTINATARIOS','code','RECIPIENTS_NONE','severity','BLOCK','message','Nenhum perfil fiscal de destinatario cadastrado.');
  ELSIF rec_ready = 0 THEN
    pend := pend || jsonb_build_object('section','DESTINATARIOS','code','RECIPIENTS_NONE_READY','severity','BLOCK','message','Nenhum destinatario com cadastro fiscal completo.');
  END IF;

  IF pol_pub = 0 THEN
    pend := pend || jsonb_build_object('section','OPERACOES','code','OPERATION_POLICIES_NONE','severity','BLOCK','message','Nenhuma politica de operacao/CFOP publicada para modelo 55.');
  END IF;

  IF coalesce((cov->>'total')::int,0) = 0 THEN
    pend := pend || jsonb_build_object('section','TRIBUTOS','code','COVERAGE_NO_SCENARIOS','severity','BLOCK',
      'message','Nao ha cenarios reais (destinatario pronto x canal ativo x NCM oficial) para aferir cobertura tributaria.');
  ELSIF (cov->>'covered')::int < (cov->>'total')::int THEN
    pend := pend || jsonb_build_object('section','TRIBUTOS','code','COVERAGE_INCOMPLETE','severity','BLOCK',
      'message','Cobertura tributaria incompleta: '||(cov->>'covered')||' de '||(cov->>'total')||' cenarios validados no motor.');
  END IF;

  -- Somente microrganismos ATIVOS podem bloquear. Inativos sao informativos.
  IF m_blocked > 0 THEN
    pend := pend || jsonb_build_object('section','TRIBUTOS','code','MICROORGANISMS_BLOCKED','severity','BLOCK',
      'message', m_blocked||' microrganismo(s) ativo(s) com perfil fiscal BLOQUEADO.');
  END IF;
  IF m_draft > 0 THEN
    pend := pend || jsonb_build_object('section','TRIBUTOS','code','MICROORGANISMS_NOT_READY','severity','BLOCK',
      'message', m_draft||' de '||m_active||' microrganismos ativos sem dossie aprovado e validacao contabil.');
  END IF;

  IF NOT cert_ok THEN
    pend := pend || jsonb_build_object('section','CERTIFICADO','code','CERTIFICATE_MISSING','severity','BLOCK','message','Certificado ausente, indisponivel, revogado, vencido ou de outra empresa.');
  END IF;
  IF series_cnt = 0 THEN
    pend := pend || jsonb_build_object('section','HOMOLOGACAO','code','SERIES_NOT_INITIALIZED','severity','WARN','message','Nenhuma serie de numeracao inicializada; sera criada na primeira reserva.');
  END IF;

  overall := CASE
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(pend) e WHERE e->>'severity'='BLOCK') THEN 'NOT_READY'
    WHEN jsonb_array_length(pend) > 0 THEN 'PARTIAL'
    ELSE 'READY_HOMOLOGATION' END;

  RETURN jsonb_build_object(
    'generatedAt', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SSZ'),
    'documentModel','55',
    'maxAllowedStatus','READY_HOMOLOGATION',
    'emitter', jsonb_build_object(
      'configured', emit.id IS NOT NULL,
      'status', emitter_status,
      'crt', emit.crt, 'uf', emit.state,
      'series', emit.nfe_series_number, 'environment', emit.nfe_environment_code,
      'certificateLinked', cert_ok,
      'sefazHomologationRecorded', emit.sefaz_homologation_at IS NOT NULL,
      'productionBlocked', true,
      'accountingValidated', emit.accounting_validated_at IS NOT NULL),
    'recipients', jsonb_build_object('total', rec_total, 'ready', rec_ready),
    'operations', jsonb_build_object('publishedPolicies', pol_pub),
    'taxes', jsonb_build_object('publishedRules', rules_pub, 'missingMandatoryKinds', '[]'::jsonb),
    'coverage', cov,
    'microorganisms', jsonb_build_object(
      'active', m_active, 'ready', m_ready, 'draft', m_draft,
      'blocked', m_blocked, 'inactive', m_inactive,
      'total', m_active + m_inactive),
    'numbering', jsonb_build_object('activeSeries', series_cnt),
    'pendencies', pend,
    'overallStatus', overall);
END $function$

CREATE OR REPLACE FUNCTION cf_user_guards_v1.touch_related_profiles()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old_id uuid; new_id uuid; item uuid;
BEGIN
 IF TG_LEVEL<>'ROW' OR TG_RELID NOT IN ('public.user_roles'::regclass,'public.user_clientes'::regclass,'public.partner_users'::regclass) THEN RAISE EXCEPTION 'invalid_user_guard_context' USING ERRCODE='42501'; END IF;
 IF TG_OP<>'INSERT' THEN old_id:=OLD.user_id; END IF;
 IF TG_OP<>'DELETE' THEN new_id:=NEW.user_id; END IF;
 FOR item IN SELECT DISTINCT x FROM unnest(ARRAY[old_id,new_id]) x WHERE x IS NOT NULL ORDER BY x LOOP UPDATE public.profiles SET updated_at=updated_at WHERE user_id=item; END LOOP;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_confirmar_entrega_embalagens(p_entrega_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_count int := 0;
  r record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT (public.has_role(v_uid,'administrador'::app_role)
       OR public.has_role(v_uid,'gestor'::app_role)
       OR public.has_role(v_uid,'producao'::app_role)
       OR public.has_role(v_uid,'operador_onfarm'::app_role)) THEN
    RAISE EXCEPTION 'sem permissão';
  END IF;

  FOR r IN
    SELECT id, status FROM public.estoque_embalagens
     WHERE entrega_id = p_entrega_id AND status IN ('reservado','separado')
     FOR UPDATE
  LOOP
    UPDATE public.estoque_embalagens
       SET status='entregue', entregue_em=now(), entregue_por=v_uid
     WHERE id = r.id;
    INSERT INTO public.estoque_embalagem_movimentacoes(
      embalagem_id, tipo_movimentacao, status_anterior, status_novo, entrega_id, user_id
    ) VALUES (r.id, 'entrega_confirmada', r.status, 'entregue', p_entrega_id, v_uid);
    v_count := v_count + 1;
  END LOOP;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'nenhuma embalagem reservada/separada para esta entrega';
  END IF;

  PERFORM public.rpc_recalcular_separacao_entrega(p_entrega_id);
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
    VALUES ('estoque_embalagem', p_entrega_id, 'EMB_DELIVERED', v_uid,
            jsonb_build_object('entrega_id', p_entrega_id, 'qtd', v_count));
  RETURN jsonb_build_object('success', true, 'total', v_count);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_confirmar_recebimento_entrega(p_entrega_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
  v_comp public.entrega_comprovantes%ROWTYPE;
  v_ressalvas text := nullif(trim(coalesce(p_payload->>'ressalvas','')), '');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão inválida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  SELECT * INTO v_entrega FROM public.entregas WHERE id = p_entrega_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada'; END IF;
  IF v_entrega.status = 'cancelada' THEN RAISE EXCEPTION 'Entrega cancelada'; END IF;
  IF v_entrega.assinatura_obrigatoria
     AND nullif(trim(coalesce(v_entrega.recebedor_nome,'')),'') IS NULL THEN
    RAISE EXCEPTION 'recebedor_nome é obrigatório';
  END IF;
  IF v_entrega.comprovante_id IS NULL THEN
    RAISE EXCEPTION 'Não há comprovante para confirmar';
  END IF;
  SELECT * INTO v_comp FROM public.entrega_comprovantes WHERE id = v_entrega.comprovante_id;
  IF v_comp.status NOT IN ('anexado','assinatura_digital_coletada','assinado','impresso','gerado') THEN
    RAISE EXCEPTION 'Status de comprovante não permite confirmação (%).', v_comp.status;
  END IF;
  IF v_entrega.assinatura_obrigatoria
     AND v_comp.status NOT IN ('anexado','assinatura_digital_coletada','assinado') THEN
    RAISE EXCEPTION 'Comprovante sem assinatura. Anexe ou colete a assinatura digital.';
  END IF;

  UPDATE public.entrega_comprovantes SET
    status = 'confirmado',
    confirmado_por = v_uid,
    confirmado_em = now(),
    ressalvas = coalesce(v_ressalvas, ressalvas),
    possui_ressalvas = (v_ressalvas IS NOT NULL) OR possui_ressalvas,
    validation_hash = encode(extensions.digest(p_entrega_id::text || coalesce(validation_hash,'') || 'CONF' || now()::text, 'sha256'),'hex'),
    updated_at = now()
  WHERE id = v_comp.id;

  UPDATE public.entregas SET
    comprovante_status = 'confirmado',
    recebimento_confirmado_em = now(),
    recebimento_confirmado_por = v_uid,
    updated_at = now()
  WHERE id = p_entrega_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by, reason)
  VALUES ('entrega', p_entrega_id, 'DELIVERY_RECEIPT_CONFIRMED',
          jsonb_build_object('comprovante_id', v_comp.id, 'ressalvas', v_ressalvas), v_uid, v_ressalvas);

  RETURN jsonb_build_object('success', true);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_xml_prepare_v1(p_invoice_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  inv  public.fiscal_invoices%ROWTYPE;
  emit public.company_fiscal_settings%ROWTYPE;
  dest public.customer_fiscal_profiles%ROWTYPE;
  resv public.fiscal_number_reservations%ROWTYPE;
  srs  public.fiscal_document_series%ROWTYPE;
  existing public.fiscal_xml_runs%ROWTYPE;
  v_items jsonb;
  v_payload jsonb;
  v_hash text;
  v_schema text;
  v_version int;
  v_prev uuid;
  v_run public.fiscal_xml_runs%ROWTYPE;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(p_invoice_id);

  IF NOT public.fn_fiscal_can_operate(auth.uid()) THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao para gerar XML fiscal.';
  END IF;
  IF nullif(btrim(coalesce(p_idempotency_key,'')),'') IS NULL THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_KEY_REQUIRED: informe uma chave de idempotencia.';
  END IF;
  IF p_invoice_id IS NULL THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: documento nao informado.';
  END IF;

  -- Gate de ambiente fail-closed ANTES de qualquer leitura/efeito (F3.1-R2).
  PERFORM public.fn_fiscal_assert_environment_homologation();

  IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_xml_runs WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_xml_runs
              WHERE idempotency_key = p_idempotency_key
                AND fiscal_invoice_id <> p_invoice_id) THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_SCOPE_MISMATCH: chave de idempotencia ja utilizada por outro documento fiscal.';
  END IF;

  SELECT * INTO inv FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: %', p_invoice_id; END IF;

  IF inv.document_model <> 'NFE' THEN
    RAISE EXCEPTION 'FISCAL_MODEL_UNSUPPORTED: fase F4 cobre apenas NF-e modelo 55.';
  END IF;
  IF coalesce(inv.tp_emis,1) <> 1 THEN
    RAISE EXCEPTION 'FISCAL_TPEMIS_UNSUPPORTED: apenas emissao normal (tpEmis=1) esta habilitada nesta fase.';
  END IF;
  IF inv.tax_snapshot IS NULL OR NOT (inv.tax_snapshot ? 'engineVersion') THEN
    RAISE EXCEPTION 'FISCAL_CALCULATION_REQUIRED: calcule os tributos antes de gerar o XML.';
  END IF;

  SELECT * INTO resv FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_number_reservations
   WHERE fiscal_invoice_id = p_invoice_id AND status = 'RESERVED'
   ORDER BY reserved_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'FISCAL_NUMBER_RESERVATION_REQUIRED: reserve a numeracao antes de gerar o XML.';
  END IF;
  SELECT * INTO srs FROM (SELECT * FROM public.fiscal_document_series WHERE public.h15_company_access(company_id)) fiscal_document_series WHERE id = resv.series_id;

  IF NOT ((public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id, p_invoice_id))->>'eligible')::boolean THEN
    RAISE EXCEPTION 'FISCAL_NOT_ELIGIBLE: %',
      (public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id, p_invoice_id))->>'reasons';
  END IF;

  PERFORM public.fn_fiscal_assert_debtor_recipient(p_invoice_id);

  SELECT * INTO emit FROM (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EMITTER_NOT_CONFIGURED: emitente nao cadastrado.'; END IF;
  IF coalesce(emit.nfe_environment_code,'2') <> '2' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_BLOCKED: apenas homologacao (tpAmb=2) e permitida na fase F4.';
  END IF;
  IF emit.nfe_readiness_status <> 'READY_HOMOLOGATION' THEN
    RAISE EXCEPTION 'FISCAL_EMITTER_NOT_READY: emitente com pendencias %', emit.nfe_readiness_pendencies;
  END IF;

  SELECT * INTO dest FROM public.customer_fiscal_profiles WHERE customer_id = inv.customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_RECIPIENT_PROFILE_MISSING: perfil fiscal do destinatario nao cadastrado.'; END IF;
  IF dest.nfe_readiness_status <> 'READY' THEN
    RAISE EXCEPTION 'FISCAL_RECIPIENT_NOT_READY: destinatario com pendencias %', dest.nfe_readiness_pendencies;
  END IF;

  SELECT schema_version INTO v_schema
    FROM public.fiscal_xsd_registry
   WHERE schema_name = 'nfe_v4.00' AND is_active
   ORDER BY published_at DESC LIMIT 1;
  IF v_schema IS NULL THEN
    RAISE EXCEPTION 'FISCAL_XSD_NOT_REGISTERED: esquema NF-e 4.00 ausente no registro oficial.';
  END IF;

  SELECT jsonb_agg(
           jsonb_build_object(
             'nItem', i.item_sequence,
             'cProd', coalesce(nullif(btrim(coalesce(i.source_item_id::text,'')),''), 'ITEM' || i.item_sequence::text),
             'xProd', i.description,
             'NCM', i.ncm_snapshot,
             'CEST', i.cest_snapshot,
             'CFOP', i.cfop_snapshot,
             'uCom', i.commercial_unit,
             'qCom', i.quantity,
             'vUnCom', i.unit_value,
             'vProd', coalesce(i.gross_value, i.quantity * i.unit_value),
             'vDesc', coalesce(i.discount_value,0),
             'vFrete', coalesce(i.freight_value,0),
             'vSeg', coalesce(i.insurance_value,0),
             'vOutro', coalesce(i.other_value,0),
             'orig', coalesce(i.origem_snapshot,'0'),
             'CST', i.cst_icms_snapshot,
             'CSOSN', i.csosn_snapshot,
             'taxSnapshot', i.tax_snapshot)
           ORDER BY i.item_sequence)
    INTO v_items
    FROM (SELECT * FROM public.fiscal_invoice_items WHERE public.h15_invoice_access(fiscal_invoice_id)) i
   WHERE i.fiscal_invoice_id = p_invoice_id;

  IF v_items IS NULL OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NO_ITEMS: documento sem itens.';
  END IF;

  v_payload := jsonb_build_object(
    'engineVersion','F4.1',
    'schemaVersion', v_schema,
    'tpAmb', emit.nfe_environment_code,
    'accessKey', resv.access_key,
    'ide', jsonb_build_object(
      'cUF', left(resv.access_key,2),
      'cNF', resv.cnf,
      'natOp', coalesce(inv.nature_operation, 'VENDA'),
      'mod', '55',
      'serie', coalesce(srs.series, emit.nfe_series_number),
      'nNF', resv.number,
      'dhEmi', to_char(coalesce(inv.issue_date, current_date), 'YYYY-MM-DD'),
      'tpNF', CASE WHEN coalesce(inv.direction,'OUT') = 'OUT' THEN '1' ELSE '0' END,
      'idDest', CASE
                  WHEN upper(coalesce(dest.fiscal_state,'')) = upper(coalesce(emit.state,'')) THEN '1'
                  ELSE '2' END,
      'cMunFG', emit.municipality_ibge_code,
      'tpImp','1', 'tpEmis','1',
      'cDV', resv.check_digit::text,
      'finNFe', coalesce(inv.fin_nfe,'1'),
      'indFinal', CASE WHEN coalesce(dest.final_consumer,true) THEN '1' ELSE '0' END,
      'indPres','9', 'procEmi','0', 'verProc','ARBIO-F4.1'),
    'emit', jsonb_build_object(
      'CNPJ', public.fn_fiscal_digits(emit.cnpj),
      'xNome', emit.legal_name,
      'xFant', emit.trade_name,
      'IE', public.fn_fiscal_digits(coalesce(emit.state_registration,'')),
      'CRT', emit.crt,
      'CNAE', emit.primary_cnae,
      'enderEmit', jsonb_build_object(
        'xLgr', emit.street, 'nro', emit.number, 'xCpl', emit.complement,
        'xBairro', emit.neighborhood, 'cMun', emit.municipality_ibge_code,
        'xMun', emit.city, 'UF', emit.state,
        'CEP', public.fn_fiscal_digits(coalesce(emit.postal_code,'')),
        'cPais','1058','xPais','BRASIL')),
    'dest', jsonb_build_object(
      'personType', dest.person_type,
      'doc', public.fn_fiscal_digits(coalesce(dest.cpf_cnpj,'')),
      'xNome', dest.legal_name,
      'indIEDest', dest.taxpayer_indicator,
      'IE', public.fn_fiscal_digits(coalesce(dest.state_registration,'')),
      'enderDest', jsonb_build_object(
        'xLgr', dest.fiscal_street, 'nro', dest.fiscal_number, 'xCpl', dest.fiscal_complement,
        'xBairro', dest.fiscal_neighborhood, 'cMun', dest.fiscal_municipality_ibge_code,
        'xMun', dest.fiscal_city, 'UF', dest.fiscal_state,
        'CEP', public.fn_fiscal_digits(coalesce(dest.fiscal_postal_code,'')),
        'cPais','1058','xPais','BRASIL')),
    'det', v_items,
    'total', inv.fiscal_totals_snapshot,
    'infAdic', jsonb_build_object(
      'infCpl', 'AMBIENTE DE HOMOLOGACAO - SEM VALOR FISCAL'));

  IF public.fiscal_json_has_sensitive_key(v_payload) THEN
    RAISE EXCEPTION 'FISCAL_PAYLOAD_SENSITIVE: payload de XML contem chave sensivel.';
  END IF;

  v_hash := encode(extensions.digest(v_payload::text, 'sha256'), 'hex');

  SELECT * INTO existing FROM (SELECT * FROM public.fiscal_xml_runs WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_xml_runs
   WHERE fiscal_invoice_id = p_invoice_id AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF existing.payload_sha256 <> v_hash THEN
      RAISE EXCEPTION 'FISCAL_XML_FINGERPRINT_MISMATCH: documento mudou apos o preparo; use nova chave de idempotencia.';
    END IF;
    RETURN jsonb_build_object(
      'runId', existing.id, 'state', existing.state, 'runVersion', existing.run_version,
      'schemaVersion', existing.schema_version, 'accessKey', existing.access_key,
      'payloadSha256', existing.payload_sha256, 'payload', existing.payload,
      'idempotentReplay', true);
  END IF;

  SELECT id, run_version INTO v_prev, v_version
    FROM (SELECT * FROM public.fiscal_xml_runs WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_xml_runs
   WHERE fiscal_invoice_id = p_invoice_id
   ORDER BY run_version DESC LIMIT 1;

  IF v_prev IS NOT NULL AND EXISTS (
      SELECT 1 FROM (SELECT * FROM public.fiscal_xml_runs WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_xml_runs
       WHERE fiscal_invoice_id = p_invoice_id AND state NOT IN ('SIGNED','FAILED')) THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IN_PROGRESS: existe execucao em andamento para este documento.';
  END IF;

  INSERT INTO public.fiscal_xml_runs (
    fiscal_invoice_id, reservation_id, idempotency_key, run_version, previous_run_id,
    schema_version, environment_code, access_key, payload, payload_sha256, created_by)
  VALUES (
    p_invoice_id, resv.id, p_idempotency_key, coalesce(v_version,0) + 1, v_prev,
    v_schema, emit.nfe_environment_code, resv.access_key, v_payload, v_hash, auth.uid())
  RETURNING * INTO v_run;

  INSERT INTO public.fiscal_audit_log (table_name, record_id, action, changed_by, new_values)
  VALUES ('fiscal_xml_runs', v_run.id, 'XML_PREPARED', auth.uid(),
          jsonb_build_object('invoiceId', p_invoice_id, 'runVersion', v_run.run_version,
                             'payloadSha256', v_hash, 'schemaVersion', v_schema));

  RETURN jsonb_build_object(
    'runId', v_run.id, 'state', v_run.state, 'runVersion', v_run.run_version,
    'schemaVersion', v_run.schema_version, 'accessKey', v_run.access_key,
    'payloadSha256', v_run.payload_sha256, 'payload', v_run.payload,
    'idempotentReplay', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_confirmar_separacao_embalagem(p_embalagem_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_st text; v_ent uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT (public.can_user_manage_estoque_embalagem(p_embalagem_id)
       OR public.has_role(v_uid,'administrativo'::app_role)) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  SELECT status, entrega_id INTO v_st, v_ent FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF v_st <> 'reservado' THEN RAISE EXCEPTION 'embalagem não está reservada'; END IF;
  UPDATE public.estoque_embalagens SET status='separado', separado_em=now(), separado_por=v_uid WHERE id = p_embalagem_id;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_anterior, status_novo, entrega_id, user_id)
    VALUES (p_embalagem_id, 'separacao_entrega', 'reservado', 'separado', v_ent, v_uid);
  IF v_ent IS NOT NULL THEN PERFORM public.rpc_recalcular_separacao_entrega(v_ent); END IF;
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by)
    VALUES ('estoque_embalagem', p_embalagem_id, 'EMB_PICKED', v_uid);
  RETURN jsonb_build_object('success', true);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_create_financial_title(p_kind text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := platform_private.h15_actor_organization();
  v_total numeric(14,2);
  v_count int;
  v_first_due date;
  v_category uuid;
  v_cc uuid;
  v_desc text;
  v_notes text;
  v_issue date;
  v_title_id uuid := gen_random_uuid();
  v_installments jsonb;
  v_sum numeric(14,2) := 0;
  v_inst jsonb;
  v_fk_col text;
  v_table text;
  v_fiscal_req boolean;
  v_customer uuid;
  v_supplier_id uuid;
  v_supplier_name text;
  v_payment uuid;
  v_supplier_invoice_date date;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para criar títulos financeiros.' USING ERRCODE='insufficient_privilege';
  END IF;

  IF v_org IS NULL THEN RAISE EXCEPTION 'FINANCIAL_TENANT_REQUIRED' USING ERRCODE='42501'; END IF;
  IF (p_payload ? 'organization_id' AND NULLIF(p_payload->>'organization_id','')::uuid IS DISTINCT FROM v_org)
     OR (p_payload ? 'tenant_id' AND NULLIF(p_payload->>'tenant_id','')::uuid IS DISTINCT FROM v_org) THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_MISMATCH' USING ERRCODE='42501';
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('receivable','payable') THEN
    RAISE EXCEPTION 'Tipo de título inválido: %', p_kind USING ERRCODE='check_violation';
  END IF;

  IF p_kind = 'payable' THEN
 IF NULLIF(btrim(p_payload->>'supplier_name'),'') IS NULL AND NULLIF(p_payload->>'supplier_id','') IS NULL THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_SUPPLIER' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR NULLIF(btrim(p_payload->>'description'),'') IS NULL THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_DESCRIPTION' USING ERRCODE='23514'; END IF;
 IF COALESCE((p_payload->>'total_amount')::numeric,0) <= 0 OR (p_payload->>'total_amount')::numeric::text IN ('NaN','Infinity','-Infinity') OR (p_payload->>'total_amount')::numeric <> round((p_payload->>'total_amount')::numeric,2) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_AMOUNT' USING ERRCODE='23514'; END IF;
 IF COALESCE((p_payload->>'installment_count')::numeric,1) NOT BETWEEN 1 AND 36 OR COALESCE((p_payload->>'installment_count')::numeric,1) <> trunc(COALESCE((p_payload->>'installment_count')::numeric,1)) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_COUNT' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.financial_categories WHERE id=NULLIF(p_payload->>'category_id','')::uuid AND active AND type IN ('DESPESA','AMBOS')) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_CATEGORY' USING ERRCODE='23514'; END IF;
 IF NULLIF(p_payload->>'cost_center_id','') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.financial_cost_centers WHERE id=(p_payload->>'cost_center_id')::uuid AND active) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_COST_CENTER' USING ERRCODE='23514'; END IF;
 IF p_payload ? 'installments' THEN
 IF jsonb_typeof(p_payload->'installments') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_INSTALLMENTS' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(p_payload->'installments') <> COALESCE((p_payload->>'installment_count')::int,1) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_COUNT' USING ERRCODE='23514'; END IF;
 FOR v_inst IN SELECT * FROM jsonb_array_elements(p_payload->'installments') LOOP
 IF jsonb_typeof(v_inst) IS DISTINCT FROM 'object' OR COALESCE((v_inst->>'amount')::numeric,0) <= 0 OR (v_inst->>'amount')::numeric::text IN ('NaN','Infinity','-Infinity') OR (v_inst->>'amount')::numeric <> round((v_inst->>'amount')::numeric,2) OR NULLIF(v_inst->>'due_date','')::date IS NULL THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_INSTALLMENT' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'installments') WITH ORDINALITY AS x(item,seq) WHERE (item->>'installment_number')::numeric IS DISTINCT FROM seq::numeric) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_SEQUENCE' USING ERRCODE='23514'; END IF;
 IF (SELECT sum((x->>'amount')::numeric) FROM jsonb_array_elements(p_payload->'installments') x) IS DISTINCT FROM (p_payload->>'total_amount')::numeric THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_SUM' USING ERRCODE='23514'; END IF;
 END IF;
 END IF;
 
 v_desc := NULLIF(p_payload->>'description','');
  v_category   := NULLIF(p_payload->>'category_id','')::uuid;
  v_cc         := NULLIF(p_payload->>'cost_center_id','')::uuid;
  v_total      := COALESCE((p_payload->>'total_amount')::numeric, 0);
  v_count      := COALESCE((p_payload->>'installment_count')::int, 1);
  v_first_due  := NULLIF(p_payload->>'first_due_date','')::date;
  v_issue      := COALESCE(NULLIF(p_payload->>'issue_date','')::date, (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date);
  v_notes      := NULLIF(p_payload->>'notes','');
  v_installments := p_payload->'installments';

  IF v_desc IS NULL THEN RAISE EXCEPTION 'Descrição obrigatória.'; END IF;
  IF v_category IS NULL THEN RAISE EXCEPTION 'Categoria obrigatória.'; END IF;
  IF v_total <= 0 THEN RAISE EXCEPTION 'Valor total deve ser maior que zero.'; END IF;
  IF v_first_due IS NULL THEN RAISE EXCEPTION '1º vencimento obrigatório.'; END IF;
  IF v_count < 1 OR v_count > 36 THEN RAISE EXCEPTION 'Nº de parcelas deve estar entre 1 e 36.'; END IF;

  IF NOT EXISTS (SELECT 1 FROM financial_categories WHERE id = v_category) THEN
    RAISE EXCEPTION 'Categoria inexistente.';
  END IF;

  IF p_kind = 'receivable' THEN
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR NULLIF(btrim(p_payload->>'description'),'') IS NULL THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_DESCRIPTION' USING ERRCODE='23514'; END IF;
 IF COALESCE((p_payload->>'total_amount')::numeric,0) <= 0 OR (p_payload->>'total_amount')::numeric::text IN ('NaN','Infinity','-Infinity') OR (p_payload->>'total_amount')::numeric <> round((p_payload->>'total_amount')::numeric,2) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_AMOUNT' USING ERRCODE='23514'; END IF;
 IF COALESCE((p_payload->>'installment_count')::numeric,1) NOT BETWEEN 1 AND 36 OR COALESCE((p_payload->>'installment_count')::numeric,1) <> trunc(COALESCE((p_payload->>'installment_count')::numeric,1)) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_COUNT' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.financial_categories WHERE id=NULLIF(p_payload->>'category_id','')::uuid AND active AND type IN ('RECEITA','AMBOS')) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_CATEGORY' USING ERRCODE='23514'; END IF;
 IF NULLIF(p_payload->>'cost_center_id','') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.financial_cost_centers WHERE id=(p_payload->>'cost_center_id')::uuid AND active) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_COST_CENTER' USING ERRCODE='23514'; END IF;
 IF p_payload ? 'installments' THEN
 IF jsonb_typeof(p_payload->'installments') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_INSTALLMENTS' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(p_payload->'installments') <> COALESCE((p_payload->>'installment_count')::int,1) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_COUNT' USING ERRCODE='23514'; END IF;
 FOR v_inst IN SELECT * FROM jsonb_array_elements(p_payload->'installments') LOOP
 IF jsonb_typeof(v_inst) IS DISTINCT FROM 'object' OR COALESCE((v_inst->>'amount')::numeric,0) <= 0 OR (v_inst->>'amount')::numeric::text IN ('NaN','Infinity','-Infinity') OR (v_inst->>'amount')::numeric <> round((v_inst->>'amount')::numeric,2) OR NULLIF(v_inst->>'due_date','')::date IS NULL THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_INSTALLMENT' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'installments') WITH ORDINALITY AS x(item,seq) WHERE (item->>'installment_number')::numeric IS DISTINCT FROM seq::numeric) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_SEQUENCE' USING ERRCODE='23514'; END IF;
 IF (SELECT sum((x->>'amount')::numeric) FROM jsonb_array_elements(p_payload->'installments') x) IS DISTINCT FROM (p_payload->>'total_amount')::numeric THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_SUM' USING ERRCODE='23514'; END IF;
 END IF;
 END IF;
 -- Validar parcelas customizadas (se fornecidas)
  IF v_installments IS NOT NULL AND jsonb_typeof(v_installments) = 'array' THEN
    IF jsonb_array_length(v_installments) <> v_count THEN
      RAISE EXCEPTION 'Qtd de parcelas customizadas (%) difere de installment_count (%)',
        jsonb_array_length(v_installments), v_count;
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_installments) LOOP
      v_sum := v_sum + COALESCE((v_inst->>'amount')::numeric, 0);
    END LOOP;
    IF abs(v_sum - v_total) > 0.01 THEN
      RAISE EXCEPTION 'Soma das parcelas (%) difere do total (%)', v_sum, v_total;
    END IF;
  END IF;

  IF v_total * 100 < v_count THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_INSTALLMENT' USING ERRCODE='23514'; END IF;
  IF NOT isfinite(v_issue) OR NOT isfinite(v_first_due) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_INSTALLMENT' USING ERRCODE='23514'; END IF;
  IF v_installments IS NOT NULL THEN
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_installments) x WHERE NOT isfinite((x->>'due_date')::date)) THEN RAISE EXCEPTION 'FIN_TITLE_INVALID_INSTALLMENT' USING ERRCODE='23514'; END IF;
    INSERT INTO platform_private.financial_initial_installments
      VALUES(txid_current(),v_title_id,p_kind,v_uid,v_org,v_installments);
  END IF;

  IF p_kind = 'receivable' THEN
    v_customer   := NULLIF(p_payload->>'customer_id','')::uuid;
    v_payment    := NULLIF(p_payload->>'payment_method_id','')::uuid;
    v_fiscal_req := COALESCE((p_payload->>'fiscal_invoice_required')::boolean, false);
    IF v_customer IS NULL THEN RAISE EXCEPTION 'Cliente obrigatório.'; END IF;

    INSERT INTO accounts_receivable (
      id, organization_id, customer_id, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count,
      notes, created_by, origin_type,
      fiscal_invoice_required, fiscal_invoice_status, payment_method_id
    ) VALUES (
      v_title_id, v_org, v_customer, v_desc, v_category, v_cc,
      v_total, v_issue, v_first_due, v_count,
      v_notes, v_uid, 'MANUAL',
      v_fiscal_req,
      CASE WHEN v_fiscal_req THEN 'PENDING' ELSE 'NOT_REQUIRED' END,
      v_payment
    ) RETURNING id INTO v_title_id;

    v_table  := 'accounts_receivable_installments';
    v_fk_col := 'receivable_id';
  ELSE
    v_supplier_id   := NULLIF(p_payload->>'supplier_id','')::uuid;
    v_supplier_name := NULLIF(p_payload->>'supplier_name','');
    v_supplier_invoice_date := NULLIF(p_payload->>'supplier_invoice_date','')::date;
    IF v_supplier_id IS NULL AND v_supplier_name IS NULL THEN
      RAISE EXCEPTION 'Fornecedor obrigatório.';
    END IF;

    INSERT INTO accounts_payable (
      id, organization_id, supplier_id, supplier_name, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count,
      notes, created_by, origin_type, supplier_invoice_date
    ) VALUES (
      v_title_id, v_org, v_supplier_id, v_supplier_name, v_desc, v_category, v_cc,
      v_total, v_issue, v_first_due, v_count,
      v_notes, v_uid, 'MANUAL', v_supplier_invoice_date
    ) RETURNING id INTO v_title_id;

    v_table  := 'accounts_payable_installments';
    v_fk_col := 'payable_id';
  END IF;

  -- Parcelas personalizadas já inseridas inicialmente pelo trigger.
  IF v_installments IS NOT NULL AND jsonb_typeof(v_installments) = 'array' THEN
    INSERT INTO financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
    VALUES (v_table, v_title_id, 'FINANCIAL_INSTALLMENTS_CUSTOMIZED', NULL,
            jsonb_build_object('installment_count', v_count, 'total_amount', v_total), v_uid);
  END IF;

  INSERT INTO financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES (
    CASE WHEN p_kind='receivable' THEN 'accounts_receivable' ELSE 'accounts_payable' END,
    v_title_id,
    CASE WHEN p_kind='receivable' THEN 'AR_MANUAL_CREATED' ELSE 'AP_MANUAL_CREATED' END,
    NULL,
    jsonb_build_object(
      'total_amount', v_total,
      'installment_count', v_count,
      'first_due_date', v_first_due,
      'category_id', v_category
    ),
    v_uid
  );

  RETURN jsonb_build_object(
    'success', true,
    'kind', p_kind,
    'title_id', v_title_id,
    'installment_count', v_count,
    'total_amount', v_total
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_b2b_credit(p_partner_order_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_order public.partner_orders%ROWTYPE;
  v_final_status public.partner_order_status;
  v_final_reason text;
BEGIN

  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')
          OR public.has_role(v_uid,'financeiro')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT * INTO v_order FROM public.partner_orders
   WHERE id = p_partner_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
  -- Re-validate authority after the row-lock wait (READ COMMITTED sees revocations committed meanwhile).
  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')
          OR public.has_role(v_uid,'financeiro')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1') THEN RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501'; END IF;

  IF v_order.status IN ('aprovado','reprovado','cancelado') THEN
    RAISE EXCEPTION 'already_processed: pedido já está em status %', v_order.status;
  END IF;

  IF v_order.status = 'em_analise_comercial' THEN
    RAISE EXCEPTION 'already_released: crédito já liberado, pedido em análise comercial';
  END IF;

  IF v_order.status <> 'aguardando_aprovacao_credito' THEN
    RAISE EXCEPTION 'invalid_status: %', v_order.status;
  END IF;

  -- H4-003: autoriza gravacao dos campos credit_approved_by/at nesta transacao.
  PERFORM set_config('arbio.b2b_credit_approval', 'on', true);

  UPDATE public.partner_orders SET
    status = 'em_analise_comercial',
    ready_for_production = false,
    approved_by = NULL,
    approved_at = NULL,
    credit_approved_by = COALESCE(credit_approved_by, v_uid),
    credit_approved_at = COALESCE(credit_approved_at, now()),
    credit_approval_notes = COALESCE(NULLIF(p_notes, ''), credit_approval_notes),
    credit_block_reason = NULL,
    updated_at = now()
  WHERE id = p_partner_order_id
    AND status = 'aguardando_aprovacao_credito';

  PERFORM set_config('arbio.b2b_credit_approval', 'off', true);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'concurrent_update: status do pedido mudou durante a aprovação';
  END IF;

  SELECT status, credit_block_reason INTO v_final_status, v_final_reason
  FROM public.partner_orders WHERE id = p_partner_order_id;

  IF v_final_status <> 'em_analise_comercial' THEN
    RAISE EXCEPTION 'credit_release_failed: %', COALESCE(v_final_reason, 'status_nao_liberado');
  END IF;

  INSERT INTO public.partner_order_audit_logs(usuario_id, partner_id, order_id, acao, dados_anteriores, dados_novos)
  VALUES (v_uid, v_order.partner_id, p_partner_order_id, 'credito_aprovado',
          jsonb_build_object('status', v_order.status, 'reason', v_order.credit_block_reason),
          jsonb_build_object('status', v_final_status, 'approved_by', v_uid, 'notes', p_notes));

  RETURN jsonb_build_object('ok', true, 'order_id', p_partner_order_id, 'status', v_final_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_create_notificacao_operacional(_usuario_id uuid, _tipo text, _titulo text, _mensagem text DEFAULT NULL::text, _link text DEFAULT NULL::text, _source_type text DEFAULT NULL::text, _source_id uuid DEFAULT NULL::uuid, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  new_id uuid; existing_id uuid;
  caller_uid uuid := auth.uid();
  st text := lower(coalesce(_source_type, ''));
  allowed_source_types text[] := ARRAY['registros_consultor','registro_consultor','monitoramento_vencido','internal_cron'];
  allowed_tipos text[] := ARRAY[
    'alerta','informativo','recomendacao','sistema','sla','erro',
    'retorno_programado','confirmacao_retorno','aprovacao_urgente',
    'aprovacao_recomendacao','urgencia_critica',
    'nova_solicitacao','nova_reserva','nova_demanda_producao','simulacao_enviada',
    'b2b_payment_terms','b2b_payment_terms_pending',
    'pedido_b2b','pedido_b2b_novo','pedido_b2b_aprovado','pedido_b2b_reprovado',
    'pedido_b2b_previsao','pedido_b2b_itens_pendentes',
    'em_producao','produzido','entregue','remarcacao_solicitada',
    'confirmada','critica','nova_confirmacao'
  ];
  is_admin_caller boolean := false; is_staff_caller boolean := false; is_authorized boolean := false;
  v_rc_owner uuid; v_rc_created_by uuid; v_rc_finalized_by uuid; v_rc_cli uuid;
BEGIN

  IF auth.uid() IS NULL OR public.h15_actor_organization() IS NULL
   OR public.h15_actor_organization() IS DISTINCT FROM platform_private.notification_source_org(lower(coalesce(_source_type,'')),_source_id)
   OR NOT COALESCE(platform_private.notification_user_ok(_usuario_id,public.h15_actor_organization()),false)
   OR _tipo = 'sistema' THEN RAISE EXCEPTION 'NOTIF_SOURCE_RECIPIENT_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NOT NULL THEN
   IF length(_idempotency_key) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'NOTIF_INVALID_KEY' USING ERRCODE='22023'; END IF;
   _idempotency_key := 'np1:'||md5(jsonb_build_array(public.h15_actor_organization(),auth.uid(),_usuario_id,_source_type,_source_id,_idempotency_key)::text);
   PERFORM pg_advisory_xact_lock(hashtextextended(_idempotency_key,0));
   IF EXISTS(SELECT 1 FROM public.notificacoes_operacionais n WHERE n.idempotency_key=_idempotency_key AND (n.usuario_id IS DISTINCT FROM _usuario_id OR n.source_type IS DISTINCT FROM _source_type OR n.source_id IS DISTINCT FROM _source_id OR n.tipo IS DISTINCT FROM _tipo OR n.titulo IS DISTINCT FROM _titulo OR n.mensagem IS DISTINCT FROM _mensagem OR n.link IS DISTINCT FROM _link)) THEN RAISE EXCEPTION 'NOTIF_REPLAY_CONFLICT' USING ERRCODE='22023'; END IF;
  END IF;
  IF _usuario_id IS NULL OR _tipo IS NULL OR _titulo IS NULL THEN
    RAISE EXCEPTION 'usuario_id, tipo e titulo são obrigatórios' USING ERRCODE = '22023';
  END IF;
  IF NOT (_tipo = ANY(allowed_tipos)) THEN
    RAISE EXCEPTION 'Tipo % não permitido', _tipo USING ERRCODE = '22023';
  END IF;
  IF char_length(_titulo) > 200 THEN
    RAISE EXCEPTION 'Título excede 200 caracteres' USING ERRCODE = '22023';
  END IF;
  IF _mensagem IS NOT NULL AND char_length(_mensagem) > 2000 THEN
    RAISE EXCEPTION 'Mensagem excede 2000 caracteres' USING ERRCODE = '22023';
  END IF;
  IF _link IS NOT NULL AND (length(_link)>501 OR _link !~ '^/[A-Za-z0-9_\-./?=&%#]*$' OR _link LIKE '//%' OR _link LIKE '%..%') THEN
    RAISE EXCEPTION 'Link inválido' USING ERRCODE = '22023';
  END IF;
  IF _idempotency_key IS NOT NULL AND char_length(_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'idempotency_key excede 200 caracteres' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE user_id = _usuario_id) THEN
    RAISE EXCEPTION 'Destinatário inexistente' USING ERRCODE = '23503';
  END IF;

  IF caller_uid IS NOT NULL THEN
    IF _source_type IS NULL OR _source_id IS NULL THEN
      RAISE EXCEPTION 'source_type e source_id são obrigatórios' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF _source_type IS NOT NULL AND NOT (st = ANY(allowed_source_types)) THEN
    RAISE EXCEPTION 'source_type % fora da whitelist', _source_type USING ERRCODE = '22023';
  END IF;

  IF caller_uid IS NULL THEN
    RAISE EXCEPTION 'Identidade obrigatória' USING ERRCODE = '42501';
  ELSE
    is_admin_caller := has_role(caller_uid, 'administrador'::app_role);
    is_staff_caller := is_admin_caller
      OR has_role(caller_uid, 'gestor'::app_role)
      OR has_role(caller_uid, 'administrativo'::app_role)
      OR has_role(caller_uid, 'consultor_tecnico'::app_role)
      OR has_role(caller_uid, 'tecnico_agronomo'::app_role)
      OR has_role(caller_uid, 'aplicador'::app_role)
      OR has_role(caller_uid, 'producao'::app_role)
      OR has_role(caller_uid, 'financeiro'::app_role);
    IF NOT is_staff_caller THEN
      RAISE EXCEPTION 'Sem papel operacional' USING ERRCODE = '42501';
    END IF;
    IF is_admin_caller THEN
      is_authorized := true;
    ELSE
      IF st IN ('registros_consultor','registro_consultor') THEN
        SELECT consultor_responsavel, created_by, finalized_by, cliente_id
          INTO v_rc_owner, v_rc_created_by, v_rc_finalized_by, v_rc_cli
          FROM public.registros_consultor WHERE id = _source_id;
        IF v_rc_owner IS NULL AND v_rc_cli IS NULL THEN
          RAISE EXCEPTION 'source_id não encontrado em registros_consultor' USING ERRCODE = '23503';
        END IF;
        IF caller_uid = v_rc_owner OR caller_uid = v_rc_created_by OR caller_uid = v_rc_finalized_by
           OR EXISTS (SELECT 1 FROM public.registros_consultor_status_log sl
                       WHERE sl.registro_consultor_id = _source_id AND sl.changed_by = caller_uid)
        THEN
          IF _tipo = 'retorno_programado' THEN
            is_authorized := (_usuario_id = caller_uid OR _usuario_id = v_rc_owner);
          ELSIF _tipo IN ('aprovacao_urgente','aprovacao_recomendacao') THEN
            is_authorized := has_role(_usuario_id, 'gestor'::app_role)
              OR has_role(_usuario_id, 'administrador'::app_role)
              OR has_role(_usuario_id, 'administrativo'::app_role);
          ELSE
            is_authorized := (_usuario_id = caller_uid OR _usuario_id = v_rc_owner);
          END IF;
        END IF;
      ELSIF st IN ('monitoramento_vencido','internal_cron') THEN
        RAISE EXCEPTION 'source_type % reservado ao cron interno', _source_type USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  IF NOT is_authorized THEN
    RAISE EXCEPTION 'Sem autorização para este evento' USING ERRCODE = '42501';
  END IF;

  IF _idempotency_key IS NOT NULL THEN
    SELECT id INTO existing_id FROM public.notificacoes_operacionais
     WHERE idempotency_key = _idempotency_key LIMIT 1;
    IF existing_id IS NOT NULL THEN
      RETURN jsonb_build_object('created', false, 'duplicated', true, 'notification_id', existing_id);
    END IF;
  END IF;

  INSERT INTO public.notificacoes_operacionais
    (usuario_id, tipo, titulo, mensagem, link, source_type, source_id, idempotency_key)
  VALUES
    (_usuario_id, _tipo, _titulo, _mensagem, _link, _source_type, _source_id, _idempotency_key)
  RETURNING id INTO new_id;

  RETURN jsonb_build_object('created', true, 'duplicated', false, 'notification_id', new_id);
EXCEPTION WHEN unique_violation THEN
  SELECT id INTO existing_id FROM public.notificacoes_operacionais
   WHERE idempotency_key = _idempotency_key LIMIT 1;
  RETURN jsonb_build_object('created', false, 'duplicated', true, 'notification_id', existing_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_converter_visita_em_os(p_registro_id uuid, p_observacao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_registro RECORD;
  v_rec RECORD;
  v_rec_count int;
  v_rec_ids uuid[];
  v_remaining int;
  v_existing_os RECORD;
  v_new_os_id uuid;
  v_new_numero text;
  v_status_anterior text;
  v_solic_id uuid;
  v_is_consultor_resp boolean;
  v_has_admin boolean;
  v_has_gestor boolean;
  v_has_consultor boolean;
  v_has_tecnico boolean;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não autenticado');
  END IF;

  -- H9-D-L4: gate de capacidade ANTES de qualquer leitura do registro.
  -- Fecha o oráculo de existência (não-encontrado vs sem-permissão) para
  -- identidades sem papel de domínio de visita técnica.
  IF NOT (
    public.has_role(v_user_id, 'administrador'::app_role)
    OR public.has_role(v_user_id, 'gestor'::app_role)
    OR public.has_role(v_user_id, 'consultor_tecnico'::app_role)
    OR public.has_role(v_user_id, 'tecnico_agronomo'::app_role)
  ) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Sem permissão para converter esta visita.');
  END IF;

  -- Scope before lookup, status or replay; global role alone is not tenant access.
  IF NOT COALESCE(public.can_manage_technical_visit(v_user_id, p_registro_id), false) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Sem permissão para converter esta visita.');
  END IF;

  -- H9-D-L4-R2: resolução ESCOPADA ao chamador em UMA única consulta.
  -- Inexistente e alheio produzem a MESMA resposta genérica, sem revelar existência.
  v_has_admin    := public.has_role(v_user_id, 'administrador'::app_role);
  v_has_gestor   := public.has_role(v_user_id, 'gestor'::app_role);
  v_has_consultor:= public.has_role(v_user_id, 'consultor_tecnico'::app_role);
  v_has_tecnico  := public.has_role(v_user_id, 'tecnico_agronomo'::app_role);

  SELECT * INTO v_registro
    FROM public.registros_consultor rc
   WHERE rc.id = p_registro_id
     AND (
       v_has_admin
       OR v_has_gestor
       OR ((v_has_consultor OR v_has_tecnico) AND rc.consultor_responsavel = v_user_id)
     ) FOR UPDATE;

  IF v_registro IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Sem permissão para converter esta visita.');
  END IF;
  -- Revalida após aguardar o lock: alteração concorrente de escopo não autoriza replay.
  IF NOT COALESCE(public.can_manage_technical_visit(v_user_id, p_registro_id), false) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Sem permissão para converter esta visita.');
  END IF;

  v_is_consultor_resp := (v_registro.consultor_responsavel = v_user_id);

  -- OS já existente → retorno idempotente
  SELECT id, numero_os INTO v_existing_os
    FROM public.ordens_servico_onfarm
   WHERE registro_consultor_id = p_registro_id
   LIMIT 1;

  IF v_existing_os.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_exists', true,
      'os_id', v_existing_os.id,
      'numero_os', v_existing_os.numero_os,
      'registro_id', p_registro_id,
      'message', 'OS já existente para esta visita.'
    );
  END IF;

  -- Validações de status
  IF v_registro.status::text = 'arquivado' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Visita arquivada não pode gerar OS.');
  END IF;
  IF v_registro.status::text = 'convertido_os' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Visita já foi convertida em OS.');
  END IF;
  IF v_registro.status::text <> 'aprovado' THEN
    RETURN jsonb_build_object('success', false,
      'message', 'Apenas visitas com recomendação aprovada podem ser convertidas em OS.');
  END IF;

  -- Campos obrigatórios
  IF v_registro.cliente_id IS NULL
     OR v_registro.fazenda_id IS NULL
     OR v_registro.talhao_id  IS NULL THEN
    RETURN jsonb_build_object('success', false,
      'message', 'Visita sem cliente, fazenda ou talhão definidos.');
  END IF;

  -- A intenção explícita é a única seleção; created_at não autoriza nem escolhe.
  -- Lock do pai já adquirido: writers canônicos e trigger abaixo serializam no mesmo pai.
  SELECT array_agg(id ORDER BY id) INTO v_rec_ids
    FROM public.registros_consultor_recomendacoes
   WHERE registro_consultor_id = p_registro_id AND encaminhar_para_os IS TRUE;
  v_rec_count := coalesce(cardinality(v_rec_ids), 0);
  IF v_rec_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'code', 'LAB_VISIT_NO_SELECTION',
      'message', 'Revise a visita e marque uma recomendação biológica ou um microrganismo para encaminhar à OS.');
  END IF;
  IF v_rec_count <> 1 THEN
    RETURN jsonb_build_object('success', false, 'code', 'LAB_VISIT_MULTIPLE_SELECTIONS',
      'message', 'Há mais de uma recomendação encaminhada. Revise os encaminhamentos e mantenha apenas uma para esta visita.');
  END IF;
  SELECT * INTO v_rec FROM public.registros_consultor_recomendacoes
   WHERE id = v_rec_ids[1] AND registro_consultor_id = p_registro_id FOR UPDATE;
  -- Catálogo próprio continua contido; sem inferência de ownership/família do histórico.
  IF v_rec.produto_biologico_sugerido_id IS NOT NULL THEN
    PERFORM 1 FROM public.produtos p WHERE p.id=v_rec.produto_biologico_sugerido_id
      AND p.ativo IS TRUE AND (to_jsonb(p)->>'owner_organization_id') IS NULL FOR SHARE;
  ELSE
    PERFORM 1 FROM public.microrganismos m WHERE m.id=v_rec.microrganismo_id
      AND m.ativo IS TRUE AND (to_jsonb(m)->>'owner_organization_id') IS NULL FOR SHARE;
  END IF;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'LAB_VISIT_SELECTION_CONFLICT',
      'message', 'O item encaminhado não está disponível para produção. Revise a recomendação, sem alterar o histórico automaticamente.');
  END IF;
  -- Revalida família sob lock do catálogo, não antes dele.
  IF NOT platform_private.lab_item_is_manufacturable(v_rec.produto_biologico_sugerido_id, v_rec.microrganismo_id) THEN
    RETURN jsonb_build_object('success', false, 'code', 'LAB_VISIT_SELECTION_CONFLICT',
      'message', 'Revise o encaminhamento: selecione somente um produto biológico ou somente um microrganismo. Químicos, adubos e itens sem família não geram produção.');
  END IF;
  IF coalesce(btrim(v_rec.recomendacao_tecnica), '') = ''
     AND coalesce(btrim(v_rec.observacoes_finais), '') = ''
     AND coalesce(btrim(v_rec.estrategia_manejo::text), '') = '' THEN
    RETURN jsonb_build_object('success', false, 'code', 'LAB_VISIT_EMPTY_RECOMMENDATION',
      'message', 'Preencha a recomendação técnica encaminhada antes de gerar a OS.');
  END IF;
  SELECT count(*) INTO v_remaining FROM public.registros_consultor_recomendacoes
    WHERE registro_consultor_id=p_registro_id AND id<>v_rec.id;

  v_status_anterior := v_registro.status::text;
  v_solic_id := v_registro.solicitacao_id;

  -- Inserir OS On-Farm (status inicial: aberta)
  INSERT INTO public.ordens_servico_onfarm (
    cliente_id, fazenda_id, talhao_id, produto_id, microrganismo_id,
    area_hectares, modo_aplicacao,
    prioridade, status,
    registro_consultor_id, solicitacao_id, consultor_responsavel, cultura_id,
    fase_fenologica, problema_principal, diagnostico, recomendacao_tecnica,
    observacoes_adicionais, created_by
  ) VALUES (
    v_registro.cliente_id, v_registro.fazenda_id, v_registro.talhao_id,
    v_rec.produto_biologico_sugerido_id, v_rec.microrganismo_id,
    v_registro.area_hectares,
    v_rec.modo_aplicacao,
    'media', 'aberta',
    p_registro_id, v_solic_id, v_registro.consultor_responsavel, v_registro.cultura_id,
    v_registro.fase_fenologica, v_registro.problema_principal, NULL,
    coalesce(v_rec.recomendacao_tecnica, v_rec.observacoes_finais, v_rec.estrategia_manejo::text),
    p_observacao, v_user_id
  )
  RETURNING id, numero_os INTO v_new_os_id, v_new_numero;

  -- convertido_os representa encaminhamento singular, NÃO conclusão das linhas comerciais.
  UPDATE public.registros_consultor
     SET status = 'convertido_os', updated_at = now()
   WHERE id = p_registro_id;

  -- Atualizar solicitação
  IF v_solic_id IS NOT NULL THEN
    UPDATE public.portal_solicitacoes
       SET status = 'aguardando_os', updated_at = now()
     WHERE id = v_solic_id AND status NOT IN ('concluida','cancelada');

    INSERT INTO public.solicitacoes_timeline
      (solicitacao_id, tipo_evento, descricao, usuario_id)
    VALUES
      (v_solic_id, 'convertida_os',
       'Uma recomendação encaminhada à OS On-Farm ' || coalesce(v_new_numero, v_new_os_id::text),
       v_user_id);
  END IF;

  -- Logs
  INSERT INTO public.registros_consultor_status_log
    (registro_consultor_id, status_anterior, status_novo, motivo, changed_by, changed_at)
  VALUES
    (p_registro_id, v_status_anterior, 'convertido_os',
     'Encaminhamento da recomendação ' || v_rec.id::text || ' à OS; demais recomendações preservadas', v_user_id, now());

  INSERT INTO public.visitas_logs
    (registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES
    (p_registro_id, v_solic_id, 'os_gerada',
     'Visita convertida em OS On-Farm ' || coalesce(v_new_numero, v_new_os_id::text),
     v_user_id,
     jsonb_build_object('os_id', v_new_os_id, 'numero_os', v_new_numero,
       'recomendacao_id', v_rec.id, 'recomendacao_versao', v_rec.versao,
       'selection_snapshot', to_jsonb(v_rec), 'remaining_recommendations', v_remaining,
       'selection_rule', 'explicit_single_manufacturable', 'commercial_completed', false));

  RETURN jsonb_build_object(
    'success', true,
    'already_exists', false,
    'message', 'OS On-Farm gerada com sucesso.',
    'os_id', v_new_os_id,
    'numero_os', v_new_numero,
    'registro_id', p_registro_id,
    'solicitacao_id', v_solic_id,
    'status_anterior', v_status_anterior,
    'status_novo', 'convertido_os', 'recomendacao_id', v_rec.id,
    'remaining_recommendations', v_remaining, 'commercial_completed', false
  );
EXCEPTION WHEN OTHERS THEN
  -- O sub-bloco PL/pgSQL desfaz todas as escritas antes de retornar falha.
  -- Nunca interpretar conflito em OUTRA constraint como replay bem-sucedido com OS nula.
  RETURN jsonb_build_object('success', false, 'code', 'LAB_VISIT_CONVERSION_FAILED',
    'message', 'Não foi possível encaminhar a recomendação. Nenhuma alteração foi mantida; revise a visita e tente novamente.');
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_desativar_payment_method(p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE='insufficient_privilege';
  END IF;
  UPDATE payment_methods SET active = false WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Forma de pagamento não encontrada.'; END IF;
  INSERT INTO financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
  VALUES ('payment_methods', p_id, 'PAYMENT_METHOD_DEACTIVATED',
          jsonb_build_object('active', false), auth.uid(), p_reason);
END$function$

CREATE OR REPLACE FUNCTION platform_private.c2_owner_order_create_allowed(_uid uuid, _partner uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c jsonb;
BEGIN
  -- c2_ord_writer_v1: nunca confia em parâmetro de uid que não seja o JWT atual.
  IF _uid IS NULL OR _partner IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RETURN false; END IF;
  -- Gestor B2B vigente (user_roles canônico; revogação remove a linha). Técnico isolado nunca compra.
  IF NOT public.has_role(_uid,'parceiro_b2b'::public.app_role) THEN RETURN false; END IF;
  c := platform_private.b2b_commercial_context();
  IF c IS NULL OR c->>'contract' <> 'C2_MULTIPROFILE_V1' OR c->>'mode' <> 'commercial_owner'
     OR (c->>'partner_id')::uuid IS DISTINCT FROM _partner OR COALESCE((c->>'manager')::boolean,false) IS NOT TRUE THEN
    RETURN false;
  END IF;
  -- Cliente comercial = sem organização própria; tenant dono ativo e coerente com perfil/vínculo.
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.partner_account_id = _partner) THEN RETURN false; END IF;
  IF NOT COALESCE(platform_private.b2b_phase1_partner_visible(_partner,true),false) THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_users pu
      JOIN public.partner_accounts pa ON pa.id = pu.partner_id
      JOIN public.profiles p ON p.user_id = pu.user_id
      JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id
     WHERE pu.user_id = _uid AND pu.partner_id = _partner
       AND pu.revoked_at IS NULL AND (pu.valid_from IS NULL OR pu.valid_from <= now())
       AND pa.ativo AND pa.deleted_at IS NULL AND o.ativo AND o.status = 'ativa'
       AND (o.partner_account_id IS NULL OR o.partner_account_id = _partner)
       AND p.ativo AND p.organization_id = pu.tenant_id AND pu.tenant_id = o.id
       AND (c->>'tenant_id')::uuid = o.id
       AND public.is_valid_b2b_partner_user(_uid, pa.id)) THEN
    RETURN false;
  END IF;
  RETURN EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'pedidos_b2b')
     AND EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'catalogo_precos');
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_lane_enqueue_solicitacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_out uuid:=gen_random_uuid(); v_ev uuid:=gen_random_uuid(); v_num text; v_ver bigint; v_idem text; v_by uuid; j platform_private.tenant_smtp_dispatch_jobs;
BEGIN
 IF OLD.consultor_atribuido IS NOT NULL OR NEW.consultor_atribuido IS NULL THEN RETURN NULL; END IF;
 BEGIN
  SELECT c.organization_id INTO v_org FROM public.clientes c WHERE c.id=NEW.cliente_id;
  IF v_org IS NULL OR NOT platform_private.tenant_smtp_lane_ready(v_org) THEN RETURN NULL; END IF;
  IF platform_private.tenant_smtp_lane_source_reason(NEW.id,NEW.cliente_id,v_org,NEW.consultor_atribuido) IS NOT NULL THEN RETURN NULL; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('tenant_smtp_lane_enqueue:'||v_org::text,0));
  IF (SELECT count(*) FROM platform_private.tenant_smtp_dispatch_jobs WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '1 hour')>=50 THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_jobs WHERE contract='solicitacao_atribuida_consultor_v1' AND source_id=NEW.id AND recipient_user_id=NEW.consultor_atribuido) THEN RETURN NULL; END IF;
  v_num:=left(regexp_replace(coalesce(NEW.numero_solicitacao::text,''),'[^A-Za-z0-9/._-]','','g'),40);
  SELECT version INTO v_ver FROM public.communication_tenant_email_settings WHERE organization_id=v_org;
  SELECT changed_by INTO v_by FROM platform_private.tenant_smtp_activation WHERE organization_id=v_org AND active;
  v_idem:='tsmtp:sa:'||NEW.id::text||':'||NEW.consultor_atribuido::text;
  INSERT INTO public.comunicacao_eventos(id,event_key,source_type,source_id,payload,occurred_at,created_by,idempotency_key,status,processed_at,outbox_enqueued,outbox_skipped)
   VALUES(v_ev,'tenant.smtp.solicitacao_atribuida','portal_solicitacoes',NEW.id,jsonb_build_object('contract','solicitacao_atribuida_consultor_v1'),clock_timestamp(),auth.uid(),v_idem,'processed',clock_timestamp(),1,0);
  INSERT INTO platform_private.tenant_smtp_dispatch_insert_tickets VALUES(v_out,txid_current(),v_org,NEW.consultor_atribuido,NEW.id);
  INSERT INTO public.comunicacao_outbox(id,event_id,template_chave,template_versao,template_snapshot,canal,recipient_user_id,payload_snapshot,status,attempts,max_attempts,locked_by,idempotency_key)
   VALUES(v_out,v_ev,'solicitacao_atribuida_consultor_v1',1,jsonb_build_object('canal','email','contract','solicitacao_atribuida_consultor_v1'),'email',NEW.consultor_atribuido,
    jsonb_strip_nulls(jsonb_build_object('numero',nullif(v_num,''),'tipo_demanda',left(NEW.tipo_demanda::text,40),'urgencia',left(NEW.urgencia::text,20))),
    'processing',0,1,'tenant_smtp_lane',v_idem);
  DELETE FROM platform_private.tenant_smtp_dispatch_insert_tickets WHERE outbox_id=v_out;
  IF NOT EXISTS(SELECT 1 FROM public.comunicacao_outbox WHERE id=v_out) THEN RAISE EXCEPTION 'lane_insert_contained'; END IF;
  INSERT INTO platform_private.tenant_smtp_dispatch_jobs(outbox_id,organization_id,contract,source_id,cliente_id,recipient_user_id,version,activated_by,state)
   VALUES(v_out,v_org,'solicitacao_atribuida_consultor_v1',NEW.id,NEW.cliente_id,NEW.consultor_atribuido,v_ver,v_by,'queued') RETURNING * INTO j;
  PERFORM platform_private.tenant_smtp_lane_log(j,'enqueued',NULL,auth.uid());
 EXCEPTION WHEN OTHERS THEN RETURN NULL;
 END;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_criar_embalagens_pos_envase(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_qtd int := COALESCE((p_payload->>'quantidade_embalagens')::int, 0);
  v_lote uuid := (p_payload->>'lote_id')::uuid;
  v_volume numeric := (p_payload->>'volume')::numeric;
  v_unidade text := COALESCE(p_payload->>'unidade','L');
  v_gerar_et bool := COALESCE((p_payload->>'gerar_etiqueta_automaticamente')::bool, false);
  v_envase uuid := NULLIF(p_payload->>'envase_id','')::uuid;
  v_produto uuid := NULLIF(p_payload->>'produto_id','')::uuid;
  v_cliente uuid := NULLIF(p_payload->>'cliente_id','')::uuid;
  v_fazenda uuid := NULLIF(p_payload->>'fazenda_id','')::uuid;
  v_fab date; v_val date;
  v_codigo text; v_emb_id uuid; v_etq_id uuid;
  v_arr jsonb := '[]'::jsonb;
  v_meta jsonb;
  v_produto_warning bool := false;
  v_warnings jsonb := '[]'::jsonb;
  i int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(gen_random_uuid()) THEN
    RAISE EXCEPTION 'sem permissão';
  END IF;
  IF v_lote IS NULL THEN RAISE EXCEPTION 'lote_id obrigatório'; END IF;
  IF v_volume IS NULL OR v_volume <= 0 THEN RAISE EXCEPTION 'volume inválido'; END IF;
  IF v_qtd < 1 OR v_qtd > 500 THEN RAISE EXCEPTION 'quantidade entre 1 e 500'; END IF;

  -- Valida referências reais (Fase 2.2)
  IF NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote) THEN
    RAISE EXCEPTION 'Lote informado não existe (%).', v_lote;
  END IF;
  IF v_envase IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.envase WHERE id = v_envase) THEN
    RAISE EXCEPTION 'Envase informado não existe (%).', v_envase;
  END IF;
  IF v_cliente IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = v_cliente) THEN
    RAISE EXCEPTION 'Cliente informado não existe (%).', v_cliente;
  END IF;
  IF v_fazenda IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.fazendas WHERE id = v_fazenda) THEN
    RAISE EXCEPTION 'Fazenda informada não existe (%).', v_fazenda;
  END IF;

  -- Fallback de produto_id a partir do lote
  IF v_produto IS NULL THEN
    SELECT produto_id INTO v_produto FROM public.lotes WHERE id = v_lote;
  END IF;
  IF v_produto IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.produtos WHERE id = v_produto) THEN
    RAISE EXCEPTION 'Produto informado não existe (%).', v_produto;
  END IF;
  IF v_produto IS NULL THEN
    v_produto_warning := true;
    v_warnings := v_warnings || to_jsonb('produto_id_nao_identificado'::text);
  END IF;

  SELECT data_envase INTO v_fab FROM public.envase WHERE id = v_envase;
  IF v_fab IS NULL THEN v_fab := CURRENT_DATE; END IF;
  v_val := v_fab + INTERVAL '6 months';

  FOR i IN 1..v_qtd LOOP
    v_codigo := 'AR-EMB-' || lpad(nextval('public.estoque_embalagem_seq')::text, 6, '0');
    v_meta := jsonb_build_object();
    IF v_produto_warning THEN
      v_meta := v_meta || jsonb_build_object('produto_id_nao_identificado', true);
    END IF;

    INSERT INTO public.estoque_embalagens(
      codigo_embalagem, lote_id, produto_id, envase_id, envase_item_id, volume, unidade, quantidade,
      tipo_embalagem, local_estoque, cliente_id, fazenda_id, fabricado_em, validade_em,
      entrada_estoque_em, criado_por, metadata
    ) VALUES (
      v_codigo, v_lote, v_produto, v_envase,
      NULLIF(p_payload->>'envase_item_id','')::uuid,
      v_volume, v_unidade, 1,
      p_payload->>'tipo_embalagem',
      p_payload->>'local_estoque',
      v_cliente, v_fazenda,
      v_fab, v_val,
      now(), v_uid, v_meta
    ) RETURNING id INTO v_emb_id;

    INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_novo, user_id, metadata)
      VALUES (v_emb_id, 'entrada_estoque', 'em_estoque', v_uid, jsonb_build_object('codigo', v_codigo));

    v_etq_id := NULL;
    IF v_gerar_et THEN
      SELECT (public.rpc_gerar_etiqueta_produto(jsonb_build_object(
        'lote_id', v_lote, 'envase_id', v_envase,
        'produto_id', v_produto,
        'cliente_id', v_cliente,
        'fazenda_id', v_fazenda,
        'volume', v_volume, 'unidade', v_unidade,
        'quantidade_embalagens', 1
      )) ->> 'etiqueta_id')::uuid INTO v_etq_id;

      IF v_etq_id IS NULL THEN
        RAISE EXCEPTION 'Falha ao gerar etiqueta automática para a embalagem. Nenhuma embalagem foi criada. Tente novamente ou gere as embalagens sem etiqueta automática.';
      END IF;

      UPDATE public.estoque_embalagens SET etiqueta_id = v_etq_id WHERE id = v_emb_id;
      UPDATE public.produto_etiquetas SET embalagem_id = v_emb_id WHERE id = v_etq_id;
      INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, user_id, metadata)
        VALUES (v_emb_id, 'etiqueta_vinculada', v_uid, jsonb_build_object('etiqueta_id', v_etq_id));
      INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id, metadata)
        VALUES (v_etq_id, 'etiqueta_gerada', v_uid, jsonb_build_object('embalagem_id', v_emb_id));
    END IF;

    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
      VALUES ('estoque_embalagem', v_emb_id, 'EMB_CREATED', v_uid,
              jsonb_build_object('codigo', v_codigo, 'etiqueta_id', v_etq_id, 'produto_id', v_produto));

    v_arr := v_arr || jsonb_build_object('embalagem_id', v_emb_id, 'codigo_embalagem', v_codigo, 'etiqueta_id', v_etq_id);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'total_embalagens', v_qtd,
    'embalagens', v_arr,
    'warnings', v_warnings
  );
END $function$

CREATE OR REPLACE FUNCTION public.rpc_create_portal_notification_secure(_cliente_id uuid, _tipo text, _titulo text, _mensagem text, _link text DEFAULT NULL::text, _source_type text DEFAULT NULL::text, _source_id uuid DEFAULT NULL::uuid, _idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  new_id uuid; existing_id uuid; caller_uid uuid := auth.uid();
  st text := lower(coalesce(_source_type,''));
  allowed_source_types text[] := ARRAY['registros_consultor','ordem_servico','aplicacao'];
  allowed_tipos public.tipo_notificacao_portal[] := ARRAY['informativo','alerta','entrega','recomendacao','aplicacao','sistema']::public.tipo_notificacao_portal[];
  is_admin_caller boolean := false; is_authorized boolean := false;
  v_rc_cli uuid; v_rc_owner uuid; v_rc_created_by uuid; v_rc_finalized_by uuid;
  v_os_cli uuid; v_apl_cli uuid; v_apl_resp uuid; v_apl_created_by uuid;
BEGIN
  IF caller_uid IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória' USING ERRCODE = '42501';
  END IF;
  IF _cliente_id IS NULL OR _tipo IS NULL OR _titulo IS NULL OR _mensagem IS NULL THEN
    RAISE EXCEPTION 'cliente_id, tipo, titulo e mensagem são obrigatórios' USING ERRCODE = '22023';
  END IF;
  IF (_source_type IS NULL) <> (_source_id IS NULL) THEN
    RAISE EXCEPTION 'source_type e source_id devem ser informados juntos' USING ERRCODE = '22023';
  END IF;
  IF _source_type IS NULL THEN
    RAISE EXCEPTION 'source_type/source_id são obrigatórios' USING ERRCODE = '22023';
  END IF;
  IF NOT (st = ANY(allowed_source_types)) THEN
    RAISE EXCEPTION 'source_type % fora da whitelist', _source_type USING ERRCODE = '22023';
  END IF;
  IF NOT (_tipo::public.tipo_notificacao_portal = ANY(allowed_tipos)) THEN
    RAISE EXCEPTION 'Tipo % não permitido', _tipo USING ERRCODE = '22023';
  END IF;
  IF char_length(_titulo) > 200 THEN RAISE EXCEPTION 'Título excede 200 caracteres' USING ERRCODE='22023'; END IF;
  IF char_length(_mensagem) > 2000 THEN RAISE EXCEPTION 'Mensagem excede 2000 caracteres' USING ERRCODE='22023'; END IF;
  IF _link IS NOT NULL AND _link !~ '^/[A-Za-z0-9_\-./?=&%#]{0,500}$' THEN
    RAISE EXCEPTION 'Link inválido' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = _cliente_id) THEN
    RAISE EXCEPTION 'Cliente inexistente' USING ERRCODE = '23503';
  END IF;

  is_admin_caller := has_role(caller_uid, 'administrador'::app_role);
  IF st = 'registros_consultor' THEN
    SELECT cliente_id, consultor_responsavel, created_by, finalized_by
      INTO v_rc_cli, v_rc_owner, v_rc_created_by, v_rc_finalized_by
      FROM public.registros_consultor WHERE id = _source_id;
    IF v_rc_cli IS NULL THEN RAISE EXCEPTION 'source_id não encontrado' USING ERRCODE='23503'; END IF;
    IF v_rc_cli <> _cliente_id THEN RAISE EXCEPTION 'source_id pertence a outro cliente' USING ERRCODE='42501'; END IF;
    IF is_admin_caller OR caller_uid = v_rc_owner OR caller_uid = v_rc_created_by OR caller_uid = v_rc_finalized_by
       OR EXISTS (SELECT 1 FROM public.registros_consultor_status_log sl
                   WHERE sl.registro_consultor_id = _source_id AND sl.changed_by = caller_uid)
    THEN is_authorized := true; END IF;
  ELSIF st = 'ordem_servico' THEN
    SELECT cliente_id INTO v_os_cli FROM public.ordens_servico WHERE id = _source_id;
    IF v_os_cli IS NULL THEN RAISE EXCEPTION 'source_id não encontrado em ordens_servico' USING ERRCODE='23503'; END IF;
    IF v_os_cli <> _cliente_id THEN RAISE EXCEPTION 'source_id pertence a outro cliente' USING ERRCODE='42501'; END IF;
    IF is_admin_caller THEN is_authorized := true; END IF;
  ELSIF st = 'aplicacao' THEN
    SELECT os.cliente_id, a.responsavel_id, a.created_by
      INTO v_apl_cli, v_apl_resp, v_apl_created_by
      FROM public.aplicacoes a JOIN public.ordens_servico os ON os.id = a.ordem_servico_id
     WHERE a.id = _source_id;
    IF v_apl_cli IS NULL THEN RAISE EXCEPTION 'source_id não encontrado em aplicacoes' USING ERRCODE='23503'; END IF;
    IF v_apl_cli <> _cliente_id THEN RAISE EXCEPTION 'source_id pertence a outro cliente' USING ERRCODE='42501'; END IF;
    IF is_admin_caller OR caller_uid = v_apl_resp OR caller_uid = v_apl_created_by THEN is_authorized := true; END IF;
  END IF;

  IF NOT is_authorized THEN
    RAISE EXCEPTION 'Sem vínculo/papel para notificar cliente por %', _source_type USING ERRCODE='42501';
  END IF;

  IF _idempotency_key IS NOT NULL THEN
    SELECT id INTO existing_id FROM public.portal_notificacoes
     WHERE idempotency_key = _idempotency_key LIMIT 1;
    IF existing_id IS NOT NULL THEN
      RETURN jsonb_build_object('created', false, 'duplicated', true, 'notification_id', existing_id);
    END IF;
  END IF;

  INSERT INTO public.portal_notificacoes
    (cliente_id, tipo, titulo, mensagem, link, created_by, source_type, source_id, idempotency_key)
  VALUES
    (_cliente_id, _tipo::public.tipo_notificacao_portal, _titulo, _mensagem,
     _link, caller_uid, _source_type, _source_id, _idempotency_key)
  RETURNING id INTO new_id;

  RETURN jsonb_build_object('created', true, 'duplicated', false, 'notification_id', new_id);
EXCEPTION WHEN unique_violation THEN
  SELECT id INTO existing_id FROM public.portal_notificacoes
   WHERE idempotency_key = _idempotency_key LIMIT 1;
  RETURN jsonb_build_object('created', false, 'duplicated', true, 'notification_id', existing_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_descartar_embalagem(p_embalagem_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_st text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(p_embalagem_id) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN RAISE EXCEPTION 'motivo obrigatório'; END IF;
  SELECT status INTO v_st FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF v_st = 'entregue' THEN RAISE EXCEPTION 'embalagem já entregue'; END IF;
  UPDATE public.estoque_embalagens SET status='descartado', descartado_em=now(), descartado_por=v_uid, motivo_descarte=p_motivo WHERE id = p_embalagem_id;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_anterior, status_novo, user_id, observacao)
    VALUES (p_embalagem_id, 'descarte', v_st, 'descartado', v_uid, p_motivo);
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, reason)
    VALUES ('estoque_embalagem', p_embalagem_id, 'EMB_DISCARDED', v_uid, p_motivo);
  RETURN jsonb_build_object('success', true);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_register_payable_payment(p_installment_id uuid, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := platform_private.h15_actor_organization();
  v_inst public.accounts_payable_installments%ROWTYPE;
  v_amount numeric; v_disc numeric; v_int numeric; v_pen numeric; v_saldo numeric;
  v_pm uuid; v_ba uuid; v_pay_date date; v_notes text;
  v_has_receipt boolean; v_require_receipt boolean;
  v_payment_id uuid; v_idem text; v_fp text; v_existing record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para registrar pagamento.' USING ERRCODE='insufficient_privilege';
  END IF;

  IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM public.accounts_payable_installments WHERE id=p_installment_id AND organization_id=v_org) THEN
    RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501';
  END IF;
  IF (p_payload ? 'organization_id' AND NULLIF(p_payload->>'organization_id','')::uuid IS DISTINCT FROM v_org)
     OR (p_payload ? 'tenant_id' AND NULLIF(p_payload->>'tenant_id','')::uuid IS DISTINCT FROM v_org) THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_MISMATCH' USING ERRCODE='42501';
  END IF;
  v_idem := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idem IS NULL OR length(v_idem) < 8 THEN
    RAISE EXCEPTION 'FIN_IDEMPOTENCY_REQUIRED: idempotency_key obrigatória (mín. 8 caracteres).'
      USING ERRCODE='check_violation';
  END IF;

  v_fp := public.fn_h6b_payment_fingerprint('payable', p_installment_id, p_payload);

  PERFORM pg_advisory_xact_lock(
    hashtextextended('fin_pay:payable:' || p_installment_id::text || ':' || v_idem, 0));

  SELECT * INTO v_inst FROM public.accounts_payable_installments
   WHERE id = p_installment_id AND organization_id=v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parcela não encontrada.'; END IF;

  SELECT id, request_fingerprint INTO v_existing FROM public.payable_payments
   WHERE installment_id = p_installment_id AND idempotency_key = v_idem;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.request_fingerprint IS NOT NULL AND v_existing.request_fingerprint <> v_fp THEN
      RAISE EXCEPTION 'FIN_IDEMPOTENCY_CONFLICT: mesma idempotency_key com payload divergente.'
        USING ERRCODE='check_violation';
    END IF;
    RETURN v_existing.id;
  END IF;

  IF v_inst.status = 'CANCELED' THEN
    RAISE EXCEPTION 'Parcela cancelada.' USING ERRCODE='check_violation';
  END IF;
  IF v_inst.status = 'PAID' THEN
    RAISE EXCEPTION 'Parcela já quitada.' USING ERRCODE='check_violation';
  END IF;

  v_amount   := COALESCE((p_payload->>'amount_paid')::numeric, 0);
  v_disc     := COALESCE((p_payload->>'discount_amount')::numeric, 0);
  v_int      := COALESCE((p_payload->>'interest_amount')::numeric, 0);
  v_pen      := COALESCE((p_payload->>'penalty_amount')::numeric, 0);
  v_pm       := NULLIF(p_payload->>'payment_method_id','')::uuid;
  v_ba       := NULLIF(p_payload->>'bank_account_id','')::uuid;
  v_pay_date := COALESCE((p_payload->>'payment_date')::date, (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date);
  v_notes    := NULLIF(p_payload->>'notes','');
  v_has_receipt := COALESCE((p_payload->>'has_receipt')::boolean, false);

  IF v_amount::text IN ('NaN','Infinity','-Infinity') OR v_disc::text IN ('NaN','Infinity','-Infinity') OR v_int::text IN ('NaN','Infinity','-Infinity') OR v_pen::text IN ('NaN','Infinity','-Infinity') OR v_disc < 0 OR v_int < 0 OR v_pen < 0 OR v_amount <> round(v_amount,2) OR v_disc <> round(v_disc,2) OR v_int <> round(v_int,2) OR v_pen <> round(v_pen,2) THEN
 RAISE EXCEPTION 'FIN_INVALID_AMOUNT: valores monetários inválidos.' USING ERRCODE='23514';
 END IF;
 IF v_amount <= 0 THEN
    RAISE EXCEPTION 'Valor inválido.' USING ERRCODE='check_violation';
  END IF;
  IF v_pm IS NULL OR NOT EXISTS (SELECT 1 FROM public.payment_methods WHERE id = v_pm AND active) THEN
    RAISE EXCEPTION 'Forma de pagamento inválida ou inativa.' USING ERRCODE='check_violation';
  END IF;
  IF v_ba IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.bank_accounts WHERE id = v_ba AND active) THEN
    RAISE EXCEPTION 'Conta bancária inválida ou inativa.' USING ERRCODE='check_violation';
  END IF;

  v_saldo := v_inst.original_amount + COALESCE(v_inst.interest_amount,0) + COALESCE(v_inst.penalty_amount,0) - COALESCE(v_inst.discount_amount,0) - COALESCE(v_inst.paid_amount,0) + v_int + v_pen - v_disc;
  IF v_amount - v_saldo > 0.005 THEN
    RAISE EXCEPTION 'Valor excede o saldo da parcela (saldo: %).', v_saldo USING ERRCODE='check_violation';
  END IF;

  SELECT require_receipt_on_payable_payment INTO v_require_receipt
    FROM public.financial_settings LIMIT 1;
  IF COALESCE(v_require_receipt,false) AND NOT v_has_receipt THEN
    RAISE EXCEPTION 'Comprovante de pagamento é obrigatório.' USING ERRCODE='check_violation';
  END IF;

  BEGIN
    INSERT INTO public.payable_payments (
      organization_id, installment_id, payment_date, amount_paid, payment_method_id, bank_account_id,
      discount_amount, interest_amount, penalty_amount, notes, created_by,
      idempotency_key, request_fingerprint
    ) VALUES (
      v_org, p_installment_id, v_pay_date, v_amount, v_pm, v_ba,
      v_disc, v_int, v_pen, v_notes, v_uid, v_idem, v_fp
    ) RETURNING id INTO v_payment_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id, request_fingerprint INTO v_existing FROM public.payable_payments
     WHERE installment_id = p_installment_id AND idempotency_key = v_idem;
    IF v_existing.request_fingerprint IS NOT NULL AND v_existing.request_fingerprint <> v_fp THEN
      RAISE EXCEPTION 'FIN_IDEMPOTENCY_CONFLICT: mesma idempotency_key com payload divergente.'
        USING ERRCODE='check_violation';
    END IF;
    RETURN v_existing.id;
  END;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('payable_payments', v_payment_id, 'PAYMENT_REGISTERED',
    jsonb_build_object('installment_id', p_installment_id, 'amount', v_amount,
      'payment_method_id', v_pm, 'bank_account_id', v_ba, 'payment_date', v_pay_date,
      'idempotency_key', v_idem, 'request_fingerprint', v_fp), v_uid);

  RETURN v_payment_id;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_defer_communication_delivery(p_outbox_id uuid, p_worker_id text, p_reason text, p_delay_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_outbox%rowtype; v_role text; v_delay int; v_attempts int;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege'; END IF;
  IF NULLIF(trim(COALESCE(p_worker_id,'')),'') IS NULL THEN RAISE EXCEPTION 'worker_id obrigatório'; END IF;
  v_delay := GREATEST(30, LEAST(3600, COALESCE(p_delay_seconds, 300)));
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'processing' THEN RAISE EXCEPTION 'não estava em processing'; END IF;
  IF r.locked_by IS DISTINCT FROM p_worker_id THEN RAISE EXCEPTION 'lease de outro'; END IF;
  v_attempts := GREATEST(COALESCE(r.attempts,0) - 1, 0);
  UPDATE public.comunicacao_outbox
     SET status='pending', attempts=v_attempts,
         next_attempt_at=now() + make_interval(secs => v_delay),
         error_code='deferred',
         error_message=left(COALESCE(p_reason,''),2000),
         locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
   WHERE id = p_outbox_id;
  RETURN jsonb_build_object('ok',true,'status','deferred','retry_in_seconds',v_delay,'attempts',v_attempts);
END$function$

CREATE OR REPLACE FUNCTION public.rpc_delete_diagnostico_visita(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_registro_id uuid;
  v_status text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- H9-D-L4: capacidade mínima de domínio (uniforme por identidade, sem leitura do recurso).
  IF NOT (
    public.has_role(v_uid, 'administrador'::app_role)
    OR public.has_role(v_uid, 'gestor'::app_role)
    OR public.has_role(v_uid, 'consultor_tecnico'::app_role)
    OR public.has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- H9-D-L4-R: resolução ESCOPADA ao chamador — inexistente e alheio são indistinguíveis.
  SELECT r.id, r.status::text
    INTO v_registro_id, v_status
  FROM public.visita_diagnosticos d
  JOIN public.registros_consultor r ON r.id = d.registro_id
  WHERE d.id = p_id
    AND (
      COALESCE(public.can_manage_technical_visit(v_uid, r.id), false)
      OR COALESCE(r.created_by = v_uid, false)
      OR COALESCE(r.consultor_responsavel = v_uid, false)
      OR COALESCE(public.is_active_visit_participant(v_uid, r.id), false)
    );

  IF v_registro_id IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.is_technical_visit_editable_status(v_status) THEN
    RAISE EXCEPTION 'visita_nao_editavel' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.visita_diagnosticos WHERE id = p_id;
END;
$function$

