CREATE OR REPLACE FUNCTION public.rpc_desvincular_etiqueta_entrega(p_entrega_id uuid, p_etiqueta_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF NOT (
    public.has_role(v_uid,'administrador'::app_role)
    OR public.has_role(v_uid,'gestor'::app_role)
    OR public.has_role(v_uid,'producao'::app_role)
    OR public.has_role(v_uid,'operador_onfarm'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;
  IF coalesce(length(trim(p_motivo)),0) < 3 THEN
    RAISE EXCEPTION 'Motivo obrigatório';
  END IF;

  UPDATE public.entrega_etiquetas
     SET ativo = false,
         desvinculado_em = now(),
         desvinculado_por = v_uid,
         motivo_desvinculacao = p_motivo
   WHERE entrega_id = p_entrega_id
     AND etiqueta_id = p_etiqueta_id
     AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo não encontrado ou já desvinculado';
  END IF;

  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id, payload)
  VALUES (p_etiqueta_id, 'etiqueta_substituida', v_uid,
          jsonb_build_object('entrega_id', p_entrega_id, 'motivo', p_motivo, 'acao','desvinculada'));

  BEGIN
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('produto_etiqueta', p_etiqueta_id, 'LABEL_DELIVERY_UNLINKED',
            jsonb_build_object('entrega_id', p_entrega_id, 'motivo', p_motivo), v_uid, p_motivo);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object('ok', true);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.stock_motor_refs(p_item uuid, p_lote uuid, p_org uuid, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_os uuid:=nullif(p->>'os_id','')::uuid; v_tipo text:=p->>'os_tipo'; v_cliente uuid:=nullif(p->>'cliente_id','')::uuid;
 v_partner uuid:=nullif(p->>'partner_id','')::uuid; v_order uuid:=nullif(p->>'partner_order_id','')::uuid;
 v_ref uuid:=nullif(p->>'referencia_id','')::uuid; v_rt text:=p->>'referencia_tipo'; v_origin uuid:=nullif(p->>'movimentacao_origem_id','')::uuid;
 v_os_cliente uuid; v_os_order uuid;
BEGIN
 IF v_cliente IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=v_cliente AND c.organization_id=p_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_partner IS NOT NULL AND NOT coalesce(public.b2b_phase1_partner_visible(v_partner,false),false) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_order IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.partner_orders o WHERE o.id=v_order AND o.partner_id=v_partner AND public.b2b_phase1_order_visible(o.id)) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_os IS NOT NULL THEN
  IF v_tipo IN ('manual','b2b') THEN
   SELECT o.cliente_id,o.partner_order_id INTO v_os_cliente,v_os_order FROM public.ordens_servico o WHERE o.id=v_os AND o.organization_id=p_org;
   IF NOT FOUND THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
   IF v_tipo='b2b' AND (v_order IS NULL OR v_os_order IS DISTINCT FROM v_order OR v_cliente IS NOT NULL) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
   IF v_tipo='manual' AND (v_os_order IS NOT NULL OR v_partner IS NOT NULL OR v_order IS NOT NULL) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
  ELSIF v_tipo IN ('onfarm','on_farm') THEN
   SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=v_os AND c.organization_id=p_org;
   IF NOT FOUND OR v_partner IS NOT NULL OR v_order IS NOT NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
  ELSE RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
  IF v_cliente IS NOT NULL AND v_cliente IS DISTINCT FROM v_os_cliente THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 END IF;
 IF v_origin IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes m WHERE m.id=v_origin AND m.estoque_produto_id=p_item AND m.lote_id=p_lote AND public.stock_p1_movement_owned(m.estoque_produto_id,m.lote_id)) THEN RAISE EXCEPTION 'ESTQ_ESTORNO_ORIGEM_INVALIDA' USING ERRCODE='42501'; END IF;
 -- Only proven existing guard semantics. Unsupported literals fail even without an ID.
 IF v_rt IS NOT NULL AND v_rt NOT IN ('entrega','ordem_servico','manual','sistema') THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_rt IN ('manual','sistema') AND v_ref IS NOT NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_ref IS NOT NULL AND v_rt IS NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_rt IN ('entrega','ordem_servico') AND v_ref IS NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_rt='ordem_servico' AND (v_os IS NULL OR v_ref IS DISTINCT FROM v_os OR v_tipo NOT IN ('manual','b2b','onfarm','on_farm')) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_rt='entrega' AND NOT EXISTS(SELECT 1 FROM public.entregas e WHERE e.id=v_ref AND e.organization_id=p_org AND e.estoque_produto_id=p_item AND (e.lote_id IS NULL OR e.lote_id=p_lote) AND (v_cliente IS NULL OR e.cliente_id=v_cliente) AND (v_os IS NULL OR (v_tipo IN ('manual','b2b') AND e.ordem_servico_id=v_os) OR (v_tipo IN ('onfarm','on_farm') AND e.ordem_servico_onfarm_id=v_os))) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_dispensar_assinatura_entrega(p_entrega_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_motivo text := nullif(trim(coalesce(p_motivo,'')),'');
  v_comp_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão inválida'; END IF;
  IF NOT (public.has_role(v_uid,'administrador'::app_role)
          OR public.has_role(v_uid,'gestor'::app_role)
          OR public.has_role(v_uid,'administrativo'::app_role)) THEN
    RAISE EXCEPTION 'Apenas admin/gestor/administrativo podem dispensar assinatura';
  END IF;
  IF v_motivo IS NULL OR length(v_motivo) < 5 THEN
    RAISE EXCEPTION 'Motivo é obrigatório (mínimo 5 caracteres)';
  END IF;

  SELECT comprovante_id INTO v_comp_id FROM public.entregas WHERE id = p_entrega_id;
  IF v_comp_id IS NULL THEN
    PERFORM public.rpc_gerar_formulario_entrega(p_entrega_id);
    SELECT comprovante_id INTO v_comp_id FROM public.entregas WHERE id = p_entrega_id;
  END IF;

  UPDATE public.entrega_comprovantes SET
    status = 'confirmado',
    assinatura_tipo = 'dispensada',
    observacoes = coalesce(observacoes,'') || E'\n[DISPENSA] ' || v_motivo,
    validation_hash = encode(extensions.digest(p_entrega_id::text || 'DISP' || now()::text,'sha256'),'hex'),
    confirmado_por = v_uid,
    confirmado_em = now(),
    updated_at = now()
  WHERE id = v_comp_id;

  INSERT INTO public.entrega_ocorrencias (entrega_id, tipo, descricao, gravidade, registrado_por)
  VALUES (p_entrega_id, 'observacao', 'Assinatura dispensada: ' || v_motivo, 'media', v_uid);

  UPDATE public.entregas SET
    comprovante_status = 'dispensado',
    assinatura_tipo = 'dispensada',
    recebimento_confirmado_em = now(),
    recebimento_confirmado_por = v_uid,
    updated_at = now()
  WHERE id = p_entrega_id;



  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, performed_by, reason)
  VALUES ('entrega', p_entrega_id, 'DELIVERY_SIGNATURE_WAIVED', v_uid, v_motivo);

  RETURN jsonb_build_object('success', true);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_assinar_termo_v1(p_termo_id uuid, p_payload jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_t public.entrega_termos%ROWTYPE;
  v_fp text;
  v_rec text := nullif(trim(coalesce(p_payload->>'recebedor_nome','')), '');
  v_tipo text := coalesce(nullif(p_payload->>'assinatura_tipo',''), 'digital_tela');
  v_ahash text := nullif(p_payload->>'assinatura_hash','');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sessao_invalida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'sem_permissao'; END IF;
  IF coalesce(trim(p_idempotency_key),'') = '' THEN RAISE EXCEPTION 'idempotency_key_obrigatoria'; END IF;
  IF v_rec IS NULL THEN RAISE EXCEPTION 'recebedor_nome_obrigatorio'; END IF;
  IF v_tipo <> 'dispensada' AND v_ahash IS NULL THEN RAISE EXCEPTION 'assinatura_hash_obrigatoria'; END IF;

  SELECT * INTO v_t FROM public.entrega_termos WHERE id = p_termo_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'termo_nao_encontrado'; END IF;
  -- Tenant explícito: ator canônico ativo/pronto (h15) e entrega+cliente da mesma empresa.
  IF NOT platform_private.entrega_termo_tenant_ok(v_t.entrega_id) THEN RAISE EXCEPTION 'termo_nao_encontrado'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('entrega_termo:' || v_t.entrega_id::text, 0));
  SELECT * INTO v_t FROM public.entrega_termos WHERE id = p_termo_id FOR UPDATE;
  -- Revalida após os locks (perfil/papel/empresa podem ter mudado durante a espera).
  IF NOT FOUND OR NOT public.is_delivery_staff(v_uid)
     OR NOT platform_private.entrega_termo_tenant_ok(v_t.entrega_id) THEN
    RAISE EXCEPTION 'termo_nao_encontrado';
  END IF;

  v_fp := encode(extensions.digest(
    v_t.snapshot_hash || '|' || v_rec || '|' || coalesce(v_ahash,'') || '|' || v_tipo, 'sha256'), 'hex');

  -- Replay
  IF v_t.status = 'assinado' THEN
    IF v_t.idempotency_key = p_idempotency_key THEN
      IF v_t.request_fingerprint IS DISTINCT FROM v_fp THEN
        RAISE EXCEPTION 'idempotency_payload_mismatch';
      END IF;
      RETURN jsonb_build_object('success', true, 'replay', true, 'termo_id', v_t.id,
                                'versao', v_t.versao, 'snapshot_hash', v_t.snapshot_hash);
    END IF;
    RAISE EXCEPTION 'termo_ja_assinado';
  END IF;

  IF v_t.status <> 'rascunho' THEN RAISE EXCEPTION 'termo_estado_invalido: %', v_t.status; END IF;

  IF EXISTS (SELECT 1 FROM public.entrega_termos
             WHERE entrega_id = v_t.entrega_id AND idempotency_key = p_idempotency_key AND id <> v_t.id) THEN
    RAISE EXCEPTION 'idempotency_key_reutilizada';
  END IF;

  -- O rascunho deve representar os dados atuais, exceto a hora de geração.
  -- O replay acima permanece imutável e não refaz a assinatura.
  PERFORM 1 FROM public.entregas
   WHERE id = v_t.entrega_id AND status <> 'cancelada'
   FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'entrega_invalida'; END IF;

  IF (v_t.snapshot - 'gerado_em') IS DISTINCT FROM
     (public.fn_entrega_build_snapshot_v1(v_t.entrega_id) - 'gerado_em')
     OR v_t.cobertura IS DISTINCT FROM public.fn_entrega_cobertura_v1(v_t.entrega_id) THEN
    RAISE EXCEPTION 'termo_desatualizado: atualize o rascunho antes de assinar';
  END IF;
  IF v_t.snapshot_hash IS DISTINCT FROM
     encode(extensions.digest(v_t.template_versao || '|' || v_t.snapshot::text, 'sha256'), 'hex') THEN
    RAISE EXCEPTION 'termo_integridade_invalida';
  END IF;

  IF v_t.cobertura = 'pendente' AND coalesce((p_payload->>'permitir_pendencia')::boolean, false) IS FALSE THEN
    RAISE EXCEPTION 'cobertura_pendente: conferir todos os itens antes de assinar';
  END IF;

  UPDATE public.entrega_termos SET
    status = 'assinado',
    recebedor_nome = v_rec,
    recebedor_documento = nullif(p_payload->>'recebedor_documento',''),
    recebedor_cargo = nullif(p_payload->>'recebedor_cargo',''),
    recebedor_telefone = nullif(p_payload->>'recebedor_telefone',''),
    assinatura_hash = v_ahash,
    assinatura_tipo = v_tipo,
    assinatura_origem = nullif(p_payload->>'origem',''),
    assinado_em = now(),
    assinado_por = v_uid,
    idempotency_key = p_idempotency_key,
    request_fingerprint = v_fp
  WHERE id = p_termo_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', v_t.entrega_id, 'DELIVERY_TERM_SIGNED',
          jsonb_build_object('termo_id', p_termo_id, 'versao', v_t.versao,
                             'snapshot_hash', v_t.snapshot_hash, 'cobertura', v_t.cobertura), v_uid);

  RETURN jsonb_build_object('success', true, 'replay', false, 'termo_id', p_termo_id,
                            'versao', v_t.versao, 'snapshot_hash', v_t.snapshot_hash,
                            'cobertura', v_t.cobertura);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_cancelar_termo_v1(p_termo_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_t public.entrega_termos%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sessao_invalida'; END IF;
  IF NOT (public.has_role(v_uid,'administrador'::public.app_role)
          OR public.has_role(v_uid,'gestor'::public.app_role)
          OR public.has_role(v_uid,'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;
  IF length(coalesce(trim(p_motivo),'')) < 5 THEN RAISE EXCEPTION 'motivo_obrigatorio'; END IF;

  SELECT * INTO v_t FROM public.entrega_termos WHERE id = p_termo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'termo_nao_encontrado'; END IF;
  -- Tenant explícito: ator canônico ativo/pronto (h15) e entrega+cliente da mesma empresa.
  IF NOT platform_private.entrega_termo_tenant_ok(v_t.entrega_id) THEN RAISE EXCEPTION 'termo_nao_encontrado'; END IF;
  -- Revalida o papel após o lock da linha.
  IF NOT (public.has_role(v_uid,'administrador'::public.app_role)
          OR public.has_role(v_uid,'gestor'::public.app_role)
          OR public.has_role(v_uid,'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;
  IF v_t.status NOT IN ('rascunho','assinado') THEN RAISE EXCEPTION 'termo_estado_invalido: %', v_t.status; END IF;

  UPDATE public.entrega_termos
     SET status = 'cancelado', cancelado_em = now(), cancelado_por = v_uid,
         motivo_cancelamento = trim(p_motivo)
   WHERE id = p_termo_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', v_t.entrega_id, 'DELIVERY_TERM_CANCELLED',
          jsonb_build_object('termo_id', p_termo_id, 'versao', v_t.versao, 'motivo', trim(p_motivo)), v_uid);

  RETURN jsonb_build_object('success', true, 'termo_id', p_termo_id, 'status', 'cancelado');
END $function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_reconciliar_v1(p_entrega_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_e public.entregas%ROWTYPE;
  v_t public.entrega_termos%ROWTYPE;
  v_r public.entrega_reconciliacoes%ROWTYPE;
  v_total int := 0; v_ok int := 0; v_no int := 0; v_pend int := 0;
  v_qtd_ok numeric := 0; v_qtd_no numeric := 0;
  v_vol_ok numeric := 0; v_vol_no numeric := 0;
  v_ratio numeric := 0;
  v_fp text;
  v_item record;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sessao_invalida' USING ERRCODE='insufficient_privilege'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE='insufficient_privilege';
  END IF;
  IF coalesce(trim(p_idempotency_key),'') = '' THEN RAISE EXCEPTION 'idempotency_key_obrigatoria'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('entrega_reconc:' || p_entrega_id::text, 0));

  SELECT * INTO v_e FROM public.entregas WHERE id = p_entrega_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'entrega_nao_encontrada'; END IF;
  IF v_e.status = 'cancelada' THEN RAISE EXCEPTION 'entrega_cancelada'; END IF;

  SELECT * INTO v_t FROM public.entrega_termos
   WHERE entrega_id = p_entrega_id AND status = 'assinado'
   ORDER BY versao DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'termo_nao_assinado'; END IF;

  SELECT count(*)::int,
         count(*) FILTER (WHERE status='aceito')::int,
         count(*) FILTER (WHERE status='recusado')::int,
         count(*) FILTER (WHERE status='pendente')::int,
         coalesce(sum(quantidade) FILTER (WHERE status='aceito'),0),
         coalesce(sum(quantidade) FILTER (WHERE status='recusado'),0)
    INTO v_total, v_ok, v_no, v_pend, v_qtd_ok, v_qtd_no
    FROM public.entrega_conferencia_itens WHERE entrega_id = p_entrega_id;

  IF v_total = 0 THEN RAISE EXCEPTION 'conferencia_ausente'; END IF;
  IF v_pend > 0 THEN RAISE EXCEPTION 'conferencia_pendente: % item(ns) sem decisao', v_pend; END IF;

  v_fp := encode(extensions.digest(
    v_t.snapshot_hash || '|' || v_total::text || '|' || v_ok::text || '|' || v_no::text
    || '|' || v_qtd_ok::text || '|' || v_qtd_no::text, 'sha256'), 'hex');

  SELECT * INTO v_r FROM public.entrega_reconciliacoes
   WHERE entrega_id = p_entrega_id AND status = 'reconciliada';
  IF FOUND THEN
    IF v_r.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
      RAISE EXCEPTION 'entrega_ja_reconciliada';
    END IF;
    IF v_r.request_fingerprint IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'idempotency_payload_mismatch';
    END IF;
    RETURN jsonb_build_object('success', true, 'replay', true,
      'reconciliacao_id', v_r.id, 'itens_aceitos', v_r.itens_aceitos,
      'itens_recusados', v_r.itens_recusados, 'faturavel', v_r.faturavel,
      'ratio_aceito', v_r.ratio_aceito);
  END IF;

  FOR v_item IN
    SELECT ci.id, ci.status, ci.quantidade, ci.motivo, ci.etiqueta_id, ci.embalagem_id
      FROM public.entrega_conferencia_itens ci
     WHERE ci.entrega_id = p_entrega_id
     ORDER BY ci.id
  LOOP
    IF v_item.status = 'aceito' THEN
      IF v_item.embalagem_id IS NOT NULL THEN
        UPDATE public.estoque_embalagens
           SET status = 'entregue', entregue_em = now(), entregue_por = v_uid,
               entrega_id = p_entrega_id, updated_at = now()
         WHERE id = v_item.embalagem_id
           AND status <> 'entregue';

        INSERT INTO public.estoque_embalagem_movimentacoes
          (embalagem_id, tipo_movimentacao, status_anterior, status_novo, origem, destino,
           entrega_id, user_id, observacao, metadata)
        SELECT v_item.embalagem_id, 'entrega_confirmada', 'separado', 'entregue',
               'entrega', 'cliente', p_entrega_id, v_uid,
               'baixa por conferencia aceita',
               jsonb_build_object('conferencia_item_id', v_item.id, 'termo_id', v_t.id);
      END IF;
      IF v_item.etiqueta_id IS NOT NULL THEN
        UPDATE public.produto_etiquetas
           SET entrega_id = p_entrega_id, updated_at = now()
         WHERE id = v_item.etiqueta_id;
      END IF;
    ELSE
      IF v_item.embalagem_id IS NOT NULL THEN
        UPDATE public.estoque_embalagens
           SET status = 'em_estoque', entrega_id = NULL, entrega_item_id = NULL,
               reservado_em = NULL, reservado_por = NULL,
               separado_em = NULL, separado_por = NULL,
               entregue_em = NULL, entregue_por = NULL,
               updated_at = now()
         WHERE id = v_item.embalagem_id;

        INSERT INTO public.estoque_embalagem_movimentacoes
          (embalagem_id, tipo_movimentacao, status_anterior, status_novo, origem, destino,
           entrega_id, user_id, observacao, metadata)
        VALUES (v_item.embalagem_id, 'estorno_recusa', 'separado', 'em_estoque',
                'entrega', 'estoque', p_entrega_id, v_uid,
                left(coalesce(v_item.motivo,'recusa na conferencia'), 240),
                jsonb_build_object('conferencia_item_id', v_item.id, 'termo_id', v_t.id));
      END IF;
      IF v_item.etiqueta_id IS NOT NULL THEN
        UPDATE public.produto_etiquetas
           SET entrega_id = NULL, updated_at = now()
         WHERE id = v_item.etiqueta_id;
      END IF;
    END IF;
  END LOOP;

  SELECT coalesce(sum(ee.volume * ci.quantidade) FILTER (WHERE ci.status='aceito'), 0),
         coalesce(sum(ee.volume * ci.quantidade) FILTER (WHERE ci.status='recusado'), 0)
    INTO v_vol_ok, v_vol_no
    FROM public.entrega_conferencia_itens ci
    LEFT JOIN public.estoque_embalagens ee ON ee.id = ci.embalagem_id
   WHERE ci.entrega_id = p_entrega_id;

  v_ratio := CASE WHEN (v_qtd_ok + v_qtd_no) > 0
                  THEN round(v_qtd_ok / (v_qtd_ok + v_qtd_no), 5) ELSE 0 END;

  INSERT INTO public.entrega_reconciliacoes (
    entrega_id, termo_id, termo_versao, status,
    itens_total, itens_aceitos, itens_recusados,
    quantidade_aceita, quantidade_recusada, volume_aceito, volume_recusado,
    ratio_aceito, faturavel, resumo, idempotency_key, request_fingerprint, reconciliado_por
  ) VALUES (
    p_entrega_id, v_t.id, v_t.versao, 'reconciliada',
    v_total, v_ok, v_no,
    v_qtd_ok, v_qtd_no, v_vol_ok, v_vol_no,
    v_ratio, (v_ok > 0),
    jsonb_build_object(
      'termo_snapshot_hash', v_t.snapshot_hash,
      'cobertura', v_t.cobertura,
      'itens', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                  'conferencia_item_id', ci.id, 'status', ci.status,
                  'quantidade', ci.quantidade) ORDER BY ci.id), '[]'::jsonb)
                FROM public.entrega_conferencia_itens ci WHERE ci.entrega_id = p_entrega_id)
    ),
    p_idempotency_key, v_fp, v_uid
  ) RETURNING id INTO v_id;

  UPDATE public.entregas SET
    status = CASE WHEN v_ok > 0 THEN 'entregue'::status_entrega ELSE status END,
    recebido_por_nome = coalesce(nullif(trim(recebido_por_nome), ''), v_t.recebedor_nome),
    recebido_por_documento = coalesce(recebido_por_documento, v_t.recebedor_documento),
    confirmado_por = coalesce(confirmado_por, v_uid),
    entregue_em = CASE WHEN v_ok > 0 THEN coalesce(entregue_em, now()) ELSE entregue_em END,
    confirmada_em = coalesce(confirmada_em, now()),
    confirmada_por = coalesce(confirmada_por, v_uid),
    quantidade_entregue = v_qtd_ok,
    volume_entregue_ml = v_vol_ok,
    financial_status = CASE WHEN v_ok > 0 THEN 'PENDING_BILLING' ELSE 'NOT_BILLABLE' END,
    not_billable_reason = CASE WHEN v_ok = 0 THEN 'RECUSA_TOTAL_NA_CONFERENCIA' ELSE not_billable_reason END,
    updated_at = now()
  WHERE id = p_entrega_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', p_entrega_id, 'DELIVERY_RECONCILED',
          jsonb_build_object('reconciliacao_id', v_id, 'termo_id', v_t.id,
                             'itens_aceitos', v_ok, 'itens_recusados', v_no,
                             'ratio_aceito', v_ratio, 'faturavel', (v_ok > 0)), v_uid);

  RETURN jsonb_build_object('success', true, 'replay', false, 'reconciliacao_id', v_id,
    'itens_total', v_total, 'itens_aceitos', v_ok, 'itens_recusados', v_no,
    'quantidade_aceita', v_qtd_ok, 'quantidade_recusada', v_qtd_no,
    'ratio_aceito', v_ratio, 'faturavel', (v_ok > 0));
END $function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_reentrega_saldo_v1(p_entrega_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_e public.entregas%ROWTYPE;
  v_new uuid;
  v_n int := 0;
  v_exist uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sessao_invalida' USING ERRCODE='insufficient_privilege'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE='insufficient_privilege';
  END IF;
  IF coalesce(trim(p_idempotency_key),'') = '' THEN RAISE EXCEPTION 'idempotency_key_obrigatoria'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('entrega_reentrega:' || p_entrega_id::text, 0));

  SELECT * INTO v_e FROM public.entregas WHERE id = p_entrega_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'entrega_nao_encontrada'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.entrega_reconciliacoes
                  WHERE entrega_id = p_entrega_id AND status = 'reconciliada') THEN
    RAISE EXCEPTION 'entrega_nao_reconciliada';
  END IF;

  SELECT id INTO v_exist FROM public.entregas WHERE reentrega_origem_id = p_entrega_id;
  IF v_exist IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'entrega_id', v_exist);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.entrega_conferencia_itens
                  WHERE entrega_id = p_entrega_id AND status = 'recusado') THEN
    RAISE EXCEPTION 'sem_saldo_recusado';
  END IF;

  INSERT INTO public.entregas (
    ordem_servico_id, ordem_servico_onfarm_id, cliente_id, produto_id, lote_id,
    status, tipo_entrega, assinatura_obrigatoria, comprovante_status,
    financial_status, reentrega_origem_id, observacoes_confirmacao
  ) VALUES (
    v_e.ordem_servico_id, v_e.ordem_servico_onfarm_id, v_e.cliente_id, v_e.produto_id, v_e.lote_id,
    'separado', coalesce(v_e.tipo_entrega,'motorista'), coalesce(v_e.assinatura_obrigatoria, true), 'pendente',
    'PENDING_BILLING', p_entrega_id,
    'Reentrega do saldo recusado na conferencia da entrega de origem.'
  ) RETURNING id INTO v_new;

  INSERT INTO public.entrega_etiquetas (entrega_id, etiqueta_id, created_by, ativo)
  SELECT v_new, ci.etiqueta_id, v_uid, true
    FROM public.entrega_conferencia_itens ci
   WHERE ci.entrega_id = p_entrega_id AND ci.status = 'recusado' AND ci.etiqueta_id IS NOT NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', p_entrega_id, 'DELIVERY_REDELIVERY_CREATED',
          jsonb_build_object('entrega_reentrega_id', v_new, 'itens', v_n,
                             'idempotency_key', p_idempotency_key), v_uid);

  RETURN jsonb_build_object('success', true, 'replay', false, 'entrega_id', v_new, 'itens', v_n);
END $function$

CREATE OR REPLACE FUNCTION platform_private.stock_motor_item(p_item uuid, p_acao text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_org uuid; v_item public.estoque_produto%ROWTYPE; v_lote public.lotes%ROWTYPE;
BEGIN
 v_org:=platform_private.stock_motor_actor(p_acao);
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR (p_payload ? 'metadata' AND jsonb_typeof(p_payload->'metadata')<>'object') OR p_payload ?| ARRAY['organization_id','tenant_id','usuario_id','user_id','owner_id'] OR coalesce(p_payload->'metadata','{}'::jsonb) ?| ARRAY['stock_request_item','stock_request_actor','stock_request_fp'] THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_payload) e WHERE e.key IN ('motivo','observacao','origem','referencia_tipo','referencia_id','os_id','os_tipo','cliente_id','partner_id','partner_order_id','movimentacao_origem_id','classificacao','sentido','unidade') AND jsonb_typeof(e.value) NOT IN ('string','null')) OR (p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida')) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 -- Scoped lookup never returns a foreign/orphan row, even under DEFINER.
 SELECT e.* INTO v_item FROM public.estoque_produto e JOIN public.lotes l ON l.id=e.lote_id WHERE e.id=p_item AND l.organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT l.* INTO v_lote FROM public.lotes l WHERE l.id=v_item.lote_id AND l.organization_id=v_org;
 IF v_lote.programacao_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.programacao_producao g WHERE g.id=v_lote.programacao_id AND g.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_item.envase_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.envase e WHERE e.id=v_item.envase_id AND e.lote_id=v_item.lote_id AND e.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.stock_motor_refs(p_item,v_item.lote_id,v_org,jsonb_build_object('os_id',v_item.reservado_para_os_id,'os_tipo',v_item.reservado_para_os_tipo,'cliente_id',v_item.reservado_para_cliente_id,'partner_id',v_item.reservado_para_partner_id,'partner_order_id',v_item.reservado_para_partner_order_id));
 PERFORM platform_private.stock_motor_refs(p_item,v_item.lote_id,v_org,p_payload);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_registrar_conferencia_v1(p_entrega_id uuid, p_itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_item jsonb;
  v_etq uuid;
  v_status text;
  v_qtd numeric;
  v_motivo text;
  v_emb uuid;
  v_cq boolean;
  v_n integer := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sessao_invalida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'sem_permissao'; END IF;

  -- Compartilha a trava com geração/assinatura; validar estado depois de adquiri-la.
  PERFORM pg_advisory_xact_lock(hashtextextended('entrega_termo:' || p_entrega_id::text, 0));
  IF NOT EXISTS (SELECT 1 FROM public.entregas WHERE id = p_entrega_id AND status <> 'cancelada') THEN
    RAISE EXCEPTION 'entrega_invalida';
  END IF;
  IF EXISTS (SELECT 1 FROM public.entrega_termos WHERE entrega_id = p_entrega_id AND status = 'assinado') THEN
    RAISE EXCEPTION 'termo_ja_assinado';
  END IF;


  FOR v_item IN SELECT * FROM jsonb_array_elements(coalesce(p_itens, '[]'::jsonb))
  LOOP
    v_etq := nullif(v_item->>'etiqueta_id','')::uuid;
    v_status := coalesce(nullif(v_item->>'status',''), 'pendente');
    v_qtd := coalesce(nullif(v_item->>'quantidade','')::numeric, 1);
    v_motivo := nullif(trim(coalesce(v_item->>'motivo','')), '');

    IF v_etq IS NULL THEN RAISE EXCEPTION 'etiqueta_id_obrigatorio'; END IF;
    IF v_status NOT IN ('aceito','recusado','pendente') THEN
      RAISE EXCEPTION 'status_invalido: %', v_status;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.entrega_etiquetas ee
                   WHERE ee.entrega_id = p_entrega_id AND ee.etiqueta_id = v_etq AND ee.ativo) THEN
      RAISE EXCEPTION 'etiqueta_nao_vinculada_a_entrega';
    END IF;

    SELECT pe.embalagem_id, pe.cq_liberado INTO v_emb, v_cq
    FROM public.produto_etiquetas pe WHERE pe.id = v_etq;

    IF v_status = 'aceito' THEN
      IF EXISTS (SELECT 1 FROM public.produto_etiquetas pe
                 WHERE pe.id = v_etq
                   AND (pe.status IN ('cancelada','substituida')
                        OR (pe.validade_em IS NOT NULL AND pe.validade_em < current_date))) THEN
        RAISE EXCEPTION 'etiqueta_invalida_ou_vencida';
      END IF;
      IF coalesce(v_cq, false) IS FALSE THEN
        RAISE EXCEPTION 'cq_nao_liberado';
      END IF;
      IF v_emb IS NULL THEN
        RAISE EXCEPTION 'embalagem_nao_vinculada_a_etiqueta';
      END IF;
    END IF;

    INSERT INTO public.entrega_conferencia_itens
      (entrega_id, etiqueta_id, embalagem_id, status, quantidade, motivo, conferido_em, conferido_por)
    VALUES (p_entrega_id, v_etq, v_emb, v_status, v_qtd, v_motivo, now(), v_uid)
    ON CONFLICT (entrega_id, etiqueta_id) WHERE etiqueta_id IS NOT NULL
    DO UPDATE SET status = EXCLUDED.status,
                  quantidade = EXCLUDED.quantidade,
                  motivo = EXCLUDED.motivo,
                  embalagem_id = EXCLUDED.embalagem_id,
                  conferido_em = now(),
                  conferido_por = v_uid;
    v_n := v_n + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'itens', v_n,
    'cobertura', public.fn_entrega_cobertura_v1(p_entrega_id));
END $function$

CREATE OR REPLACE FUNCTION public.rpc_upsert_fiscal_invoice_manual(p_receivable_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ar  record;
  v_existing record;
  v_id uuid;
  v_status text;
  v_number text;
  v_series text;
  v_key text;
  v_issue date;
  v_type text;
  v_total numeric(14,2);
  v_delivery uuid;
  v_old jsonb;
  v_action text;
BEGIN
  PERFORM public.h15_require_staff();

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para alterar dados fiscais.' USING ERRCODE='insufficient_privilege';
  END IF;

  SELECT * INTO v_ar FROM accounts_receivable WHERE id = p_receivable_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta a receber não encontrada.'; END IF;

  v_status   := COALESCE(NULLIF(p_payload->>'status',''), 'PENDING');
  v_number   := NULLIF(p_payload->>'invoice_number','');
  v_series   := NULLIF(p_payload->>'series','');
  v_key      := NULLIF(btrim(coalesce(p_payload->>'access_key','')),'');
  v_issue    := NULLIF(p_payload->>'issue_date','')::date;
  v_type     := COALESCE(NULLIF(p_payload->>'invoice_type',''), 'NFE');
  v_total    := COALESCE((p_payload->>'total_amount')::numeric, v_ar.total_amount);
  v_delivery := NULLIF(p_payload->>'delivery_id','')::uuid;

  IF v_status NOT IN ('PENDING','ISSUED','CANCELED','ERROR') THEN
    RAISE EXCEPTION 'Status fiscal inválido: %', v_status USING ERRCODE='check_violation';
  END IF;

  -- H7B-005: nenhum registro manual assume "emitido" sem evidencia externa.
  IF v_status = 'ISSUED' THEN
    IF v_key IS NULL OR v_key !~ '^[0-9]{44}$' THEN
      RAISE EXCEPTION
        'FISCAL_MANUAL_EVIDENCE_REQUIRED: registro manual como emitido exige chave de acesso de 44 digitos do documento externo.'
        USING ERRCODE='check_violation';
    END IF;
    IF v_number IS NULL THEN
      RAISE EXCEPTION
        'FISCAL_MANUAL_EVIDENCE_REQUIRED: registro manual como emitido exige o numero do documento externo.'
        USING ERRCODE='check_violation';
    END IF;
  END IF;

  SELECT * INTO v_existing FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE receivable_id = p_receivable_id
   FOR UPDATE;

  IF FOUND THEN
    IF public.fn_fiscal_status_is_terminal(v_existing.normalized_status) THEN
      RAISE EXCEPTION
        'FISCAL_DOCUMENT_LOCKED: documento fiscal % esta em % e nao aceita registro manual.',
        v_existing.id, v_existing.normalized_status
        USING ERRCODE='insufficient_privilege';
    END IF;
    IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) r
                WHERE r.fiscal_invoice_id = v_existing.id) THEN
      RAISE EXCEPTION
        'FISCAL_DOCUMENT_ENGINE_MANAGED: documento % pertence ao motor NF-e; use o fluxo de emissao.',
        v_existing.id
        USING ERRCODE='insufficient_privilege';
    END IF;

    v_old := to_jsonb(v_existing);
    UPDATE fiscal_invoices SET
      status = v_status,
      invoice_number = v_number,
      series = v_series,
      access_key = v_key,
      issue_date = v_issue,
      invoice_type = v_type,
      total_amount = v_total,
      delivery_id = COALESCE(v_delivery, v_existing.delivery_id),
      document_origin = 'MANUAL_RECORD',
      provider = COALESCE(v_existing.provider, 'NONE')
    WHERE id = v_existing.id
    RETURNING id INTO v_id;
    v_action := 'FISCAL_INVOICE_UPDATED';
  ELSE
    INSERT INTO fiscal_invoices(company_settings_id, 
      receivable_id, delivery_id, invoice_type, invoice_number, series, access_key,
      issue_date, total_amount, status, created_by, document_origin, provider
    ) VALUES (public.h15_active_company(), 
      p_receivable_id, v_delivery, v_type, v_number, v_series, v_key,
      v_issue, v_total, v_status, v_uid, 'MANUAL_RECORD', 'NONE'
    ) RETURNING id INTO v_id;
    v_action := 'FISCAL_INVOICE_CREATED';
  END IF;

  UPDATE accounts_receivable SET
    fiscal_invoice_status = CASE
      WHEN v_status = 'ISSUED' THEN 'ISSUED'
      WHEN v_status = 'CANCELED' THEN 'CANCELED'
      WHEN v_status = 'PENDING' THEN 'PENDING'
      ELSE accounts_receivable.fiscal_invoice_status
    END,
    fiscal_invoice_number = COALESCE(v_number, fiscal_invoice_number),
    fiscal_access_key     = COALESCE(v_key, fiscal_access_key),
    fiscal_issue_date     = COALESCE(v_issue, fiscal_issue_date)
  WHERE id = p_receivable_id;

  INSERT INTO financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES ('fiscal_invoices', v_id, v_action, v_old,
          jsonb_build_object('status', v_status, 'invoice_number', v_number,
                             'delivery_id', v_delivery,
                             'document_origin', 'MANUAL_RECORD'),
          v_uid);

  RETURN jsonb_build_object('invoice_id', v_id, 'status', v_status,
                            'document_origin', 'MANUAL_RECORD');
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_executar_motor_alertas(p_tipo_execucao text DEFAULT 'manual'::text, p_origem text DEFAULT 'painel'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_execucao_id uuid;
  v_iniciado_em timestamptz := clock_timestamp();
  v_resultado jsonb;
  v_uid uuid := auth.uid();
  v_is_service boolean := (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role';
  v_erro_msg text;
BEGIN
  -- Guardrail de permissao quando chamado via cliente autenticado.
  IF NOT v_is_service THEN
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'permission_denied' USING HINT = 'Usuario nao autenticado';
    END IF;
    IF NOT (
      public.has_role(v_uid, 'administrador'::app_role)
      OR public.has_role(v_uid, 'gestor'::app_role)
      OR public.has_role(v_uid, 'administrativo'::app_role)
    ) THEN
      RAISE EXCEPTION 'permission_denied' USING HINT = 'Perfil sem permissao para executar o motor de alertas';
    END IF;
  END IF;

  -- Normaliza inputs
  IF p_tipo_execucao IS NULL OR p_tipo_execucao NOT IN ('manual','automatico','cron','edge_function','sistema') THEN
    p_tipo_execucao := 'manual';
  END IF;
  IF p_origem IS NULL OR length(trim(p_origem)) = 0 THEN
    p_origem := 'sistema';
  END IF;

  INSERT INTO public.alertas_execucoes (
    tipo_execucao, origem, status, iniciado_em, executado_por
  ) VALUES (
    p_tipo_execucao, p_origem, 'iniciada', v_iniciado_em, v_uid
  ) RETURNING id INTO v_execucao_id;

  BEGIN
    SELECT public.rpc_gerar_alertas_operacionais() INTO v_resultado;

    UPDATE public.alertas_execucoes
       SET status = 'concluida',
           finalizado_em = clock_timestamp(),
           duracao_ms = GREATEST(0, EXTRACT(EPOCH FROM (clock_timestamp() - v_iniciado_em)) * 1000)::int,
           total_processados = COALESCE((v_resultado->>'total_processados')::int, 0),
           total_criados = COALESCE((v_resultado->>'total_criados')::int, 0),
           total_atualizados = COALESCE((v_resultado->>'total_atualizados')::int, 0),
           total_resolvidos_automaticamente = COALESCE((v_resultado->>'total_resolvidos_automaticamente')::int, 0),
           total_ignorados_por_regra = COALESCE((v_resultado->>'total_ignorados_por_regra')::int, 0),
           metadata = COALESCE(v_resultado, '{}'::jsonb)
     WHERE id = v_execucao_id;

    RETURN jsonb_build_object(
      'success', true,
      'execucao_id', v_execucao_id,
      'tipo_execucao', p_tipo_execucao,
      'origem', p_origem,
      'resultado', COALESCE(v_resultado, '{}'::jsonb)
    );
  EXCEPTION WHEN OTHERS THEN
    v_erro_msg := left(COALESCE(SQLERRM, 'erro_desconhecido'), 500);
    UPDATE public.alertas_execucoes
       SET status = 'falhou',
           finalizado_em = clock_timestamp(),
           duracao_ms = GREATEST(0, EXTRACT(EPOCH FROM (clock_timestamp() - v_iniciado_em)) * 1000)::int,
           erro = v_erro_msg
     WHERE id = v_execucao_id;

    RAISE EXCEPTION 'Falha na execucao do motor de alertas: %', v_erro_msg;
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_estoque_operar_v1(p_acao text, p_item_id uuid, p_quantidade numeric DEFAULT NULL::numeric, p_idempotency_key text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_fp text;
  v_prev public.estoque_movimentacoes%ROWTYPE;
  v_item public.estoque_produto%ROWTYPE;
  v_after public.estoque_produto%ROWTYPE;
  v_mov public.estoque_movimentacoes%ROWTYPE;
  v_ctx jsonb;
  v_qtd numeric := p_quantidade;
  v_motivo text := NULLIF(p_payload->>'motivo','');
  v_origem_mov uuid;
  v_limite numeric;
  v_classif text;
  v_target_id uuid;
  v_lote public.lotes%ROWTYPE;
BEGIN
  PERFORM platform_private.stock_motor_context_set(NULL);
  PERFORM platform_private.stock_motor_actor(p_acao);
  IF (p_quantidade IS NULL AND p_acao IS DISTINCT FROM 'estorno_expedicao') OR
     (p_quantidade IS NOT NULL AND (p_quantidade::text IN ('NaN','Infinity','-Infinity') OR p_quantidade <= 0)) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  IF p_acao = 'ajuste' AND p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida') THEN
    RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO: sentido deve ser entrada ou saida.' USING ERRCODE='22023';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,p_acao,p_payload);
  v_origem_mov := NULLIF(p_payload->>'movimentacao_origem_id','')::uuid;
  IF p_acao IS NULL OR p_acao NOT IN
     ('reserva','cancelamento_reserva','expedicao','entrega','estorno_expedicao','ajuste','perda','descarte','devolucao') THEN
    RAISE EXCEPTION 'ESTQ_ACAO_INVALIDA: ação % não é suportada pelo motor canônico.', p_acao
      USING ERRCODE='check_violation';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'ESTQ_NAO_AUTENTICADO' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.fn_estoque_pode_operar(v_uid, p_acao) THEN
    RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO: perfil não autorizado para %.', p_acao
      USING ERRCODE='insufficient_privilege';
  END IF;
  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_OBRIGATORIA: informe uma chave com ao menos 8 caracteres.'
      USING ERRCODE='check_violation';
  END IF;

  SELECT * INTO v_item FROM public.estoque_produto WHERE id=p_item_id FOR UPDATE;
  PERFORM platform_private.stock_motor_context_set(NULL);
  PERFORM platform_private.stock_motor_actor(p_acao);
  IF (p_quantidade IS NULL AND p_acao IS DISTINCT FROM 'estorno_expedicao') OR
     (p_quantidade IS NOT NULL AND (p_quantidade::text IN ('NaN','Infinity','-Infinity') OR p_quantidade <= 0)) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  IF p_acao = 'ajuste' AND p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida') THEN
    RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO: sentido deve ser entrada ou saida.' USING ERRCODE='22023';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,p_acao,p_payload);
  v_fp := public.fn_estoque_fingerprint(p_acao, p_item_id, p_quantidade, p_payload);
  PERFORM pg_advisory_xact_lock(hashtext('estoque_mov:'||p_idempotency_key));

  SELECT * INTO v_prev FROM public.estoque_movimentacoes
   WHERE idempotency_key = p_idempotency_key LIMIT 1;
  IF FOUND THEN
    IF v_prev.usuario_id IS DISTINCT FROM v_uid OR NOT coalesce(public.stock_p1_movement_owned(v_prev.estoque_produto_id,v_prev.lote_id),false) OR v_prev.metadata->>'stock_request_item' IS DISTINCT FROM p_item_id::text OR v_prev.metadata->>'stock_request_actor' IS DISTINCT FROM v_uid::text THEN
      RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505';
    END IF;
    IF v_prev.request_fingerprint IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO: chave já usada com payload divergente.'
        USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object(
      'ok', true, 'replay', true, 'acao', v_prev.acao,
      'movimentacao_id', v_prev.id, 'estoque_produto_id', v_prev.estoque_produto_id,
      'saldo_anterior', v_prev.saldo_anterior, 'saldo_posterior', v_prev.saldo_posterior,
      'reservado_anterior', v_prev.reservado_anterior, 'reservado_posterior', v_prev.reservado_posterior,
      'status_anterior', v_prev.status_anterior, 'status_novo', v_prev.status_novo);
  END IF;

  SELECT * INTO v_item FROM public.estoque_produto WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ESTQ_ITEM_INEXISTENTE: item % não encontrado.', p_item_id USING ERRCODE='no_data_found';
  END IF;

  IF p_acao <> 'estorno_expedicao' AND (v_qtd IS NULL OR v_qtd <= 0) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser maior que zero.' USING ERRCODE='check_violation';
  END IF;

  v_ctx := jsonb_strip_nulls(jsonb_build_object(
    'reserve_args', jsonb_build_object('os_id',p_payload->>'os_id','os_tipo',COALESCE(p_payload->>'os_tipo','interna'),'cliente_id',NULLIF(p_payload->>'cliente_id',''),'partner_id',NULLIF(p_payload->>'partner_id',''),'partner_order_id',NULLIF(p_payload->>'partner_order_id',''),'observacao',p_payload->>'observacao'),'acao', p_acao, 'origem', COALESCE(p_payload->>'origem','rpc_estoque_operar_v1'),
    'referencia_tipo', p_payload->>'referencia_tipo', 'referencia_id', p_payload->>'referencia_id',
    'motivo', v_motivo, 'idempotency_key', p_idempotency_key, 'request_fingerprint', v_fp,
    'usuario_id', v_uid::text, 'unidade', COALESCE(p_payload->>'unidade','un'),
    'observacao', p_payload->>'observacao',
    'metadata', COALESCE(p_payload->'metadata','{}'::jsonb) || jsonb_build_object('motor','v1','stock_request_item',p_item_id::text,'stock_request_actor',v_uid::text)
  ));

  -- ---------- validações por ação ----------
  IF p_acao = 'reserva' THEN
    IF v_item.status::text <> 'disponivel' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: item não está disponível (%).', v_item.status USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade,0) THEN
      RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: solicitado % > disponível %.', v_qtd, COALESCE(v_item.quantidade,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    v_target_id := public.reservar_estoque_item(
      p_item_id, v_qtd, (p_payload->>'os_id')::uuid, COALESCE(p_payload->>'os_tipo','interna'),
      NULLIF(p_payload->>'cliente_id','')::uuid, NULLIF(p_payload->>'partner_id','')::uuid,
      NULLIF(p_payload->>'partner_order_id','')::uuid, p_payload->>'observacao');

  ELSIF p_acao = 'cancelamento_reserva' THEN
    IF v_item.status::text <> 'reservado' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: item não está reservado.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade_reservada,0) THEN
      RAISE EXCEPTION 'ESTQ_LIBERACAO_EXCEDE: % > reservado %.', v_qtd, COALESCE(v_item.quantidade_reservada,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    IF v_qtd = COALESCE(v_item.quantidade_reservada,0) THEN
      UPDATE public.estoque_produto SET status='disponivel' WHERE id=p_item_id;
    ELSE
      UPDATE public.estoque_produto SET quantidade_reservada = quantidade_reservada - v_qtd WHERE id=p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'expedicao' THEN
    IF v_item.status::text <> 'reservado' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: só é possível expedir item reservado.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade_reservada,0) THEN
      RAISE EXCEPTION 'ESTQ_EXPEDICAO_EXCEDE: % > reservado %.', v_qtd, COALESCE(v_item.quantidade_reservada,0)
        USING ERRCODE='check_violation';
    END IF;
    IF (p_payload->>'cliente_id') IS NOT NULL
       AND v_item.reservado_para_cliente_id IS NOT NULL
       AND v_item.reservado_para_cliente_id <> (p_payload->>'cliente_id')::uuid THEN
      RAISE EXCEPTION 'ESTQ_ESCOPO_INVALIDO: item reservado para outro cliente.' USING ERRCODE='insufficient_privilege';
    END IF;
    IF (p_payload->>'os_id') IS NOT NULL
       AND v_item.reservado_para_os_id IS NOT NULL
       AND v_item.reservado_para_os_id <> (p_payload->>'os_id')::uuid THEN
      RAISE EXCEPTION 'ESTQ_ESCOPO_INVALIDO: item reservado para outra OS/pedido.' USING ERRCODE='insufficient_privilege';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    IF v_qtd = COALESCE(v_item.quantidade_reservada,0) THEN
      UPDATE public.estoque_produto SET status='expedido', expedido_em=now(), expedido_por=v_uid WHERE id=p_item_id;
    ELSE
      -- expedição parcial: baixa somente a quantidade autorizada
      UPDATE public.estoque_produto
         SET quantidade = GREATEST(COALESCE(quantidade,0) - v_qtd, 0),
             quantidade_reservada = COALESCE(quantidade_reservada,0) - v_qtd
       WHERE id = p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'entrega' THEN
    IF v_item.status::text NOT IN ('reservado','expedido') THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: entrega exige item reservado ou expedido.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade,0) THEN
      RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: entrega % > saldo %.', v_qtd, COALESCE(v_item.quantidade,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    UPDATE public.estoque_produto
       SET quantidade = COALESCE(quantidade,0) - v_qtd,
           quantidade_reservada = GREATEST(COALESCE(quantidade_reservada,0) - v_qtd, 0),
           status = 'expedido', expedido_em = COALESCE(expedido_em, now()), expedido_por = COALESCE(expedido_por, v_uid)
     WHERE id = p_item_id;
    v_target_id := p_item_id;

  ELSIF p_acao = 'estorno_expedicao' THEN
    IF v_origem_mov IS NULL THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_SEM_ORIGEM: informe movimentacao_origem_id.' USING ERRCODE='check_violation';
    END IF;
    SELECT * INTO v_mov FROM public.estoque_movimentacoes WHERE id = v_origem_mov;
    IF NOT FOUND OR v_mov.estoque_produto_id <> p_item_id THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_ORIGEM_INVALIDA' USING ERRCODE='check_violation';
    END IF;
    IF v_mov.acao IN ('estorno_expedicao','devolucao') THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_DE_ESTORNO: operação não permitida.' USING ERRCODE='check_violation';
    END IF;
    IF v_mov.acao NOT IN ('expedicao','entrega') THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_ACAO_INVALIDA: só expedição/entrega pode ser estornada.' USING ERRCODE='check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM public.estoque_movimentacoes WHERE movimentacao_origem_id = v_origem_mov) THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_DUPLICADO: movimentação já estornada.' USING ERRCODE='23505';
    END IF;
    v_qtd := COALESCE(v_qtd, v_mov.quantidade);
    v_ctx := v_ctx || jsonb_build_object('movimentacao_origem_id', v_origem_mov::text);
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    UPDATE public.estoque_produto
       SET quantidade = COALESCE(quantidade,0) + COALESCE(v_mov.saldo_anterior,0) - COALESCE(v_mov.saldo_posterior,0),
           quantidade_reservada = COALESCE(v_mov.reservado_anterior, quantidade_reservada),
           status = COALESCE(v_mov.status_anterior, status::text)::status_estoque,
           expedido_em = NULL, expedido_por = NULL
     WHERE id = p_item_id;
    v_target_id := p_item_id;

  ELSIF p_acao IN ('ajuste','perda','descarte') THEN
    IF v_motivo IS NULL THEN
      RAISE EXCEPTION 'ESTQ_MOTIVO_OBRIGATORIO: informe o motivo para %.', p_acao USING ERRCODE='check_violation';
    END IF;
    SELECT limite_ajuste_sem_aprovacao INTO v_limite FROM public.estoque_politicas LIMIT 1;
    IF p_acao <> 'ajuste' OR COALESCE(p_payload->>'sentido','saida') = 'saida' THEN
      IF v_qtd > COALESCE(v_limite,10)
         AND NOT (public.has_role(v_uid,'administrador'::app_role) OR public.has_role(v_uid,'gestor'::app_role)) THEN
        RAISE EXCEPTION 'ESTQ_APROVACAO_REQUERIDA: redução de % excede o limite % sem aprovação.', v_qtd, v_limite
          USING ERRCODE='insufficient_privilege';
      END IF;
      IF v_qtd > COALESCE(v_item.quantidade,0) THEN
        RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: redução % > saldo %.', v_qtd, COALESCE(v_item.quantidade,0)
          USING ERRCODE='check_violation';
      END IF;
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto
         SET quantidade = COALESCE(quantidade,0) - v_qtd,
             quantidade_reservada = LEAST(COALESCE(quantidade_reservada,0), COALESCE(quantidade,0) - v_qtd)
       WHERE id = p_item_id;
    ELSE
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto SET quantidade = COALESCE(quantidade,0) + v_qtd WHERE id = p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'devolucao' THEN
    v_classif := NULLIF(p_payload->>'classificacao','');
    IF v_classif IS NULL OR v_classif NOT IN ('reintegravel','quarentena','descarte','reprocesso') THEN
      RAISE EXCEPTION 'ESTQ_DEVOLUCAO_CLASSIFICACAO: informe reintegravel|quarentena|descarte|reprocesso.'
        USING ERRCODE='check_violation';
    END IF;
    IF v_motivo IS NULL THEN
      RAISE EXCEPTION 'ESTQ_MOTIVO_OBRIGATORIO: informe o motivo da devolução.' USING ERRCODE='check_violation';
    END IF;
    IF v_classif = 'reintegravel' THEN
      SELECT * INTO v_lote FROM public.lotes WHERE id = v_item.lote_id;
      IF NOT EXISTS (SELECT 1 FROM public.controle_qualidade cq
                      WHERE cq.lote_id = v_item.lote_id AND cq.resultado = 'aprovado'::resultado_cq) THEN
        RAISE EXCEPTION 'ESTQ_DEVOLUCAO_CQ: lote sem CQ aprovado não pode ser reintegrado ao estoque comercial.'
          USING ERRCODE='check_violation';
      END IF;
      IF v_item.validade IS NOT NULL AND v_item.validade < current_date THEN
        RAISE EXCEPTION 'ESTQ_DEVOLUCAO_VALIDADE: item vencido não pode ser reintegrado.' USING ERRCODE='check_violation';
      END IF;
      v_ctx := v_ctx || jsonb_build_object('metadata',
        COALESCE(v_ctx->'metadata','{}'::jsonb) || jsonb_build_object('classificacao', v_classif));
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto SET quantidade = COALESCE(quantidade,0) + v_qtd WHERE id = p_item_id;
    ELSE
      v_ctx := v_ctx || jsonb_build_object('metadata',
        COALESCE(v_ctx->'metadata','{}'::jsonb) || jsonb_build_object('classificacao', v_classif, 'reintegrado', false));
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      -- não reintegra saldo comercial: registra apenas a trilha da devolução
      UPDATE public.estoque_produto SET observacao_reserva = COALESCE(observacao_reserva, v_motivo) WHERE id = p_item_id;
      INSERT INTO public.estoque_movimentacoes
        (estoque_produto_id, acao, quantidade, status_anterior, status_novo, lote_id, usuario_id,
         saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
         unidade, direcao, origem, referencia_tipo, referencia_id, motivo,
         idempotency_key, request_fingerprint, metadata)
      VALUES (p_item_id, 'devolucao', v_qtd, v_item.status::text, v_item.status::text, v_item.lote_id, v_uid,
         COALESCE(v_item.quantidade,0), COALESCE(v_item.quantidade,0),
         COALESCE(v_item.quantidade_reservada,0), COALESCE(v_item.quantidade_reservada,0),
         COALESCE(p_payload->>'unidade','un'), 'neutro',
         COALESCE(p_payload->>'origem','rpc_estoque_operar_v1'),
         p_payload->>'referencia_tipo', NULLIF(p_payload->>'referencia_id','')::uuid, v_motivo,
         p_idempotency_key, v_fp,
         jsonb_build_object('classificacao', v_classif, 'reintegrado', false, 'motor','v1','stock_request_item',p_item_id::text,'stock_request_actor',v_uid::text));
    END IF;
    v_target_id := p_item_id;
  END IF;

  PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close();

  SELECT * INTO v_after FROM public.estoque_produto WHERE id = COALESCE(v_target_id, p_item_id);
  SELECT * INTO v_mov FROM public.estoque_movimentacoes
   WHERE idempotency_key = p_idempotency_key ORDER BY created_at DESC LIMIT 1;

  IF v_mov.id IS NULL THEN
    RAISE EXCEPTION 'ESTQ_SEM_TRILHA: operação não gerou lançamento no livro.' USING ERRCODE='internal_error';
  END IF;
  IF COALESCE(v_after.quantidade,0) < 0 OR COALESCE(v_after.quantidade_reservada,0) < 0 THEN
    RAISE EXCEPTION 'ESTQ_SALDO_NEGATIVO: operação resultaria em saldo negativo.' USING ERRCODE='check_violation';
  END IF;
  IF COALESCE(v_after.quantidade_reservada,0) > COALESCE(v_after.quantidade,0) THEN
    RAISE EXCEPTION 'ESTQ_RESERVA_MAIOR_QUE_SALDO' USING ERRCODE='check_violation';
  END IF;

  IF v_mov.usuario_id IS DISTINCT FROM v_uid OR v_mov.metadata->>'stock_request_item' IS DISTINCT FROM p_item_id::text OR NOT coalesce(public.stock_p1_movement_owned(v_mov.estoque_produto_id,v_mov.lote_id),false) THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object(
    'ok', true, 'replay', false, 'acao', p_acao,
    'movimentacao_id', v_mov.id, 'estoque_produto_id', COALESCE(v_target_id, p_item_id),
    'saldo_anterior', v_mov.saldo_anterior, 'saldo_posterior', v_mov.saldo_posterior,
    'reservado_anterior', v_mov.reservado_anterior, 'reservado_posterior', v_mov.reservado_posterior,
    'status_anterior', v_mov.status_anterior, 'status_novo', v_mov.status_novo,
    'quantidade', v_mov.quantidade, 'unidade', v_mov.unidade);
EXCEPTION WHEN OTHERS THEN PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close(); RAISE;
END; $function$

CREATE OR REPLACE FUNCTION platform_private.stock_motor_context_set(p_ctx jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 DELETE FROM platform_private.stock_motor_context WHERE txid=txid_current();
 IF p_ctx IS NOT NULL THEN
  PERFORM platform_private.stock_motor_actor(p_ctx->>'acao');
  IF p_ctx->>'usuario_id' IS DISTINCT FROM auth.uid()::text OR jsonb_typeof(p_ctx->'metadata') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  INSERT INTO platform_private.stock_motor_context(txid,actor,item,ctx) VALUES(txid_current(),auth.uid(),(p_ctx->'metadata'->>'stock_request_item')::uuid,p_ctx);
 END IF;
 PERFORM public.fn_estoque_ctx_force(p_ctx);
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_lane_invoke()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_secret text; v_header text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_gate WHERE id AND approved) THEN RETURN; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_jobs WHERE state IN ('executing','authorized') AND lease_expires_at>clock_timestamp()) THEN RETURN; END IF;
 IF NOT (EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_jobs WHERE state='queued')
  OR EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_jobs WHERE state IN ('executing','authorized') AND lease_expires_at<=clock_timestamp())
  OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_lane_heartbeat WHERE id AND seen_at>clock_timestamp()-interval '5 minutes')) THEN RETURN; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('tenant_smtp_lane_invoke',0)) THEN RETURN; END IF;
 SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name='tenant_smtp_lane_invoker_secret';
 IF v_secret IS NULL OR length(v_secret)<32 THEN RETURN; END IF;
 -- Transport v1: ASCII header 'b64u1.' || base64url(UTF-8), no padding/CR/LF; computed in memory, never stored/logged.
 v_header:='b64u1.'||rtrim(translate(replace(replace(encode(convert_to(v_secret,'UTF8'),'base64'),E'\n',''),E'\r',''),'+/','-_'),'=');
 PERFORM net.http_post(url:='https://swzpzcwiasxmjutrmvkm.supabase.co/functions/v1/process-communication-outbox?lane=tenant_smtp',
  headers:=jsonb_build_object('Content-Type','application/json','x-tenant-smtp-secret',v_header),body:='{}'::jsonb,timeout_milliseconds:=55000);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_estoque_reservar_v1(p_os_id uuid, p_origem text, p_itens jsonb, p_idempotency_key text, p_dados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_org uuid; v_actor uuid:=auth.uid(); v_tipo text; v_cliente uuid; v_partner uuid; v_order uuid; v_obs text;
 v_item jsonb; v_qty numeric; v_id uuid; v_payload jsonb; v_items jsonb; v_fp text; v_key text;
 v_prev platform_private.stock_batch_requests%ROWTYPE; v_result jsonb; v_call jsonb; v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
 v_org:=platform_private.stock_motor_actor('reserva');
 PERFORM platform_private.stock_motor_context_set(NULL);
 IF p_os_id IS NULL THEN RAISE EXCEPTION 'ESTQ_OS_OBRIGATORIA' USING ERRCODE='23514'; END IF;
 IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key))<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_OBRIGATORIA' USING ERRCODE='23514'; END IF;
 IF p_origem IS NULL OR p_origem NOT IN ('padrao','manual','onfarm','on_farm','b2b') THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 v_tipo:=CASE WHEN p_origem='padrao' THEN 'manual' WHEN p_origem='on_farm' THEN 'onfarm' ELSE p_origem END;
 IF p_dados IS NULL OR jsonb_typeof(p_dados)<>'object' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_dados) e WHERE e.key NOT IN ('cliente_id','partner_id','partner_order_id','observacao') OR jsonb_typeof(e.value) NOT IN ('string','null')) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF p_itens IS NULL OR jsonb_typeof(p_itens)<>'array' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_itens)=0 THEN RAISE EXCEPTION 'ESTQ_ITENS_VAZIOS' USING ERRCODE='23514'; END IF;
 v_cliente:=nullif(p_dados->>'cliente_id','')::uuid; v_partner:=nullif(p_dados->>'partner_id','')::uuid; v_order:=nullif(p_dados->>'partner_order_id','')::uuid; v_obs:=nullif(p_dados->>'observacao','');
 v_payload:=jsonb_build_object('os_id',p_os_id,'os_tipo',v_tipo,'cliente_id',v_cliente,'partner_id',v_partner,'partner_order_id',v_order,'observacao',v_obs);
 v_items:='[]'::jsonb;
 FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
  IF jsonb_typeof(v_item)<>'object' OR NOT(v_item ? 'item_id' AND v_item ? 'quantidade') THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(v_item) e WHERE e.key NOT IN ('item_id','quantidade') OR (e.key='item_id' AND jsonb_typeof(e.value)<>'string') OR (e.key='quantidade' AND jsonb_typeof(e.value) NOT IN ('string','number'))) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  IF v_qty IS NULL OR v_qty::text IN ('NaN','Infinity','-Infinity') OR v_qty<=0 THEN RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA' USING ERRCODE='23514'; END IF;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',v_payload);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) e WHERE e->>'item_id'=v_id::text) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  v_items:=v_items||jsonb_build_array(jsonb_build_object('item_id',v_id,'quantidade',v_qty));
 END LOOP;
 SELECT jsonb_agg(value ORDER BY value->>'item_id') INTO v_items FROM jsonb_array_elements(v_items);
 v_fp:=md5(jsonb_build_object('actor',v_actor,'org',v_org,'os',p_os_id,'tipo',v_tipo,'payload',v_payload,'itens',v_items)::text);
 -- Global key collision is denied, never reused across actor/tenant/content. No wildcard comparisons.
 PERFORM pg_advisory_xact_lock(hashtextextended('stock_batch:'||p_idempotency_key,0));
 SELECT * INTO v_prev FROM platform_private.stock_batch_requests WHERE request_key=p_idempotency_key;
 IF FOUND THEN
  IF v_prev.actor IS DISTINCT FROM v_actor OR v_prev.organization_id IS DISTINCT FROM v_org OR v_prev.fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
  RETURN v_prev.result||jsonb_build_object('replay',true);
 END IF;
 IF EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE idempotency_key=p_idempotency_key OR left(idempotency_key,length(p_idempotency_key)+1)=p_idempotency_key||'#') THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
 -- Consistent item order before nested motor calls; all writes are one transaction.
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid;
  PERFORM 1 FROM public.estoque_produto WHERE id=v_id FOR UPDATE;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',v_payload);
 END LOOP;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  v_key:='stock_batch_item:'||md5(jsonb_build_array(p_idempotency_key,v_actor,v_org,v_id)::text);
  IF EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE idempotency_key=v_key OR left(idempotency_key,length(v_key)+1)=v_key||'#') THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
  v_call:=public.rpc_estoque_operar_v1('reserva',v_id,v_qty,v_key,v_payload);
  IF v_call->>'ok' IS DISTINCT FROM 'true' OR v_call->>'replay' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA'; END IF;
  -- The ledger is canonical for the split target, not the source item.
  SELECT estoque_produto_id INTO v_id FROM public.estoque_movimentacoes WHERE id=(v_call->>'movimentacao_id')::uuid;
  IF v_id IS NULL THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA'; END IF;
  v_ids:=array_append(v_ids,v_id);
 END LOOP;
 v_result:=jsonb_build_object('ok',true,'replay',false,'itens',to_jsonb(v_ids));
 INSERT INTO platform_private.stock_batch_requests(request_key,actor,organization_id,fingerprint,result) VALUES(p_idempotency_key,v_actor,v_org,v_fp,v_result);
 PERFORM platform_private.stock_motor_context_set(NULL);
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.fn_estoque_ctx_read()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v text;
BEGIN
  v := NULLIF(current_setting('app.estoque_mov_ctx', true), '');
  IF v IS NULL THEN RETURN NULL; END IF;
  RETURN v::jsonb;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_fail_communication_delivery(p_outbox_id uuid, p_worker_id text, p_error_code text, p_error_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_outbox%rowtype; v_backoff int;
BEGIN
  IF NULLIF(trim(COALESCE(p_worker_id,'')),'') IS NULL THEN RAISE EXCEPTION 'worker_id obrigatório'; END IF;
  IF p_error_code IS NOT NULL AND length(p_error_code) > 80 THEN RAISE EXCEPTION 'error_code excede 80'; END IF;
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'processing' THEN RAISE EXCEPTION 'não estava em processing'; END IF;
  IF r.locked_by IS DISTINCT FROM p_worker_id THEN RAISE EXCEPTION 'lease de outro worker'; END IF;
  IF r.attempts >= r.max_attempts THEN
    UPDATE public.comunicacao_outbox
       SET status = 'dead_letter', error_code = left(COALESCE(p_error_code,''),80),
           error_message = left(COALESCE(p_error_message,''),2000),
           locked_at = NULL, locked_by = NULL, lease_expires_at = NULL
     WHERE id = p_outbox_id;
    RETURN jsonb_build_object('ok',true,'status','dead_letter');
  END IF;
  v_backoff := LEAST(3600, POWER(2, r.attempts)::int * 30);
  UPDATE public.comunicacao_outbox
     SET status = 'pending', next_attempt_at = now() + make_interval(secs => v_backoff),
         error_code = left(COALESCE(p_error_code,''),80),
         error_message = left(COALESCE(p_error_message,''),2000),
         locked_at = NULL, locked_by = NULL, lease_expires_at = NULL
   WHERE id = p_outbox_id;
  RETURN jsonb_build_object('ok',true,'status','pending','retry_in_seconds',v_backoff);
END$function$

CREATE OR REPLACE FUNCTION platform_private.c2_partner_order_attempt_authz(p_uid uuid, p_partner_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_is_internal boolean; v_is_partner boolean; v_is_partner_tech boolean; v_user_partner uuid;
BEGIN
  -- Espelha a autorização do create canônico (mesma ordem/mensagens). Chamado antes E
  -- depois do lock b2b_idem; cada chamada lê um snapshot novo (READ COMMITTED).
  IF p_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  PERFORM platform_private.c2_order_actor_scope(p_uid, p_partner_id);
  v_is_internal := public.has_role(p_uid,'administrador'::public.app_role)
                OR public.has_role(p_uid,'financeiro'::public.app_role)
                OR public.has_role(p_uid,'gestor_comercial'::public.app_role);
  v_is_partner      := public.has_role(p_uid,'parceiro_b2b'::public.app_role);
  v_is_partner_tech := public.has_role(p_uid,'parceiro_b2b_tecnico'::public.app_role);
  v_user_partner    := public.get_user_partner_id();
  IF public.has_role(p_uid,'cliente_produtor'::public.app_role) AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'PRODUCER_DIRECT_NOT_ENABLED';
  END IF;
  IF v_is_partner_tech AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'partner_tech_cannot_create_order';
  END IF;
  IF NOT v_is_internal THEN
    IF NOT v_is_partner OR v_user_partner IS NULL OR v_user_partner <> p_partner_id THEN
      RAISE EXCEPTION 'forbidden_partner';
    END IF;
  END IF;
  PERFORM 1 FROM public.partner_accounts WHERE id = p_partner_id AND ativo = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'partner_not_found'; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_finalizar_visita_v2(p_registro_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_ok boolean;
  v_diag_count integer;
  v_checkin_count integer;
  v_new_version integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;

  IF NOT COALESCE(public.can_view_technical_visit(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_reg
    FROM public.registros_consultor
   WHERE id = p_registro_id
   FOR UPDATE;

  IF v_reg.id IS NULL THEN
    RAISE EXCEPTION 'registro_nao_encontrado' USING ERRCODE = 'P0002';
  END IF;

  v_ok := COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false)
       OR (COALESCE(public.is_active_visit_participant(v_uid, p_registro_id), false)
           AND COALESCE(public.technical_client_link(v_uid, v_reg.cliente_id, ARRAY['execute','manage']::text[]), false));

  IF v_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_technical_visit_editable_status(v_reg.status::text) THEN
    RAISE EXCEPTION 'visita_nao_editavel' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(p_expected_version, -1) <> v_reg.version THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001';
  END IF;

  IF v_reg.cultura_id IS NULL THEN
    RAISE EXCEPTION 'cultura_obrigatoria' USING ERRCODE = '23514', DETAIL = 'invalid_request';
  END IF;

  SELECT count(*) INTO v_diag_count FROM public.visita_diagnosticos WHERE registro_id = p_registro_id;
  IF v_diag_count = 0 THEN RAISE EXCEPTION 'diagnostico_obrigatorio' USING ERRCODE = '23514'; END IF;

  SELECT count(*) INTO v_checkin_count FROM public.visitas_checkin WHERE registro_consultor_id = p_registro_id;
  IF v_checkin_count = 0 THEN RAISE EXCEPTION 'checkin_obrigatorio' USING ERRCODE = '23514'; END IF;

  v_new_version := v_reg.version + 1;

  UPDATE public.registros_consultor
     SET status = 'finalizado'::status_registro_consultor,
         finalized_at = now(),
         finalized_by = v_uid,
         version = v_new_version,
         pdf_status = COALESCE(pdf_status, 'pending'),
         updated_at = now()
   WHERE id = p_registro_id;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, v_uid, 'visita_finalizada', 'Visita finalizada via rpc_finalizar_visita_v2');

  RETURN jsonb_build_object(
    'id', p_registro_id,
    'status', 'finalizado',
    'version', v_new_version,
    'finalized_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fail_communication_delivery_v2(p_outbox_id uuid, p_worker_id text, p_error_code text, p_error_message text, p_is_permanent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.comunicacao_outbox%rowtype;
  v_role text;
  v_base int;
  v_jitter numeric;
  v_backoff int;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NULLIF(trim(COALESCE(p_worker_id,'')),'') IS NULL THEN
    RAISE EXCEPTION 'worker_id obrigatório';
  END IF;
  IF p_error_code IS NOT NULL AND length(p_error_code) > 80 THEN
    RAISE EXCEPTION 'error_code >80';
  END IF;
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'processing' THEN RAISE EXCEPTION 'não estava em processing'; END IF;
  IF r.locked_by IS DISTINCT FROM p_worker_id THEN RAISE EXCEPTION 'lease de outro'; END IF;
  IF p_is_permanent OR r.attempts >= r.max_attempts THEN
    UPDATE public.comunicacao_outbox
       SET status='dead_letter',
           error_code=left(COALESCE(p_error_code,''),80),
           error_message=left(COALESCE(p_error_message,''),2000),
           locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
     WHERE id = p_outbox_id;
    RETURN jsonb_build_object('ok',true,'status','dead_letter','attempts',r.attempts);
  END IF;
  -- Backoff exponencial base + jitter simétrico ±20%. Teto 3600s, piso 1s.
  v_base := LEAST(3600, GREATEST(1, POWER(2, GREATEST(r.attempts-1, 0))::int * 30));
  v_jitter := 0.8 + (random() * 0.4); -- [0.8, 1.2)
  v_backoff := LEAST(3600, GREATEST(1, floor(v_base * v_jitter)::int));
  UPDATE public.comunicacao_outbox
     SET status='pending',
         next_attempt_at=now() + make_interval(secs => v_backoff),
         error_code=left(COALESCE(p_error_code,''),80),
         error_message=left(COALESCE(p_error_message,''),2000),
         locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
   WHERE id = p_outbox_id;
  RETURN jsonb_build_object('ok',true,'status','pending','retry_in_seconds',v_backoff,'attempts',r.attempts);
END$function$

CREATE OR REPLACE FUNCTION public.guard_superadmin_role_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_touches boolean := false;
BEGIN
  IF TG_OP IN ('INSERT','UPDATE') AND NEW.role = 'superadmin'::public.app_role THEN
    v_touches := true;
  END IF;
  IF TG_OP IN ('UPDATE','DELETE') AND OLD.role = 'superadmin'::public.app_role THEN
    v_touches := true;
  END IF;

  IF v_touches AND current_user NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'superadmin_role_reserved'
      USING ERRCODE = '42501',
            HINT = 'O papel de plataforma so pode ser atribuido ou removido pelo mecanismo interno.';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.notification_source_org(st text, sid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v uuid; BEGIN
 IF sid IS NULL THEN RETURN NULL; END IF;
 CASE st
 WHEN 'registros_consultor','registro_consultor','monitoramento_vencido' THEN SELECT c.organization_id INTO v FROM public.registros_consultor r JOIN public.clientes c ON c.id=r.cliente_id WHERE r.id=sid;
 WHEN 'ordem_servico','ordens_servico' THEN SELECT o.organization_id INTO v FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE o.id=sid;
 WHEN 'portal_solicitacoes' THEN SELECT c.organization_id INTO v FROM public.portal_solicitacoes s JOIN public.clientes c ON c.id=s.cliente_id WHERE s.id=sid;
 WHEN 'programacao_producao' THEN SELECT p.organization_id INTO v FROM public.programacao_producao p WHERE p.id=sid AND ((p.ordem_servico_id IS NOT NULL AND p.ordem_servico_onfarm_id IS NULL AND EXISTS(SELECT 1 FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE o.id=p.ordem_servico_id AND o.organization_id=p.organization_id)) OR (p.ordem_servico_onfarm_id IS NOT NULL AND p.ordem_servico_id IS NULL AND EXISTS(SELECT 1 FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=p.ordem_servico_onfarm_id AND c.organization_id=p.organization_id)));
 WHEN 'estoque_produto' THEN RETURN NULL;
 WHEN 'aplicacao','aplicacoes' THEN SELECT a.organization_id INTO v FROM public.aplicacoes a JOIN public.ordens_servico o ON o.id=a.ordem_servico_id AND o.organization_id=a.organization_id JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE a.id=sid AND a.ordem_servico_onfarm_id IS NULL;
 WHEN 'partner_orders' THEN SELECT c.organization_id INTO v FROM public.partner_orders o JOIN public.partner_accounts p ON p.id=o.partner_id AND p.ativo IS TRUE AND p.deleted_at IS NULL JOIN public.clientes c ON c.id=p.client_id WHERE o.id=sid;
 WHEN 'partner_simulations' THEN SELECT c.organization_id INTO v FROM public.partner_simulations s JOIN public.partner_accounts p ON p.id=s.partner_id AND p.ativo IS TRUE AND p.deleted_at IS NULL JOIN public.clientes c ON c.id=p.client_id WHERE s.id=sid;
 ELSE RETURN NULL; END CASE;
 IF NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=v AND o.ativo IS TRUE) THEN RETURN NULL; END IF;
 RETURN v; END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_attempt_closure_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_key text := btrim(NEW.idempotency_key);
BEGIN
  -- Barreira durável no caminho de ESCRITA: cobre corpos antigos de create ainda em voo
  -- durante o rollout (CREATE OR REPLACE não drena execuções já iniciadas). Mesmo lock
  -- b2b_idem (reentrante para quem já o detém) + recusa se a chave foi fechada.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:' || NEW.partner_id::text || ':' || v_key, 0));
  IF EXISTS (SELECT 1 FROM platform_private.partner_order_idempotency_closures c
              WHERE c.partner_id = NEW.partner_id AND c.idempotency_key = v_key) THEN
    RAISE EXCEPTION 'idempotency_key_closed';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.user_edit_f2_authorize(p_target uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid;
BEGIN
 IF auth.uid() IS NULL OR platform_private.platform_actor_access_ready(auth.uid()) IS NOT TRUE
 OR NOT public.has_role(auth.uid(),'administrador') OR public.is_platform_superadmin(auth.uid())
 OR public.is_platform_superadmin(p_target) THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 SELECT organization_id INTO org FROM public.profiles WHERE user_id=auth.uid() AND ativo IS TRUE;
 IF org IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_target AND organization_id=org)
 THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org AND ativo IS TRUE AND status='ativa' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 RETURN org;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_calculate_invoice_v1(p_invoice_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  inv public.fiscal_invoices%ROWTYPE;
  emit public.company_fiscal_settings%ROWTYPE;
  dest public.customer_fiscal_profiles%ROWTYPE;
  it record; pol public.fiscal_operation_policies%ROWTYPE; rule public.fiscal_tax_rules%ROWTYPE;
  item_taxes jsonb; item_snapshot jsonb; ctx jsonb; res jsonb;
  totals jsonb; existing jsonb; debtor jsonb;
  t_icms numeric := 0; t_st numeric := 0; t_fcp numeric := 0; t_difal numeric := 0;
  t_pis numeric := 0; t_cofins numeric := 0; t_ipi numeric := 0; t_fcpst numeric := 0;
  t_difal_dest numeric := 0; t_difal_orig numeric := 0; t_fcp_dest numeric := 0;
  t_prod numeric := 0; t_desc numeric := 0; t_frete numeric := 0; t_seg numeric := 0; t_outros numeric := 0;
  t_nf numeric := 0; t_com numeric := 0; n_items int := 0; ref_date date; kinds text[]; k text;
  has_difal boolean := false;
  v_prod numeric; v_icms_own numeric; v_ipi numeric; v_base_st numeric;
  v_st_val numeric; v_fcp_own numeric; v_fcp_st numeric;
  v_difal_dest numeric; v_difal_orig numeric; v_fcp_dest numeric;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(p_invoice_id);

  IF NOT public.fn_fiscal_can_operate() THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao para calcular documento fiscal.';
  END IF;
  IF nullif(btrim(coalesce(p_idempotency_key,'')),'') IS NULL THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_KEY_REQUIRED: informe uma chave de idempotencia.';
  END IF;

  -- F3.1-R1: gate de ambiente avaliado ANTES de qualquer leitura/efeito, fail-closed.
  PERFORM public.fn_fiscal_assert_environment_homologation();

  SELECT * INTO inv FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: %', p_invoice_id; END IF;

  IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_calculation_runs WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_calculation_runs
              WHERE idempotency_key = p_idempotency_key
                AND fiscal_invoice_id <> p_invoice_id) THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_SCOPE_MISMATCH: chave de idempotencia ja utilizada por outro documento fiscal.';
  END IF;

  SELECT result INTO existing FROM (SELECT * FROM public.fiscal_calculation_runs WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_calculation_runs
   WHERE fiscal_invoice_id = p_invoice_id AND idempotency_key = p_idempotency_key;
  IF existing IS NOT NULL THEN
    RETURN existing || jsonb_build_object('idempotentReplay', true);
  END IF;

  IF inv.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_DRAFT: somente rascunho pode ser calculado (status=%)', inv.status;
  END IF;
  IF inv.document_model <> 'NFE' THEN
    RAISE EXCEPTION 'FISCAL_MODEL_UNSUPPORTED: fase F3 cobre apenas NF-e modelo 55.';
  END IF;
  IF coalesce(inv.tp_emis,1) <> 1 THEN
    RAISE EXCEPTION 'FISCAL_TPEMIS_UNSUPPORTED: apenas emissao normal (tpEmis=1) esta habilitada nesta fase.';
  END IF;
  IF inv.tax_snapshot IS NOT NULL AND inv.tax_snapshot ? 'engineVersion' THEN
    RAISE EXCEPTION 'FISCAL_SNAPSHOT_IMMUTABLE: documento ja possui snapshot tributario; historico nao recalcula.';
  END IF;

  IF NOT ((public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id))->>'eligible')::boolean THEN
    RAISE EXCEPTION 'FISCAL_NOT_ELIGIBLE: %', (public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id))->>'reasons';
  END IF;

  -- F3.1: devedor B2B x destinatario do documento (fail-closed, antes de qualquer efeito).
  debtor := public.fn_fiscal_assert_debtor_recipient(p_invoice_id);

  SELECT * INTO emit FROM (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EMITTER_NOT_CONFIGURED: emitente nao cadastrado.'; END IF;

  -- F3.1: gate de ambiente/homologacao reavaliado tambem no CALCULO.
  IF coalesce(emit.nfe_environment_code,'2') = '1' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_BLOCKED: ambiente de producao (tpAmb=1) bloqueado na fase F3; teto READY_HOMOLOGATION.';
  END IF;
  IF emit.nfe_readiness_status <> 'READY_HOMOLOGATION' THEN
    RAISE EXCEPTION 'FISCAL_EMITTER_NOT_READY: emitente com pendencias %', emit.nfe_readiness_pendencies;
  END IF;

  IF inv.customer_id IS NULL THEN
    RAISE EXCEPTION 'FISCAL_RECIPIENT_MISSING: destinatario/devedor nao resolvido para o documento.';
  END IF;
  SELECT * INTO dest FROM public.customer_fiscal_profiles WHERE customer_id = inv.customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_RECIPIENT_PROFILE_MISSING: perfil fiscal do destinatario nao cadastrado.'; END IF;
  IF dest.nfe_readiness_status <> 'READY' THEN
    RAISE EXCEPTION 'FISCAL_RECIPIENT_NOT_READY: destinatario com pendencias %', dest.nfe_readiness_pendencies;
  END IF;

  ref_date := coalesce(inv.issue_date, current_date);

  FOR it IN
    SELECT * FROM (SELECT * FROM public.fiscal_invoice_items WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_invoice_items WHERE fiscal_invoice_id = p_invoice_id ORDER BY item_sequence
  LOOP
    n_items := n_items + 1;
    IF coalesce(it.quantity,0) <= 0 OR coalesce(it.unit_value,0) < 0 THEN
      RAISE EXCEPTION 'FISCAL_ITEM_INVALID: item % com quantidade ou valor unitario invalido.', it.item_sequence;
    END IF;
    IF nullif(btrim(coalesce(it.ncm_snapshot,'')),'') IS NULL THEN
      RAISE EXCEPTION 'FISCAL_ITEM_NCM_MISSING: item % sem NCM no snapshot do pedido.', it.item_sequence;
    END IF;

    v_prod := public.fn_fiscal_round(coalesce(it.gross_value, it.quantity * it.unit_value));

    res := public.fn_fiscal_compute_item_taxes_v1(
      emit, dest, coalesce(inv.direction,'OUT'), inv.sales_channel, ref_date, it.ncm_snapshot,
      v_prod, coalesce(it.discount_value,0), coalesce(it.freight_value,0),
      coalesce(it.insurance_value,0), coalesce(it.other_value,0),
      coalesce(it.tax_input_snapshot,'{}'::jsonb), auth.uid());

    item_taxes := res->'taxes';
    kinds := ARRAY(SELECT jsonb_array_elements_text(res->'taxOrder'));
    SELECT * INTO pol FROM public.fiscal_operation_policies WHERE id = (res->'policy'->>'id')::uuid;
    v_icms_own   := coalesce((res->'chained'->>'icmsOwnValue')::numeric,0);
    v_ipi        := coalesce((res->'chained'->>'ipi')::numeric,0);
    v_st_val     := coalesce((res->'chained'->>'icmsSt')::numeric,0);
    v_base_st    := nullif(res->'chained'->>'baseST','')::numeric;
    v_fcp_own    := coalesce((res->'itemTotals'->>'vFCP')::numeric,0);
    v_fcp_st     := coalesce((res->'itemTotals'->>'vFCPST')::numeric,0);
    v_difal_dest := coalesce((res->'itemTotals'->>'vICMSUFDest')::numeric,0);
    v_difal_orig := coalesce((res->'itemTotals'->>'vICMSUFRemet')::numeric,0);
    v_fcp_dest   := coalesce((res->'itemTotals'->>'vFCPUFDest')::numeric,0);
    has_difal    := has_difal OR coalesce((res->>'hasDifal')::boolean,false);

    t_prod   := t_prod + v_prod;
    t_desc   := t_desc + public.fn_fiscal_round(coalesce(it.discount_value,0));
    t_frete  := t_frete + public.fn_fiscal_round(coalesce(it.freight_value,0));
    t_seg    := t_seg + public.fn_fiscal_round(coalesce(it.insurance_value,0));
    t_outros := t_outros + public.fn_fiscal_round(coalesce(it.other_value,0));
    t_icms   := t_icms   + coalesce((item_taxes->'ICMS'->>'value')::numeric,0);
    t_st     := t_st     + v_st_val;
    -- vFCP = FCP proprio da operacao. vFCPST = FCP retido por ST.
    -- vFCPUFDest = FCP devido a UF de destino no DIFAL. Sem sobreposicao.
    t_fcp    := t_fcp    + v_fcp_own;
    t_fcpst  := t_fcpst  + v_fcp_st;
    t_difal  := t_difal  + coalesce((item_taxes->'DIFAL'->>'value')::numeric,0);
    t_difal_dest := t_difal_dest + v_difal_dest;
    t_difal_orig := t_difal_orig + v_difal_orig;
    t_fcp_dest   := t_fcp_dest + v_fcp_dest;
    t_pis    := t_pis    + coalesce((item_taxes->'PIS'->>'value')::numeric,0);
    t_cofins := t_cofins + coalesce((item_taxes->'COFINS'->>'value')::numeric,0);
    t_ipi    := t_ipi    + coalesce((item_taxes->'IPI'->>'value')::numeric,0);

    item_snapshot := jsonb_build_object(
      'engineVersion','F3.4',
      'calculatedAt', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SSZ'),
      'ncm', it.ncm_snapshot,
      'cfop', pol.cfop,
      'natureOperation', pol.nature_operation,
      'operationPolicyId', pol.id,
      'operationPolicyVersion', pol.legal_version,
      'operationLegalBasis', pol.legal_basis,
      'operationSourceId', pol.source_id,
      'crt', emit.crt,
      'roundingMode','HALF_UP_2',
      'components', jsonb_build_object(
        'produto', v_prod,
        'desconto', public.fn_fiscal_round(coalesce(it.discount_value,0)),
        'frete', public.fn_fiscal_round(coalesce(it.freight_value,0)),
        'seguro', public.fn_fiscal_round(coalesce(it.insurance_value,0)),
        'outras', public.fn_fiscal_round(coalesce(it.other_value,0))),
      'taxOrder', to_jsonb(kinds),
      'taxInputs', coalesce(it.tax_input_snapshot, '{}'::jsonb),
      'chainedContext', jsonb_build_object(
        'icmsOwnValue', v_icms_own, 'ipi', v_ipi,
        'icmsSt', v_st_val, 'baseST', v_base_st),
      'itemTotals', jsonb_build_object(
        'vFCP', v_fcp_own, 'vFCPST', v_fcp_st,
        'vICMSUFDest', v_difal_dest, 'vICMSUFRemet', v_difal_orig,
        'vFCPUFDest', v_fcp_dest),
      'taxes', item_taxes);

    UPDATE public.fiscal_invoice_items
       SET tax_snapshot = item_snapshot,
           cfop_snapshot = pol.cfop,
           cst_icms_snapshot = item_taxes->'ICMS'->>'cst',
           csosn_snapshot = item_taxes->'ICMS'->>'csosn',
           net_value = coalesce((item_taxes->'ICMS'->>'baseOriginal')::numeric, v_prod),
           updated_at = now()
     WHERE id = it.id;
  END LOOP;

  IF n_items = 0 THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NO_ITEMS: documento sem itens.';
  END IF;

  -- H12: o total comercial do rascunho NAO contem tributos somados ao documento
  -- (ST/FCP-ST/IPI). O guard permanece, mas compara grandezas equivalentes.
  t_com := public.fn_fiscal_round(t_prod - t_desc + t_frete + t_seg + t_outros);
  t_nf  := public.fn_fiscal_round(t_com + t_st + t_fcpst + t_ipi);

  IF inv.total_amount IS NOT NULL
     AND abs(inv.total_amount - t_com) > 0.01
     AND abs(inv.total_amount - t_nf)  > 0.01 THEN
    RAISE EXCEPTION 'FISCAL_TOTAL_MISMATCH: total informado % difere do total comercial % e do total fiscal %',
      inv.total_amount, t_com, t_nf;
  END IF;

  totals := jsonb_build_object(
    'engineVersion','F3.4', 'roundingMode','HALF_UP_2',
    'itemCount', n_items,
    'vProd', public.fn_fiscal_round(t_prod), 'vDesc', public.fn_fiscal_round(t_desc),
    'vFrete', public.fn_fiscal_round(t_frete), 'vSeg', public.fn_fiscal_round(t_seg),
    'vOutro', public.fn_fiscal_round(t_outros),
    'vICMS', public.fn_fiscal_round(t_icms), 'vST', public.fn_fiscal_round(t_st),
    'vFCP', public.fn_fiscal_round(t_fcp), 'vFCPST', public.fn_fiscal_round(t_fcpst),
    'vDIFAL', public.fn_fiscal_round(t_difal),
    'vPIS', public.fn_fiscal_round(t_pis), 'vCOFINS', public.fn_fiscal_round(t_cofins),
    'vIPI', public.fn_fiscal_round(t_ipi), 'vNF', t_nf, 'vCommercial', t_com,
    'debtor', debtor);

  IF has_difal THEN
    totals := totals || jsonb_build_object(
      'vICMSUFDest', public.fn_fiscal_round(t_difal_dest),
      'vICMSUFRemet', public.fn_fiscal_round(t_difal_orig),
      'vFCPUFDest', public.fn_fiscal_round(t_fcp_dest));
  END IF;

  UPDATE public.fiscal_invoices
     SET tax_snapshot = totals,
         fiscal_totals_snapshot = totals,
         total_amount = t_nf,
         debtor_partner_id = coalesce(inv.debtor_partner_id, nullif(debtor->>'debtorPartnerId','')::uuid),
         debtor_customer_id = coalesce(inv.debtor_customer_id, nullif(debtor->>'recipientCustomerId','')::uuid),
         company_snapshot = jsonb_build_object(
           'cnpj', emit.cnpj, 'legalName', emit.legal_name, 'crt', emit.crt,
           'ie', emit.state_registration, 'uf', emit.state,
           'municipalityIbge', emit.municipality_ibge_code,
           'series', emit.nfe_series_number, 'environment', emit.nfe_environment_code),
         customer_snapshot = jsonb_build_object(
           'document', dest.cpf_cnpj, 'legalName', dest.legal_name,
           'indIEDest', dest.taxpayer_indicator, 'uf', dest.fiscal_state,
           'municipalityIbge', dest.fiscal_municipality_ibge_code,
           'finalConsumer', dest.final_consumer, 'icmsTaxpayer', dest.icms_taxpayer,
           'debtorPartnerId', debtor->>'debtorPartnerId'),
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.fiscal_calculation_runs (fiscal_invoice_id, idempotency_key, engine_version, result, created_by)
  VALUES (p_invoice_id, p_idempotency_key, 'F3.4', totals, auth.uid());

  RETURN totals || jsonb_build_object('idempotentReplay', false);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_certificate_register_a1(p_company_settings_id uuid, p_created_by uuid, p_display_name text, p_subject_name text, p_issuer_name text, p_serial_number text, p_valid_from timestamp with time zone, p_valid_until timestamp with time zone, p_fingerprint_sha256 text, p_key_usage text[], p_object_path text, p_material_iv_b64 text, p_key_version integer, p_material_format text DEFAULT 'SIGNING_BUNDLE_V2'::text, p_material_algorithm text DEFAULT 'AES-256-GCM'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF current_setting('request.jwt.claim.role', true) IN ('anon', 'authenticated') THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  IF p_company_settings_id IS NULL THEN
    RAISE EXCEPTION 'company_settings_id_required' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.company_fiscal_settings
    WHERE id = p_company_settings_id AND is_active = true
  ) THEN
    RAISE EXCEPTION 'company_settings_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF p_fingerprint_sha256 IS NULL OR p_fingerprint_sha256 !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'fingerprint_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_valid_until IS NULL OR p_valid_until <= now() THEN
    RAISE EXCEPTION 'certificate_expired' USING ERRCODE = '22023';
  END IF;
  IF p_object_path IS NULL OR length(p_object_path) = 0 THEN
    RAISE EXCEPTION 'object_path_required' USING ERRCODE = '22023';
  END IF;
  IF p_material_iv_b64 IS NULL OR length(p_material_iv_b64) = 0 THEN
    RAISE EXCEPTION 'material_iv_required' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_material_format, '') <> 'SIGNING_BUNDLE_V2' THEN
    RAISE EXCEPTION 'material_format_unsupported' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_material_algorithm, '') <> 'AES-256-GCM' THEN
    RAISE EXCEPTION 'material_algorithm_unsupported' USING ERRCODE = '22023';
  END IF;

  UPDATE public.fiscal_certificates
  SET is_active = false,
      status = CASE WHEN status = 'AVAILABLE' THEN 'REVOKED' ELSE status END,
      revoked_at = now(),
      revoked_by = p_created_by,
      revoke_reason = COALESCE(revoke_reason, 'substituido por novo A1'),
      updated_at = now()
  WHERE company_settings_id = p_company_settings_id
    AND environment = 'HOMOLOGATION'
    AND is_active = true;

  INSERT INTO public.fiscal_certificates (
    company_settings_id, source_type, environment, status,
    display_name, subject_name, issuer_name, serial_number,
    valid_from, valid_until, fingerprint_sha256, key_usage,
    is_active, created_by
  ) VALUES (
    p_company_settings_id, 'A1_UPLOAD', 'HOMOLOGATION', 'AVAILABLE',
    p_display_name, p_subject_name, p_issuer_name, p_serial_number,
    p_valid_from, p_valid_until, lower(p_fingerprint_sha256), p_key_usage,
    true, p_created_by
  ) RETURNING id INTO v_id;

  INSERT INTO public.fiscal_certificate_material (
    certificate_id, object_path, material_iv, key_version,
    material_format, material_algorithm
  ) VALUES (
    v_id, p_object_path, decode(p_material_iv_b64, 'base64'),
    COALESCE(p_key_version, 1), p_material_format, p_material_algorithm
  );

  UPDATE public.company_fiscal_settings
  SET certificate_ref = v_id::text,
      updated_at = now()
  WHERE id = p_company_settings_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_certificate_register_os(p_company_settings_id uuid, p_metadata jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user            uuid := auth.uid();
  v_id              uuid;
  v_display_name    text;
  v_native_alias    text;
  v_subject         text;
  v_issuer          text;
  v_serial          text;
  v_from            timestamptz;
  v_until           timestamptz;
  v_fp              text;
  v_env             text := 'HOMOLOGATION';
  ALLOWED_KEYS      text[] := ARRAY[
    'display_name','native_alias','subject_name','issuer_name',
    'serial_number','valid_from','valid_until','fingerprint_sha256','key_usage'
  ];
  k text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_role(v_user, 'administrador'::app_role) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata) <> 'object' THEN
    RAISE EXCEPTION 'metadata_object_required' USING ERRCODE = '22023';
  END IF;
  IF public.fiscal_json_has_sensitive_key(p_metadata) THEN
    RAISE EXCEPTION 'sensitive_key_in_payload' USING ERRCODE = '22023';
  END IF;

  -- 3.16.2-C: exigir company_settings_id existente antes de qualquer escrita
  IF p_company_settings_id IS NULL THEN
    RAISE EXCEPTION 'company_settings_id_required' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.company_fiscal_settings WHERE id = p_company_settings_id
  ) THEN
    RAISE EXCEPTION 'company_settings_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Whitelist estrita de chaves
  FOR k IN SELECT jsonb_object_keys(p_metadata) LOOP
    IF NOT (k = ANY(ALLOWED_KEYS)) THEN
      RAISE EXCEPTION 'metadata_key_not_allowed' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- Ambiente sempre HOMOLOGATION nesta fase (PRODUCTION bloqueado)
  IF v_env <> 'HOMOLOGATION' THEN
    RAISE EXCEPTION 'environment_not_allowed' USING ERRCODE = '22023';
  END IF;

  v_display_name := COALESCE(NULLIF(p_metadata->>'display_name',''), 'Certificado do sistema operacional');
  IF char_length(v_display_name) > 120 THEN
    RAISE EXCEPTION 'display_name_too_long' USING ERRCODE = '22023';
  END IF;

  v_native_alias := NULLIF(p_metadata->>'native_alias','');
  IF v_native_alias IS NOT NULL AND char_length(v_native_alias) > 200 THEN
    RAISE EXCEPTION 'native_alias_too_long' USING ERRCODE = '22023';
  END IF;

  v_subject := NULLIF(p_metadata->>'subject_name','');
  IF v_subject IS NULL OR char_length(v_subject) > 500 THEN
    RAISE EXCEPTION 'subject_name_invalid' USING ERRCODE = '22023';
  END IF;

  v_issuer := NULLIF(p_metadata->>'issuer_name','');
  IF v_issuer IS NULL OR char_length(v_issuer) > 500 THEN
    RAISE EXCEPTION 'issuer_name_invalid' USING ERRCODE = '22023';
  END IF;

  v_serial := NULLIF(p_metadata->>'serial_number','');
  IF v_serial IS NULL OR char_length(v_serial) > 128 THEN
    RAISE EXCEPTION 'serial_number_invalid' USING ERRCODE = '22023';
  END IF;

  v_fp := lower(COALESCE(p_metadata->>'fingerprint_sha256',''));
  IF v_fp !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'fingerprint_sha256_invalid' USING ERRCODE = '22023';
  END IF;

  v_from  := NULLIF(p_metadata->>'valid_from','')::timestamptz;
  v_until := NULLIF(p_metadata->>'valid_until','')::timestamptz;
  IF v_from IS NULL OR v_until IS NULL THEN
    RAISE EXCEPTION 'validity_required' USING ERRCODE = '22023';
  END IF;
  IF v_from >= v_until THEN
    RAISE EXCEPTION 'validity_range_invalid' USING ERRCODE = '22023';
  END IF;
  -- 3.16.2-C: notBefore server-side (v_from <= now() < v_until)
  IF v_from > now() THEN
    RAISE EXCEPTION 'certificate_not_yet_valid' USING ERRCODE = '22023';
  END IF;
  IF now() >= v_until THEN
    RAISE EXCEPTION 'certificate_expired' USING ERRCODE = '22023';
  END IF;

  -- 3.16.2-C: key_usage — max 20 itens, cada string 1..80, apenas strings
  IF p_metadata ? 'key_usage' THEN
    PERFORM public.fiscal_validate_key_usage(p_metadata->'key_usage');
  END IF;

  -- Revoga certificados ativos anteriores de homologação
  UPDATE public.fiscal_certificates SET
    is_active = false,
    status = CASE WHEN status = 'AVAILABLE' THEN 'REVOKED' ELSE status END,
    revoked_at = now(), revoked_by = v_user, updated_at = now()
  WHERE company_settings_id = p_company_settings_id
    AND environment = v_env
    AND is_active = true;

  INSERT INTO public.fiscal_certificates (
    company_settings_id, source_type, environment, status,
    display_name, native_alias, subject_name, issuer_name, serial_number,
    valid_from, valid_until, fingerprint_sha256, key_usage, created_by
  ) VALUES (
    p_company_settings_id, 'SYSTEM_STORE', v_env, 'AVAILABLE',
    v_display_name, v_native_alias, v_subject, v_issuer, v_serial,
    v_from, v_until, v_fp,
    CASE
      WHEN p_metadata ? 'key_usage'
      THEN ARRAY(SELECT jsonb_array_elements_text(p_metadata->'key_usage'))
      ELSE NULL
    END,
    v_user
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.user_edit_f2_common(p_user uuid, p_stamp timestamp with time zone, p_profile jsonb, p_roles app_role[], p_clients uuid[], p_primary uuid, p_partner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid; envelope jsonb:=p_profile->'_external_edit'; common jsonb:=p_profile-'_external_edit';
 current_roles public.app_role[]; before_version text; after_version text; req_hash text; receipt record;
 key uuid; reason text; stamp timestamptz; old_common jsonb; new_common jsonb; result jsonb; k text;
BEGIN
 -- Reject unauthorized callers before any global or target row lock.
 -- Repeat full authorization after locks to close concurrent permission changes.
 IF auth.uid() IS NULL
 OR platform_private.platform_actor_access_ready(auth.uid()) IS NOT TRUE
 OR platform_private.is_tenant_admin_for_user(p_user) IS NOT TRUE
 THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.user_edit_f2_gate WHERE singleton AND reviewed)
 THEN RAISE EXCEPTION 'user_edit_phase_closed' USING ERRCODE='42501'; END IF;
 -- Lock order shared with ALL existing identity/link DML (statement trigger).
 -- NOWAIT prevents reverse-order legacy writers from causing a deadlock; retry is explicit.
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 PERFORM 1 FROM platform_private.user_edit_f2_gate WHERE singleton AND reviewed FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_phase_closed' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id IN (auth.uid(),p_user) ORDER BY user_id FOR UPDATE;
 org:=platform_private.user_edit_f2_authorize(p_user);
 PERFORM 1 FROM public.user_roles WHERE user_id IN (auth.uid(),p_user) ORDER BY user_id,id FOR UPDATE;
 PERFORM 1 FROM public.user_clientes WHERE user_id=p_user ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.partner_users WHERE user_id=p_user ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.clientes WHERE id IN (SELECT cliente_id FROM public.user_clientes WHERE user_id=p_user) ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.partner_accounts WHERE id IN (SELECT partner_id FROM public.partner_users WHERE user_id=p_user) ORDER BY id FOR SHARE;
 SELECT array_agg(role ORDER BY role::text) INTO current_roles FROM public.user_roles WHERE user_id=p_user;
 IF current_roles IS NULL OR cardinality(current_roles)<>1 OR current_roles[1] NOT IN ('cliente_produtor','parceiro_b2b')
 OR p_roles IS DISTINCT FROM current_roles THEN RAISE EXCEPTION 'user_edit_linked_role_unavailable' USING ERRCODE='42501'; END IF;
 IF cardinality(coalesce(p_clients,'{}'::uuid[]))<>0 OR p_primary IS NOT NULL OR p_partner IS NOT NULL THEN
  RAISE EXCEPTION 'user_edit_unscoped_links_forbidden' USING ERRCODE='42501'; END IF;
 -- Common-only path may preserve inactive/revoked links, but never adopt unowned ones.
 IF EXISTS(SELECT 1 FROM public.user_clientes u LEFT JOIN public.clientes c ON c.id=u.cliente_id WHERE u.user_id=p_user AND c.organization_id IS DISTINCT FROM org)
 OR EXISTS(SELECT 1 FROM public.partner_users u LEFT JOIN public.partner_accounts p ON p.id=u.partner_id WHERE u.user_id=p_user AND p.commercial_owner_organization_id IS DISTINCT FROM org)
 THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(envelope) IS DISTINCT FROM 'object' OR envelope->>'mode' IS DISTINCT FROM 'common_preserve_links'
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(envelope) x WHERE x NOT IN ('mode','expected_version','idempotency_key','reason'))
 OR jsonb_typeof(envelope->'expected_version') IS DISTINCT FROM 'string' OR (envelope->>'expected_version') !~ '^[a-f0-9]{64}$'
 OR jsonb_typeof(envelope->'idempotency_key') IS DISTINCT FROM 'string' OR (envelope->>'idempotency_key') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
 OR jsonb_typeof(envelope->'reason') IS DISTINCT FROM 'string' OR char_length(btrim(envelope->>'reason')) NOT BETWEEN 2 AND 500
 OR p_stamp IS NULL THEN RAISE EXCEPTION 'user_edit_invalid_input' USING ERRCODE='22023'; END IF;
 key:=(envelope->>'idempotency_key')::uuid; reason:=btrim(envelope->>'reason');
 -- Exactly these six payload fields are intentional (not a profiles column count).
 -- Omitting a nullable field must not silently clear it in a whole-form update.
 IF (SELECT count(*) FROM jsonb_object_keys(common))<>6 OR EXISTS(SELECT 1 FROM jsonb_object_keys(common) x WHERE x NOT IN ('nome','telefone','cargo','cpf_cnpj','crea','especialidade')) THEN
 RAISE EXCEPTION 'user_edit_invalid_fields' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT jsonb_object_keys(common) LOOP
 IF jsonb_typeof(common->k) NOT IN ('string','null') OR char_length(coalesce(common->>k,''))>500 THEN RAISE EXCEPTION 'user_edit_invalid_fields' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF jsonb_typeof(common->'nome') IS DISTINCT FROM 'string' OR char_length(btrim(common->>'nome')) NOT BETWEEN 2 AND 150 THEN RAISE EXCEPTION 'user_edit_invalid_name' USING ERRCODE='22023'; END IF;
 IF nullif(common->>'telefone','') IS NOT NULL AND (common->>'telefone') !~ '^[0-9]{10,11}$' THEN RAISE EXCEPTION 'user_edit_invalid_phone' USING ERRCODE='22023'; END IF;
 req_hash:=encode(extensions.digest(convert_to(jsonb_build_object('target',p_user,'stamp',p_stamp,'profile',p_profile,'roles',p_roles,'clients',p_clients,'primary',p_primary,'partner',p_partner)::text,'UTF8'),'sha256'),'hex');
 -- Authorization, target type, ownership and gates were revalidated BEFORE replay.
 SELECT * INTO receipt FROM platform_private.user_edit_f2_audit WHERE actor_id=auth.uid() AND organization_id=org AND idempotency_key=key;
 IF FOUND THEN
  IF receipt.request_hash IS DISTINCT FROM req_hash THEN RAISE EXCEPTION 'user_edit_idempotency_conflict' USING ERRCODE='PT409'; END IF;
  -- A retry after unrelated target changes must not present a stale result as current.
  IF receipt.version_after IS DISTINCT FROM platform_private.user_edit_f2_version(p_user) THEN RAISE EXCEPTION 'user_edit_conflict' USING ERRCODE='PT409'; END IF;
  RETURN receipt.result || jsonb_build_object('replayed',true);
 END IF;
 before_version:=platform_private.user_edit_f2_version(p_user);
 SELECT updated_at,jsonb_build_object('nome',nome,'telefone',telefone,'cargo',cargo,'cpf_cnpj',cpf_cnpj,'crea',crea,'especialidade',especialidade)
 INTO stamp,old_common FROM public.profiles WHERE user_id=p_user;
 IF before_version IS DISTINCT FROM envelope->>'expected_version' OR stamp IS DISTINCT FROM p_stamp THEN RAISE EXCEPTION 'user_edit_conflict' USING ERRCODE='PT409'; END IF;
 UPDATE public.profiles SET nome=btrim(common->>'nome'),telefone=nullif(common->>'telefone',''),cargo=nullif(common->>'cargo',''),cpf_cnpj=nullif(common->>'cpf_cnpj',''),crea=nullif(common->>'crea',''),especialidade=nullif(common->>'especialidade','')
 WHERE user_id=p_user RETURNING updated_at,jsonb_build_object('nome',nome,'telefone',telefone,'cargo',cargo,'cpf_cnpj',cpf_cnpj,'crea',crea,'especialidade',especialidade) INTO stamp,new_common;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_not_found' USING ERRCODE='P0002'; END IF;
 after_version:=platform_private.user_edit_f2_version(p_user);
 result:=jsonb_build_object('success',true,'user_id',p_user,'updated_at',stamp,'version',after_version,'replayed',false,'links_preserved',true);
 INSERT INTO platform_private.user_edit_f2_audit(actor_id,organization_id,target_id,idempotency_key,request_hash,reason,version_before,version_after,old_common,new_common,result)
 VALUES(auth.uid(),org,p_user,key,req_hash,reason,before_version,after_version,old_common,new_common,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_draft_validate_homologation(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_user    uuid := auth.uid();
  v_row     public.fiscal_invoices;
  v_items   integer;
  v_missing jsonb := '[]'::jsonb;
  v_status  text;
  v_has_cert boolean;
  v_has_company boolean;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(p_invoice_id);

  IF v_user IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT (public.has_role(v_user, 'administrador'::app_role)
          OR public.has_role(v_user, 'financeiro'::app_role)
          OR public.has_role(v_user, 'gestor'::app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002'; END IF;

  IF v_row.status <> 'DRAFT' THEN
    RETURN jsonb_build_object(
      'status','BLOCKED',
      'reason','Documento nao esta em rascunho (status atual: '||v_row.status||').'
    );
  END IF;
  IF v_row.provider <> 'NONE' THEN
    RETURN jsonb_build_object(
      'status','BLOCKED',
      'reason','Documento com provedor configurado nao pode ser homologado por esta central.'
    );
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) cs WHERE cs.cnpj = v_row.company_cnpj
  ) INTO v_has_company;

  SELECT EXISTS (
    SELECT 1 FROM (SELECT * FROM public.fiscal_certificates WHERE public.h15_company_access(company_settings_id)) fc
    JOIN (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) cs ON cs.id = fc.company_settings_id
    WHERE cs.cnpj = v_row.company_cnpj
      AND fc.environment = 'HOMOLOGATION'
      AND fc.is_active = true
      AND fc.status = 'AVAILABLE'
  ) INTO v_has_cert;

  IF NOT v_has_company THEN
    v_missing := v_missing || jsonb_build_object('field','company','message','Configuracao fiscal da empresa nao encontrada.');
  END IF;
  IF v_row.customer_id IS NULL THEN
    v_missing := v_missing || jsonb_build_object('field','customer','message','Cliente destinatario e obrigatorio.');
  ELSIF NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = v_row.customer_id) THEN
    v_missing := v_missing || jsonb_build_object('field','customer','message','Cliente informado nao existe mais no cadastro.');
  END IF;
  IF v_row.invoice_type IS NULL THEN
    v_missing := v_missing || jsonb_build_object('field','invoice_type','message','Tipo de documento (NF-e/NFS-e) e obrigatorio.');
  END IF;
  IF v_row.document_model IS NULL THEN
    v_missing := v_missing || jsonb_build_object('field','document_model','message','Modelo do documento e obrigatorio.');
  END IF;
  IF v_row.series IS NULL THEN
    v_missing := v_missing || jsonb_build_object('field','series','message','Serie do documento e obrigatoria.');
  END IF;
  IF v_row.issue_date IS NULL THEN
    v_missing := v_missing || jsonb_build_object('field','issue_date','message','Data de emissao e obrigatoria.');
  END IF;

  SELECT COUNT(*) INTO v_items FROM (SELECT * FROM public.fiscal_invoice_items WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_invoice_items WHERE fiscal_invoice_id = p_invoice_id;
  IF v_items = 0 THEN
    v_missing := v_missing || jsonb_build_object('field','items','message','Documento precisa de ao menos um item.');
  END IF;

  -- 3.16.2-C: perfil fiscal + tributos obrigatórios por item
  -- Produto (NF-e): NCM, CFOP e (CST_ICMS ou CSOSN).
  -- Serviço (NFS-e): LC116, CNAE e ISS rate.
  DECLARE
    r RECORD;
    v_prof jsonb;
    v_tax  jsonb;
    v_icms jsonb;
    v_has_cst_or_csosn boolean;
  BEGIN
    FOR r IN
      SELECT item_sequence, item_kind,
             COALESCE(fiscal_profile_snapshot, '{}'::jsonb) AS prof,
             COALESCE(tax_snapshot, '{}'::jsonb) AS tax
      FROM (SELECT * FROM public.fiscal_invoice_items WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_invoice_items
      WHERE fiscal_invoice_id = p_invoice_id
      ORDER BY item_sequence
    LOOP
      v_prof := r.prof;
      v_tax  := r.tax;
      IF r.item_kind = 'PRODUCT' THEN
        IF v_prof = '{}'::jsonb OR NULLIF(v_prof->>'ncm','') IS NULL THEN
          v_missing := v_missing || jsonb_build_object(
            'field','item_fiscal_profile','item_sequence', r.item_sequence,
            'message','Item '||r.item_sequence||' sem NCM no perfil fiscal.'
          );
        END IF;
        IF NULLIF(v_prof->>'cfop','') IS NULL THEN
          v_missing := v_missing || jsonb_build_object(
            'field','item_cfop','item_sequence', r.item_sequence,
            'message','Item '||r.item_sequence||' sem CFOP no perfil fiscal.'
          );
        END IF;
        v_icms := v_tax->'icms';
        v_has_cst_or_csosn :=
          NULLIF(v_prof->>'cst_icms','') IS NOT NULL
          OR NULLIF(v_prof->>'csosn','') IS NOT NULL
          OR (v_icms IS NOT NULL AND (NULLIF(v_icms->>'cst','') IS NOT NULL OR NULLIF(v_icms->>'csosn','') IS NOT NULL));
        IF NOT v_has_cst_or_csosn THEN
          v_missing := v_missing || jsonb_build_object(
            'field','item_cst_csosn','item_sequence', r.item_sequence,
            'message','Item '||r.item_sequence||' sem CST_ICMS ou CSOSN definido.'
          );
        END IF;
      ELSIF r.item_kind = 'SERVICE' THEN
        IF v_prof = '{}'::jsonb OR NULLIF(v_prof->>'lc116_item','') IS NULL THEN
          v_missing := v_missing || jsonb_build_object(
            'field','item_lc116','item_sequence', r.item_sequence,
            'message','Item '||r.item_sequence||' sem item LC 116 no perfil fiscal.'
          );
        END IF;
        IF NULLIF(v_prof->>'cnae','') IS NULL THEN
          v_missing := v_missing || jsonb_build_object(
            'field','item_cnae','item_sequence', r.item_sequence,
            'message','Item '||r.item_sequence||' sem CNAE no perfil fiscal.'
          );
        END IF;
        IF NOT (v_tax ? 'iss_rate') OR jsonb_typeof(v_tax->'iss_rate') <> 'number' THEN
          v_missing := v_missing || jsonb_build_object(
            'field','item_iss_rate','item_sequence', r.item_sequence,
            'message','Item '||r.item_sequence||' sem aliquota de ISS definida.'
          );
        END IF;
      END IF;
    END LOOP;
  END;

  IF v_row.customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.customer_fiscal_profiles WHERE customer_id = v_row.customer_id
  ) THEN
    v_missing := v_missing || jsonb_build_object('field','customer_fiscal_profile','message','Cliente ainda nao possui perfil fiscal cadastrado.');
  END IF;

  IF NOT v_has_cert THEN
    v_missing := v_missing || jsonb_build_object('field','certificate','message','Certificado digital ativo para homologacao nao configurado.');
  END IF;

  v_status := CASE WHEN jsonb_array_length(v_missing) = 0 THEN 'READY' ELSE 'INCOMPLETE' END;

  RETURN jsonb_build_object(
    'status', v_status,
    'missing', v_missing,
    'item_count', v_items,
    'total_amount', v_row.total_amount
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_company_settings_init()
 RETURNS company_fiscal_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_existing public.company_fiscal_settings;
  v_actor    uuid;
BEGIN
  PERFORM public.h15_require_staff();

  BEGIN
    v_actor := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_actor := NULL;
  END;
  IF v_actor IS NULL OR NOT public.has_role(v_actor, 'administrador') THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  -- Advisory lock transacional: elimina corrida de singleton entre
  -- chamadas concorrentes desta RPC.
  PERFORM pg_advisory_xact_lock(hashtext('fiscal_company_settings_singleton'));

  SELECT * INTO v_existing
    FROM (SELECT * FROM public.company_fiscal_settings WHERE organization_id = public.h15_actor_organization()) company_fiscal_settings
    WHERE is_active = true
    LIMIT 1;
  IF v_existing.id IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  INSERT INTO public.company_fiscal_settings (
    organization_id, is_active, fiscal_environment, configuration_status,
    fiscal_provider, nfe_provider, nfse_provider,
    nfe_enabled, nfse_enabled, production_enabled,
    last_validation_status, configuration_version,
    created_by, updated_by
  ) VALUES (
    public.h15_actor_organization(), true, 'NOT_CONFIGURED', 'DRAFT',
    'NONE', 'NONE', 'NONE',
    false, false, false,
    'NOT_VALIDATED', 1,
    v_actor, v_actor
  ) RETURNING * INTO v_existing;

  RETURN v_existing;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_rule_sod_override(p_scope text, p_target_id uuid, p_justification text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT public.has_role(auth.uid(),'administrador'::app_role) THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: somente administrador concede override de segregacao.';
  END IF;
  IF p_scope NOT IN ('TAX_RULE','OPERATION_POLICY') THEN
    RAISE EXCEPTION 'FISCAL_SOD_SCOPE_INVALID: %', p_scope;
  END IF;
  IF length(btrim(coalesce(p_justification,''))) < 40 THEN
    RAISE EXCEPTION 'FISCAL_SOD_JUSTIFICATION_REQUIRED: justificativa com pelo menos 40 caracteres.';
  END IF;
  INSERT INTO public.fiscal_rule_sod_overrides (scope, target_id, justification, granted_by)
  VALUES (p_scope, p_target_id, btrim(p_justification), auth.uid())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('overrideId', v_id, 'scope', p_scope, 'targetId', p_target_id);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_emitter_accounting_validate(p_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE r public.company_fiscal_settings%ROWTYPE;
BEGIN
  PERFORM public.h15_require_staff();

  IF NOT public.fn_regulatory_can_approve('FISCAL') THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: somente responsavel fiscal/contabil valida o emitente.';
  END IF;
  IF length(btrim(coalesce(p_notes,''))) < 20 THEN
    RAISE EXCEPTION 'FISCAL_JUSTIFICATION_REQUIRED: registre a justificativa da validacao (min. 20 caracteres).';
  END IF;
  SELECT * INTO r FROM (SELECT * FROM public.company_fiscal_settings WHERE organization_id = public.h15_actor_organization()) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EMITTER_NOT_CONFIGURED: emitente nao cadastrado.'; END IF;
  IF r.updated_by IS NOT NULL AND r.updated_by = auth.uid() AND r.configuration_status = 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_SEGREGATION_OF_DUTIES: preparador e validador contabil devem ser pessoas distintas.';
  END IF;
  UPDATE public.company_fiscal_settings
     SET configuration_status = 'VALIDATED', accounting_validated_at = now(),
         accounting_validated_by = auth.uid(), configuration_notes = btrim(p_notes), updated_at = now()
   WHERE id = r.id;
  RETURN jsonb_build_object('companyId', r.id, 'status','VALIDATED');
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_attempt_scope_lock(p_uid uuid, p_partner uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
DECLARE org uuid; fresh uuid;
BEGIN
 IF p_uid IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'C2DJ_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.c2_partner_order_attempt_authz(p_uid,p_partner);
 SELECT organization_id INTO org FROM public.profiles WHERE user_id=p_uid AND ativo;
 IF org IS NULL THEN RAISE EXCEPTION 'C2DJ_ORG_REQUIRED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('b2b_attempt_scope:'||p_uid::text||':'||org::text||':'||p_partner::text,0));
 PERFORM platform_private.c2_partner_order_attempt_authz(p_uid,p_partner);
 SELECT organization_id INTO fresh FROM public.profiles WHERE user_id=p_uid AND ativo;
 IF fresh IS DISTINCT FROM org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 RETURN org;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_close_partner_order_attempt_core(p_partner_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_idem text;
  v_scope_org uuid; v_current_org uuid;
  v_found boolean; v_order_id uuid; v_numero text;
BEGIN
  -- Autorização canônica ANTES do lock e de revelar qualquer estado.
  PERFORM platform_private.c2_partner_order_attempt_authz(v_uid, p_partner_id);
  v_scope_org := platform_private.c2_attempt_scope_lock(v_uid,p_partner_id);
  v_idem := NULLIF(btrim(COALESCE(p_idempotency_key,'')),'');
  IF v_idem IS NULL THEN RAISE EXCEPTION 'idempotency_key_required'; END IF;
  IF length(v_idem) > 120 THEN RAISE EXCEPTION 'invalid_idempotency_key'; END IF;

  -- MESMO lock do create. Espera limitada (lock_timeout da função): estouro => in_progress,
  -- nunca conclusivo e sem nenhuma escrita.
  BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:' || p_partner_id::text || ':' || v_idem, 0));
  EXCEPTION WHEN lock_not_available THEN
    RETURN jsonb_build_object('contract','C2_ORDER_ATTEMPT_CLOSURE_V1','state','in_progress');
  END;

  -- Revalida APÓS a espera: revogação/perfil/parceiro inativo confirmados durante a espera
  -- abortam sem revelar committed e sem gravar closed.
  PERFORM platform_private.c2_partner_order_attempt_authz(v_uid, p_partner_id);
  SELECT organization_id INTO v_current_org FROM public.profiles WHERE user_id=v_uid AND ativo;
  IF v_current_org IS DISTINCT FROM v_scope_org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;

  SELECT true, i.order_id INTO v_found, v_order_id
    FROM public.partner_order_idempotency i
   WHERE i.partner_id = p_partner_id AND i.idempotency_key = v_idem;
  IF v_found THEN
    SELECT o.numero INTO v_numero FROM public.partner_orders o WHERE o.id = v_order_id;
    RETURN jsonb_build_object('contract','C2_ORDER_ATTEMPT_CLOSURE_V1','state','committed',
                              'order_id', v_order_id, 'numero', v_numero);
  END IF;

  INSERT INTO platform_private.partner_order_idempotency_closures(partner_id, idempotency_key, closed_by, closed_org)
  VALUES (p_partner_id, v_idem, v_uid,
          (SELECT p.organization_id FROM public.profiles p WHERE p.user_id = v_uid))
  ON CONFLICT (partner_id, idempotency_key) DO NOTHING;
  RETURN jsonb_build_object('contract','C2_ORDER_ATTEMPT_CLOSURE_V1','state','closed');
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.c2_recover_order_attempt_core(p_partner uuid, p_expected_key text DEFAULT NULL::text, p_expected_generation bigint DEFAULT NULL::bigint, p_advance boolean DEFAULT false, p_ack_order uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
DECLARE uid uuid:=auth.uid(); org uuid; j platform_private.partner_order_attempt_journal;
  result jsonb; nextgen bigint; nextkey text; fresh uuid; predecessors jsonb;
BEGIN
 org := platform_private.c2_attempt_scope_lock(uid,p_partner);
 SELECT * INTO j FROM platform_private.partner_order_attempt_journal
 WHERE actor_id=uid AND organization_id=org AND partner_id=p_partner ORDER BY generation DESC LIMIT 1;
 -- Immutable journal links plus canonical committed receipts/closure tombstones.
 -- Read only: no inferred closure, no added locks, no client-supplied terminal proof.
 SELECT coalesce(jsonb_agg(jsonb_build_object('key',h.idempotency_key,'generation',h.generation,
   'state',CASE WHEN i.order_id IS NOT NULL THEN 'committed' WHEN c.idempotency_key IS NOT NULL THEN 'closed' ELSE 'unknown' END)
   || CASE WHEN i.order_id IS NOT NULL THEN jsonb_build_object('order_id',i.order_id,'numero',o.numero) ELSE '{}'::jsonb END
   ORDER BY h.generation),'[]'::jsonb) INTO predecessors
 FROM platform_private.partner_order_attempt_journal h
 LEFT JOIN public.partner_order_idempotency i ON i.partner_id=h.partner_id AND i.idempotency_key=h.idempotency_key AND i.created_by=uid
 LEFT JOIN public.partner_orders o ON o.id=i.order_id
 LEFT JOIN platform_private.partner_order_idempotency_closures c ON c.partner_id=h.partner_id AND c.idempotency_key=h.idempotency_key
 WHERE h.actor_id=uid AND h.organization_id=org AND h.partner_id=p_partner AND h.generation<j.generation;
 IF p_advance THEN
  IF j.idempotency_key IS NULL OR p_expected_key IS DISTINCT FROM j.idempotency_key
   OR p_expected_generation IS DISTINCT FROM j.generation THEN
   RAISE EXCEPTION 'C2DJ_CAS_CONFLICT' USING ERRCODE='PT409'; END IF;
  -- Explicit click only; existing atomic close is the ONLY way to abandon uncertain K.
  result := platform_private.c2_close_partner_order_attempt_core(p_partner,j.idempotency_key);
  SELECT organization_id INTO fresh FROM public.profiles WHERE user_id=uid AND ativo;
  IF fresh IS DISTINCT FROM org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  IF result->>'state'='in_progress' THEN RETURN jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','state','unknown'); END IF;
  IF result->>'state'='committed' AND p_ack_order IS DISTINCT FROM (result->>'order_id')::uuid THEN
   RETURN result || jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','key',j.idempotency_key,'generation',j.generation,'predecessors',predecessors); END IF;
  IF result->>'state' NOT IN ('closed','committed') OR result->>'state' IS NULL THEN
   RAISE EXCEPTION 'C2DJ_INVALID_CLOSURE'; END IF;
  predecessors:=predecessors||jsonb_build_array(result||jsonb_build_object('key',j.idempotency_key,'generation',j.generation));
 ELSIF j.idempotency_key IS NOT NULL THEN
  -- Recovery is read-only with respect to closure; never auto-close an absent order.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:'||p_partner::text||':'||j.idempotency_key,0));
  PERFORM platform_private.c2_partner_order_attempt_authz(uid,p_partner);
  SELECT organization_id INTO fresh FROM public.profiles WHERE user_id=uid AND ativo;
  IF fresh IS DISTINCT FROM org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  SELECT jsonb_build_object('state','committed','order_id',i.order_id,'numero',o.numero) INTO result
   FROM public.partner_order_idempotency i JOIN public.partner_orders o ON o.id=i.order_id
   WHERE i.partner_id=p_partner AND i.idempotency_key=j.idempotency_key AND i.created_by=uid;
  IF result IS NULL THEN
   result := jsonb_build_object('state',CASE WHEN EXISTS(SELECT 1 FROM platform_private.partner_order_idempotency_closures
    WHERE partner_id=p_partner AND idempotency_key=j.idempotency_key) THEN 'closed' ELSE 'uncertain' END);
  END IF;
  RETURN result || jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','key',j.idempotency_key,'generation',j.generation,'predecessors',predecessors);
 ELSIF p_expected_key IS NOT NULL OR p_expected_generation IS NOT NULL THEN
  -- Lost legacy memory cannot be adopted by mere key knowledge.
  RAISE EXCEPTION 'C2DJ_LEGACY_RECONCILIATION_REQUIRED' USING ERRCODE='42501';
 END IF;
 nextgen := coalesce(j.generation,0)+1; nextkey := gen_random_uuid()::text;
 IF j.idempotency_key IS NULL AND EXISTS(SELECT 1 FROM public.partner_order_idempotency i
 WHERE i.created_by=uid AND i.partner_id=p_partner) THEN
  RAISE EXCEPTION 'C2DJ_LEGACY_RECONCILIATION_REQUIRED' USING ERRCODE='42501'; END IF;
 INSERT INTO platform_private.partner_order_attempt_journal(actor_id,organization_id,partner_id,generation,idempotency_key,predecessor_key)
 VALUES(uid,org,p_partner,nextgen,nextkey,j.idempotency_key);
 RETURN jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','state','reserved','key',nextkey,'generation',nextgen,'predecessors',predecessors);
END $function$

CREATE OR REPLACE FUNCTION public.convert_partner_simulation_to_order_secure(p_simulation_id uuid, p_observacoes text DEFAULT NULL::text, p_payment_plan_id uuid DEFAULT NULL::uuid, p_first_due_date date DEFAULT NULL::date, p_installment_count integer DEFAULT NULL::integer, p_confirm_price_change boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean; v_is_partner_b2b boolean; v_is_tecnico boolean;
  v_user_partner uuid; v_sim record; v_partner_id uuid;
  v_items jsonb; v_result jsonb; v_order_id uuid;
  v_cart jsonb; v_new_table numeric(14,2);
  v_plan record; v_quote boolean; v_final numeric(14,2); v_hash text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF p_payment_plan_id IS NULL THEN RAISE EXCEPTION 'payment_plan_required'; END IF;

  v_is_admin := has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial');
  v_is_partner_b2b := has_role(v_uid,'parceiro_b2b');
  v_is_tecnico := has_role(v_uid,'parceiro_b2b_tecnico');

  IF v_is_tecnico AND NOT v_is_admin AND NOT v_is_partner_b2b THEN
    RAISE EXCEPTION 'forbidden_role_tecnico_cannot_convert';
  END IF;
  IF NOT (v_is_admin OR v_is_partner_b2b) THEN RAISE EXCEPTION 'forbidden_role'; END IF;

  SELECT * INTO v_sim FROM public.partner_simulations WHERE id = p_simulation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'simulation_not_found'; END IF;
  IF v_sim.status = 'convertida_pedido' THEN RAISE EXCEPTION 'already_converted'; END IF;
  IF v_sim.status NOT IN ('rascunho','enviada_gestor') THEN RAISE EXCEPTION 'invalid_status'; END IF;

  v_partner_id := v_sim.partner_id;
  PERFORM platform_private.assert_b2b_partner_scope(v_uid, v_partner_id);
  IF v_is_partner_b2b AND NOT v_is_admin THEN
    v_user_partner := get_user_partner_id();
    IF v_user_partner IS NULL OR v_user_partner <> v_partner_id THEN RAISE EXCEPTION 'forbidden_partner'; END IF;
  END IF;

  IF v_sim.valid_until IS NOT NULL AND v_sim.valid_until < current_date
     AND NOT p_confirm_price_change THEN
    RAISE EXCEPTION 'simulation_expired_requires_confirmation';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'item_id', item_id, 'item_tipo', item_tipo, 'quantidade', quantidade,
           'unidade_medida', COALESCE(unidade_medida,'hectare'), 'volume_ml', volume_ml)), '[]'::jsonb)
    INTO v_items
  FROM public.partner_simulation_items WHERE simulation_id = p_simulation_id;
  IF v_items = '[]'::jsonb THEN RAISE EXCEPTION 'empty_simulation'; END IF;

  SELECT * INTO v_plan FROM public.commercial_payment_plans WHERE id = p_payment_plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF; IF NOT public.fn_b2b_plan_selectable(v_plan.id) THEN RAISE EXCEPTION 'plan_not_selectable'; END IF;

  -- Revalidacao autoritativa do preco no momento da conversao
  v_cart := public.fn_resolve_b2b_cart(v_partner_id, p_payment_plan_id, v_items, current_date);
  v_new_table := (v_cart->>'table_amount')::numeric;

  IF COALESCE(v_sim.total_cheio,0) > 0
     AND ABS(v_new_table - v_sim.total_cheio) > 0.01
     AND NOT p_confirm_price_change THEN
    RAISE EXCEPTION 'price_changed_requires_confirmation: simulado=% atual=%',
      v_sim.total_cheio, v_new_table USING ERRCODE='P0001';
  END IF;

  -- assinatura calculada no servidor a partir do carrinho recem-resolvido
  v_quote := COALESCE((v_cart->>'quote_required')::boolean,false);
  v_final := CASE WHEN v_quote THEN 0
                  ELSE public.fn_b2b_apply_interest((v_cart->>'net_amount')::numeric,
                         v_plan.interest_type, v_plan.monthly_interest_percent, v_plan.months_count) END;
  v_hash := public.fn_b2b_cart_hash(v_partner_id, p_payment_plan_id, v_cart, v_final);

  v_result := public.create_partner_order_secure(
    v_partner_id, COALESCE(p_observacoes, v_sim.observacoes), v_items,
    NULL, p_payment_plan_id, p_first_due_date, p_installment_count,
    v_hash, 'sim:' || p_simulation_id::text);
  v_order_id := (v_result->>'id')::uuid;

  UPDATE public.partner_orders
     SET origin_simulation_id = p_simulation_id, cliente_id = v_sim.cliente_id
   WHERE id = v_order_id;

  UPDATE public.partner_simulations
     SET status='convertida_pedido', converted_order_id=v_order_id,
         converted_by=v_uid, converted_at=now(), updated_at=now()
   WHERE id = p_simulation_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_order_id, v_partner_id, v_uid, 'converted_from_simulation',
          jsonb_build_object('simulation_id', p_simulation_id, 'numero', v_result->>'numero',
                             'cliente_id', v_sim.cliente_id, 'total', v_result->>'total',
                             'cart_hash', v_hash,
                             'price_change_confirmed', p_confirm_price_change));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_converted_to_order', v_partner_id, v_uid, v_sim.cliente_id,
    p_simulation_id, v_order_id, NULL, jsonb_build_object('total', v_result->>'total'));

  RETURN v_order_id;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_promote_accounting_pending_order_core(p_order_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE uid uuid:=auth.uid(); o public.partner_orders; cs public.company_fiscal_settings; n integer; org uuid; v1 jsonb;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 IF NOT platform_private.b2b_internal_commercial_actor() THEN RAISE EXCEPTION 'C2AP_ORDER_DENIED' USING ERRCODE='42501'; END IF;
 org:=public.h15_actor_organization();
 IF org IS NULL OR p_order_id IS NULL THEN RAISE EXCEPTION 'C2AP_ORDER_DENIED' USING ERRCODE='42501'; END IF;
 -- Rows of other organizations do not satisfy the predicate and are skipped without being locked or waited on.
 SELECT * INTO o FROM public.partner_orders WHERE id=p_order_id AND c2_external_origin_snapshot->>'organization_id'=org::text FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'C2AP_ORDER_DENIED' USING ERRCODE='42501'; END IF;
 -- Re-validate authority under the lock (revocation / organization change during the wait).
 IF NOT platform_private.b2b_internal_commercial_actor()
    OR public.h15_actor_organization() IS DISTINCT FROM org
    OR o.c2_external_origin_snapshot->>'organization_id' IS DISTINCT FROM org::text
    OR NOT platform_private.c2p1_settings_allowed(o.partner_id,true) THEN
  RAISE EXCEPTION 'C2AP_ORDER_DENIED' USING ERRCODE='42501';
 END IF;
 IF o.c2_external_origin_snapshot->>'contract' IS DISTINCT FROM 'C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1' THEN RAISE EXCEPTION 'C2AP_NOT_PENDING' USING ERRCODE='22023'; END IF;
 IF p_expected_updated_at IS NULL OR o.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'C2AP_STALE' USING ERRCODE='PT409'; END IF;
 IF o.status::text NOT IN ('em_analise_comercial','aguardando_cotacao','aguardando_aprovacao_credito') THEN RAISE EXCEPTION 'C2AP_STATUS_DENIED' USING ERRCODE='42501'; END IF;
 SELECT count(*) INTO n FROM public.company_fiscal_settings c WHERE c.organization_id=org AND c.is_active;
 IF n=1 THEN SELECT * INTO cs FROM public.company_fiscal_settings c WHERE c.organization_id=org AND c.is_active FOR SHARE; END IF;
 IF n<>1 OR cs.configuration_status IS DISTINCT FROM 'VALIDATED' OR cs.accounting_validated_at IS NULL OR nullif(btrim(cs.legal_name),'') IS NULL OR nullif(btrim(cs.cnpj),'') IS NULL THEN
  RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501';
 END IF;
 v1:=jsonb_build_object('contract','C2_EXTERNAL_ORDER_ORIGIN_V1','schema_version','1','organization_id',org,'creditor_organization_id',org,'issuer_organization_id',org,'company_settings_id',cs.id,'company_configuration_version',cs.configuration_version,'issuer_legal_name',cs.legal_name,'issuer_cnpj',cs.cnpj,'actor_user_id',o.c2_external_origin_snapshot->>'actor_user_id','partner_id',o.partner_id,'promoted_from_contract','C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1','accounting_promoted_by',uid,'accounting_promoted_at',now());
 PERFORM platform_private.issue_ticket('c2_accounting_promote',p_order_id);
 UPDATE public.partner_orders SET c2_external_origin_snapshot=v1, updated_at=now() WHERE id=p_order_id;
 INSERT INTO public.partner_order_audit_logs(id,order_id,partner_id,usuario_id,acao,dados_anteriores,dados_novos,created_at)
 VALUES(gen_random_uuid(),p_order_id,o.partner_id,uid,'c2_accounting_pending_promoted',jsonb_build_object('origin',o.c2_external_origin_snapshot),jsonb_build_object('origin',v1),now());
 RETURN jsonb_build_object('order_id',p_order_id,'contract','C2_EXTERNAL_ORDER_ORIGIN_V1');
END $function$

CREATE OR REPLACE FUNCTION private.fn_public_validation_rate_check(p_token uuid)
 RETURNS TABLE(allowed boolean, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_pepper       bytea;
  v_headers      jsonb;
  v_origin       text;
  v_now          timestamptz := pg_catalog.clock_timestamp();
  v_allowed      boolean := true;
  v_retry        integer := 0;
  v_retry_scope  integer;
  v_value        text;
  v_bucket       bytea;
  v_ws           timestamptz;
  v_hits         integer;
  r              record;
BEGIN
  SELECT p.pepper INTO v_pepper FROM private.public_validation_rate_pepper p WHERE p.id = 1;
  IF v_pepper IS NULL THEN
    -- fail-closed: sem pepper não há como contabilizar com privacidade.
    RAISE EXCEPTION 'rate_limit_not_initialized' USING ERRCODE = '55000';
  END IF;

  BEGIN
    v_headers := nullif(pg_catalog.current_setting('request.headers', true), '')::jsonb;
  EXCEPTION WHEN others THEN
    v_headers := NULL;
  END;
  v_origin := coalesce(
    nullif(pg_catalog.btrim(pg_catalog.split_part(v_headers->>'cf-connecting-ip', ',', 1)), ''),
    nullif(pg_catalog.btrim(pg_catalog.split_part(v_headers->>'x-forwarded-for', ',', 1)), ''),
    nullif(pg_catalog.btrim(v_headers->>'x-real-ip'), ''),
    'unknown');

  FOR r IN
    SELECT pol.scope, pol.max_hits, pol.window_seconds
      FROM private.public_validation_rate_policy pol
     ORDER BY pol.scope
  LOOP
    v_value := CASE r.scope
                 WHEN 'token'  THEN 'token:'  || coalesce(p_token::text, '')
                 WHEN 'origin' THEN 'origin:' || v_origin
                 ELSE 'global'
               END;
    v_bucket := extensions.hmac(pg_catalog.convert_to(v_value, 'utf8'), v_pepper, 'sha256');
    v_ws := pg_catalog.to_timestamp(
              pg_catalog.floor(extract(epoch FROM v_now) / r.window_seconds) * r.window_seconds);

    INSERT INTO private.public_validation_rate_counters AS c
           (scope, bucket_hash, window_start, hits, first_seen, last_seen)
    VALUES (r.scope, v_bucket, v_ws, 1, v_now, v_now)
    ON CONFLICT (scope, bucket_hash, window_start)
    DO UPDATE SET hits = c.hits + 1, last_seen = v_now
    RETURNING c.hits INTO v_hits;

    IF v_hits > r.max_hits THEN
      v_allowed := false;
      UPDATE private.public_validation_rate_counters c
         SET blocked = c.blocked + 1
       WHERE c.scope = r.scope AND c.bucket_hash = v_bucket AND c.window_start = v_ws;
      v_retry_scope := greatest(1,
        pg_catalog.ceil(extract(epoch FROM
          (v_ws + pg_catalog.make_interval(secs => r.window_seconds) - v_now)))::integer);
      v_retry := greatest(v_retry, v_retry_scope);
    END IF;

    -- housekeeping barato: descarta janelas anteriores do mesmo bucket (limita linhas por bucket).
    DELETE FROM private.public_validation_rate_counters c
     WHERE c.scope = r.scope AND c.bucket_hash = v_bucket AND c.window_start < v_ws;
  END LOOP;

  allowed := v_allowed;
  retry_after_seconds := v_retry;
  RETURN NEXT;
END
$function$

CREATE OR REPLACE FUNCTION platform_private.c2p1_update_settings(p_partner_id uuid, p_expected jsonb, p_values jsonb)
 RETURNS partner_financial_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE oldrow public.partner_financial_settings; newrow public.partner_financial_settings; result public.partner_financial_settings; k text;
BEGIN
 IF NOT platform_private.c2p1_settings_allowed(p_partner_id,true) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Serialize absence and updates by canonical partner; lock actor/roles/organizations against revocation.
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id=public.h15_actor_organization() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id=p_partner_id FOR UPDATE;
 IF NOT platform_private.c2p1_settings_allowed(p_partner_id,true) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_values IS NULL OR jsonb_typeof(p_values)<>'object' THEN RAISE EXCEPTION 'C2P1_INVALID_PAYLOAD' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT jsonb_object_keys(p_values) LOOP
 IF k NOT IN ('billing_trigger','payment_terms_days','default_payment_method','credit_limit','block_if_overdue','auto_generate_receivable','active','credit_limit_action','overdue_tolerance_days','credit_alert_threshold_1','credit_alert_threshold_2')
 THEN RAISE EXCEPTION 'C2P1_INVALID_PAYLOAD' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM jsonb_object_keys(p_values))<>11 THEN RAISE EXCEPTION 'C2P1_INVALID_PAYLOAD' USING ERRCODE='22023'; END IF;
 SELECT * INTO oldrow FROM public.partner_financial_settings WHERE partner_id=p_partner_id FOR UPDATE;
 IF FOUND THEN
 IF p_expected IS NULL OR p_expected<>to_jsonb(oldrow) THEN RAISE EXCEPTION 'settings_conflict' USING ERRCODE='PT409'; END IF;
 ELSE
 IF p_expected IS NOT NULL THEN RAISE EXCEPTION 'settings_conflict' USING ERRCODE='PT409'; END IF;
 END IF;
 newrow=jsonb_populate_record(NULL::public.partner_financial_settings,p_values);
 -- Exact canonical name; method row lock prevents concurrent deactivation through commit.
 PERFORM 1 FROM public.payment_methods WHERE name=newrow.default_payment_method AND active IS TRUE FOR SHARE;
 IF (SELECT count(*) FROM public.payment_methods WHERE name=newrow.default_payment_method AND active IS TRUE)<>1
 THEN RAISE EXCEPTION 'C2P1_PAYMENT_METHOD_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM platform_private.issue_ticket('c2p1_settings_write',p_partner_id);
 IF oldrow.id IS NULL THEN
 INSERT INTO public.partner_financial_settings(partner_id,billing_trigger,payment_terms_days,default_payment_method,credit_limit,block_if_overdue,auto_generate_receivable,active,credit_limit_action,overdue_tolerance_days,credit_alert_threshold_1,credit_alert_threshold_2)
 VALUES(p_partner_id,newrow.billing_trigger,newrow.payment_terms_days,newrow.default_payment_method,newrow.credit_limit,newrow.block_if_overdue,newrow.auto_generate_receivable,newrow.active,newrow.credit_limit_action,newrow.overdue_tolerance_days,newrow.credit_alert_threshold_1,newrow.credit_alert_threshold_2) RETURNING * INTO result;
 ELSE
 UPDATE public.partner_financial_settings SET billing_trigger=newrow.billing_trigger,payment_terms_days=newrow.payment_terms_days,default_payment_method=newrow.default_payment_method,credit_limit=newrow.credit_limit,block_if_overdue=newrow.block_if_overdue,auto_generate_receivable=newrow.auto_generate_receivable,active=newrow.active,credit_limit_action=newrow.credit_limit_action,overdue_tolerance_days=newrow.overdue_tolerance_days,credit_alert_threshold_1=newrow.credit_alert_threshold_1,credit_alert_threshold_2=newrow.credit_alert_threshold_2 WHERE id=oldrow.id RETURNING * INTO result;
 END IF;
 DELETE FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='c2p1_settings_write' AND target=p_partner_id;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_financial_document_soft_delete(p_document_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_reason text; v_active boolean; v_rows integer; v_org uuid;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão não autenticada' USING ERRCODE='42501'; END IF;
 IF NOT public.is_financial_staff(v_uid) THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 IF p_document_id IS NULL THEN RAISE EXCEPTION 'Documento inválido' USING ERRCODE='22023'; END IF;
 v_reason:=btrim(coalesce(p_reason,''));
 IF length(v_reason)=0 THEN RAISE EXCEPTION 'Motivo da exclusão é obrigatório' USING ERRCODE='22023'; END IF;
 IF length(v_reason)>500 THEN RAISE EXCEPTION 'Motivo excede 500 caracteres' USING ERRCODE='22023'; END IF;
 SELECT (deleted_at IS NULL) INTO v_active FROM public.financial_documents WHERE id=p_document_id AND organization_id=v_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Documento não encontrado' USING ERRCODE='PT404'; END IF;
 IF public.h15_actor_organization() IS DISTINCT FROM v_org OR NOT public.is_financial_staff(v_uid) THEN
 RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 IF NOT v_active THEN RAISE EXCEPTION 'Documento já removido' USING ERRCODE='PT409'; END IF;
 UPDATE public.financial_documents SET deleted_at=now(),deleted_by=v_uid,delete_reason=v_reason WHERE id=p_document_id AND organization_id=v_org AND deleted_at IS NULL;
 GET DIAGNOSTICS v_rows=ROW_COUNT;
 IF v_rows<>1 THEN RAISE EXCEPTION 'Conflito concorrente ao remover documento' USING ERRCODE='PT409'; END IF;
 RETURN p_document_id;
END; $function$

CREATE OR REPLACE FUNCTION platform_private.notification_p1_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE org uuid; uid uuid; cid uuid; BEGIN
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'lido') IS DISTINCT FROM (to_jsonb(OLD)-'lido') THEN RAISE EXCEPTION 'NOTIF_CONTENT_IMMUTABLE' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 -- Unknown source is quarantined, not attributed from recipient or message/link. Preserve parent operations.
 IF NEW.source_type IS NULL OR NEW.source_id IS NULL THEN RETURN NULL; END IF;
 org:=platform_private.notification_source_org(NEW.source_type,NEW.source_id);
 IF TG_TABLE_NAME='notificacoes_operacionais' THEN uid:=NEW.usuario_id; ELSE uid:=NEW.recipient_user_id; cid:=NEW.cliente_id; END IF;
 IF NOT COALESCE(platform_private.notification_user_ok(uid,org),false) THEN RAISE EXCEPTION 'NOTIF_SOURCE_RECIPIENT_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF cid IS NOT NULL AND (platform_private.notification_source_client(NEW.source_type,NEW.source_id) IS DISTINCT FROM cid OR NOT public.has_role(uid,'cliente_produtor') OR NOT public._portal_cliente_user_has_link(uid,cid) OR NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=cid AND c.organization_id=org)) THEN RAISE EXCEPTION 'NOTIF_PORTAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.tipo::text='sistema' THEN RAISE EXCEPTION 'NOTIF_GLOBAL_PRODUCER_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN NEW; END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_company_rtc_save(payload jsonb, expected_revision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_org uuid; v_id uuid; v_stamp timestamptz; v_new text; v_count integer;
BEGIN
 PERFORM public.h15_require_staff();
 IF v_uid IS NULL THEN RAISE EXCEPTION 'FISCAL_UNAUTHENTICATED' USING ERRCODE='42501'; END IF;
 IF NOT public.has_role(v_uid,'administrador'::public.app_role) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 v_org:=public.h15_actor_organization();
 PERFORM public._fiscal_rtc_assert_payload(payload,'company');
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE' USING ERRCODE='55000'; END IF;
 PERFORM public.h15_require_staff();
 IF public.h15_actor_organization() IS DISTINCT FROM v_org OR NOT public.has_role(v_uid,'administrador'::public.app_role) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT count(*) INTO v_count FROM public.company_fiscal_settings WHERE organization_id=v_org;
 IF v_count=0 THEN RAISE EXCEPTION 'FISCAL_COMPANY_NOT_INITIALIZED' USING ERRCODE='PT404'; END IF;
 IF v_count<>1 THEN RAISE EXCEPTION 'FISCAL_COMPANY_AMBIGUOUS' USING ERRCODE='PT409'; END IF;
 SELECT id,updated_at INTO v_id,v_stamp FROM public.company_fiscal_settings WHERE organization_id=v_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_COMPANY_NOT_INITIALIZED' USING ERRCODE='PT404'; END IF;
 IF expected_revision IS NULL OR expected_revision IS DISTINCT FROM v_stamp::text THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 UPDATE public.company_fiscal_settings SET rtc_configuration=payload,updated_at=greatest(clock_timestamp(),v_stamp+interval '1 microsecond')
 WHERE id=v_id AND organization_id=v_org AND updated_at=v_stamp RETURNING updated_at::text INTO v_new;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 RETURN jsonb_build_object('configuration',payload,'revision',v_new);
END; $function$

CREATE OR REPLACE FUNCTION platform_private.notification_p1_visible(uid uuid, st text, sid uuid, cid uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE org uuid; BEGIN
 org:=platform_private.notification_source_org(st,sid);
 IF uid IS DISTINCT FROM auth.uid() OR NOT COALESCE(platform_private.notification_user_ok(uid,org),false) OR public.h15_actor_organization() IS DISTINCT FROM org THEN RETURN false; END IF;
 IF cid IS NOT NULL THEN
IF platform_private.notification_source_client(st,sid) IS DISTINCT FROM cid THEN RETURN false; END IF;
  RETURN public.has_role(uid,'cliente_produtor') AND EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=cid AND c.organization_id=org) AND public._portal_cliente_user_has_link(uid,cid);
 END IF;
 RETURN true; END $function$

CREATE OR REPLACE FUNCTION public._comunicacao_resolve_recipients_v2(_event_key text, _rule comunicacao_regras, _source_type text, _source_id uuid)
 RETURNS TABLE(recipient_user_id uuid, recipient_cliente_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_os_cliente uuid;
  v_sol RECORD;
BEGIN
  IF _event_key = 'administrative_important_update' THEN
    IF _rule.estrategia <> 'broadcast_role' OR _rule.perfil IS NULL THEN RETURN; END IF;
    RETURN QUERY
      SELECT DISTINCT pr.user_id, NULL::uuid
        FROM public.user_roles ur JOIN public.profiles pr ON pr.user_id = ur.user_id
       WHERE ur.role = _rule.perfil AND COALESCE(pr.ativo, true) = true;
    RETURN;
  END IF;

  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    IF _source_type NOT IN ('ordens_servico','ordens_servico_onfarm') THEN
      RAISE EXCEPTION 'source_type inválido: %', _source_type; END IF;
    CASE _source_type
      WHEN 'ordens_servico' THEN
        SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico o WHERE o.id = _source_id;
      WHEN 'ordens_servico_onfarm' THEN
        SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico_onfarm o WHERE o.id = _source_id;
    END CASE;
    IF v_os_cliente IS NULL THEN RETURN; END IF;
    IF _rule.estrategia = 'source_participants' THEN
      RETURN QUERY
        SELECT NULL::uuid, v_os_cliente
        UNION
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.profiles pr
         WHERE pr.cliente_id = v_os_cliente AND COALESCE(pr.ativo,true) = true;
      RETURN;
    ELSIF _rule.estrategia = 'by_role' THEN
      IF _rule.perfil IS NULL THEN RETURN; END IF;
      RETURN QUERY
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.user_roles ur JOIN public.profiles pr ON pr.user_id = ur.user_id
         WHERE ur.role = _rule.perfil AND pr.cliente_id = v_os_cliente
           AND COALESCE(pr.ativo,true) = true;
      RETURN;
    ELSE RETURN;
    END IF;
  END IF;

  IF _event_key IN (
    'solicitacao_criada','solicitacao_atribuida','solicitacao_checkin_realizado',
    'solicitacao_em_visita','solicitacao_aguardando_os','solicitacao_concluida',
    'solicitacao_cancelada','solicitacao_urgencia_critica'
  ) THEN
    IF _source_type <> 'portal_solicitacoes' THEN
      RAISE EXCEPTION 'source_type inválido: %', _source_type; END IF;
    SELECT s.cliente_id, s.consultor_atribuido INTO v_sol
      FROM public.portal_solicitacoes s WHERE s.id = _source_id;
    IF v_sol IS NULL THEN RETURN; END IF;

    IF _rule.estrategia = 'source_cliente' THEN
      IF v_sol.cliente_id IS NULL THEN RETURN; END IF;
      RETURN QUERY SELECT NULL::uuid, v_sol.cliente_id;
      RETURN;
    ELSIF _rule.estrategia = 'assigned_consultant' THEN
      IF v_sol.consultor_atribuido IS NULL THEN RETURN; END IF;
      RETURN QUERY
        SELECT pr.user_id, NULL::uuid
          FROM public.profiles pr
         WHERE pr.user_id = v_sol.consultor_atribuido
           AND COALESCE(pr.ativo, true) = true;
      RETURN;
    ELSIF _rule.estrategia = 'source_participants' THEN
      RETURN QUERY SELECT NULL::uuid, v_sol.cliente_id;
      IF v_sol.consultor_atribuido IS NOT NULL THEN
        RETURN QUERY SELECT v_sol.consultor_atribuido, NULL::uuid;
      END IF;
      RETURN;
    ELSIF _rule.estrategia = 'by_role' THEN
      IF _rule.perfil IS NULL THEN RETURN; END IF;
      IF _rule.perfil <> 'administrador'::public.app_role THEN RETURN; END IF;
      RETURN QUERY
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.user_roles ur
          JOIN public.profiles pr ON pr.user_id = ur.user_id
         WHERE ur.role = _rule.perfil
           AND COALESCE(pr.ativo,true) = true;
      RETURN;
    ELSE
      RETURN;
    END IF;
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public._cpp_validate_payload(p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_disc numeric; v_int numeric; v_inst integer; v_months numeric; v_days integer;
BEGIN
  IF coalesce(btrim(p->>'name'),'') = '' THEN RAISE EXCEPTION 'plan_name_required'; END IF;
  IF coalesce(btrim(p->>'code'),'') = '' THEN RAISE EXCEPTION 'plan_code_required'; END IF;
  IF coalesce(p->>'plan_type','') NOT IN ('cash','short_term','medium_term','extended_term','harvest','custom')
    THEN RAISE EXCEPTION 'plan_type_invalid'; END IF;
  IF coalesce(p->>'interest_type','') NOT IN ('none','simple','compound')
    THEN RAISE EXCEPTION 'interest_type_invalid'; END IF;
  IF coalesce(p->>'pricing_mode','discount_from_base') NOT IN ('discount_from_base','fixed_item_price','quote_only')
    THEN RAISE EXCEPTION 'pricing_mode_invalid'; END IF;

  v_disc := coalesce((p->>'discount_percent')::numeric, 0);
  v_int  := coalesce((p->>'monthly_interest_percent')::numeric, 0);
  v_inst := coalesce((p->>'installment_count')::integer, 1);
  v_months := coalesce((p->>'months_count')::numeric, 0);
  v_days := coalesce((p->>'max_days')::integer, 0);

  IF v_disc < 0 OR v_disc > 100 THEN RAISE EXCEPTION 'discount_out_of_range'; END IF;
  IF v_int < 0 OR v_int > 100 THEN RAISE EXCEPTION 'interest_out_of_range'; END IF;
  IF v_inst < 1 OR v_inst > 60 THEN RAISE EXCEPTION 'installment_out_of_range'; END IF;
  IF v_months < 0 OR v_months > 60 THEN RAISE EXCEPTION 'months_out_of_range'; END IF;
  IF v_days < 0 OR v_days > 1095 THEN RAISE EXCEPTION 'max_days_out_of_range'; END IF;
  IF (p ? 'minimum_order_amount') AND p->>'minimum_order_amount' IS NOT NULL
     AND (p->>'minimum_order_amount')::numeric < 0 THEN RAISE EXCEPTION 'minimum_order_amount_invalid'; END IF;
  IF (p ? 'valid_until') AND p->>'valid_until' IS NOT NULL
     AND (p->>'valid_until')::timestamptz <= coalesce((p->>'valid_from')::timestamptz, now())
     THEN RAISE EXCEPTION 'validity_window_invalid'; END IF;
END
$function$

CREATE OR REPLACE FUNCTION public._fiscal_rtc_assert_payload(payload jsonb, kind text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  k text; sz int;
  company_keys text[] := ARRAY['schema_version','source_document','source_version',
    'effective_from','last_reviewed_at','rtc_environment','transition_year',
    'accounting_review_notes','accounting_review_status','additional_fields'];
  item_keys text[] := ARRAY['schema_version','source_document','source_version',
    'effective_from','last_reviewed_at','cst_ibs_cbs','c_class_trib',
    'c_credito_presumido','c_ind_op','aliquota_cbs','aliquota_ibs_uf',
    'aliquota_ibs_municipio','aliquota_cbs_reference','aliquota_ibs_reference',
    'reducao','diferimento','monofasia','accounting_notes',
    'accounting_review_status','additional_fields'];
  allowed text[];
BEGIN
  IF payload IS NULL OR jsonb_typeof(payload) <> 'object' THEN
    RAISE EXCEPTION 'FISCAL_RTC_INVALID_PAYLOAD' USING ERRCODE='22023'; END IF;
  IF public.fiscal_rtc_has_sensitive_key(payload) THEN
    RAISE EXCEPTION 'FISCAL_RTC_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  sz := length(payload::text);
  IF sz > 65536 THEN
    RAISE EXCEPTION 'FISCAL_RTC_PAYLOAD_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF NOT (payload ? 'schema_version') OR (payload->>'schema_version') NOT IN ('1') THEN
    RAISE EXCEPTION 'FISCAL_RTC_SCHEMA_VERSION_UNSUPPORTED' USING ERRCODE='22023'; END IF;
  allowed := CASE WHEN kind='company' THEN company_keys ELSE item_keys END;
  FOR k IN SELECT jsonb_object_keys(payload) LOOP
    IF NOT (k = ANY(allowed)) THEN
      RAISE EXCEPTION 'FISCAL_RTC_UNKNOWN_FIELD' USING ERRCODE='22023'; END IF;
  END LOOP;
  IF payload ? 'additional_fields'
     AND jsonb_typeof(payload->'additional_fields') <> 'object' THEN
    RAISE EXCEPTION 'FISCAL_RTC_INVALID_ADDITIONAL_FIELDS' USING ERRCODE='22023'; END IF;
  IF kind='company' AND payload ? 'rtc_environment'
     AND (payload->>'rtc_environment') NOT IN ('NOT_CONFIGURED','HOMOLOGATION') THEN
    RAISE EXCEPTION 'FISCAL_RTC_INVALID_ENVIRONMENT' USING ERRCODE='22023'; END IF;
  IF payload ? 'accounting_review_status'
     AND (payload->>'accounting_review_status') NOT IN ('PENDING','REVIEWED') THEN
    RAISE EXCEPTION 'FISCAL_RTC_INVALID_REVIEW_STATUS' USING ERRCODE='22023'; END IF;
  FOR k IN SELECT unnest(ARRAY['aliquota_cbs','aliquota_ibs_uf',
    'aliquota_ibs_municipio','aliquota_cbs_reference','aliquota_ibs_reference']) LOOP
    IF payload ? k THEN
      IF jsonb_typeof(payload->k) <> 'number'
         OR (payload->>k)::numeric < 0 OR (payload->>k)::numeric > 100 THEN
        RAISE EXCEPTION 'FISCAL_RTC_INVALID_PERCENT' USING ERRCODE='22023'; END IF;
    END IF;
  END LOOP;
  FOR k IN SELECT unnest(ARRAY['cst_ibs_cbs','c_class_trib',
    'c_credito_presumido','c_ind_op']) LOOP
    IF payload ? k THEN
      IF jsonb_typeof(payload->k) <> 'string'
         OR length(payload->>k) < 1 OR length(payload->>k) > 12
         OR (payload->>k) !~ '^[A-Za-z0-9._-]+$' THEN
        RAISE EXCEPTION 'FISCAL_RTC_INVALID_CODE' USING ERRCODE='22023'; END IF;
    END IF;
  END LOOP;
  FOR k IN SELECT unnest(ARRAY['effective_from','last_reviewed_at']) LOOP
    IF payload ? k THEN
      IF jsonb_typeof(payload->k) <> 'string'
         OR (payload->>k) !~ '^\d{4}-\d{2}-\d{2}(T.*)?$' THEN
        RAISE EXCEPTION 'FISCAL_RTC_INVALID_DATE' USING ERRCODE='22023'; END IF;
    END IF;
  END LOOP;
  IF payload ? 'source_document' AND length(payload->>'source_document') > 120 THEN
    RAISE EXCEPTION 'FISCAL_RTC_STRING_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF payload ? 'source_version' AND length(payload->>'source_version') > 60 THEN
    RAISE EXCEPTION 'FISCAL_RTC_STRING_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF payload ? 'accounting_review_notes'
     AND length(payload->>'accounting_review_notes') > 4000 THEN
    RAISE EXCEPTION 'FISCAL_RTC_STRING_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF payload ? 'accounting_notes'
     AND length(payload->>'accounting_notes') > 2000 THEN
    RAISE EXCEPTION 'FISCAL_RTC_STRING_TOO_LONG' USING ERRCODE='22023'; END IF;
  -- ------------------------------------------------------------------
  -- Fase 3.19.5 - validacao NFS-e Nacional dentro de additional_fields.
  -- Codigos estaveis; fail-fast; sem catch silenciador.
  -- ------------------------------------------------------------------
  IF payload ? 'additional_fields' THEN
    DECLARE af jsonb := payload->'additional_fields';
    BEGIN
      IF af ? 'finNFSe' THEN
        IF jsonb_typeof(af->'finNFSe') <> 'string' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:finNFSe' USING ERRCODE='22023'; END IF;
        IF length(btrim(af->>'finNFSe')) < 1 OR length(btrim(af->>'finNFSe')) > 30 THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:finNFSe' USING ERRCODE='22023'; END IF;
      END IF;
      IF af ? 'tpNFSeDebito' THEN
        IF jsonb_typeof(af->'tpNFSeDebito') <> 'string' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:tpNFSeDebito' USING ERRCODE='22023'; END IF;
        IF length(btrim(af->>'tpNFSeDebito')) < 1 OR length(btrim(af->>'tpNFSeDebito')) > 30 THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:tpNFSeDebito' USING ERRCODE='22023'; END IF;
      END IF;
      IF af ? 'tpNFSeCredito' THEN
        IF jsonb_typeof(af->'tpNFSeCredito') <> 'string' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:tpNFSeCredito' USING ERRCODE='22023'; END IF;
        IF length(btrim(af->>'tpNFSeCredito')) < 1 OR length(btrim(af->>'tpNFSeCredito')) > 30 THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_CODE:tpNFSeCredito' USING ERRCODE='22023'; END IF;
      END IF;
      IF af ? 'gIBSCBSAjuste' THEN
        IF jsonb_typeof(af->'gIBSCBSAjuste') <> 'boolean' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_TOGGLE:gIBSCBSAjuste' USING ERRCODE='22023'; END IF;
      END IF;
      IF af ? 'vAjusteBC' THEN
        IF jsonb_typeof(af->'vAjusteBC') <> 'number' THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_VALUE:vAjusteBC' USING ERRCODE='22023'; END IF;
        IF (af->>'vAjusteBC')::numeric < 0 THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_INVALID_VALUE:vAjusteBC' USING ERRCODE='22023'; END IF;
        IF NOT (af ? 'gIBSCBSAjuste') THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_VALUE_WITHOUT_TOGGLE:vAjusteBC' USING ERRCODE='22023'; END IF;
        IF jsonb_typeof(af->'gIBSCBSAjuste') <> 'boolean'
           OR (af->>'gIBSCBSAjuste')::boolean IS DISTINCT FROM true THEN
          RAISE EXCEPTION 'FISCAL_RTC_NFSE_VALUE_WITHOUT_TOGGLE:vAjusteBC' USING ERRCODE='22023'; END IF;
      END IF;
    END;
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_check_monitoramento_and_notify(_registro_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  caller_uid uuid := auth.uid();
  v_consultor uuid; v_cliente uuid; v_data_prox date; v_talhao_id uuid;
  v_talhao_nome text; v_cliente_nome text; v_reserved_id uuid; v_notif_id uuid;
  v_hoje_br date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_idem text;
BEGIN
  IF caller_uid IS NOT NULL AND NOT has_role(caller_uid, 'administrador'::app_role) THEN
    RAISE EXCEPTION 'Sem autorização' USING ERRCODE='42501';
  END IF;
  IF _registro_id IS NULL THEN RAISE EXCEPTION 'registro_id obrigatório' USING ERRCODE='22023'; END IF;

  SELECT r.consultor_responsavel, r.cliente_id, r.data_proxima_visita, r.talhao_id, t.nome, c.nome
    INTO v_consultor, v_cliente, v_data_prox, v_talhao_id, v_talhao_nome, v_cliente_nome
    FROM public.registros_consultor r
    LEFT JOIN public.talhoes t ON t.id = r.talhao_id
    LEFT JOIN public.clientes c ON c.id = r.cliente_id
   WHERE r.id = _registro_id
     AND r.necessidade_intervencao = 'monitorar'
     AND r.status = 'finalizado'
     AND r.data_proxima_visita IS NOT NULL
     AND r.data_proxima_visita <= v_hoje_br
   FOR UPDATE;

  IF v_consultor IS NULL THEN
    RETURN jsonb_build_object('created', false, 'reason', 'not_eligible');
  END IF;

  INSERT INTO public.monitoramento_avisos (registro_consultor_id, tipo, data_referencia)
  VALUES (_registro_id, 'vencido', v_hoje_br)
  ON CONFLICT (registro_consultor_id, tipo, data_referencia) DO NOTHING
  RETURNING id INTO v_reserved_id;

  IF v_reserved_id IS NULL THEN
    RETURN jsonb_build_object('created', false, 'reason', 'duplicate');
  END IF;

  v_idem := format('monit-venc-%s-%s', _registro_id, v_hoje_br);
  INSERT INTO public.notificacoes_operacionais
    (usuario_id, tipo, titulo, mensagem, link, source_type, source_id, idempotency_key)
  VALUES (
    v_consultor, 'alerta', 'Monitoramento Vencido',
    format('A reavaliação do talhão %s (%s) venceu em %s.',
           coalesce(v_talhao_nome,'—'), coalesce(v_cliente_nome,'—'), v_data_prox),
    format('/visita-tecnica/%s', _registro_id),
    'monitoramento_vencido', _registro_id, v_idem
  ) ON CONFLICT DO NOTHING RETURNING id INTO v_notif_id;

  IF v_notif_id IS NULL THEN
    SELECT id INTO v_notif_id FROM public.notificacoes_operacionais
     WHERE idempotency_key = v_idem LIMIT 1;
  END IF;
  IF v_notif_id IS NULL THEN
    RAISE EXCEPTION 'Reserva sem notificação; revertendo' USING ERRCODE='23514';
  END IF;

  RETURN jsonb_build_object('created', true, 'aviso_id', v_reserved_id, 'notification_id', v_notif_id,
    'consultor_id', v_consultor, 'talhao_id', v_talhao_id,
    'talhao_nome', v_talhao_nome, 'cliente_nome', v_cliente_nome);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_reprogramar_monitoramento_v1(p_alerta_id uuid, p_nova_data date, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_alerta public.alertas_agronomicos%ROWTYPE;
  v_hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  IF v_uid IS NULL OR NOT public.technical_actor_ready(v_uid) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  IF NOT (
    public.has_role(v_uid, 'administrador'::public.app_role)
    OR public.has_role(v_uid, 'gestor'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  IF p_alerta_id IS NULL OR p_nova_data IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_nova_data < v_hoje THEN
    RAISE EXCEPTION 'past_date_not_allowed' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_gate_unavailable' USING ERRCODE='55000'; END IF;
  IF NOT public.technical_actor_ready(v_uid) OR NOT (public.has_role(v_uid,'administrador'::public.app_role) OR public.has_role(v_uid,'gestor'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_alerta
    FROM public.alertas_agronomicos
   WHERE id = p_alerta_id AND platform_private.monitoring_refs_in_actor_tenant(fazenda_id,talhao_id,registro_origem_id)
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE = 'PT404';
  END IF;
  IF NOT public.technical_actor_ready(v_uid) OR NOT platform_private.monitoring_refs_in_actor_tenant(v_alerta.fazenda_id,v_alerta.talhao_id,v_alerta.registro_origem_id) THEN
    RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE='PT404';
  END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    PERFORM 1 FROM public.registros_consultor WHERE id=v_alerta.registro_origem_id
      AND public.can_manage_technical_visit(v_uid,id) FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE='PT404'; END IF;
  END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    RAISE EXCEPTION 'monitoring_reschedule_requires_current_client' USING ERRCODE='PT428';
  END IF;
  IF v_alerta.status IS DISTINCT FROM 'monitoramento'::public.status_alerta THEN
    RAISE EXCEPTION 'monitoring_alert_not_active' USING ERRCODE = 'P0001';
  END IF;
  IF p_expected_updated_at IS NULL OR v_alerta.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE = 'PT409';
  END IF;
  UPDATE public.alertas_agronomicos
     SET data_vencimento = p_nova_data,
         nivel_risco = 'medio'::public.nivel_risco,
         updated_at = greatest(clock_timestamp(),v_alerta.updated_at+interval '1 microsecond')
   WHERE id = p_alerta_id AND updated_at=p_expected_updated_at
     AND platform_private.monitoring_refs_in_actor_tenant(fazenda_id,talhao_id,registro_origem_id);
  IF NOT FOUND THEN RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409'; END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    UPDATE public.registros_consultor
       SET data_proxima_visita = p_nova_data,
           version = version + 1,
           updated_at = now()
     WHERE id = v_alerta.registro_origem_id AND public.can_manage_technical_visit(v_uid,id);
    IF NOT FOUND THEN
      RAISE EXCEPTION 'source_record_not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;
  RETURN jsonb_build_object(
    'success', true,
    'alerta_id', p_alerta_id,
    'data_anterior', v_alerta.data_vencimento,
    'nova_data', p_nova_data,
    'registro_origem_id', v_alerta.registro_origem_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.ofo_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'override_imutavel: exceções não podem ser apagadas';
  end if;
  if old.ended_at is not null then
    raise exception 'override_imutavel: exceção já encerrada';
  end if;
  if new.organization_id <> old.organization_id or new.feature_id <> old.feature_id
     or new.mode <> old.mode or new.limit_value is distinct from old.limit_value
     or new.starts_at <> old.starts_at or new.ends_at is distinct from old.ends_at
     or new.reason <> old.reason or new.created_by is distinct from old.created_by
     or new.created_at <> old.created_at or new.ended_at is null then
    raise exception 'override_imutavel: somente encerramento é permitido';
  end if;
  new.updated_at := now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.ofo_stamp_author()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.created_by := auth.uid();
  new.ended_at := null; new.ended_by := null; new.end_reason := null;
  new.created_at := now(); new.updated_at := now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.rpc_criar_alerta_climatico_v1(p_fazenda_id uuid, p_talhao_id uuid, p_tipo_alerta tipo_alerta, p_nivel_risco nivel_risco, p_descricao text)
 RETURNS TABLE(id uuid, criado boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
declare
  v_id uuid;
begin
  if not public.technical_actor_ready(auth.uid()) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if p_tipo_alerta is null or p_nivel_risco is null or p_fazenda_id is null or p_talhao_id is null or nullif(btrim(p_descricao), '') is null then
    raise exception 'INVALID_INPUT';
  end if;
  if length(p_descricao) > 2000 then raise exception 'DESCRIPTION_TOO_LONG'; end if;
  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not platform_private.monitoring_refs_in_actor_tenant(p_fazenda_id,p_talhao_id,null) then
    raise exception 'monitoring_reference_not_found' using errcode='PT404';
  end if;
  perform 1 from cf_user_guards_v1.state where singleton for update;
  if not found then raise exception 'monitoring_gate_unavailable' using errcode='55000'; end if;
  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not platform_private.monitoring_refs_in_actor_tenant(p_fazenda_id,p_talhao_id,null) then
    raise exception 'monitoring_reference_not_found' using errcode='PT404';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_fazenda_id::text || ':' || p_talhao_id::text || ':' || p_tipo_alerta::text, 0
  ));

  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not platform_private.monitoring_refs_in_actor_tenant(p_fazenda_id,p_talhao_id,null) then
    raise exception 'monitoring_reference_not_found' using errcode='PT404';
  end if;

  select a.id into v_id
  from public.alertas_agronomicos a
  where a.fazenda_id = p_fazenda_id
    and a.talhao_id = p_talhao_id
    and a.tipo_alerta = p_tipo_alerta
    and platform_private.monitoring_refs_in_actor_tenant(a.fazenda_id,a.talhao_id,a.registro_origem_id)
    and a.status <> 'encerrado'::public.status_alerta
  order by a.created_at desc
  limit 1;

  if v_id is not null then
    return query select v_id, false;
    return;
  end if;

  insert into public.alertas_agronomicos (
    fazenda_id, talhao_id, tipo_alerta, nivel_risco, descricao
  ) values (
    p_fazenda_id, p_talhao_id, p_tipo_alerta, p_nivel_risco, btrim(p_descricao)
  ) returning alertas_agronomicos.id into v_id;

  return query select v_id, true;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_activate_communication_template(p_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_templates%rowtype; prev public.comunicacao_templates%rowtype;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO r FROM public.comunicacao_templates WHERE id = p_template_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'template não encontrado'; END IF;
  IF r.status = 'archived' THEN RAISE EXCEPTION 'template arquivado'; END IF;
  SELECT * INTO prev FROM public.comunicacao_templates
    WHERE chave = r.chave AND canal = r.canal AND status = 'active' AND id <> r.id FOR UPDATE;
  IF FOUND THEN
    UPDATE public.comunicacao_templates
       SET status = 'archived', archived_at = now(), updated_by = auth.uid()
     WHERE id = prev.id;
    PERFORM public._comunicacao_write_audit('template.archive_prev_on_activate','comunicacao_templates',prev.id,
      to_jsonb(prev), jsonb_build_object('archived_by_activation_of', p_template_id));
  END IF;
  UPDATE public.comunicacao_templates
     SET status = 'active', updated_by = auth.uid() WHERE id = p_template_id;
  PERFORM public._comunicacao_write_audit('template.activate','comunicacao_templates',p_template_id,
    to_jsonb(r), (SELECT to_jsonb(t) FROM public.comunicacao_templates t WHERE t.id = p_template_id));
  RETURN jsonb_build_object('ok',true);
END$function$

CREATE OR REPLACE FUNCTION public.rpc_admin_replay_communication_dead_letter(p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_outbox%rowtype; v_before jsonb; v_after jsonb;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();
  PERFORM public._comunicacao_dlq_replay_rate_check('unit', 30);

  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'dead_letter' THEN
    RAISE EXCEPTION 'item não está em dead_letter (status=%)', r.status
      USING ERRCODE='invalid_parameter_value';
  END IF;

  v_before := jsonb_build_object(
    'status', r.status::text, 'attempts', r.attempts,
    'error_code', r.error_code, 'error_message', left(COALESCE(r.error_message,''),200)
  );
  UPDATE public.comunicacao_outbox
     SET status='pending', attempts=0, next_attempt_at=now(),
         error_code=NULL, error_message=NULL,
         locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
   WHERE id = p_outbox_id;
  v_after := jsonb_build_object('status','pending','attempts',0);

  INSERT INTO public.comunicacao_dlq_replay_audit(actor_id, scope, target_id)
    VALUES (auth.uid(), 'unit', p_outbox_id);

  PERFORM public._comunicacao_write_audit(
    'outbox.dlq_replay', 'comunicacao_outbox', p_outbox_id, v_before, v_after
  );
  RETURN jsonb_build_object('ok',true,'id',p_outbox_id,'status','pending');
END;$function$

CREATE OR REPLACE FUNCTION public.saas_subscription_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_old jsonb;
  v_new jsonb;
  v_reason text;
  v_action text;
  v_correlation uuid;
BEGIN
  v_new := to_jsonb(NEW);
  IF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    IF v_old = v_new THEN RETURN NEW; END IF;
  END IF;
  v_reason := nullif(current_setting('app.saas_change_reason', true), '');
  v_action := nullif(current_setting('app.saas_change_action', true), '');
  BEGIN
    v_correlation := nullif(current_setting('app.saas_correlation_id', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_correlation := NULL;
  END;
  INSERT INTO public.organization_subscription_history(
    subscription_id, organization_id, actor_user_id, source, reason,
    old_values, new_values, action, correlation_id,
    previous_status, new_status, previous_plan_id, new_plan_id,
    previous_plan_version_id, new_plan_version_id,
    price_snapshot, currency_snapshot, billing_cycle_snapshot, limits_snapshot
  ) VALUES (
    NEW.id, NEW.organization_id, auth.uid(),
    CASE WHEN v_action = 'expire_trial' THEN 'system' ELSE 'rpc' END,
    COALESCE(v_reason, CASE WHEN TG_OP = 'INSERT' THEN 'subscription_created' ELSE 'subscription_updated' END),
    v_old, v_new, COALESCE(v_action, lower(TG_OP)), v_correlation,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NULL END,
    NEW.status,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.plan_id ELSE NULL END,
    NEW.plan_id,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.plan_version_id ELSE NULL END,
    NEW.plan_version_id,
    NEW.price_snapshot, NEW.currency_snapshot, NEW.billing_cycle_snapshot, NEW.limits_snapshot
  );
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_atualizar_status_alerta_agronomico_v1(p_alerta_id uuid, p_novo_status status_alerta, p_updated_at_esperado timestamp with time zone)
 RETURNS alertas_agronomicos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
declare
  v_alerta public.alertas_agronomicos;
begin
  if not public.technical_actor_ready(auth.uid()) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if p_alerta_id is null or p_novo_status is null or p_updated_at_esperado is null then
    raise exception 'INVALID_INPUT';
  end if;

  perform 1 from cf_user_guards_v1.state where singleton for update;
  if not found then raise exception 'monitoring_gate_unavailable' using errcode='55000'; end if;
  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(),'administrador'::public.app_role)
    or public.has_role(auth.uid(),'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  select * into v_alerta
  from public.alertas_agronomicos a
  where a.id = p_alerta_id and platform_private.monitoring_refs_in_actor_tenant(a.fazenda_id,a.talhao_id,a.registro_origem_id)
  for update;
  if not found then raise exception 'monitoring_alert_not_found' using errcode='PT404'; end if;
  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(),'administrador'::public.app_role)
    or public.has_role(auth.uid(),'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if v_alerta.updated_at IS DISTINCT FROM p_updated_at_esperado then raise exception 'CONCURRENT_UPDATE' using errcode='PT409'; end if;
  if v_alerta.status = 'encerrado'::public.status_alerta and p_novo_status <> v_alerta.status then
    raise exception 'CLOSED_ALERT';
  end if;

  update public.alertas_agronomicos a
  set status = p_novo_status, updated_at = greatest(clock_timestamp(),v_alerta.updated_at+interval '1 microsecond')
  where a.id = p_alerta_id and a.updated_at=p_updated_at_esperado and platform_private.monitoring_refs_in_actor_tenant(a.fazenda_id,a.talhao_id,a.registro_origem_id)
  returning * into v_alerta;
  if not found then raise exception 'CONCURRENT_UPDATE' using errcode='PT409'; end if;
  return v_alerta;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_admin_replay_communication_dead_letter_batch(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_limit int; v_ids uuid[]; v_id uuid; v_before jsonb; v_count int := 0;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();
  PERFORM public._comunicacao_dlq_replay_rate_check('batch', 6);

  v_limit := GREATEST(1, LEAST(20, COALESCE(p_limit, 10)));
  SELECT array_agg(id) INTO v_ids FROM (
    SELECT id FROM public.comunicacao_outbox
     WHERE status='dead_letter'
     ORDER BY updated_at ASC NULLS FIRST, created_at ASC
     LIMIT v_limit FOR UPDATE SKIP LOCKED
  ) s;
  IF v_ids IS NULL THEN
    INSERT INTO public.comunicacao_dlq_replay_audit(actor_id, scope, batch_size)
      VALUES (auth.uid(), 'batch', 0);
    RETURN jsonb_build_object('ok',true,'replayed',0,'ids','[]'::jsonb);
  END IF;

  FOREACH v_id IN ARRAY v_ids LOOP
    SELECT jsonb_build_object(
      'status', o.status::text, 'attempts', o.attempts,
      'error_code', o.error_code, 'error_message', left(COALESCE(o.error_message,''),200)
    ) INTO v_before FROM public.comunicacao_outbox o WHERE o.id = v_id;
    UPDATE public.comunicacao_outbox
       SET status='pending', attempts=0, next_attempt_at=now(),
           error_code=NULL, error_message=NULL,
           locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
     WHERE id = v_id;
    PERFORM public._comunicacao_write_audit(
      'outbox.dlq_replay_batch', 'comunicacao_outbox', v_id, v_before,
      jsonb_build_object('status','pending','attempts',0)
    );
    v_count := v_count + 1;
  END LOOP;

  INSERT INTO public.comunicacao_dlq_replay_audit(actor_id, scope, batch_size)
    VALUES (auth.uid(), 'batch', v_count);

  RETURN jsonb_build_object('ok',true,'replayed',v_count,'ids',to_jsonb(v_ids));
END;$function$

CREATE OR REPLACE FUNCTION public.rpc_create_communication_template(p_chave text, p_nome text, p_canal comunicacao_canal, p_assunto text, p_corpo text, p_variaveis jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_versao integer;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF jsonb_typeof(p_variaveis) <> 'array' THEN
    RAISE EXCEPTION 'variaveis deve ser array JSON';
  END IF;
  SELECT COALESCE(MAX(versao),0) + 1 INTO v_versao
    FROM public.comunicacao_templates WHERE chave = p_chave AND canal = p_canal;
  INSERT INTO public.comunicacao_templates(chave,nome,canal,versao,status,assunto,corpo,variaveis,created_by,updated_by)
  VALUES (p_chave,p_nome,p_canal,v_versao,'draft',p_assunto,p_corpo,p_variaveis,auth.uid(),auth.uid())
  RETURNING id INTO v_id;
  PERFORM public._comunicacao_write_audit('template.create','comunicacao_templates',v_id, NULL,
    jsonb_build_object('chave',p_chave,'canal',p_canal,'versao',v_versao,'nome',p_nome));
  RETURN jsonb_build_object('ok',true,'template_id',v_id,'versao',v_versao);
END$function$

CREATE OR REPLACE FUNCTION platform_private.save_visit_monitoring_plan_core(p_registro_id uuid, p_expected_version integer, p_plano jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_id uuid;
  v_version integer;
  v_date date;
  v_obs text;
  v_block text;
  v_receipt jsonb;
  v_fingerprint text := md5(jsonb_build_object('visit',p_registro_id,'version',p_expected_version,'plan',p_plano)::text);
BEGIN
  IF NOT coalesce(public.technical_actor_ready(v_uid),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='42501';
  END IF;
  IF NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  IF p_expected_version IS NULL OR p_expected_version<=0 THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE='PT409';
  END IF;
  IF p_request_id IS NULL OR jsonb_typeof(p_plano) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid_plan' USING ERRCODE='22023';
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_plano))<>4
    OR NOT p_plano ?& ARRAY['items','frequency','triggers','next_date']
    OR jsonb_typeof(p_plano->'items') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_plano->'triggers') IS DISTINCT FROM 'string'
    OR jsonb_typeof(p_plano->'frequency') IS DISTINCT FROM 'string'
    OR jsonb_typeof(p_plano->'next_date') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid_plan' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(p_plano->'items') NOT BETWEEN 1 AND 6
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_plano->'items') x
      WHERE jsonb_typeof(x)<>'string' OR x#>>'{}' NOT IN ('Pragas','Doenças','Plantas Daninhas','Nutrição','Clima','Estande'))
    OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(p_plano->'items') x)<>jsonb_array_length(p_plano->'items')
    OR p_plano->>'frequency' NOT IN ('7','14','30')
    OR length(p_plano->>'triggers')>2000
    OR p_plano->>'triggers' ~ '[\r\n]'
    OR position('[PLANO DE MONITORAMENTO]' in p_plano->>'triggers')>0
    OR position('[FIM DO PLANO]' in p_plano->>'triggers')>0
    OR p_plano->>'next_date' !~ '^\d{4}-\d{2}-\d{2}$' THEN
    RAISE EXCEPTION 'invalid_plan' USING ERRCODE='22023';
  END IF;
  v_date := (p_plano->>'next_date')::date;
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_gate_unavailable' USING ERRCODE='55000'; END IF;
  IF NOT coalesce(public.technical_actor_ready(v_uid),false) OR
    NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  -- NULL here does not authorize CAS: replay is checked first, explicit mandatory CAS below.
  v_reg := public._visita_lock_and_check(p_registro_id,NULL,false);
  IF NOT coalesce(public.technical_actor_ready(v_uid),false) OR
    NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) OR
    NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_reg.fazenda_id,v_reg.talhao_id,v_reg.id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  -- visitas_logs accepts authenticated INSERT: never trust it as a receipt authority.
  SELECT jsonb_build_object('fingerprint',fingerprint,'result',result) INTO v_receipt
    FROM platform_private.visit_monitoring_plan_receipts
    WHERE registro_id=p_registro_id AND actor_id=v_uid AND request_id=p_request_id;
  IF FOUND THEN
    IF v_receipt->>'fingerprint' IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION 'request_conflict' USING ERRCODE='PT409';
    END IF;
    RETURN v_receipt->'result';
  END IF;
  -- Time-dependent rule AFTER authorized replay; a confirmed receipt never expires.
  IF v_date < (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date THEN
    RAISE EXCEPTION 'past_date_not_allowed' USING ERRCODE='22023';
  END IF;
  IF v_reg.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE='PT409';
  END IF;
  IF v_reg.status::text NOT IN ('rascunho','em_andamento') THEN
    RAISE EXCEPTION 'technical_record_content_locked' USING ERRCODE='42501';
  END IF;
  IF EXISTS(SELECT 1 FROM public.alertas_agronomicos o WHERE o.registro_origem_id=p_registro_id AND o.status::text<>'encerrado')
    AND v_date IS DISTINCT FROM v_reg.data_proxima_visita THEN
    RAISE EXCEPTION 'linked_alert_date_requires_reschedule' USING ERRCODE='PT409';
  END IF;
  IF (SELECT count(*) FROM public.monitoramento_avisos WHERE registro_consultor_id=p_registro_id AND tipo='plano_monitoramento')>1 THEN
    RAISE EXCEPTION 'ambiguous_plan_notice' USING ERRCODE='PT409';
  END IF;
  SELECT id INTO v_id FROM public.monitoramento_avisos
    WHERE registro_consultor_id=p_registro_id AND tipo='plano_monitoramento' FOR UPDATE;
  IF NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) OR
    NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_reg.fazenda_id,v_reg.talhao_id,v_reg.id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  -- Replace only a complete single legacy block; malformed/ambiguous text needs human review.
  v_obs := coalesce(v_reg.observacoes_tecnicas,'');
  IF (length(v_obs)-length(replace(v_obs,'[PLANO DE MONITORAMENTO]','')))/length('[PLANO DE MONITORAMENTO]') > 1
    OR (length(v_obs)-length(replace(v_obs,'[FIM DO PLANO]','')))/length('[FIM DO PLANO]') > 1
    OR (position('[PLANO DE MONITORAMENTO]' in v_obs)>0)<>(position('[FIM DO PLANO]' in v_obs)>0)
    OR (position('[FIM DO PLANO]' in v_obs)>0 AND position('[FIM DO PLANO]' in v_obs)<position('[PLANO DE MONITORAMENTO]' in v_obs)) THEN
    RAISE EXCEPTION 'ambiguous_plan_text' USING ERRCODE='PT409';
  END IF;
  v_obs := regexp_replace(v_obs,'\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]','','ns');
  v_block := '[PLANO DE MONITORAMENTO]'||chr(10)||'Itens: '||
    (SELECT string_agg(x,', ' ORDER BY ord) FROM jsonb_array_elements_text(p_plano->'items') WITH ORDINALITY a(x,ord))||chr(10)||
    'Frequência: '||(p_plano->>'frequency')||' dias'||chr(10)||'Gatilhos: '||(p_plano->>'triggers')||chr(10)||
    'Próxima Avaliação: '||v_date::text||chr(10)||'[FIM DO PLANO]';
  INSERT INTO platform_private.visit_plan_write_tickets(transaction_id,registro_id,block,next_date)
    VALUES(txid_current(),p_registro_id,v_block,v_date);
  UPDATE public.registros_consultor SET observacoes_tecnicas=btrim(v_obs||chr(10)||chr(10)||v_block),
    data_proxima_visita=v_date, version=p_expected_version+1, updated_at=clock_timestamp()
    WHERE id=p_registro_id AND version=p_expected_version
      AND public.can_manage_technical_visit(v_uid,id) RETURNING version INTO v_version;
  IF NOT FOUND OR v_version<>p_expected_version+1 THEN RAISE EXCEPTION 'version_conflict' USING ERRCODE='PT409'; END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.monitoramento_avisos(registro_consultor_id,tipo,data_referencia)
      VALUES(p_registro_id,'plano_monitoramento',v_date) RETURNING id INTO v_id;
  ELSE
    UPDATE public.monitoramento_avisos SET data_referencia=v_date WHERE id=v_id AND registro_consultor_id=p_registro_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'notice_conflict' USING ERRCODE='PT409'; END IF;
  END IF;
  v_receipt := jsonb_build_object('ok',true,'registro_id',p_registro_id,'version',v_version,
    'aviso_id',v_id,'data_referencia',v_date,'plano',p_plano,'request_id',p_request_id);
  INSERT INTO public.visitas_logs(registro_consultor_id,usuario_id,acao,descricao,metadata)
    VALUES(p_registro_id,v_uid,'plano_monitoramento_salvo','Plano de monitoramento atualizado',
      jsonb_build_object('request_id',p_request_id,'fingerprint',v_fingerprint,'version',v_version,'result',v_receipt));
  INSERT INTO platform_private.visit_monitoring_plan_receipts(actor_id,registro_id,request_id,fingerprint,result)
    VALUES(v_uid,p_registro_id,p_request_id,v_fingerprint,v_receipt);
  DELETE FROM platform_private.visit_plan_write_tickets WHERE transaction_id=txid_current() AND registro_id=p_registro_id;
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.guard_visit_plan_preservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  old_block text;
  new_block text;
  authorized boolean;
BEGIN
  old_block := substring(coalesce(OLD.observacoes_tecnicas,'') from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]');
  new_block := substring(coalesce(NEW.observacoes_tecnicas,'') from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]');
  IF (coalesce(NEW.observacoes_tecnicas,'') LIKE '%[PLANO DE MONITORAMENTO]%' OR coalesce(NEW.observacoes_tecnicas,'') LIKE '%[FIM DO PLANO]%') AND
    (new_block IS NULL OR length(coalesce(NEW.observacoes_tecnicas,''))-length(replace(coalesce(NEW.observacoes_tecnicas,''),'[PLANO DE MONITORAMENTO]',''))<>length('[PLANO DE MONITORAMENTO]') OR
      length(coalesce(NEW.observacoes_tecnicas,''))-length(replace(coalesce(NEW.observacoes_tecnicas,''),'[FIM DO PLANO]',''))<>length('[FIM DO PLANO]')) THEN
    RAISE EXCEPTION 'ambiguous_plan_text' USING ERRCODE='PT409';
  END IF;
  IF old_block IS NOT DISTINCT FROM new_block AND (old_block IS NULL OR OLD.data_proxima_visita IS NOT DISTINCT FROM NEW.data_proxima_visita) THEN
    RETURN NEW;
  END IF;
  SELECT EXISTS(SELECT 1 FROM platform_private.visit_plan_write_tickets t
    WHERE t.transaction_id=txid_current() AND t.registro_id=OLD.id
      AND t.block IS NOT DISTINCT FROM new_block AND t.next_date IS NOT DISTINCT FROM NEW.data_proxima_visita)
    INTO authorized;
  IF NOT authorized THEN
    RAISE EXCEPTION 'monitoring_plan_requires_canonical_save' USING ERRCODE='PT409';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.catalog_sources_set_source_key()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ref text;
BEGIN
  v_ref := coalesce(NEW.fonte_url, NEW.fonte_titulo, '');
  v_ref := regexp_replace(trim(lower(v_ref)), '\s+', ' ', 'g');
  NEW.source_key := lower(md5(
    trim(lower(coalesce(NEW.entidade_tipo, ''))) || ':' ||
    trim(lower(coalesce(NEW.entidade_id::text, ''))) || ':' ||
    v_ref
  ));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public._saas_trg_require_feature()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_key text := TG_ARGV[0];
BEGIN
  IF v_uid IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    JOIN public.organizations o ON o.id = p.organization_id AND o.ativo IS TRUE
    WHERE p.user_id = v_uid AND p.ativo IS TRUE AND p.organization_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'saas_context_unavailable: usuário ativo e empresa são obrigatórios'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public._saas_user_has_feature(v_uid, v_key) THEN
    RAISE EXCEPTION 'saas_feature_not_entitled: funcionalidade não contratada ou assinatura indisponível'
      USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.guard_alert_origin_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'platform_private'
AS $function$
DECLARE v_ticket boolean;
BEGIN
  v_ticket := EXISTS(SELECT 1 FROM platform_private.alert_origin_write_tickets
                      WHERE transaction_id=txid_current() AND alerta_id=NEW.id);
  IF TG_OP='INSERT' THEN
    IF NEW.registro_origem_id IS NOT NULL AND NOT v_ticket THEN
      RAISE EXCEPTION 'alert_origin_requires_canonical_link' USING ERRCODE='PT409';
    END IF;
    RETURN NEW;
  END IF;
  IF v_ticket THEN RETURN NEW; END IF;
  -- Link/unlink/relink (including unlink-then-change-date) only via the link core.
  IF NEW.registro_origem_id IS DISTINCT FROM OLD.registro_origem_id OR NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'alert_origin_requires_canonical_link' USING ERRCODE='PT409';
  END IF;
  IF OLD.registro_origem_id IS NOT NULL AND (
       NEW.data_vencimento IS DISTINCT FROM OLD.data_vencimento
    OR NEW.fazenda_id IS DISTINCT FROM OLD.fazenda_id
    OR NEW.talhao_id IS DISTINCT FROM OLD.talhao_id
    OR (OLD.status='encerrado' AND NEW.status IS DISTINCT FROM 'encerrado')) THEN
    RAISE EXCEPTION 'linked_alert_requires_canonical_reschedule' USING ERRCODE='PT409';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.comunicacao_templates_guard_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status = 'active' THEN
    IF (NEW.corpo, NEW.assunto, NEW.variaveis, NEW.canal, NEW.chave, NEW.versao, NEW.locale)
       IS DISTINCT FROM
       (OLD.corpo, OLD.assunto, OLD.variaveis, OLD.canal, OLD.chave, OLD.versao, OLD.locale) THEN
      RAISE EXCEPTION 'template ativo imutável (chave=% canal=% versao=%)',
        OLD.chave, OLD.canal, OLD.versao USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status NOT IN ('active','archived') THEN
      RAISE EXCEPTION 'template ativo só transita para archived' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public.rpc_publish_communication_event_v2(p_event_key text, p_source_type text, p_source_id uuid, p_payload jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_event_id uuid; v_expand jsonb; v_target_role public.app_role;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth requerida' USING ERRCODE='insufficient_privilege'; END IF;
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE='insufficient_privilege'; END IF;
  IF p_event_key NOT IN ('produto_pronto_retirada','produto_pronto_aplicacao','administrative_important_update') THEN
    RAISE EXCEPTION 'event_key inválido: %', p_event_key; END IF;
  IF jsonb_typeof(COALESCE(p_payload,'{}'::jsonb)) <> 'object' THEN RAISE EXCEPTION 'payload objeto'; END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) < 8 OR length(p_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'idempotency_key inválido'; END IF;
  IF p_event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    IF (SELECT count(*) FROM jsonb_object_keys(COALESCE(p_payload,'{}'::jsonb))) > 0 THEN
      RAISE EXCEPTION 'payload não aceita chaves'; END IF;
    IF p_source_type NOT IN ('ordens_servico','ordens_servico_onfarm') THEN
      RAISE EXCEPTION 'source_type inválido: %', p_source_type; END IF;
    IF p_source_id IS NULL THEN RAISE EXCEPTION 'source_id obrigatório'; END IF;
    IF p_event_key = 'produto_pronto_retirada' THEN
      IF p_source_type = 'ordens_servico' THEN
        IF NOT EXISTS (SELECT 1 FROM public.ordens_servico o
          WHERE o.id = p_source_id AND o.status = 'pronto_entrega'::public.status_os) THEN
          RAISE EXCEPTION 'ordens_servico não pronto_entrega'; END IF;
      ELSE
        IF NOT EXISTS (SELECT 1 FROM public.ordens_servico_onfarm o
          WHERE o.id = p_source_id AND o.status = 'pronto_entrega'::public.status_os_onfarm) THEN
          RAISE EXCEPTION 'ordens_servico_onfarm não pronto_entrega'; END IF;
      END IF;
    ELSE
      IF p_source_type <> 'ordens_servico' THEN RAISE EXCEPTION 'produto_pronto_aplicacao só regular'; END IF;
      IF NOT EXISTS (SELECT 1 FROM public.ordens_servico o WHERE o.id = p_source_id) THEN
        RAISE EXCEPTION 'ordem inexistente'; END IF;
    END IF;
  ELSE
    IF p_source_type IS NOT NULL THEN RAISE EXCEPTION 'source_type deve ser NULL'; END IF;
    IF p_source_id IS NOT NULL THEN RAISE EXCEPTION 'source_id deve ser NULL'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(COALESCE(p_payload,'{}'::jsonb)) k
               WHERE k NOT IN ('target_role','titulo','mensagem')) THEN
      RAISE EXCEPTION 'chaves não permitidas'; END IF;
    IF p_payload->>'target_role' IS NULL THEN RAISE EXCEPTION 'target_role obrigatório'; END IF;
    BEGIN v_target_role := (p_payload->>'target_role')::public.app_role;
    EXCEPTION WHEN others THEN RAISE EXCEPTION 'target_role inválido'; END;
    IF p_payload->>'titulo' IS NULL OR length(trim(p_payload->>'titulo'))=0 THEN
      RAISE EXCEPTION 'titulo obrigatório'; END IF;
    IF length(p_payload->>'titulo') > 200 THEN RAISE EXCEPTION 'titulo >200'; END IF;
    IF p_payload->>'mensagem' IS NULL OR length(trim(p_payload->>'mensagem'))=0 THEN
      RAISE EXCEPTION 'mensagem obrigatória'; END IF;
    IF length(p_payload->>'mensagem') > 2000 THEN RAISE EXCEPTION 'mensagem >2000'; END IF;
  END IF;
  INSERT INTO public.comunicacao_eventos(event_key,source_type,source_id,payload,created_by,idempotency_key)
  VALUES (p_event_key,p_source_type,p_source_id,COALESCE(p_payload,'{}'::jsonb),auth.uid(),p_idempotency_key)
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_event_id;
  IF v_event_id IS NULL THEN
    SELECT id INTO v_event_id FROM public.comunicacao_eventos WHERE idempotency_key = p_idempotency_key;
    RETURN jsonb_build_object('ok',true,'event_id',v_event_id,'duplicated',true);
  END IF;
  v_expand := public._comunicacao_expand_event(v_event_id, p_event_key, p_source_type, p_source_id, COALESCE(p_payload,'{}'::jsonb));
  PERFORM public._comunicacao_write_audit('event.publish.v2','comunicacao_eventos', v_event_id, NULL,
    jsonb_build_object('event_key',p_event_key,'source_type',p_source_type,'source_id',p_source_id,'expand',v_expand));
  RETURN jsonb_build_object('ok',true,'event_id',v_event_id,'duplicated',false,
    'enqueued', v_expand->'enqueued','skipped', v_expand->'skipped');
END$function$

CREATE OR REPLACE FUNCTION platform_private.link_alert_origin_core(p_alerta_id uuid, p_registro_id uuid, p_expected_alert_updated_at timestamp with time zone, p_expected_visit_version integer, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_alerta public.alertas_agronomicos;
  v_reg public.registros_consultor;
  v_receipt jsonb;
  v_updated timestamptz;
  v_obs text;
  v_fp text := md5(jsonb_build_object('op','link_origin','alerta',p_alerta_id,'visit',p_registro_id,
    'alert_at',p_expected_alert_updated_at,'version',p_expected_visit_version)::text);
BEGIN
  IF NOT coalesce(public.technical_actor_ready(v_uid),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='42501';
  END IF;
  IF p_alerta_id IS NULL OR p_registro_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023';
  END IF;
  IF p_expected_alert_updated_at IS NULL OR NOT isfinite(p_expected_alert_updated_at)
    OR p_expected_visit_version IS NULL OR p_expected_visit_version<=0 THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409';
  END IF;
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_gate_unavailable' USING ERRCODE='55000'; END IF;
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  SELECT * INTO v_alerta FROM public.alertas_agronomicos
   WHERE id=p_alerta_id AND platform_private.monitoring_refs_in_actor_tenant(fazenda_id,talhao_id,NULL)
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE='PT404'; END IF;
  v_reg := public._visita_lock_and_check(p_registro_id,NULL,false);
  -- Re-read authority after every wait (READ COMMITTED: new snapshot per statement).
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false)
    OR NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_alerta.fazenda_id,v_alerta.talhao_id,NULL),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  SELECT jsonb_build_object('fp',fingerprint,'op',operation,'result',result) INTO v_receipt
    FROM platform_private.monitoring_alert_receipts
   WHERE actor_id=v_uid AND alerta_id=p_alerta_id AND request_id=p_request_id;
  IF FOUND THEN
    IF v_receipt->>'op'<>'link_origin' OR v_receipt->>'fp' IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'request_conflict' USING ERRCODE='PT409';
    END IF;
    RETURN v_receipt->'result';
  END IF;
  IF v_reg.status::text NOT IN ('rascunho','em_andamento') THEN
    RAISE EXCEPTION 'technical_record_content_locked' USING ERRCODE='42501';
  END IF;
  IF v_reg.version IS DISTINCT FROM p_expected_visit_version
    OR v_alerta.updated_at IS DISTINCT FROM p_expected_alert_updated_at THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409';
  END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    RAISE EXCEPTION 'alert_origin_already_linked' USING ERRCODE='PT409';
  END IF;
  IF v_alerta.status::text NOT IN ('ativo','monitoramento') THEN
    RAISE EXCEPTION 'monitoring_alert_not_active' USING ERRCODE='P0001';
  END IF;
  -- Sync contract: at most one open alert per origin visit (its date is the visit/plan date).
  IF EXISTS(SELECT 1 FROM public.alertas_agronomicos o WHERE o.registro_origem_id=p_registro_id
      AND o.id<>p_alerta_id AND o.status::text<>'encerrado') THEN
    RAISE EXCEPTION 'visit_already_has_origin_alert' USING ERRCODE='PT409';
  END IF;
  -- Supported scope only: one canonical plan block, present date, exactly one coherent notice.
  -- Checked BEFORE any alert write; nothing is created automatically.
  v_obs := coalesce(v_reg.observacoes_tecnicas,'');
  IF (length(v_obs)-length(replace(v_obs,'[PLANO DE MONITORAMENTO]','')))/length('[PLANO DE MONITORAMENTO]')<>1
    OR (length(v_obs)-length(replace(v_obs,'[FIM DO PLANO]','')))/length('[FIM DO PLANO]')<>1
    OR position('[FIM DO PLANO]' in v_obs)<position('[PLANO DE MONITORAMENTO]' in v_obs)
    OR v_reg.data_proxima_visita IS NULL
    OR (SELECT count(*) FROM regexp_matches(substring(v_obs from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]'),'(^|\n)Próxima Avaliação: [^\n]*','g'))<>1
    OR substring(v_obs from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]') !~ ('(^|\n)Próxima Avaliação: '||v_reg.data_proxima_visita::text||'(\n|$)')
    OR (SELECT count(*) FROM public.monitoramento_avisos WHERE registro_consultor_id=p_registro_id AND tipo='plano_monitoramento')<>1
    OR NOT EXISTS(SELECT 1 FROM public.monitoramento_avisos WHERE registro_consultor_id=p_registro_id AND tipo='plano_monitoramento'
      AND data_referencia=v_reg.data_proxima_visita) THEN
    RAISE EXCEPTION 'origin_requires_saved_plan' USING ERRCODE='PT409';
  END IF;
  -- Date policy: linking never creates divergence; reprogram the alert first.
  IF v_alerta.data_vencimento IS DISTINCT FROM v_reg.data_proxima_visita THEN
    RAISE EXCEPTION 'origin_date_mismatch' USING ERRCODE='22023';
  END IF;
  -- Same farm and compatible plot; an alert without plot only matches by farm.
  IF v_reg.fazenda_id IS DISTINCT FROM v_alerta.fazenda_id
    OR (v_alerta.talhao_id IS NOT NULL AND v_reg.talhao_id IS DISTINCT FROM v_alerta.talhao_id)
    OR NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_alerta.fazenda_id,v_alerta.talhao_id,v_reg.id),false) THEN
    RAISE EXCEPTION 'origin_reference_mismatch' USING ERRCODE='22023';
  END IF;
  INSERT INTO platform_private.alert_origin_write_tickets VALUES(txid_current(),p_alerta_id);
  UPDATE public.alertas_agronomicos
     SET registro_origem_id=p_registro_id,
         updated_at=greatest(clock_timestamp(),v_alerta.updated_at+interval '1 microsecond')
   WHERE id=p_alerta_id AND updated_at=p_expected_alert_updated_at AND registro_origem_id IS NULL
   RETURNING updated_at INTO v_updated;
  IF NOT FOUND THEN RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409'; END IF;
  DELETE FROM platform_private.alert_origin_write_tickets WHERE transaction_id=txid_current() AND alerta_id=p_alerta_id;
  v_receipt := jsonb_build_object('ok',true,'alerta_id',p_alerta_id,'registro_origem_id',p_registro_id,
    'tipo_alerta',v_alerta.tipo_alerta,'alerta_updated_at',v_updated,'visit_version',v_reg.version,'request_id',p_request_id);
  INSERT INTO public.visitas_logs(registro_consultor_id,usuario_id,acao,descricao,metadata)
    VALUES(p_registro_id,v_uid,'alerta_origem_vinculada','Alerta agronômico vinculado à visita de origem',
      jsonb_build_object('request_id',p_request_id,'alerta_id',p_alerta_id,'fingerprint',v_fp));
  INSERT INTO platform_private.monitoring_alert_receipts VALUES(v_uid,p_alerta_id,p_request_id,'link_origin',v_fp,v_receipt);
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_technical_visit_secure(p_cliente_id uuid, p_fazenda_id uuid, p_talhao_id uuid DEFAULT NULL::uuid, p_solicitacao_origem_id uuid DEFAULT NULL::uuid, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_visit_type tipo_visita DEFAULT 'vistoria_inicial'::tipo_visita, p_priority urgencia_consultor DEFAULT 'media'::urgencia_consultor, p_initial_notes text DEFAULT NULL::text, p_client_uuid uuid DEFAULT NULL::uuid)
 RETURNS TABLE(registro_id uuid, is_new boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_existing uuid;
  v_vinculo record;
  v_new_id uuid;
BEGIN
  -- 1) Auth
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  -- 2) Admin bypass (resolvido antes de qualquer leitura de dado)
  SELECT public.has_role(v_uid, 'administrador'::app_role) INTO v_is_admin;

  -- 3) Vínculo técnico ativo com o cliente alvo (autorização ANTES de ler dados)
  IF NOT v_is_admin THEN
    SELECT * INTO v_vinculo
      FROM public.user_clientes
     WHERE user_id = v_uid
       AND cliente_id = p_cliente_id
       AND is_active = true
       AND (valid_from IS NULL OR valid_from <= now())
       AND (valid_until IS NULL OR valid_until >= now())
       AND access_level IN ('execute','manage')
     LIMIT 1;

    IF v_vinculo.id IS NULL THEN
      RAISE EXCEPTION 'no_active_binding_or_insufficient_access' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 4) Idempotência (somente após autorização), escopada ao cliente autorizado
  --    e ao próprio chamador; admin fica escopado ao cliente autorizado.
  IF p_client_uuid IS NOT NULL THEN
    SELECT id INTO v_existing
      FROM public.registros_consultor
     WHERE client_uuid = p_client_uuid
       AND cliente_id = p_cliente_id
       AND (v_is_admin OR created_by = v_uid)
     LIMIT 1;

    IF v_existing IS NOT NULL THEN
      RETURN QUERY SELECT v_existing, false;
      RETURN;
    END IF;

    -- Colisão fora do escopo autorizado: falha genérica, sem revelar
    -- a existência ou a propriedade do client_uuid.
    IF EXISTS (
      SELECT 1 FROM public.registros_consultor WHERE client_uuid = p_client_uuid
    ) THEN
      RAISE EXCEPTION 'request_rejected' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 5) Cliente ativo
  IF NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = p_cliente_id) THEN
    RAISE EXCEPTION 'cliente_not_found' USING ERRCODE = '22023';
  END IF;

  -- 6) Fazenda pertence ao cliente
  IF NOT EXISTS (
    SELECT 1 FROM public.fazendas
     WHERE id = p_fazenda_id AND cliente_id = p_cliente_id
  ) THEN
    RAISE EXCEPTION 'fazenda_does_not_belong_to_cliente' USING ERRCODE = '22023';
  END IF;

  -- 7) Talhão pertence à fazenda
  IF p_talhao_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.talhoes
       WHERE id = p_talhao_id AND fazenda_id = p_fazenda_id
    ) THEN
      RAISE EXCEPTION 'talhao_does_not_belong_to_fazenda' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- 8) Solicitação pertence ao mesmo cliente
  IF p_solicitacao_origem_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.portal_solicitacoes
       WHERE id = p_solicitacao_origem_id AND cliente_id = p_cliente_id
    ) THEN
      RAISE EXCEPTION 'solicitacao_mismatch_cliente' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- 9) Insert
  INSERT INTO public.registros_consultor(
    cliente_id, fazenda_id, talhao_id,
    consultor_responsavel, created_by,
    solicitacao_id, tipo_visita, urgencia,
    natureza_registro, status,
    observacoes_tecnicas, data_vistoria,
    client_uuid
  ) VALUES (
    p_cliente_id, p_fazenda_id, p_talhao_id,
    v_uid, v_uid,
    p_solicitacao_origem_id, p_visit_type, p_priority,
    'visita', 'rascunho',
    p_initial_notes, COALESCE(p_scheduled_at::date, CURRENT_DATE),
    p_client_uuid
  )
  RETURNING id INTO v_new_id;

  -- 10) Log de auditoria
  INSERT INTO public.visitas_logs(registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES (
    v_new_id, p_solicitacao_origem_id, 'visita_criada',
    'Visita técnica criada via create_technical_visit_secure',
    v_uid,
    jsonb_build_object(
      'tipo_visita', p_visit_type,
      'urgencia', p_priority,
      'admin_bypass', v_is_admin
    )
  );

  RETURN QUERY SELECT v_new_id, true;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_register_org_admin(p_actor_id uuid, p_user_id uuid, p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_modo_acesso text DEFAULT 'link'::text, p_responsavel_principal boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_jwt_role text; v_cpf text; v_tel text; v_email text; v_auth_email text; v_auth_created timestamptz;
BEGIN
  v_jwt_role := COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''),
    (NULLIF(current_setting('request.jwt.claims', true), '')::json ->> 'role'), '');
  IF v_jwt_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_forbidden: uso restrito ao backend da plataforma';
  END IF;
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin de plataforma';
  END IF;
  v_email := lower(btrim(COALESCE(p_email,'')));
  v_cpf := NULLIF(regexp_replace(COALESCE(p_cpf_cnpj,''), '\D', '', 'g'), '');
  v_tel := NULLIF(regexp_replace(COALESCE(p_telefone,''), '\D', '', 'g'), '');
  IF p_user_id IS NULL OR p_organization_id IS NULL OR v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$'
     OR length(btrim(COALESCE(p_nome,''))) < 3 OR length(btrim(p_nome)) > 200 THEN
    RAISE EXCEPTION 'platform_invalid: dados do administrador incompletos';
  END IF;
  IF v_cpf IS NOT NULL AND length(v_cpf) <> 11 THEN RAISE EXCEPTION 'platform_invalid: cpf'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN (10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone'; END IF;
  IF p_modo_acesso NOT IN ('link','senha_temporaria') THEN RAISE EXCEPTION 'platform_invalid: modo'; END IF;
  IF public.is_platform_superadmin(p_user_id) THEN
    RAISE EXCEPTION 'platform_forbidden: conta de plataforma não pode virar administrador de empresa';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = p_organization_id AND o.ativo IS TRUE) THEN
    RAISE EXCEPTION 'platform_invalid: empresa inexistente ou inativa';
  END IF;
  SELECT lower(u.email), u.created_at INTO v_auth_email, v_auth_created FROM auth.users u WHERE u.id = p_user_id;
  IF v_auth_email IS NULL OR v_auth_email <> v_email OR v_auth_created < now() - interval '10 minutes' THEN
    RAISE EXCEPTION 'platform_conflict: conta não é nova';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.profiles WHERE user_id = p_user_id AND (organization_id IS NOT NULL OR cliente_id IS NOT NULL))
     OR EXISTS (SELECT 1 FROM public.platform_org_admin_invites WHERE lower(email) = v_email) THEN
    RAISE EXCEPTION 'platform_conflict: usuário já existente';
  END IF;

  INSERT INTO public.profiles AS prof (user_id, nome, email, telefone, cargo, cpf_cnpj, ativo, organization_id, senha_provisoria)
  VALUES (p_user_id, btrim(p_nome), v_email, v_tel,
          CASE WHEN p_responsavel_principal THEN 'Responsável Principal' ELSE 'Administrador' END,
          v_cpf, true, p_organization_id, true)
  ON CONFLICT (user_id) DO UPDATE SET nome = EXCLUDED.nome, email = EXCLUDED.email, telefone = EXCLUDED.telefone,
    cargo = EXCLUDED.cargo, cpf_cnpj = EXCLUDED.cpf_cnpj, ativo = true,
    organization_id = EXCLUDED.organization_id, senha_provisoria = true, updated_at = now();

  INSERT INTO public.user_roles (user_id, role) VALUES (p_user_id, 'administrador'::public.app_role);

  INSERT INTO platform_private.provisional_password_state (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO UPDATE SET desde = now(), pwd_digest = NULL;

  IF p_responsavel_principal THEN
    UPDATE public.organizations SET responsavel_user_id = p_user_id, responsavel_definido_em = now(), updated_at = now()
     WHERE id = p_organization_id;
  END IF;

  INSERT INTO public.platform_org_admin_invites
    (organization_id, user_id, email, nome, cpf_cnpj, telefone, modo_acesso, responsavel_principal, invited_by, status)
  VALUES (p_organization_id, p_user_id, v_email, btrim(p_nome), v_cpf, v_tel, p_modo_acesso, p_responsavel_principal, p_actor_id, 'pendente');
END $function$

CREATE OR REPLACE FUNCTION public.enforce_micro_profile_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_alvos int;
  v_fontes int;
  v_old_status text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status_validacao ELSE NULL END;
BEGIN
  IF NEW.status_validacao = 'aprovado'
     AND (TG_OP = 'INSERT' OR COALESCE(v_old_status, '') <> 'aprovado') THEN

    IF COALESCE(btrim(NEW.resumo_curto), '') = '' THEN RAISE EXCEPTION 'approval_missing_resumo_curto'; END IF;
    IF COALESCE(btrim(NEW.explicacao_tecnica), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_tecnica'; END IF;
    IF COALESCE(btrim(NEW.explicacao_produtor), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_produtor'; END IF;
    IF COALESCE(btrim(NEW.mecanismo_acao), '') = '' THEN RAISE EXCEPTION 'approval_missing_mecanismo_acao'; END IF;
    IF COALESCE(btrim(NEW.beneficios_agronomicos), '') = '' THEN RAISE EXCEPTION 'approval_missing_beneficios_agronomicos'; END IF;
    IF COALESCE(btrim(NEW.observacoes_regulatorias), '') = '' THEN RAISE EXCEPTION 'approval_missing_observacoes_regulatorias'; END IF;

    SELECT count(*) INTO v_alvos FROM public.microorganism_targets
      WHERE microrganismo_id = NEW.microrganismo_id AND ativo = true;
    IF v_alvos = 0 THEN RAISE EXCEPTION 'approval_missing_alvos'; END IF;

    IF v_uid IS NOT NULL THEN
      SELECT (public.has_role(v_uid, 'administrador'::app_role)
           OR public.has_role(v_uid, 'gestor'::app_role)) INTO v_is_admin;
    END IF;

    IF NOT v_is_admin THEN
      SELECT count(*) INTO v_fontes FROM public.catalog_technical_sources
        WHERE (entidade_tipo = 'ficha_microrganismo' AND entidade_id = NEW.id)
           OR (entidade_tipo = 'microrganismo' AND entidade_id = NEW.microrganismo_id);
      IF v_fontes = 0 THEN RAISE EXCEPTION 'approval_missing_fontes'; END IF;
    END IF;

    IF NEW.validado_por IS NULL THEN NEW.validado_por := v_uid; END IF;
    IF NEW.validado_em IS NULL THEN NEW.validado_em := now(); END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_by := COALESCE(v_uid, NEW.updated_by);
    NEW.updated_at := now();
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_product_profile_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_alvos int;
  v_fontes int;
  v_comp int;
  v_old_status text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status_validacao ELSE NULL END;
BEGIN
  IF NEW.status_validacao = 'aprovado'
     AND (TG_OP = 'INSERT' OR COALESCE(v_old_status, '') <> 'aprovado') THEN

    IF COALESCE(btrim(NEW.resumo_curto), '') = '' THEN RAISE EXCEPTION 'approval_missing_resumo_curto'; END IF;
    IF COALESCE(btrim(NEW.explicacao_tecnica), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_tecnica'; END IF;
    IF COALESCE(btrim(NEW.explicacao_produtor), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_produtor'; END IF;
    IF COALESCE(btrim(NEW.beneficio_combinado), '') = '' THEN RAISE EXCEPTION 'approval_missing_beneficio_combinado'; END IF;
    IF COALESCE(btrim(NEW.observacoes_regulatorias), '') = ''
       AND COALESCE(btrim(NEW.cuidados_aplicacao), '') = '' THEN
      RAISE EXCEPTION 'approval_missing_observacoes_ou_cuidados';
    END IF;

    SELECT count(*) INTO v_comp FROM public.formulacoes WHERE produto_id = NEW.produto_id;
    IF v_comp = 0 THEN RAISE EXCEPTION 'approval_missing_composicao'; END IF;

    SELECT count(*) INTO v_alvos FROM public.product_target_recommendations
      WHERE produto_id = NEW.produto_id AND ativo = true;
    IF v_alvos = 0 THEN RAISE EXCEPTION 'approval_missing_alvos'; END IF;

    IF v_uid IS NOT NULL THEN
      SELECT (public.has_role(v_uid, 'administrador'::app_role)
           OR public.has_role(v_uid, 'gestor'::app_role)) INTO v_is_admin;
    END IF;

    IF NOT v_is_admin THEN
      SELECT count(*) INTO v_fontes FROM public.catalog_technical_sources
        WHERE (entidade_tipo = 'ficha_produto' AND entidade_id = NEW.id)
           OR (entidade_tipo = 'produto' AND entidade_id = NEW.produto_id);
      IF v_fontes = 0 THEN RAISE EXCEPTION 'approval_missing_fontes'; END IF;
    END IF;

    IF NEW.validado_por IS NULL THEN NEW.validado_por := v_uid; END IF;
    IF NEW.validado_em IS NULL THEN NEW.validado_em := now(); END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_by := COALESCE(v_uid, NEW.updated_by);
    NEW.updated_at := now();
  END IF;

  RETURN NEW;
END;
$function$

