CREATE OR REPLACE FUNCTION platform_private.reschedule_monitoring_core(p_alerta_id uuid, p_nova_data date, p_expected_alert_updated_at timestamp with time zone, p_expected_visit_version integer, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_alerta public.alertas_agronomicos;
  v_reg public.registros_consultor;
  v_receipt jsonb;
  v_obs text; v_block text; v_new_block text;
  v_notice uuid; v_version integer; v_updated timestamptz; v_visit_updated boolean := false; v_mode text := 'somente_alerta';
  v_fp text := md5(jsonb_build_object('op','reschedule','alerta',p_alerta_id,'date',p_nova_data,
    'alert_at',p_expected_alert_updated_at,'version',p_expected_visit_version)::text);
BEGIN
  IF v_uid IS NULL OR NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT (public.has_role(v_uid,'administrador'::public.app_role) OR public.has_role(v_uid,'gestor'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501';
  END IF;
  IF p_alerta_id IS NULL OR p_nova_data IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023';
  END IF;
  IF p_expected_alert_updated_at IS NULL OR NOT isfinite(p_expected_alert_updated_at)
    OR (p_expected_visit_version IS NOT NULL AND p_expected_visit_version<=0) THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409';
  END IF;
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_gate_unavailable' USING ERRCODE='55000'; END IF;
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT (public.has_role(v_uid,'administrador'::public.app_role) OR public.has_role(v_uid,'gestor'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_alerta FROM public.alertas_agronomicos
   WHERE id=p_alerta_id AND platform_private.monitoring_refs_in_actor_tenant(fazenda_id,talhao_id,registro_origem_id)
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE='PT404'; END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    v_reg := public._visita_lock_and_check(v_alerta.registro_origem_id,NULL,false);
  END IF;
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT (public.has_role(v_uid,'administrador'::public.app_role) OR public.has_role(v_uid,'gestor'::public.app_role))
    OR NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_alerta.fazenda_id,v_alerta.talhao_id,v_alerta.registro_origem_id),false)
    OR (v_alerta.registro_origem_id IS NOT NULL AND NOT coalesce(public.can_manage_technical_visit(v_uid,v_alerta.registro_origem_id),false)) THEN
    RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE='PT404';
  END IF;
  SELECT jsonb_build_object('fp',fingerprint,'op',operation,'result',result) INTO v_receipt
    FROM platform_private.monitoring_alert_receipts
   WHERE actor_id=v_uid AND alerta_id=p_alerta_id AND request_id=p_request_id;
  IF FOUND THEN
    IF v_receipt->>'op'<>'reschedule' OR v_receipt->>'fp' IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'request_conflict' USING ERRCODE='PT409';
    END IF;
    RETURN v_receipt->'result';
  END IF;
  IF p_nova_data < (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date THEN
    RAISE EXCEPTION 'past_date_not_allowed' USING ERRCODE='22023';
  END IF;
  IF v_alerta.status IS DISTINCT FROM 'monitoramento'::public.status_alerta THEN
    RAISE EXCEPTION 'monitoring_alert_not_active' USING ERRCODE='P0001';
  END IF;
  IF v_alerta.updated_at IS DISTINCT FROM p_expected_alert_updated_at
    OR (v_alerta.registro_origem_id IS NULL AND p_expected_visit_version IS NOT NULL)
    OR (v_alerta.registro_origem_id IS NOT NULL AND v_reg.version IS DISTINCT FROM p_expected_visit_version) THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409';
  END IF;
  IF v_alerta.registro_origem_id IS NOT NULL AND v_reg.status::text IN ('rascunho','em_andamento') THEN
    -- Shared date: any other open alert on the same visit makes synchronization ambiguous.
    IF EXISTS(SELECT 1 FROM public.alertas_agronomicos o WHERE o.registro_origem_id=v_reg.id
        AND o.id<>p_alerta_id AND o.status::text<>'encerrado') THEN
      RAISE EXCEPTION 'multiple_alerts_share_visit' USING ERRCODE='PT409';
    END IF;
    v_obs := coalesce(v_reg.observacoes_tecnicas,'');
    IF (length(v_obs)-length(replace(v_obs,'[PLANO DE MONITORAMENTO]','')))/length('[PLANO DE MONITORAMENTO]')>1
      OR (length(v_obs)-length(replace(v_obs,'[FIM DO PLANO]','')))/length('[FIM DO PLANO]')>1
      OR (position('[PLANO DE MONITORAMENTO]' in v_obs)>0)<>(position('[FIM DO PLANO]' in v_obs)>0)
      OR (position('[FIM DO PLANO]' in v_obs)>0 AND position('[FIM DO PLANO]' in v_obs)<position('[PLANO DE MONITORAMENTO]' in v_obs)) THEN
      RAISE EXCEPTION 'ambiguous_plan_text' USING ERRCODE='PT409';
    END IF;
    v_block := substring(v_obs from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]');
    IF v_block IS NOT NULL THEN
      -- Only the date line changes; every other byte of notes and plan is preserved.
      IF (SELECT count(*) FROM regexp_matches(v_block,'(^|\n)Próxima Avaliação: [^\n]*','g'))<>1 THEN
        RAISE EXCEPTION 'ambiguous_plan_text' USING ERRCODE='PT409';
      END IF;
      v_new_block := regexp_replace(v_block,'(^|\n)Próxima Avaliação: [^\n]*','\1Próxima Avaliação: '||p_nova_data::text);
      v_obs := overlay(v_obs placing v_new_block from position(v_block in v_obs) for length(v_block));
      -- Exactly one coherent generic notice; never fabricate one.
      IF (SELECT count(*) FROM public.monitoramento_avisos WHERE registro_consultor_id=v_reg.id AND tipo='plano_monitoramento')<>1
        OR v_block !~ ('(^|\n)Próxima Avaliação: '||coalesce(v_reg.data_proxima_visita::text,'<none>')||'(\n|$)') THEN
        RAISE EXCEPTION 'plan_notice_incoherent' USING ERRCODE='PT409';
      END IF;
      SELECT id INTO v_notice FROM public.monitoramento_avisos
       WHERE registro_consultor_id=v_reg.id AND tipo='plano_monitoramento'
         AND data_referencia IS NOT DISTINCT FROM v_reg.data_proxima_visita FOR UPDATE;
      IF v_notice IS NULL THEN RAISE EXCEPTION 'plan_notice_incoherent' USING ERRCODE='PT409'; END IF;
      INSERT INTO platform_private.visit_plan_write_tickets(transaction_id,registro_id,block,next_date)
        VALUES(txid_current(),v_reg.id,v_new_block,p_nova_data);
    ELSE
      -- Legacy origin without plan: generic writers are not all protected; refuse instead of claiming sync.
      RAISE EXCEPTION 'origin_without_plan_unsupported' USING ERRCODE='PT409';
    END IF;
    UPDATE public.registros_consultor
       SET observacoes_tecnicas=v_obs,
           data_proxima_visita=p_nova_data, version=p_expected_visit_version+1, updated_at=clock_timestamp()
     WHERE id=v_reg.id AND version=p_expected_visit_version
       AND public.can_manage_technical_visit(v_uid,id)
     RETURNING version INTO v_version;
    IF NOT FOUND OR v_version<>p_expected_visit_version+1 THEN RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409'; END IF;
    IF v_notice IS NOT NULL THEN
      UPDATE public.monitoramento_avisos SET data_referencia=p_nova_data WHERE id=v_notice AND registro_consultor_id=v_reg.id;
      IF NOT FOUND THEN RAISE EXCEPTION 'notice_conflict' USING ERRCODE='PT409'; END IF;
    END IF;
    DELETE FROM platform_private.visit_plan_write_tickets WHERE transaction_id=txid_current() AND registro_id=v_reg.id;
    v_visit_updated := true;
    v_mode := 'plano_visita_aviso_alerta';
  ELSIF v_alerta.registro_origem_id IS NOT NULL THEN
    -- Immutable visit: explicit alert-only mode; the visit/plan is NOT synchronized.
    v_version := v_reg.version;
  END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    INSERT INTO platform_private.alert_origin_write_tickets VALUES(txid_current(),p_alerta_id);
  END IF;
  UPDATE public.alertas_agronomicos
     SET data_vencimento=p_nova_data, nivel_risco='medio'::public.nivel_risco,
         updated_at=greatest(clock_timestamp(),v_alerta.updated_at+interval '1 microsecond')
   WHERE id=p_alerta_id AND updated_at=p_expected_alert_updated_at
   RETURNING updated_at INTO v_updated;
  IF NOT FOUND THEN RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409'; END IF;
  DELETE FROM platform_private.alert_origin_write_tickets WHERE transaction_id=txid_current() AND alerta_id=p_alerta_id;
  v_receipt := jsonb_build_object('success',true,'alerta_id',p_alerta_id,'data_anterior',v_alerta.data_vencimento,
    'nova_data',p_nova_data,'registro_origem_id',v_alerta.registro_origem_id,'visita_atualizada',v_visit_updated,'modo',v_mode,
    'visit_version',v_version,'alerta_updated_at',v_updated,'request_id',p_request_id);
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    INSERT INTO public.visitas_logs(registro_consultor_id,usuario_id,acao,descricao,metadata)
      VALUES(v_alerta.registro_origem_id,v_uid,'monitoramento_reprogramado','Monitoramento reprogramado pelo alerta de origem',
        jsonb_build_object('request_id',p_request_id,'alerta_id',p_alerta_id,'fingerprint',v_fp,'modo',v_mode));
  END IF;
  INSERT INTO platform_private.monitoring_alert_receipts VALUES(v_uid,p_alerta_id,p_request_id,'reschedule',v_fp,v_receipt);
  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_technical_visit_secure(p_registro_id uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_precisao_gps numeric DEFAULT NULL::numeric, p_foto_url text DEFAULT NULL::text, p_foto_path text DEFAULT NULL::text, p_observacoes text DEFAULT NULL::text, p_client_uuid uuid DEFAULT NULL::uuid)
 RETURNS TABLE(registro_id uuid, checkout_id uuid, finalized_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_reg public.registros_consultor;
  v_existing public.visitas_checkin;
  v_diag_count int;
  v_new_checkout uuid;
  v_now timestamptz := now();
  v_prev_final timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  v_is_admin := COALESCE(public.has_role(v_uid, 'administrador'::app_role), false);

  -- H9-E2 (A): gate de escopo fail-closed ANTES de qualquer SELECT em
  -- registros_consultor ou visitas_checkin. Registro inexistente, registro
  -- alheio, p_registro_id NULL e qualquer client_uuid (existente, alheio ou
  -- aleatorio) produzem a MESMA superficie publica: 42501 not_visit_owner.
  IF NOT v_is_admin
     AND NOT COALESCE(public._visita_scope_ok(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'not_visit_owner' USING ERRCODE = '42501';
  END IF;

  -- H9-E2 (B): lock por registro ANTES da busca idempotente. Serializa
  -- encerramentos concorrentes do mesmo agregado; nao ha lock global.
  SELECT * INTO v_reg
    FROM public.registros_consultor r
   WHERE r.id = p_registro_id
     FOR UPDATE;

  IF v_reg.id IS NULL THEN
    -- Alcancavel apenas no bypass de administrador; mantem a superficie unica.
    RAISE EXCEPTION 'not_visit_owner' USING ERRCODE = '42501';
  END IF;

  -- H9-E2 (B): busca idempotente POS-lock e ANTES de qualquer rejeicao por
  -- estado. A sessao perdedora da corrida encontra aqui o resultado vencedor
  -- (ja commitado) e retorna identico, em vez de erro de estado.
  IF p_client_uuid IS NOT NULL THEN
    SELECT * INTO v_existing
      FROM public.visitas_checkin
     WHERE client_uuid = p_client_uuid
     LIMIT 1;

    IF v_existing.id IS NOT NULL THEN
      IF v_existing.registro_consultor_id IS DISTINCT FROM p_registro_id
         OR v_existing.tipo_checkin <> 'checkout'::public.tipo_checkin
         OR (v_existing.consultor_id IS DISTINCT FROM v_uid AND NOT v_is_admin) THEN
        RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = '22023';
      END IF;

      SELECT r.finalized_at INTO v_prev_final
        FROM public.registros_consultor r
       WHERE r.id = p_registro_id;

      RETURN QUERY
        SELECT p_registro_id,
               v_existing.id,
               COALESCE(v_prev_final, v_existing.data_hora_checkin);
      RETURN;
    END IF;
  END IF;
  -- Nota: com p_client_uuid NULL nao existe chave de idempotencia; a chamada
  -- permanece compativel, porem NAO e idempotente. Limitacao documentada.

  IF v_reg.status <> 'em_andamento' THEN
    RAISE EXCEPTION 'visit_not_in_progress:%', v_reg.status USING ERRCODE = '22023';
  END IF;

  -- Exige ao menos um diagnostico
  SELECT count(*) INTO v_diag_count
    FROM public.visita_diagnosticos vd WHERE vd.registro_id = v_reg.id;
  IF v_diag_count = 0 THEN
    RAISE EXCEPTION 'diagnostico_required' USING ERRCODE = '22023';
  END IF;

  -- H9-E1R (2): check-out gravado com o tipo canonico 'checkout'.
  BEGIN
    INSERT INTO public.visitas_checkin(
      registro_consultor_id, solicitacao_id, consultor_id,
      cliente_id, fazenda_id, talhao_id,
      latitude, longitude, precisao_gps,
      foto_url, foto_path, observacoes,
      tipo_checkin, status, client_uuid
    ) VALUES (
      v_reg.id, v_reg.solicitacao_id, v_uid,
      v_reg.cliente_id, v_reg.fazenda_id, v_reg.talhao_id,
      p_latitude, p_longitude, p_precisao_gps,
      p_foto_url, p_foto_path, p_observacoes,
      'checkout'::public.tipo_checkin, 'realizado', p_client_uuid
    )
    RETURNING id INTO v_new_checkout;
  EXCEPTION WHEN unique_violation THEN
    -- Corrida do mesmo client_uuid em registros distintos (fora do lock):
    -- converge para o vencedor, fail-closed.
    SELECT * INTO v_existing
      FROM public.visitas_checkin
     WHERE client_uuid = p_client_uuid
     LIMIT 1;

    IF v_existing.id IS NULL
       OR v_existing.registro_consultor_id IS DISTINCT FROM p_registro_id
       OR v_existing.tipo_checkin <> 'checkout'::public.tipo_checkin
       OR (v_existing.consultor_id IS DISTINCT FROM v_uid AND NOT v_is_admin) THEN
      RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = '22023';
    END IF;

    SELECT r.finalized_at INTO v_prev_final
      FROM public.registros_consultor r
     WHERE r.id = p_registro_id;

    RETURN QUERY
      SELECT p_registro_id,
             v_existing.id,
             COALESCE(v_prev_final, v_existing.data_hora_checkin);
    RETURN;
  END;

  UPDATE public.registros_consultor
     SET status = 'finalizado',
         hora_fim = v_now,
         finalized_at = v_now,
         finalized_by = v_uid,
         updated_at = v_now
   WHERE id = v_reg.id;

  INSERT INTO public.visitas_logs(registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES (v_reg.id, v_reg.solicitacao_id, 'checkout', 'Check-out e finalizacao da visita', v_uid,
          jsonb_build_object('checkout_id', v_new_checkout, 'admin_bypass', v_is_admin));

  RETURN QUERY SELECT v_reg.id, v_new_checkout, v_now;
END;
$function$

CREATE OR REPLACE FUNCTION public.fiscal_invoice_items_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_invoice_id uuid;
  v_status text;
begin
  v_invoice_id := case when tg_op = 'DELETE' then old.fiscal_invoice_id else new.fiscal_invoice_id end;
  if v_invoice_id is null then
    raise exception using errcode = 'P0001', message = 'O item fiscal deve estar vinculado a uma nota fiscal.';
  end if;

  select fi.normalized_status
    into v_status
    from public.fiscal_invoices fi
   where fi.id = v_invoice_id
   for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'A nota fiscal vinculada ao item não foi encontrada.';
  end if;

  if v_status is null or v_status not in ('DRAFT','VALIDATING','READY','REJECTED','ERROR') then
    raise exception using errcode = 'P0001', message = 'Os itens desta nota fiscal não podem ser alterados no estado atual.';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fiscal_json_has_sensitive_key(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  k text;
  v jsonb;
  item jsonb;
  sensitive constant text[] := ARRAY[
    'token','password','senha','secret','api_key','apikey',
    'private_key','privatekey','pfx','p12',
    'certificate_content','certificate_pem','pem',
    'authorization','bearer'
  ];
BEGIN
  IF p IS NULL THEN RETURN false; END IF;
  IF jsonb_typeof(p) = 'object' THEN
    FOR k, v IN SELECT key, value FROM jsonb_each(p) LOOP
      IF lower(k) = ANY (sensitive) THEN
        RETURN true;
      END IF;
      IF public.fiscal_json_has_sensitive_key(v) THEN
        RETURN true;
      END IF;
    END LOOP;
    RETURN false;
  ELSIF jsonb_typeof(p) = 'array' THEN
    FOR item IN SELECT value FROM jsonb_array_elements(p) LOOP
      IF public.fiscal_json_has_sensitive_key(item) THEN
        RETURN true;
      END IF;
    END LOOP;
    RETURN false;
  END IF;
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.fiscal_rtc_has_sensitive_key(payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  k text; v jsonb; needle text;
  needles text[] := ARRAY[
    'token','password','senha','secret','api_key','apikey',
    'private_key','privatekey','pfx','p12',
    'certificate','certificate_content','certificate_pem','pem',
    'authorization','bearer','access_token','refresh_token','client_secret',
    'production_enabled'];
BEGIN
  IF payload IS NULL THEN RETURN false; END IF;
  IF jsonb_typeof(payload) = 'object' THEN
    FOR k, v IN SELECT * FROM jsonb_each(payload) LOOP
      FOREACH needle IN ARRAY needles LOOP
        IF position(needle IN lower(k)) > 0 THEN RETURN true; END IF;
      END LOOP;
      IF public.fiscal_rtc_has_sensitive_key(v) THEN RETURN true; END IF;
    END LOOP;
  ELSIF jsonb_typeof(payload) = 'array' THEN
    FOR v IN SELECT jsonb_array_elements(payload) LOOP
      IF public.fiscal_rtc_has_sensitive_key(v) THEN RETURN true; END IF;
    END LOOP;
  END IF;
  RETURN false;
END; $function$

CREATE OR REPLACE FUNCTION public.fiscal_sinief20_snapshot_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND OLD.original_recipient_snapshot IS NOT NULL AND NEW.original_recipient_snapshot IS DISTINCT FROM OLD.original_recipient_snapshot THEN
  RAISE EXCEPTION 'SINIEF 20/2026: original_recipient_snapshot e imutavel apos persistencia.' USING ERRCODE='P0001';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fiscal_validate_key_usage(p_arr jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_len integer;
  v_el  jsonb;
BEGIN
  IF p_arr IS NULL THEN RETURN; END IF;
  IF jsonb_typeof(p_arr) <> 'array' THEN
    RAISE EXCEPTION 'key_usage_invalid' USING ERRCODE = '22023';
  END IF;
  v_len := jsonb_array_length(p_arr);
  IF v_len > 20 THEN
    RAISE EXCEPTION 'key_usage_too_many' USING ERRCODE = '22023';
  END IF;
  FOR v_el IN SELECT * FROM jsonb_array_elements(p_arr) LOOP
    IF jsonb_typeof(v_el) <> 'string' THEN
      RAISE EXCEPTION 'key_usage_item_not_string' USING ERRCODE = '22023';
    END IF;
    IF char_length(v_el #>> '{}') < 1 OR char_length(v_el #>> '{}') > 80 THEN
      RAISE EXCEPTION 'key_usage_item_length_invalid' USING ERRCODE = '22023';
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.fiscal_validate_snapshot_keys(p_obj jsonb, p_allowed text[], p_label text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE k text;
BEGIN
  IF p_obj IS NULL OR jsonb_typeof(p_obj) <> 'object' THEN
    RETURN;
  END IF;
  FOR k IN SELECT jsonb_object_keys(p_obj) LOOP
    IF NOT (k = ANY(p_allowed)) THEN
      RAISE EXCEPTION 'snapshot_unknown_key:%:%', p_label, k
        USING ERRCODE = '22023';
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_upsert_communication_rule(p_rule_id uuid, p_event_key text, p_perfil app_role, p_estrategia text, p_canal comunicacao_canal, p_template_chave text, p_template_versao integer, p_condicoes jsonb, p_prioridade integer, p_enabled boolean, p_cooldown_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; prev public.comunicacao_regras%rowtype;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_event_key NOT IN ('produto_pronto_retirada','produto_pronto_aplicacao','administrative_important_update') THEN
    RAISE EXCEPTION 'event_key não permitido: %', p_event_key;
  END IF;
  IF COALESCE(p_estrategia,'by_role') NOT IN ('by_role','source_participants','broadcast_role') THEN
    RAISE EXCEPTION 'estrategia inválida: %', p_estrategia;
  END IF;
  IF p_event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao')
     AND COALESCE(p_estrategia,'by_role') = 'broadcast_role' THEN
    RAISE EXCEPTION 'broadcast_role não permitido para eventos de OS';
  END IF;
  IF p_event_key = 'administrative_important_update' THEN
    IF COALESCE(p_estrategia,'by_role') <> 'broadcast_role' THEN
      RAISE EXCEPTION 'administrative_important_update exige broadcast_role';
    END IF;
    IF p_perfil IS NULL THEN
      RAISE EXCEPTION 'administrative_important_update exige perfil (target_role)';
    END IF;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.comunicacao_templates
     WHERE chave = p_template_chave AND canal = p_canal
       AND (p_template_versao IS NULL OR versao = p_template_versao)
  ) THEN
    RAISE EXCEPTION 'template % (canal=%, versao=%) inexistente',
      p_template_chave, p_canal, COALESCE(p_template_versao::text,'active');
  END IF;

  IF p_rule_id IS NULL THEN
    INSERT INTO public.comunicacao_regras(event_key,perfil,estrategia,canal,template_chave,template_versao,
      condicoes,prioridade,enabled,cooldown_seconds,created_by,updated_by)
    VALUES (p_event_key,p_perfil,COALESCE(p_estrategia,'by_role'),p_canal,p_template_chave,p_template_versao,
      COALESCE(p_condicoes,'{}'::jsonb),COALESCE(p_prioridade,100),COALESCE(p_enabled,false),
      COALESCE(p_cooldown_seconds,0),auth.uid(),auth.uid())
    RETURNING id INTO v_id;
    PERFORM public._comunicacao_write_audit('rule.create','comunicacao_regras',v_id, NULL,
      (SELECT to_jsonb(r) FROM public.comunicacao_regras r WHERE r.id = v_id));
  ELSE
    SELECT * INTO prev FROM public.comunicacao_regras WHERE id = p_rule_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'regra não encontrada'; END IF;
    UPDATE public.comunicacao_regras
       SET event_key = p_event_key, perfil = p_perfil, estrategia = COALESCE(p_estrategia,'by_role'),
           canal = p_canal, template_chave = p_template_chave, template_versao = p_template_versao,
           condicoes = COALESCE(p_condicoes,'{}'::jsonb), prioridade = COALESCE(p_prioridade,100),
           enabled = COALESCE(p_enabled,false), cooldown_seconds = COALESCE(p_cooldown_seconds,0),
           updated_by = auth.uid(), updated_at = now()
     WHERE id = p_rule_id RETURNING id INTO v_id;
    PERFORM public._comunicacao_write_audit('rule.update','comunicacao_regras',v_id,
      to_jsonb(prev), (SELECT to_jsonb(r) FROM public.comunicacao_regras r WHERE r.id = v_id));
  END IF;
  RETURN jsonb_build_object('ok',true,'rule_id',v_id);
END$function$

CREATE OR REPLACE FUNCTION public.fn_calc_next_generation_date(_freq text, _from_date date, _due_day integer)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_next DATE;
BEGIN
  CASE _freq
    WHEN 'MONTHLY' THEN v_next := (_from_date + INTERVAL '1 month')::DATE;
    WHEN 'WEEKLY' THEN v_next := (_from_date + INTERVAL '1 week')::DATE;
    WHEN 'BIWEEKLY' THEN v_next := (_from_date + INTERVAL '2 weeks')::DATE;
    WHEN 'QUARTERLY' THEN v_next := (_from_date + INTERVAL '3 months')::DATE;
    WHEN 'YEARLY' THEN v_next := (_from_date + INTERVAL '1 year')::DATE;
    ELSE v_next := (_from_date + INTERVAL '1 month')::DATE;
  END CASE;
  IF _due_day IS NOT NULL AND _freq IN ('MONTHLY','QUARTERLY','YEARLY') THEN
    BEGIN
      v_next := make_date(EXTRACT(YEAR FROM v_next)::INT, EXTRACT(MONTH FROM v_next)::INT,
        LEAST(_due_day, EXTRACT(DAY FROM (date_trunc('month', v_next) + INTERVAL '1 month - 1 day'))::INT));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  RETURN v_next;
END $function$

CREATE OR REPLACE FUNCTION public.fn_calc_os_faturamento_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Subtotal based on pricing model
    IF NEW.modelo_precificacao = 'HA' THEN
        NEW.subtotal := NEW.area_hectares_snapshot * NEW.valor_ha_snapshot;
    END IF;

    -- Total Faturavel
    NEW.valor_total_faturavel := NEW.subtotal - NEW.desconto_valor + NEW.acrescimo_valor;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_enviar_visita_aprovacao(p_registro_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_new_version integer;
  v_rows integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_registro_id IS NULL THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;
  -- CAS is mandatory: NULL/non-positive never matches.
  IF p_expected_version IS NULL OR p_expected_version <= 0 THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;
  -- Fast denial (no lock taken for unauthorized callers).
  IF NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- 1) Canonical gate BEFORE the visit row lock (same order as revocation writers).
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate_unavailable' USING ERRCODE = '55000';
  END IF;
  -- 2) Re-authorize after the gate wait (revocation committed first is observed here).
  IF NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- 3) Visit row lock.
  SELECT r.* INTO v_reg FROM public.registros_consultor r
   WHERE r.id = p_registro_id
     AND COALESCE(public.can_manage_technical_visit(v_uid,p_registro_id),false)
     AND (public.has_role(v_uid, 'administrador'::app_role)
       OR r.created_by = v_uid
       OR r.consultor_responsavel = v_uid
       OR (r.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(v_uid, r.cliente_id, ARRAY['execute','manage'])))
   FOR UPDATE;

  -- 4) Re-authorize + tenant + original actor restriction after the row wait; never cached.
  IF v_reg.id IS NULL
     OR NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false)
     OR NOT COALESCE((
       public.has_role(v_uid, 'administrador'::app_role)
       OR v_reg.created_by = v_uid
       OR v_reg.consultor_responsavel = v_uid
       OR (v_reg.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(v_uid, v_reg.cliente_id, ARRAY['execute','manage']))
     ), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  IF v_reg.status::text <> 'finalizado' THEN
    RAISE EXCEPTION 'transicao_invalida' USING ERRCODE = 'PT409';
  END IF;
  IF v_reg.version IS NULL OR p_expected_version <> v_reg.version THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  v_new_version := v_reg.version + 1;

  UPDATE public.registros_consultor
     SET status = 'enviado_aprovacao'::status_registro_consultor,
         version = v_new_version,
         updated_at = now()
   WHERE id = p_registro_id
     AND version = p_expected_version
     AND status = 'finalizado'::status_registro_consultor
     AND cliente_id IS NOT DISTINCT FROM v_reg.cliente_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
    VALUES (p_registro_id, v_uid, 'enviado_aprovacao', 'Visita enviada para aprovação via rpc_enviar_visita_aprovacao');
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'log_write_failed' USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object('id', p_registro_id, 'status', 'enviado_aprovacao', 'version', v_new_version);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_update_communication_preferences(p_canal comunicacao_canal, p_enabled boolean, p_whatsapp_opt_in boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_prev public.comunicacao_preferencias%rowtype;
BEGIN
  IF v_uid IS NULL OR NOT COALESCE(platform_private.platform_actor_access_ready(v_uid), false) THEN
    RAISE EXCEPTION 'COMMUNICATION_PREFERENCES_ACTOR_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  v_org := platform_private.h15_actor_organization();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'COMMUNICATION_PREFERENCES_ORGANIZATION_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_prev FROM public.comunicacao_preferencias WHERE user_id = v_uid AND canal = p_canal;
  INSERT INTO public.comunicacao_preferencias(user_id, canal, enabled,
      whatsapp_opt_in_at, whatsapp_opt_out_at, source)
  VALUES (v_uid, p_canal, COALESCE(p_enabled,true),
      CASE WHEN p_whatsapp_opt_in IS TRUE THEN now() END,
      CASE WHEN p_whatsapp_opt_in IS FALSE THEN now() END,
      'user')
  ON CONFLICT (user_id, canal) WHERE user_id IS NOT NULL DO UPDATE
    SET enabled = EXCLUDED.enabled,
        whatsapp_opt_in_at = CASE WHEN p_whatsapp_opt_in IS TRUE THEN now()
                                   ELSE public.comunicacao_preferencias.whatsapp_opt_in_at END,
        whatsapp_opt_out_at = CASE WHEN p_whatsapp_opt_in IS FALSE THEN now()
                                   ELSE public.comunicacao_preferencias.whatsapp_opt_out_at END,
        updated_at = now();
  IF p_whatsapp_opt_in IS FALSE THEN
    PERFORM public._comunicacao_write_consent(v_uid, NULL, p_canal, 'opt_out','user');
  ELSIF p_whatsapp_opt_in IS TRUE THEN
    PERFORM public._comunicacao_write_consent(v_uid, NULL, p_canal, 'opt_in','user');
  END IF;
  IF v_prev.id IS NULL OR v_prev.enabled IS DISTINCT FROM COALESCE(p_enabled,true) THEN
    PERFORM public._comunicacao_write_consent(v_uid, NULL, p_canal,
      CASE WHEN COALESCE(p_enabled,true) THEN 'enabled_on' ELSE 'enabled_off' END, 'user');
  END IF;
  RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.fn_cc_validate_item_input(p_plan_id uuid, p_pricing_mode text, p_condition_price numeric, p_discount_percent numeric)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_plan_mode text;
BEGIN
  IF p_pricing_mode NOT IN ('fixed_item_price','discount_from_base','quote_only') THEN
    RAISE EXCEPTION 'invalid_pricing_mode';
  END IF;
  SELECT pricing_mode INTO v_plan_mode FROM public.commercial_payment_plans WHERE id = p_plan_id;
  IF v_plan_mode IS NULL THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF p_pricing_mode <> 'quote_only' AND p_pricing_mode <> v_plan_mode THEN
    RAISE EXCEPTION 'pricing_mode_conflicts_plan';
  END IF;
  IF p_pricing_mode = 'fixed_item_price' AND COALESCE(p_condition_price,0) <= 0 THEN
    RAISE EXCEPTION 'condition_price_required';
  END IF;
  IF p_pricing_mode = 'discount_from_base'
     AND p_discount_percent IS NOT NULL
     AND (p_discount_percent < 0 OR p_discount_percent > 100) THEN
    RAISE EXCEPTION 'discount_percent_out_of_range';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.platform_update_catalog_label(p_id uuid, p_expected_updated_at timestamp with time zone, p_rotulo_exibicao text, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid := gen_random_uuid();
  v_op public.catalog_family_labels%ROWTYPE; v_np public.catalog_family_labels%ROWTYPE;
  v_exib text := pg_catalog.btrim(COALESCE(p_rotulo_exibicao, ''));
BEGIN
  v_actor := platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at)
     OR pg_catalog.char_length(v_exib) < 2 OR pg_catalog.char_length(v_exib) > 80
     OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_invalid';
  END IF;
  -- Gate canônico de revogação: writers de user_roles/profiles (a00_cf_user_gate) e convites
  -- (a00_cf_invitation_gate) adquirem cf_user_guards_v1.state. Ordem: gate -> idempotência -> linha.
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'PT503', MESSAGE = 'catalog_label_gate_unavailable'; END IF;
  -- Autoridade fresca (novo snapshot por statement) após a espera do gate.
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  -- Mesma chave do catalog_entity_replay (reentrante na transação): espera aqui, revalida antes do replay.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_idempotency_key::text,0));
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  v_req := pg_catalog.jsonb_build_object('id', p_id, 'expected_updated_at', p_expected_updated_at,
    'rotulo_exibicao', v_exib, 'reason', pg_catalog.btrim(COALESCE(p_reason, '')));
  v_replay := platform_private.catalog_entity_replay(v_actor, 'update_catalog_label', v_req, p_reason, p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  SELECT * INTO v_op FROM public.catalog_family_labels WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_label_unavailable'; END IF;
  -- Revalida após a espera do lock de linha, antes do CAS/UPDATE.
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  IF v_op.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'catalog_label_conflict'; END IF;
  IF v_op.rotulo_exibicao IS NOT DISTINCT FROM v_exib THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_no_change'; END IF;

  UPDATE public.catalog_family_labels SET rotulo_exibicao = v_exib
   WHERE id = p_id AND updated_at = p_expected_updated_at
  RETURNING * INTO v_np;
  IF NOT FOUND OR v_np.updated_at IS NULL OR v_np.updated_at <= v_op.updated_at
     OR v_np.rotulo IS DISTINCT FROM v_op.rotulo OR v_np.familia IS DISTINCT FROM v_op.familia
     OR v_np.ativo IS DISTINCT FROM v_op.ativo THEN
    RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'catalog_label_confirmation_failed'; END IF;

  v_receipt := pg_catalog.jsonb_build_object('id', p_id, 'familia', v_np.familia, 'rotulo', v_np.rotulo,
    'rotulo_exibicao', v_exib, 'updated_at', v_np.updated_at, 'idempotency_key', p_idempotency_key,
    'audit_id', v_audit, 'idempotent', false);
  PERFORM platform_private.catalog_entity_audit(v_actor, 'update_catalog_label', p_reason, p_idempotency_key,
    v_req, v_receipt,
    pg_catalog.jsonb_build_object('id', p_id, 'rotulo_exibicao', v_op.rotulo_exibicao, 'updated_at', v_op.updated_at),
    pg_catalog.jsonb_build_object('id', p_id, 'rotulo_exibicao', v_exib, 'updated_at', v_np.updated_at));
  RETURN v_receipt;
END $function$

CREATE OR REPLACE FUNCTION public.platform_set_catalog_label_active(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid := gen_random_uuid();
  v_op public.catalog_family_labels%ROWTYPE; v_np public.catalog_family_labels%ROWTYPE;
BEGIN
  v_actor := platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at)
     OR p_ativo IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_invalid';
  END IF;
  -- Gate canônico de revogação: writers de user_roles/profiles (a00_cf_user_gate) e convites
  -- (a00_cf_invitation_gate) adquirem cf_user_guards_v1.state. Ordem: gate -> idempotência -> linha.
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'PT503', MESSAGE = 'catalog_label_gate_unavailable'; END IF;
  -- Autoridade fresca (novo snapshot por statement) após a espera do gate.
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  -- Mesma chave do catalog_entity_replay (reentrante na transação): espera aqui, revalida antes do replay.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_idempotency_key::text,0));
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  v_req := pg_catalog.jsonb_build_object('id', p_id, 'expected_updated_at', p_expected_updated_at,
    'ativo', p_ativo, 'reason', pg_catalog.btrim(COALESCE(p_reason, '')));
  v_replay := platform_private.catalog_entity_replay(v_actor, 'set_catalog_label_active', v_req, p_reason, p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  -- FOR UPDATE serializa com catalog_family_label_check (FOR KEY SHARE): ver comentário lá.
  SELECT * INTO v_op FROM public.catalog_family_labels WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_label_unavailable'; END IF;
  -- Revalida após a espera do lock de linha, antes do CAS/UPDATE.
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  IF v_op.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'catalog_label_conflict'; END IF;
  IF v_op.ativo IS NOT DISTINCT FROM p_ativo THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_no_change'; END IF;

  -- Inativação NÃO altera atribuições existentes em produtos; o trigger de
  -- validação só barra NOVAS atribuições de rótulo inativo.
  UPDATE public.catalog_family_labels SET ativo = p_ativo
   WHERE id = p_id AND updated_at = p_expected_updated_at
  RETURNING * INTO v_np;
  IF NOT FOUND OR v_np.updated_at IS NULL OR v_np.updated_at <= v_op.updated_at
     OR v_np.rotulo IS DISTINCT FROM v_op.rotulo OR v_np.familia IS DISTINCT FROM v_op.familia
     OR v_np.rotulo_exibicao IS DISTINCT FROM v_op.rotulo_exibicao THEN
    RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'catalog_label_confirmation_failed'; END IF;

  v_receipt := pg_catalog.jsonb_build_object('id', p_id, 'familia', v_np.familia, 'rotulo', v_np.rotulo,
    'ativo', p_ativo, 'updated_at', v_np.updated_at, 'idempotency_key', p_idempotency_key,
    'audit_id', v_audit, 'idempotent', false);
  PERFORM platform_private.catalog_entity_audit(v_actor, 'set_catalog_label_active', p_reason, p_idempotency_key,
    v_req, v_receipt,
    pg_catalog.jsonb_build_object('id', p_id, 'ativo', v_op.ativo, 'updated_at', v_op.updated_at),
    pg_catalog.jsonb_build_object('id', p_id, 'ativo', p_ativo, 'updated_at', v_np.updated_at));
  RETURN v_receipt;
END $function$

CREATE OR REPLACE FUNCTION public.fn_cockpit_norm_origem(p_origem text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v text := lower(btrim(coalesce(p_origem, '')));
BEGIN
  IF v IN ('manual', 'os', 'ordem_servico') THEN RETURN 'manual'; END IF;
  IF v IN ('onfarm', 'on_farm', 'ordem_servico_onfarm') THEN RETURN 'onfarm'; END IF;
  IF v = 'b2b' THEN RETURN 'b2b'; END IF;
  RAISE EXCEPTION 'COCKPIT_ORIGEM_INVALIDA';
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_guard_faturamento_v1(p_entrega_id uuid, p_total numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_r public.entrega_reconciliacoes%ROWTYPE;
  v_conf int;
  v_canon jsonb;
  v_max numeric;
  v_canon_valor numeric;
BEGIN
  SELECT count(*)::int INTO v_conf
    FROM public.entrega_conferencia_itens WHERE entrega_id = p_entrega_id;

  v_canon := public.fn_entrega_valor_faturavel_v1(p_entrega_id);

  -- H6C-001: condição comercial pendente/rejeitada/não vinculada bloqueia o
  -- faturamento em qualquer modo, inclusive o manual.
  IF (v_canon->>'origem') = 'bloqueado' THEN
    RAISE EXCEPTION 'condicao_b2b_bloqueada: %', COALESCE(v_canon->>'motivo','indefinido')
      USING ERRCODE='check_violation';
  END IF;

  v_canon_valor := NULLIF(v_canon->>'valor','')::numeric;

  IF v_conf = 0 THEN
    -- H6c-003: entrega integral também é comparada ao canônico, quando existir.
    IF v_canon_valor IS NOT NULL AND p_total IS NOT NULL
       AND abs(p_total - v_canon_valor) > 0.01 THEN
      RAISE EXCEPTION 'valor_divergente_do_canonico: informado=%, canonico=%',
        round(p_total,2), round(v_canon_valor,2) USING ERRCODE='check_violation';
    END IF;
    IF v_canon_valor IS NULL THEN
      -- sem fonte histórica confiável: fluxo legado/manual, o guard não arbitra preço.
      RETURN jsonb_build_object('modo','legado','ratio_aceito',1,'canonico',v_canon);
    END IF;
    RETURN jsonb_build_object('modo','integral_canonico','ratio_aceito',1,
                              'valor_faturavel_max', round(v_canon_valor,2),
                              'canonico', v_canon);
  END IF;

  SELECT * INTO v_r FROM public.entrega_reconciliacoes
   WHERE entrega_id = p_entrega_id AND status = 'reconciliada';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'entrega_nao_reconciliada: conclua a conferencia e a reconciliacao antes de faturar'
      USING ERRCODE='check_violation';
  END IF;
  IF NOT v_r.faturavel THEN
    RAISE EXCEPTION 'entrega_nao_faturavel: todos os itens foram recusados'
      USING ERRCODE='check_violation';
  END IF;

  v_max := COALESCE(v_r.valor_faturavel_max, v_canon_valor);
  IF v_max IS NOT NULL AND p_total > v_max + 0.01 THEN
    RAISE EXCEPTION 'valor_acima_do_aceito' USING ERRCODE='check_violation';
  END IF;

  RETURN jsonb_build_object('modo', 'reconciliado', 'reconciliacao_id', v_r.id,
                            'ratio_aceito', v_r.ratio_aceito,
                            'valor_faturavel_max', v_max, 'canonico', v_canon);
END
$function$

CREATE OR REPLACE FUNCTION public.org_onboarding_save(_dados jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_status text; v_clean jsonb;
BEGIN
  v_org := public._org_admin_org();
  IF v_org IS NULL THEN RAISE EXCEPTION 'org_forbidden: apenas administrador da empresa' USING errcode='42501'; END IF;
  v_clean := platform_private.onboarding_validar(_dados);
  SELECT status INTO v_status FROM public.organizations WHERE id = v_org FOR UPDATE;
  IF v_status NOT IN ('aguardando_ativacao','onboarding') THEN
    RAISE EXCEPTION 'org_invalid: empresa não está em onboarding'; END IF;
  IF v_status = 'aguardando_ativacao' THEN PERFORM public._org_set_status(v_org,'onboarding','início do onboarding'); END IF;
  PERFORM platform_private.issue_ticket('org_write', v_org);
  UPDATE public.organizations SET onboarding_dados = onboarding_dados || v_clean, updated_at = now() WHERE id = v_org;
END $function$

CREATE OR REPLACE FUNCTION public.org_onboarding_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; r record; v_plan text; v_admin boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'org_forbidden' USING errcode='42501'; END IF;
  SELECT organization_id INTO v_org FROM public.profiles WHERE user_id = auth.uid();
  IF v_org IS NULL THEN RETURN jsonb_build_object('required', false); END IF;
  SELECT id, status, nome, razao_social, nome_fantasia, cnpj, email_corporativo, fuso_horario, onboarding_dados
    INTO r FROM public.organizations WHERE id = v_org;
  v_admin := coalesce(public._org_admin_org() = v_org, false);
  IF NOT v_admin THEN
    RETURN jsonb_build_object('required', r.status IN ('aguardando_ativacao','onboarding','rascunho'),
      'blocked', r.status IN ('suspensa','cancelada'), 'is_admin', false, 'status', r.status);
  END IF;
  SELECT pl.name INTO v_plan FROM public.organization_subscriptions s JOIN public.saas_plans pl ON pl.id=s.plan_id
   WHERE s.organization_id=v_org AND s.status IN ('TRIAL','ACTIVE','PAST_DUE','SUSPENDED') LIMIT 1;
  RETURN jsonb_build_object(
    'required', r.status IN ('aguardando_ativacao','onboarding','rascunho'),
    'blocked', r.status IN ('suspensa','cancelada'), 'is_admin', true,
    'organization_id', r.id, 'status', r.status, 'nome', r.nome, 'razao_social', r.razao_social,
    'nome_fantasia', r.nome_fantasia, 'cnpj', r.cnpj, 'email_corporativo', r.email_corporativo,
    'fuso_horario', r.fuso_horario, 'dados', r.onboarding_dados, 'plano', v_plan);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_access_key_dv(_key43 text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d text := public.fn_fiscal_digits(_key43);
  s int := 0; i int; w int := 2; r int;
BEGIN
  IF length(d) <> 43 THEN
    RAISE EXCEPTION 'FISCAL_ACCESS_KEY_LENGTH: esperado 43 digitos antes do DV, recebido %', length(d);
  END IF;
  FOR i IN REVERSE 43..1 LOOP
    s := s + substr(d,i,1)::int * w;
    w := CASE WHEN w = 9 THEN 2 ELSE w + 1 END;
  END LOOP;
  r := 11 - (s % 11);
  RETURN CASE WHEN r >= 10 THEN 0 ELSE r END;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_apply_tax_v2(r fiscal_tax_rules, _ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  base_raw numeric; base_eff numeric; val numeric := 0;
  extra jsonb := '{}'::jsonb;
  icms_own numeric; base_st numeric; v_st numeric;
  v_mode text; v_src text; v_red numeric; v_manual numeric;
  v_manual_by text; v_manual_at text; v_manual_reason text;
  r_int numeric; r_inter numeric; share numeric;
  v_difal_dest numeric; v_difal_orig numeric; v_fcp numeric;
BEGIN
  IF r.tax_kind IN ('IBS','CBS','IS') THEN
    RAISE EXCEPTION 'FISCAL_RTC_ENGINE_UNAVAILABLE: IBS/CBS/IS permanecem em scaffolding bloqueado ate regra e leiaute oficiais.'
      USING HINT = 'Nao simule tributos da reforma como se fossem vigentes.';
  END IF;

  base_raw := public.fn_fiscal_item_base(r.base_components, _ctx);
  IF base_raw < 0 THEN
    RAISE EXCEPTION 'FISCAL_TAX_BASE_NEGATIVE: base negativa para tributo %.', r.tax_kind;
  END IF;
  -- Resolucao canonica do percentual de reducao da base (NONE / FIXED / MANUAL).
  v_mode := coalesce(r.base_reduction_mode,'NONE');
  v_manual := nullif(btrim(coalesce(_ctx->>'manualBaseReductionPct','')),'')::numeric;
  v_manual_by := nullif(btrim(coalesce(_ctx->>'manualBy','')),'');
  v_manual_at := nullif(btrim(coalesce(_ctx->>'manualAt','')),'');
  v_manual_reason := nullif(btrim(coalesce(_ctx->>'manualReason','')),'');

  IF v_mode = 'MANUAL' THEN
    IF v_manual IS NULL THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_INPUT_REQUIRED: tributo % exige percentual de reducao informado na preparacao.', r.tax_kind;
    END IF;
    IF v_manual < 0 OR v_manual > 100 THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_OUT_OF_RANGE: percentual de reducao % invalido para %; use 0 a 100.', v_manual, r.tax_kind;
    END IF;
    IF v_manual_reason IS NULL THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_REASON_REQUIRED: informe o motivo da reducao manual da base de calculo (%).', r.tax_kind;
    END IF;
    v_red := v_manual;
    v_src := 'MANUAL';
  ELSIF v_mode = 'FIXED' THEN
    IF v_manual IS NOT NULL THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_NOT_EDITABLE: regra % define reducao fixa; percentual manual nao e aceito.', r.rule_key;
    END IF;
    v_red := coalesce(r.base_reduction_pct,0);
    v_src := 'FIXED';
  ELSE
    IF v_manual IS NOT NULL THEN
      RAISE EXCEPTION 'FISCAL_BASE_REDUCTION_NOT_ALLOWED: regra % nao admite reducao da base de calculo.', r.rule_key;
    END IF;
    v_red := 0;
    v_src := 'NONE';
  END IF;

  base_eff := public.fn_fiscal_round(base_raw * (1 - v_red/100));

  IF r.calc_mode IN ('EXEMPT_DOCUMENTED','NOT_TAXED_DOCUMENTED','SUSPENDED_DOCUMENTED') THEN
    -- Modo documentado: preserva base/CST/motivo; nao apaga informacao exigida no leiaute.
    IF nullif(btrim(coalesce(r.justification,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.legal_basis,'')),'') IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: modo % exige motivo e base legal documentados.', r.calc_mode;
    END IF;
    val := 0;
    extra := extra || jsonb_build_object('documentedMode', r.calc_mode, 'taxedBase', base_eff);

  ELSIF r.calc_mode = 'DEFERRED_DOCUMENTED' THEN
    -- Diferimento: exige percentual, motivo e base legal; valor diferido explicitado.
    IF nullif(btrim(coalesce(r.justification,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.legal_basis,'')),'') IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: diferimento exige motivo e base legal documentados.';
    END IF;
    IF r.rate IS NULL OR r.deferral_pct IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: diferimento exige aliquota e deferral_pct.';
    END IF;
    val := public.fn_fiscal_round(base_eff * r.rate / 100);
    extra := extra || jsonb_build_object('documentedMode', r.calc_mode,
      'deferralPct', r.deferral_pct,
      'deferredValue', public.fn_fiscal_round(val * r.deferral_pct / 100));
    val := public.fn_fiscal_round(val * (1 - r.deferral_pct/100));

  ELSIF r.calc_mode <> 'PERCENT' THEN
    RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: calc_mode % nao suportado pelo motor F3.', r.calc_mode;

  ELSIF r.tax_kind IN ('ICMS','PIS','COFINS','IPI','ISS') THEN
    IF r.rate IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: aliquota ausente para tributo %.', r.tax_kind;
    END IF;
    val := public.fn_fiscal_round(base_eff * r.rate / 100);
    IF coalesce(r.deferral_pct,0) > 0 THEN
      extra := extra || jsonb_build_object('deferredValue',
        public.fn_fiscal_round(val * r.deferral_pct / 100));
      val := public.fn_fiscal_round(val * (1 - r.deferral_pct/100));
    END IF;

  ELSIF r.tax_kind = 'ICMS_ST' THEN
    IF coalesce(r.st_modality,'MVA') <> 'MVA' THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: modalidade de BC ST % nao implementada nesta fase.', r.st_modality;
    END IF;
    IF r.mva_pct IS NULL OR r.internal_rate_pct IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: ICMS-ST exige mva_pct e internal_rate_pct.';
    END IF;
    icms_own := coalesce((_ctx->>'icmsOwnValue')::numeric, 0);
    base_st := public.fn_fiscal_round(base_eff * (1 + r.mva_pct/100));
    v_st := public.fn_fiscal_round(base_st * r.internal_rate_pct / 100);
    IF coalesce(r.credit_own_icms,true) THEN
      v_st := public.fn_fiscal_round(v_st - icms_own);
    END IF;
    IF v_st < 0 THEN v_st := 0; END IF;
    val := v_st;
    extra := extra || jsonb_build_object('modBCST', r.st_modality, 'baseST', base_st,
      'internalRatePct', r.internal_rate_pct, 'mvaPct', r.mva_pct,
      'creditedOwnIcms', coalesce(r.credit_own_icms,true), 'ownIcmsValue', icms_own);

  ELSIF r.tax_kind IN ('FCP','FCP_ST') THEN
    IF r.fcp_rate IS NULL AND r.fcp_st_rate IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: FCP exige aliquota propria (fcp_rate/fcp_st_rate).';
    END IF;
    IF r.tax_kind = 'FCP' THEN
      IF r.fcp_rate IS NULL THEN
        RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: FCP exige fcp_rate.';
      END IF;
      val := public.fn_fiscal_round(base_eff * r.fcp_rate / 100);
      extra := extra || jsonb_build_object('fcpBase', base_eff, 'fcpRate', r.fcp_rate);
    ELSE
      IF r.fcp_st_rate IS NULL THEN
        RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: FCP-ST exige fcp_st_rate.';
      END IF;
      base_st := coalesce((_ctx->>'baseST')::numeric, null);
      IF base_st IS NULL THEN
        RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: FCP-ST exige base de ST previamente apurada.';
      END IF;
      val := public.fn_fiscal_round(base_st * r.fcp_st_rate / 100);
      extra := extra || jsonb_build_object('fcpStBase', base_st, 'fcpStRate', r.fcp_st_rate);
    END IF;

  ELSIF r.tax_kind = 'DIFAL' THEN
    r_int := r.internal_rate_pct; r_inter := r.interstate_rate_pct;
    share := r.difal_dest_share_pct;
    IF r_int IS NULL OR r_inter IS NULL OR share IS NULL THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: DIFAL exige internal_rate_pct, interstate_rate_pct e difal_dest_share_pct.';
    END IF;
    IF r_int < r_inter THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: aliquota interna do destino menor que a interestadual; parametros incoerentes.';
    END IF;
    val := public.fn_fiscal_round(base_eff * (r_int - r_inter) / 100);
    v_difal_dest := public.fn_fiscal_round(val * share / 100);
    v_difal_orig := public.fn_fiscal_round(val - v_difal_dest);
    v_fcp := CASE WHEN r.fcp_rate IS NULL THEN NULL
                  ELSE public.fn_fiscal_round(base_eff * r.fcp_rate / 100) END;
    extra := extra || jsonb_build_object(
      'internalRatePct', r_int, 'interstateRatePct', r_inter,
      'destSharePct', share, 'valueDestination', v_difal_dest,
      'valueOrigin', v_difal_orig, 'fcpValue', v_fcp);

  ELSE
    RAISE EXCEPTION 'FISCAL_TAX_KIND_UNSUPPORTED: tributo % sem formula canonica implementada.', r.tax_kind;
  END IF;

  RETURN jsonb_build_object(
    'taxKind', r.tax_kind, 'calcMode', r.calc_mode, 'formula', 'F3.4/'||r.tax_kind,
    'ruleId', r.id, 'ruleKey', r.rule_key, 'ruleVersion', r.version,
    'sourceId', r.source_id, 'legalBasis', r.legal_basis, 'legalVersion', r.legal_version,
    'justification', r.justification,
    'cst', r.cst, 'csosn', r.csosn, 'crt', r.crt,
    'rate', r.rate, 'baseReductionPct', v_red, 'deferralPct', r.deferral_pct,
    'baseReductionMode', v_mode, 'baseReductionSource', v_src,
    'baseReductionRulePct', r.base_reduction_pct,
    'baseReductionAppliedBy', CASE WHEN v_src = 'MANUAL' THEN v_manual_by ELSE NULL END,
    'baseReductionAppliedAt', CASE WHEN v_src = 'MANUAL' THEN v_manual_at ELSE NULL END,
    'baseReductionReason', CASE WHEN v_src = 'MANUAL' THEN v_manual_reason ELSE NULL END,
    'baseComponents', r.base_components,
    'baseOriginal', base_raw, 'base', base_eff, 'value', val,
    'params', extra);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_cnpj_is_valid(_v text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d text := public.fn_fiscal_digits(_v);
  w1 int[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
  w2 int[] := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
  s int := 0; i int; dv1 int; dv2 int;
BEGIN
  IF length(d) <> 14 THEN RETURN false; END IF;
  IF d ~ ('^(' || substr(d,1,1) || '){14}$') THEN RETURN false; END IF;
  FOR i IN 1..12 LOOP s := s + substr(d,i,1)::int * w1[i]; END LOOP;
  dv1 := s % 11; dv1 := CASE WHEN dv1 < 2 THEN 0 ELSE 11 - dv1 END;
  IF dv1 <> substr(d,13,1)::int THEN RETURN false; END IF;
  s := 0;
  FOR i IN 1..13 LOOP s := s + substr(d,i,1)::int * w2[i]; END LOOP;
  dv2 := s % 11; dv2 := CASE WHEN dv2 < 2 THEN 0 ELSE 11 - dv2 END;
  RETURN dv2 = substr(d,14,1)::int;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_cpf_is_valid(_v text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d text := public.fn_fiscal_digits(_v);
  s int := 0; i int; dv1 int; dv2 int;
BEGIN
  IF length(d) <> 11 THEN RETURN false; END IF;
  IF d ~ ('^(' || substr(d,1,1) || '){11}$') THEN RETURN false; END IF;
  FOR i IN 1..9 LOOP s := s + substr(d,i,1)::int * (11 - i); END LOOP;
  dv1 := (s * 10) % 11; IF dv1 = 10 THEN dv1 := 0; END IF;
  IF dv1 <> substr(d,10,1)::int THEN RETURN false; END IF;
  s := 0;
  FOR i IN 1..10 LOOP s := s + substr(d,i,1)::int * (12 - i); END LOOP;
  dv2 := (s * 10) % 11; IF dv2 = 10 THEN dv2 := 0; END IF;
  RETURN dv2 = substr(d,11,1)::int;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_ie_check(_uf text, _ie text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  uf text := upper(btrim(coalesce(_uf,'')));
  raw text := upper(btrim(coalesce(_ie,'')));
  d text; len int; s int := 0; i int; dv int; w int;
BEGIN
  IF raw = '' THEN RETURN 'MISSING'; END IF;
  IF raw IN ('ISENTO','ISENTA') THEN RETURN 'ISENTO'; END IF;
  IF public.fn_fiscal_uf_ibge_code(uf) IS NULL THEN RETURN 'INVALID_UF'; END IF;
  d := public.fn_fiscal_digits(raw);
  len := length(d);

  IF (uf = 'AC' AND len <> 13)
  OR (uf = 'AL' AND len <> 9) OR (uf = 'AM' AND len <> 9)
  OR (uf = 'AP' AND len <> 9) OR (uf = 'BA' AND len NOT IN (8,9))
  OR (uf = 'CE' AND len <> 9) OR (uf = 'DF' AND len <> 13)
  OR (uf = 'ES' AND len <> 9) OR (uf = 'GO' AND len <> 9)
  OR (uf = 'MA' AND len <> 9) OR (uf = 'MG' AND len <> 13)
  OR (uf = 'MS' AND len <> 9) OR (uf = 'MT' AND len <> 11)
  OR (uf = 'PA' AND len <> 9) OR (uf = 'PB' AND len <> 9)
  OR (uf = 'PE' AND len NOT IN (9,14)) OR (uf = 'PI' AND len <> 9)
  OR (uf = 'PR' AND len <> 10) OR (uf = 'RJ' AND len <> 8)
  OR (uf = 'RN' AND len NOT IN (9,10)) OR (uf = 'RO' AND len <> 14)
  OR (uf = 'RR' AND len <> 9) OR (uf = 'RS' AND len <> 10)
  OR (uf = 'SC' AND len <> 9) OR (uf = 'SE' AND len <> 9)
  OR (uf = 'SP' AND len NOT IN (12,13)) OR (uf = 'TO' AND len <> 9)
  THEN
    RETURN 'INVALID_LENGTH';
  END IF;

  -- Dígito verificador: subconjunto com algoritmo público e estável.
  IF uf = 'GO' THEN
    IF substr(d,1,2) NOT IN ('10','11','15') THEN RETURN 'INVALID_FORMAT'; END IF;
    s := 0;
    FOR i IN 1..8 LOOP s := s + substr(d,i,1)::int * (10 - i); END LOOP;
    dv := s % 11;
    dv := CASE WHEN dv = 0 THEN 0 WHEN dv = 1 THEN 1 ELSE 11 - dv END;
    RETURN CASE WHEN dv = substr(d,9,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  ELSIF uf = 'RJ' THEN
    s := 0; w := 2;
    FOR i IN 1..7 LOOP
      s := s + substr(d,i,1)::int * w;
      w := CASE WHEN w = 7 THEN 2 ELSE w + 1 END;
    END LOOP;
    dv := 11 - (s % 11); IF dv >= 10 THEN dv := 0; END IF;
    RETURN CASE WHEN dv = substr(d,8,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  ELSIF uf = 'SC' THEN
    s := 0;
    FOR i IN 1..8 LOOP s := s + substr(d,i,1)::int * (10 - i); END LOOP;
    dv := 11 - (s % 11); IF dv >= 10 THEN dv := 0; END IF;
    RETURN CASE WHEN dv = substr(d,9,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  END IF;

  RETURN 'VALID_LENGTH_DV_NOT_IMPLEMENTED';
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_item_profile_gate_eval(p_scope text, p_crt text, p_is_active boolean, p_profile_status text, p_accounting_validated_at timestamp with time zone, p_accounting_notes text, p_fiscal_description text, p_commercial_unit text, p_taxable_unit text, p_ncm text, p_origin_code text, p_cfop_in_state text, p_cfop_interstate text, p_icms_cst text, p_icms_csosn text, p_pis_cst text, p_cofins_cst text, p_regulatory jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_p jsonb := '[]'::jsonb;   -- pendências técnicas
  v_reg jsonb := '[]'::jsonb; -- pendências regulatórias
  v_na jsonb := '[]'::jsonb;  -- itens declarados NÃO APLICÁVEIS (com justificativa)
  v_notes text := lower(coalesce(p_accounting_notes, ''));
  v_synthetic boolean;
  v_technical_ready boolean;
  v_regulatory_ready boolean;
  v_has_cst boolean := nullif(btrim(coalesce(p_icms_cst,'')),'') IS NOT NULL;
  v_has_csosn boolean := nullif(btrim(coalesce(p_icms_csosn,'')),'') IS NOT NULL;
  v_pend_count int;
BEGIN
  -- ---------------- Camada REGULATÓRIA (Fase F2) ----------------
  -- Exigida apenas onde o dossiê existe como conceito: microrganismos.
  IF p_scope <> 'MICROORGANISM' THEN
    v_reg := '[]'::jsonb;
  ELSIF p_regulatory IS NULL OR p_regulatory = 'null'::jsonb THEN
    v_reg := jsonb_build_array(jsonb_build_object(
      'code','REGULATORY_DOSSIER_MISSING','field','microorganism_regulatory_dossiers','layer','REGULATORY',
      'message','Sem dossie regulatorio cadastrado para o item.'));
  ELSE
    v_na := coalesce(p_regulatory->'checklist_not_applicable','[]'::jsonb);

    IF coalesce(p_regulatory->>'status','') = 'BLOCKED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_DOSSIER_BLOCKED','field','status','layer','REGULATORY',
        'message', coalesce(p_regulatory->>'blocked_reason','Dossie regulatorio bloqueado.')));
    ELSIF coalesce(p_regulatory->>'status','') <> 'VALIDATED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_DOSSIER_NOT_PUBLISHED','field','status','layer','REGULATORY',
        'message','Dossie regulatorio em '||coalesce(p_regulatory->>'status','?')||'; exigido VALIDATED.'));
    END IF;

    IF p_regulatory->>'regulatory_category' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_CATEGORY_MISSING','field','regulatory_category','layer','REGULATORY',
        'message','Finalidade/categoria regulatoria nao definida (nao pode ser presumida pela especie).'));
    END IF;
    IF p_regulatory->>'strain' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_STRAIN_MISSING','field','strain_code','layer','REGULATORY',
        'message','Cepa/estirpe nao informada.'));
    END IF;
    IF p_regulatory->>'formulation' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_FORMULATION_MISSING','field','formulation','layer','REGULATORY',
        'message','Formulacao/apresentacao nao informada.'));
    END IF;
    IF p_regulatory->>'label_guarantee' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_LABEL_GUARANTEE_MISSING','field','label_guarantee','layer','REGULATORY',
        'message','Composicao/garantia de rotulo nao informada.'));
    END IF;

    -- MAPA: MISSING x NOT_APPLICABLE justificado x vencido
    IF coalesce(p_regulatory->>'mapa_status','') = 'NOT_APPLICABLE' THEN
      v_na := v_na || jsonb_build_array(jsonb_build_object(
        'item_key','REGISTRO_MAPA','justification', p_regulatory->>'mapa_not_applicable_reason'));
    ELSIF p_regulatory->>'mapa_registration_number' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_MAPA_REGISTRATION_MISSING','field','mapa_registration_number','layer','REGULATORY',
        'message','Registro MAPA/SIPEAGRO ausente e sem declaracao justificada de nao aplicabilidade.'));
    ELSIF coalesce(p_regulatory->>'mapa_status','') IN ('EXPIRED','SUSPENDED') THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_MAPA_REGISTRATION_INVALID','field','mapa_status','layer','REGULATORY',
        'message','Registro MAPA em situacao '||(p_regulatory->>'mapa_status')||'.'));
    ELSIF (p_regulatory->>'mapa_valid_until') IS NOT NULL
          AND (p_regulatory->>'mapa_valid_until')::date < current_date THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_MAPA_REGISTRATION_INVALID','field','mapa_valid_until','layer','REGULATORY',
        'message','Registro MAPA com validade expirada.'));
    END IF;
    IF p_regulatory->>'mapa_holder' IS NULL AND coalesce(p_regulatory->>'mapa_status','') <> 'NOT_APPLICABLE' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_HOLDER_MISSING','field','mapa_holder','layer','REGULATORY',
        'message','Titular/fabricante do registro nao informado.'));
    END IF;

    -- Documentos de evidência
    IF coalesce((p_regulatory->>'has_label_document')::boolean,false) IS NOT TRUE THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_LABEL_DOCUMENT_MISSING','field','documents','layer','REGULATORY',
        'message','Rotulo nao anexado ao dossie.'));
    END IF;
    IF coalesce((p_regulatory->>'has_report_document')::boolean,false) IS NOT TRUE THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_REPORT_DOCUMENT_MISSING','field','documents','layer','REGULATORY',
        'message','Laudo/certificado de analise nao anexado ao dossie.'));
    END IF;
    IF coalesce((p_regulatory->>'expired_documents')::int,0) > 0 THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_DOCUMENT_EXPIRED','field','documents','layer','REGULATORY',
        'message',(p_regulatory->>'expired_documents')||' documento(s) com validade expirada.'));
    END IF;

    -- Aprovações separadas
    IF coalesce(p_regulatory->>'review_technical','PENDING') <> 'APPROVED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_TECHNICAL_APPROVAL_MISSING','field','technical_review_status','layer','REGULATORY',
        'message','Revisao tecnica nao aprovada.'));
    END IF;
    IF coalesce(p_regulatory->>'review_regulatory','PENDING') <> 'APPROVED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_RESPONSIBLE_APPROVAL_MISSING','field','regulatory_review_status','layer','REGULATORY',
        'message','Revisao do responsavel tecnico (regulatoria) nao aprovada.'));
    END IF;
    IF coalesce(p_regulatory->>'review_fiscal','PENDING') <> 'APPROVED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_FISCAL_APPROVAL_MISSING','field','fiscal_review_status','layer','REGULATORY',
        'message','Revisao contabil/fiscal nao aprovada.'));
    END IF;

    -- Checklist
    v_pend_count := jsonb_array_length(coalesce(p_regulatory->'checklist_pending','[]'::jsonb));
    IF v_pend_count > 0 THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_CHECKLIST_INCOMPLETE','field','checklist','layer','REGULATORY',
        'message', v_pend_count||' item(ns) de checklist pendente(s).',
        'items', p_regulatory->'checklist_pending'));
    END IF;

    -- NCM aprovado e coerente com o perfil fiscal
    IF coalesce((p_regulatory->>'ncm_approved')::boolean,false) IS NOT TRUE THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_NCM_NOT_APPROVED','field','microorganism_ncm_candidates','layer','REGULATORY',
        'message','Nenhum candidato de NCM aprovado; sugestao nunca vale como codigo aprovado.'));
    ELSIF nullif(btrim(coalesce(p_ncm,'')),'') IS NOT NULL
          AND p_regulatory->>'published_ncm' IS NOT NULL
          AND p_regulatory->>'published_ncm' <> btrim(p_ncm) THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_NCM_DIVERGES_FROM_PROFILE','field','ncm','layer','REGULATORY',
        'message','NCM do perfil fiscal diverge do NCM publicado no dossie.'));
    END IF;

    -- Apresentações: unidades e GTIN exigem confirmação explícita
    IF coalesce((p_regulatory->>'presentations_total')::int,0) = 0 THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_PRESENTATION_MISSING','field','presentations','layer','REGULATORY',
        'message','Nenhuma apresentacao cadastrada.'));
    ELSE
      IF coalesce((p_regulatory->>'presentations_units_unconfirmed')::int,0) > 0 THEN
        v_reg := v_reg || jsonb_build_array(jsonb_build_object(
          'code','REGULATORY_UNITS_NOT_CONFIRMED','field','presentations.units','layer','REGULATORY',
          'message',(p_regulatory->>'presentations_units_unconfirmed')||' apresentacao(oes) sem uCom/uTrib/fator confirmados.'));
      END IF;
      IF coalesce((p_regulatory->>'presentations_gtin_unconfirmed')::int,0) > 0 THEN
        v_reg := v_reg || jsonb_build_array(jsonb_build_object(
          'code','REGULATORY_GTIN_NOT_DECLARED','field','presentations.gtin','layer','REGULATORY',
          'message',(p_regulatory->>'presentations_gtin_unconfirmed')||' apresentacao(oes) sem GTIN confirmado nem declaracao SEM GTIN.'));
      END IF;
    END IF;
  END IF;

  -- ---------------- Camada TÉCNICA (Fase F1, inalterada) ----------------
  IF p_profile_status IS NULL THEN
    RETURN jsonb_build_object(
      'scope', p_scope, 'ready', false, 'technical_ready', false, 'regulatory_ready', false,
      'status', 'NOT_READY', 'quarantined', false, 'profile_present', false,
      'not_applicable', v_na,
      'pendencies', jsonb_build_array(jsonb_build_object(
        'code','PROFILE_MISSING','field','profile_status','layer','TECHNICAL',
        'message','Item sem perfil fiscal cadastrado.')) || v_reg);
  END IF;

  v_synthetic := v_notes LIKE '%sintetic%'
              OR v_notes LIKE '%sintétic%'
              OR v_notes LIKE '%homologacao%'
              OR v_notes LIKE '%homologação%'
              OR v_notes LIKE '%hml-b2b%'
              OR v_notes LIKE '%test_only%'
              OR v_notes LIKE '%quarentena%';

  IF coalesce(p_is_active, false) IS NOT TRUE THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','PROFILE_INACTIVE','field','is_active','layer','TECHNICAL','message','Perfil fiscal inativo.'));
  END IF;

  IF p_profile_status = 'BLOCKED' THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','PROFILE_QUARANTINED','field','profile_status','layer','TECHNICAL',
      'message','Perfil fiscal em quarentena (BLOCKED).'));
  ELSIF p_profile_status <> 'VALIDATED' THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','PROFILE_NOT_PUBLISHED','field','profile_status','layer','TECHNICAL',
      'message','Perfil fiscal nao publicado (exigido VALIDATED).'));
  END IF;

  IF p_accounting_validated_at IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','ACCOUNTING_NOT_VALIDATED','field','accounting_validated_at','layer','TECHNICAL',
      'message','Sem validacao contabil preliminar registrada.'));
  END IF;

  IF v_synthetic THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','PROFILE_SYNTHETIC','field','accounting_notes','layer','TECHNICAL',
      'message','Classificacao sintetica de homologacao; nao utilizavel em faturamento.'));
  END IF;

  IF nullif(btrim(coalesce(p_fiscal_description,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_FISCAL_DESCRIPTION','field','fiscal_description','layer','TECHNICAL','message','Descricao fiscal ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_commercial_unit,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_COMMERCIAL_UNIT','field','commercial_unit','layer','TECHNICAL','message','Unidade comercial ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_taxable_unit,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_TAXABLE_UNIT','field','taxable_unit','layer','TECHNICAL','message','Unidade tributavel ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_ncm,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_NCM','field','ncm','layer','TECHNICAL','message','NCM ausente.'));
  ELSIF p_accounting_validated_at IS NULL OR v_synthetic THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','NCM_NOT_ACCOUNTING_REVIEWED','field','ncm','layer','TECHNICAL',
      'message','NCM sem revisao contabil preliminar (validacao contabil ausente ou perfil sintetico). Nao afirma nem substitui evidencia regulatoria.'));
  END IF;
  IF nullif(btrim(coalesce(p_origin_code,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_ORIGIN_CODE','field','origin_code','layer','TECHNICAL','message','Codigo de origem ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_cfop_in_state,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_CFOP_IN_STATE','field','cfop_in_state','layer','TECHNICAL','message','CFOP interno ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_cfop_interstate,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_CFOP_INTERSTATE','field','cfop_interstate','layer','TECHNICAL','message','CFOP interestadual ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_pis_cst,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_PIS_CST','field','pis_cst','layer','TECHNICAL','message','CST de PIS ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_cofins_cst,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_COFINS_CST','field','cofins_cst','layer','TECHNICAL','message','CST de COFINS ausente.'));
  END IF;

  IF v_has_cst AND v_has_csosn THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','CST_AND_CSOSN_CONFLICT','field','icms_cst,icms_csosn','layer','TECHNICAL',
      'message','CST e CSOSN preenchidos simultaneamente; mutuamente exclusivos.'));
  END IF;

  IF nullif(btrim(coalesce(p_crt,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','TAX_REGIME_UNKNOWN','field','company_fiscal_settings.crt','layer','TECHNICAL',
      'message','CRT do emitente nao configurado.'));
  ELSIF p_crt = '3' THEN
    IF v_has_csosn THEN
      v_p := v_p || jsonb_build_array(jsonb_build_object(
        'code','CSOSN_NOT_ALLOWED_FOR_CRT3','field','icms_csosn','layer','TECHNICAL',
        'message','CSOSN e exclusivo do Simples Nacional; emitente em CRT 3 (Regime Normal).'));
    END IF;
    IF NOT v_has_cst THEN
      v_p := v_p || jsonb_build_array(jsonb_build_object(
        'code','CST_REQUIRED_FOR_CRT3','field','icms_cst','layer','TECHNICAL',
        'message','CST de ICMS obrigatorio para CRT 3.'));
    END IF;
  ELSIF p_crt IN ('1','2') THEN
    IF v_has_cst THEN
      v_p := v_p || jsonb_build_array(jsonb_build_object(
        'code','CST_NOT_ALLOWED_FOR_SIMPLES','field','icms_cst','layer','TECHNICAL',
        'message','CST de ICMS nao se aplica a emitente do Simples Nacional.'));
    END IF;
    IF NOT v_has_csosn THEN
      v_p := v_p || jsonb_build_array(jsonb_build_object(
        'code','CSOSN_REQUIRED_FOR_SIMPLES','field','icms_csosn','layer','TECHNICAL',
        'message','CSOSN obrigatorio para CRT 1/2.'));
    END IF;
  ELSE
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','TAX_REGIME_UNKNOWN','field','company_fiscal_settings.crt','layer','TECHNICAL',
      'message','CRT do emitente com valor nao reconhecido.'));
  END IF;

  v_technical_ready := (jsonb_array_length(v_p) = 0);
  v_regulatory_ready := (jsonb_array_length(v_reg) = 0);

  RETURN jsonb_build_object(
    'scope', p_scope,
    'ready', (v_technical_ready AND v_regulatory_ready),
    'technical_ready', v_technical_ready,
    'regulatory_ready', v_regulatory_ready,
    'status', CASE WHEN (v_technical_ready AND v_regulatory_ready) THEN 'READY' ELSE 'NOT_READY' END,
    'quarantined', (p_profile_status = 'BLOCKED'),
    'profile_present', true,
    'not_applicable', v_na,
    'pendencies', v_p || v_reg);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_invoice_eligibility(_source_type text, _source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  reasons jsonb := '[]'::jsonb;
  po public.partner_orders%ROWTYPE;
  ent public.entregas%ROWTYPE;
  st text;
  v_order_id uuid;
  v_debtor uuid;
  n_items int := 0; n_quote int := 0; n_no_snapshot int := 0;
  canceled boolean := false;
  allowed text[];
BEGIN
  PERFORM public.h15_require_staff();

  IF _source_type IS NULL OR _source_id IS NULL THEN
    RETURN jsonb_build_object('eligible', false, 'reasons',
      jsonb_build_array(jsonb_build_object('code','FISCAL_SOURCE_MISSING','severity','BLOCK',
        'message','Origem fiscal (pedido/entrega) obrigatoria.')));
  END IF;

  IF _source_type = 'PARTNER_ORDER' THEN
    SELECT * INTO po FROM public.partner_orders WHERE id = _source_id;
    IF NOT FOUND THEN
      reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_NOT_FOUND','severity','BLOCK','message','Pedido inexistente.');
    ELSE
      v_order_id := po.id;
      st := po.status::text;
      allowed := public.fn_fiscal_billing_allowed_order_status();

      IF st = 'cancelado' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_CANCELED','severity','BLOCK','message','Pedido cancelado; emissao bloqueada.');
      ELSIF st IN ('reprovado','reprovado_sem_itens') THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_REJECTED','severity','BLOCK','message','Pedido reprovado; emissao bloqueada.');
      ELSIF st = 'aguardando_cotacao' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_QUOTE_PENDING','severity','BLOCK','message','Pedido aguardando cotacao; emissao bloqueada.');
      ELSIF st = 'faturado' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_ALREADY_INVOICED','severity','BLOCK','message','Pedido ja faturado.');
      ELSIF NOT (st = ANY (allowed)) THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_STATUS_NOT_BILLABLE','severity','BLOCK',
          'message','Status do pedido nao habilitado para faturamento: '||st);
      END IF;

      -- Aprovacao comercial obrigatoria.
      IF po.approved_at IS NULL OR po.approved_by IS NULL THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_COMMERCIAL_APPROVAL_MISSING','severity','BLOCK',
          'message','Pedido sem aprovacao comercial registrada.');
      END IF;

      -- Aprovacao financeira quando exigida.
      IF coalesce(po.requires_financial_approval,false)
         AND coalesce(po.financial_approval_status,'pending') <> 'approved' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_FINANCIAL_APPROVAL_MISSING','severity','BLOCK',
          'message','Pedido exige aprovacao financeira e ela nao foi concedida.');
      END IF;

      -- Condicao de pagamento aceita/definida.
      IF coalesce(po.payment_condition_status,'') NOT IN ('defined','accepted','aceita') THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_PAYMENT_CONDITION_NOT_ACCEPTED','severity','BLOCK',
          'message','Condicao de pagamento nao aceita/definida.');
      END IF;

      -- Devedor correto: parceiro B2B, nunca o produtor final vinculado.
      IF po.partner_id IS NULL THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DEBTOR_UNRESOLVED','severity','BLOCK',
          'message','Parceiro devedor do pedido nao identificado.');
      ELSE
        v_debtor := po.partner_id;
      END IF;

      -- Snapshot de preco/condicao e ausencia de itens sob consulta.
      SELECT count(*),
             count(*) FILTER (WHERE coalesce(pricing_mode_snapshot,'') = 'quote_only'),
             count(*) FILTER (WHERE preco_unitario_final_snapshot IS NULL
                                 OR price_source_snapshot IS NULL)
        INTO n_items, n_quote, n_no_snapshot
        FROM public.partner_order_items WHERE order_id = _source_id;

      IF n_items = 0 THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_NO_ITEMS','severity','BLOCK','message','Pedido sem itens.');
      END IF;
      IF n_quote > 0 THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_QUOTE_ONLY_BLOCKED','severity','BLOCK',
          'message','Pedido possui itens sob consulta (quote_only); emissao bloqueada sem efeito colateral.');
      END IF;
      IF n_no_snapshot > 0 THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_PRICE_SNAPSHOT_MISSING','severity','BLOCK',
          'message','Itens sem snapshot de preco/condicao comercial.');
      END IF;
    END IF;

  ELSIF _source_type = 'ENTREGA' THEN
    SELECT * INTO ent FROM public.entregas WHERE id = _source_id;
    IF NOT FOUND THEN
      reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_NOT_FOUND','severity','BLOCK','message','Entrega inexistente.');
    ELSE
      IF ent.cancelada_em IS NOT NULL OR coalesce(ent.status,'') = 'cancelada'
         OR coalesce(ent.financial_status,'') = 'CANCELED' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_CANCELED','severity','BLOCK','message','Entrega cancelada.');
      END IF;
      IF NOT (coalesce(ent.status,'') = ANY (public.fn_fiscal_billing_allowed_delivery_status())) THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_NOT_COMPLETED','severity','BLOCK',
          'message','Entrega nao concluida/aceita. Status atual: '||coalesce(ent.status,'-'));
      END IF;
      IF ent.recebimento_confirmado_em IS NULL AND ent.confirmada_em IS NULL AND ent.entregue_em IS NULL THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_RECEIPT_MISSING','severity','BLOCK',
          'message','Entrega sem aceite/recebimento registrado.');
      END IF;
      IF ent.partner_order_id IS NULL THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_ORDER_LINK_MISSING','severity','BLOCK',
          'message','Entrega sem vinculo inequivoco a pedido B2B.');
      ELSE
        v_order_id := ent.partner_order_id;
        SELECT partner_id, status::text INTO v_debtor, st FROM public.partner_orders WHERE id = ent.partner_order_id;
        IF v_debtor IS NULL THEN
          reasons := reasons || jsonb_build_object('code','FISCAL_DEBTOR_UNRESOLVED','severity','BLOCK',
            'message','Parceiro devedor da entrega nao identificado.');
        END IF;
        IF st IS NULL OR NOT (st = ANY (public.fn_fiscal_billing_allowed_order_status())) THEN
          reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_STATUS_NOT_BILLABLE','severity','BLOCK',
            'message','Pedido vinculado a entrega nao esta habilitado para faturamento: '||coalesce(st,'-'));
        END IF;
      END IF;
    END IF;

  ELSE
    reasons := reasons || jsonb_build_object('code','FISCAL_SOURCE_TYPE_UNSUPPORTED','severity','BLOCK',
      'message','Escopo fiscal nao suportado nesta fase: '||_source_type);
  END IF;

  -- Duplicidade fiscal: documento vivo para a mesma origem.
  IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi
             WHERE fi.source_type = _source_type AND fi.source_id = _source_id
               AND fi.document_model = 'NFE'
               AND fi.status NOT IN ('CANCELED','REJECTED')
               AND fi.access_key IS NOT NULL) THEN
    reasons := reasons || jsonb_build_object('code','FISCAL_DUPLICATE_DOCUMENT','severity','BLOCK',
      'message','Ja existe documento fiscal vigente para esta origem.');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi
    WHERE fi.source_type = _source_type AND fi.source_id = _source_id
      AND fi.document_model = 'NFE' AND fi.status = 'CANCELED') INTO canceled;

  RETURN jsonb_build_object(
    'eligible', jsonb_array_length(reasons) = 0,
    'reasons', reasons,
    'sourceType', _source_type,
    'orderId', v_order_id,
    'debtorPartnerId', v_debtor,
    'has_canceled_history', canceled);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_rule_validate_synthetic(_tax_kind text, _rule fiscal_tax_rules, _ctx jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE msg text;
BEGIN
  PERFORM public.fn_fiscal_apply_tax_v2(_rule, _ctx);
  RETURN 'OK';
EXCEPTION WHEN OTHERS THEN
  msg := coalesce(SQLERRM,'');
  IF msg LIKE '%ENGINE_UNAVAILABLE%' THEN RETURN 'ENGINE_UNAVAILABLE'; END IF;
  IF msg LIKE '%AMBIGUOUS%'          THEN RETURN 'AMBIGUOUS'; END IF;
  IF msg LIKE '%NOT_FOUND%'          THEN RETURN 'NOT_FOUND'; END IF;
  RETURN 'INCOMPLETE';
END $function$

CREATE OR REPLACE FUNCTION platform_private.cnpj_valido(_v text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE v text := upper(regexp_replace(coalesce(_v,''), '[\s./-]', '', 'g'));
  w1 int[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2]; w2 int[] := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
  s int; r int; d1 int; d2 int; i int;
BEGIN
  IF v !~ '^[0-9A-Z]{12}[0-9]{2}$' THEN RETURN false; END IF;
  IF v ~ '^([0-9])\1{13}$' THEN RETURN false; END IF;
  s := 0; FOR i IN 1..12 LOOP s := s + (ascii(substr(v,i,1)) - 48) * w1[i]; END LOOP;
  r := s % 11; d1 := CASE WHEN r < 2 THEN 0 ELSE 11 - r END;
  s := 0; FOR i IN 1..12 LOOP s := s + (ascii(substr(v,i,1)) - 48) * w2[i]; END LOOP;
  s := s + d1 * w2[13];
  r := s % 11; d2 := CASE WHEN r < 2 THEN 0 ELSE 11 - r END;
  RETURN substr(v,13,2) = d1::text || d2::text;
END $function$

CREATE OR REPLACE FUNCTION public.organizations_guard_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE via_api boolean := session_user = 'authenticator';
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.id <> OLD.id THEN
    RAISE EXCEPTION 'org_invalid: id imutável' USING errcode='42501'; END IF;
  IF NOT via_api THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NOT platform_private.has_ticket('org_create', '00000000-0000-0000-0000-000000000000'::uuid) THEN
      RAISE EXCEPTION 'org_forbidden: criação apenas via plataforma' USING errcode='42501'; END IF;
    RETURN NEW;
  END IF;
  IF (NEW.status, NEW.razao_social, NEW.nome_fantasia, NEW.cnpj, NEW.cnpj_normalizado, NEW.email_corporativo,
      NEW.fuso_horario, NEW.onboarding_dados, NEW.onboarding_concluido_em, NEW.ativada_em, NEW.nome)
     IS DISTINCT FROM
     (OLD.status, OLD.razao_social, OLD.nome_fantasia, OLD.cnpj, OLD.cnpj_normalizado, OLD.email_corporativo,
      OLD.fuso_horario, OLD.onboarding_dados, OLD.onboarding_concluido_em, OLD.ativada_em, OLD.nome)
     AND NOT platform_private.has_ticket('org_write', NEW.id) THEN
    RAISE EXCEPTION 'org_forbidden: alteração apenas via fluxo do servidor' USING errcode='42501';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._org_set_status(_org uuid, _para text, _motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_de text;
BEGIN
  SELECT status INTO v_de FROM public.organizations WHERE id = _org FOR UPDATE;
  IF v_de IS NULL THEN RAISE EXCEPTION 'org_invalid: empresa inexistente'; END IF;
  IF v_de = _para THEN RETURN; END IF;
  IF NOT public.org_status_transition_ok(v_de, _para) THEN
    RAISE EXCEPTION 'org_invalid: transição % -> % não permitida', v_de, _para; END IF;
  PERFORM platform_private.issue_ticket('org_write', _org);
  UPDATE public.organizations SET status = _para,
    ativo = (_para IN ('ativa','onboarding','aguardando_ativacao','rascunho')),
    ativada_em = CASE WHEN _para='ativa' THEN coalesce(ativada_em, now()) ELSE ativada_em END,
    updated_at = now()
   WHERE id = _org;
  INSERT INTO public.organization_status_audit(organization_id,status_anterior,status_novo,ator_id,motivo)
  VALUES (_org, v_de, _para, auth.uid(), left(_motivo, 300));
END $function$

CREATE OR REPLACE FUNCTION public.fn_generate_recurring_title(_template_id uuid, _reference_date date, _is_manual boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t public.recurring_financial_templates%ROWTYPE;
  v_new_id UUID;
  v_user UUID;
BEGIN
  -- H7O: sessão interna/cron (sem JWT) preservada; chamada autenticada exige staff financeiro.
  IF auth.uid() IS NOT NULL AND NOT public.is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
      HINT = 'H7O: geração de título recorrente restrita ao staff financeiro.';
  END IF;

  SELECT * INTO t FROM public.recurring_financial_templates
  WHERE id = _template_id AND organization_id IS NOT NULL
    AND (auth.uid() IS NULL OR organization_id = platform_private.h15_actor_organization())
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Template não encontrado'; END IF;

  IF NOT t.active THEN
    INSERT INTO public.recurring_generation_log(template_id, reference_date, status, error_message, generated_by, generated_entity_type, amount)
    VALUES (_template_id, _reference_date, 'SKIPPED', 'Template inativo', auth.uid(), t.type, t.amount);
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_GENERATION_SKIPPED', jsonb_build_object('reference_date', _reference_date), auth.uid(), 'Template inativo');
    RETURN NULL;
  END IF;

  IF t.end_date IS NOT NULL AND _reference_date > t.end_date THEN
    INSERT INTO public.recurring_generation_log(template_id, reference_date, status, error_message, generated_by, generated_entity_type, amount)
    VALUES (_template_id, _reference_date, 'SKIPPED', 'Após data final', auth.uid(), t.type, t.amount);
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_GENERATION_SKIPPED', jsonb_build_object('reference_date', _reference_date), auth.uid(), 'Após data final');
    RETURN NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM public.recurring_generation_log WHERE template_id = _template_id AND reference_date = _reference_date AND status = 'SUCCESS') THEN
    INSERT INTO public.recurring_generation_log(template_id, reference_date, status, error_message, generated_by, generated_entity_type, amount)
    VALUES (_template_id, _reference_date, 'SKIPPED', 'Competência já gerada', auth.uid(), t.type, t.amount);
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_GENERATION_SKIPPED', jsonb_build_object('reference_date', _reference_date), auth.uid(), 'Competência já gerada');
    RETURN NULL;
  END IF;

  v_user := COALESCE(auth.uid(), t.created_by);

  IF t.type = 'RECEIVABLE' THEN
    INSERT INTO public.accounts_receivable(
      organization_id, origin_type, customer_id, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count, status,
      fiscal_invoice_required, fiscal_invoice_status, notes, created_by,
      recurring_template_id, reference_month, auto_generated, payment_method_id
    ) VALUES (
      t.organization_id, 'RECURRING', t.customer_id, t.description, t.category_id, t.cost_center_id,
      t.amount, CURRENT_DATE, _reference_date, 1, 'OPEN',
      COALESCE(t.fiscal_invoice_required, false),
      CASE WHEN COALESCE(t.fiscal_invoice_required, false) THEN 'PENDING' ELSE 'NOT_REQUIRED' END,
      t.notes, v_user,
      t.id, date_trunc('month', _reference_date)::DATE, NOT _is_manual, t.payment_method_id
    ) RETURNING id INTO v_new_id;

    INSERT INTO public.recurring_generation_log(template_id, generated_entity_type, generated_entity_id, reference_date, amount, status, generated_by)
    VALUES (_template_id, 'RECEIVABLE', v_new_id, _reference_date, t.amount, 'SUCCESS', v_user);

    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_RECEIVABLE_GENERATED',
            jsonb_build_object('receivable_id', v_new_id, 'reference_date', _reference_date, 'amount', t.amount, 'manual', _is_manual),
            v_user);
  ELSE
    INSERT INTO public.accounts_payable(
      organization_id, origin_type, supplier_name, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count, status,
      notes, created_by,
      recurring_template_id, reference_month, auto_generated
    ) VALUES (
      t.organization_id, 'RECURRING', t.supplier_name, t.description, t.category_id, t.cost_center_id,
      t.amount, CURRENT_DATE, _reference_date, 1, 'OPEN',
      t.notes, v_user,
      t.id, date_trunc('month', _reference_date)::DATE, NOT _is_manual
    ) RETURNING id INTO v_new_id;

    INSERT INTO public.recurring_generation_log(template_id, generated_entity_type, generated_entity_id, reference_date, amount, status, generated_by)
    VALUES (_template_id, 'PAYABLE', v_new_id, _reference_date, t.amount, 'SUCCESS', v_user);

    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_PAYABLE_GENERATED',
            jsonb_build_object('payable_id', v_new_id, 'reference_date', _reference_date, 'amount', t.amount, 'manual', _is_manual),
            v_user);
  END IF;

  UPDATE public.recurring_financial_templates
    SET next_generation_date = public.fn_calc_next_generation_date(t.recurrence_frequency, _reference_date, t.due_day),
        updated_at = now()
    WHERE id = _template_id;

  UPDATE public.recurring_financial_templates
    SET active = false
    WHERE id = _template_id AND end_date IS NOT NULL AND next_generation_date > end_date;

  RETURN v_new_id;
END $function$

CREATE OR REPLACE FUNCTION public.fn_gtin_is_valid(_gtin text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v text;
  v_len int;
  i int;
  v_sum int := 0;
  v_weight int;
  v_check int;
BEGIN
  IF _gtin IS NULL THEN RETURN false; END IF;
  v := btrim(_gtin);
  IF v !~ '^[0-9]+$' THEN RETURN false; END IF;
  v_len := length(v);
  IF v_len NOT IN (8, 12, 13, 14) THEN RETURN false; END IF;

  -- GS1: da direita para a esquerda, ignorando o dígito verificador,
  -- pesos alternados 3,1,3,1...
  FOR i IN REVERSE (v_len - 1)..1 LOOP
    v_weight := CASE WHEN ((v_len - 1 - i) % 2) = 0 THEN 3 ELSE 1 END;
    v_sum := v_sum + (substr(v, i, 1))::int * v_weight;
  END LOOP;

  v_check := (10 - (v_sum % 10)) % 10;
  RETURN v_check = (substr(v, v_len, 1))::int;
END $function$

CREATE OR REPLACE FUNCTION public.fn_generate_receivable_from_entrega(_entrega_id uuid, _payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
  v_receivable_id uuid;
  v_total numeric(14,2);
  v_canon jsonb;
  v_canon_valor numeric;
  v_canon_origem text;
  v_manual boolean;
  v_manual_reason text;
  v_count integer;
  v_category uuid; v_cost_center uuid; v_payment_method uuid;
  v_first_due date; v_issue date;
  v_fiscal_required boolean; v_fiscal_status text;
  v_installments jsonb; v_sum numeric(14,2) := 0; v_inst jsonb;
  v_desc text; v_notes text; v_guard jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para faturar entregas.' USING ERRCODE='insufficient_privilege';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('entrega_faturar:' || _entrega_id::text, 0));

  SELECT * INTO v_entrega FROM public.entregas WHERE id = _entrega_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada.'; END IF;

  -- H6-003.5 replay estavel
  IF v_entrega.receivable_id IS NOT NULL THEN
    RETURN v_entrega.receivable_id;
  END IF;

  IF v_entrega.status = 'cancelada' THEN
    RAISE EXCEPTION 'Entrega cancelada não pode ser faturada.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.status <> 'entregue' THEN
    RAISE EXCEPTION 'Entrega precisa estar com status "entregue" para faturar.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.cliente_id IS NULL THEN
    RAISE EXCEPTION 'Entrega sem cliente vinculado.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.financial_status = 'NOT_BILLABLE' THEN
    RAISE EXCEPTION 'Entrega marcada como não faturável.' USING ERRCODE='check_violation';
  END IF;

  v_total           := COALESCE((_payload->>'total_amount')::numeric, 0);
  v_count           := COALESCE((_payload->>'installment_count')::integer, 1);
  v_category        := NULLIF(_payload->>'category_id','')::uuid;
  v_cost_center     := NULLIF(_payload->>'cost_center_id','')::uuid;
  v_payment_method  := NULLIF(_payload->>'payment_method_id','')::uuid;
  v_first_due       := COALESCE((_payload->>'first_due_date')::date, CURRENT_DATE);
  v_issue           := COALESCE((_payload->>'issue_date')::date, CURRENT_DATE);
  v_fiscal_required := COALESCE((_payload->>'fiscal_invoice_required')::boolean, false);
  v_fiscal_status   := CASE WHEN v_fiscal_required THEN 'PENDING' ELSE 'NOT_REQUIRED' END;
  v_installments    := _payload->'installments';
  v_desc            := COALESCE(NULLIF(_payload->>'description',''), 'Entrega ' || substr(_entrega_id::text,1,8));
  v_notes           := NULLIF(_payload->>'notes','');
  v_manual          := COALESCE((_payload->>'manual_financial_adjustment')::boolean, false);
  v_manual_reason   := NULLIF(trim(_payload->>'manual_adjustment_reason'), '');

  IF v_category IS NULL THEN
    RAISE EXCEPTION 'Categoria financeira é obrigatória.' USING ERRCODE='check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.financial_categories WHERE id = v_category) THEN
    RAISE EXCEPTION 'Categoria financeira não encontrada.' USING ERRCODE='check_violation';
  END IF;
  IF v_count < 1 OR v_count > 36 THEN
    RAISE EXCEPTION 'Número de parcelas deve estar entre 1 e 36.' USING ERRCODE='check_violation';
  END IF;

  -- ------- H6-003: valor canonico server-side é a autoridade do total -------
  v_canon := public.fn_entrega_valor_faturavel_v1(_entrega_id);
  v_canon_origem := v_canon->>'origem';

  -- reconciliacao parcial: usa exatamente o valor_faturavel_max persistido
  SELECT r.valor_faturavel_max INTO v_canon_valor
    FROM public.entrega_reconciliacoes r
   WHERE r.entrega_id = _entrega_id AND r.status = 'reconciliada'
   LIMIT 1;
  IF v_canon_valor IS NULL THEN
    v_canon_valor := (v_canon->>'valor')::numeric;
  ELSE
    v_canon_origem := 'RECONCILIACAO:' || COALESCE(v_canon_origem,'-');
  END IF;

  IF v_canon_valor IS NOT NULL THEN
    IF abs(v_total - v_canon_valor) > 0.01 THEN
      RAISE EXCEPTION 'valor_divergente_do_canonico: informado %, canônico % (origem %).',
        v_total, v_canon_valor, v_canon_origem USING ERRCODE='check_violation';
    END IF;
    v_total := round(v_canon_valor, 2);
  ELSE
    -- sem fonte historica confiavel: exige ajuste financeiro manual justificado
    IF NOT v_manual OR v_manual_reason IS NULL OR length(v_manual_reason) < 10 THEN
      RAISE EXCEPTION 'valor_canonico_indisponivel: informe manual_financial_adjustment com motivo (mín. 10 caracteres).'
        USING ERRCODE='check_violation';
    END IF;
  END IF;

  IF v_total <= 0 THEN
    RAISE EXCEPTION 'Valor total inválido.' USING ERRCODE='check_violation';
  END IF;

  -- GATE: reconciliação obrigatória quando há conferência por item
  v_guard := public.fn_entrega_guard_faturamento_v1(_entrega_id, v_total);

  IF v_installments IS NOT NULL AND jsonb_array_length(v_installments) > 0 THEN
    IF jsonb_array_length(v_installments) <> v_count THEN
      RAISE EXCEPTION 'Quantidade de parcelas (%) diverge de installment_count (%).',
        jsonb_array_length(v_installments), v_count USING ERRCODE='check_violation';
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_installments) LOOP
      v_sum := v_sum + COALESCE((v_inst->>'amount')::numeric, 0);
    END LOOP;
    IF abs(v_sum - v_total) > 0.01 THEN
      RAISE EXCEPTION 'Soma das parcelas (%) difere do total (%).', v_sum, v_total USING ERRCODE='check_violation';
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.accounts_receivable (
      origin_type, origin_id, customer_id, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count,
      payment_method_id, fiscal_invoice_required, fiscal_invoice_status,
      notes, created_by
    ) VALUES (
      'DELIVERY', _entrega_id, v_entrega.cliente_id, v_desc, v_category, v_cost_center,
      v_total, v_issue, v_first_due, v_count,
      v_payment_method, v_fiscal_required, v_fiscal_status,
      v_notes, v_uid
    ) RETURNING id INTO v_receivable_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_receivable_id FROM public.accounts_receivable
     WHERE origin_type = 'DELIVERY' AND origin_id = _entrega_id AND status <> 'CANCELED';
    IF v_receivable_id IS NOT NULL THEN RETURN v_receivable_id; END IF;
    RAISE EXCEPTION 'Entrega já possui conta a receber ativa.' USING ERRCODE='check_violation';
  END;

  IF v_installments IS NOT NULL AND jsonb_array_length(v_installments) > 0 THEN
    DELETE FROM public.accounts_receivable_installments WHERE receivable_id = v_receivable_id;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_installments) LOOP
      INSERT INTO public.accounts_receivable_installments (
        receivable_id, installment_number, due_date, original_amount, net_amount, status
      ) VALUES (
        v_receivable_id,
        (v_inst->>'installment_number')::integer,
        (v_inst->>'due_date')::date,
        (v_inst->>'amount')::numeric,
        (v_inst->>'amount')::numeric,
        'OPEN'
      );
    END LOOP;
  END IF;

  UPDATE public.entregas
     SET receivable_id = v_receivable_id,
         financial_status = 'BILLED',
         billing_generated_at = now(),
         billing_generated_by = v_uid
   WHERE id = _entrega_id;

  INSERT INTO public.financial_audit_log (
    entity_type, entity_id, action, old_data, new_data, performed_by
  ) VALUES (
    'entregas', _entrega_id, 'DELIVERY_BILLED',
    jsonb_build_object('receivable_id', v_entrega.receivable_id,
                       'financial_status', v_entrega.financial_status),
    jsonb_build_object('receivable_id', v_receivable_id, 'total_amount', v_total,
      'installment_count', v_count, 'fiscal_invoice_required', v_fiscal_required,
      'payment_method_id', v_payment_method, 'origem', 'entrega',
      'valor_canonico', v_canon_valor, 'valor_canonico_origem', v_canon_origem,
      'manual_financial_adjustment', v_manual, 'manual_adjustment_reason', v_manual_reason,
      'reconciliacao', v_guard),
    v_uid
  );

  RETURN v_receivable_id;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.conclude_provisional_password()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid := auth.uid(); v_digest text; v_atual text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE user_id = v_uid AND senha_provisoria IS TRUE) THEN
    RETURN true;
  END IF;
  SELECT pwd_digest INTO v_digest FROM platform_private.provisional_password_state WHERE user_id = v_uid;
  SELECT md5(COALESCE(u.encrypted_password,'')) INTO v_atual FROM auth.users u WHERE u.id = v_uid;
  IF v_digest IS NULL OR v_atual IS NULL OR v_atual = v_digest OR v_atual = md5('') THEN
    RAISE EXCEPTION 'platform_senha_nao_alterada' USING ERRCODE='22023';
  END IF;
  PERFORM platform_private.issue_ticket('pwd_conclude', v_uid);
  PERFORM set_config('cf.concluir_senha','on', true);
  UPDATE public.profiles SET senha_provisoria = false, updated_at = now() WHERE user_id = v_uid;
  PERFORM set_config('cf.concluir_senha','off', true);
  UPDATE public.platform_org_admin_invites SET status='ativo', concluido_em=now()
   WHERE user_id = v_uid AND status='pendente';
  DELETE FROM platform_private.provisional_password_state WHERE user_id = v_uid;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION platform_private.storage1_application_allowed(p_name text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid; r platform_private.application_save_preparations%ROWTYPE; a public.aplicacoes%ROWTYPE;
 client uuid; os_org uuid; product uuid; staff boolean; u uuid:=auth.uid(); responsible uuid; own_role boolean; os_status text; lot uuid;
BEGIN
 IF auth.uid() IS NULL OR public.storage1_path_strict(p_name) IS DISTINCT FROM true OR p_action IS NULL
 OR p_action NOT IN ('select','insert','update','delete') OR p_name !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[A-Za-z0-9_.-]+$' THEN RETURN false; END IF;
 org:=public.h15_actor_organization(); IF org IS NULL THEN RETURN false; END IF;
 SELECT * INTO r FROM platform_private.application_save_preparations WHERE application_id=split_part(p_name,'/',2)::uuid;
 IF p_action='insert' AND r.application_id IS NOT NULL THEN
 IF r.actor_id IS DISTINCT FROM auth.uid() OR r.organization_id IS DISTINCT FROM org OR r.committed_at IS NOT NULL
 OR r.expires_at<=clock_timestamp() OR r.client_id::text IS DISTINCT FROM split_part(p_name,'/',1)
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r.manifest) ev WHERE ev->>'storage_path'=p_name)
 OR public.can_user_create_aplicacao_for_cliente(r.client_id) IS DISTINCT FROM true THEN RETURN false; END IF;
 -- Exact current RPC membership branch: a broad operator/applicator role must
 -- not rescue a revoked consultant/technical/producer portfolio.
 IF (public.has_role(u,'cliente_produtor') OR public.has_role(u,'consultor_tecnico') OR public.has_role(u,'tecnico_agronomo'))
 AND NOT (public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo'))
 AND NOT r.client_id=ANY(public.get_cliente_ids_for_user(u)) THEN RETURN false; END IF;
 responsible:=nullif(r.payload->>'responsavel_id','')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=responsible AND organization_id=org AND ativo IS TRUE AND senha_provisoria IS FALSE)
 OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=responsible AND role::text IN
 ('administrador','gestor','administrativo','consultor_tecnico','tecnico_agronomo','aplicador','operador_onfarm','cliente_produtor'))
 OR platform_private.platform_actor_access_ready(responsible) IS DISTINCT FROM true THEN RETURN false; END IF;
 own_role:=public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo') OR public.has_role(u,'consultor_tecnico');
 IF NOT own_role AND responsible IS DISTINCT FROM u THEN RETURN false; END IF;
 lot:=nullif(r.payload->>'lote_usado_id','')::uuid;
 IF r.payload->>'ordem_servico_id' IS NOT NULL THEN
 SELECT cliente_id,organization_id,produto_id,status::text INTO client,os_org,product,os_status FROM public.ordens_servico WHERE id=(r.payload->>'ordem_servico_id')::uuid;
 ELSE SELECT os.cliente_id,c.organization_id,os.produto_id,os.status::text INTO client,os_org,product,os_status FROM public.ordens_servico_onfarm os JOIN public.clientes c ON c.id=os.cliente_id WHERE os.id=(r.payload->>'ordem_servico_onfarm_id')::uuid; END IF;
 RETURN client=r.client_id AND os_org=org AND product::text=r.payload->>'produto_usado_id'
 AND (os_status IN ('entregue','pronto_entrega','envase') OR (r.rectify_id IS NOT NULL AND os_status='finalizada'))
 AND (lot IS NULL OR EXISTS(SELECT 1 FROM public.lotes WHERE id=lot AND produto_id=product AND organization_id=org AND status='aprovado'))
 AND EXISTS(SELECT 1 FROM public.clientes WHERE id=client AND organization_id=org)
 AND EXISTS(SELECT 1 FROM public.produtos WHERE id=product AND ativo IS TRUE)
 AND (r.rectify_id IS NULL OR EXISTS(SELECT 1 FROM public.aplicacoes WHERE id=r.rectify_id AND organization_id=org AND is_latest IS TRUE)
 AND public.can_user_manage_aplicacao(r.rectify_id) AND public.can_user_access_aplicacao(r.rectify_id))
 AND public.h15_actor_organization()=org;
 END IF;
 SELECT * INTO a FROM public.aplicacoes WHERE id=split_part(p_name,'/',2)::uuid;
 IF NOT FOUND OR a.organization_id IS DISTINCT FROM org OR (a.ordem_servico_id IS NULL)=(a.ordem_servico_onfarm_id IS NULL) THEN RETURN false; END IF;
 IF a.ordem_servico_id IS NOT NULL THEN SELECT cliente_id,organization_id INTO client,os_org FROM public.ordens_servico WHERE id=a.ordem_servico_id;
 ELSE SELECT os.cliente_id,c.organization_id INTO client,os_org FROM public.ordens_servico_onfarm os JOIN public.clientes c ON c.id=os.cliente_id WHERE os.id=a.ordem_servico_onfarm_id; END IF;
 IF client::text IS DISTINCT FROM split_part(p_name,'/',1) OR os_org IS DISTINCT FROM org
 OR NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=client AND organization_id=org) THEN RETURN false; END IF;
 staff:=NOT public.has_role(auth.uid(),'aplicador') OR public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor')
 OR public.has_role(auth.uid(),'administrativo') OR public.has_role(auth.uid(),'consultor_tecnico') OR a.responsavel_id=auth.uid()
 OR client=ANY(public.get_cliente_ids_for_user(auth.uid()));
 IF p_action='select' THEN RETURN staff AND public.can_user_access_aplicacao(a.id); END IF;
 -- Finalized objects are immutable. Deletion remains denied when metadata references bytes.
 IF p_action IN ('insert','update') THEN RETURN false; END IF;
 RETURN staff AND a.is_latest IS TRUE AND public.can_user_manage_aplicacao(a.id)
 AND NOT EXISTS(SELECT 1 FROM public.aplicacao_evidencias WHERE storage_path=p_name);
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.storage1_delivery_allowed(p_name text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_id uuid; v_e public.entregas%ROWTYPE; v_client_org uuid; v_staff boolean;
BEGIN
 IF auth.uid() IS NULL OR p_action IS NULL OR NOT public.storage1_path_strict(p_name) OR p_action NOT IN ('select','insert','update','delete') THEN RETURN false; END IF;
 v_org:=public.h15_actor_organization(); IF v_org IS NULL THEN RETURN false; END IF;
 IF p_name !~ '^entregas/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/([A-Za-z0-9_-]+/)*[A-Za-z0-9_.-]+$' THEN RETURN false; END IF;
 v_id:=split_part(p_name,'/',2)::uuid;
 SELECT * INTO v_e FROM public.entregas WHERE id=v_id;
 IF NOT FOUND OR v_e.organization_id IS DISTINCT FROM v_org OR v_e.cliente_id IS NULL THEN RETURN false; END IF;
 SELECT organization_id INTO v_client_org FROM public.clientes WHERE id=v_e.cliente_id;
 IF v_client_org IS DISTINCT FROM v_org THEN RETURN false; END IF;
 v_staff:=public.is_delivery_staff(auth.uid()) AND (NOT public.has_role(auth.uid(),'aplicador') OR public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'administrativo') OR public.has_role(auth.uid(),'producao') OR public.has_role(auth.uid(),'operador_onfarm') OR v_e.cliente_id=ANY(public.get_cliente_ids_for_user(auth.uid())));
 IF p_action='select' THEN RETURN v_staff OR public.is_financial_staff(auth.uid()) OR (public.has_role(auth.uid(),'cliente_produtor') AND v_e.cliente_id=ANY(public.get_cliente_ids_for_user(auth.uid()))); END IF;
 RETURN v_staff AND v_e.status::text IN ('separado','em_rota');
END; $function$

CREATE OR REPLACE FUNCTION public.guard_profile_senha_provisoria()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF current_user IN ('postgres','service_role','supabase_auth_admin') THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.senha_provisoria IS TRUE THEN
      RAISE EXCEPTION 'profile_sensitive_fields_forbidden' USING ERRCODE='42501';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.senha_provisoria IS DISTINCT FROM OLD.senha_provisoria THEN
    RAISE EXCEPTION 'profile_sensitive_fields_forbidden' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_resolve_b2b_cart(p_partner_id uuid, p_plan_id uuid, p_items jsonb, p_ref_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item jsonb; v_iid uuid; v_itipo text; v_qty numeric(12,2);
  v_unidade text; v_volume_ml numeric(12,2);
  v_nome text; v_codigo text; v_res jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_table numeric(14,2) := 0; v_net numeric(14,2) := 0;
  v_quote boolean := false;
  v_line_table numeric(14,2); v_line_final numeric(14,2);
  v_ok boolean; v_active boolean; v_b2b boolean;
BEGIN
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'empty_cart' USING ERRCODE='P0001';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_iid     := COALESCE(NULLIF(v_item->>'item_id','')::uuid, NULLIF(v_item->>'product_id','')::uuid);
    v_itipo   := COALESCE(NULLIF(v_item->>'item_tipo',''), 'produto');
    v_qty     := COALESCE((v_item->>'quantidade')::numeric, 0);
    v_unidade := COALESCE(NULLIF(v_item->>'unidade_medida',''), 'hectare');
    v_volume_ml := NULLIF((v_item->>'volume_ml')::numeric, 0);

    IF v_iid IS NULL THEN RAISE EXCEPTION 'invalid_item' USING ERRCODE='P0001'; END IF;
    IF v_qty <= 0 THEN RAISE EXCEPTION 'invalid_qty' USING ERRCODE='P0001'; END IF;
    IF v_unidade NOT IN ('hectare','litro','dose','unidade') THEN
      RAISE EXCEPTION 'invalid_unidade_medida' USING ERRCODE='P0001'; END IF;
    IF v_unidade = 'unidade' AND COALESCE(v_volume_ml,0) <= 0 THEN
      RAISE EXCEPTION 'invalid_volume_ml' USING ERRCODE='P0001'; END IF;

    IF v_itipo = 'produto' THEN
      SELECT nome, codigo, ativo, COALESCE(b2b_enabled,true) INTO v_nome, v_codigo, v_active, v_b2b
        FROM public.produtos WHERE id = v_iid;
    ELSIF v_itipo = 'microrganismo' THEN
      SELECT nome, codigo, ativo, COALESCE(b2b_enabled,false) INTO v_nome, v_codigo, v_active, v_b2b
        FROM public.microrganismos WHERE id = v_iid;
    ELSE
      RAISE EXCEPTION 'invalid_item_tipo' USING ERRCODE='P0001';
    END IF;
    IF v_nome IS NULL OR v_active IS NOT TRUE OR v_b2b IS NOT TRUE THEN
      RAISE EXCEPTION 'product_unavailable' USING ERRCODE='P0001';
    END IF;

    v_res := public.fn_resolve_commercial_price(
      'partner', p_partner_id, NULL, p_plan_id,
      CASE WHEN v_itipo='produto' THEN v_iid END,
      CASE WHEN v_itipo='microrganismo' THEN v_iid END,
      v_unidade, v_volume_ml, COALESCE(p_ref_date, current_date), v_qty);

    v_ok := COALESCE((v_res->>'ok')::boolean,false);

    IF COALESCE((v_res->>'quote_required')::boolean,false) THEN
      v_quote := true;
      v_line_table := 0; v_line_final := 0;
    ELSIF NOT v_ok THEN
      RAISE EXCEPTION '%', v_res->>'reason_code' USING ERRCODE='P0001';
    ELSE
      v_line_table := ROUND((v_res->>'base_price')::numeric * v_qty, 2);
      v_line_final := ROUND((v_res->>'final_unit_price')::numeric * v_qty, 2);
      v_table := v_table + v_line_table;
      v_net   := v_net + v_line_final;
    END IF;

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'item_id', v_iid, 'item_tipo', v_itipo, 'quantidade', v_qty,
      'unidade_medida', v_unidade, 'volume_ml', v_volume_ml,
      'nome', v_nome, 'codigo', v_codigo,
      'pricing_mode', v_res->>'pricing_mode',
      'price_source', v_res->>'price_source',
      'reason_code',  v_res->>'reason_code',
      'quote_required', COALESCE((v_res->>'quote_required')::boolean,false),
      'base_price', (v_res->>'base_price')::numeric,
      'condition_price', (v_res->>'condition_price')::numeric,
      'plan_discount_percent', (v_res->>'plan_discount_percent')::numeric,
      'min_quantity', (v_res->>'min_quantity')::numeric,
      'final_unit_price', (v_res->>'final_unit_price')::numeric,
      'rule_id', v_res->>'rule_id',
      'line_table_amount', v_line_table,
      'line_final_amount', v_line_final
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'quote_required', v_quote,
    'table_amount', CASE WHEN v_quote THEN 0 ELSE v_table END,
    'discount_amount', CASE WHEN v_quote THEN 0 ELSE ROUND(v_table - v_net,2) END,
    'net_amount', CASE WHEN v_quote THEN 0 ELSE v_net END,
    'lines', v_lines);
END $function$

CREATE OR REPLACE FUNCTION public.fn_set_initial_next_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_initial DATE;
BEGIN
  IF NEW.next_generation_date IS NULL THEN
    v_initial := NEW.start_date;
    IF NEW.due_day IS NOT NULL AND NEW.recurrence_frequency IN ('MONTHLY','QUARTERLY','YEARLY') THEN
      BEGIN
        v_initial := make_date(EXTRACT(YEAR FROM v_initial)::INT, EXTRACT(MONTH FROM v_initial)::INT,
          LEAST(NEW.due_day, EXTRACT(DAY FROM (date_trunc('month', v_initial) + INTERVAL '1 month - 1 day'))::INT));
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
    NEW.next_generation_date := v_initial;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.storage1_consultor_core(p_name text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_id uuid; v_client uuid; v_status text;
BEGIN
 IF auth.uid() IS NULL OR p_action IS NULL OR NOT public.storage1_path_strict(p_name) OR p_action NOT IN ('select','insert','update','delete') THEN RETURN false; END IF;
 v_org:=public.h15_actor_organization(); IF v_org IS NULL THEN RETURN false; END IF;
 IF p_name !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/(foto|audio|documento)/[A-Za-z0-9_.-]+$' OR split_part(p_name,'/',1)<>v_org::text THEN RETURN false; END IF;
 BEGIN v_id:=split_part(p_name,'/',2)::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END;
 SELECT r.cliente_id,r.status::text INTO v_client,v_status FROM public.registros_consultor r JOIN public.clientes c ON c.id=r.cliente_id AND c.organization_id=v_org WHERE r.id=v_id;
 IF NOT FOUND THEN RETURN false; END IF;
 IF p_action='select' THEN RETURN public.technical_child_read_scope(v_id) AND ((public.has_role(auth.uid(),'cliente_produtor') AND v_client=ANY(public.get_cliente_ids_for_user(auth.uid()))) OR ((public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'consultor_tecnico') OR public.has_role(auth.uid(),'tecnico_agronomo') OR public.has_role(auth.uid(),'aplicador')) AND public.can_view_technical_visit(auth.uid(),v_id))); END IF;
 RETURN v_status IN ('rascunho','em_andamento') AND (public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'consultor_tecnico') OR public.has_role(auth.uid(),'tecnico_agronomo') OR public.has_role(auth.uid(),'aplicador')) AND public.can_manage_technical_visit(auth.uid(),v_id);
END; $function$

CREATE OR REPLACE FUNCTION public.fn_sync_receipt_aliases()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.receivable_payment_id IS NULL AND NEW.payment_id IS NOT NULL THEN
    NEW.receivable_payment_id := NEW.payment_id;
  ELSIF NEW.payment_id IS NULL AND NEW.receivable_payment_id IS NOT NULL THEN
    NEW.payment_id := NEW.receivable_payment_id;
  END IF;
  IF NEW.description IS NULL OR length(trim(NEW.description)) = 0 THEN
    NEW.description := 'Recibo nº ' || COALESCE(NEW.receipt_number, '—');
  END IF;
  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public.fn_sync_report_export_aliases()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.file_format IS NULL AND NEW.format IS NOT NULL THEN NEW.file_format := NEW.format; END IF;
  IF NEW.format IS NULL AND NEW.file_format IS NOT NULL THEN NEW.format := NEW.file_format; END IF;
  IF NEW.report_title IS NULL THEN NEW.report_title := NEW.report_type; END IF;
  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public.fn_validate_envase_cq()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_lote_status TEXT;
    v_cq_resultado TEXT;
BEGIN
    SELECT status INTO v_lote_status FROM public.lotes WHERE id = NEW.lote_id;

    SELECT resultado::text INTO v_cq_resultado
      FROM public.controle_qualidade
     WHERE lote_id = NEW.lote_id
     ORDER BY created_at DESC, seq DESC
     LIMIT 1;

    IF v_lote_status <> 'aprovado' OR v_cq_resultado IS NULL OR v_cq_resultado <> 'aprovado' THEN
        RAISE EXCEPTION 'O lote % não possui Controle de Qualidade aprovado. O envase não é permitido.',
            (SELECT codigo_lote FROM public.lotes WHERE id = NEW.lote_id);
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_salvar_aplicacao_v1(p_aplicacao_id uuid, p_payload jsonb, p_rectify_id uuid DEFAULT NULL::uuid, p_evidencias jsonb DEFAULT '[]'::jsonb, p_evidencias_manter uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 u uuid:=auth.uid(); org uuid; client uuid; product uuid; os_org uuid;
 osid uuid; onid uuid; lot uuid; responsible uuid; phase text; canonical jsonb; os_status text;
 r platform_private.application_save_preparations%ROWTYPE;
 original public.aplicacoes%ROWTYPE; a public.aplicacoes%ROWTYPE;
 ev jsonb; e public.aplicacao_evidencias%ROWTYPE; obj storage.objects%ROWTYPE;
 kept uuid; k text; n numeric; lo numeric; hi numeric; root uuid; ver integer:=1;
 expected text; ev_id uuid; moment date; start_at timestamptz; end_at timestamptz;
 manifest jsonb; count_files integer; own_role boolean; name_responsible text;
BEGIN
 -- Never parse/replay a receipt before proving current actor readiness.
 IF u IS NULL THEN RAISE EXCEPTION 'application_auth_required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=u FOR SHARE;
 org:=public.h15_actor_organization();
 IF org IS NULL THEN RAISE EXCEPTION 'application_actor_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=u ORDER BY role FOR SHARE;
 PERFORM 1 FROM public.platform_org_admin_invites WHERE user_id=u FOR SHARE;
 IF p_aplicacao_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_evidencias) IS DISTINCT FROM 'array' OR p_evidencias_manter IS NULL
 OR octet_length(p_payload::text)>32768 OR octet_length(p_evidencias::text)>32768 THEN
 RAISE EXCEPTION 'application_payload_invalid' USING ERRCODE='22023'; END IF;
 phase:=p_payload->>'_phase';
 IF phase IS NULL OR phase NOT IN ('prepare','finalize') THEN RAISE EXCEPTION 'application_phase_required' USING ERRCODE='22023'; END IF;
 canonical:=p_payload-'_phase';
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(canonical) key WHERE key NOT IN (
 'ordem_servico_id','ordem_servico_onfarm_id','data_aplicacao','hora_inicio','hora_fim','responsavel_id','responsavel',
 'modo_aplicacao','produto_usado_id','lote_usado_id','dose_aplicada','dose_unidade','volume_calda_l_ha',
 'volume_total_aplicado_ml','area_aplicada_ha','equipamento','equipamento_modelo','bico_tipo','pressao_bar',
 'temperatura_c','umidade_pct','vento_kmh','condicoes_climaticas','latitude','longitude','resultado_inicial',
 'observacoes','created_by','motivo_retificacao')) THEN RAISE EXCEPTION 'application_unknown_field' USING ERRCODE='22023'; END IF;
 IF canonical->>'created_by' IS DISTINCT FROM u::text OR canonical->>'dose_unidade' IS DISTINCT FROM 'mL/ha'
 THEN RAISE EXCEPTION 'application_author_or_unit_invalid' USING ERRCODE='42501'; END IF;
 osid:=nullif(canonical->>'ordem_servico_id','')::uuid;
 onid:=nullif(canonical->>'ordem_servico_onfarm_id','')::uuid;
 IF num_nonnulls(osid,onid)<>1 THEN RAISE EXCEPTION 'application_origin_invalid' USING ERRCODE='22023'; END IF;
 -- Lock every persisted authority before receipt lookup. Locks prevent UPDATE/DELETE races;
 -- they do not invent membership, roles or a tenant for NULL legacy rows.
 IF osid IS NOT NULL THEN
 SELECT cliente_id,produto_id,organization_id,status::text INTO client,product,os_org,os_status FROM public.ordens_servico WHERE id=osid FOR SHARE;
 ELSE
 SELECT cliente_id,produto_id,status::text INTO client,product,os_status FROM public.ordens_servico_onfarm WHERE id=onid FOR SHARE;
 SELECT organization_id INTO os_org FROM public.clientes WHERE id=client;
 END IF;
 IF client IS NULL OR os_org IS DISTINCT FROM org OR product IS NULL THEN RAISE EXCEPTION 'application_origin_denied' USING ERRCODE='42501'; END IF;
 -- Same lifecycle as the canonical desktop form. Replay is reauthorized too.
 IF os_status IS NULL OR NOT (os_status IN ('entregue','pronto_entrega','envase')
 OR (p_rectify_id IS NOT NULL AND os_status='finalizada')) THEN RAISE EXCEPTION 'application_os_status_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.clientes WHERE id=client AND organization_id=org FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_client_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.user_clientes WHERE user_id=u AND cliente_id=client ORDER BY id FOR SHARE;
 IF public.can_user_create_aplicacao_for_cliente(client) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_create_denied' USING ERRCODE='42501'; END IF;
 IF (public.has_role(u,'cliente_produtor') OR public.has_role(u,'consultor_tecnico') OR public.has_role(u,'tecnico_agronomo'))
 AND NOT (public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo'))
 AND NOT client=ANY(public.get_cliente_ids_for_user(u)) THEN RAISE EXCEPTION 'application_membership_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.produtos WHERE id=product AND ativo IS TRUE FOR SHARE;
 IF NOT FOUND OR nullif(canonical->>'produto_usado_id','')::uuid IS DISTINCT FROM product THEN RAISE EXCEPTION 'application_product_denied' USING ERRCODE='42501'; END IF;
 lot:=nullif(canonical->>'lote_usado_id','')::uuid;
 IF lot IS NOT NULL THEN
 PERFORM 1 FROM public.lotes WHERE id=lot AND produto_id=product AND organization_id=org AND status='aprovado' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_lot_denied' USING ERRCODE='42501'; END IF; END IF;
 responsible:=nullif(canonical->>'responsavel_id','')::uuid;
 SELECT nome INTO name_responsible FROM public.profiles WHERE user_id=responsible AND organization_id=org
 AND ativo IS TRUE AND senha_provisoria IS FALSE FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.user_roles WHERE user_id=responsible ORDER BY role FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=responsible AND role::text IN
 ('administrador','gestor','administrativo','consultor_tecnico','tecnico_agronomo','aplicador','operador_onfarm','cliente_produtor'))
 OR platform_private.platform_actor_access_ready(responsible) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 own_role:=public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo') OR public.has_role(u,'consultor_tecnico');
 IF NOT own_role AND responsible IS DISTINCT FROM u THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 -- Preserve Storage1's applicator restriction; do not make RPC metadata a bypass.
 IF public.has_role(u,'aplicador') AND NOT own_role AND responsible IS DISTINCT FROM u
 AND NOT client=ANY(public.get_cliente_ids_for_user(u)) THEN RAISE EXCEPTION 'application_applicator_denied' USING ERRCODE='42501'; END IF;
 FOR k,lo,hi IN SELECT * FROM (VALUES
 ('dose_aplicada',0::numeric,NULL::numeric),('area_aplicada_ha',0::numeric,NULL::numeric),
 ('volume_calda_l_ha',0::numeric,NULL::numeric),('volume_total_aplicado_ml',0::numeric,NULL::numeric),
 ('pressao_bar',0::numeric,NULL::numeric),('temperatura_c',-50::numeric,70::numeric),('umidade_pct',0::numeric,100::numeric),
 ('vento_kmh',0::numeric,250::numeric),('latitude',-90::numeric,90::numeric),('longitude',-180::numeric,180::numeric)) bounds LOOP
 IF canonical->>k IS NULL THEN
 IF k IN ('dose_aplicada','area_aplicada_ha','volume_total_aplicado_ml') THEN RAISE EXCEPTION 'application_numeric_required' USING ERRCODE='22023'; END IF;
 ELSE
 IF jsonb_typeof(canonical->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'application_numeric_invalid' USING ERRCODE='22023'; END IF;
 n:=(canonical->>k)::numeric;
 IF n::text IN ('NaN','Infinity','-Infinity') OR n<lo OR (hi IS NOT NULL AND n>hi)
 OR (k IN ('dose_aplicada','area_aplicada_ha','volume_total_aplicado_ml') AND n<=0) THEN RAISE EXCEPTION 'application_numeric_bounds' USING ERRCODE='22023'; END IF;
 END IF;
 END LOOP;
 IF (canonical->>'volume_total_aplicado_ml')::numeric IS DISTINCT FROM (canonical->>'dose_aplicada')::numeric*(canonical->>'area_aplicada_ha')::numeric
 THEN RAISE EXCEPTION 'application_total_invalid' USING ERRCODE='22023'; END IF;
 moment:=(canonical->>'data_aplicacao')::date;
 start_at:=nullif(canonical->>'hora_inicio','')::timestamptz; end_at:=nullif(canonical->>'hora_fim','')::timestamptz;
 IF moment IS NULL OR NOT isfinite(moment) OR (start_at IS NOT NULL AND NOT isfinite(start_at))
 OR (end_at IS NOT NULL AND (NOT isfinite(end_at) OR start_at IS NULL OR end_at<=start_at)) THEN RAISE EXCEPTION 'application_time_invalid' USING ERRCODE='22023'; END IF;
 IF p_rectify_id IS NULL AND cardinality(p_evidencias_manter)>0 THEN RAISE EXCEPTION 'application_inheritance_denied' USING ERRCODE='42501'; END IF;
 count_files:=jsonb_array_length(p_evidencias)+cardinality(p_evidencias_manter);
 IF count_files>20 OR cardinality(p_evidencias_manter)<>(SELECT count(DISTINCT x) FROM unnest(p_evidencias_manter)x)
 THEN RAISE EXCEPTION 'application_evidence_limit' USING ERRCODE='22023'; END IF;
 manifest:='[]'::jsonb;
 FOR ev IN SELECT value FROM jsonb_array_elements(p_evidencias) LOOP
 IF jsonb_typeof(ev) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(ev) key WHERE key NOT IN ('tipo','storage_path','legenda','mime','tamanho_bytes'))
 THEN RAISE EXCEPTION 'application_evidence_invalid' USING ERRCODE='22023'; END IF;
 expected:=CASE ev->>'mime' WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' WHEN 'image/webp' THEN 'webp'
 WHEN 'image/heic' THEN 'heic' WHEN 'image/heif' THEN 'heif' WHEN 'application/pdf' THEN 'pdf'
 WHEN 'video/mp4' THEN 'mp4' WHEN 'video/webm' THEN 'webm' WHEN 'video/quicktime' THEN 'mov'
 WHEN 'audio/mpeg' THEN 'mp3' WHEN 'audio/mp4' THEN 'm4a' WHEN 'audio/wav' THEN 'wav' WHEN 'audio/ogg' THEN 'ogg' WHEN 'audio/webm' THEN 'webm' END;
 IF expected IS NULL OR public.storage1_path_strict(ev->>'storage_path') IS DISTINCT FROM true
 OR split_part(ev->>'storage_path','/',1) IS DISTINCT FROM client::text
 OR split_part(ev->>'storage_path','/',2) IS DISTINCT FROM p_aplicacao_id::text
 OR split_part(ev->>'storage_path','/',3) !~ ('^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.'||expected||'$')
 OR jsonb_typeof(ev->'tamanho_bytes') IS DISTINCT FROM 'number' OR (ev->>'tamanho_bytes')::numeric NOT BETWEEN 1 AND 10485760
 OR (ev->>'tamanho_bytes')::numeric<>trunc((ev->>'tamanho_bytes')::numeric)
 OR coalesce(char_length(ev->>'legenda'),0)>1000
 OR ev->>'tipo' IS DISTINCT FROM (CASE WHEN ev->>'mime' LIKE 'image/%' THEN 'foto' WHEN ev->>'mime' LIKE 'video/%' THEN 'video' WHEN ev->>'mime' LIKE 'audio/%' THEN 'audio' ELSE 'documento' END)
 THEN RAISE EXCEPTION 'application_evidence_invalid' USING ERRCODE='22023'; END IF;
 manifest:=manifest||jsonb_build_array(ev);
 END LOOP;
 IF jsonb_array_length(manifest)<>(SELECT count(DISTINCT value->>'storage_path') FROM jsonb_array_elements(manifest)) THEN RAISE EXCEPTION 'application_evidence_duplicate' USING ERRCODE='22023'; END IF;
 -- One writer per application; then one writer per original version. No global cache.
 PERFORM pg_advisory_xact_lock(hashtextextended('application-save:'||p_aplicacao_id::text,0));
 SELECT * INTO r FROM platform_private.application_save_preparations WHERE application_id=p_aplicacao_id FOR UPDATE;
 IF FOUND AND (r.actor_id IS DISTINCT FROM u OR r.organization_id IS DISTINCT FROM org OR r.payload IS DISTINCT FROM canonical
 OR r.rectify_id IS DISTINCT FROM p_rectify_id OR r.manifest IS DISTINCT FROM manifest OR r.keep_ids IS DISTINCT FROM p_evidencias_manter)
 THEN RAISE EXCEPTION 'application_receipt_mismatch' USING ERRCODE='42501'; END IF;
 IF p_rectify_id IS NOT NULL THEN
 SELECT * INTO original FROM public.aplicacoes WHERE id=p_rectify_id FOR UPDATE;
 IF NOT FOUND OR original.organization_id IS DISTINCT FROM org OR public.can_user_manage_aplicacao(p_rectify_id) IS DISTINCT FROM true
 OR public.can_user_access_aplicacao(p_rectify_id) IS DISTINCT FROM true
 OR original.ordem_servico_id IS DISTINCT FROM osid OR original.ordem_servico_onfarm_id IS DISTINCT FROM onid
 THEN RAISE EXCEPTION 'application_rectification_denied' USING ERRCODE='42501'; END IF;
 IF (r.application_id IS NULL OR r.committed_at IS NULL) AND original.is_latest IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_version_conflict' USING ERRCODE='PT409'; END IF;
 IF char_length(btrim(coalesce(canonical->>'motivo_retificacao',''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'application_reason_invalid' USING ERRCODE='22023'; END IF;
 root:=coalesce(original.parent_id,original.id); ver:=original.versao+1;
 END IF;
 -- Validate inherited objects through their immutable origin, never rewritten paths.
 FOREACH kept IN ARRAY p_evidencias_manter LOOP
 SELECT ae.* INTO e FROM public.aplicacao_evidencias ae JOIN public.aplicacao_evidencias_vinculos v ON v.evidencia_id=ae.id
 WHERE v.aplicacao_id=p_rectify_id AND ae.id=kept FOR SHARE OF ae,v;
 IF NOT FOUND OR e.aplicacao_id IS DISTINCT FROM e.versao_origem_id
 OR public.can_user_access_aplicacao(e.versao_origem_id) IS DISTINCT FROM true
 OR split_part(e.storage_path,'/',1) IS DISTINCT FROM client::text OR split_part(e.storage_path,'/',2) IS DISTINCT FROM e.versao_origem_id::text
 OR public.storage1_path_strict(e.storage_path) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_inheritance_denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO obj FROM storage.objects WHERE bucket_id='aplicacao-evidencias' AND name=e.storage_path FOR SHARE;
 IF NOT FOUND OR obj.metadata->>'mimetype' IS DISTINCT FROM e.mime OR nullif(obj.metadata->>'size','')::bigint IS DISTINCT FROM e.tamanho_bytes
 THEN RAISE EXCEPTION 'application_inherited_object_invalid' USING ERRCODE='42501'; END IF;
 END LOOP;
 IF public.h15_actor_organization() IS DISTINCT FROM org OR public.can_user_create_aplicacao_for_cliente(client) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'application_actor_denied' USING ERRCODE='42501'; END IF;
 IF r.committed_at IS NOT NULL THEN
 SELECT * INTO a FROM public.aplicacoes WHERE id=p_aplicacao_id AND organization_id=org AND created_by=u;
 IF NOT FOUND OR public.can_user_access_aplicacao(p_aplicacao_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_replay_denied' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('success',true,'created',false,'id',a.id,'versao',a.versao,'phase','finalized'); END IF;
 IF r.application_id IS NOT NULL AND r.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'application_preparation_expired' USING ERRCODE='42501'; END IF;
 IF phase='prepare' THEN
 IF r.application_id IS NULL THEN
 IF EXISTS(SELECT 1 FROM public.aplicacoes WHERE id=p_aplicacao_id) THEN RAISE EXCEPTION 'application_identity_conflict' USING ERRCODE='42501'; END IF;
 INSERT INTO platform_private.application_save_preparations(application_id,actor_id,organization_id,client_id,payload,rectify_id,manifest,keep_ids,expires_at)
 VALUES(p_aplicacao_id,u,org,client,canonical,p_rectify_id,manifest,p_evidencias_manter,clock_timestamp()+interval '15 minutes'); END IF;
 RETURN jsonb_build_object('success',true,'id',p_aplicacao_id,'phase','prepared'); END IF;
 IF r.application_id IS NULL THEN RAISE EXCEPTION 'application_preparation_required' USING ERRCODE='42501'; END IF;
 FOR ev IN SELECT value FROM jsonb_array_elements(manifest) LOOP
 SELECT * INTO obj FROM storage.objects WHERE bucket_id='aplicacao-evidencias' AND name=ev->>'storage_path' FOR SHARE;
 IF NOT FOUND OR coalesce(obj.owner_id,obj.owner::text) IS DISTINCT FROM u::text
 OR obj.metadata->>'mimetype' IS DISTINCT FROM ev->>'mime' OR nullif(obj.metadata->>'size','')::bigint IS DISTINCT FROM (ev->>'tamanho_bytes')::bigint
 OR obj.version IS NULL THEN RAISE EXCEPTION 'application_object_denied' USING ERRCODE='42501'; END IF;
 END LOOP;
 -- Metadata and latest-version switch are a single transaction. No OS/communications effects.
 IF p_rectify_id IS NOT NULL THEN UPDATE public.aplicacoes SET is_latest=false WHERE id=p_rectify_id; END IF;
 INSERT INTO public.aplicacoes(id,organization_id,ordem_servico_id,ordem_servico_onfarm_id,data_aplicacao,hora_inicio,hora_fim,responsavel_id,responsavel,modo_aplicacao,produto_usado_id,lote_usado_id,dose_aplicada,volume_calda_l_ha,volume_total_aplicado_ml,area_aplicada_ha,equipamento,equipamento_modelo,bico_tipo,pressao_bar,temperatura_c,umidade_pct,vento_kmh,condicoes_climaticas,latitude,longitude,resultado_inicial,observacoes,created_by,parent_id,versao,motivo_retificacao,is_latest)
 VALUES(p_aplicacao_id,org,osid,onid,moment,start_at,end_at,responsible,name_responsible,nullif(btrim(canonical->>'modo_aplicacao'),''),product,lot,(canonical->>'dose_aplicada')::numeric,(canonical->>'volume_calda_l_ha')::numeric,(canonical->>'volume_total_aplicado_ml')::numeric,(canonical->>'area_aplicada_ha')::numeric,nullif(btrim(canonical->>'equipamento'),''),nullif(btrim(canonical->>'equipamento_modelo'),''),nullif(btrim(canonical->>'bico_tipo'),''),(canonical->>'pressao_bar')::numeric,(canonical->>'temperatura_c')::numeric,(canonical->>'umidade_pct')::numeric,(canonical->>'vento_kmh')::numeric,nullif(btrim(canonical->>'condicoes_climaticas'),''),(canonical->>'latitude')::numeric,(canonical->>'longitude')::numeric,nullif(canonical->>'resultado_inicial',''),nullif(btrim(canonical->>'observacoes'),''),u,root,ver,CASE WHEN p_rectify_id IS NULL THEN NULL ELSE btrim(canonical->>'motivo_retificacao') END,true);
 FOR ev IN SELECT value FROM jsonb_array_elements(manifest) LOOP
 INSERT INTO public.aplicacao_evidencias(aplicacao_id,tipo,storage_path,legenda,mime,tamanho_bytes,created_by,versao_origem_id)
 VALUES(p_aplicacao_id,ev->>'tipo',ev->>'storage_path',nullif(btrim(ev->>'legenda'),''),ev->>'mime',(ev->>'tamanho_bytes')::bigint,u,p_aplicacao_id) RETURNING id INTO ev_id;
 INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,ev_id);
 END LOOP;
 FOREACH kept IN ARRAY p_evidencias_manter LOOP INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,kept); END LOOP;
 UPDATE platform_private.application_save_preparations SET committed_at=clock_timestamp() WHERE application_id=p_aplicacao_id;
 RETURN jsonb_build_object('success',true,'created',true,'id',p_aplicacao_id,'versao',ver,'phase','finalized');
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_claim_org_admin_provisioning(p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_modo_acesso text DEFAULT 'link'::text, p_responsavel_principal boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_email text := lower(btrim(coalesce(p_email,'')));
  v_cpf text := nullif(regexp_replace(coalesce(p_cpf_cnpj,''), '\D', '', 'g'),'');
  v_tel text := nullif(regexp_replace(coalesce(p_telefone,''), '\D', '', 'g'),'');
  v_row public.platform_org_admin_invites%ROWTYPE;
  v_token uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL OR NOT public.is_platform_superadmin(v_actor) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin de plataforma' USING ERRCODE='42501';
  END IF;
  IF p_organization_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.organizations o WHERE o.id=p_organization_id AND o.ativo IS TRUE
  ) THEN RAISE EXCEPTION 'platform_invalid: empresa inexistente ou inativa'; END IF;
  IF v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR length(v_email)>255
     OR length(btrim(coalesce(p_nome,''))) NOT BETWEEN 3 AND 200 THEN
    RAISE EXCEPTION 'platform_invalid: nome ou e-mail inválido';
  END IF;
  IF v_cpf IS NOT NULL AND length(v_cpf)<>11 THEN RAISE EXCEPTION 'platform_invalid: cpf'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN (10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone'; END IF;
  IF p_modo_acesso NOT IN ('link','senha_temporaria') THEN RAISE EXCEPTION 'platform_invalid: modo'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_email, 0));
  SELECT * INTO v_row FROM public.platform_org_admin_invites WHERE lower(email)=v_email FOR UPDATE;

  IF FOUND THEN
 IF EXISTS(SELECT 1 FROM public.platform_org_admin_email_changes c WHERE c.invite_id=v_row.id AND c.status IN ('requested','auth_updated','failed')) THEN RAISE EXCEPTION 'email_change_pending' USING ERRCODE='55P03'; END IF;
    IF v_row.organization_id <> p_organization_id THEN
      RAISE EXCEPTION 'platform_conflict: e-mail já vinculado a outra empresa' USING ERRCODE='23505';
    END IF;
    IF v_row.status='ativo' THEN
      RETURN jsonb_build_object('job_id',v_row.id,'request_id',v_row.request_id,'status','ativo','user_id',v_row.user_id,'completed',true);
    END IF;
    IF v_row.lease_expires_at IS NOT NULL AND v_row.lease_expires_at > clock_timestamp() THEN
      RAISE EXCEPTION 'platform_conflict: provisionamento em andamento' USING ERRCODE='55P03';
    END IF;
    IF (v_row.nome, v_row.cpf_cnpj, v_row.telefone, v_row.modo_acesso, v_row.responsavel_principal)
       IS DISTINCT FROM (btrim(p_nome), v_cpf, v_tel, p_modo_acesso, p_responsavel_principal) THEN
      RAISE EXCEPTION 'platform_conflict: dados divergentes para o mesmo e-mail' USING ERRCODE='23505';
    END IF;
    UPDATE public.platform_org_admin_invites
       SET status='processando', lease_token=v_token,
           lease_expires_at=clock_timestamp()+interval '2 minutes',
           attempt_count=attempt_count+1, last_error_code=NULL, updated_at=now()
     WHERE id=v_row.id
     RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.platform_org_admin_invites(
      organization_id,user_id,email,nome,cpf_cnpj,telefone,modo_acesso,
      responsavel_principal,invited_by,status,request_id,attempt_count,
      lease_token,lease_expires_at,updated_at)
    VALUES (
      p_organization_id,NULL,v_email,btrim(p_nome),v_cpf,v_tel,p_modo_acesso,
      p_responsavel_principal,v_actor,'processando',gen_random_uuid(),1,
      v_token,clock_timestamp()+interval '2 minutes',now())
    RETURNING * INTO v_row;
  END IF;

  RETURN jsonb_build_object('job_id',v_row.id,'request_id',v_row.request_id,
    'status',v_row.status,'lease_token',v_token,'lease_expires_at',v_row.lease_expires_at,
    'user_id',v_row.user_id,'completed',false);
END
$function$

CREATE OR REPLACE FUNCTION public.set_my_context_preference(p_context text, p_remember boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_previous text;
  v_action text;
  v_available jsonb;
BEGIN
  IF v_uid IS NULL OR NOT platform_private.platform_actor_access_ready(v_uid) OR public.h15_actor_organization() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_context IS NULL OR p_context NOT IN ('b2b','technical','producer','admin') THEN
    RAISE EXCEPTION 'invalid context %', p_context;
  END IF;

  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'c2_guard_unavailable'; END IF;
  v_available := public.get_my_available_portal_contexts();

  IF NOT (v_available->'available_contexts' ? p_context) THEN
    -- Grava auditoria e retorna erro em JSON (sem RAISE).
    -- Sem exception, sem rollback: o INSERT persiste.
    INSERT INTO public.user_context_access_logs (
      user_id, context_code, action, previous_context, metadata
    ) VALUES (
      v_uid, p_context, 'access_denied', NULL,
      jsonb_build_object('reason','context_not_available')
    );

    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'context_not_available',
      'context', p_context
    );
  END IF;

  SELECT last_context INTO v_previous
  FROM public.user_access_preferences
  WHERE user_id = v_uid;

  -- Upsert com semântica correta para p_remember=false (limpar preferência)
  INSERT INTO public.user_access_preferences (
    user_id, last_context, preferred_context, skip_context_selector
  ) VALUES (
    v_uid,
    p_context,
    CASE WHEN p_remember THEN p_context ELSE NULL END,
    COALESCE(p_remember, false)
  )
  ON CONFLICT (user_id) DO UPDATE
    SET last_context = EXCLUDED.last_context,
        preferred_context = CASE
          WHEN p_remember THEN EXCLUDED.last_context
          ELSE NULL
        END,
        skip_context_selector = COALESCE(p_remember, false),
        updated_at = now();

  v_action := CASE
    WHEN v_previous IS NULL THEN 'context_selected'
    WHEN v_previous = p_context THEN 'context_selected'
    ELSE 'context_switched'
  END;

  INSERT INTO public.user_context_access_logs (
    user_id, context_code, action, previous_context, metadata
  ) VALUES (
    v_uid, p_context, v_action, v_previous,
    jsonb_build_object('remember', COALESCE(p_remember, false))
  );

  RETURN jsonb_build_object(
    'ok', true,
    'context', p_context,
    'remembered', COALESCE(p_remember, false)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_claim_org_admin_provisioning(p_actor_id uuid, p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_modo_acesso text DEFAULT 'link'::text, p_responsavel_principal boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text; v_email text:=lower(btrim(coalesce(p_email,''))); v_cpf text:=nullif(regexp_replace(coalesce(p_cpf_cnpj,''),'\D','','g'),''); v_tel text:=nullif(regexp_replace(coalesce(p_telefone,''),'\D','','g'),''); j public.platform_org_admin_invites%ROWTYPE; token uuid:=gen_random_uuid();
BEGIN
 v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
 IF v_role<>'service_role' OR p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 IF p_organization_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=p_organization_id AND o.ativo IS TRUE) THEN RAISE EXCEPTION 'platform_invalid: empresa'; END IF;
 IF v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR length(v_email)>255 OR length(btrim(coalesce(p_nome,''))) NOT BETWEEN 3 AND 200 THEN RAISE EXCEPTION 'platform_invalid: identidade'; END IF;
 IF v_cpf IS NOT NULL AND length(v_cpf)<>11 THEN RAISE EXCEPTION 'platform_invalid: cpf'; END IF;
 IF v_tel IS NOT NULL AND length(v_tel) NOT IN(10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone'; END IF;
 IF p_modo_acesso NOT IN('link','senha_temporaria') THEN RAISE EXCEPTION 'platform_invalid: modo'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_email,0));
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE lower(email)=v_email FOR UPDATE;
 IF FOUND THEN
 IF EXISTS(SELECT 1 FROM public.platform_org_admin_email_changes c WHERE c.invite_id=j.id AND c.status IN ('requested','auth_updated','failed')) THEN RAISE EXCEPTION 'email_change_pending' USING ERRCODE='55P03'; END IF;
  IF j.organization_id<>p_organization_id THEN RAISE EXCEPTION 'platform_conflict: outro tenant' USING ERRCODE='23505'; END IF;
  IF j.status='ativo' THEN RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status','ativo','user_id',j.user_id,'completed',true); END IF;
  IF j.lease_expires_at IS NOT NULL AND j.lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_conflict: em andamento' USING ERRCODE='55P03'; END IF;
  IF (j.nome,j.cpf_cnpj,j.telefone,j.modo_acesso,j.responsavel_principal) IS DISTINCT FROM (btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal) THEN RAISE EXCEPTION 'platform_conflict: dados divergentes' USING ERRCODE='23505'; END IF;
  UPDATE public.platform_org_admin_invites SET status='processando',lease_token=token,lease_expires_at=clock_timestamp()+interval '2 minutes',attempt_count=attempt_count+1,last_error_code=NULL,updated_at=now() WHERE id=j.id RETURNING * INTO j;
 ELSE
  INSERT INTO public.platform_org_admin_invites(organization_id,user_id,email,nome,cpf_cnpj,telefone,modo_acesso,responsavel_principal,invited_by,status,request_id,attempt_count,lease_token,lease_expires_at,updated_at)
  VALUES(p_organization_id,NULL,v_email,btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal,p_actor_id,'processando',gen_random_uuid(),1,token,clock_timestamp()+interval '2 minutes',now()) RETURNING * INTO j;
 END IF;
 RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status',j.status,'lease_token',token,'lease_expires_at',j.lease_expires_at,'user_id',j.user_id,'completed',false);
END $function$

CREATE OR REPLACE FUNCTION public.platform_find_org_admin_provisioning_auth_user(p_job_id uuid, p_lease_token uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text; j public.platform_org_admin_invites%ROWTYPE; found_id uuid;
BEGIN
 v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
 IF v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id;
 IF NOT FOUND OR j.status<>'processando' OR j.lease_token IS DISTINCT FROM p_lease_token OR j.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'platform_stale_lease' USING ERRCODE='55P03'; END IF;
 SELECT u.id INTO found_id FROM auth.users u WHERE lower(u.email)=lower(j.email) AND u.raw_app_meta_data->>'provisioning_request_id'=j.request_id::text ORDER BY u.created_at LIMIT 1;
 RETURN found_id;
END $function$

CREATE OR REPLACE FUNCTION public.platform_accept_org_admin_email_delivery(p_job_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
BEGIN
  v_role := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_forbidden: uso restrito ao backend' USING ERRCODE='42501';
  END IF;
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.email_delivery_status='accepted' THEN
    RETURN jsonb_build_object('status','accepted','idempotent',true);
  END IF;
  IF j.email_delivery_status<>'sending' OR j.email_lease_token IS DISTINCT FROM p_lease_token
     OR j.email_lease_expires_at IS NULL OR j.email_lease_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'platform_stale_lease: confirmação sem reserva vigente' USING ERRCODE='55P03';
  END IF;
  UPDATE public.platform_org_admin_invites
     SET email_delivery_status='accepted',email_accepted_at=now(),email_failed_at=NULL,
         email_lease_token=NULL,email_lease_expires_at=NULL,email_last_error_code=NULL,updated_at=now()
   WHERE id=j.id AND email_lease_token=p_lease_token;
  RETURN jsonb_build_object('status','accepted','idempotent',false);
END
$function$

CREATE OR REPLACE FUNCTION public.platform_fail_org_admin_email_delivery(p_job_id uuid, p_lease_token uuid, p_error_code text, p_retry_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
  v_code text := left(regexp_replace(coalesce(nullif(btrim(p_error_code),''),'email_failed'),'[^a-zA-Z0-9_:-]','','g'),80);
BEGIN
  v_role := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_forbidden: uso restrito ao backend' USING ERRCODE='42501';
  END IF;
  IF p_retry_seconds < 30 OR p_retry_seconds > 86400 THEN
    RAISE EXCEPTION 'platform_invalid: retry inválido' USING ERRCODE='22023';
  END IF;
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.email_delivery_status<>'sending' OR j.email_lease_token IS DISTINCT FROM p_lease_token
     OR j.email_lease_expires_at IS NULL OR j.email_lease_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'platform_stale_lease: falha sem reserva vigente' USING ERRCODE='55P03';
  END IF;
  UPDATE public.platform_org_admin_invites
     SET email_delivery_status='failed',email_failed_at=now(),email_lease_token=NULL,
         email_lease_expires_at=NULL,email_last_error_code=v_code,
         email_next_attempt_at=clock_timestamp()+make_interval(secs=>p_retry_seconds),updated_at=now()
   WHERE id=j.id AND email_lease_token=p_lease_token;
  RETURN jsonb_build_object('status','failed','code',v_code);
END
$function$

CREATE OR REPLACE FUNCTION public.platform_claim_org_admin_email_delivery(p_job_id uuid, p_cooldown_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
  v_token uuid := gen_random_uuid();
  v_idempotency uuid;
BEGIN
  v_role := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_forbidden: uso restrito ao backend' USING ERRCODE='42501';
  END IF;
  IF p_cooldown_seconds < 30 OR p_cooldown_seconds > 86400 THEN
    RAISE EXCEPTION 'platform_invalid: cooldown inválido' USING ERRCODE='22023';
  END IF;

  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.modo_acesso <> 'link' OR j.user_id IS NULL OR j.status NOT IN ('pendente','ativo') THEN
    RAISE EXCEPTION 'platform_invalid: convite ainda não está pronto para envio' USING ERRCODE='22023';
  END IF;
  IF j.email_delivery_status='sending' AND j.email_lease_expires_at > clock_timestamp() THEN
    RAISE EXCEPTION 'platform_email_busy: envio já reservado' USING ERRCODE='55P03';
  END IF;
  IF j.email_next_attempt_at > clock_timestamp() THEN
    RAISE EXCEPTION 'platform_email_cooldown: reenvio em cooldown' USING ERRCODE='55P03';
  END IF;

  v_idempotency := CASE
    WHEN j.email_delivery_status='accepted' THEN gen_random_uuid()
    ELSE j.email_idempotency_key
  END;

  UPDATE public.platform_org_admin_invites
     SET email_delivery_status='sending',
         email_attempt_count=email_attempt_count+1,
         email_idempotency_key=v_idempotency,
         email_lease_token=v_token,
         email_lease_expires_at=clock_timestamp()+interval '2 minutes',
         email_last_attempt_at=now(),
         email_last_error_code=NULL,
         email_next_attempt_at=clock_timestamp()+make_interval(secs=>p_cooldown_seconds),
         updated_at=now()
   WHERE id=j.id;

  RETURN jsonb_build_object(
    'job_id',j.id,
    'lease_token',v_token,
    'idempotency_key',v_idempotency,
    'recipient_email',lower(j.email),
    'recipient_name',j.nome
  );
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_b2b_financial_kpis(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_partner_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_from date := COALESCE(p_from, date_trunc('month', CURRENT_DATE)::date);
  v_to date := COALESCE(p_to, CURRENT_DATE);
  v_result jsonb;
BEGIN
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'financeiro') OR has_role(v_uid,'gestor') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;

  WITH ar AS (
    SELECT a.*, i.due_date, i.original_amount, i.received_amount, i.status AS inst_status
    FROM public.accounts_receivable a
    JOIN public.accounts_receivable_installments i ON i.receivable_id = a.id
    WHERE a.origin_type='B2B_ORDER'
      AND a.created_at::date BETWEEN v_from AND v_to
      AND (p_partner_id IS NULL OR a.partner_id = p_partner_id)
  )
  SELECT jsonb_build_object(
    'total_a_receber', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL','OVERDUE') THEN original_amount - COALESCE(received_amount,0) END),0),
    'total_recebido', COALESCE(SUM(received_amount),0),
    'total_vencido', COALESCE(SUM(CASE WHEN inst_status='OVERDUE' OR (inst_status IN ('OPEN','PARTIAL') AND due_date < CURRENT_DATE) THEN original_amount - COALESCE(received_amount,0) END),0),
    'total_em_aberto', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL') THEN original_amount - COALESCE(received_amount,0) END),0),
    'ticket_medio', COALESCE(AVG(total_amount),0),
    'vencendo_7d', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL') AND due_date BETWEEN CURRENT_DATE AND CURRENT_DATE+7 THEN original_amount - COALESCE(received_amount,0) END),0)
  ) INTO v_result FROM ar;

  v_result := v_result || jsonb_build_object(
    'pedidos_entregues_sem_cobranca', (
      SELECT COUNT(*) FROM public.partner_orders po
      WHERE po.status='entregue' AND po.receivable_generated=false
        AND (p_partner_id IS NULL OR po.partner_id = p_partner_id)
    ),
    'parceiros_inadimplentes', (
      SELECT COUNT(DISTINCT partner_id) FROM public.accounts_receivable a
      JOIN public.accounts_receivable_installments i ON i.receivable_id=a.id
      WHERE a.origin_type='B2B_ORDER' AND (i.status='OVERDUE' OR (i.status IN ('OPEN','PARTIAL') AND i.due_date < CURRENT_DATE))
    )
  );

  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_b2b_governance_kpis()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_concedido numeric := 0;
  v_total_utilizado numeric := 0;
  v_total_disponivel numeric := 0;
  v_bloqueados int := 0;
  v_vencidos numeric := 0;
  v_recebido_mes numeric := 0;
  v_inad_pct numeric := 0;
  v_receita numeric := 0;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(SUM(credit_limit),0) INTO v_total_concedido
    FROM public.partner_financial_settings WHERE active;

  SELECT COALESCE(SUM((ari.original_amount - ari.received_amount)),0) INTO v_total_utilizado
    FROM public.accounts_receivable ar
    JOIN public.accounts_receivable_installments ari ON ari.receivable_id = ar.id
   WHERE ar.origin_type = 'B2B_ORDER' AND ar.status <> 'CANCELED'
     AND ari.status IN ('OPEN','PARTIAL','OVERDUE');

  v_total_disponivel := GREATEST(v_total_concedido - v_total_utilizado, 0);

  SELECT COUNT(DISTINCT partner_id) INTO v_bloqueados
    FROM public.partner_orders WHERE status = 'aguardando_aprovacao_credito';

  SELECT COALESCE(SUM(ari.original_amount - ari.received_amount),0) INTO v_vencidos
    FROM public.accounts_receivable ar
    JOIN public.accounts_receivable_installments ari ON ari.receivable_id = ar.id
   WHERE ar.origin_type = 'B2B_ORDER' AND ar.status <> 'CANCELED'
     AND ari.status IN ('OPEN','PARTIAL','OVERDUE') AND ari.due_date < current_date;

  SELECT COALESCE(SUM(rp.amount_received),0) INTO v_recebido_mes
    FROM public.receivable_payments rp
    JOIN public.accounts_receivable_installments ari ON ari.id = rp.installment_id
    JOIN public.accounts_receivable ar ON ar.id = ari.receivable_id
   WHERE ar.origin_type = 'B2B_ORDER'
     AND date_trunc('month', rp.payment_date) = date_trunc('month', current_date);

  SELECT COALESCE(SUM(total),0) INTO v_receita
    FROM public.partner_orders
   WHERE status IN ('entregue','faturado')
     AND date_trunc('month', created_at) = date_trunc('month', current_date);

  v_inad_pct := CASE WHEN v_total_utilizado > 0
                     THEN ROUND((v_vencidos / v_total_utilizado) * 100, 2)
                     ELSE 0 END;

  RETURN jsonb_build_object(
    'credito_total_concedido', v_total_concedido,
    'credito_utilizado', v_total_utilizado,
    'credito_disponivel', v_total_disponivel,
    'parceiros_bloqueados', v_bloqueados,
    'titulos_vencidos', v_vencidos,
    'recebimentos_mes', v_recebido_mes,
    'inadimplencia_pct', v_inad_pct,
    'receita_b2b_mes', v_receita
  );
END;$function$

CREATE OR REPLACE FUNCTION public.platform_claim_org_admin_provisioning(p_actor_id uuid, p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_modo_acesso text DEFAULT 'link'::text, p_responsavel_principal boolean DEFAULT true, p_confirm_ambiguous_email_retry boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text;
  v_email text:=lower(btrim(coalesce(p_email,'')));
  v_cpf text:=nullif(regexp_replace(coalesce(p_cpf_cnpj,''),'\D','','g'),'');
  v_tel text:=nullif(regexp_replace(coalesce(p_telefone,''),'\D','','g'),'');
  j public.platform_org_admin_invites%ROWTYPE;
  token uuid:=gen_random_uuid();
  v_ambiguous boolean;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role<>'service_role' OR p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_organization_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=p_organization_id AND o.ativo IS TRUE) THEN RAISE EXCEPTION 'platform_invalid: empresa'; END IF;
  IF v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR length(v_email)>255 OR length(btrim(coalesce(p_nome,''))) NOT BETWEEN 3 AND 200 THEN RAISE EXCEPTION 'platform_invalid: identidade'; END IF;
  IF v_cpf IS NOT NULL AND length(v_cpf)<>11 THEN RAISE EXCEPTION 'platform_invalid: cpf'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN(10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone'; END IF;
  IF p_modo_acesso NOT IN('link','senha_temporaria') THEN RAISE EXCEPTION 'platform_invalid: modo'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_email,0));
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE lower(email)=v_email FOR UPDATE;
  IF FOUND THEN
 IF EXISTS(SELECT 1 FROM public.platform_org_admin_email_changes c WHERE c.invite_id=j.id AND c.status IN ('requested','auth_updated','failed')) THEN RAISE EXCEPTION 'email_change_pending' USING ERRCODE='55P03'; END IF;
    IF j.organization_id<>p_organization_id THEN RAISE EXCEPTION 'platform_conflict: outro tenant' USING ERRCODE='23505'; END IF;
    IF j.status='ativo' THEN RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status','ativo','user_id',j.user_id,'completed',true); END IF;
    IF j.lease_expires_at IS NOT NULL AND j.lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_conflict: em andamento' USING ERRCODE='55P03'; END IF;
    IF (j.nome,j.cpf_cnpj,j.telefone,j.modo_acesso,j.responsavel_principal) IS DISTINCT FROM (btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal) THEN RAISE EXCEPTION 'platform_conflict: dados divergentes' USING ERRCODE='23505'; END IF;
    v_ambiguous := j.email_delivery_status='ambiguous' OR (
      j.email_delivery_status='failed' AND j.email_last_error_code IN (
        'email_unknown_error','email_send_ambiguous','email_accept_persistence_failed',
        'email_timeout','email_network_error','email_send_crash','email_delivery_setup_failed'
      )
    );
    IF v_ambiguous AND NOT coalesce(p_confirm_ambiguous_email_retry,false) THEN
      RAISE EXCEPTION 'email_ambiguous_confirmation_required' USING ERRCODE='P0001';
    END IF;
    IF j.email_next_attempt_at > clock_timestamp() THEN
      RAISE EXCEPTION 'platform_email_cooldown: reenvio em cooldown' USING ERRCODE='55P03';
    END IF;
    UPDATE public.platform_org_admin_invites SET status='processando',lease_token=token,lease_expires_at=clock_timestamp()+interval '2 minutes',attempt_count=attempt_count+1,last_error_code=NULL,updated_at=now() WHERE id=j.id RETURNING * INTO j;
  ELSE
    INSERT INTO public.platform_org_admin_invites(organization_id,user_id,email,nome,cpf_cnpj,telefone,modo_acesso,responsavel_principal,invited_by,status,request_id,attempt_count,lease_token,lease_expires_at,updated_at)
    VALUES(p_organization_id,NULL,v_email,btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal,p_actor_id,'processando',gen_random_uuid(),1,token,clock_timestamp()+interval '2 minutes',now()) RETURNING * INTO j;
  END IF;
  RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status',j.status,'lease_token',token,'lease_expires_at',j.lease_expires_at,'user_id',j.user_id,'completed',false);
END $function$

CREATE OR REPLACE FUNCTION public.platform_claim_org_admin_email_delivery(p_job_id uuid, p_actor_id uuid, p_confirm_ambiguous_email_retry boolean DEFAULT false, p_cooldown_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
  v_token uuid:=gen_random_uuid();
  v_idempotency uuid;
  v_ambiguous boolean;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role<>'service_role' OR p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_cooldown_seconds<30 OR p_cooldown_seconds>86400 THEN RAISE EXCEPTION 'platform_invalid: cooldown inválido' USING ERRCODE='22023'; END IF;
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.modo_acesso<>'link' OR j.user_id IS NULL OR j.status NOT IN('pendente','ativo') THEN RAISE EXCEPTION 'platform_invalid: convite ainda não está pronto para envio' USING ERRCODE='22023'; END IF;
  v_ambiguous := j.email_delivery_status='ambiguous' OR (j.email_delivery_status='failed' AND j.email_last_error_code IN('email_unknown_error','email_send_ambiguous','email_accept_persistence_failed','email_timeout','email_network_error','email_send_crash','email_delivery_setup_failed'));
  IF v_ambiguous AND NOT coalesce(p_confirm_ambiguous_email_retry,false) THEN RAISE EXCEPTION 'email_ambiguous_confirmation_required' USING ERRCODE='P0001'; END IF;
  IF j.email_delivery_status='sending' AND j.email_lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_email_busy: envio já reservado' USING ERRCODE='55P03'; END IF;
  IF j.email_next_attempt_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_email_cooldown: reenvio em cooldown' USING ERRCODE='55P03'; END IF;
  IF v_ambiguous THEN
    INSERT INTO public.comunicacao_audit_log(acao,entidade,entity_id,actor_id,before_state,after_state)
    VALUES('invite.email_ambiguous_retry_confirmed','platform_org_admin_invites',j.id,p_actor_id,
      jsonb_build_object('delivery_status',j.email_delivery_status,'safe_code',j.email_last_error_code),
      jsonb_build_object('confirmation','nao_recebimento_confirmado','next_action','retry_claimed'));
  END IF;
  v_idempotency:=CASE WHEN j.email_delivery_status='accepted' THEN gen_random_uuid() ELSE j.email_idempotency_key END;
  UPDATE public.platform_org_admin_invites SET email_delivery_status='sending',email_attempt_count=email_attempt_count+1,email_idempotency_key=v_idempotency,email_lease_token=v_token,email_lease_expires_at=clock_timestamp()+interval '2 minutes',email_last_attempt_at=now(),email_last_error_code=NULL,email_next_attempt_at=clock_timestamp()+make_interval(secs=>p_cooldown_seconds),updated_at=now() WHERE id=j.id;
  RETURN jsonb_build_object('job_id',j.id,'lease_token',v_token,'idempotency_key',v_idempotency,'recipient_email',lower(j.email),'recipient_name',j.nome);
END $function$

CREATE OR REPLACE FUNCTION public.platform_mark_org_admin_email_ambiguous(p_job_id uuid, p_lease_token uuid, p_error_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text; j public.platform_org_admin_invites%ROWTYPE; v_code text;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
