CREATE OR REPLACE FUNCTION public.generate_b2b_receivable_secure(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;

  IF auth.uid() IS NULL THEN
    IF pg_trigger_depth()=0 THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  ELSIF NOT (public.b2b_phase1_order_visible(p_partner_order_id) OR EXISTS (
    SELECT 1 FROM public.partner_orders po WHERE po.id=p_partner_order_id
      AND platform_private.c2p1_settings_allowed(po.partner_id,true))) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF NOT (pg_trigger_depth() > 0 or public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND internal_origin_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'B2B_INTERNAL_DOWNSTREAM_UNVERIFIED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1') THEN RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501'; END IF;
  IF p_partner_order_id IS NULL THEN
    RAISE EXCEPTION 'partner_order_id_required' USING ERRCODE='P0001';
  END IF;

  -- Canonical row-before-receipt order, matching approval and its billing trigger.
  PERFORM 1 FROM public.partner_orders WHERE id=p_partner_order_id FOR UPDATE;

  -- Serializa concorrencia real (clique duplo / chamadas simultaneas).
  -- Chave unica bigint: assinatura pg_advisory_xact_lock(bigint).
  PERFORM pg_advisory_xact_lock(
    hashtextextended('b2b_receivable:' || p_partner_order_id::text, 0)
  );

  IF NOT public.fn_b2b_order_priceable(p_partner_order_id) THEN
    RAISE EXCEPTION 'order_not_priceable_quote_required' USING ERRCODE='P0001';
  END IF;

  RETURN public.generate_b2b_receivable_secure_impl(p_partner_order_id);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_executivo_timeline_operacional(p_filtros jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_uid uuid := auth.uid();
 v_org uuid;
 v_filtros jsonb := COALESCE(p_filtros, '{}'::jsonb);
 v_periodo text;
 v_inicio timestamptz;
 v_fim timestamptz := pg_catalog.now();
 v_lim integer := LEAST(GREATEST(COALESCE(p_limit,20),1),100);
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_AUTH_REQUIRED'; END IF;
 IF pg_catalog.jsonb_typeof(auth.jwt()->'iat') IS DISTINCT FROM 'number' OR COALESCE(auth.jwt()->>'iat','') !~ '^[0-9]{1,12}$' THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_SESSION_IAT_REQUIRED'; END IF;
 IF (auth.jwt()->>'iat')::bigint <= 0 THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_SESSION_IAT_REQUIRED'; END IF;
 v_org := platform_private.h15_actor_organization();
 IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id=v_uid AND ur.role IN ('administrador'::public.app_role,'gestor'::public.app_role)) THEN
  RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_ACTIVE_ACTOR_TENANT_ROLE_REQUIRED';
 END IF;
 IF pg_catalog.jsonb_typeof(v_filtros) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='EXECUTIVO_INVALID_FILTERS'; END IF;
 IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_each(v_filtros) f WHERE f.key IN ('organization_id','tenant_id','cliente_id','fazenda_id') AND f.value NOT IN ('null'::jsonb,'""'::jsonb)) THEN
  RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_UNPROVEN_SCOPE_FILTER';
 END IF;
 v_periodo := COALESCE(v_filtros->>'periodo','30_dias');
 IF v_periodo='personalizado' THEN
  IF NULLIF(v_filtros->>'data_inicio','') IS NULL OR NULLIF(v_filtros->>'data_fim','') IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='EXECUTIVO_INVALID_PERIOD'; END IF;
  BEGIN v_inicio := (v_filtros->>'data_inicio')::timestamptz; v_fim := (v_filtros->>'data_fim')::timestamptz;
  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='EXECUTIVO_INVALID_PERIOD'; END;
  IF NOT pg_catalog.isfinite(v_inicio) OR NOT pg_catalog.isfinite(v_fim) OR v_inicio>v_fim THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='EXECUTIVO_INVALID_PERIOD'; END IF;
 ELSIF v_periodo='hoje' THEN v_inicio := pg_catalog.date_trunc('day',pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo';
 ELSIF v_periodo='7_dias' THEN v_inicio := pg_catalog.now()-interval '7 days';
 ELSIF v_periodo='15_dias' THEN v_inicio := pg_catalog.now()-interval '15 days';
 ELSIF v_periodo='safra_atual' THEN v_inicio := pg_catalog.date_trunc('year',pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo';
 ELSE v_periodo := '30_dias'; v_inicio := pg_catalog.now()-interval '30 days'; END IF;
 -- No source is read until its ownership chain is proven; NULL legacy ownership is never inferred.
 RETURN pg_catalog.jsonb_build_object('eventos','[]'::jsonb,'periodo',pg_catalog.jsonb_build_object('data_inicio',v_inicio,'data_fim',v_fim,'periodo',v_periodo),'dados_indisponiveis',pg_catalog.jsonb_build_array('timeline_geral','solicitacoes','os','envase','entregas','alertas_operacionais'),'gerado_em',pg_catalog.now(),'organization_scoped',true,'limite',v_lim,'motivo_indisponibilidade','Fontes sem vínculo organizacional comprovado');
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_executivo_gargalos(p_filtros jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_uid uuid := auth.uid();
 v_org uuid;
 v_filtros jsonb := COALESCE(p_filtros,'{}'::jsonb);
 v_lim integer := LEAST(GREATEST(COALESCE(p_limit,10),1),50);
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_AUTH_REQUIRED'; END IF;
 IF pg_catalog.jsonb_typeof(auth.jwt()->'iat') IS DISTINCT FROM 'number' OR COALESCE(auth.jwt()->>'iat','') !~ '^[0-9]{1,12}$' THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_SESSION_IAT_REQUIRED'; END IF;
 IF (auth.jwt()->>'iat')::bigint <= 0 THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_SESSION_IAT_REQUIRED'; END IF;
 v_org := platform_private.h15_actor_organization();
 IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id=v_uid AND ur.role IN ('administrador'::public.app_role,'gestor'::public.app_role)) THEN
  RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_ACTIVE_ACTOR_TENANT_ROLE_REQUIRED';
 END IF;
 IF pg_catalog.jsonb_typeof(v_filtros) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='EXECUTIVO_INVALID_FILTERS'; END IF;
 IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_each(v_filtros) f WHERE f.key IN ('organization_id','tenant_id','cliente_id','fazenda_id') AND f.value NOT IN ('null'::jsonb,'""'::jsonb)) THEN
  RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='EXECUTIVO_UNPROVEN_SCOPE_FILTER';
 END IF;
 -- Containment mirrors the executive summary; no legacy operational or commercial records are queried.
 RETURN pg_catalog.jsonb_build_object('gargalos','[]'::jsonb,'dados_indisponiveis',pg_catalog.jsonb_build_array('os_atrasadas','entregas_sem_comprovante','entregas_nao_faturadas','embalagens_sem_etiqueta','alertas_operacionais'),'gerado_em',pg_catalog.now(),'organization_scoped',true,'limite',v_lim,'motivo_indisponibilidade','Fontes sem vínculo organizacional comprovado');
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_claim_org_admin_provisioning(p_actor_id uuid, p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_modo_acesso text DEFAULT 'link'::text, p_responsavel_principal boolean DEFAULT true, p_confirm_ambiguous_email_retry boolean DEFAULT false, p_delivery_mode text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text;
  v_email text:=lower(btrim(coalesce(p_email,'')));
  v_cpf text:=nullif(regexp_replace(coalesce(p_cpf_cnpj,''),'\D','','g'),'');
  v_tel text:=nullif(regexp_replace(coalesce(p_telefone,''),'\D','','g'),'');
  j public.platform_org_admin_invites%ROWTYPE;
  token uuid:=gen_random_uuid();
  v_ambiguous boolean;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role<>'service_role' OR p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_delivery_mode NOT IN('email','manual_link') THEN RAISE EXCEPTION 'platform_invalid: delivery mode' USING ERRCODE='22023'; END IF;
  IF p_delivery_mode='manual_link' AND p_modo_acesso<>'link' THEN RAISE EXCEPTION 'platform_invalid: manual link requires link access' USING ERRCODE='22023'; END IF;
  IF p_organization_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=p_organization_id AND o.ativo IS TRUE) THEN RAISE EXCEPTION 'platform_invalid: empresa'; END IF;
  IF v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR length(v_email)>255 OR length(btrim(coalesce(p_nome,''))) NOT BETWEEN 3 AND 200 THEN RAISE EXCEPTION 'platform_invalid: identidade'; END IF;
  IF v_cpf IS NOT NULL AND length(v_cpf)<>11 THEN RAISE EXCEPTION 'platform_invalid: cpf'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN(10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone'; END IF;
  IF p_modo_acesso NOT IN('link','senha_temporaria') THEN RAISE EXCEPTION 'platform_invalid: modo'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_email,0));
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE lower(email)=v_email FOR UPDATE;
  IF FOUND THEN
 IF EXISTS(SELECT 1 FROM public.platform_org_admin_email_changes c WHERE c.invite_id=j.id AND c.status IN ('requested','auth_updated','failed')) THEN RAISE EXCEPTION 'email_change_pending' USING ERRCODE='55P03'; END IF;
    IF j.organization_id<>p_organization_id THEN RAISE EXCEPTION 'platform_conflict: outro tenant' USING ERRCODE='23505'; END IF;
    IF j.status='ativo' THEN RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status','ativo','user_id',j.user_id,'completed',true); END IF;
    IF j.lease_expires_at IS NOT NULL AND j.lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_conflict: em andamento' USING ERRCODE='55P03'; END IF;
    IF (j.nome,j.cpf_cnpj,j.telefone,j.modo_acesso,j.responsavel_principal) IS DISTINCT FROM (btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal) THEN RAISE EXCEPTION 'platform_conflict: dados divergentes' USING ERRCODE='23505'; END IF;
    IF p_delivery_mode='email' THEN
      v_ambiguous := j.email_delivery_status='ambiguous' OR (
        j.email_delivery_status='failed' AND j.email_last_error_code IN (
          'email_unknown_error','email_send_ambiguous','email_accept_persistence_failed',
          'email_timeout','email_network_error','email_send_crash','email_delivery_setup_failed'
        )
      );
      IF v_ambiguous AND NOT coalesce(p_confirm_ambiguous_email_retry,false) THEN
        RAISE EXCEPTION 'email_ambiguous_confirmation_required' USING ERRCODE='P0001';
      END IF;
      IF j.email_next_attempt_at > clock_timestamp() THEN
        RAISE EXCEPTION 'platform_email_cooldown: reenvio em cooldown' USING ERRCODE='55P03';
      END IF;
    END IF;
    UPDATE public.platform_org_admin_invites
       SET status='processando',lease_token=token,lease_expires_at=clock_timestamp()+interval '2 minutes',attempt_count=attempt_count+1,last_error_code=NULL,updated_at=now()
     WHERE id=j.id RETURNING * INTO j;
  ELSE
    INSERT INTO public.platform_org_admin_invites(organization_id,user_id,email,nome,cpf_cnpj,telefone,modo_acesso,responsavel_principal,invited_by,status,request_id,attempt_count,lease_token,lease_expires_at,updated_at)
    VALUES(p_organization_id,NULL,v_email,btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal,p_actor_id,'processando',gen_random_uuid(),1,token,clock_timestamp()+interval '2 minutes',now()) RETURNING * INTO j;
  END IF;
  RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status',j.status,'lease_token',token,'lease_expires_at',j.lease_expires_at,'user_id',j.user_id,'completed',false);
END
$function$

CREATE OR REPLACE FUNCTION platform_private.current_user_organization_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_organization_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id
    INTO v_organization_id
    FROM public.profiles p
   WHERE p.user_id = auth.uid()
     AND p.ativo = true
     AND p.organization_id IS NOT NULL;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Organização ativa não encontrada' USING ERRCODE = '42501';
  END IF;

  RETURN v_organization_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_dashboard_geral_lab_resumo()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '42501';
  END IF;

  v_org := platform_private.current_user_organization_id();

  IF NOT EXISTS (
    SELECT 1
      FROM public.user_roles ur
     WHERE ur.user_id = v_uid
       AND ur.role IN ('administrador'::public.app_role, 'gestor'::public.app_role)
  ) THEN
