      'os_aguardando','lotes_producao','cq_pendente','envases_pendentes',
      'insumos_criticos','entregas_pendentes'
    ),
    'gerado_em', now(),
    'organization_scoped', v_org IS NOT NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_executivo_resumo_geral(p_filtros jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_tz text := 'America/Sao_Paulo';
  v_periodo text := COALESCE(p_filtros->>'periodo', '30_dias');
  v_data_inicio timestamptz;
  v_data_fim timestamptz := now();
  v_hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_cliente uuid := NULLIF(p_filtros->>'cliente_id','')::uuid;
  v_fazenda uuid := NULLIF(p_filtros->>'fazenda_id','')::uuid;
  v_indisp text[] := ARRAY[
    'solicitacoes_abertas','solicitacoes_criticas','visitas_pendentes','visitas_atrasadas',
    'checkins_hoje','visitas_hoje','recomendacoes_pendentes','os_ativas','os_abertas',
    'os_atrasadas','lotes_em_producao','cq_pendente','envases_pendentes',
    'embalagens_em_estoque','embalagens_sem_etiqueta','entregas_pendentes',
    'entregas_sem_comprovante','entregas_nao_faturadas','alertas_operacionais',
    'clientes_ativos','receita_recebida','sla_vencidos'
  ]::text[];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '42501';
  END IF;

  v_org := platform_private.current_user_organization_id();

  IF NOT EXISTS (
    SELECT 1
      FROM public.user_roles ur
     WHERE ur.user_id = v_uid
       AND ur.role IN ('administrador'::public.app_role, 'gestor'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'Acesso negado ao Portal Executivo' USING ERRCODE = '42501';
  END IF;

  IF v_cliente IS NOT NULL THEN
    RAISE EXCEPTION 'Filtro de cliente sem vínculo organizacional comprovado' USING ERRCODE = '42501';
  END IF;
  IF v_fazenda IS NOT NULL THEN
    RAISE EXCEPTION 'Filtro de fazenda sem vínculo organizacional comprovado' USING ERRCODE = '42501';
  END IF;

  IF v_periodo = 'personalizado' THEN
    IF NULLIF(p_filtros->>'data_inicio','') IS NULL OR NULLIF(p_filtros->>'data_fim','') IS NULL THEN
      RAISE EXCEPTION 'Período personalizado exige data_inicio e data_fim' USING ERRCODE = '22023';
    END IF;
    v_data_inicio := (p_filtros->>'data_inicio')::timestamptz;
    v_data_fim := (p_filtros->>'data_fim')::timestamptz;
    IF v_data_inicio > v_data_fim THEN
      RAISE EXCEPTION 'data_inicio não pode ser maior que data_fim' USING ERRCODE = '22023';
    END IF;
  ELSIF v_periodo = 'hoje' THEN
    v_data_inicio := (v_hoje::timestamp) AT TIME ZONE v_tz;
  ELSIF v_periodo = '7_dias' THEN
    v_data_inicio := now() - interval '7 days';
  ELSIF v_periodo = '15_dias' THEN
    v_data_inicio := now() - interval '15 days';
  ELSIF v_periodo = 'safra_atual' THEN
    v_data_inicio := (date_trunc('year', v_hoje)::timestamp) AT TIME ZONE v_tz;
  ELSE
    v_data_inicio := now() - interval '30 days';
    v_periodo := '30_dias';
  END IF;

  RETURN jsonb_build_object(
    'periodo', jsonb_build_object(
      'data_inicio', v_data_inicio,
      'data_fim', v_data_fim,
      'periodo', v_periodo,
      'timezone', v_tz
    ),
    'resumo', '{}'::jsonb,
    'saude_operacional', jsonb_build_object(
      'score', 0,
      'classificacao', 'sem_dados',
      'motivos', jsonb_build_array('Fontes sem vínculo organizacional comprovado')
    ),
    'dados_indisponiveis', to_jsonb(v_indisp),
    'gerado_em', now(),
    'organization_scoped', v_org IS NOT NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_profile_tenant_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
     OR NEW.email IS DISTINCT FROM OLD.email
     OR NEW.senha_provisoria IS DISTINCT FROM OLD.senha_provisoria
     OR NEW.cliente_id IS DISTINCT FROM OLD.cliente_id THEN
    RAISE EXCEPTION 'profile_protected_fields' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() = OLD.user_id AND NEW.ativo IS DISTINCT FROM OLD.ativo THEN
    RAISE EXCEPTION 'profile_protected_fields' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_edit_user_profile_v1(p_user_id uuid, p_expected_updated_at timestamp with time zone, p_profile jsonb, p_roles app_role[], p_cliente_ids uuid[], p_principal_cliente_id uuid, p_partner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE caller uuid:=auth.uid(); stamp timestamptz; current_roles public.app_role[]; n integer;
BEGIN
 IF p_profile ? '_external_edit' THEN
 RETURN platform_private.user_edit_f2_common(p_user_id,p_expected_updated_at,p_profile,p_roles,p_cliente_ids,p_principal_cliente_id,p_partner_id);
 END IF;
 IF caller IS NULL OR NOT platform_private.is_tenant_admin_for_user(p_user_id) THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 IF p_user_id IS NULL OR p_expected_updated_at IS NULL OR p_profile IS NULL OR jsonb_typeof(p_profile)<>'object' THEN RAISE EXCEPTION 'user_edit_invalid_input' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_profile) k WHERE k NOT IN ('nome','telefone','cargo','cpf_cnpj','crea','especialidade')) THEN RAISE EXCEPTION 'user_edit_invalid_fields' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p_profile->'nome') IS DISTINCT FROM 'string' OR char_length(btrim(coalesce(p_profile->>'nome',''))) NOT BETWEEN 2 AND 150 THEN RAISE EXCEPTION 'user_edit_invalid_name' USING ERRCODE='22023'; END IF;
 IF nullif(p_profile->>'telefone','') IS NOT NULL AND (p_profile->>'telefone') !~ '^[0-9]{10,11}$' THEN RAISE EXCEPTION 'user_edit_invalid_phone' USING ERRCODE='22023'; END IF;
 IF p_roles IS NULL OR cardinality(p_roles) NOT BETWEEN 1 AND 13 OR array_position(p_roles,NULL) IS NOT NULL OR cardinality(p_roles)<>(SELECT count(DISTINCT r) FROM unnest(p_roles) r) THEN RAISE EXCEPTION 'user_edit_invalid_roles' USING ERRCODE='22023'; END IF;
 IF 'superadmin'::public.app_role=ANY(p_roles) OR public.is_platform_superadmin(p_user_id) THEN RAISE EXCEPTION 'user_edit_superadmin_forbidden' USING ERRCODE='42501'; END IF;
 IF cardinality(coalesce(p_cliente_ids,'{}'::uuid[]))<>0 OR p_principal_cliente_id IS NOT NULL OR p_partner_id IS NOT NULL THEN RAISE EXCEPTION 'user_edit_unscoped_links_forbidden' USING ERRCODE='42501'; END IF;
 SELECT array_agg(role ORDER BY role::text) INTO current_roles FROM public.user_roles WHERE user_id=p_user_id;
 IF EXISTS(SELECT 1 FROM unnest(coalesce(current_roles,'{}'::public.app_role[])) r WHERE r IN ('cliente_produtor','parceiro_b2b','parceiro_b2b_tecnico')) OR EXISTS(SELECT 1 FROM unnest(p_roles) r WHERE r IN ('cliente_produtor','parceiro_b2b','parceiro_b2b_tecnico')) THEN RAISE EXCEPTION 'user_edit_linked_role_unavailable' USING ERRCODE='42501'; END IF;
 IF caller=p_user_id AND NOT ('administrador'=ANY(p_roles)) THEN RAISE EXCEPTION 'user_edit_self_admin_removal' USING ERRCODE='42501'; END IF;
 SELECT updated_at INTO stamp FROM public.profiles WHERE user_id=p_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_not_found' USING ERRCODE='P0002'; END IF;
 IF stamp IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'user_edit_conflict' USING ERRCODE='PT409'; END IF;
 INSERT INTO public.user_roles(user_id,role) SELECT p_user_id,r FROM unnest(p_roles) r WHERE NOT EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=p_user_id AND ur.role=r);
 DELETE FROM public.user_roles WHERE user_id=p_user_id AND NOT(role=ANY(p_roles)) AND role<>'superadmin'::public.app_role;
 UPDATE public.profiles SET nome=btrim(p_profile->>'nome'),telefone=nullif(p_profile->>'telefone',''),cargo=nullif(p_profile->>'cargo',''),cpf_cnpj=nullif(p_profile->>'cpf_cnpj',''),crea=nullif(p_profile->>'crea',''),especialidade=nullif(p_profile->>'especialidade','') WHERE user_id=p_user_id RETURNING updated_at INTO stamp;
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'user_edit_not_found' USING ERRCODE='P0002'; END IF;
 RETURN jsonb_build_object('success',true,'user_id',p_user_id,'updated_at',stamp);
END; $function$

CREATE OR REPLACE FUNCTION public.get_my_available_portal_contexts()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); org uuid; management boolean:=false; tech boolean:=false; partner boolean:=false; scopes record; contexts text[]:=ARRAY[]::text[]; pref text; last_ctx text; skip boolean:=false; def text;
BEGIN
 IF u IS NULL OR NOT platform_private.platform_actor_access_ready(u) THEN
  RETURN jsonb_build_object('available_contexts',contexts,'default_context',NULL,'must_select_context',false,'has_b2b_access',false,'has_technical_access',false,'is_admin',false,'preferred_context',NULL,'skip_context_selector',false);
 END IF;
 org:=public.h15_actor_organization();
 IF org IS NULL THEN RETURN jsonb_build_object('available_contexts',contexts,'default_context',NULL,'must_select_context',false,'has_b2b_access',false,'has_technical_access',false,'is_admin',false,'preferred_context',NULL,'skip_context_selector',false); END IF;
 SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u AND r.role IN ('administrador','gestor')),
 EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u AND r.role IN ('tecnico_agronomo','consultor_tecnico','aplicador')) INTO management,tech;
 partner:=platform_private.b2b_commercial_context() IS NOT NULL;
 IF management THEN contexts:=array_append(contexts,'admin'); END IF;
 IF partner AND public.has_role(u,'parceiro_b2b') THEN contexts:=array_append(contexts,'b2b'); END IF;
 IF partner AND public.has_role(u,'parceiro_b2b_tecnico') THEN tech:=true; END IF;
 IF public.has_role(u,'cliente_produtor') AND platform_private.c2_producer_links(u,org) THEN contexts:=array_append(contexts,'producer'); END IF;
 IF tech THEN contexts:=array_append(contexts,'technical'); END IF;
 SELECT preferred_context,last_context,skip_context_selector INTO pref,last_ctx,skip FROM public.user_access_preferences WHERE user_id=u;
 IF pref IS NOT NULL AND pref=ANY(contexts) THEN def:=pref;
 ELSIF last_ctx IS NOT NULL AND last_ctx=ANY(contexts) THEN def:=last_ctx;
 ELSIF cardinality(contexts)=1 THEN def:=contexts[1]; END IF;
 IF pref IS NULL OR NOT(pref=ANY(contexts)) THEN pref:=NULL; skip:=false; END IF;
 RETURN jsonb_build_object('contract','C2_MULTIPROFILE_V1','actor_id',u,'tenant_id',org,'partner_id',(platform_private.b2b_commercial_context()->>'partner_id')::uuid,'ready',true,'profile_stamp',(SELECT updated_at FROM public.profiles WHERE user_id=u),'link_version',(SELECT version FROM public.partner_users WHERE user_id=u),'producer_links_valid',platform_private.c2_producer_links(u,org),'available_contexts',contexts,'default_context',def,'must_select_context',cardinality(contexts)>1 AND NOT COALESCE(skip,false),
 'has_b2b_access',management OR (partner AND public.has_role(u,'parceiro_b2b')),'has_technical_access',management OR tech,'is_admin',management,
 'preferred_context',pref,'skip_context_selector',COALESCE(skip,false));
END $function$

CREATE OR REPLACE FUNCTION public.tenant_admin_list_users(p_search text DEFAULT NULL::text, p_role app_role DEFAULT NULL::app_role, p_active boolean DEFAULT NULL::boolean, p_offset integer DEFAULT 0, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_total integer; v_items jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'administrador'::public.app_role) OR public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'tenant_users_forbidden' USING ERRCODE='42501'; END IF;
 SELECT organization_id INTO v_org FROM public.profiles WHERE user_id=auth.uid() AND ativo=true;
 IF v_org IS NULL THEN RAISE EXCEPTION 'tenant_users_forbidden' USING ERRCODE='42501'; END IF;
 IF p_offset<0 OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'tenant_users_invalid_pagination' USING ERRCODE='22023'; END IF;
 SELECT count(*) INTO v_total FROM public.profiles p WHERE p.organization_id=v_org AND (p_active IS NULL OR p.ativo=p_active) AND (NULLIF(btrim(p_search),'') IS NULL OR p.nome ILIKE '%'||btrim(p_search)||'%' OR p.email ILIKE '%'||btrim(p_search)||'%') AND (p_role IS NULL OR EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=p.user_id AND ur.role=p_role)) AND NOT public.is_platform_superadmin(p.user_id);
 SELECT COALESCE(jsonb_agg(row_data ORDER BY created_at DESC,user_id),'[]'::jsonb) INTO v_items FROM (SELECT p.user_id,p.nome,p.email,p.telefone,p.cpf_cnpj,p.ativo,p.created_at,p.updated_at,p.cargo,p.crea,p.especialidade,COALESCE((SELECT jsonb_agg(ur.role ORDER BY ur.role::text) FROM public.user_roles ur WHERE ur.user_id=p.user_id),'[]'::jsonb) roles,EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p.user_id) has_client_links,EXISTS(SELECT 1 FROM public.partner_users pu WHERE pu.user_id=p.user_id) has_partner_link FROM public.profiles p WHERE p.organization_id=v_org AND (p_active IS NULL OR p.ativo=p_active) AND (NULLIF(btrim(p_search),'') IS NULL OR p.nome ILIKE '%'||btrim(p_search)||'%' OR p.email ILIKE '%'||btrim(p_search)||'%') AND (p_role IS NULL OR EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=p.user_id AND ur.role=p_role)) AND NOT public.is_platform_superadmin(p.user_id) ORDER BY p.created_at DESC,p.user_id OFFSET p_offset LIMIT p_limit) row_data;
 RETURN jsonb_build_object('items',v_items,'total',v_total,'organization_id',v_org);
END;
$function$

CREATE OR REPLACE FUNCTION public.tenant_admin_set_user_active(p_user_id uuid, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_count integer; v_admin_count integer;
BEGIN
 IF NOT platform_private.is_tenant_admin_for_user(p_user_id) THEN RAISE EXCEPTION 'user_status_forbidden' USING ERRCODE='42501'; END IF;
 IF p_user_id=auth.uid() AND p_active=false THEN RAISE EXCEPTION 'user_status_self_deactivation' USING ERRCODE='42501'; END IF;
 IF p_active=false AND public.has_role(p_user_id,'administrador'::public.app_role) THEN SELECT count(*) INTO v_admin_count FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.user_id WHERE p.organization_id=platform_private.current_user_organization_id() AND p.ativo=true AND ur.role='administrador'::public.app_role; IF v_admin_count<=1 THEN RAISE EXCEPTION 'user_last_active_admin' USING ERRCODE='PT409'; END IF; END IF;
 UPDATE public.profiles SET ativo=p_active WHERE user_id=p_user_id; GET DIAGNOSTICS v_count=ROW_COUNT;
 IF v_count<>1 THEN RAISE EXCEPTION 'user_status_not_found' USING ERRCODE='P0002'; END IF;
 RETURN jsonb_build_object('success',true,'user_id',p_user_id,'active',p_active);
END; $function$

CREATE OR REPLACE FUNCTION public.org_onboarding_complete()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; r record; d jsonb; v_cnpj text;
BEGIN
  v_org := public._org_admin_org();
  IF v_org IS NULL THEN RAISE EXCEPTION 'org_forbidden: apenas administrador da empresa' USING errcode='42501'; END IF;
  SELECT * INTO r FROM public.organizations WHERE id = v_org FOR UPDATE;
  IF r.status = 'ativa' THEN RETURN jsonb_build_object('status','ativa','idempotent',true); END IF;
  IF r.status <> 'onboarding' THEN RAISE EXCEPTION 'org_invalid: empresa não está em onboarding'; END IF;
  d := platform_private.onboarding_validar(r.onboarding_dados);
  IF coalesce(d->>'razao_social','') = '' OR coalesce(d->>'cep','') = '' OR coalesce(d->>'logradouro','') = ''
     OR coalesce(d->>'cidade','') = '' OR coalesce(d->>'uf','') = '' OR coalesce(d->>'telefone','') = ''
     OR coalesce(d->>'responsavel_nome','') = '' OR coalesce(d->>'fuso_horario','') = ''
     OR coalesce((d->>'confirmado')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'org_invalid: cadastro incompleto'; END IF;
  v_cnpj := platform_private.cnpj_normalizar(coalesce(nullif(d->>'cnpj',''), r.cnpj));
  IF v_cnpj IS NULL OR NOT platform_private.cnpj_valido(v_cnpj) THEN RAISE EXCEPTION 'org_invalid: CNPJ inválido (dígitos verificadores)'; END IF;
  IF EXISTS (SELECT 1 FROM public.organizations WHERE cnpj_normalizado = v_cnpj AND id <> v_org) THEN RAISE EXCEPTION 'org_duplicate: CNPJ já cadastrado' USING errcode='23505'; END IF;
  PERFORM platform_private.issue_ticket('org_write', v_org);
  UPDATE public.organizations
     SET razao_social = d->>'razao_social',
         nome_fantasia = coalesce(nullif(d->>'nome_fantasia',''), nome_fantasia),
         cnpj = v_cnpj,
         cnpj_normalizado = v_cnpj,
         email_corporativo = nullif(d->>'email_contato',''),
         fuso_horario = d->>'fuso_horario',
         onboarding_dados = d,
         onboarding_concluido_em = now(),
         updated_at = now()
   WHERE id = v_org;
  PERFORM public._org_set_status(v_org, 'ativa', 'onboarding concluído');
  RETURN jsonb_build_object('status','ativa','idempotent',false);
END $function$

CREATE OR REPLACE FUNCTION public.guard_tenant_organization_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  v_org := public.h15_actor_organization();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'tenant_context_required' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.organization_id IS NULL THEN
    NEW.organization_id := v_org;
  END IF;
  IF NEW.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'tenant_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'tenant_immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.financial_storage_object_permitted(_bucket text, _name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_parts text[]; v_owner_type text; v_owner_id uuid;
BEGIN
  IF NOT public.storage1_path_strict(_name) THEN RETURN false; END IF;
  v_org := public.h15_actor_organization();
  IF v_org IS NULL OR NOT public.is_financial_staff(auth.uid()) THEN RETURN false; END IF;
  v_parts := storage.foldername(_name);
  IF _bucket IN ('financial-reports','financial-receipts') THEN
    RETURN array_length(v_parts,1) >= 1 AND v_parts[1] = v_org::text;
  END IF;
  IF _bucket <> 'financial-docs' OR array_length(v_parts,1) < 2 THEN RETURN false; END IF;
  v_owner_type := v_parts[1];
  BEGIN
  IF NOT public.storage1_path_strict(_name) THEN RETURN false; END IF; v_owner_id := v_parts[2]::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END;
  RETURN CASE v_owner_type
    WHEN 'RECEIVABLE' THEN EXISTS(SELECT 1 FROM public.accounts_receivable x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    WHEN 'PAYABLE' THEN EXISTS(SELECT 1 FROM public.accounts_payable x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    WHEN 'PAYMENT_RECEIVABLE' THEN EXISTS(SELECT 1 FROM public.receivable_payments x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    WHEN 'PAYMENT_PAYABLE' THEN EXISTS(SELECT 1 FROM public.payable_payments x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    WHEN 'FISCAL_INVOICE' THEN EXISTS(SELECT 1 FROM public.fiscal_invoices x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    ELSE false END;
END $function$

CREATE OR REPLACE FUNCTION public.cliente_storage_object_permitted(_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_org uuid;
  v_parts text[];
  v_cliente uuid;
BEGIN
  IF NOT public.storage1_path_strict(_name) THEN RETURN false; END IF;
  v_org := public.h15_actor_organization();
  v_parts := storage.foldername(_name);
  IF v_org IS NULL
     OR array_length(v_parts, 1) < 3
     OR v_parts[1] <> v_org::text
     OR v_parts[2] <> 'clientes' THEN
    RETURN false;
  END IF;
  BEGIN
  IF NOT public.storage1_path_strict(_name) THEN RETURN false; END IF;
    v_cliente := v_parts[3]::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN false;
  END;
  RETURN EXISTS (
    SELECT 1
      FROM public.clientes c
     WHERE c.id = v_cliente
       AND c.organization_id = v_org
       AND public.can_user_access_cliente(c.id)
  );
END
$function$

CREATE OR REPLACE FUNCTION public.issue_financial_receipt(_payment_id uuid, _description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid; v_payment record; v_installment record; v_receivable record; v_existing record; v_receipt_id uuid; v_desc text;
BEGIN
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL OR NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_payment FROM public.receivable_payments WHERE id=_payment_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Recebimento não encontrado' USING ERRCODE='42501'; END IF;
 IF v_payment.is_reversal THEN RAISE EXCEPTION 'Não é possível emitir recibo para estorno'; END IF;
 SELECT * INTO v_installment FROM public.accounts_receivable_installments WHERE id=v_payment.installment_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Parcela não encontrada' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_receivable FROM public.accounts_receivable WHERE id=v_installment.receivable_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Título não encontrado' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_existing FROM public.financial_receipts WHERE payment_id=_payment_id AND status='ISSUED' AND organization_id=v_org LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('duplicate',true,'receipt_id',v_existing.id,'receipt_number',v_existing.receipt_number,'message','Recibo já emitido para este recebimento'); END IF;
 v_desc:=COALESCE(NULLIF(trim(_description),''),'Recebimento ref. parcela '||COALESCE(v_installment.installment_number::text,'—')||' de '||COALESCE(v_receivable.description,'título financeiro'));
 INSERT INTO public.financial_receipts(payment_id,receivable_payment_id,receivable_id,customer_id,amount,payment_date,payment_method_id,description,issued_by,status,organization_id)
 VALUES(_payment_id,_payment_id,v_installment.receivable_id,v_receivable.customer_id,v_payment.amount_received,v_payment.payment_date,v_payment.payment_method_id,v_desc,auth.uid(),'ISSUED',v_org) RETURNING id INTO v_receipt_id;
 INSERT INTO public.financial_audit_log(entity_type,entity_id,action,new_data,performed_by) VALUES('financial_receipts',v_receipt_id,'FINANCIAL_RECEIPT_ISSUED',jsonb_build_object('payment_id',_payment_id,'amount',v_payment.amount_received),auth.uid());
 RETURN jsonb_build_object('duplicate',false,'receipt_id',v_receipt_id,'receipt_number',(SELECT receipt_number FROM public.financial_receipts WHERE id=v_receipt_id AND organization_id=v_org));
END $function$

CREATE OR REPLACE FUNCTION public.cancel_financial_receipt(_receipt_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid; v_rec record;
BEGIN
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL OR NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 IF _reason IS NULL OR length(trim(_reason))<5 THEN RAISE EXCEPTION 'Motivo do cancelamento é obrigatório (mín. 5 caracteres)'; END IF;
 SELECT * INTO v_rec FROM public.financial_receipts WHERE id=_receipt_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Recibo não encontrado' USING ERRCODE='42501'; END IF;
 IF v_rec.status='CANCELED' THEN RAISE EXCEPTION 'Recibo já cancelado'; END IF;
 IF NOT (public.has_role(auth.uid(),'administrador'::public.app_role) OR public.has_role(auth.uid(),'gestor'::public.app_role)) AND v_rec.issued_at::date<>CURRENT_DATE THEN RAISE EXCEPTION 'Apenas administrador/gestor podem cancelar recibos de outros dias'; END IF;
 UPDATE public.financial_receipts SET status='CANCELED',cancel_reason=_reason,canceled_by=auth.uid(),canceled_at=now() WHERE id=_receipt_id AND organization_id=v_org;
 INSERT INTO public.financial_audit_log(entity_type,entity_id,action,new_data,performed_by,reason) VALUES('financial_receipts',_receipt_id,'FINANCIAL_RECEIPT_CANCELED',jsonb_build_object('reason',_reason),auth.uid(),_reason);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_event_sefaz_prepare_v1(_invoice_id uuid, _event_kind text, _reason text, _idempotency_key text, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ref text; v_prod boolean; v_tpamb text; v_inv public.fiscal_invoices; v_actor_org uuid; v_code text; v_type text; v_reason text:=btrim(coalesce(_reason,'')); v_fp text; v_prev public.fiscal_events; v_seq integer; v_id uuid; v_prot text;
BEGIN
 IF _actor IS NULL OR _actor IS DISTINCT FROM auth.uid() OR NOT public.fn_fiscal_can_operate(_actor) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 v_actor_org:=public.h15_actor_organization(); IF v_actor_org IS NULL THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF coalesce(btrim(_idempotency_key),'')='' OR length(_idempotency_key)>200 THEN RAISE EXCEPTION 'FISCAL_EVENT_IDEMPOTENCY_INVALID'; END IF;
 SELECT project_ref,production_emission_allowed INTO v_ref,v_prod FROM public.fiscal_environment_marker LIMIT 1;
 IF v_ref IS DISTINCT FROM 'swzpzcwiasxmjutrmvkm' OR coalesce(v_prod,true) THEN RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED'; END IF;
 SELECT * INTO v_inv FROM public.fiscal_invoices WHERE id=_invoice_id AND organization_id=v_actor_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EVENT_INVOICE_NOT_FOUND' USING ERRCODE='42501'; END IF;
 SELECT nfe_environment_code INTO v_tpamb FROM public.company_fiscal_settings WHERE id=v_inv.company_settings_id AND organization_id=v_actor_org AND is_active;
 IF v_tpamb IS DISTINCT FROM '2' THEN RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED'; END IF;
 IF _event_kind='CANCELLATION' THEN v_code:='110111';v_type:='SEFAZ_CANCELLATION_PREPARED'; ELSIF _event_kind='CORRECTION' THEN v_code:='110110';v_type:='SEFAZ_CORRECTION_PREPARED'; ELSE RAISE EXCEPTION 'FISCAL_EVENT_TYPE_UNSUPPORTED'; END IF;
 IF coalesce(v_inv.access_key,'') !~ '^[0-9]{44}$' THEN RAISE EXCEPTION 'FISCAL_EVENT_ACCESS_KEY_INVALID'; END IF;
 IF coalesce(v_inv.environment,'HOMOLOGATION')<>'HOMOLOGATION' THEN RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED'; END IF;
 SELECT n_prot INTO v_prot FROM public.fiscal_sefaz_transmissions WHERE fiscal_invoice_id=_invoice_id AND service IN ('NFeAutorizacao4','NFeRetAutorizacao4') AND state='SUCCEEDED' AND outcome='AUTHORIZED' AND n_prot IS NOT NULL AND ch_nfe=v_inv.access_key ORDER BY created_at DESC LIMIT 1;
 IF v_prot IS NULL THEN RAISE EXCEPTION 'FISCAL_EVENT_INVOICE_NOT_AUTHORIZED'; END IF;
 IF _event_kind='CANCELLATION' THEN IF length(v_reason)<15 OR length(v_reason)>255 THEN RAISE EXCEPTION 'FISCAL_EVENT_REASON_INVALID'; END IF; IF EXISTS(SELECT 1 FROM public.v_fiscal_sefaz_event_state WHERE fiscal_invoice_id=_invoice_id AND sefaz_event_code='110111' AND state='REGISTERED') THEN RAISE EXCEPTION 'FISCAL_EVENT_ALREADY_REGISTERED'; END IF;
 ELSE IF length(v_reason)<15 OR length(v_reason)>1000 THEN RAISE EXCEPTION 'FISCAL_EVENT_REASON_INVALID'; END IF; IF EXISTS(SELECT 1 FROM public.v_fiscal_sefaz_event_state WHERE fiscal_invoice_id=_invoice_id AND sefaz_event_code='110111' AND state='REGISTERED') THEN RAISE EXCEPTION 'FISCAL_EVENT_INVOICE_CANCELED'; END IF; END IF;
 v_fp:=encode(extensions.digest(v_code||'|'||v_inv.access_key||'|'||v_reason,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('fiscal_sefaz_event:'||_invoice_id::text||':'||_idempotency_key,0));
 SELECT * INTO v_prev FROM public.fiscal_events WHERE fiscal_invoice_id=_invoice_id AND organization_id=v_actor_org AND event_type=v_type AND idempotency_key=_idempotency_key;
 IF FOUND THEN IF v_prev.payload_fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'FISCAL_EVENT_IDEMPOTENCY_MISMATCH'; END IF; RETURN jsonb_build_object('eventId',v_prev.id,'eventCode',v_prev.sefaz_event_code,'seqEvento',v_prev.sefaz_seq_evento,'accessKey',v_prev.sefaz_access_key,'reason',v_prev.sefaz_reason,'protocol',v_prot,'companySettingsId',v_inv.company_settings_id,'idempotentReplay',true); END IF;
 SELECT coalesce(max(sefaz_seq_evento),0)+1 INTO v_seq FROM public.fiscal_events WHERE fiscal_invoice_id=_invoice_id AND organization_id=v_actor_org AND sefaz_event_code=v_code;
 IF v_seq>20 THEN RAISE EXCEPTION 'FISCAL_EVENT_SEQUENCE_EXHAUSTED'; END IF;
 INSERT INTO public.fiscal_events(fiscal_invoice_id,event_type,event_source,performed_by,idempotency_key,payload_fingerprint,notes,sefaz_event_code,sefaz_seq_evento,sefaz_access_key,sefaz_reason,request_snapshot,organization_id)
 VALUES(_invoice_id,v_type,'INTERNAL',_actor,_idempotency_key,v_fp,left(v_reason,2000),v_code,v_seq,v_inv.access_key,v_reason,jsonb_build_object('eventKind',_event_kind,'protocol',v_prot,'environmentCode','2'),v_actor_org) RETURNING id INTO v_id;
 RETURN jsonb_build_object('eventId',v_id,'eventCode',v_code,'seqEvento',v_seq,'accessKey',v_inv.access_key,'reason',v_reason,'protocol',v_prot,'companySettingsId',v_inv.company_settings_id,'idempotentReplay',false);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_message_set_status(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid:=public.h15_actor_organization(); ctx jsonb; resource record; internal boolean; BEGIN
IF org IS NULL OR NOT platform_private.platform_actor_access_ready(auth.uid()) THEN RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501'; END IF;
internal:=platform_private.b2b_internal_commercial_actor(); IF NOT internal THEN ctx:=platform_private.b2b_commercial_context(); IF ctx IS NULL OR ctx->>'role'<>'parceiro_b2b' OR ctx->>'mode'<>'commercial_owner' THEN RAISE EXCEPTION 'b2b_messages_unavailable' USING ERRCODE='42501'; END IF; END IF;
SELECT m.id,po.partner_id,pa.commercial_owner_organization_id,po.cliente_id INTO resource FROM public.partner_order_messages m JOIN public.partner_orders po ON po.id=m.order_id JOIN public.partner_accounts pa ON pa.id=po.partner_id WHERE m.id=p_id AND pa.ativo IS TRUE AND pa.deleted_at IS NULL FOR UPDATE OF m,po,pa;
IF resource.id IS NULL OR resource.commercial_owner_organization_id IS DISTINCT FROM org OR (NOT internal AND resource.partner_id IS DISTINCT FROM (ctx->>'partner_id')::uuid) OR (resource.cliente_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=resource.cliente_id AND c.organization_id=org)) THEN RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501'; END IF;
IF p_status IS NULL OR p_status NOT IN ('nao_lida','lida','respondida','encerrada') THEN RAISE EXCEPTION 'invalid_status' USING ERRCODE='22023'; END IF;
UPDATE public.partner_order_messages SET status=p_status,status_updated_at=now() WHERE id=resource.id; END $function$

CREATE OR REPLACE FUNCTION public.d51_5_validate_financial_tenant_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_new jsonb := to_jsonb(NEW);
  v_org uuid;
  v_parent_id uuid;
BEGIN
  BEGIN
    v_org := NULLIF(v_new->>'organization_id', '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_INVALID' USING ERRCODE = '23514';
  END;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'accounts_receivable' THEN
    v_parent_id := NULLIF(v_new->>'customer_id', '')::uuid;
    IF v_parent_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.clientes c WHERE c.id = v_parent_id AND c.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_CUSTOMER_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'accounts_receivable_installments' THEN
    v_parent_id := NULLIF(v_new->>'receivable_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts_receivable ar WHERE ar.id = v_parent_id AND ar.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_RECEIVABLE_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'accounts_payable_installments' THEN
    v_parent_id := NULLIF(v_new->>'payable_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts_payable ap WHERE ap.id = v_parent_id AND ap.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_PAYABLE_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'receivable_payments' THEN
    v_parent_id := NULLIF(v_new->>'installment_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts_receivable_installments ari WHERE ari.id = v_parent_id AND ari.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_RECEIVABLE_PAYMENT_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'payable_payments' THEN
    v_parent_id := NULLIF(v_new->>'installment_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts_payable_installments api WHERE api.id = v_parent_id AND api.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_PAYABLE_PAYMENT_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'financial_receipts' THEN
    v_parent_id := NULLIF(v_new->>'customer_id', '')::uuid;
    IF v_parent_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.clientes c WHERE c.id = v_parent_id AND c.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_RECEIPT_CUSTOMER_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
    v_parent_id := NULLIF(v_new->>'payment_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.receivable_payments rp WHERE rp.id = v_parent_id AND rp.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_RECEIPT_PAYMENT_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.partner_apply_default_discount(p_partner_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_desc numeric(5,2);
  v_count integer := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT desconto_padrao INTO v_desc FROM public.partner_accounts WHERE id = p_partner_id AND ativo IS TRUE AND deleted_at IS NULL FOR UPDATE;
  IF v_desc IS NULL THEN RAISE EXCEPTION 'partner_not_found' USING ERRCODE='42501'; END IF;

  INSERT INTO public.partner_product_prices(partner_id, product_id, preco_tabela, desconto_percentual, preco_final, ativo)
  SELECT p_partner_id, p.id,
         COALESCE(p.valor_ha_brl, 0),
         v_desc,
         ROUND(COALESCE(p.valor_ha_brl, 0) * (1 - v_desc/100.0), 2),
         true
  FROM public.produtos p
  WHERE p.ativo = true
  ON CONFLICT (partner_id, product_id) WHERE product_id IS NOT NULL DO UPDATE
    SET preco_tabela = EXCLUDED.preco_tabela,
        desconto_percentual = EXCLUDED.desconto_percentual,
        preco_final = EXCLUDED.preco_final,
        ativo = true;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_wipe_global_product_catalog(p_actor_id uuid, p_reason text, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_table text;
  v_count bigint;
  v_before jsonb := '{}'::jsonb;
  v_deleted jsonb := '{}'::jsonb;
  v_total_deleted bigint := 0;
  v_existing jsonb;
  v_tables constant text[] := ARRAY[
    'catalogo_volumes',
    'product_crop_recommendations',
    'product_fiscal_profiles',
    'product_target_recommendations',
    'product_technical_profiles',
    'formulacoes',
    'produtos'
  ];
BEGIN
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_correlation_id IS NULL THEN
    RAISE EXCEPTION 'correlation_id_required' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 10 AND 500 THEN
    RAISE EXCEPTION 'invalid_reason' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('platform_wipe_global_product_catalog', 0));

  SELECT jsonb_build_object(
    'ok', true,
    'idempotent', true,
    'correlation_id', correlation_id,
    'deleted', counts_after -> 'deleted',
    'total_deleted', COALESCE((counts_after ->> 'total_deleted')::bigint, 0)
  )
  INTO v_existing
  FROM public.catalog_platform_admin_audit
  WHERE correlation_id = p_correlation_id
    AND operation = 'wipe_global_products'
    AND status = 'completed';

  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  FOREACH v_table IN ARRAY v_tables LOOP
    EXECUTE format('SELECT count(*) FROM public.%I', v_table) INTO v_count;
    v_before := v_before || jsonb_build_object(v_table, v_count);
  END LOOP;

  FOREACH v_table IN ARRAY v_tables LOOP
    EXECUTE format('DELETE FROM public.%I WHERE id IS NOT NULL', v_table);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object(v_table, v_count);
    v_total_deleted := v_total_deleted + v_count;
  END LOOP;

  INSERT INTO public.catalog_platform_admin_audit (
    operation, actor_id, reason, correlation_id, status,
    counts_before, counts_after, completed_at
  ) VALUES (
    'wipe_global_products', p_actor_id, btrim(p_reason), p_correlation_id, 'completed',
    v_before,
    jsonb_build_object('deleted', v_deleted, 'total_deleted', v_total_deleted),
    now()
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'correlation_id', p_correlation_id,
    'deleted', v_deleted,
    'total_deleted', v_total_deleted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.d51_5_p0d_ab_selftest()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
begin
  if coalesce(current_setting('app.d51_5_p0d_selftest', true), '') <> 'enabled' then
    raise exception 'P0D_SELFTEST_DISABLED' using errcode = '42501';
  end if;

  -- Structural A/B assertions: every direct production surface must have a restrictive
  -- tenant policy; no historic true policy may survive; operational definers are not
  -- executable by signed-in callers until they embed resource-tenant checks.
  if exists (
    select 1 from pg_catalog.pg_policies p
    where p.schemaname = 'public'
      and p.tablename in ('clientes','fazendas','talhoes','ordens_servico','lotes','envase','controle_qualidade')
      and p.policyname = 'tenant_isolation_d51_5'
      and p.permissive <> 'RESTRICTIVE'
  ) or (
    select count(*) from pg_catalog.pg_policies p
    where p.schemaname = 'public'
      and p.tablename in ('clientes','fazendas','talhoes','ordens_servico','lotes','envase','controle_qualidade')
      and p.policyname = 'tenant_isolation_d51_5'
      and p.permissive = 'RESTRICTIVE'
  ) <> 7 then
    raise exception 'P0D_RESTRICTIVE_TENANT_POLICY_MISSING';
  end if;

  if exists (
    select 1 from pg_catalog.pg_policies p
    where p.schemaname = 'public'
      and p.tablename in ('lotes','envase','controle_qualidade')
      and (p.qual = 'true' or p.with_check = 'true')
  ) then
    raise exception 'P0D_TRUE_POLICY_SURVIVED';
  end if;

  if has_function_privilege('authenticated', 'public.rpc_programar_os_v1(uuid,text,date)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.rpc_cockpit_gerar_lote_v1(uuid,uuid,text,jsonb)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.rpc_cockpit_registrar_envase_v1(uuid,uuid,text,uuid,jsonb,date,text,text,boolean,text)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.rpc_avancar_esteira_laboratorio(uuid,text,text,uuid)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.rpc_cockpit_listar_esteira_v1(text,text[],text[],text[],boolean,date,date,boolean,integer,integer)', 'EXECUTE') then
    raise exception 'P0D_UNSCOPED_DEFINER_STILL_EXECUTABLE';
  end if;

  v_result := jsonb_build_object(
    'tenant_restrictive_policies', 7,
    'legacy_true_policies', 0,
    'unscoped_cockpit_rpcs_executable', false,
    'transactional', true
  );
  return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.rpc_criar_visita_idempotente(p_client_uuid uuid, p_cliente_id uuid, p_fazenda_id uuid, p_talhao_id uuid, p_cultura_id uuid DEFAULT NULL::uuid, p_data_vistoria date DEFAULT CURRENT_DATE, p_tipo_visita tipo_visita DEFAULT 'vistoria_inicial'::tipo_visita, p_objetivo_visita text DEFAULT NULL::text, p_safra text DEFAULT NULL::text, p_fase_fenologica text DEFAULT NULL::text, p_solicitacao_id uuid DEFAULT NULL::uuid, p_origem text DEFAULT 'visita_avulsa'::text, p_categoria_problema categoria_problema_consultor DEFAULT NULL::categoria_problema_consultor, p_nivel_pressao nivel_pressao DEFAULT NULL::nivel_pressao, p_percentual_area_afetada numeric DEFAULT NULL::numeric, p_urgencia urgencia_consultor DEFAULT NULL::urgencia_consultor, p_localizacao_na_area text DEFAULT NULL::text, p_observacoes_tecnicas text DEFAULT NULL::text, p_problema_principal text DEFAULT NULL::text, p_area_hectares numeric DEFAULT NULL::numeric, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_registro_origem_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_existing public.registros_consultor%ROWTYPE;
  v_new_id uuid;
  v_fazenda_cliente uuid;
  v_talhao_fazenda uuid;
  v_origem text := COALESCE(NULLIF(p_origem,''), 'visita_avulsa');
  v_natureza natureza_registro_consultor;
  v_cultura uuid := p_cultura_id;
  v_safra text := p_safra;
  v_missing text[] := ARRAY[]::text[];
  c_cultura_opcional constant text[] := ARRAY['ocorrencia_campo','solicitacao_produtor'];
BEGIN
  IF NOT public.technical_actor_ready(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unauthenticated');
  END IF;

  IF v_origem NOT IN ('ocorrencia_campo','solicitacao_produtor','agenda','retorno_monitoramento','visita_avulsa') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_origin');
  END IF;

  v_natureza := CASE WHEN v_origem = 'ocorrencia_campo' THEN 'ocorrencia'::natureza_registro_consultor
                     ELSE 'visita'::natureza_registro_consultor END;

  IF p_client_uuid IS NULL
     OR p_cliente_id IS NULL
     OR p_fazenda_id IS NULL
     OR p_talhao_id IS NULL
     OR p_data_vistoria IS NULL
     OR p_tipo_visita IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_request');
  END IF;

  IF NOT public.technical_refs_in_actor_tenant(p_cliente_id,p_fazenda_id,p_talhao_id)
     OR NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')
       OR ((public.has_role(v_uid,'consultor_tecnico') OR public.has_role(v_uid,'tecnico_agronomo'))
       AND public.technical_client_link(v_uid,p_cliente_id,ARRAY['execute','manage']))) THEN
    RETURN jsonb_build_object('ok',false,'error','technical_access_required');
  END IF;
  IF p_solicitacao_id IS NOT NULL AND NOT public.can_user_access_solicitacao(p_solicitacao_id) THEN
    RETURN jsonb_build_object('ok',false,'error','invalid_request');
  END IF;
  IF p_registro_origem_id IS NOT NULL AND NOT public.can_view_technical_visit(v_uid,p_registro_origem_id) THEN
    RETURN jsonb_build_object('ok',false,'error','invalid_request');
  END IF;
  SELECT * INTO v_existing
    FROM public.registros_consultor
    WHERE client_uuid = p_client_uuid
    LIMIT 1;

  IF FOUND THEN
    IF NOT public.can_manage_technical_visit(v_uid,v_existing.id)
       OR v_existing.cliente_id IS DISTINCT FROM p_cliente_id
       OR v_existing.fazenda_id IS DISTINCT FROM p_fazenda_id
       OR v_existing.talhao_id IS DISTINCT FROM p_talhao_id
       OR (v_existing.consultor_responsavel <> v_uid
       AND NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor'))) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'idempotency_conflict');
    END IF;

    RETURN jsonb_build_object(
      'ok', true, 'created', false, 'idempotent', true,
      'registro_id', v_existing.id,
      'client_uuid', v_existing.client_uuid,
      'status', v_existing.status::text,
      'origem', v_existing.origem_atendimento,
      'version', v_existing.version,
      'cultura_id', v_existing.cultura_id,
      'missing_fields', CASE WHEN v_existing.cultura_id IS NULL
                             THEN jsonb_build_array('cultura_id') ELSE '[]'::jsonb END,
      'next_step', CASE WHEN v_existing.cultura_id IS NULL THEN 'identificacao' ELSE 'continuar' END,
      'can_edit', v_existing.status IN ('rascunho','em_andamento','reprovado'),
      'next_route', '/app/visita/' || v_existing.id::text,
      'pdf_status', v_existing.pdf_status
    );
  END IF;

  IF NOT public.has_active_user_cliente_access(v_uid, p_cliente_id, ARRAY['execute','manage']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'technical_access_required');
  END IF;

  SELECT cliente_id INTO v_fazenda_cliente FROM public.fazendas WHERE id = p_fazenda_id;
  IF v_fazenda_cliente IS NULL OR v_fazenda_cliente <> p_cliente_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_farm');
  END IF;

  SELECT fazenda_id INTO v_talhao_fazenda FROM public.talhoes WHERE id = p_talhao_id;
  IF v_talhao_fazenda IS NULL OR v_talhao_fazenda <> p_fazenda_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_plot');
  END IF;

  IF v_cultura IS NULL THEN
    WITH cand AS (
      SELECT DISTINCT ts.cultura_id, ts.safra
        FROM public.talhao_safras ts
       WHERE ts.talhao_id = p_talhao_id
         AND ts.cultura_id IS NOT NULL
         AND COALESCE(ts.status,'ativa') IN ('ativa','em_andamento','plantada')
    )
    SELECT c.cultura_id, c.safra
      INTO v_cultura, v_safra
      FROM cand c
     WHERE (SELECT count(*) FROM cand) = 1;

    IF NOT FOUND THEN
      v_cultura := NULL;
      v_safra := p_safra;
    END IF;
  END IF;

  IF v_cultura IS NULL AND NOT (v_origem = ANY (c_cultura_opcional)) THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'invalid_request',
      'missing_fields', jsonb_build_array('cultura_id'),
      'next_step', 'identificacao'
    );
  END IF;

  IF v_cultura IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.culturas WHERE id = v_cultura) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_crop');
  END IF;

  IF p_solicitacao_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.portal_solicitacoes
        WHERE id = p_solicitacao_id AND cliente_id = p_cliente_id
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_request');
    END IF;
  END IF;

  IF v_cultura IS NULL THEN
    v_missing := array_append(v_missing, 'cultura_id');
  END IF;

  INSERT INTO public.registros_consultor (
    client_uuid,
    cliente_id, fazenda_id, talhao_id, cultura_id,
    data_vistoria, tipo_visita, objetivo_visita, safra, fase_fenologica,
    solicitacao_id, registro_origem_id, origem_atendimento,
    categoria_problema, nivel_pressao, percentual_area_afetada, urgencia,
    localizacao_na_area, observacoes_tecnicas, problema_principal,
    area_hectares, latitude, longitude,
    consultor_responsavel, consultor_profile_id, created_by,
    natureza_registro, status, version, pdf_status
  ) VALUES (
    p_client_uuid,
    p_cliente_id, p_fazenda_id, p_talhao_id, v_cultura,
    p_data_vistoria, p_tipo_visita, p_objetivo_visita, v_safra, p_fase_fenologica,
    p_solicitacao_id, p_registro_origem_id, v_origem,
    p_categoria_problema, COALESCE(p_nivel_pressao,'medio'), p_percentual_area_afetada,
    COALESCE(p_urgencia,'media'),
    p_localizacao_na_area, p_observacoes_tecnicas, p_problema_principal,
    p_area_hectares, p_latitude, p_longitude,
    v_uid, (SELECT pr.id FROM public.profiles pr WHERE pr.user_id = v_uid LIMIT 1), v_uid,
    v_natureza, 'rascunho', 1, 'pending'
  )
  RETURNING id INTO v_new_id;

  RETURN jsonb_build_object(
    'ok', true, 'created', true, 'idempotent', false,
    'registro_id', v_new_id,
    'client_uuid', p_client_uuid,
    'status', 'rascunho',
    'origem', v_origem,
    'version', 1,
    'cultura_id', v_cultura,
    'missing_fields', to_jsonb(v_missing),
    'next_step', CASE WHEN array_length(v_missing,1) IS NULL THEN 'continuar' ELSE 'identificacao' END,
    'can_edit', true,
    'next_route', '/app/visita/' || v_new_id::text,
    'pdf_status', 'pending'
  );

EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_existing
      FROM public.registros_consultor WHERE client_uuid = p_client_uuid LIMIT 1;
    IF FOUND THEN
      IF NOT public.can_manage_technical_visit(v_uid,v_existing.id)
       OR v_existing.cliente_id IS DISTINCT FROM p_cliente_id
       OR v_existing.fazenda_id IS DISTINCT FROM p_fazenda_id
       OR v_existing.talhao_id IS DISTINCT FROM p_talhao_id
       OR (v_existing.consultor_responsavel <> v_uid
         AND NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor'))) THEN
        RETURN jsonb_build_object('ok', false, 'error', 'idempotency_conflict');
      END IF;
      RETURN jsonb_build_object(
        'ok', true, 'created', false, 'idempotent', true,
        'registro_id', v_existing.id,
        'client_uuid', v_existing.client_uuid,
        'status', v_existing.status::text,
        'origem', v_existing.origem_atendimento,
        'version', v_existing.version,
        'cultura_id', v_existing.cultura_id,
        'missing_fields', CASE WHEN v_existing.cultura_id IS NULL
                               THEN jsonb_build_array('cultura_id') ELSE '[]'::jsonb END,
        'next_step', CASE WHEN v_existing.cultura_id IS NULL THEN 'identificacao' ELSE 'continuar' END,
        'can_edit', v_existing.status IN ('rascunho','em_andamento','reprovado'),
        'next_route', '/app/visita/' || v_existing.id::text,
        'pdf_status', v_existing.pdf_status
      );
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'idempotency_conflict');
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_publish_plan_version(_plan_key text, _price_amount numeric, _currency text, _billing_cycle text, _limits jsonb, _effective_from timestamp with time zone, _reason text, _correlation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_plan public.saas_plans%ROWTYPE; v_id uuid; v_version integer; v_features jsonb; v_existing public.saas_plan_versions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _reason IS NULL OR length(btrim(_reason))<5 OR _correlation_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: motivo e correlação obrigatórios' USING ERRCODE='22023'; END IF;
  IF _price_amount IS NULL OR _price_amount<0 OR upper(btrim(coalesce(_currency,'')))!~'^[A-Z]{3}$' OR _billing_cycle NOT IN ('monthly','quarterly','semiannual','annual','custom') OR _limits IS NULL OR jsonb_typeof(_limits)<>'object' OR _effective_from IS NULL THEN RAISE EXCEPTION 'platform_invalid: versão comercial incompleta' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_existing FROM public.saas_plan_versions v WHERE v.correlation_id=_correlation_id;
  IF FOUND THEN
    IF v_existing.price_amount=_price_amount AND v_existing.currency=upper(btrim(_currency)) AND v_existing.billing_cycle=_billing_cycle AND v_existing.limits_snapshot=_limits AND v_existing.effective_from=_effective_from AND EXISTS(SELECT 1 FROM public.saas_plans p WHERE p.id=v_existing.plan_id AND p.key=_plan_key) THEN RETURN v_existing.id; END IF;
    RAISE EXCEPTION 'platform_conflict: correlação já utilizada com conteúdo diferente' USING ERRCODE='40001';
  END IF;
  SELECT p.* INTO v_plan FROM public.saas_plans p WHERE p.key=_plan_key AND p.active FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: plano inexistente ou inativo' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM public.saas_plan_versions v WHERE v.plan_id=v_plan.id AND v.effective_from<=_effective_from AND (v.effective_to IS NULL OR v.effective_to>_effective_from)) THEN RAISE EXCEPTION 'platform_conflict: versão vigente não pode ser substituída' USING ERRCODE='40001'; END IF;
  SELECT coalesce(max(v.version_number),0)+1 INTO v_version FROM public.saas_plan_versions v WHERE v.plan_id=v_plan.id;
  SELECT coalesce(jsonb_agg(jsonb_build_object('feature_id',pf.feature_id,'enabled',pf.enabled,'limit_value',pf.limit_value,'config',pf.config) ORDER BY pf.feature_id::text),'[]'::jsonb) INTO v_features FROM public.saas_plan_features pf WHERE pf.plan_id=v_plan.id;
  PERFORM platform_private.issue_ticket('saas_plan_version_create',v_plan.id);
  INSERT INTO public.saas_plan_versions(plan_id,version_number,name_snapshot,description_snapshot,price_amount,currency,billing_cycle,limits_snapshot,features_snapshot,effective_from,created_by,publication_reason,correlation_id) VALUES(v_plan.id,v_version,v_plan.name,v_plan.description,_price_amount,upper(btrim(_currency)),_billing_cycle,_limits,v_features,_effective_from,auth.uid(),btrim(_reason),_correlation_id) RETURNING id INTO v_id;
  INSERT INTO public.saas_plan_version_features(plan_version_id,feature_id,enabled,limit_value,config) SELECT v_id,pf.feature_id,pf.enabled,pf.limit_value,pf.config FROM public.saas_plan_features pf WHERE pf.plan_id=v_plan.id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_technical_content_editable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_old uuid; v_new uuid; v_id uuid; v_status text;
BEGIN
 IF TG_OP <> 'INSERT' THEN v_old := (to_jsonb(OLD)->>TG_ARGV[0])::uuid; END IF;
 IF TG_OP <> 'DELETE' THEN v_new := (to_jsonb(NEW)->>TG_ARGV[0])::uuid; END IF;
 FOR v_id IN SELECT DISTINCT x FROM unnest(ARRAY[v_old,v_new]) x WHERE x IS NOT NULL ORDER BY x LOOP
  SELECT r.status::text INTO v_status FROM public.registros_consultor r WHERE r.id=v_id FOR SHARE;
  IF NOT FOUND OR v_status NOT IN ('rascunho','em_andamento') THEN
   RAISE EXCEPTION 'technical_content_locked: reabra a visita pelo fluxo autorizado antes de alterar seu conteúdo' USING ERRCODE='23514';
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.saas_subscription_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF session_user = 'authenticator' AND NOT platform_private.has_ticket('saas_subscription_write', NEW.organization_id) THEN
    RAISE EXCEPTION 'platform_forbidden: assinatura alterada fora do fluxo autorizado' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.saas_plan_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF session_user = 'authenticator' AND NOT platform_private.has_ticket('saas_plan_version_create', NEW.plan_id) THEN
    RAISE EXCEPTION 'platform_forbidden: versão criada fora do fluxo autorizado' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_liberar_recomendacao_produtor(p_registro_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_registro public.registros_consultor;
  v_rec_count integer;
  v_solic_id uuid;
  v_can_approve boolean;
  v_new_version integer;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não autenticado');
  END IF;

  IF NOT public.can_manage_technical_visit(v_user_id, p_registro_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Sem permissão para aprovar esta recomendação.');
  END IF;

  SELECT * INTO v_registro
    FROM public.registros_consultor
   WHERE id = p_registro_id
   FOR UPDATE;

  IF v_registro.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Visita técnica não encontrada.');
  END IF;

  v_can_approve :=
    public.has_role(v_user_id, 'administrador'::public.app_role)
    OR (
      public.has_role(v_user_id, 'gestor'::public.app_role)
      AND v_registro.cliente_id IS NOT NULL
      AND public.has_active_user_cliente_access(
        v_user_id, v_registro.cliente_id, ARRAY['manage']
      )
    );

  IF NOT v_can_approve THEN
    RETURN jsonb_build_object('success', false, 'message', 'Sem permissão para aprovar esta recomendação.');
  END IF;

  IF v_registro.status::text <> 'enviado_aprovacao' THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Visita em status ' || v_registro.status::text || ' não pode ser aprovada.'
    );
  END IF;

  SELECT count(*) INTO v_rec_count
    FROM public.registros_consultor_recomendacoes
   WHERE registro_consultor_id = p_registro_id
     AND (
       coalesce(btrim(recomendacao_tecnica), '') <> ''
       OR coalesce(btrim(observacoes_finais), '') <> ''
       OR coalesce(btrim(estrategia_manejo::text), '') <> ''
     );

  IF v_rec_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não existe recomendação técnica preenchida para esta visita.');
  END IF;

  v_solic_id := v_registro.solicitacao_id;
  v_new_version := COALESCE(v_registro.version, 1) + 1;

  INSERT INTO public.aprovacoes_tecnicas
    (registro_consultor_id,status_aprovacao,aprovado_por,comentario_gestor,data_aprovacao,aprovado_por_role,override)
  VALUES (p_registro_id,'aprovado',v_user_id,'Liberação da recomendação ao produtor',now(),
    CASE WHEN public.has_role(v_user_id,'administrador'::public.app_role) THEN 'administrador'::public.app_role ELSE 'gestor'::public.app_role END,false);

  UPDATE public.registros_consultor
     SET status = 'aprovado'::public.status_registro_consultor,
         version = v_new_version,
         updated_at = now()
   WHERE id = p_registro_id;

  IF v_solic_id IS NOT NULL THEN
    UPDATE public.portal_solicitacoes
       SET status = 'aguardando_decisao_produtor', updated_at = now()
     WHERE id = v_solic_id;

    INSERT INTO public.solicitacoes_timeline
      (solicitacao_id, tipo_evento, descricao, usuario_id)
    VALUES
      (v_solic_id, 'recomendacao_liberada', 'Recomendação técnica liberada para decisão do produtor.', v_user_id);
  END IF;

  INSERT INTO public.registros_consultor_status_log
    (registro_consultor_id, status_anterior, status_novo, motivo, changed_by, changed_at)
  VALUES
    (p_registro_id, v_registro.status::text, 'aprovado', 'Liberação da recomendação ao produtor', v_user_id, now());

  INSERT INTO public.visitas_logs
    (registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES
    (p_registro_id, v_solic_id, 'recomendacao_liberada',
     'Recomendação técnica liberada ao produtor.', v_user_id,
     jsonb_build_object('status_anterior', v_registro.status::text,
                        'status_novo', 'aprovado',
                        'version', v_new_version));

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Recomendação liberada ao produtor com sucesso.',
    'registro_id', p_registro_id,
    'solicitacao_id', v_solic_id,
    'status_anterior', v_registro.status::text,
    'status_novo', 'aprovado',
    'version', v_new_version
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', 'Erro ao liberar recomendação: ' || SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.saas_plan_version_feature_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_plan uuid; v_status text;
BEGIN
  SELECT plan_id,status INTO v_plan,v_status FROM public.saas_plan_versions WHERE id=COALESCE(NEW.plan_version_id,OLD.plan_version_id);
  IF v_status <> 'DRAFT' THEN RAISE EXCEPTION 'saas_version_immutable: conteúdo publicado não pode ser alterado'; END IF;
  IF session_user='authenticator' AND NOT platform_private.has_ticket('saas_plan_version_write',v_plan) THEN
    RAISE EXCEPTION 'platform_forbidden: conteúdo alterado fora do fluxo autorizado' USING ERRCODE='42501';
  END IF;
  RETURN COALESCE(NEW,OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.expire_due_trials(_limit integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text; v_count integer:=0; v_row record; v_correlation uuid;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF current_user<>'postgres' AND v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF _limit<1 OR _limit>500 THEN RAISE EXCEPTION 'platform_invalid: limite inválido' USING ERRCODE='22023'; END IF;
  FOR v_row IN SELECT id,organization_id FROM public.organization_subscriptions WHERE status='TRIAL' AND plan_version_id IS NOT NULL AND trial_ends_at IS NOT NULL AND trial_ends_at<=now() ORDER BY trial_ends_at FOR UPDATE SKIP LOCKED LIMIT _limit LOOP
    v_correlation:=gen_random_uuid();
    PERFORM platform_private.issue_ticket('saas_subscription_write',v_row.organization_id);
    PERFORM set_config('app.saas_change_reason','trial expirado automaticamente',true);
    PERFORM set_config('app.saas_change_action','expire_trial',true);
    PERFORM set_config('app.saas_correlation_id',v_correlation::text,true);
    UPDATE public.organization_subscriptions SET status='EXPIRED',state_changed_at=now(),last_correlation_id=v_correlation WHERE id=v_row.id AND status='TRIAL';
    IF FOUND THEN v_count:=v_count+1; END IF;
  END LOOP;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_extend_trial(_subscription_id uuid, _new_trial_end timestamp with time zone, _reason text, _correlation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_sub public.organization_subscriptions%ROWTYPE; v_existing uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _reason IS NULL OR length(btrim(_reason))<5 OR _correlation_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: motivo e correlação obrigatórios' USING ERRCODE='22023'; END IF;
  SELECT h.subscription_id INTO v_existing FROM public.organization_subscription_history h WHERE h.correlation_id=_correlation_id;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  SELECT * INTO v_sub FROM public.organization_subscriptions WHERE id=_subscription_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: assinatura inexistente' USING ERRCODE='22023'; END IF;
  SELECT h.subscription_id INTO v_existing FROM public.organization_subscription_history h WHERE h.correlation_id=_correlation_id;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  IF v_sub.status<>'TRIAL' OR v_sub.plan_version_id IS NULL OR v_sub.trial_ends_at IS NULL OR _new_trial_end<=v_sub.trial_ends_at OR _new_trial_end>v_sub.trial_ends_at+interval '14 days' THEN RAISE EXCEPTION 'platform_conflict: extensão de trial inválida' USING ERRCODE='40001'; END IF;
  PERFORM platform_private.issue_ticket('saas_subscription_write',v_sub.organization_id);
  PERFORM set_config('app.saas_change_reason',btrim(_reason),true); PERFORM set_config('app.saas_change_action','extend_trial',true); PERFORM set_config('app.saas_correlation_id',_correlation_id::text,true);
  UPDATE public.organization_subscriptions SET trial_ends_at=_new_trial_end,state_changed_at=now(),last_correlation_id=_correlation_id WHERE id=_subscription_id;
  RETURN _subscription_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_financial_category_platform_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'superadmin'::public.app_role) THEN
  RAISE EXCEPTION 'FINANCIAL_CATEGORY_PLATFORM_WRITE_REQUIRED' USING ERRCODE='42501';
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
