$function$

CREATE OR REPLACE FUNCTION public.saas_trial_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP='INSERT' AND NEW.status='TRIAL' AND NEW.plan_version_id IS NOT NULL AND (NEW.started_at IS NULL OR NEW.trial_ends_at IS NULL OR NEW.trial_ends_at<>NEW.started_at+interval '14 days') THEN
    RAISE EXCEPTION 'platform_invalid: trial novo deve ter exatamente 14 dias' USING ERRCODE='22023';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.my_entitlement_context()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_org uuid;
  v_status public.saas_subscription_status;
  v_version uuid;
  v_trial_end timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'saas_auth_required' USING ERRCODE = '42501';
  END IF;

  IF public.is_platform_superadmin(auth.uid()) THEN
    RETURN 'platform_superadmin';
  END IF;

  SELECT p.organization_id
    INTO v_org
  FROM public.profiles p
  JOIN public.organizations org
    ON org.id = p.organization_id
   AND org.ativo IS TRUE
  WHERE p.user_id = auth.uid()
    AND p.ativo IS TRUE
    AND p.organization_id IS NOT NULL
  LIMIT 1;

  IF v_org IS NULL THEN RETURN 'no_context'; END IF;

  SELECT s.status, s.plan_version_id, s.trial_ends_at
    INTO v_status, v_version, v_trial_end
  FROM public.organization_subscriptions s
  WHERE s.organization_id = v_org
  ORDER BY s.started_at DESC, s.id DESC
  LIMIT 1;

  IF NOT FOUND THEN RETURN 'no_subscription'; END IF;
  IF v_version IS NULL THEN RETURN 'legacy_unversioned'; END IF;
  IF v_status = 'ACTIVE' THEN RETURN 'active'; END IF;
  IF v_status = 'TRIAL' AND v_trial_end IS NOT NULL AND v_trial_end > now() THEN RETURN 'trial_active'; END IF;
  IF v_status = 'TRIAL' THEN RETURN 'trial_expired'; END IF;
  RETURN 'blocked_status';
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_service_apply_provider_settings(p_actor uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
DECLARE
  v_row       public.communication_provider_settings%ROWTYPE;
  v_updates   jsonb := '{}'::jsonb;
  v_secret_ops jsonb := '[]'::jsonb;
  v_changed   text[] := ARRAY[]::text[];
  v_op        jsonb;
  v_slot      text;
  v_col       text;
  v_action    text;
  v_value     text;
  v_existing  uuid;
  v_new_id    uuid;
  v_name      text;
  v_effective_test_mode boolean;
  v_effective_email_on  boolean;
  v_effective_wa_on     boolean;
  v_effective_delivery_on boolean;
  v_effective_smtp_pw_configured boolean;
  v_effective_wa_tok_configured  boolean;
BEGIN
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_actor IS NULL THEN
    RAISE EXCEPTION 'invalid_actor' USING ERRCODE = '22023';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'invalid_payload' USING ERRCODE = '22023';
  END IF;

  v_updates    := coalesce(p_payload->'updates', '{}'::jsonb);
  v_secret_ops := coalesce(p_payload->'secret_ops', '[]'::jsonb);

  IF jsonb_typeof(v_updates) <> 'object' THEN
    RAISE EXCEPTION 'invalid_updates' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_secret_ops) <> 'array' THEN
    RAISE EXCEPTION 'invalid_secret_ops' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row FROM public.communication_provider_settings WHERE id = 1 FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'settings_row_missing' USING ERRCODE = 'P0002';
  END IF;

  FOR v_op IN SELECT * FROM jsonb_array_elements(v_secret_ops) LOOP
    v_slot   := v_op->>'slot';
    v_action := v_op->>'action';
    v_value  := v_op->>'value';

    CASE v_slot
      WHEN 'smtp_password'         THEN v_col := 'secret_smtp_password';         v_name := 'comm_smtp_password';
      WHEN 'whatsapp_access_token' THEN v_col := 'secret_whatsapp_access_token'; v_name := 'comm_whatsapp_access_token';
      WHEN 'whatsapp_app_secret'   THEN v_col := 'secret_whatsapp_app_secret';   v_name := 'comm_whatsapp_app_secret';
      WHEN 'whatsapp_verify_token' THEN v_col := 'secret_whatsapp_verify_token'; v_name := 'comm_whatsapp_verify_token';
      ELSE RAISE EXCEPTION 'invalid_slot' USING ERRCODE = '22023';
    END CASE;

    EXECUTE format('SELECT %I FROM public.communication_provider_settings WHERE id = 1', v_col)
      INTO v_existing;

    IF v_action = 'set' THEN
      IF v_value IS NULL OR length(v_value) = 0 THEN
        RAISE EXCEPTION 'empty_secret_value' USING ERRCODE = '22023';
      END IF;
      IF v_existing IS NOT NULL THEN
        PERFORM vault.update_secret(
          v_existing,
          v_value,
          v_name || '_' || extract(epoch from now())::bigint::text,
          ''
        );
        v_new_id := v_existing;
      ELSE
        v_new_id := vault.create_secret(
          v_value,
          v_name || '_' || extract(epoch from now())::bigint::text,
          ''
        );
      END IF;
      EXECUTE format('UPDATE public.communication_provider_settings SET %I = $1 WHERE id = 1', v_col)
        USING v_new_id;
      v_changed := array_append(v_changed, v_col);
    ELSIF v_action = 'clear' THEN
      IF v_existing IS NOT NULL THEN
        DELETE FROM vault.secrets WHERE id = v_existing;
        EXECUTE format('UPDATE public.communication_provider_settings SET %I = NULL WHERE id = 1', v_col);
      END IF;
      v_changed := array_append(v_changed, v_col);
    ELSE
      RAISE EXCEPTION 'invalid_secret_action' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.communication_provider_settings_audit(actor_id, action, secret_field, changed_fields)
    VALUES (p_actor, 'secret_' || v_action, v_slot, ARRAY[v_col]);
  END LOOP;

  IF v_updates ? 'test_mode_enabled' THEN
    UPDATE public.communication_provider_settings SET test_mode_enabled = (v_updates->>'test_mode_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'test_mode_enabled');
  END IF;
  IF v_updates ? 'allowed_emails' THEN
    UPDATE public.communication_provider_settings
       SET allowed_emails = ARRAY(SELECT jsonb_array_elements_text(v_updates->'allowed_emails'))
     WHERE id = 1;
    v_changed := array_append(v_changed, 'allowed_emails');
  END IF;
  IF v_updates ? 'allowed_phones' THEN
    UPDATE public.communication_provider_settings
       SET allowed_phones = ARRAY(SELECT jsonb_array_elements_text(v_updates->'allowed_phones'))
     WHERE id = 1;
    v_changed := array_append(v_changed, 'allowed_phones');
  END IF;
  IF v_updates ? 'delivery_enabled' THEN
    UPDATE public.communication_provider_settings SET delivery_enabled = (v_updates->>'delivery_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'delivery_enabled');
  END IF;
  IF v_updates ? 'email_delivery_enabled' THEN
    UPDATE public.communication_provider_settings SET email_delivery_enabled = (v_updates->>'email_delivery_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'email_delivery_enabled');
  END IF;
  IF v_updates ? 'whatsapp_delivery_enabled' THEN
    UPDATE public.communication_provider_settings SET whatsapp_delivery_enabled = (v_updates->>'whatsapp_delivery_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'whatsapp_delivery_enabled');
  END IF;
  IF v_updates ? 'inapp_delivery_enabled' THEN
    UPDATE public.communication_provider_settings SET inapp_delivery_enabled = (v_updates->>'inapp_delivery_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'inapp_delivery_enabled');
  END IF;
  IF v_updates ? 'whatsapp_webhook_enabled' THEN
    UPDATE public.communication_provider_settings SET whatsapp_webhook_enabled = (v_updates->>'whatsapp_webhook_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'whatsapp_webhook_enabled');
  END IF;
  IF v_updates ? 'smtp_host' THEN
    UPDATE public.communication_provider_settings SET smtp_host = NULLIF(v_updates->>'smtp_host','') WHERE id = 1;
    v_changed := array_append(v_changed, 'smtp_host');
  END IF;
  IF v_updates ? 'smtp_port' THEN
    UPDATE public.communication_provider_settings SET smtp_port = NULLIF(v_updates->>'smtp_port','')::integer WHERE id = 1;
    v_changed := array_append(v_changed, 'smtp_port');
  END IF;
  IF v_updates ? 'smtp_user' THEN
    UPDATE public.communication_provider_settings SET smtp_user = NULLIF(v_updates->>'smtp_user','') WHERE id = 1;
    v_changed := array_append(v_changed, 'smtp_user');
  END IF;
  IF v_updates ? 'smtp_from' THEN
    UPDATE public.communication_provider_settings SET smtp_from = NULLIF(v_updates->>'smtp_from','') WHERE id = 1;
    v_changed := array_append(v_changed, 'smtp_from');
  END IF;
  IF v_updates ? 'whatsapp_phone_number_id' THEN
    UPDATE public.communication_provider_settings SET whatsapp_phone_number_id = NULLIF(v_updates->>'whatsapp_phone_number_id','') WHERE id = 1;
    v_changed := array_append(v_changed, 'whatsapp_phone_number_id');
  END IF;
  IF v_updates ? 'whatsapp_api_version' THEN
    UPDATE public.communication_provider_settings SET whatsapp_api_version = NULLIF(v_updates->>'whatsapp_api_version','') WHERE id = 1;
    v_changed := array_append(v_changed, 'whatsapp_api_version');
  END IF;

  SELECT * INTO v_row FROM public.communication_provider_settings WHERE id = 1;
  v_effective_test_mode        := v_row.test_mode_enabled;
  v_effective_email_on         := v_row.email_delivery_enabled;
  v_effective_wa_on            := v_row.whatsapp_delivery_enabled;
  v_effective_delivery_on      := v_row.delivery_enabled;
  v_effective_smtp_pw_configured := v_row.secret_smtp_password  IS NOT NULL AND v_row.smtp_host IS NOT NULL AND v_row.smtp_port IS NOT NULL AND v_row.smtp_user IS NOT NULL AND v_row.smtp_from IS NOT NULL;
  v_effective_wa_tok_configured  := v_row.secret_whatsapp_access_token IS NOT NULL AND v_row.whatsapp_phone_number_id IS NOT NULL AND v_row.whatsapp_api_version IS NOT NULL;

  IF NOT v_effective_test_mode THEN
    IF v_effective_delivery_on AND v_effective_email_on AND NOT v_effective_smtp_pw_configured THEN
      RAISE EXCEPTION 'test_mode_off_requires_email_provider' USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_delivery_on AND v_effective_wa_on AND NOT v_effective_wa_tok_configured THEN
      RAISE EXCEPTION 'test_mode_off_requires_whatsapp_provider' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF v_effective_delivery_on AND v_effective_email_on AND NOT v_effective_smtp_pw_configured THEN
    RAISE EXCEPTION 'email_enabled_requires_provider_configured' USING ERRCODE = 'P0001';
  END IF;
  IF v_effective_delivery_on AND v_effective_wa_on AND NOT v_effective_wa_tok_configured THEN
    RAISE EXCEPTION 'whatsapp_enabled_requires_provider_configured' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.communication_provider_settings
     SET updated_at = now(), updated_by = p_actor
   WHERE id = 1;

  INSERT INTO public.communication_provider_settings_audit(actor_id, action, changed_fields)
  VALUES (p_actor, 'apply', v_changed);

  RETURN jsonb_build_object('ok', true, 'changed_fields', to_jsonb(v_changed));
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_validate_plan_version_draft(_draft_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v public.saas_plan_versions%ROWTYPE;
  v_missing text[] := ARRAY[]::text[];
  v_feature_keys jsonb;
  v_feature_count integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_draft_id;
  IF NOT FOUND OR v.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'platform_invalid: rascunho inexistente' USING ERRCODE='22023';
  END IF;

  SELECT count(*),coalesce(jsonb_agg(f.key ORDER BY f.key) FILTER (WHERE vf.enabled),'[]'::jsonb)
    INTO v_feature_count,v_feature_keys
  FROM public.saas_plan_version_features vf
  JOIN public.saas_features f ON f.id=vf.feature_id
  WHERE vf.plan_version_id=v.id AND vf.enabled;

  IF v.price_amount IS NULL OR v.price_amount <= 0 THEN v_missing:=array_append(v_missing,'price_amount'); END IF;
  IF v.currency IS NULL OR v.currency NOT IN ('BRL','USD','EUR') THEN v_missing:=array_append(v_missing,'currency'); END IF;
  IF v.billing_cycle IS NULL OR v.billing_cycle NOT IN ('monthly','quarterly','semiannual','annual','custom') THEN v_missing:=array_append(v_missing,'billing_cycle'); END IF;
  IF v.trial_days IS NULL OR v.trial_days < 1 OR v.trial_days > 365 THEN v_missing:=array_append(v_missing,'trial_days'); END IF;
  IF v.effective_from IS NULL THEN v_missing:=array_append(v_missing,'effective_from'); END IF;
  IF v.limits_snapshot IS NULL OR jsonb_typeof(v.limits_snapshot) <> 'object' THEN v_missing:=array_append(v_missing,'limits'); END IF;
  IF v_feature_count=0 THEN v_missing:=array_append(v_missing,'features'); END IF;

  IF cardinality(v_missing)=0 THEN
    BEGIN
      PERFORM platform_private.validate_commercial_plan_payload(v.plan_id,v.limits_snapshot,v_feature_keys);
    EXCEPTION WHEN SQLSTATE '22023' THEN
      v_missing:=array_append(v_missing,'commercial_payload');
    END;
  END IF;

  RETURN jsonb_build_object(
    'complete',cardinality(v_missing)=0,
    'valid',cardinality(v_missing)=0,
    'missing',to_jsonb(v_missing),
    'feature_count',v_feature_count,
    'revision',v.revision
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_save_plan_version_draft(_draft_id uuid, _plan_key text, _price_amount numeric, _currency text, _billing_cycle text, _trial_days integer, _limits jsonb, _effective_from timestamp with time zone, _features jsonb, _reason text, _idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_plan public.saas_plans%ROWTYPE;
  v_draft public.saas_plan_versions%ROWTYPE;
  v_id uuid;
  v_old jsonb;
  v_number integer;
  v_feature_keys jsonb;
  v_features_snapshot jsonb;
  v_existing uuid;
  v_reason text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023';
  END IF;
  v_reason := platform_private.normalize_commercial_reason(_reason);
  IF _features IS NULL OR jsonb_typeof(_features) <> 'array' THEN
    RAISE EXCEPTION 'platform_invalid: funcionalidades inválidas' USING ERRCODE='22023';
  END IF;

  SELECT p.* INTO v_plan
  FROM public.saas_plans p
  WHERE p.key=_plan_key AND p.active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform_invalid: plano inexistente ou inativo' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('saas_plan_version:' || v_plan.id::text,0));

  SELECT coalesce(jsonb_agg(DISTINCT btrim(item->>'feature_key')),'[]'::jsonb)
    INTO v_feature_keys
  FROM jsonb_array_elements(_features) item
  WHERE coalesce((item->>'enabled')::boolean,true)
    AND nullif(btrim(item->>'feature_key'),'') IS NOT NULL;

  PERFORM platform_private.validate_commercial_plan_payload(v_plan.id,_limits,v_feature_keys);

  SELECT a.plan_version_id INTO v_existing
  FROM public.saas_plan_version_audit a
  JOIN public.saas_plan_versions pv ON pv.id=a.plan_version_id
  WHERE a.idempotency_key=_idempotency_key
    AND a.actor_user_id=auth.uid()
    AND a.action IN ('draft_created','draft_updated')
    AND pv.plan_id=v_plan.id
  ORDER BY a.created_at DESC
  LIMIT 1;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  IF _draft_id IS NULL THEN
    SELECT id INTO v_id FROM public.saas_plan_versions
    WHERE plan_id=v_plan.id AND status='DRAFT'
    FOR UPDATE;
    IF v_id IS NOT NULL THEN
      RAISE EXCEPTION 'platform_conflict: já existe rascunho para este plano' USING ERRCODE='40001';
    END IF;
    SELECT coalesce(max(version_number),0)+1 INTO v_number
    FROM public.saas_plan_versions WHERE plan_id=v_plan.id;
    v_id:=gen_random_uuid();
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_create',v_plan.id);
    INSERT INTO public.saas_plan_versions(
      id,plan_id,version_number,name_snapshot,description_snapshot,price_amount,currency,
      billing_cycle,trial_days,limits_snapshot,features_snapshot,effective_from,status,
      revision,draft_key,created_by,updated_at
    ) VALUES (
      v_id,v_plan.id,v_number,v_plan.name,v_plan.description,_price_amount,
      nullif(upper(btrim(coalesce(_currency,''))),''),nullif(_billing_cycle,''),_trial_days,
      _limits,'[]'::jsonb,_effective_from,'DRAFT',1,_idempotency_key,auth.uid(),now()
    );
  ELSE
    SELECT * INTO v_draft
    FROM public.saas_plan_versions
    WHERE id=_draft_id AND plan_id=v_plan.id
    FOR UPDATE;
    IF NOT FOUND OR v_draft.status <> 'DRAFT' THEN
      RAISE EXCEPTION 'platform_invalid: rascunho inexistente' USING ERRCODE='22023';
    END IF;
    v_id:=v_draft.id;
    v_old:=to_jsonb(v_draft);
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v_plan.id);
    UPDATE public.saas_plan_versions SET
      price_amount=_price_amount,
      currency=nullif(upper(btrim(coalesce(_currency,''))),'') ,
      billing_cycle=nullif(_billing_cycle,''),
      trial_days=_trial_days,
      limits_snapshot=_limits,
      effective_from=_effective_from,
      revision=revision+1,
      updated_at=now()
    WHERE id=v_id;
  END IF;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v_plan.id);
  DELETE FROM public.saas_plan_version_features WHERE plan_version_id=v_id;
  INSERT INTO public.saas_plan_version_features(plan_version_id,feature_id,enabled,limit_value,config)
  SELECT v_id,f.id,true,NULL,'{}'::jsonb
  FROM jsonb_array_elements_text(v_feature_keys) selected(feature_key)
  JOIN public.saas_features f ON f.key=selected.feature_key;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'feature_id',vf.feature_id,
    'feature_key',f.key,
    'feature_name',f.name,
    'module_key',m.key,
    'module_name',m.name,
    'enabled',vf.enabled,
    'limit_value',vf.limit_value,
    'config',vf.config
  ) ORDER BY m.key,f.key),'[]'::jsonb)
  INTO v_features_snapshot
  FROM public.saas_plan_version_features vf
  JOIN public.saas_features f ON f.id=vf.feature_id
  JOIN public.saas_modules m ON m.id=f.module_id
  WHERE vf.plan_version_id=v_id;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v_plan.id);
  UPDATE public.saas_plan_versions
  SET features_snapshot=v_features_snapshot,updated_at=now()
  WHERE id=v_id;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v_plan.id);
  INSERT INTO public.saas_plan_version_audit(
    plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key
  ) VALUES (
    v_id,CASE WHEN _draft_id IS NULL THEN 'draft_created' ELSE 'draft_updated' END,
    v_old,(SELECT to_jsonb(current_version) FROM public.saas_plan_versions current_version WHERE current_version.id=v_id),
    v_reason,'platform_rpc',auth.uid(),_idempotency_key
  );
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.saas_ingest_payment_event_non_operational(_provider text, _environment text, _provider_event_id text, _event_type text, _occurred_at timestamp with time zone, _signature_status text, _aggregate_ref text, _sequence_number bigint, _payload_hash text, _payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text; v_id uuid; v_latest bigint;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF current_user<>'postgres' AND v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF _provider NOT IN ('mercado_pago','stripe','mock') OR _environment NOT IN ('test','live') OR _provider_event_id IS NULL OR length(_provider_event_id)>255 OR _event_type IS NULL OR _occurred_at IS NULL OR _payload_hash IS NULL OR jsonb_typeof(_payload)<>'object' THEN RAISE EXCEPTION 'payment_invalid'; END IF;
  SELECT id INTO v_id FROM public.saas_payment_events WHERE provider=_provider AND environment=_environment AND provider_event_id=_provider_event_id;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  SELECT max(sequence_number) INTO v_latest FROM public.saas_payment_events WHERE provider=_provider AND environment=_environment AND aggregate_ref=_aggregate_ref AND processing_status IN ('pending','processed');
  INSERT INTO public.saas_payment_events(provider,environment,provider_event_id,event_type,occurred_at,signature_status,processing_status,aggregate_ref,sequence_number,payload_hash,payload)
  VALUES(_provider,_environment,_provider_event_id,_event_type,_occurred_at,_signature_status,CASE WHEN _signature_status<>'valid' THEN 'ignored' WHEN _sequence_number IS NOT NULL AND v_latest IS NOT NULL AND _sequence_number<=v_latest THEN 'ignored' ELSE 'pending' END,_aggregate_ref,_sequence_number,_payload_hash,_payload) RETURNING id INTO v_id;
  INSERT INTO public.saas_payment_audit(event_id,action,new_values,reason,origin) VALUES(v_id,'event_ingested',jsonb_build_object('processing_status',(SELECT processing_status FROM public.saas_payment_events WHERE id=v_id),'signature_status',_signature_status),CASE WHEN _signature_status<>'valid' THEN 'assinatura inválida; evento ignorado' WHEN _sequence_number IS NOT NULL AND v_latest IS NOT NULL AND _sequence_number<=v_latest THEN 'evento fora de ordem; evento ignorado' ELSE 'evento aceito em modo não operacional' END,'internal_non_operational');
  IF _signature_status='valid' AND NOT (_sequence_number IS NOT NULL AND v_latest IS NOT NULL AND _sequence_number<=v_latest) THEN
    INSERT INTO public.saas_payment_outbox(event_id,topic,payload,status) VALUES(v_id,'payment.reconcile',jsonb_build_object('event_id',v_id),'held');
  END IF;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_validar_integridade_esteira(p_os_id uuid, p_origem_os text, p_acao_solicitada text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
    v_integridade RECORD;
    v_permitido BOOLEAN := TRUE;
    v_bloqueios TEXT[] := ARRAY[]::TEXT[];
    v_status_esteira TEXT;
    v_pode_finalizar BOOLEAN;
    v_user_id UUID := auth.uid();
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('permitido', FALSE, 'bloqueios', ARRAY['Usuário não autenticado'], 'status_esteira_atual', 'erro_seguranca');
    END IF;

    SELECT * INTO v_integridade FROM public.vw_os_integridade_esteira WHERE os_id = p_os_id AND origem_os = p_origem_os;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('permitido', FALSE, 'bloqueios', ARRAY['Ordem de Serviço não encontrada'], 'status_esteira_atual', 'nao_encontrado');
    END IF;

    v_status_esteira := v_integridade.status_esteira_oficial;
    v_pode_finalizar := v_integridade.pode_finalizar;

    CASE p_acao_solicitada
        WHEN 'enviar_cq' THEN
            IF v_integridade.lote_id IS NULL THEN
                v_permitido := FALSE;
                v_bloqueios := array_append(v_bloqueios, 'Não é possível enviar para CQ sem lote gerado.');
            END IF;
        WHEN 'enviar_envase' THEN
            IF v_integridade.cq_resultado IS DISTINCT FROM 'aprovado' THEN
                v_permitido := FALSE;
                v_bloqueios := array_append(v_bloqueios, 'Não é possível envasar sem CQ aprovado.');
            END IF;
        WHEN 'gerar_estoque' THEN
            IF v_integridade.envase_id IS NULL THEN
                v_permitido := FALSE;
                v_bloqueios := array_append(v_bloqueios, 'Não é possível gerar estoque sem envase concluído.');
            END IF;
        WHEN 'criar_entrega' THEN
            IF v_integridade.estoque_id IS NULL THEN
                v_permitido := FALSE;
                v_bloqueios := array_append(v_bloqueios, 'Não é possível criar entrega sem estoque disponível.');
            END IF;
        WHEN 'finalizar_os' THEN
            IF NOT COALESCE(v_integridade.pode_finalizar, FALSE) THEN
                v_permitido := FALSE;
                v_bloqueios := COALESCE(v_integridade.bloqueios, ARRAY['Ordem não pode ser finalizada.']);
            END IF;
        ELSE
            NULL;
    END CASE;

    RETURN jsonb_build_object('permitido', v_permitido, 'bloqueios', v_bloqueios, 'status_esteira_atual', v_status_esteira, 'pode_finalizar', v_pode_finalizar);
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_catalogo_volumes_calc()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.volume_ml IS NOT NULL AND NEW.volume_ml > 0 AND NEW.preco_brl IS NOT NULL THEN
    NEW.preco_litro_brl := round(NEW.preco_brl / (NEW.volume_ml / 1000.0), 2);
    NEW.valor_dose_100ml_brl := round(NEW.preco_litro_brl / 10.0, 2);
  ELSE
    NEW.preco_litro_brl := NULL;
    NEW.valor_dose_100ml_brl := NULL;
  END IF;
  IF NEW.volume_ml IS NOT NULL AND NEW.volume_ml > 0 THEN
    NEW.doses_por_volume := round(NEW.volume_ml / 100.0, 4);
  ELSE
    NEW.doses_por_volume := NULL;
  END IF;
  RETURN NEW;
END;
$function$

