CREATE OR REPLACE FUNCTION public.tg_entrega_termos_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'rascunho' THEN
      RAISE EXCEPTION 'termo_imutavel: documento % nao pode ser excluido', OLD.id
        USING ERRCODE = 'raise_exception';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status IN ('assinado','cancelado','substituido') THEN
    IF NEW.snapshot IS DISTINCT FROM OLD.snapshot
       OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
       OR NEW.versao IS DISTINCT FROM OLD.versao
       OR NEW.template_versao IS DISTINCT FROM OLD.template_versao
       OR NEW.entrega_id IS DISTINCT FROM OLD.entrega_id
       OR NEW.recebedor_nome IS DISTINCT FROM OLD.recebedor_nome
       OR NEW.recebedor_documento IS DISTINCT FROM OLD.recebedor_documento
       OR NEW.assinatura_hash IS DISTINCT FROM OLD.assinatura_hash
       OR NEW.assinado_em IS DISTINCT FROM OLD.assinado_em
       OR NEW.assinado_por IS DISTINCT FROM OLD.assinado_por
       OR NEW.cobertura IS DISTINCT FROM OLD.cobertura THEN
      RAISE EXCEPTION 'termo_imutavel: documento assinado nao pode ser alterado'
        USING ERRCODE = 'raise_exception';
    END IF;
    -- PDF só pode ser gravado uma vez por versão
    IF OLD.pdf_path IS NOT NULL AND NEW.pdf_path IS DISTINCT FROM OLD.pdf_path THEN
      RAISE EXCEPTION 'termo_pdf_imutavel: ja existe PDF ativo para esta versao'
        USING ERRCODE = 'raise_exception';
    END IF;
    IF OLD.status <> 'assinado' AND NEW.status <> OLD.status THEN
      RAISE EXCEPTION 'termo_estado_terminal: transicao % -> % proibida', OLD.status, NEW.status
        USING ERRCODE = 'raise_exception';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_fiscal_operation_policy_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.policy_status = 'PUBLISHED' THEN
      RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada nao pode ser excluida (id=%)', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.policy_status = 'PUBLISHED' AND NEW.policy_status = 'PUBLISHED' THEN
    IF (OLD.cfop, OLD.nature_operation, OLD.direction, OLD.origin_uf, OLD.destination_uf,
        OLD.crt, OLD.ncm_prefix, OLD.final_consumer, OLD.taxpayer_indicator,
        OLD.valid_from, OLD.valid_until, OLD.source_id, OLD.legal_basis)
       IS DISTINCT FROM
       (NEW.cfop, NEW.nature_operation, NEW.direction, NEW.origin_uf, NEW.destination_uf,
        NEW.crt, NEW.ncm_prefix, NEW.final_consumer, NEW.taxpayer_indicator,
        NEW.valid_from, NEW.valid_until, NEW.source_id, NEW.legal_basis) THEN
      RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada e imutavel; crie nova vigencia (id=%)', OLD.id;
    END IF;
  END IF;
  IF OLD.policy_status = 'PUBLISHED' AND NEW.policy_status = 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada nao retorna a DRAFT (id=%)', OLD.id;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_fiscal_tax_rule_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('PUBLISHED','SUPERSEDED') THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: versao publicada nao pode ser excluida (rule_key=% v=%)', OLD.rule_key, OLD.version;
    END IF;
    RETURN OLD;
  END IF;

  -- H7-101: máquina de estados fechada. Nenhum caminho reabilita histórico.
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    IF NOT (
         (OLD.status = 'DRAFT'     AND NEW.status IN ('PUBLISHED'))
      OR (OLD.status = 'PUBLISHED' AND NEW.status = 'SUPERSEDED')
    ) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_STATUS_TRANSITION_FORBIDDEN: % -> % nao permitido (rule_key=% v=%)',
        OLD.status, NEW.status, OLD.rule_key, OLD.version
        USING HINT = 'Regra arquivada nunca volta a vigorar. Crie nova versao DRAFT e publique via rpc_fiscal_tax_rule_publish.';
    END IF;
    -- Publicação só pelo fluxo canônico (fonte oficial + SoD + aprovador).
    IF NEW.status = 'PUBLISHED' AND (NEW.published_by IS NULL OR NEW.published_at IS NULL) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_PUBLISH_CHANNEL: publicacao exige rpc_fiscal_tax_rule_publish (autoria/aprovacao obrigatorias).';
    END IF;
  END IF;

  -- H7-101: conteúdo de versão publicada OU arquivada é imutável.
  IF OLD.status IN ('PUBLISHED','SUPERSEDED') THEN
    IF OLD.status = 'PUBLISHED' AND NEW.status = 'DRAFT' THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: versao publicada nao retorna a DRAFT (rule_key=% v=%)', OLD.rule_key, OLD.version;
    END IF;
    IF (OLD.tax_kind, OLD.calc_mode, OLD.crt, OLD.origin_uf, OLD.destination_uf, OLD.ncm_prefix,
        OLD.product_category, OLD.final_consumer, OLD.taxpayer_indicator, OLD.cst, OLD.csosn,
        OLD.rate, OLD.base_reduction_pct, OLD.deferral_pct, OLD.mva_pct, OLD.fcp_rate,
        OLD.difal_dest_share_pct, OLD.legal_basis, OLD.source_id, OLD.valid_from, OLD.valid_until, OLD.version)
       IS DISTINCT FROM
       (NEW.tax_kind, NEW.calc_mode, NEW.crt, NEW.origin_uf, NEW.destination_uf, NEW.ncm_prefix,
        NEW.product_category, NEW.final_consumer, NEW.taxpayer_indicator, NEW.cst, NEW.csosn,
        NEW.rate, NEW.base_reduction_pct, NEW.deferral_pct, NEW.mva_pct, NEW.fcp_rate,
        NEW.difal_dest_share_pct, NEW.legal_basis, NEW.source_id, NEW.valid_from, NEW.valid_until, NEW.version) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: conteudo de versao % e imutavel; crie nova versao (rule_key=% v=%)',
        OLD.status, OLD.rule_key, OLD.version;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.tg_pcp_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  -- imutabilidade após aprovação: só permite transição para inativo
  IF TG_OP = 'UPDATE' AND OLD.status = 'aprovado' THEN
    IF NEW.status NOT IN ('aprovado','inativo') THEN
      RAISE EXCEPTION 'compliance_profile_immutable: perfil aprovado só pode ser inativado';
    END IF;
    IF NEW.status = 'aprovado' AND (
         NEW.conservacao_texto IS DISTINCT FROM OLD.conservacao_texto
      OR NEW.uso_texto IS DISTINCT FROM OLD.uso_texto
      OR NEW.transporte_texto IS DISTINCT FROM OLD.transporte_texto
      OR NEW.advertencias IS DISTINCT FROM OLD.advertencias
      OR NEW.validade_meses IS DISTINCT FROM OLD.validade_meses
      OR NEW.registro_mapa IS DISTINCT FROM OLD.registro_mapa
      OR NEW.responsavel_tecnico_registro IS DISTINCT FROM OLD.responsavel_tecnico_registro
      OR NEW.versao IS DISTINCT FROM OLD.versao
      OR NEW.perfil_key IS DISTINCT FROM OLD.perfil_key
    ) THEN
      RAISE EXCEPTION 'compliance_profile_immutable: conteúdo de perfil aprovado não pode ser alterado; crie nova versão';
    END IF;
    IF NEW.status = 'inativo' AND COALESCE(btrim(NEW.motivo_inativacao),'') = '' THEN
      RAISE EXCEPTION 'compliance_profile_reason_required: motivo de inativação obrigatório';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status <> 'aprovado' AND NEW.status = 'aprovado' THEN
    IF COALESCE(btrim(NEW.motivo_aprovacao),'') = '' THEN
      RAISE EXCEPTION 'compliance_profile_reason_required: motivo de aprovação obrigatório';
    END IF;
    NEW.aprovado_por := COALESCE(NEW.aprovado_por, auth.uid());
    NEW.aprovado_em := COALESCE(NEW.aprovado_em, now());
  END IF;
  RETURN NEW;
END;
$function$

