CREATE OR REPLACE FUNCTION platform_private.issue_saas_plan_version_ticket(_scope text, _target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE = '42501';
  END IF;
  IF _scope NOT IN ('saas_plan_version_create','saas_plan_version_write','saas_plan_version_audit',
                    'saas_plan_version_archive','saas_plan_version_supersede') THEN
    RAISE EXCEPTION 'platform_invalid: escopo de autorização inválido' USING ERRCODE = '22023';
  END IF;
  IF _scope = 'saas_plan_version_supersede' THEN
    -- Alvo é a versão antecessora exata: publicada e com vigência aberta.
    IF NOT EXISTS (SELECT 1 FROM public.saas_plan_versions v
                    WHERE v.id = _target AND v.status = 'PUBLISHED' AND v.effective_to IS NULL) THEN
      RAISE EXCEPTION 'platform_invalid: versão antecessora inexistente ou não vigente' USING ERRCODE = '22023';
    END IF;
  ELSIF NOT EXISTS (SELECT 1 FROM public.saas_plans p WHERE p.id = _target) THEN
    RAISE EXCEPTION 'platform_invalid: plano inexistente' USING ERRCODE = '22023';
  END IF;
  INSERT INTO platform_private.authz_tickets(txid, scope, target)
  VALUES (txid_current(), _scope, _target) ON CONFLICT DO NOTHING;
END; $function$

CREATE OR REPLACE FUNCTION public.update_partner_order_notes(p_order_id uuid, p_commercial_notes text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_pid uuid; v_prev text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  SELECT partner_id, commercial_notes INTO v_pid, v_prev
    FROM public.partner_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;

  UPDATE public.partner_orders
     SET commercial_notes = NULLIF(p_commercial_notes,''), updated_at = now()
   WHERE id = p_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'commercial_notes_updated',
          jsonb_build_object('commercial_notes', v_prev),
          jsonb_build_object('commercial_notes', p_commercial_notes));
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_archive_plan_version(_version_id uuid, _reason text, _idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v public.saas_plan_versions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _idempotency_key IS NULL OR length(btrim(coalesce(_reason,'')))<5 THEN
    RAISE EXCEPTION 'platform_invalid: motivo e chave idempotente obrigatórios' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_version_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: versão inexistente' USING ERRCODE='22023'; END IF;
  IF v.status='ARCHIVED' THEN RETURN v.id; END IF;
  IF v.status<>'PUBLISHED' THEN RAISE EXCEPTION 'platform_conflict: apenas publicada pode ser arquivada' USING ERRCODE='40001'; END IF;
  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_archive',v.plan_id);
  UPDATE public.saas_plan_versions SET status='ARCHIVED',archived_at=now(),archived_by=auth.uid(),archive_reason=btrim(_reason),updated_at=now() WHERE id=v.id;
  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v.plan_id);
  INSERT INTO public.saas_plan_version_audit(plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key)
  VALUES(v.id,'archived',to_jsonb(v),(SELECT to_jsonb(x) FROM public.saas_plan_versions x WHERE x.id=v.id),btrim(_reason),'platform_rpc',auth.uid(),_idempotency_key);
  RETURN v.id;
END;
$function$

