CREATE OR REPLACE FUNCTION public.validate_retorno_tecnico_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    has_overlap BOOLEAN;
    visit_duration INTEGER;
BEGIN
    -- Se tem data e consultor, validar sobreposição (independente do tipo de demanda)
    IF NEW.data_prevista_atendimento IS NOT NULL AND NEW.consultor_atribuido IS NOT NULL THEN

        -- Duração padrão de 120 min se não informado
        visit_duration := COALESCE(NEW.duracao_estimada, 120);

        -- Verificar sobreposições
        -- Consideramos que uma visita ocupa o intervalo [data, data + duracao]
        SELECT EXISTS (
            SELECT 1 FROM portal_solicitacoes
            WHERE consultor_atribuido = NEW.consultor_atribuido
            AND id <> NEW.id -- desconsiderar a própria
            AND data_prevista_atendimento IS NOT NULL
            AND status NOT IN ('concluida', 'cancelada')
            AND (
                -- Caso A: Nova visita começa DURANTE uma existente
                (NEW.data_prevista_atendimento >= data_prevista_atendimento AND NEW.data_prevista_atendimento < (data_prevista_atendimento + (COALESCE(duracao_estimada, 120) || ' minutes')::interval))
                OR
                -- Caso B: Visita existente começa DURANTE a nova
                (data_prevista_atendimento >= NEW.data_prevista_atendimento AND data_prevista_atendimento < (NEW.data_prevista_atendimento + (visit_duration || ' minutes')::interval))
            )
        ) INTO has_overlap;

        IF has_overlap THEN
            RAISE EXCEPTION 'CONFLITO_AGENDA: Já existe uma visita agendada para este consultor neste horário ou intervalo.';
        END IF;
    END IF;

    -- Validações específicas para o tipo 'retorno_tecnico'
    IF NEW.tipo_demanda = 'retorno_tecnico' THEN
        -- Validar data obrigatória e no futuro (tolerância de 1h)
        IF NEW.data_prevista_atendimento IS NULL THEN
            RAISE EXCEPTION 'Data prevista é obrigatória para retornos técnicos.';
        END IF;

        IF NEW.data_prevista_atendimento < now() - interval '1 hour' THEN
            RAISE EXCEPTION 'A data do retorno não pode ser no passado.';
        END IF;

        -- Validar descrição/motivo
        IF NEW.descricao IS NULL OR length(trim(NEW.descricao)) < 5 THEN
            RAISE EXCEPTION 'O motivo do retorno deve ser detalhado na descrição.';
        END IF;

        -- Validar consultor
        IF NEW.consultor_atribuido IS NULL THEN
            RAISE EXCEPTION 'Um consultor deve estar atribuído ao retorno.';
        END IF;

        -- Validar duração
        IF NEW.duracao_estimada IS NULL OR NEW.duracao_estimada <= 0 THEN
             RAISE EXCEPTION 'Duração estimada é obrigatória para retornos técnicos.';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.visitas_campo_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Initial contract: a new row always starts at version 1.
    IF NEW.versao IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'versao_inicial_invalida' USING ERRCODE = 'PT409';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.registro_consultor_id IS DISTINCT FROM OLD.registro_consultor_id THEN
    RAISE EXCEPTION 'campo_imutavel_registro_consultor_id' USING ERRCODE = '42501';
  END IF;
  IF NEW.cliente_id IS DISTINCT FROM OLD.cliente_id THEN
    RAISE EXCEPTION 'campo_imutavel_cliente_id' USING ERRCODE = '42501';
  END IF;
  IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'campo_imutavel_created_by' USING ERRCODE = '42501';
  END IF;
  IF OLD.client_uuid IS NOT NULL AND NEW.client_uuid IS DISTINCT FROM OLD.client_uuid THEN
    RAISE EXCEPTION 'campo_imutavel_client_uuid' USING ERRCODE = '42501';
  END IF;
  -- Strict +1: no NULL, no jump, no repeat, no regression (applies to every writer).
  IF OLD.versao IS NULL OR NEW.versao IS NULL OR NEW.versao <> OLD.versao + 1 THEN
    RAISE EXCEPTION 'versao_deve_incrementar' USING ERRCODE = 'PT409';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_force_checkout_visita(p_registro_id uuid, p_target_user_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_open_id uuid;
  v_new_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF NULLIF(btrim(COALESCE(p_reason,'')), '') IS NULL THEN
    RAISE EXCEPTION 'motivo_obrigatorio' USING ERRCODE='22023';
  END IF;
  IF NOT (
    public.has_role(v_uid, 'administrador'::public.app_role)
    OR public.can_manage_technical_visit(v_uid, p_registro_id)
  ) THEN
    RAISE EXCEPTION 'forbidden_force_checkout' USING ERRCODE='42501';
  END IF;

  SELECT id INTO v_open_id
    FROM public.visitas_checkin c
   WHERE c.registro_consultor_id = p_registro_id
     AND c.consultor_id = p_target_user_id
     AND c.tipo_checkin <> 'checkout'::public.tipo_checkin
     AND NOT EXISTS (
       SELECT 1 FROM public.visitas_checkin c2
       WHERE c2.registro_consultor_id = c.registro_consultor_id
         AND c2.consultor_id = c.consultor_id
         AND c2.tipo_checkin = 'checkout'::public.tipo_checkin
         AND c2.data_hora_checkin > c.data_hora_checkin
     )
   ORDER BY c.data_hora_checkin DESC
   LIMIT 1;

  IF v_open_id IS NULL THEN
    RAISE EXCEPTION 'sem_ciclo_aberto' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.visitas_checkin (
    registro_consultor_id, cliente_id, fazenda_id, talhao_id,
    consultor_id, tipo_checkin, observacoes, client_uuid,
    data_hora_checkin, status
  )
  SELECT c.registro_consultor_id, c.cliente_id, c.fazenda_id, c.talhao_id,
         c.consultor_id, 'checkout'::public.tipo_checkin,
         '[force_checkout by ' || v_uid::text || '] ' || btrim(p_reason),
         'force-' || gen_random_uuid()::text,
         now(), 'realizado'::public.status_checkin
    FROM public.visitas_checkin c WHERE c.id = v_open_id
  RETURNING id INTO v_new_id;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, v_uid, 'force_checkout',
          'Checkout forçado do técnico ' || p_target_user_id::text || ' — motivo: ' || btrim(p_reason));

  RETURN jsonb_build_object('checkout_id', v_new_id, 'forced', true);
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_sefaz_transmit_begin_v1(_service text, _idempotency_key text, _request_fingerprint text, _endpoint_url text, _invoice_id uuid DEFAULT NULL::uuid, _xml_run_id uuid DEFAULT NULL::uuid, _actor uuid DEFAULT NULL::uuid, _event_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ref       text;
  v_prod      boolean;
  v_tpamb     text;
  v_host      text;
  v_run       public.fiscal_xml_runs;
  v_ev        record;
  v_invoice   uuid := _invoice_id;
  v_existing  public.fiscal_sefaz_transmissions;
  v_row       public.fiscal_sefaz_transmissions;
BEGIN
  IF coalesce(btrim(_idempotency_key), '') = '' OR length(_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'FISCAL_TRANSMISSION_IDEMPOTENCY_INVALID';
  END IF;
  IF coalesce(btrim(_request_fingerprint), '') = '' THEN
    RAISE EXCEPTION 'FISCAL_TRANSMISSION_FINGERPRINT_REQUIRED';
  END IF;

  SELECT project_ref, production_emission_allowed INTO v_ref, v_prod
    FROM public.fiscal_environment_marker LIMIT 1;
  IF v_ref IS DISTINCT FROM 'swzpzcwiasxmjutrmvkm' OR coalesce(v_prod, true) THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;

  SELECT coalesce(nfe_environment_code, '') INTO v_tpamb
    FROM public.company_fiscal_settings WHERE is_active LIMIT 1;
  IF v_tpamb IS DISTINCT FROM '2' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;

  v_host := split_part(split_part(_endpoint_url, '://', 2), '/', 1);
  IF _endpoint_url NOT LIKE 'https://hnfe.fazenda.mg.gov.br/%'
     OR v_host <> 'hnfe.fazenda.mg.gov.br' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;

  -- H7G-001: na autorização, o invoice é DERIVADO do XML run. O parâmetro do
  -- chamador nunca é autoridade; divergência é bloqueio duro.
  IF _service = 'NFeAutorizacao4' THEN
    IF _xml_run_id IS NULL THEN RAISE EXCEPTION 'SEFAZ_RUN_REQUIRED'; END IF;
    SELECT * INTO v_run FROM public.fiscal_xml_runs WHERE id = _xml_run_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'SEFAZ_RUN_NOT_FOUND'; END IF;
    IF v_run.state IS DISTINCT FROM 'SIGNED' OR coalesce(v_run.signed_path, '') = '' THEN
      RAISE EXCEPTION 'SEFAZ_DOCUMENT_NOT_SIGNED';
    END IF;
    IF coalesce(v_run.environment_code, '') <> '2' THEN
      RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
    END IF;
    IF coalesce(v_run.access_key, '') !~ '^[0-9]{44}$' THEN
      RAISE EXCEPTION 'SEFAZ_ACCESS_KEY_INVALID';
    END IF;
    IF v_run.fiscal_invoice_id IS NULL THEN RAISE EXCEPTION 'SEFAZ_RUN_INVOICE_MISSING'; END IF;
    IF _invoice_id IS NOT NULL AND _invoice_id IS DISTINCT FROM v_run.fiscal_invoice_id THEN
      RAISE EXCEPTION 'SEFAZ_INVOICE_RUN_MISMATCH';
    END IF;
    v_invoice := v_run.fiscal_invoice_id;
  END IF;

  -- H7G-002: no evento, invoice e chave vêm do evento fiscal canônico.
  IF _service = 'NFeRecepcaoEvento4' THEN
    IF _event_id IS NULL THEN RAISE EXCEPTION 'SEFAZ_EVENT_REQUIRED'; END IF;
    SELECT * INTO v_ev FROM public.v_fiscal_sefaz_event_state WHERE event_id = _event_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'SEFAZ_EVENT_NOT_FOUND'; END IF;
    IF v_ev.state <> 'SIGNED' THEN RAISE EXCEPTION 'SEFAZ_EVENT_NOT_SIGNED'; END IF;
    IF _invoice_id IS NOT NULL AND _invoice_id IS DISTINCT FROM v_ev.fiscal_invoice_id THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_INVOICE_MISMATCH';
    END IF;
    v_invoice := v_ev.fiscal_invoice_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('fiscal_sefaz_tx:' || _idempotency_key, 0));

  SELECT * INTO v_existing FROM public.fiscal_sefaz_transmissions
   WHERE idempotency_key = _idempotency_key;

  IF FOUND THEN
    IF v_existing.request_fingerprint IS DISTINCT FROM _request_fingerprint THEN
      RAISE EXCEPTION 'FISCAL_TRANSMISSION_IDEMPOTENCY_MISMATCH';
    END IF;
    RETURN jsonb_build_object(
      'transmissionId', v_existing.id, 'state', v_existing.state,
      'outcome', v_existing.outcome,
      'service', v_existing.service, 'correlationId', v_existing.correlation_id,
      'invoiceId', v_existing.fiscal_invoice_id, 'eventId', v_existing.fiscal_event_id,
      'cStat', v_existing.c_stat, 'xMotivo', v_existing.x_motivo,
      'chNFe', v_existing.ch_nfe, 'nProt', v_existing.n_prot,
      'idempotentReplay', true);
  END IF;

  -- Documento já autorizado nunca é reenviado (invoice canônico).
  IF v_invoice IS NOT NULL AND _service IN ('NFeAutorizacao4','NFeRetAutorizacao4') THEN
    SELECT * INTO v_existing FROM public.fiscal_sefaz_transmissions
     WHERE fiscal_invoice_id = v_invoice
       AND state = 'SUCCEEDED'
       AND outcome = 'AUTHORIZED'
     ORDER BY created_at DESC LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'transmissionId', v_existing.id, 'state', v_existing.state,
        'outcome', v_existing.outcome,
        'service', v_existing.service, 'correlationId', v_existing.correlation_id,
        'invoiceId', v_existing.fiscal_invoice_id,
        'cStat', v_existing.c_stat, 'xMotivo', v_existing.x_motivo,
        'chNFe', v_existing.ch_nfe, 'nProt', v_existing.n_prot,
        'alreadyAuthorized', true, 'idempotentReplay', true);
    END IF;
  END IF;

  INSERT INTO public.fiscal_sefaz_transmissions (
    fiscal_invoice_id, xml_run_id, fiscal_event_id, service, environment_code,
    endpoint_host, endpoint_url, idempotency_key, request_fingerprint,
    state, outcome, attempt, created_by)
  VALUES (v_invoice, _xml_run_id, _event_id, _service, '2',
          v_host, _endpoint_url, _idempotency_key, _request_fingerprint,
          'PENDING', 'PENDING', 1, _actor)
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'transmissionId', v_row.id, 'state', v_row.state, 'outcome', v_row.outcome,
    'service', v_row.service, 'correlationId', v_row.correlation_id,
    'invoiceId', v_row.fiscal_invoice_id, 'eventId', v_row.fiscal_event_id,
    'idempotentReplay', false);
END $function$

CREATE OR REPLACE FUNCTION platform_private.normalize_commercial_reason(_reason text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_reason text := btrim(coalesce(_reason, ''));
BEGIN
  IF char_length(v_reason) < 2 THEN
    RAISE EXCEPTION 'platform_invalid: motivo deve ter pelo menos 2 caracteres' USING ERRCODE = '22023';
  END IF;
  RETURN v_reason;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_tax_rule_publish(p_rule_id uuid, p_justification text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.fiscal_tax_rules%ROWTYPE; ov public.fiscal_rule_sod_overrides%ROWTYPE;
BEGIN
  IF NOT public.fn_regulatory_can_approve('FISCAL') THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao para publicar regra tributaria.';
  END IF;
  SELECT * INTO r FROM public.fiscal_tax_rules WHERE id = p_rule_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_TAX_RULE_NOT_FOUND: %', p_rule_id; END IF;
  IF r.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_TAX_RULE_NOT_DRAFT: apenas rascunho pode ser publicado (status=%)', r.status;
  END IF;
  IF r.source_id IS NULL OR nullif(btrim(coalesce(r.legal_basis,'')),'') IS NULL THEN
    RAISE EXCEPTION 'FISCAL_TAX_RULE_SOURCE_REQUIRED: fonte oficial e base legal obrigatorias.';
  END IF;

  IF r.prepared_by IS NOT NULL AND r.prepared_by = auth.uid() THEN
    SELECT * INTO ov FROM public.fiscal_rule_sod_overrides
     WHERE scope = 'TAX_RULE' AND target_id = r.id AND consumed_at IS NULL
     ORDER BY granted_at DESC LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'FISCAL_SEGREGATION_OF_DUTIES: quem preparou a regra nao pode publica-la. Solicite aprovacao de outro responsavel ou override auditado de administrador.';
    END IF;
    UPDATE public.fiscal_rule_sod_overrides SET consumed_at = now(), consumed_by = auth.uid() WHERE id = ov.id;
  END IF;

  UPDATE public.fiscal_tax_rules
     SET status = 'PUBLISHED', published_by = auth.uid(), published_at = now(),
         justification = coalesce(nullif(btrim(coalesce(p_justification,'')),''), justification),
         updated_by = auth.uid(), updated_at = now()
   WHERE id = p_rule_id;

  UPDATE public.fiscal_tax_rules
     SET status = 'SUPERSEDED', superseded_by = p_rule_id, updated_at = now()
   WHERE rule_key = r.rule_key AND id <> p_rule_id AND status = 'PUBLISHED';

  RETURN jsonb_build_object('ruleId', p_rule_id, 'ruleKey', r.rule_key, 'version', r.version, 'status','PUBLISHED');
END $function$

CREATE OR REPLACE FUNCTION platform_private.validate_commercial_plan_payload(_plan_id uuid, _limits jsonb, _features jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  _entry record;
  _selected_keys text[];
  _legacy_catalog_cutoff constant timestamptz := '2026-10-06 02:42:42+00'::timestamptz;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.saas_plans p WHERE p.id = _plan_id AND p.active IS TRUE) THEN
    RAISE EXCEPTION 'saas_plan_unavailable' USING ERRCODE = '22023';
  END IF;
  IF _limits IS NULL OR jsonb_typeof(_limits) <> 'object' THEN
    RAISE EXCEPTION 'saas_limits_invalid' USING ERRCODE = '22023';
  END IF;
  IF _features IS NULL OR jsonb_typeof(_features) <> 'array' THEN
    RAISE EXCEPTION 'saas_features_invalid' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_features) item
    WHERE jsonb_typeof(item) <> 'string' OR nullif(btrim(item #>> '{}'), '') IS NULL
  ) THEN
    RAISE EXCEPTION 'saas_feature_key_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(feature_key ORDER BY feature_key), ARRAY[]::text[])
    INTO _selected_keys
  FROM (SELECT DISTINCT jsonb_array_elements_text(_features) AS feature_key) selected;

  IF cardinality(_selected_keys) <> jsonb_array_length(_features) THEN
    RAISE EXCEPTION 'saas_feature_duplicate' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(_selected_keys) feature_key
    LEFT JOIN public.saas_features f ON f.key = feature_key
    LEFT JOIN public.saas_modules m ON m.id = f.module_id
    WHERE f.id IS NULL
       OR f.active IS NOT TRUE
       OR m.id IS NULL
       OR m.active IS NOT TRUE
       OR (f.commercializable IS NOT TRUE AND f.created_at >= _legacy_catalog_cutoff)
  ) THEN
    RAISE EXCEPTION 'saas_feature_unavailable' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.saas_feature_dependencies d
    JOIN public.saas_features f ON f.id = d.feature_id
    JOIN public.saas_features required_f ON required_f.id = d.depends_on_feature_id
    WHERE f.key = ANY(_selected_keys)
      AND NOT (required_f.key = ANY(_selected_keys))
  ) THEN
    RAISE EXCEPTION 'saas_feature_dependency_missing' USING ERRCODE = '22023';
  END IF;

  FOR _entry IN SELECT key, value FROM jsonb_each(_limits)
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM public.saas_limit_definitions ld
      JOIN public.saas_feature_limit_definitions fld ON fld.limit_definition_id = ld.id
      JOIN public.saas_features f ON f.id = fld.feature_id
      WHERE ld.key = _entry.key
        AND ld.active IS TRUE
        AND f.key = ANY(_selected_keys)
    ) THEN
      RAISE EXCEPTION 'saas_limit_unknown' USING ERRCODE = '22023';
    END IF;

    IF jsonb_typeof(_entry.value) <> 'object'
       OR NOT (_entry.value ? 'state')
       OR (_entry.value - 'state' - 'value') <> '{}'::jsonb
       OR (_entry.value->>'state') NOT IN ('not_included', 'limited', 'unlimited') THEN
      RAISE EXCEPTION 'saas_limit_state_invalid' USING ERRCODE = '22023';
    END IF;

    IF (_entry.value->>'state') = 'limited' THEN
      IF NOT (_entry.value ? 'value')
         OR jsonb_typeof(_entry.value->'value') <> 'number'
         OR ((_entry.value->>'value')::numeric < 0) THEN
        RAISE EXCEPTION 'saas_limit_value_invalid' USING ERRCODE = '22023';
      END IF;
      IF EXISTS (
        SELECT 1 FROM public.saas_limit_definitions ld
        WHERE ld.key = _entry.key
          AND ld.value_type = 'integer'
          AND trunc((_entry.value->>'value')::numeric) <> ((_entry.value->>'value')::numeric)
      ) THEN
        RAISE EXCEPTION 'saas_limit_value_type_invalid' USING ERRCODE = '22023';
      END IF;
    ELSIF _entry.value ? 'value' THEN
      RAISE EXCEPTION 'saas_limit_value_unexpected' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM public.saas_feature_limit_definitions fld
    JOIN public.saas_limit_definitions ld ON ld.id = fld.limit_definition_id
    JOIN public.saas_features f ON f.id = fld.feature_id
    WHERE fld.required IS TRUE
      AND ld.active IS TRUE
      AND f.key = ANY(_selected_keys)
      AND (NOT (_limits ? ld.key) OR _limits->ld.key->>'state' = 'not_included')
  ) THEN
    RAISE EXCEPTION 'saas_required_limit_missing' USING ERRCODE = '22023';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_service_profile_ibs_cbs_save(p_profile_id uuid, payload jsonb, expected_revision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_id uuid; v_stamp timestamptz; v_new text; v_count integer;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'FISCAL_UNAUTHENTICATED' USING ERRCODE='42501'; END IF;
 IF NOT (platform_private.platform_actor_access_ready(v_uid) AND public.is_platform_superadmin(v_uid)) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE' USING ERRCODE='55000'; END IF;
 IF NOT (platform_private.platform_actor_access_ready(v_uid) AND public.is_platform_superadmin(v_uid)) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM public._fiscal_rtc_assert_payload(payload,'item');
 SELECT count(*) INTO v_count FROM public.service_fiscal_profiles WHERE id=p_profile_id AND is_active IS TRUE;
 IF v_count=0 THEN RAISE EXCEPTION 'FISCAL_ITEM_NOT_FOUND' USING ERRCODE='PT404'; END IF;
 IF v_count<>1 THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 SELECT id,updated_at INTO v_id,v_stamp FROM public.service_fiscal_profiles WHERE id=p_profile_id AND is_active IS TRUE FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_ITEM_NOT_FOUND' USING ERRCODE='PT404'; END IF;
 IF expected_revision IS NULL OR expected_revision IS DISTINCT FROM v_stamp::text THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 UPDATE public.service_fiscal_profiles SET ibs_cbs_configuration=payload,updated_at=greatest(clock_timestamp(),v_stamp+interval '1 microsecond'),updated_by=v_uid
 WHERE id=v_id AND is_active IS TRUE AND updated_at=v_stamp RETURNING updated_at::text INTO v_new;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 RETURN jsonb_build_object('configuration',payload,'revision',v_new);
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_gerar_alertas_operacionais()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_processados int := 0;
  v_total_resolvidos int := 0;
  v_chaves text[] := ARRAY[]::text[];
  v_now timestamptz := now();
  rec record;
  v_dias int;
  v_meta jsonb;
  v_alerta_id uuid;
BEGIN
  IF NOT (
    public.has_role(auth.uid(),'administrador') OR
    public.has_role(auth.uid(),'gestor') OR
    public.has_role(auth.uid(),'administrativo') OR
    COALESCE(auth.role(),'') = 'service_role'
  ) THEN
    RAISE EXCEPTION 'Sem permissão para executar geração de alertas';
  END IF;

  -- VISITAS
  IF coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='visita_sem_checkin'),true) THEN
    v_dias := coalesce((SELECT (parametros->>'dias')::int FROM public.alertas_regras WHERE codigo='visita_sem_checkin'),2);
    FOR rec IN SELECT * FROM public.vw_fluxo_visita_tecnica
       WHERE origem_fluxo IN ('visita_com_solicitacao','visita_avulsa')
         AND coalesce(possui_checkin,false)=false
         AND coalesce(status_visita,'') NOT IN ('finalizado','aprovado','convertido_os')
         AND coalesce(dias_em_aberto,0) >= v_dias LOOP
      v_meta := jsonb_build_object('origem_fluxo',rec.origem_fluxo,'status_visita',rec.status_visita,'dias_em_aberto',rec.dias_em_aberto,'bloqueios',rec.bloqueios,'verificado_em',v_now);
      v_alerta_id := public.fn_upsert_alerta_operacional('visita_sem_checkin','visita','Visita sem check-in',
        format('Visita %s do cliente %s sem check-in há %s dias.',coalesce(rec.codigo_visita,rec.numero_solicitacao,'(sem código)'),coalesce(rec.cliente_nome,'(sem cliente)'),coalesce(rec.dias_em_aberto::text,'?')),
        'media','vw_fluxo_visita_tecnica',coalesce(rec.registro_consultor_id,rec.solicitacao_id),
        rec.cliente_id,rec.fazenda_id,rec.talhao_id,rec.consultor_id,NULL,rec.registro_consultor_id,rec.solicitacao_id,NULL,NULL,
        coalesce(rec.proxima_acao,'Realizar check-in da visita'),v_meta);
      v_chaves := array_append(v_chaves, concat_ws('|','visita_sem_checkin','visita','vw_fluxo_visita_tecnica',coalesce(coalesce(rec.registro_consultor_id,rec.solicitacao_id)::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),coalesce(rec.consultor_id::text,''),''));
      v_total_processados := v_total_processados+1;
    END LOOP;
  END IF;

  IF coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='visita_finalizada_sem_recomendacao'),true) THEN
    FOR rec IN SELECT * FROM public.vw_fluxo_visita_tecnica
       WHERE status_visita IN ('finalizado','aprovado') AND coalesce(possui_recomendacao,false)=false LOOP
      v_meta := jsonb_build_object('status_visita',rec.status_visita,'bloqueios',rec.bloqueios,'verificado_em',v_now);
      v_alerta_id := public.fn_upsert_alerta_operacional('visita_finalizada_sem_recomendacao','visita','Visita finalizada sem recomendação',
        format('Visita %s do cliente %s finalizada sem recomendação registrada.',coalesce(rec.codigo_visita,'(sem código)'),coalesce(rec.cliente_nome,'(sem cliente)')),
        'alta','vw_fluxo_visita_tecnica',rec.registro_consultor_id,
        rec.cliente_id,rec.fazenda_id,rec.talhao_id,rec.consultor_id,NULL,rec.registro_consultor_id,rec.solicitacao_id,NULL,NULL,
        'Registrar recomendação técnica',v_meta);
      v_chaves := array_append(v_chaves, concat_ws('|','visita_finalizada_sem_recomendacao','visita','vw_fluxo_visita_tecnica',coalesce(rec.registro_consultor_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),coalesce(rec.consultor_id::text,''),''));
      v_total_processados := v_total_processados+1;
    END LOOP;
  END IF;

  IF coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='recomendacao_liberada_sem_decisao'),true) THEN
    v_dias := coalesce((SELECT (parametros->>'dias')::int FROM public.alertas_regras WHERE codigo='recomendacao_liberada_sem_decisao'),3);
    FOR rec IN SELECT * FROM public.vw_fluxo_visita_tecnica
       WHERE coalesce(possui_recomendacao,false)=true AND data_liberacao_recomendacao IS NOT NULL
         AND coalesce(possui_os,false)=false AND data_conversao_os IS NULL
         AND data_liberacao_recomendacao <= now() - make_interval(days => v_dias) LOOP
      v_meta := jsonb_build_object('data_liberacao',rec.data_liberacao_recomendacao,'verificado_em',v_now);
      v_alerta_id := public.fn_upsert_alerta_operacional('recomendacao_liberada_sem_decisao','recomendacao','Recomendação liberada sem decisão',
        format('Recomendação liberada para cliente %s aguarda decisão há mais de %s dias.',coalesce(rec.cliente_nome,'(sem cliente)'),v_dias),
        'media','vw_fluxo_visita_tecnica',rec.registro_consultor_id,
        rec.cliente_id,rec.fazenda_id,rec.talhao_id,rec.consultor_id,NULL,rec.registro_consultor_id,rec.solicitacao_id,NULL,NULL,
        'Aprovar ou recusar a recomendação',v_meta);
      v_chaves := array_append(v_chaves, concat_ws('|','recomendacao_liberada_sem_decisao','recomendacao','vw_fluxo_visita_tecnica',coalesce(rec.registro_consultor_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),coalesce(rec.consultor_id::text,''),''));
      v_total_processados := v_total_processados+1;
    END LOOP;
  END IF;

  IF coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='recomendacao_convertida_sem_os'),true) THEN
    FOR rec IN SELECT * FROM public.vw_fluxo_visita_tecnica
       WHERE status_visita='convertido_os' AND (coalesce(possui_os,false)=false OR os_id IS NULL) LOOP
      v_meta := jsonb_build_object('bloqueios',rec.bloqueios,'verificado_em',v_now);
      v_alerta_id := public.fn_upsert_alerta_operacional('recomendacao_convertida_sem_os','recomendacao','Recomendação convertida sem OS vinculada',
        format('Visita %s do cliente %s marcada como convertida, mas sem OS vinculada.',coalesce(rec.codigo_visita,'(sem código)'),coalesce(rec.cliente_nome,'(sem cliente)')),
        'critica','vw_fluxo_visita_tecnica',rec.registro_consultor_id,
        rec.cliente_id,rec.fazenda_id,rec.talhao_id,rec.consultor_id,NULL,rec.registro_consultor_id,rec.solicitacao_id,NULL,NULL,
        'Vincular OS à recomendação',v_meta);
      v_chaves := array_append(v_chaves, concat_ws('|','recomendacao_convertida_sem_os','recomendacao','vw_fluxo_visita_tecnica',coalesce(rec.registro_consultor_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),coalesce(rec.consultor_id::text,''),''));
      v_total_processados := v_total_processados+1;
    END LOOP;
  END IF;

  IF coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='visita_com_bloqueio'),true) THEN
    FOR rec IN SELECT * FROM public.vw_fluxo_visita_tecnica
       WHERE bloqueios IS NOT NULL AND array_length(bloqueios,1)>0 LOOP
      v_meta := jsonb_build_object('bloqueios',rec.bloqueios,'status_visita',rec.status_visita,'verificado_em',v_now);
      v_alerta_id := public.fn_upsert_alerta_operacional('visita_com_bloqueio','visita','Visita com bloqueio',
        format('Visita %s do cliente %s possui bloqueios: %s.',coalesce(rec.codigo_visita,'(sem código)'),coalesce(rec.cliente_nome,'(sem cliente)'),array_to_string(rec.bloqueios,', ')),
        'media','vw_fluxo_visita_tecnica',rec.registro_consultor_id,
        rec.cliente_id,rec.fazenda_id,rec.talhao_id,rec.consultor_id,NULL,rec.registro_consultor_id,rec.solicitacao_id,NULL,NULL,
        coalesce(rec.proxima_acao,'Revisar pendências da visita'),v_meta);
      v_chaves := array_append(v_chaves, concat_ws('|','visita_com_bloqueio','visita','vw_fluxo_visita_tecnica',coalesce(rec.registro_consultor_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),coalesce(rec.consultor_id::text,''),''));
      v_total_processados := v_total_processados+1;
    END LOOP;
  END IF;

  -- ESTEIRA LABORATÓRIO
  FOR rec IN SELECT * FROM public.vw_esteira_laboratorio LOOP
    v_meta := jsonb_build_object('status_esteira_oficial',rec.status_esteira_oficial,'bloqueios',rec.bloqueios,'pendencias_informativas',rec.pendencias_informativas,'atrasado',rec.atrasado,'verificado_em',v_now);

    IF rec.bloqueios IS NOT NULL AND 'os_duplicada'=ANY(rec.bloqueios)
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='os_duplicada'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('os_duplicada','laboratorio','OS duplicada',
        format('OS %s possui indicador de duplicidade.',coalesce(rec.numero_os,'(sem número)')),
        'critica','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Revisar OS duplicada (não corrigir automaticamente)',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','os_duplicada','laboratorio','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF rec.bloqueios IS NOT NULL AND 'sem_programacao'=ANY(rec.bloqueios)
       AND coalesce(rec.status_esteira_oficial,'') NOT IN ('finalizada','cancelada')
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='os_sem_programacao'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('os_sem_programacao','laboratorio','OS sem programação',
        format('OS %s sem programação de produção.',coalesce(rec.numero_os,'(sem número)')),
        'alta','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,coalesce(rec.proxima_acao,'Programar produção'),v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','os_sem_programacao','laboratorio','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF rec.bloqueios IS NOT NULL AND 'sem_lote'=ANY(rec.bloqueios)
       AND coalesce(rec.status_esteira_oficial,'') IN ('em_producao','aguardando_cq','cq_aprovado','envase','pronto_entrega','entrega_pendente')
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='os_sem_lote'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('os_sem_lote','laboratorio','OS sem lote',
        format('OS %s sem lote vinculado.',coalesce(rec.numero_os,'(sem número)')),
        'alta','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Gerar lote para a OS',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','os_sem_lote','laboratorio','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF (rec.bloqueios IS NOT NULL AND 'cq_pendente'=ANY(rec.bloqueios))
       AND coalesce(rec.status_esteira_oficial,'')='aguardando_cq'
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='cq_pendente'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('cq_pendente','cq','CQ pendente',
        format('OS %s aguardando controle de qualidade.',coalesce(rec.numero_os,'(sem número)')),
        'alta','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Registrar CQ do lote',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','cq_pendente','cq','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF ((rec.bloqueios IS NOT NULL AND 'cq_reprovado'=ANY(rec.bloqueios))
         OR coalesce(rec.status_esteira_oficial,'')='cq_reprovado')
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='cq_reprovado'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('cq_reprovado','cq','CQ reprovado',
        format('OS %s com CQ reprovado.',coalesce(rec.numero_os,'(sem número)')),
        'critica','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Avaliar reprovação de CQ e reprogramar',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','cq_reprovado','cq','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF (rec.bloqueios IS NOT NULL AND 'sem_envase'=ANY(rec.bloqueios))
       AND coalesce(rec.status_esteira_oficial,'') IN ('cq_aprovado','envase','pronto_entrega','entrega_pendente')
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='os_sem_envase'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('os_sem_envase','laboratorio','OS sem envase',
        format('OS %s aguardando envase.',coalesce(rec.numero_os,'(sem número)')),
        'alta','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Registrar envase do lote',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','os_sem_envase','laboratorio','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF (rec.bloqueios IS NOT NULL AND 'sem_estoque'=ANY(rec.bloqueios))
       AND coalesce(rec.status_esteira_oficial,'') IN ('envase','pronto_entrega','entrega_pendente')
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='os_sem_estoque'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('os_sem_estoque','estoque','OS sem estoque',
        format('OS %s sem reserva ou movimentação de estoque.',coalesce(rec.numero_os,'(sem número)')),
        'alta','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Reservar/registrar estoque para a OS',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','os_sem_estoque','estoque','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF (coalesce(rec.status_esteira_oficial,'')='entrega_pendente'
        OR (rec.bloqueios IS NOT NULL AND 'sem_entrega_confirmada'=ANY(rec.bloqueios)))
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='entrega_pendente'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('entrega_pendente','entrega','Entrega pendente',
        format('OS %s aguardando confirmação de entrega.',coalesce(rec.numero_os,'(sem número)')),
        'alta','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Confirmar entrega',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','entrega_pendente','entrega','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF coalesce(rec.pode_finalizar,false)=true
       AND coalesce(rec.status_esteira_oficial,'')<>'finalizada'
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='os_apta_finalizacao'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('os_apta_finalizacao','laboratorio','OS apta para finalização',
        format('OS %s atende a todos os critérios para finalização.',coalesce(rec.numero_os,'(sem número)')),
        'media','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Finalizar OS no cockpit',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','os_apta_finalizacao','laboratorio','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF rec.pendencias_informativas IS NOT NULL
       AND ('aplicacao_nao_registrada'=ANY(rec.pendencias_informativas)
            OR 'cliente_nao_informou_aplicacao'=ANY(rec.pendencias_informativas))
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='aplicacao_nao_registrada'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('aplicacao_nao_registrada','entrega','Aplicação não registrada',
        format('OS %s entregue, mas aplicação em campo ainda não foi registrada.',coalesce(rec.numero_os,'(sem número)')),
        'informativa','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,'Solicitar registro de aplicação',v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','aplicacao_nao_registrada','entrega','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;

    IF coalesce(rec.atrasado,false)=true
       AND coalesce((SELECT ativo FROM public.alertas_regras WHERE codigo='os_atrasada'),true) THEN
      v_alerta_id := public.fn_upsert_alerta_operacional('os_atrasada','laboratorio','OS atrasada',
        format('OS %s sinalizada como atrasada na esteira.',coalesce(rec.numero_os,'(sem número)')),
        'alta','vw_esteira_laboratorio',rec.os_id,rec.cliente_id,rec.fazenda_id,rec.talhao_id,NULL,
        rec.os_id,NULL,NULL,rec.lote_id,rec.entrega_id,coalesce(rec.proxima_acao,'Verificar próxima etapa da esteira'),v_meta);
      v_chaves := array_append(v_chaves,concat_ws('|','os_atrasada','laboratorio','vw_esteira_laboratorio',coalesce(rec.os_id::text,''),coalesce(rec.cliente_id::text,''),coalesce(rec.fazenda_id::text,''),'',coalesce(rec.os_id::text,'')));
      v_total_processados := v_total_processados+1;
    END IF;
  END LOOP;

  -- RESOLUÇÃO AUTOMÁTICA: aceita auth.uid() NULL (service role/cron) com metadata identificando origem sistema.
  WITH a_resolver AS (
    SELECT id FROM public.alertas_operacionais
     WHERE status IN ('aberto','lido','reaberto')
       AND chave_dedupe IS NOT NULL
       AND NOT (chave_dedupe = ANY(v_chaves))
       AND tipo IN ('visita_sem_checkin','visita_finalizada_sem_recomendacao','recomendacao_liberada_sem_decisao','recomendacao_convertida_sem_os','visita_com_bloqueio','os_duplicada','os_sem_programacao','os_sem_lote','cq_pendente','cq_reprovado','os_sem_envase','os_sem_estoque','entrega_pendente','os_apta_finalizacao','aplicacao_nao_registrada','os_atrasada')
  ), upd AS (
    UPDATE public.alertas_operacionais a
       SET status='resolvido', resolvido_em=v_now, updated_at=v_now
      FROM a_resolver r WHERE a.id=r.id
    RETURNING a.id
  )
  INSERT INTO public.alertas_acoes(alerta_id, user_id, acao, observacao, metadata)
  SELECT id, auth.uid(), 'resolvido_automaticamente',
         'Condição do alerta não foi mais identificada na última verificação.',
         jsonb_build_object(
           'origem','sistema',
           'executado_por', COALESCE(auth.role(),'service_role'),
           'verificado_em', v_now
         ) FROM upd;
  GET DIAGNOSTICS v_total_resolvidos = ROW_COUNT;

  RETURN jsonb_build_object(
    'total_processados', v_total_processados,
    'total_resolvidos_automaticamente', v_total_resolvidos,
    'executado_em', v_now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_gerar_etiqueta_produto(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_lote_id uuid := NULLIF(p_payload->>'lote_id','')::uuid;
  v_produto_id uuid := NULLIF(p_payload->>'produto_id','')::uuid;
  v_envase_id uuid := NULLIF(p_payload->>'envase_id','')::uuid;
  v_envase_item_id uuid := NULLIF(p_payload->>'envase_item_id','')::uuid;
  v_estoque_item_id uuid := NULLIF(p_payload->>'estoque_item_id','')::uuid;
  v_embalagem_id uuid := NULLIF(p_payload->>'embalagem_id','')::uuid;
  v_entrega_id uuid := NULLIF(p_payload->>'entrega_id','')::uuid;
  v_entrega_item_id uuid := NULLIF(p_payload->>'entrega_item_id','')::uuid;
  v_cliente_id uuid := NULLIF(p_payload->>'cliente_id','')::uuid;
  v_fazenda_id uuid := NULLIF(p_payload->>'fazenda_id','')::uuid;
  v_tipo text := COALESCE(NULLIF(p_payload->>'tipo_etiqueta',''), 'principal');
  v_volume numeric := NULLIF(p_payload->>'volume','')::numeric;
  v_unidade text := NULLIF(p_payload->>'unidade','');
  v_qtd_emb integer := NULLIF(p_payload->>'quantidade_embalagens','')::integer;
  v_conservacao text := NULLIF(p_payload->>'conservacao','');
  v_uso text := NULLIF(p_payload->>'uso_recomendado','');
  v_obs text := NULLIF(p_payload->>'observacoes','');
  v_substitui uuid := NULLIF(p_payload->>'substitui_etiqueta_id','')::uuid;
  v_template_codigo text := NULLIF(p_payload->>'template_codigo','');
  v_comercial boolean;
  v_produto_nome text;
  v_produto_tipo text;
  v_lote_codigo text;
  v_lote_status text;
  v_cq_liberado boolean;
  v_cepas text[];
  v_fabricado_em date;
  v_validade_em date;
  v_validade_origem text;
  v_perfil public.produto_conformidade_perfis;
  v_tpl public.etiqueta_templates;
  v_seq bigint;
  v_codigo text;
  v_trace_token uuid := gen_random_uuid();
  v_trace_hash text;
  v_id uuid := gen_random_uuid();
  v_qr_payload text;
  v_snapshot jsonb;
  v_template text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  IF NOT (
    public.has_role(v_uid,'administrador'::app_role)
    OR public.has_role(v_uid,'gestor'::app_role)
    OR public.has_role(v_uid,'producao'::app_role)
    OR public.has_role(v_uid,'operador_onfarm'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para gerar etiqueta';
  END IF;

  v_comercial := v_tipo NOT IN ('interna','amostra');

  -- embalagem como origem unitária canônica
  IF v_embalagem_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('etiqueta_embalagem:' || v_embalagem_id::text, 0));
    SELECT eb.lote_id, COALESCE(v_produto_id, eb.produto_id), COALESCE(v_envase_id, eb.envase_id),
           COALESCE(v_volume, eb.volume), COALESCE(v_unidade, eb.unidade), eb.validade_em
      INTO v_lote_id, v_produto_id, v_envase_id, v_volume, v_unidade, v_validade_em
    FROM public.estoque_embalagens eb WHERE eb.id = v_embalagem_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'label_package_not_found: embalagem inexistente'; END IF;
    IF v_validade_em IS NOT NULL THEN v_validade_origem := 'embalagem'; END IF;
    v_qtd_emb := COALESCE(v_qtd_emb, 1);
  END IF;

  IF v_envase_id IS NOT NULL AND v_lote_id IS NULL THEN
    SELECT e.lote_id, COALESCE(v_volume, e.volume_por_unidade), COALESCE(v_qtd_emb, e.quantidade)
      INTO v_lote_id, v_volume, v_qtd_emb
    FROM public.envase e WHERE e.id = v_envase_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Envase não encontrado'; END IF;
  ELSIF v_envase_id IS NOT NULL THEN
    SELECT COALESCE(v_volume, e.volume_por_unidade), COALESCE(v_qtd_emb, e.quantidade)
      INTO v_volume, v_qtd_emb
    FROM public.envase e WHERE e.id = v_envase_id;
  END IF;

  IF v_lote_id IS NULL THEN
    RAISE EXCEPTION 'Lote obrigatório';
  END IF;

  SELECT l.codigo_lote, COALESCE(v_produto_id, l.produto_id), l.data_producao, l.status::text
    INTO v_lote_codigo, v_produto_id, v_fabricado_em, v_lote_status
  FROM public.lotes l WHERE l.id = v_lote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Lote não encontrado'; END IF;

  v_cq_liberado := (v_lote_status = 'aprovado');

  IF NOT v_cq_liberado AND v_comercial THEN
    RAISE EXCEPTION 'label_cq_not_approved: etiqueta % bloqueada, lote % com status de qualidade "%"',
      v_tipo, v_lote_codigo, v_lote_status;
  END IF;

  IF v_produto_id IS NOT NULL THEN
    SELECT p.nome, p.tipo::text INTO v_produto_nome, v_produto_tipo
    FROM public.produtos p WHERE p.id = v_produto_id;
  END IF;
  IF v_produto_nome IS NULL THEN v_produto_nome := 'Bioinsumo AR Bio'; END IF;

  -- Perfil de conformidade vigente
  v_perfil := public.fn_conformidade_perfil_vigente(v_produto_id, v_produto_tipo);

  IF v_comercial AND v_perfil.id IS NULL THEN
    RAISE EXCEPTION 'label_compliance_profile_missing: não há perfil de conformidade aprovado vigente para o produto %', v_produto_nome;
  END IF;

  IF v_comercial AND v_perfil.campos_obrigatorios IS NOT NULL THEN
    IF 'responsavel_tecnico' = ANY(v_perfil.campos_obrigatorios)
       AND COALESCE(btrim(v_perfil.responsavel_tecnico_registro),'') = '' THEN
      RAISE EXCEPTION 'label_compliance_field_missing: responsavel_tecnico não validado no perfil de conformidade';
    END IF;
    IF 'registro_mapa' = ANY(v_perfil.campos_obrigatorios)
       AND COALESCE(btrim(v_perfil.registro_mapa),'') = '' THEN
      RAISE EXCEPTION 'label_compliance_field_missing: registro_mapa não validado no perfil de conformidade';
    END IF;
  END IF;

  SELECT array_remove(ARRAY[m.nome], NULL)
    INTO v_cepas
  FROM public.lotes l
  LEFT JOIN public.microrganismos m ON m.id = l.microrganismo_id
  WHERE l.id = v_lote_id;

  -- Resolução de validade: embalagem > estoque > política do perfil. Sem fallback estimado.
  IF v_validade_em IS NULL THEN
    SELECT MIN(ep.validade) INTO v_validade_em
    FROM public.estoque_produto ep WHERE ep.lote_id = v_lote_id;
    IF v_validade_em IS NOT NULL THEN v_validade_origem := 'estoque'; END IF;
  END IF;

  IF v_validade_em IS NULL AND v_perfil.validade_meses IS NOT NULL AND v_fabricado_em IS NOT NULL THEN
    v_validade_em := (v_fabricado_em + make_interval(months => v_perfil.validade_meses))::date;
    v_validade_origem := 'perfil_conformidade';
  END IF;

  IF v_validade_em IS NULL THEN
    IF v_comercial THEN
      RAISE EXCEPTION 'label_expiry_not_validated: validade não validada para o lote % — defina validade em estoque/embalagem ou política de validade no perfil de conformidade aprovado',
        v_lote_codigo;
    END IF;
    v_validade_origem := 'nao_validada';
  END IF;

  IF v_unidade IS NULL AND v_volume IS NOT NULL THEN
    v_unidade := 'ml';
  END IF;

  -- Template configurável
  IF v_template_codigo IS NULL THEN
    v_template_codigo := CASE WHEN v_tipo = 'reduzida' THEN 'etiqueta-produto-reduzida'
                              ELSE 'etiqueta-produto-principal' END;
  END IF;
  SELECT * INTO v_tpl FROM public.etiqueta_templates
   WHERE codigo = v_template_codigo AND ativo
   ORDER BY versao DESC LIMIT 1;
  IF v_tpl.id IS NULL THEN
    RAISE EXCEPTION 'label_template_not_found: template % inexistente ou inativo', v_template_codigo;
  END IF;
  v_template := v_tpl.codigo || '@v' || v_tpl.versao;

  SELECT nextval('public.produto_etiqueta_seq') INTO v_seq;
  v_codigo := 'AR-LB-' || lpad(v_seq::text, 6, '0');

  v_trace_hash := encode(extensions.digest(v_trace_token::text || '|' || v_codigo, 'sha256'), 'hex');
  v_qr_payload := '/rastrear-produto/' || v_trace_token::text;

  v_conservacao := COALESCE(v_conservacao, v_perfil.conservacao_texto);
  v_uso := COALESCE(v_uso, v_perfil.uso_texto);

  IF v_comercial AND (COALESCE(btrim(v_conservacao),'') = '' OR COALESCE(btrim(v_uso),'') = '') THEN
    RAISE EXCEPTION 'label_compliance_field_missing: textos de conservação/uso não validados no perfil de conformidade';
  END IF;

  v_snapshot := jsonb_build_object(
    'template_versao', v_template,
    'template', jsonb_build_object(
      'codigo', v_tpl.codigo, 'versao', v_tpl.versao, 'midia', v_tpl.midia,
      'largura_mm', v_tpl.largura_mm, 'altura_mm', v_tpl.altura_mm,
      'orientacao', v_tpl.orientacao, 'densidade_dpi', v_tpl.densidade_dpi,
      'colunas', v_tpl.colunas, 'linhas', v_tpl.linhas,
      'margens_mm', jsonb_build_object('topo', v_tpl.margem_topo_mm, 'direita', v_tpl.margem_direita_mm,
                                       'base', v_tpl.margem_base_mm, 'esquerda', v_tpl.margem_esquerda_mm)
    ),
    'conformidade', CASE WHEN v_perfil.id IS NULL THEN NULL ELSE jsonb_build_object(
      'perfil_id', v_perfil.id, 'perfil_key', v_perfil.perfil_key, 'versao', v_perfil.versao,
      'aprovado_em', v_perfil.aprovado_em,
      'responsavel_informacao', v_perfil.responsavel_informacao,
      'fonte_documento', v_perfil.fonte_documento,
      'responsavel_tecnico_nome', v_perfil.responsavel_tecnico_nome,
      'responsavel_tecnico_registro', v_perfil.responsavel_tecnico_registro,
      'registro_mapa', v_perfil.registro_mapa,
      'identificadores_regulatorios', v_perfil.identificadores_regulatorios,
      'identificadores_fiscais', v_perfil.identificadores_fiscais,
      'advertencias', to_jsonb(v_perfil.advertencias),
      'transporte_texto', v_perfil.transporte_texto,
      'politica_validade', v_perfil.politica_validade
    ) END,
    'origem_dados', jsonb_build_object(
      'validade', v_validade_origem,
      'conservacao', CASE WHEN NULLIF(p_payload->>'conservacao','') IS NOT NULL THEN 'payload' ELSE 'perfil_conformidade' END,
      'uso_recomendado', CASE WHEN NULLIF(p_payload->>'uso_recomendado','') IS NOT NULL THEN 'payload' ELSE 'perfil_conformidade' END,
      'produto', 'cadastro_produtos',
      'lote', 'lotes',
      'embalagem', CASE WHEN v_embalagem_id IS NOT NULL THEN 'estoque_embalagens' ELSE NULL END
    ),
    'codigo_etiqueta', v_codigo,
    'tipo_etiqueta', v_tipo,
    'produto_nome', v_produto_nome,
    'lote_codigo', v_lote_codigo,
    'cepas', to_jsonb(COALESCE(v_cepas, ARRAY[]::text[])),
    'volume', v_volume,
    'unidade', v_unidade,
    'quantidade_embalagens', v_qtd_emb,
    'fabricado_em', v_fabricado_em,
    'validade_em', v_validade_em,
    'validade_origem', v_validade_origem,
    'conservacao', v_conservacao,
    'uso_recomendado', v_uso,
    'observacoes', v_obs,
    'cq_liberado', v_cq_liberado,
    'lote_status_na_emissao', v_lote_status,
    'emitida_em', now(),
    'emitida_por', v_uid
  );

  INSERT INTO public.produto_etiquetas (
    id, codigo_etiqueta, tipo_etiqueta, status,
    lote_id, produto_id, envase_id, envase_item_id, estoque_item_id, embalagem_id,
    entrega_id, entrega_item_id, cliente_id, fazenda_id,
    produto_nome, lote_codigo, volume, unidade, quantidade_embalagens, cepas,
    fabricado_em, validade_em, conservacao, uso_recomendado, observacoes,
    trace_token, trace_hash, qr_code_payload, qr_code_generated_at,
    gerada_por, gerada_em,
    snapshot, template_versao, cq_liberado, lote_status_na_emissao, substitui_etiqueta_id
  ) VALUES (
    v_id, v_codigo, v_tipo, 'gerada',
    v_lote_id, v_produto_id, v_envase_id, v_envase_item_id, v_estoque_item_id, v_embalagem_id,
    v_entrega_id, v_entrega_item_id, v_cliente_id, v_fazenda_id,
    v_produto_nome, v_lote_codigo, v_volume, v_unidade, v_qtd_emb, v_cepas,
    v_fabricado_em, v_validade_em, v_conservacao, v_uso, v_obs,
    v_trace_token, v_trace_hash, v_qr_payload, now(),
    v_uid, now(),
    v_snapshot, v_template, v_cq_liberado, v_lote_status, v_substitui
  );

  IF v_substitui IS NOT NULL THEN
    UPDATE public.produto_etiquetas SET substituida_por_id = v_id WHERE id = v_substitui;
  END IF;

  IF v_embalagem_id IS NOT NULL THEN
    UPDATE public.estoque_embalagens SET etiqueta_id = v_id, updated_at = now()
     WHERE id = v_embalagem_id;
  END IF;

  IF v_envase_id IS NOT NULL THEN
    UPDATE public.envase
       SET etiqueta_gerada = true,
           etiqueta_id = v_id,
           etiqueta_gerada_em = now(),
           etiqueta_gerada_por = v_uid
     WHERE id = v_envase_id;
  END IF;

  IF v_entrega_id IS NOT NULL THEN
    INSERT INTO public.entrega_etiquetas (entrega_id, etiqueta_id, created_by)
      VALUES (v_entrega_id, v_id, v_uid)
      ON CONFLICT DO NOTHING;
  END IF;

  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, descricao, user_id, metadata)
    VALUES (v_id, 'etiqueta_gerada', 'Etiqueta gerada', v_uid,
            jsonb_build_object('tipo', v_tipo, 'codigo', v_codigo, 'cq_liberado', v_cq_liberado,
                               'template', v_template, 'validade_origem', v_validade_origem));

  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('produto_etiqueta', v_id, 'LABEL_GENERATED',
            jsonb_build_object('codigo', v_codigo, 'tipo', v_tipo, 'lote_id', v_lote_id,
                               'envase_id', v_envase_id, 'embalagem_id', v_embalagem_id,
                               'cq_liberado', v_cq_liberado, 'template', v_template),
            v_uid, 'Geração de etiqueta de produto');

  RETURN jsonb_build_object(
    'success', true,
    'etiqueta_id', v_id,
    'codigo_etiqueta', v_codigo,
    'trace_token', v_trace_token,
    'trace_url', v_qr_payload,
    'qr_code_payload', v_qr_payload,
    'cq_liberado', v_cq_liberado,
    'validade_origem', v_validade_origem,
    'template_versao', v_template
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_xml_record_v1(p_run_id uuid, p_state text, p_patch jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r public.fiscal_xml_runs%ROWTYPE;
  v_ok boolean := false;
BEGIN
  PERFORM public.fn_fiscal_environment_gate_v1();
  IF p_state IS NULL OR p_state NOT IN ('GENERATED','XSD_VALIDATED','SIGNED','FAILED') THEN
    RAISE EXCEPTION 'FISCAL_XML_STATE_INVALID: estado % nao permitido.', p_state;
  END IF;
  IF p_patch IS NOT NULL AND public.fiscal_json_has_sensitive_key(p_patch) THEN
    RAISE EXCEPTION 'FISCAL_PAYLOAD_SENSITIVE: patch contem chave sensivel.';
  END IF;

  SELECT * INTO r FROM public.fiscal_xml_runs WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_XML_RUN_NOT_FOUND: %', p_run_id; END IF;
  IF r.state IN ('SIGNED','FAILED') THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_TERMINAL: execucao ja finalizada em %.', r.state;
  END IF;

  v_ok := (r.state = p_state) OR (p_state = 'FAILED')
       OR (r.state = 'PREPARED'      AND p_state = 'GENERATED')
       OR (r.state = 'GENERATED'     AND p_state = 'XSD_VALIDATED')
       OR (r.state = 'XSD_VALIDATED' AND p_state = 'SIGNED');
  IF NOT v_ok THEN
    RAISE EXCEPTION 'FISCAL_XML_TRANSITION_INVALID: % -> % nao permitido.', r.state, p_state;
  END IF;

  PERFORM set_config('app.fiscal_xml_engine','on', true);

  UPDATE public.fiscal_xml_runs SET
    state = p_state,
    unsigned_sha256 = coalesce(unsigned_sha256, nullif(p_patch->>'unsignedSha256','')),
    unsigned_bytes  = coalesce(unsigned_bytes,  nullif(p_patch->>'unsignedBytes','')::int),
    unsigned_path   = coalesce(unsigned_path,   nullif(p_patch->>'unsignedPath','')),
    signed_sha256   = coalesce(signed_sha256,   nullif(p_patch->>'signedSha256','')),
    signed_bytes    = coalesce(signed_bytes,    nullif(p_patch->>'signedBytes','')::int),
    signed_path     = coalesce(signed_path,     nullif(p_patch->>'signedPath','')),
    certificate_id  = coalesce(certificate_id,  nullif(p_patch->>'certificateId','')::uuid),
    validation      = CASE WHEN p_patch ? 'validation'
                           THEN validation || (p_patch->'validation') ELSE validation END,
    signature_metadata = CASE WHEN p_patch ? 'signature'
                           THEN signature_metadata || (p_patch->'signature') ELSE signature_metadata END,
    error_code   = CASE WHEN p_state = 'FAILED' THEN nullif(p_patch->>'errorCode','') ELSE error_code END,
    error_detail = CASE WHEN p_state = 'FAILED' THEN left(coalesce(p_patch->>'errorDetail',''), 500) ELSE error_detail END,
    generated_at = CASE WHEN p_state = 'GENERATED'     THEN now() ELSE generated_at END,
    validated_at = CASE WHEN p_state = 'XSD_VALIDATED' THEN now() ELSE validated_at END,
    signed_at    = CASE WHEN p_state = 'SIGNED'        THEN now() ELSE signed_at END,
    failed_at    = CASE WHEN p_state = 'FAILED'        THEN now() ELSE failed_at END
  WHERE id = p_run_id
  RETURNING * INTO r;

  PERFORM set_config('app.fiscal_xml_engine','off', true);

  INSERT INTO public.fiscal_audit_log (table_name, record_id, action, changed_by, new_values)
  VALUES ('fiscal_xml_runs', r.id, 'XML_' || p_state, r.created_by,
          jsonb_build_object('state', r.state, 'unsignedSha256', r.unsigned_sha256,
                             'signedSha256', r.signed_sha256, 'errorCode', r.error_code));

  RETURN jsonb_build_object('runId', r.id, 'state', r.state,
    'unsignedSha256', r.unsigned_sha256, 'signedSha256', r.signed_sha256,
    'validation', r.validation, 'errorCode', r.error_code);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_gerar_formulario_entrega(p_entrega_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
  v_comp public.entrega_comprovantes%ROWTYPE;
  v_num text;
  v_token uuid := gen_random_uuid();
  v_hash text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão inválida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para gerar formulário de entrega';
  END IF;
  SELECT * INTO v_entrega FROM public.entregas WHERE id = p_entrega_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada'; END IF;
  IF v_entrega.status = 'cancelada' THEN RAISE EXCEPTION 'Entrega cancelada'; END IF;

  -- reuse if exists
  SELECT * INTO v_comp FROM public.entrega_comprovantes
    WHERE entrega_id = p_entrega_id AND tipo = 'formulario_entrega'
    ORDER BY gerado_em DESC LIMIT 1;

  IF v_comp.id IS NOT NULL AND v_comp.status NOT IN ('rejeitado','cancelado') THEN
    RETURN jsonb_build_object(
      'success', true, 'reused', true,
      'entrega_id', p_entrega_id,
      'comprovante_id', v_comp.id,
      'numero_formulario', v_comp.numero_formulario,
      'validation_token', v_comp.validation_token,
      'validation_url', v_comp.validation_url
    );
  END IF;

  v_num := 'AR-ENT-' || lpad(nextval('public.entrega_formulario_seq')::text, 6, '0');
  v_hash := encode(extensions.digest(p_entrega_id::text || v_num || v_token::text || now()::text, 'sha256'), 'hex');

  INSERT INTO public.entrega_comprovantes (
    entrega_id, numero_formulario, tipo, status,
    validation_token, validation_hash, qr_code_payload, gerado_por
  ) VALUES (
    p_entrega_id, v_num, 'formulario_entrega', 'gerado',
    v_token, v_hash, v_token::text, v_uid
  ) RETURNING * INTO v_comp;

  UPDATE public.entregas SET
    comprovante_status = 'formulario_gerado',
    comprovante_id = v_comp.id,
    formulario_gerado_em = now(),
    formulario_gerado_por = v_uid,
    validation_token = v_token,
    validation_hash = v_hash,
    updated_at = now()
  WHERE id = p_entrega_id;

  PERFORM public._entrega_seed_checklist(p_entrega_id);

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', p_entrega_id, 'DELIVERY_FORM_GENERATED',
          jsonb_build_object('comprovante_id', v_comp.id, 'numero_formulario', v_num), v_uid);

  RETURN jsonb_build_object(
    'success', true,
    'entrega_id', p_entrega_id,
    'comprovante_id', v_comp.id,
    'numero_formulario', v_num,
    'validation_token', v_token,
    'validation_hash', v_hash
  );
END $function$

CREATE OR REPLACE FUNCTION public.rpc_get_my_visit_by_client_uuid(p_client_uuid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.registros_consultor%ROWTYPE;
  v_is_admin boolean;
  v_is_gestor boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unauthenticated');
  END IF;
  IF p_client_uuid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_request');
  END IF;

  v_is_admin  := public.has_role(v_uid, 'administrador');
  v_is_gestor := public.has_role(v_uid, 'gestor');

  -- H9-D-L5: resolucao e autorizacao em consulta unica escopada.
  -- client_uuid inexistente e client_uuid alheio retornam o MESMO payload
  -- generico ('not_found'), eliminando o oraculo de existencia.
  SELECT r.* INTO v_row
    FROM public.registros_consultor r
   WHERE r.client_uuid = p_client_uuid
     AND (
       v_is_admin
       OR r.consultor_responsavel = v_uid
       OR (v_is_gestor
           AND r.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(
                 v_uid, r.cliente_id, ARRAY['view','execute','manage']))
     )
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'registro_id', v_row.id,
    'status', v_row.status::text,
    'version', v_row.version,
    'pdf_status', v_row.pdf_status
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_comprovante_entrega_data(p_entrega_id uuid, p_reemissao boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  e           public.entregas%ROWTYPE;
  v_conteudo  jsonb;
  v_snapshot  jsonb;
  v_comp      public.entrega_comprovantes%ROWTYPE;
  v_doc_tipo  text;
  v_receb     text;
  v_numero    text;
  v_hash      text;
  v_reemissoes int := 0;
  v_congelado boolean := false;
  v_item      jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'COMPROVANTE_UNAUTHENTICATED';
  END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN
    RAISE EXCEPTION 'COMPROVANTE_FORBIDDEN';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('comprovante_entrega:' || p_entrega_id::text));

  SELECT * INTO e FROM public.entregas WHERE id = p_entrega_id FOR UPDATE;
  IF e.id IS NULL THEN
    RAISE EXCEPTION 'COMPROVANTE_ENTREGA_NAO_ENCONTRADA';
  END IF;
  IF e.status = 'cancelada' THEN
    RAISE EXCEPTION 'COMPROVANTE_ENTREGA_CANCELADA';
  END IF;

  v_receb := nullif(btrim(coalesce(e.recebido_por_nome, e.recebedor_nome, '')), '');
  v_doc_tipo := CASE
                  WHEN e.status = 'entregue' AND v_receb IS NOT NULL THEN 'comprovante'
                  ELSE 'romaneio'
                END;

  v_conteudo := public.fn_comprovante_entrega_montar_v1(p_entrega_id);

  -- Documento operacional: sempre montado do estado atual, sem congelar.
  IF v_doc_tipo = 'romaneio' THEN
    RETURN jsonb_build_object(
      'doc_tipo', 'romaneio',
      'titulo', 'Romaneio de Entrega',
      'definitivo', false,
      'numero_documento', 'RM-' || upper(substr(replace(e.id::text, '-', ''), 1, 8)),
      'emitido_em', now(),
      'conteudo', v_conteudo,
      'aviso', 'Documento operacional. Nao comprova o recebimento fisico.'
    );
  END IF;

  -- Comprovante definitivo: cliente + OS + produto + lote + quantidade + volume.
  IF (v_conteudo->'destinatario'->>'cliente_id') IS NULL THEN
    RAISE EXCEPTION 'COMPROVANTE_CLIENTE_OBRIGATORIO';
  END IF;
  IF v_conteudo->'ordem_servico' IS NULL
     OR jsonb_typeof(v_conteudo->'ordem_servico') <> 'object'
     OR (v_conteudo->'ordem_servico'->>'os_id') IS NULL THEN
    RAISE EXCEPTION 'COMPROVANTE_OS_OBRIGATORIA';
  END IF;
  IF jsonb_array_length(v_conteudo->'itens') = 0 THEN
    RAISE EXCEPTION 'COMPROVANTE_SEM_ITENS';
  END IF;
  FOR v_item IN SELECT * FROM jsonb_array_elements(v_conteudo->'itens') LOOP
    IF nullif(btrim(coalesce(v_item->>'produto', '')), '') IS NULL THEN
      RAISE EXCEPTION 'COMPROVANTE_PRODUTO_OBRIGATORIO';
    END IF;
    IF nullif(btrim(coalesce(v_item->>'lote', '')), '') IS NULL THEN
      RAISE EXCEPTION 'COMPROVANTE_LOTE_OBRIGATORIO';
    END IF;
    IF coalesce((v_item->>'quantidade')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'COMPROVANTE_QUANTIDADE_OBRIGATORIA';
    END IF;
    IF coalesce((v_item->>'volume_total_ml')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'COMPROVANTE_VOLUME_OBRIGATORIO';
    END IF;
  END LOOP;
  IF (v_conteudo->'recebimento'->>'confirmado_em') IS NULL THEN
    RAISE EXCEPTION 'COMPROVANTE_CONFIRMACAO_SEM_DATA';
  END IF;

  SELECT * INTO v_comp
    FROM public.entrega_comprovantes
   WHERE entrega_id = p_entrega_id
     AND metadata ? 'comprovante_snapshot_v1'
   ORDER BY gerado_em DESC
   LIMIT 1;

  IF v_comp.id IS NOT NULL THEN
    v_congelado := true;
    v_snapshot  := v_comp.metadata->'comprovante_snapshot_v1';
    v_numero    := coalesce(v_comp.metadata->>'comprovante_numero', v_comp.numero_formulario);
    v_hash      := v_comp.metadata->>'comprovante_snapshot_hash';
    v_reemissoes := coalesce((v_comp.metadata->>'comprovante_reemissoes')::int, 0);
  ELSE
    SELECT * INTO v_comp
      FROM public.entrega_comprovantes
     WHERE entrega_id = p_entrega_id
     ORDER BY gerado_em DESC
     LIMIT 1;

    v_numero := 'CE-' || to_char(now(), 'YYYY') || '-'
             || lpad(nextval('public.comprovante_entrega_seq')::text, 6, '0');
    v_snapshot := v_conteudo || jsonb_build_object(
      'congelado_em', now(),
      'congelado_por', v_uid,
      'numero_documento', v_numero
    );
    v_hash := encode(extensions.digest(v_snapshot::text, 'sha256'), 'hex');

    IF v_comp.id IS NULL THEN
      INSERT INTO public.entrega_comprovantes (
        entrega_id, numero_formulario, tipo, status,
        validation_token, gerado_por, metadata
      ) VALUES (
        p_entrega_id, v_numero, 'comprovante_entrega', 'confirmado',
        gen_random_uuid(), v_uid,
        jsonb_build_object(
          'comprovante_snapshot_v1', v_snapshot,
          'comprovante_snapshot_hash', v_hash,
          'comprovante_numero', v_numero,
          'comprovante_reemissoes', 0
        )
      ) RETURNING * INTO v_comp;
    ELSE
      UPDATE public.entrega_comprovantes
         SET metadata = metadata || jsonb_build_object(
               'comprovante_snapshot_v1', v_snapshot,
               'comprovante_snapshot_hash', v_hash,
               'comprovante_numero', v_numero,
               'comprovante_reemissoes', 0
             ),
             updated_at = now()
       WHERE id = v_comp.id
       RETURNING * INTO v_comp;
    END IF;

    INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
    VALUES ('entrega', p_entrega_id, 'DELIVERY_RECEIPT_SNAPSHOT_FROZEN',
            jsonb_build_object('comprovante_id', v_comp.id, 'numero', v_numero, 'hash', v_hash), v_uid);
  END IF;

  IF p_reemissao AND v_congelado THEN
    v_reemissoes := v_reemissoes + 1;
    UPDATE public.entrega_comprovantes
       SET metadata = metadata || jsonb_build_object(
             'comprovante_reemissoes', v_reemissoes,
             'comprovante_ultima_reemissao_em', now(),
             'comprovante_ultima_reemissao_por', v_uid),
           updated_at = now()
     WHERE id = v_comp.id;

    INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
    VALUES ('entrega', p_entrega_id, 'DELIVERY_RECEIPT_REISSUED',
            jsonb_build_object('comprovante_id', v_comp.id, 'reemissao', v_reemissoes), v_uid);
  END IF;

  RETURN jsonb_build_object(
    'doc_tipo', 'comprovante',
    'titulo', 'Comprovante de Entrega',
    'definitivo', true,
    'numero_documento', v_numero,
    'comprovante_id', v_comp.id,
    'snapshot_hash', v_hash,
    'reemissoes', v_reemissoes,
    'emitido_em', now(),
    'conteudo', v_snapshot,
    'aviso', 'Este documento comprova exclusivamente a entrega fisica dos produtos nele relacionados. '
          || 'Nao substitui documento fiscal, receituario agronomico, prescricao tecnica ou laudo tecnico '
          || 'quando legalmente exigiveis.'
  );
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_ignorar_alerta_operacional(p_alerta_id uuid, p_observacao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alerta record;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success',false,'error','unauthorized'); END IF;
  IF NOT public.can_user_access_alerta(p_alerta_id) THEN
    RETURN jsonb_build_object('success',false,'error','forbidden');
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','alerta_nao_encontrado'); END IF;

  UPDATE public.alertas_operacionais
    SET status='ignorado', ignorado_por=auth.uid(), ignorado_em=now(), updated_at=now()
    WHERE id = p_alerta_id;

  INSERT INTO public.alertas_acoes(alerta_id, user_id, acao, observacao)
    VALUES (p_alerta_id, auth.uid(), 'ignorar', p_observacao);

  IF v_alerta.sla_config_id IS NOT NULL THEN
    INSERT INTO public.alertas_sla_eventos(alerta_id, config_id, evento, criado_por)
      VALUES (p_alerta_id, v_alerta.sla_config_id, 'sla_cancelado', auth.uid());
  END IF;

  PERFORM public.rpc_recalcular_prioridade_alerta(p_alerta_id);
  RETURN jsonb_build_object('success',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_ler_embalagem_por_qr(p_codigo_ou_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_emb record; v_etq_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  -- Tenta codigo_embalagem direto
  SELECT * INTO v_emb FROM public.estoque_embalagens WHERE codigo_embalagem = p_codigo_ou_token LIMIT 1;
  IF NOT FOUND THEN
    -- Tenta via etiqueta (codigo ou trace_token)
    SELECT id INTO v_etq_id FROM public.produto_etiquetas
     WHERE codigo_etiqueta = p_codigo_ou_token
        OR trace_token::text = p_codigo_ou_token
     LIMIT 1;
    IF v_etq_id IS NOT NULL THEN
      SELECT * INTO v_emb FROM public.estoque_embalagens WHERE etiqueta_id = v_etq_id LIMIT 1;
    END IF;
  END IF;
  IF v_emb.id IS NULL THEN RETURN jsonb_build_object('found', false); END IF;
  IF NOT public.can_user_access_estoque_embalagem(v_emb.id) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, user_id)
    VALUES (v_emb.id, 'leitura_qr', v_uid);
  RETURN jsonb_build_object(
    'found', true,
    'embalagem_id', v_emb.id,
    'codigo_embalagem', v_emb.codigo_embalagem,
    'status', v_emb.status,
    'lote_id', v_emb.lote_id,
    'produto_id', v_emb.produto_id,
    'etiqueta_id', v_emb.etiqueta_id,
    'entrega_id', v_emb.entrega_id,
    'validade_em', v_emb.validade_em,
    'volume', v_emb.volume,
    'unidade', v_emb.unidade
  );
END $function$

CREATE OR REPLACE FUNCTION public.rpc_iniciar_atendimento_solicitacao_v1(p_solicitacao_id uuid, p_client_uuid uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_s public.portal_solicitacoes%ROWTYPE;
  v_is_admin boolean;
  v_is_tech boolean;
  v_existing_id uuid;
  v_res jsonb;
  v_cuuid uuid;
BEGIN
  IF NOT public.technical_actor_ready(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unauthenticated');
  END IF;

  v_is_admin := public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor');
  v_is_tech := EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid AND ur.role IN ('tecnico_agronomo','consultor_tecnico')
  );

  IF NOT (v_is_admin OR v_is_tech) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  IF NOT public.can_user_access_solicitacao(p_solicitacao_id) THEN
    RETURN jsonb_build_object('ok',false,'error','forbidden');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('solic_atend:' || p_solicitacao_id::text, 0));

  SELECT * INTO v_s FROM public.portal_solicitacoes WHERE id = p_solicitacao_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF NOT public.technical_refs_in_actor_tenant(v_s.cliente_id,v_s.fazenda_id,v_s.talhao_id)
     OR NOT (v_is_admin OR public.technical_client_link(v_uid,v_s.cliente_id,ARRAY['execute','manage'])) THEN
    RETURN jsonb_build_object('ok',false,'error','technical_access_required');
  END IF;
  IF v_s.consultor_atribuido IS NOT NULL
     AND v_s.consultor_atribuido <> v_uid
     AND NOT v_is_admin THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_assigned');
  END IF;

  IF NOT public.has_active_user_cliente_access(v_uid, v_s.cliente_id, ARRAY['execute','manage']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'technical_access_required');
  END IF;

  SELECT id INTO v_existing_id
    FROM public.registros_consultor
   WHERE solicitacao_id = p_solicitacao_id
   ORDER BY created_at DESC LIMIT 1;

  IF v_s.consultor_atribuido IS NULL THEN
    UPDATE public.portal_solicitacoes
       SET consultor_atribuido = v_uid,
           status = CASE WHEN status IN ('pendente','aberta','em_triagem') THEN 'atribuida' ELSE status END,
           updated_at = now()
     WHERE id = p_solicitacao_id;
  END IF;

  IF v_existing_id IS NOT NULL THEN
    IF NOT public.can_manage_technical_visit(v_uid,v_existing_id) THEN
      RETURN jsonb_build_object('ok',false,'error','forbidden');
    END IF;
    SELECT jsonb_build_object(
      'ok', true, 'created', false, 'idempotent', true,
      'registro_id', r.id, 'status', r.status::text, 'version', r.version,
      'origem', r.origem_atendimento,
      'cultura_id', r.cultura_id,
      'missing_fields', CASE WHEN r.cultura_id IS NULL THEN jsonb_build_array('cultura_id') ELSE '[]'::jsonb END,
      'next_step', CASE WHEN r.cultura_id IS NULL THEN 'identificacao' ELSE 'continuar' END,
      'can_edit', r.status IN ('rascunho','em_andamento','reprovado'),
      'next_route', '/app/visita/' || r.id::text
    ) INTO v_res
    FROM public.registros_consultor r WHERE r.id = v_existing_id;
    RETURN v_res;
  END IF;

  v_cuuid := COALESCE(p_client_uuid, gen_random_uuid());

  v_res := public.rpc_criar_visita_idempotente(
    p_client_uuid := v_cuuid,
    p_cliente_id := v_s.cliente_id,
    p_fazenda_id := v_s.fazenda_id,
    p_talhao_id := v_s.talhao_id,
    p_cultura_id := NULL,
    p_data_vistoria := CURRENT_DATE,
    p_tipo_visita := 'vistoria_inicial',
    p_objetivo_visita := v_s.descricao,
    p_solicitacao_id := p_solicitacao_id,
    p_origem := 'solicitacao_produtor',
    p_urgencia := NULLIF(v_s.urgencia,'')::urgencia_consultor,
    p_problema_principal := v_s.descricao
  );

  IF NOT COALESCE((v_res->>'ok')::boolean, false) THEN
    RETURN v_res;
  END IF;

  UPDATE public.portal_solicitacoes
     SET status = CASE WHEN status IN ('pendente','aberta','em_triagem','atribuida') THEN 'em_visita' ELSE status END,
         updated_at = now()
   WHERE id = p_solicitacao_id;

  INSERT INTO public.solicitacoes_timeline (solicitacao_id, tipo_evento, descricao, usuario_id)
  VALUES (p_solicitacao_id, 'visita_iniciada', 'Atendimento técnico iniciado a partir da demanda', v_uid);

  RETURN v_res;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_set_feature_override(_organization_id uuid, _feature_key text, _mode text, _reason text, _ends_at timestamp with time zone, _limit_value numeric, _idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_feature uuid;
  v_id uuid;
  v_existing public.organization_feature_overrides%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023';
  END IF;
  IF _mode NOT IN ('GRANT','REVOKE') THEN
    RAISE EXCEPTION 'platform_invalid: modo inválido' USING ERRCODE='22023';
  END IF;
  IF _reason IS NULL OR length(btrim(_reason)) < 5 THEN
    RAISE EXCEPTION 'platform_invalid: motivo obrigatório' USING ERRCODE='22023';
  END IF;
  IF _limit_value IS NOT NULL AND _limit_value < 0 THEN
    RAISE EXCEPTION 'platform_invalid: limite inválido' USING ERRCODE='22023';
  END IF;
  IF _ends_at IS NOT NULL AND _ends_at <= now() THEN
    RAISE EXCEPTION 'platform_invalid: prazo no passado' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=_organization_id AND o.ativo) THEN
    RAISE EXCEPTION 'platform_invalid: empresa inexistente ou inativa' USING ERRCODE='22023';
  END IF;
  SELECT f.id INTO v_feature
  FROM public.saas_features f
  JOIN public.saas_modules m ON m.id=f.module_id AND m.active
  WHERE f.key=_feature_key AND f.active;
  IF v_feature IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: funcionalidade inexistente ou inativa' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_existing
  FROM public.organization_feature_overrides o
  WHERE o.idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF v_existing.organization_id=_organization_id
       AND v_existing.feature_id=v_feature
       AND v_existing.mode=_mode
       AND v_existing.reason=btrim(_reason)
       AND v_existing.ends_at IS NOT DISTINCT FROM _ends_at
       AND v_existing.limit_value IS NOT DISTINCT FROM _limit_value THEN
      RETURN v_existing.id;
    END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já utilizada' USING ERRCODE='40001';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.organization_feature_overrides o
    WHERE o.organization_id=_organization_id AND o.feature_id=v_feature AND o.ended_at IS NULL
  ) THEN
    RAISE EXCEPTION 'platform_conflict: já existe exceção aberta para esta funcionalidade' USING ERRCODE='40001';
  END IF;

  INSERT INTO public.organization_feature_overrides(
    organization_id,feature_id,mode,limit_value,ends_at,reason,created_by,idempotency_key
  ) VALUES (
    _organization_id,v_feature,_mode,_limit_value,_ends_at,btrim(_reason),auth.uid(),_idempotency_key
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_marcar_etiqueta_impressa(p_etiqueta_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_status text;
  v_count integer;
  v_new_status text;
  v_event text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF NOT (
    public.has_role(v_uid,'administrador'::app_role)
    OR public.has_role(v_uid,'gestor'::app_role)
    OR public.has_role(v_uid,'producao'::app_role)
    OR public.has_role(v_uid,'operador_onfarm'::app_role)
    OR public.has_role(v_uid,'administrativo'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para imprimir etiqueta';
  END IF;

  SELECT status, quantidade_impressoes INTO v_status, v_count
    FROM public.produto_etiquetas WHERE id = p_etiqueta_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Etiqueta não encontrada'; END IF;
  IF v_status = 'cancelada' THEN RAISE EXCEPTION 'Etiqueta cancelada não pode ser impressa'; END IF;

  IF v_status = 'gerada' THEN
    v_new_status := 'impressa'; v_event := 'etiqueta_impressa';
    UPDATE public.produto_etiquetas
      SET status='impressa', impressa_em=now(), impressa_por=v_uid,
          quantidade_impressoes = quantidade_impressoes + 1
      WHERE id = p_etiqueta_id;
  ELSE
    IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN
      RAISE EXCEPTION 'Motivo obrigatório para reimpressão (mínimo 3 caracteres)';
    END IF;
    v_new_status := 'reimpressa'; v_event := 'etiqueta_reimpressa';
    UPDATE public.produto_etiquetas
      SET status='reimpressa', ultima_reimpressao_em=now(), ultima_reimpressao_por=v_uid,
          motivo_ultima_reimpressao = trim(p_motivo),
          quantidade_impressoes = quantidade_impressoes + 1
      WHERE id = p_etiqueta_id;
  END IF;

  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, descricao, user_id, metadata)
    VALUES (p_etiqueta_id, v_event, NULLIF(trim(COALESCE(p_motivo,'')),''), v_uid,
            jsonb_build_object('quantidade_total', v_count+1, 'motivo', NULLIF(trim(COALESCE(p_motivo,'')),'')));

  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, reason)
    VALUES ('produto_etiqueta', p_etiqueta_id, upper(v_event), v_uid, NULLIF(trim(COALESCE(p_motivo,'')),''));

  RETURN jsonb_build_object('success', true, 'status', v_new_status, 'quantidade_impressoes', v_count+1);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_partner_dashboard(p_partner_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pid uuid;
  r jsonb;
BEGIN
  v_pid := COALESCE(p_partner_id, public.get_user_partner_id());
  IF v_pid IS NULL THEN RAISE EXCEPTION 'no partner'; END IF;
  IF NOT (
    public.has_role(auth.uid(),'administrador')
    OR public.has_role(auth.uid(),'gestor_comercial')
    OR (public.has_role(auth.uid(),'parceiro_b2b') AND public.get_user_partner_id() = v_pid)
  ) THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT jsonb_build_object(
    'em_andamento', COUNT(*) FILTER (WHERE status IN ('aprovado','em_producao','produzido','aguardando_entrega','em_separacao','enviado')),
    'entregues', COUNT(*) FILTER (WHERE status IN ('entregue','faturado')),
    'aguardando_aprovacao', COUNT(*) FILTER (WHERE status IN ('solicitado','em_analise_comercial','aguardando_aprovacao_credito')),
    'aguardando_ajuste', COUNT(*) FILTER (WHERE status::text='aguardando_ajuste_comercial'),
    'favoritos_count', (SELECT COUNT(*) FROM public.partner_order_templates t WHERE t.partner_id = v_pid AND t.favorito),
    'ultimas_mensagens', COALESCE((
      SELECT jsonb_agg(row_to_json(m)) FROM (
        SELECT pm.id, pm.order_id, pm.autor_tipo, pm.mensagem, pm.created_at
        FROM public.partner_order_messages pm
        JOIN public.partner_orders po ON po.id = pm.order_id
        WHERE po.partner_id = v_pid
        ORDER BY pm.created_at DESC
        LIMIT 5
      ) m
    ), '[]'::jsonb)
  ) INTO r
  FROM public.partner_orders
  WHERE partner_id = v_pid;
  RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.platform_end_feature_override(_override_id uuid, _reason text, _idempotency_key uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_existing public.organization_feature_overrides%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023';
  END IF;
  IF _reason IS NULL OR length(btrim(_reason)) < 5 THEN
    RAISE EXCEPTION 'platform_invalid: motivo obrigatório' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_existing
  FROM public.organization_feature_overrides o
  WHERE o.id=_override_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform_invalid: exceção inexistente' USING ERRCODE='22023';
  END IF;
  IF v_existing.ended_at IS NOT NULL THEN
    IF v_existing.end_idempotency_key=_idempotency_key AND v_existing.end_reason=btrim(_reason) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'platform_conflict: exceção já encerrada' USING ERRCODE='40001';
  END IF;

  UPDATE public.organization_feature_overrides
  SET ended_at=now(),ended_by=auth.uid(),end_reason=btrim(_reason),end_idempotency_key=_idempotency_key
  WHERE id=_override_id;
END;
$function$

