CREATE OR REPLACE FUNCTION public.rpc_vincular_etiqueta_embalagem(p_embalagem_id uuid, p_etiqueta_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_st text; v_et_st text; v_dup uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(p_embalagem_id) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  SELECT status INTO v_st FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF v_st IS NULL THEN RAISE EXCEPTION 'embalagem inexistente'; END IF;
  IF v_st IN ('cancelado','descartado','entregue') THEN RAISE EXCEPTION 'embalagem em status %', v_st; END IF;
  SELECT status INTO v_et_st FROM public.produto_etiquetas WHERE id = p_etiqueta_id;
  IF v_et_st IS NULL THEN RAISE EXCEPTION 'etiqueta inexistente'; END IF;
  IF v_et_st = 'cancelada' THEN RAISE EXCEPTION 'etiqueta cancelada'; END IF;
  SELECT id INTO v_dup FROM public.estoque_embalagens
    WHERE etiqueta_id = p_etiqueta_id AND id <> p_embalagem_id AND status NOT IN ('cancelado','descartado') LIMIT 1;
  IF v_dup IS NOT NULL THEN RAISE EXCEPTION 'etiqueta já vinculada a outra embalagem ativa'; END IF;
  UPDATE public.estoque_embalagens SET etiqueta_id = p_etiqueta_id WHERE id = p_embalagem_id;
  UPDATE public.produto_etiquetas SET embalagem_id = p_embalagem_id WHERE id = p_etiqueta_id;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, user_id, metadata)
    VALUES (p_embalagem_id, 'etiqueta_vinculada', v_uid, jsonb_build_object('etiqueta_id', p_etiqueta_id));
  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id, metadata)
    VALUES (p_etiqueta_id, 'etiqueta_substituida', v_uid, jsonb_build_object('embalagem_id', p_embalagem_id));
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
    VALUES ('estoque_embalagem', p_embalagem_id, 'EMB_LABEL_LINKED', v_uid, jsonb_build_object('etiqueta_id', p_etiqueta_id));
  RETURN jsonb_build_object('success', true);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_preparar_resumos_alertas(p_tipo_resumo text DEFAULT 'diario'::text, p_periodo_inicio timestamp with time zone DEFAULT NULL::timestamp with time zone, p_periodo_fim timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_service boolean := (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role';
  v_ini timestamptz;
  v_fim timestamptz;
  cfg record;
  dest record;
  v_total_dest int := 0;
  v_criados int := 0;
  v_dup int := 0;
  v_total_alertas int := 0;
  v_total_criticos int;
  v_total_alta int;
  v_total_media int;
  v_total_baixa int;
  v_total_info int;
  v_total_resolv int;
  v_total_abertos int;
  v_total_falhas int;
  v_assunto text;
  v_conteudo text;
  v_top text;
BEGIN
  IF p_tipo_resumo NOT IN ('diario','semanal','manual') THEN
    RAISE EXCEPTION 'tipo_resumo_invalido';
  END IF;

  IF NOT v_is_service THEN
    IF v_uid IS NULL THEN RAISE EXCEPTION 'permission_denied'; END IF;
    IF NOT (public.has_role(v_uid,'administrador'::app_role) OR public.has_role(v_uid,'gestor'::app_role)) THEN
      RAISE EXCEPTION 'permission_denied';
    END IF;
  END IF;

  -- Periodo
  IF p_periodo_inicio IS NOT NULL AND p_periodo_fim IS NOT NULL THEN
    v_ini := p_periodo_inicio;
    v_fim := p_periodo_fim;
  ELSIF p_tipo_resumo = 'semanal' THEN
    v_fim := date_trunc('day', now());
    v_ini := v_fim - interval '7 days';
  ELSE
    v_fim := date_trunc('day', now());
    v_ini := v_fim - interval '1 day';
  END IF;

  -- Config: usar config 'email'
  SELECT * INTO cfg FROM public.alertas_notificacao_config WHERE canal = 'email' LIMIT 1;
  IF cfg IS NULL THEN
    RETURN jsonb_build_object(
      'total_destinatarios', 0, 'total_resumos_criados', 0,
      'total_ignorados_duplicidade', 0, 'total_alertas_periodo', 0,
      'periodo_inicio', v_ini, 'periodo_fim', v_fim,
      'executado_em', now(),
      'aviso', 'config_email_inexistente'
    );
  END IF;

  -- Totais consolidados do periodo
  SELECT
    COUNT(*) FILTER (WHERE gravidade = 'critica'),
    COUNT(*) FILTER (WHERE gravidade = 'alta'),
    COUNT(*) FILTER (WHERE gravidade = 'media'),
    COUNT(*) FILTER (WHERE gravidade = 'baixa'),
    COUNT(*) FILTER (WHERE gravidade = 'informativa'),
    COUNT(*) FILTER (WHERE status = 'resolvido'),
    COUNT(*) FILTER (WHERE status IN ('aberto','reaberto','lido')),
    COUNT(*)
    INTO v_total_criticos, v_total_alta, v_total_media, v_total_baixa,
         v_total_info, v_total_resolv, v_total_abertos, v_total_alertas
  FROM public.alertas_operacionais
  WHERE created_at >= v_ini AND created_at < v_fim;

  SELECT COUNT(*) INTO v_total_falhas
  FROM public.alertas_execucoes
  WHERE status = 'falhou' AND iniciado_em >= v_ini AND iniciado_em < v_fim;

  -- Top criticos/alta abertos (max 10)
  SELECT string_agg(linha, E'\n')
    INTO v_top
    FROM (
      SELECT '- [' || gravidade::text || '] ' || COALESCE(titulo, 'sem título') AS linha
      FROM public.alertas_operacionais
      WHERE status IN ('aberto','reaberto','lido')
        AND gravidade IN ('critica','alta')
        AND created_at >= v_ini AND created_at < v_fim
      ORDER BY (gravidade = 'critica') DESC, created_at DESC
      LIMIT 10
    ) t;

  v_assunto := CASE p_tipo_resumo
    WHEN 'semanal' THEN '[AR Bio] Resumo semanal de alertas operacionais'
    WHEN 'manual'  THEN '[AR Bio] Resumo de alertas operacionais (manual)'
    ELSE '[AR Bio] Resumo diário de alertas operacionais'
  END;

  v_conteudo := format(
    'Período: %s a %s%sTotal de alertas: %s%sCríticos: %s | Alta: %s | Média: %s | Baixa: %s | Informativos: %s%sResolvidos no período: %s%sAbertos: %s%sFalhas do motor de alertas: %s%s%sPrincipais alertas críticos/alta em aberto:%s%s',
    to_char(v_ini AT TIME ZONE 'UTC', 'DD/MM/YYYY HH24:MI'),
    to_char(v_fim AT TIME ZONE 'UTC', 'DD/MM/YYYY HH24:MI'),
    E'\n', v_total_alertas,
    E'\n', v_total_criticos, v_total_alta, v_total_media, v_total_baixa, v_total_info,
    E'\n', v_total_resolv,
    E'\n', v_total_abertos,
    E'\n', v_total_falhas,
    E'\n', E'\n',
    E'\n',
    COALESCE(v_top, 'Nenhum alerta crítico ou de alta prioridade no período.')
  );

  -- Destinatarios com receber_resumo = true
  FOR dest IN
    SELECT * FROM public.alertas_notificacao_destinatarios
    WHERE ativo = true
      AND canal = 'email'
      AND receber_resumo = true
      AND email IS NOT NULL
      AND length(trim(email)) > 0
  LOOP
    v_total_dest := v_total_dest + 1;

    -- Deduplicacao
    PERFORM 1 FROM public.alertas_resumos
      WHERE tipo_resumo = p_tipo_resumo
        AND canal = 'email'
        AND destinatario_id = dest.id
        AND periodo_inicio = v_ini
        AND periodo_fim = v_fim;
    IF FOUND THEN
      v_dup := v_dup + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.alertas_resumos (
      tipo_resumo, canal, periodo_inicio, periodo_fim, status,
      destinatario_id, destino, assunto, conteudo,
      total_alertas, total_criticos, total_alta, total_media,
      total_baixa, total_informativos, total_resolvidos, total_abertos,
      total_falhas_execucao
    ) VALUES (
      p_tipo_resumo, 'email', v_ini, v_fim, 'pendente',
      dest.id, dest.email, v_assunto, v_conteudo,
      v_total_alertas, v_total_criticos, v_total_alta, v_total_media,
      v_total_baixa, v_total_info, v_total_resolv, v_total_abertos,
      v_total_falhas
    );
    v_criados := v_criados + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'total_destinatarios', v_total_dest,
    'total_resumos_criados', v_criados,
    'total_ignorados_duplicidade', v_dup,
    'total_alertas_periodo', v_total_alertas,
    'periodo_inicio', v_ini,
    'periodo_fim', v_fim,
    'executado_em', now()
  );
END $function$

CREATE OR REPLACE FUNCTION public.rpc_reabrir_alerta_operacional(p_alerta_id uuid, p_observacao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alerta record;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success',false,'error','unauthorized'); END IF;
  IF NOT public.can_user_access_alerta(p_alerta_id) THEN
    RETURN jsonb_build_object('success',false,'error','forbidden');
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','alerta_nao_encontrado'); END IF;

  UPDATE public.alertas_operacionais
    SET status='reaberto', resolvido_por=NULL, resolvido_em=NULL,
        ignorado_por=NULL, ignorado_em=NULL, updated_at=now()
    WHERE id = p_alerta_id;

  INSERT INTO public.alertas_acoes(alerta_id, user_id, acao, observacao)
    VALUES (p_alerta_id, auth.uid(), 'reabrir', p_observacao);

  IF v_alerta.sla_config_id IS NOT NULL THEN
    INSERT INTO public.alertas_sla_eventos(alerta_id, config_id, evento, criado_por)
      VALUES (p_alerta_id, v_alerta.sla_config_id, 'sla_reaberto', auth.uid());
  END IF;

  PERFORM public.rpc_recalcular_prioridade_alerta(p_alerta_id);
  RETURN jsonb_build_object('success',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_programar_retorno_visita(p_registro_id uuid, p_expected_version integer, p_data_prevista date, p_descricao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor%ROWTYPE;
  v_sol_id uuid;
  v_new_id uuid;
  v_target_user uuid;
  v_profile uuid;
  v_new_version integer;
BEGIN
  IF p_data_prevista IS NULL THEN
    RAISE EXCEPTION 'data_prevista_obrigatoria' USING ERRCODE = 'P0001';
  END IF;

  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, false);

  -- Idempotência canônica: mesma origem + mesma data prevista + rascunho
  SELECT id INTO v_new_id FROM public.registros_consultor
   WHERE registro_origem_id = p_registro_id
     AND status::text = 'rascunho'
     AND data_vistoria = p_data_prevista
   LIMIT 1;

  IF v_new_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'registro_id', v_new_id, 'version', v_reg.version, 'idempotent', true);
  END IF;

  v_target_user := v_uid;
  IF v_reg.solicitacao_id IS NOT NULL THEN
    SELECT user_id INTO v_target_user FROM public.portal_solicitacoes WHERE id = v_reg.solicitacao_id;
    v_target_user := COALESCE(v_target_user, v_uid);
  END IF;
  SELECT id INTO v_profile FROM public.profiles WHERE user_id = v_uid LIMIT 1;

  INSERT INTO public.portal_solicitacoes (
    cliente_id, fazenda_id, talhao_id, tipo_demanda, descricao, status,
    consultor_atribuido, data_prevista_atendimento, registro_origem_id,
    origem_solicitacao, user_id, urgencia, duracao_estimada
  ) VALUES (
    v_reg.cliente_id, v_reg.fazenda_id, v_reg.talhao_id, 'retorno_tecnico',
    COALESCE(NULLIF(btrim(p_descricao),''), 'Retorno técnico programado'),
    'agendada', COALESCE(v_reg.consultor_responsavel, v_uid), p_data_prevista,
    p_registro_id, 'interna', v_target_user, 'media', 120
  ) RETURNING id INTO v_sol_id;

  INSERT INTO public.registros_consultor (
    solicitacao_id, registro_origem_id, cliente_id, fazenda_id, talhao_id, cultura_id,
    consultor_responsavel, created_by, consultor_profile_id, status, tipo_visita,
    tipo_demanda, problema_principal, data_vistoria
  ) VALUES (
    v_sol_id, p_registro_id, v_reg.cliente_id, v_reg.fazenda_id, v_reg.talhao_id, v_reg.cultura_id,
    COALESCE(v_reg.consultor_responsavel, v_uid), v_uid, v_profile, 'rascunho', 'retorno',
    COALESCE(v_reg.tipo_demanda, 'outro'::public.tipo_demanda_consultor),
    'Acompanhamento de visita anterior', p_data_prevista
  ) RETURNING id INTO v_new_id;

  UPDATE public.registros_consultor
     SET data_proxima_visita = p_data_prevista,
         version = COALESCE(version,1)+1,
         updated_at = now()
   WHERE id = p_registro_id
   RETURNING version INTO v_new_version;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao, metadata)
  VALUES
    (p_registro_id, v_uid, 'retorno_programado', 'Retorno técnico programado para ' || p_data_prevista::text,
     jsonb_build_object('data_prevista', p_data_prevista, 'registro_retorno_id', v_new_id, 'version', v_new_version)),
    (v_new_id, v_uid, 'visita_criada', 'Visita de retorno criada a partir da visita ' || p_registro_id::text,
     jsonb_build_object('registro_origem_id', p_registro_id));

  RETURN jsonb_build_object('ok', true, 'registro_id', v_new_id, 'solicitacao_id', v_sol_id, 'version', v_new_version);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_resolve_commercial_price(p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_plan_id uuid, p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric, p_ref_date date DEFAULT CURRENT_DATE, p_quantity numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan record; v_rule record; v_quote record;
  v_mode text; v_base numeric(18,6); v_src text; v_unit numeric(14,2);
  v_disc numeric(9,4) := 0; v_disc_src text := 'plan';
  v_ref date := COALESCE(p_ref_date, current_date);
  v_minq numeric(14,3) := 0;
BEGIN
  IF num_nonnulls(p_product_id, p_microrganismo_id) <> 1 THEN
    RETURN jsonb_build_object('ok',false,'reason_code','ITEM_INVALID','quote_required',false);
  END IF;
  IF p_unit_type IS NULL OR p_unit_type NOT IN ('hectare','litro','dose','unidade') THEN
    RETURN jsonb_build_object('ok',false,'reason_code','UNIT_INVALID','quote_required',false);
  END IF;
  IF p_unit_type = 'unidade' AND COALESCE(p_volume_ml,0) <= 0 THEN
    RETURN jsonb_build_object('ok',false,'reason_code','VOLUME_REQUIRED','quote_required',false);
  END IF;
  IF p_plan_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason_code','PLAN_REQUIRED','quote_required',false);
  END IF;
  IF p_quantity IS NOT NULL AND p_quantity <= 0 THEN
    RETURN jsonb_build_object('ok',false,'reason_code','QUANTITY_INVALID','quote_required',false);
  END IF;

  SELECT * INTO v_plan FROM public.commercial_payment_plans WHERE id = p_plan_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason_code','PLAN_NOT_FOUND','quote_required',false);
  END IF;
  IF NOT v_plan.active THEN
    RETURN jsonb_build_object('ok',false,'reason_code','PLAN_INACTIVE','quote_required',false);
  END IF;

  v_mode := COALESCE(v_plan.pricing_mode,'discount_from_base');

  IF v_mode = 'quote_only' THEN
    RETURN jsonb_build_object('ok',false,'reason_code','QUOTE_REQUIRED','quote_required',true,
      'pricing_mode','quote_only','price_source','quote_only','plan_id',p_plan_id,'currency','BRL',
      'base_price',NULL,'plan_discount_percent',NULL,'unit_price',NULL,'final_unit_price',NULL,
      'resolved_at', now());
  END IF;

  SELECT * INTO v_rule
  FROM public.commercial_price_rules r
  WHERE r.active
    AND r.pricing_mode = v_mode
    AND r.unit_type = p_unit_type
    AND r.volume_ml IS NOT DISTINCT FROM (CASE WHEN p_unit_type='unidade' THEN p_volume_ml ELSE NULL END)
    AND r.product_id IS NOT DISTINCT FROM p_product_id
    AND r.microrganismo_id IS NOT DISTINCT FROM p_microrganismo_id
    AND r.valid_from <= v_ref
    AND (r.valid_until IS NULL OR r.valid_until >= v_ref)
    AND ( (p_buyer_scope='partner'  AND r.buyer_scope='partner'  AND r.partner_id  = p_partner_id)
       OR (p_buyer_scope='producer' AND r.buyer_scope='producer' AND r.customer_id = p_customer_id) )
    AND (r.plan_id IS NULL OR r.plan_id = p_plan_id)
    AND ( NOT EXISTS (SELECT 1 FROM public.commercial_condition_item_prices ip
                       WHERE ip.published_rule_id = r.id)
          OR EXISTS (SELECT 1 FROM public.commercial_payment_plan_assignments a
                      WHERE a.status = 'published'
                        AND a.plan_id = r.plan_id
                        AND a.buyer_scope = r.buyer_scope
                        AND a.partner_id IS NOT DISTINCT FROM r.partner_id
                        AND a.customer_id IS NOT DISTINCT FROM r.customer_id
                        AND a.valid_from <= v_ref
                        AND (a.valid_until IS NULL OR a.valid_until >= v_ref)) )
  ORDER BY (r.plan_id IS NOT NULL) DESC, r.valid_from DESC
  LIMIT 1;

  SELECT * INTO v_quote
  FROM public.commercial_price_rules r
  WHERE r.active AND r.pricing_mode = 'quote_only'
    AND r.unit_type = p_unit_type
    AND r.volume_ml IS NOT DISTINCT FROM (CASE WHEN p_unit_type='unidade' THEN p_volume_ml ELSE NULL END)
    AND r.product_id IS NOT DISTINCT FROM p_product_id
    AND r.microrganismo_id IS NOT DISTINCT FROM p_microrganismo_id
    AND r.valid_from <= v_ref
    AND (r.valid_until IS NULL OR r.valid_until >= v_ref)
    AND ( (p_buyer_scope='partner'  AND r.buyer_scope='partner'  AND r.partner_id  = p_partner_id)
       OR (p_buyer_scope='producer' AND r.buyer_scope='producer' AND r.customer_id = p_customer_id) )
    AND (r.plan_id IS NULL OR r.plan_id = p_plan_id)
    AND ( NOT EXISTS (SELECT 1 FROM public.commercial_condition_item_prices ip
                       WHERE ip.published_rule_id = r.id)
          OR EXISTS (SELECT 1 FROM public.commercial_payment_plan_assignments a
                      WHERE a.status = 'published'
                        AND a.plan_id = r.plan_id
                        AND a.buyer_scope = r.buyer_scope
                        AND a.partner_id IS NOT DISTINCT FROM r.partner_id
                        AND a.customer_id IS NOT DISTINCT FROM r.customer_id
                        AND a.valid_from <= v_ref
                        AND (a.valid_until IS NULL OR a.valid_until >= v_ref)) )
  LIMIT 1;

  IF v_quote.id IS NOT NULL THEN
    RETURN jsonb_build_object('ok',false,'reason_code','QUOTE_REQUIRED','quote_required',true,
      'pricing_mode','quote_only','price_source','quote_only','rule_id',v_quote.id,'plan_id',p_plan_id,
      'currency','BRL','base_price',NULL,'plan_discount_percent',NULL,
      'unit_price',NULL,'final_unit_price',NULL,'resolved_at', now());
  END IF;

  v_minq := COALESCE(v_rule.min_quantity, 0);
  IF v_minq > 0 THEN
    IF p_quantity IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason_code','QUANTITY_REQUIRED','quote_required',false,
        'min_quantity', v_minq, 'rule_id', v_rule.id, 'plan_id', p_plan_id, 'resolved_at', now());
    ELSIF p_quantity < v_minq THEN
      RETURN jsonb_build_object('ok',false,'reason_code','MIN_QUANTITY_NOT_MET','quote_required',false,
        'min_quantity', v_minq, 'quantity', p_quantity, 'rule_id', v_rule.id,
        'plan_id', p_plan_id, 'resolved_at', now());
    END IF;
  END IF;

  IF v_mode = 'fixed_item_price' THEN
    IF v_rule.id IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason_code','PRICE_RULE_MISSING','quote_required',false,
        'pricing_mode','fixed_item_price','price_source',NULL,'plan_id',p_plan_id,'currency','BRL',
        'base_price',NULL,'plan_discount_percent',NULL,'unit_price',NULL,'final_unit_price',NULL,
        'resolved_at', now());
    END IF;
    v_unit := round(v_rule.condition_price, 2);
    RETURN jsonb_build_object('ok',true,'reason_code','OK','quote_required',false,
      'pricing_mode','fixed_item_price','price_source','condition_fixed_price',
      'base_price', v_unit, 'condition_price', v_unit, 'plan_discount_percent', 0,
      'discount_source','none','min_quantity', v_minq,
      'unit_price', v_unit, 'final_unit_price', v_unit,
      'currency','BRL','rule_id',v_rule.id,'plan_id',p_plan_id,
      'valid_from',v_rule.valid_from,'valid_until',v_rule.valid_until,'resolved_at', now());
  END IF;

  v_disc := COALESCE(v_plan.discount_percent, 0);
  IF v_rule.id IS NOT NULL AND v_rule.discount_percent IS NOT NULL THEN
    v_disc := v_rule.discount_percent;
    v_disc_src := 'item_rule';
  END IF;

  IF p_buyer_scope = 'partner' THEN
    SELECT ppp.preco_tabela INTO v_base
    FROM public.partner_product_prices ppp
    WHERE ppp.partner_id = p_partner_id
      AND ppp.ativo
      AND ppp.product_id IS NOT DISTINCT FROM p_product_id
      AND ppp.microrganismo_id IS NOT DISTINCT FROM p_microrganismo_id
      AND (ppp.valid_from IS NULL OR ppp.valid_from <= v_ref)
      AND (ppp.valid_until IS NULL OR ppp.valid_until >= v_ref)
    ORDER BY ppp.is_current DESC, ppp.valid_from DESC NULLS LAST
    LIMIT 1;
    IF COALESCE(v_base,0) > 0 THEN v_src := 'partner_base_price'; ELSE v_base := NULL; END IF;
  END IF;

  -- H3b: fonte canonica de preco comercial = catalogo_volumes (apresentacao ativa).
  IF v_base IS NULL THEN
    v_base := public.fn_catalogo_preco_canonico(p_product_id, p_microrganismo_id, p_unit_type, p_volume_ml);
    IF COALESCE(v_base,0) > 0 THEN v_src := 'catalog_volume_price'; ELSE v_base := NULL; END IF;
  END IF;

  -- Fallback legado documentado: mestre produtos/microrganismos (nao canonico).
  IF v_base IS NULL THEN
    IF p_product_id IS NOT NULL THEN
      SELECT CASE p_unit_type
               WHEN 'hectare' THEN COALESCE(NULLIF(pr.valor_ha_brl,0), (pr.dose_ml_ha/100.0) * pr.valor_dose_brl)
               WHEN 'litro'   THEN COALESCE(NULLIF(pr.valor_litro_brl,0), pr.valor_dose_brl * 10)
               WHEN 'dose'    THEN COALESCE(NULLIF(pr.valor_dose_brl,0), pr.valor_litro_brl / 10)
               WHEN 'unidade' THEN (p_volume_ml / 1000.0) * COALESCE(NULLIF(pr.valor_litro_brl,0), pr.valor_dose_brl*10)
             END
        INTO v_base
      FROM public.produtos pr WHERE pr.id = p_product_id;
    ELSE
      SELECT CASE p_unit_type
               WHEN 'hectare' THEN (mo.dose_ml_ha/100.0) * mo.valor_dose_brl
               WHEN 'litro'   THEN COALESCE(NULLIF(mo.valor_litro_brl,0), mo.valor_dose_brl * 10)
               WHEN 'dose'    THEN COALESCE(NULLIF(mo.valor_dose_brl,0), mo.valor_litro_brl / 10)
               WHEN 'unidade' THEN (p_volume_ml / 1000.0) * COALESCE(NULLIF(mo.valor_litro_brl,0), mo.valor_dose_brl*10)
             END
        INTO v_base
      FROM public.microrganismos mo WHERE mo.id = p_microrganismo_id;
    END IF;
    IF COALESCE(v_base,0) > 0 THEN v_src := 'catalog_base_price'; ELSE v_base := NULL; END IF;
  END IF;

  IF v_base IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason_code','ITEM_WITHOUT_PRICE','quote_required',false,
      'pricing_mode','discount_from_base','price_source',NULL,'plan_id',p_plan_id,'currency','BRL',
      'base_price',NULL,'plan_discount_percent',v_disc,'unit_price',NULL,'final_unit_price',NULL,
      'rule_id', v_rule.id, 'resolved_at', now());
  END IF;

  v_unit := round(v_base * (1 - v_disc/100.0), 2);
  IF v_unit <= 0 THEN
    RETURN jsonb_build_object('ok',false,'reason_code','ITEM_WITHOUT_PRICE','quote_required',false,
      'pricing_mode','discount_from_base','currency','BRL','plan_id',p_plan_id,'resolved_at', now());
  END IF;

  RETURN jsonb_build_object('ok',true,'reason_code','OK','quote_required',false,
    'pricing_mode','discount_from_base','price_source',v_src,
    'base_price', round(v_base,2), 'condition_price', NULL, 'plan_discount_percent', v_disc,
    'discount_source', v_disc_src, 'min_quantity', v_minq,
    'unit_price', v_unit, 'final_unit_price', v_unit,
    'currency','BRL','rule_id',v_rule.id,'plan_id',p_plan_id,
    'valid_from',v_rule.valid_from,'valid_until',v_rule.valid_until,'resolved_at', now());
END $function$

CREATE OR REPLACE FUNCTION public.rpc_publish_communication_event(p_event_key text, p_source_type text, p_source_id uuid, p_payload jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id uuid; v_rule public.comunicacao_regras%rowtype;
  v_tpl public.comunicacao_templates%rowtype; v_rec record;
  v_snapshot jsonb; v_payload_snapshot jsonb; v_idem_out text;
  v_enq int := 0; v_skp int := 0; v_row int := 0;
  v_target_role public.app_role;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'autenticação requerida' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_event_key NOT IN ('produto_pronto_retirada','produto_pronto_aplicacao','administrative_important_update') THEN
    RAISE EXCEPTION 'event_key não permitido: %', p_event_key;
  END IF;
  IF jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'payload deve ser objeto JSON';
  END IF;
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador (fase 1 manual)' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    IF (SELECT count(*) FROM jsonb_object_keys(p_payload)) > 0 THEN
      RAISE EXCEPTION 'payload não aceita chaves para %', p_event_key;
    END IF;
    IF p_source_type <> 'ordens_servico' OR p_source_id IS NULL THEN
      RAISE EXCEPTION 'source ordens_servico/id requerido';
    END IF;
    IF p_event_key = 'produto_pronto_retirada' THEN
      IF NOT EXISTS (SELECT 1 FROM public.ordens_servico o
                      WHERE o.id = p_source_id AND o.status = 'pronto_entrega') THEN
        RAISE EXCEPTION 'ordens_servico não está em pronto_entrega';
      END IF;
    ELSE
      IF NOT EXISTS (SELECT 1 FROM public.ordens_servico o WHERE o.id = p_source_id) THEN
        RAISE EXCEPTION 'ordem_servico inexistente';
      END IF;
    END IF;
  ELSIF p_event_key = 'administrative_important_update' THEN
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('target_role','titulo','mensagem')) THEN
      RAISE EXCEPTION 'chaves de payload não permitidas';
    END IF;
    IF p_payload ->> 'target_role' IS NULL THEN RAISE EXCEPTION 'target_role obrigatório'; END IF;
    BEGIN
      v_target_role := (p_payload ->> 'target_role')::public.app_role;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'target_role inválido: %', p_payload ->> 'target_role';
    END;
    IF length(COALESCE(p_payload->>'titulo','')) > 200 THEN RAISE EXCEPTION 'titulo excede 200'; END IF;
    IF length(COALESCE(p_payload->>'mensagem','')) > 2000 THEN RAISE EXCEPTION 'mensagem excede 2000'; END IF;
  END IF;

  INSERT INTO public.comunicacao_eventos(event_key,source_type,source_id,payload,created_by,idempotency_key)
  VALUES (p_event_key,p_source_type,p_source_id,p_payload,auth.uid(),p_idempotency_key)
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    SELECT id INTO v_event_id FROM public.comunicacao_eventos WHERE idempotency_key = p_idempotency_key;
    RETURN jsonb_build_object('ok',true,'event_id',v_event_id,'duplicated',true);
  END IF;

  FOR v_rule IN
    SELECT * FROM public.comunicacao_regras
     WHERE event_key = p_event_key AND enabled = true
       AND (p_event_key <> 'administrative_important_update'
            OR (estrategia = 'broadcast_role' AND perfil = v_target_role))
     ORDER BY prioridade ASC
  LOOP
    v_tpl := public._comunicacao_resolve_template(v_rule.template_chave, v_rule.canal, v_rule.template_versao);
    IF v_tpl.id IS NULL OR v_tpl.canal <> v_rule.canal THEN
      v_skp := v_skp + 1; CONTINUE;
    END IF;
    v_snapshot := jsonb_build_object(
      'assunto', v_tpl.assunto, 'corpo', v_tpl.corpo,
      'variaveis', v_tpl.variaveis, 'canal', v_tpl.canal, 'locale', v_tpl.locale);

    FOR v_rec IN SELECT * FROM public._comunicacao_resolve_recipients(p_event_key, v_rule, p_source_id)
    LOOP
      IF NOT public._comunicacao_can_deliver(v_rec.recipient_user_id, v_rec.recipient_cliente_id, v_rule.canal) THEN
        v_skp := v_skp + 1; CONTINUE;
      END IF;
      v_payload_snapshot := public._comunicacao_build_snapshot(
        p_event_key, p_source_id, p_payload, v_rec.recipient_user_id, v_rec.recipient_cliente_id);
      v_idem_out := encode(extensions.digest(
        concat_ws('|', v_event_id::text, v_rule.id::text, v_tpl.id::text,
                  COALESCE(v_rec.recipient_user_id::text,''),
                  COALESCE(v_rec.recipient_cliente_id::text,'')),
        'sha256'), 'hex');
      INSERT INTO public.comunicacao_outbox(
        event_id, rule_id, template_id, template_chave, template_versao,
        template_snapshot, canal, recipient_user_id, recipient_cliente_id,
        payload_snapshot, idempotency_key)
      VALUES (
        v_event_id, v_rule.id, v_tpl.id, v_tpl.chave, v_tpl.versao,
        v_snapshot, v_rule.canal, v_rec.recipient_user_id, v_rec.recipient_cliente_id,
        v_payload_snapshot, v_idem_out)
      ON CONFLICT (idempotency_key) DO NOTHING;
      GET DIAGNOSTICS v_row = ROW_COUNT;
      IF v_row = 1 THEN v_enq := v_enq + 1; ELSE v_skp := v_skp + 1; END IF;
    END LOOP;
  END LOOP;

  UPDATE public.comunicacao_eventos
     SET status = 'processed', processed_at = now(),
         outbox_enqueued = v_enq, outbox_skipped = v_skp
   WHERE id = v_event_id;

  PERFORM public._comunicacao_write_audit('event.publish','comunicacao_eventos',v_event_id, NULL,
    jsonb_build_object('event_key',p_event_key,'enqueued',v_enq,'skipped',v_skp));

  RETURN jsonb_build_object('ok',true,'event_id',v_event_id,'duplicated',false,
    'enqueued',v_enq,'skipped',v_skp);
END$function$

CREATE OR REPLACE FUNCTION public.rpc_programar_os_v1(p_os_id uuid, p_origem text, p_data_programada date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_uid uuid:=auth.uid(); v_org uuid; v_origin text; v_os record;
 v_pp public.programacao_producao%ROWTYPE; v_before jsonb; v_after jsonb;
 v_count integer; v_canonical text; v_status text;
BEGIN
 -- Local wait bound also applies to normal SDK calls, not only migration transaction.
 PERFORM pg_catalog.set_config('lock_timeout','3s',true);
 -- O helper corrente valida a cadeia completa atual, não a MV; antes de status/replay.
 v_org:=platform_private.h15_actor_organization();
 IF v_uid IS NULL OR v_org IS NULL OR public.technical_actor_ready(v_uid) IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE THEN
 RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 BEGIN v_origin:=public.fn_cockpit_norm_origem(p_origem); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END;
 IF v_origin <> 'manual' THEN RETURN jsonb_build_object('success',false,'message','Somente OS manual neste recorte.'); END IF;
 v_canonical:='manual';
 IF p_os_id IS NULL OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=v_canonical) THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Authoritative phantom fences: conservative table locks, bounded by review transaction.
 -- Never use this path from REPEATABLE READ: stale snapshots cannot reauthorize.
 IF current_setting('transaction_isolation') <> 'read committed' THEN RAISE EXCEPTION 'PROGRAMAR_ISOLATION_DENIED' USING ERRCODE='42501'; END IF;
 -- Immediate FK checks take KEY SHARE on the locked OS/program parent.
 -- No table locks on production links or lots; parent UPDATE prevents new target references.
 -- Invites have NO user/profile FK: retain bounded SHARE against insert phantoms.
 LOCK TABLE public.platform_org_admin_invites,public.ordens_servico_onfarm IN SHARE MODE;
 -- Onfarm IDs have no FK to manual OS: retain phantom fence against a duplicate ID.
 -- Global published catalog still requires phantom protection; never drop SaaS gate.
 LOCK TABLE public.saas_plan_versions,public.saas_plan_version_features,public.saas_features,public.saas_modules IN SHARE MODE;
 SELECT o.organization_id,o.id,o.cliente_id,o.fazenda_id,o.talhao_id,o.produto_id,o.microrganismo_id,o.status::text status,o.volume_total_ml,o.data_programada os_date,o.partner_order_id,o.partner_order_item_id,o.origem INTO v_os FROM public.ordens_servico o WHERE o.id=p_os_id FOR UPDATE;
 IF v_os.id IS NULL OR (v_canonical='manual' AND v_os.organization_id IS DISTINCT FROM v_org) THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Locks sobre referências atuais. Revalidação posterior impede respostas antigas.
 PERFORM 1 FROM public.profiles WHERE user_id=v_uid OR id IN (SELECT responsavel_id FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id) ORDER BY user_id FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=v_uid ORDER BY role::text FOR SHARE;
 PERFORM 1 FROM public.organizations WHERE id=v_org FOR UPDATE;
 -- Org FK plus parent UPDATE fences new subscriptions/overrides for this tenant.
 PERFORM 1 FROM public.organization_subscriptions WHERE organization_id=v_org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.organization_feature_overrides WHERE organization_id=v_org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.clientes WHERE id=v_os.cliente_id FOR SHARE;
 PERFORM 1 FROM public.fazendas WHERE id=v_os.fazenda_id FOR SHARE;
 PERFORM 1 FROM public.talhoes WHERE id=v_os.talhao_id FOR SHARE;
 PERFORM 1 FROM public.produtos WHERE id=v_os.produto_id FOR SHARE;
 PERFORM 1 FROM public.microrganismos WHERE id=v_os.microrganismo_id FOR SHARE;
 PERFORM 1 FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id ORDER BY id FOR UPDATE;
 IF public.technical_actor_ready(v_uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=v_canonical) THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- B2B/links acionam sync comercial/planejamento/notificações não homologados.
 IF v_origin='b2b' OR v_os.origem='b2b' OR v_os.partner_order_id IS NOT NULL OR v_os.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id) THEN
 RETURN jsonb_build_object('success',false,'message','Programação B2B indisponível até validação dos efeitos associados.'); END IF;
 SELECT count(*) INTO v_count FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id;
 IF v_count<>1 THEN RETURN jsonb_build_object('success',false,'message','Programação existente não comprovada; revisão necessária.'); END IF;
 SELECT * INTO v_pp FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id;
 IF NOT ((v_pp.organization_id=v_org AND ((v_canonical='manual' AND v_pp.ordem_servico_id=p_os_id AND v_pp.ordem_servico_onfarm_id IS NULL) OR (v_canonical='onfarm' AND v_pp.ordem_servico_onfarm_id=p_os_id AND v_pp.ordem_servico_id IS NULL)) AND v_pp.produto_id IS NOT DISTINCT FROM v_os.produto_id AND v_pp.microrganismo_id IS NOT DISTINCT FROM v_os.microrganismo_id) IS TRUE) THEN RAISE EXCEPTION 'PROGRAMAR_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- FK responsável usa profiles.id; helper legado usa user_id. Não reinterpretar silenciosamente.
 IF v_pp.responsavel_id IS NOT NULL OR nullif(btrim(v_pp.responsavel),'') IS NOT NULL THEN RETURN jsonb_build_object('success',false,'message','Responsável não nulo indisponível neste recorte.'); END IF;
 IF v_os.status IS NULL OR v_os.status NOT IN ('aprovada','programada') THEN RETURN jsonb_build_object('success',false,'message','A OS deve estar previamente aprovada; esta ação não aprova nem inicia fabricação.'); END IF;
 IF platform_private.lab_item_is_manufacturable(v_os.produto_id,v_os.microrganismo_id) IS NOT TRUE THEN RETURN jsonb_build_object('success',false,'message','Item não elegível ao laboratório biológico.'); END IF;
 IF EXISTS(SELECT 1 FROM public.entregas WHERE ordem_servico_id=p_os_id) OR EXISTS(SELECT 1 FROM public.aplicacoes WHERE ordem_servico_id=p_os_id) THEN RETURN jsonb_build_object('success',false,'message','OS com entrega/aplicação já vinculada indisponível neste recorte.'); END IF;
 IF v_pp.status::text IS DISTINCT FROM 'aguardando' OR EXISTS(SELECT 1 FROM public.lotes WHERE programacao_id=v_pp.id) THEN RETURN jsonb_build_object('success',false,'message','A programação já avançou; operação indisponível.'); END IF;
 IF p_data_programada IS NULL OR NOT isfinite(p_data_programada) THEN RETURN jsonb_build_object('success',false,'message','Informe uma data válida, sem inferência automática.'); END IF;
 v_before:=jsonb_build_object('status_os',v_os.status,'data_os',v_os.os_date,'data_programacao',v_pp.data_programada,'status_programacao',v_pp.status,'volume_os',v_os.volume_total_ml,'volume_programacao',v_pp.volume_necessario);
 IF v_os.status='programada' AND v_pp.data_programada IS NOT DISTINCT FROM p_data_programada AND (v_canonical='onfarm' OR v_os.os_date IS NOT DISTINCT FROM p_data_programada) THEN RETURN jsonb_build_object('success',true,'replay',true,'status','programada','message','Programação já corresponde à data informada.'); END IF;
 -- Three-argument contract: only first scheduling and identical-state replay.
 -- Different date on a programmed OS is denied, preventing delayed A/B/A retries.
 IF v_os.status='programada' THEN RETURN jsonb_build_object('success',false,'message','OS já programada. Alteração de data indisponível neste contrato.'); END IF;
 -- Sem INSERT de programação/lote: usa somente programação previamente criada pelo fluxo.
 UPDATE public.ordens_servico SET status='programada',data_programada=p_data_programada WHERE id=p_os_id;
 -- Existing downstream trigger sets the same program date; avoid a second global refresh.
 -- No explicit program UPDATE/INSERT: exact downstream postcondition below is authoritative.
 SELECT * INTO v_pp FROM public.programacao_producao WHERE id=v_pp.id;
 IF v_pp.responsavel_id IS NOT NULL OR v_pp.organization_id IS DISTINCT FROM v_org OR v_pp.status::text IS DISTINCT FROM 'aguardando' OR v_pp.data_programada IS DISTINCT FROM p_data_programada OR EXISTS(SELECT 1 FROM public.lotes WHERE programacao_id=v_pp.id)
 OR public.technical_actor_ready(v_uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=v_canonical) THEN RAISE EXCEPTION 'PROGRAMAR_POSTCONDITION_FAILED'; END IF;
 v_after:=jsonb_build_object('status_os','programada','data_os',CASE WHEN v_canonical='manual' THEN p_data_programada ELSE NULL END,'data_programacao',v_pp.data_programada,'status_programacao',v_pp.status,'volume_os',v_os.volume_total_ml,'volume_programacao',v_pp.volume_necessario);
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 VALUES(p_os_id,v_canonical,v_pp.id,v_os.status,'programada','programar_os',v_uid,jsonb_build_object('organization_id',v_org,'before',v_before,'after',v_after,'actor',v_uid,'at',clock_timestamp(),'manufacturing_started',false)::text);
 -- Refresh interno existente por trigger permanece; nenhum refresh adicional/client-side.
 RETURN jsonb_build_object('success',true,'replay',false,'status','programada','message','Data programada; fabricação não iniciada.');
END $function$

CREATE OR REPLACE FUNCTION public.rpc_reabrir_visita(p_registro_id uuid, p_expected_version integer, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_new_version integer;
BEGIN
  IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
    RAISE EXCEPTION 'motivo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;
  IF NOT public.has_role(auth.uid(), 'administrador') THEN
    RAISE EXCEPTION 'forbidden_reabertura' USING ERRCODE = '42501';
  END IF;
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, true);

  IF v_reg.status::text <> 'aprovado' THEN
    RAISE EXCEPTION 'status_invalido' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.registros_consultor
     SET status = 'enviado_aprovacao', version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
   RETURNING version INTO v_new_version;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, auth.uid(), 'visita_reaberta', 'Visita reaberta. Motivo: ' || p_motivo);

  RETURN jsonb_build_object('ok', true, 'version', v_new_version, 'status', 'enviado_aprovacao');
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_realizar_checkin_visita(p_registro_id uuid, p_client_uuid uuid, p_tipo tipo_checkin, p_latitude numeric, p_longitude numeric, p_precisao numeric, p_justificativa_sem_gps text, p_observacoes text, p_captured_at_local timestamp with time zone, p_solicitacao_id uuid, p_cliente_id uuid, p_fazenda_id uuid, p_talhao_id uuid, p_foto_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_existing public.visitas_checkin;
  v_new public.visitas_checkin;
  v_obs text;
  v_can_manage boolean;
  v_is_participant boolean;
  v_cliente_id uuid;
  v_fazenda_id uuid;
  v_talhao_id uuid;
  v_solicitacao_id uuid;
  v_last_checkout timestamptz;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_client_uuid IS NULL THEN RAISE EXCEPTION 'client_uuid_obrigatorio' USING ERRCODE = '22023'; END IF;
  IF p_tipo = 'checkout'::public.tipo_checkin THEN RAISE EXCEPTION 'use_rpc_realizar_checkout_visita' USING ERRCODE = '22023'; END IF;
  IF p_registro_id IS NULL THEN RAISE EXCEPTION 'registro_obrigatorio' USING ERRCODE = '22023'; END IF;

  -- H9-E2 (A): gate de escopo fail-closed ANTES de qualquer leitura sensivel,
  -- inclusive do lookup por client_uuid. Registro inexistente, registro alheio
  -- e qualquer client_uuid convergem para o mesmo erro.
  IF NOT COALESCE(public._visita_scope_ok(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'forbidden_visita_nao_atribuido' USING ERRCODE = '42501';
  END IF;

  -- Derivacoes de papel somente apos o gate.
  v_can_manage := COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false);
  v_is_participant := COALESCE(public.is_active_visit_participant(v_uid, p_registro_id), false);

  -- H9-E2 (B): lock por registro antes da busca idempotente determinante.
  PERFORM 1 FROM public.registros_consultor WHERE id = p_registro_id FOR UPDATE;

  -- H9-E2 (B): busca idempotente POS-lock, ANTES de qualquer rejeicao por
  -- estado ou por duplicidade de ciclo.
  SELECT * INTO v_existing FROM public.visitas_checkin WHERE client_uuid = p_client_uuid LIMIT 1;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.registro_consultor_id IS DISTINCT FROM p_registro_id
       OR v_existing.tipo_checkin <> p_tipo
       OR (v_existing.consultor_id <> v_uid AND NOT v_can_manage) THEN
      RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object('id', v_existing.id, 'data_hora_checkin', v_existing.data_hora_checkin, 'idempotent', true);
  END IF;

  v_reg := public._assert_visita_editavel(p_registro_id);

  IF NOT v_can_manage AND NOT v_is_participant
     AND (v_reg.consultor_profile_id IS NULL OR v_reg.consultor_profile_id <> v_uid) THEN
    RAISE EXCEPTION 'forbidden_visita_nao_atribuido' USING ERRCODE = '42501';
  END IF;

  v_cliente_id := v_reg.cliente_id;
  v_fazenda_id := v_reg.fazenda_id;
  v_talhao_id  := v_reg.talhao_id;
  v_solicitacao_id := v_reg.solicitacao_id;

  IF p_cliente_id IS NOT NULL AND v_cliente_id IS NOT NULL AND p_cliente_id <> v_cliente_id THEN
    RAISE EXCEPTION 'relacional_divergente_cliente' USING ERRCODE = '22023'; END IF;
  IF p_fazenda_id IS NOT NULL AND v_fazenda_id IS NOT NULL AND p_fazenda_id <> v_fazenda_id THEN
    RAISE EXCEPTION 'relacional_divergente_fazenda' USING ERRCODE = '22023'; END IF;
  IF p_talhao_id IS NOT NULL AND v_talhao_id IS NOT NULL AND p_talhao_id <> v_talhao_id THEN
    RAISE EXCEPTION 'relacional_divergente_talhao' USING ERRCODE = '22023'; END IF;
  IF p_solicitacao_id IS NOT NULL AND v_solicitacao_id IS NOT NULL AND p_solicitacao_id <> v_solicitacao_id THEN
    RAISE EXCEPTION 'relacional_divergente_solicitacao' USING ERRCODE = '22023'; END IF;

  IF (p_latitude IS NULL OR p_longitude IS NULL)
     AND (p_justificativa_sem_gps IS NULL OR btrim(p_justificativa_sem_gps) = '') THEN
    RAISE EXCEPTION 'gps_ou_justificativa_obrigatorio' USING ERRCODE = '22023';
  END IF;

  SELECT MAX(data_hora_checkin) INTO v_last_checkout
    FROM public.visitas_checkin
   WHERE registro_consultor_id = p_registro_id
     AND consultor_id = v_uid
     AND tipo_checkin = 'checkout'::public.tipo_checkin;

  IF EXISTS (
    SELECT 1 FROM public.visitas_checkin
     WHERE registro_consultor_id = p_registro_id
       AND consultor_id = v_uid
       AND tipo_checkin = p_tipo
       AND status <> 'inconsistente'::public.status_checkin
       AND data_hora_checkin > COALESCE(v_last_checkout, '-infinity'::timestamptz)
  ) THEN
    RAISE EXCEPTION 'checkin_duplicado_para_tipo_no_ciclo' USING ERRCODE = '22023';
  END IF;

  v_obs := p_observacoes;
  IF p_captured_at_local IS NOT NULL THEN
    v_obs := COALESCE(v_obs,'') ||
             CASE WHEN v_obs IS NULL OR v_obs = '' THEN '' ELSE E'\n' END ||
             '[captured_at_local=' || p_captured_at_local::text || ']';
  END IF;

  INSERT INTO public.visitas_checkin (
    registro_consultor_id, solicitacao_id, cliente_id, fazenda_id, talhao_id,
    consultor_id, tipo_checkin, latitude, longitude, precisao_gps,
    justificativa_sem_gps, observacoes, foto_path, client_uuid,
    data_hora_checkin, status
  ) VALUES (
    p_registro_id, v_solicitacao_id, v_cliente_id, v_fazenda_id, v_talhao_id,
    v_uid, p_tipo, p_latitude, p_longitude, p_precisao,
    NULLIF(btrim(COALESCE(p_justificativa_sem_gps,'')), ''),
    v_obs, p_foto_path, p_client_uuid,
    now(), 'realizado'::public.status_checkin
  ) RETURNING * INTO v_new;

  -- H9-GR: log de presenca gravado exclusivamente pelo trigger canonico
  -- trg_log_checkin -> public.log_visita_checkin() (uma linha por evento).

  IF v_solicitacao_id IS NOT NULL THEN
    UPDATE public.portal_solicitacoes SET status='checkin_realizado', updated_at=now()
     WHERE id = v_solicitacao_id
       AND (cliente_id IS NULL OR v_cliente_id IS NULL OR cliente_id = v_cliente_id);
    INSERT INTO public.solicitacoes_timeline (solicitacao_id, tipo_evento, descricao, usuario_id)
    VALUES (v_solicitacao_id, 'checkin_realizado',
            COALESCE(p_observacoes,'Check-in realizado via visita técnica'), v_uid);
  END IF;

  RETURN jsonb_build_object('id', v_new.id, 'data_hora_checkin', v_new.data_hora_checkin, 'idempotent', false);
EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_existing FROM public.visitas_checkin WHERE client_uuid = p_client_uuid LIMIT 1;
    IF v_existing.id IS NOT NULL THEN
      IF v_existing.registro_consultor_id IS DISTINCT FROM p_registro_id
         OR v_existing.tipo_checkin <> p_tipo
         OR (v_existing.consultor_id <> v_uid AND NOT v_can_manage) THEN
        RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = '22023';
      END IF;
      RETURN jsonb_build_object('id', v_existing.id, 'data_hora_checkin', v_existing.data_hora_checkin, 'idempotent', true);
    END IF;
    RAISE;
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_realizar_checkout_visita(p_registro_id uuid, p_client_uuid uuid, p_latitude numeric, p_longitude numeric, p_precisao numeric, p_justificativa_sem_gps text, p_observacoes text, p_captured_at_local timestamp with time zone, p_foto_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_existing public.visitas_checkin;
  v_last_event public.visitas_checkin;
  v_new public.visitas_checkin;
  v_obs text;
  v_can_manage boolean;
  v_is_participant boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_client_uuid IS NULL THEN RAISE EXCEPTION 'client_uuid_obrigatorio' USING ERRCODE='22023'; END IF;
  IF p_registro_id IS NULL THEN RAISE EXCEPTION 'registro_obrigatorio' USING ERRCODE='22023'; END IF;

  -- H9-E2 (A): gate de escopo fail-closed ANTES de qualquer leitura sensivel,
  -- inclusive do lookup por client_uuid (oraculo remanescente da H9-D-L6).
  IF NOT COALESCE(public._visita_scope_ok(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'forbidden_visita_nao_atribuido' USING ERRCODE = '42501';
  END IF;

  -- Derivacoes de papel somente apos o gate.
  v_can_manage := COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false);
  v_is_participant := COALESCE(public.is_active_visit_participant(v_uid, p_registro_id), false);

  -- H9-E2 (B): lock por registro antes da busca idempotente determinante.
  PERFORM 1 FROM public.registros_consultor WHERE id = p_registro_id FOR UPDATE;

  -- H9-E2 (B): busca idempotente POS-lock, ANTES da duplicidade de encerramento e das
  -- demais rejeicoes de ciclo. A sessao perdedora converge para o vencedor.
  SELECT * INTO v_existing FROM public.visitas_checkin WHERE client_uuid = p_client_uuid LIMIT 1;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.registro_consultor_id IS DISTINCT FROM p_registro_id
       OR v_existing.tipo_checkin <> 'checkout'::public.tipo_checkin
       OR (v_existing.consultor_id <> v_uid AND NOT v_can_manage) THEN
      RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='22023';
    END IF;
    RETURN jsonb_build_object('id', v_existing.id, 'data_hora_checkin', v_existing.data_hora_checkin, 'idempotent', true);
  END IF;

  v_reg := public._assert_visita_editavel(p_registro_id);

  IF NOT v_can_manage AND NOT v_is_participant
     AND (v_reg.consultor_profile_id IS NULL OR v_reg.consultor_profile_id <> v_uid) THEN
    RAISE EXCEPTION 'forbidden_visita_nao_atribuido' USING ERRCODE='42501';
  END IF;

  IF (p_latitude IS NULL OR p_longitude IS NULL)
     AND (p_justificativa_sem_gps IS NULL OR btrim(p_justificativa_sem_gps) = '') THEN
    RAISE EXCEPTION 'gps_ou_justificativa_obrigatorio' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_last_event FROM public.visitas_checkin
   WHERE registro_consultor_id = p_registro_id AND consultor_id = v_uid
   ORDER BY data_hora_checkin DESC, created_at DESC, id DESC LIMIT 1;

  IF v_last_event.id IS NULL THEN RAISE EXCEPTION 'checkout_sem_checkin' USING ERRCODE='22023'; END IF;
  IF v_last_event.tipo_checkin = 'checkout'::public.tipo_checkin THEN RAISE EXCEPTION 'checkout_duplicado' USING ERRCODE='22023'; END IF;
  IF v_last_event.data_hora_checkin > now() THEN RAISE EXCEPTION 'checkin_no_futuro' USING ERRCODE='22023'; END IF;

  v_obs := p_observacoes;
  IF p_captured_at_local IS NOT NULL THEN
    v_obs := COALESCE(v_obs,'') ||
             CASE WHEN v_obs IS NULL OR v_obs='' THEN '' ELSE E'\n' END ||
             '[captured_at_local=' || p_captured_at_local::text || ']';
  END IF;

  INSERT INTO public.visitas_checkin (
    registro_consultor_id, solicitacao_id, cliente_id, fazenda_id, talhao_id,
    consultor_id, tipo_checkin, latitude, longitude, precisao_gps,
    justificativa_sem_gps, observacoes, foto_path, client_uuid,
    data_hora_checkin, status
  ) VALUES (
    p_registro_id, v_last_event.solicitacao_id, v_last_event.cliente_id,
    v_last_event.fazenda_id, v_last_event.talhao_id,
    v_uid, 'checkout'::public.tipo_checkin, p_latitude, p_longitude, p_precisao,
    NULLIF(btrim(COALESCE(p_justificativa_sem_gps,'')), ''),
    v_obs, p_foto_path, p_client_uuid,
    now(), 'realizado'::public.status_checkin
  ) RETURNING * INTO v_new;

  -- H9-GR: log de presenca gravado exclusivamente pelo trigger canonico
  -- trg_log_checkin -> public.log_visita_checkin() (acao 'checkout_realizado').

  IF v_last_event.solicitacao_id IS NOT NULL THEN
    INSERT INTO public.solicitacoes_timeline (solicitacao_id, tipo_evento, descricao, usuario_id)
    VALUES (v_last_event.solicitacao_id, 'checkout_realizado',
            COALESCE(p_observacoes,'Presença encerrada com sucesso'), v_uid);
  END IF;

  RETURN jsonb_build_object('id', v_new.id, 'data_hora_checkin', v_new.data_hora_checkin, 'idempotent', false);
EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_existing FROM public.visitas_checkin WHERE client_uuid = p_client_uuid LIMIT 1;
    IF v_existing.id IS NOT NULL THEN
      IF v_existing.registro_consultor_id IS DISTINCT FROM p_registro_id
         OR v_existing.tipo_checkin <> 'checkout'::public.tipo_checkin
         OR (v_existing.consultor_id <> v_uid AND NOT v_can_manage) THEN
        RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='22023';
      END IF;
      RETURN jsonb_build_object('id', v_existing.id, 'data_hora_checkin', v_existing.data_hora_checkin, 'idempotent', true);
    END IF;
    RAISE;
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_registrar_ocorrencia_entrega(p_entrega_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão inválida'; END IF;
  IF NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.entregas WHERE id = p_entrega_id) THEN
    RAISE EXCEPTION 'Entrega não encontrada';
  END IF;

  INSERT INTO public.entrega_ocorrencias (entrega_id, tipo, descricao, gravidade, registrado_por, metadata)
  VALUES (
    p_entrega_id,
    coalesce(p_payload->>'tipo','observacao'),
    coalesce(p_payload->>'descricao',''),
    coalesce(p_payload->>'gravidade','baixa'),
    v_uid,
    coalesce(p_payload->'metadata','{}'::jsonb)
  ) RETURNING id INTO v_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', p_entrega_id, 'DELIVERY_OCCURRENCE_REGISTERED',
          jsonb_build_object('ocorrencia_id', v_id, 'tipo', p_payload->>'tipo'), v_uid);

  RETURN jsonb_build_object('success', true, 'id', v_id);
END $function$

CREATE OR REPLACE FUNCTION public.get_partner_catalog_secure(p_partner_id uuid)
 RETURNS TABLE(item_id uuid, item_tipo text, product_id uuid, produto_nome text, produto_codigo text, descricao_curta text, preco_tabela numeric, desconto_percentual numeric, preco_parceiro numeric, produto_ativo boolean, resumo_curto text, explicacao_b2b text, beneficios_principais text, ficha_status text, ficha_aprovada boolean, valor_dose_brl numeric, valor_litro_brl numeric, valor_ha_brl numeric, unidade_preco_principal text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_visibility_scope uuid[];
  v_uid uuid := auth.uid();
  v_super boolean; s record; r record;
  v_pid uuid; v_mid uuid; j_ha jsonb; j_li jsonb; j_do jsonb;
  n_ha numeric; n_li numeric; n_do numeric; v_base numeric; v_unid text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
  IF p_partner_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.partner_accounts pa
       WHERE pa.id = p_partner_id AND pa.ativo = true AND pa.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'partner_not_found' USING ERRCODE='42501';
  END IF;
  v_super := public.is_platform_superadmin(v_uid);
  IF NOT v_super THEN
    IF public.has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN
      RAISE EXCEPTION 'forbidden_financial_terms' USING ERRCODE='42501';
    END IF;
    SELECT * INTO s FROM platform_private.b2b_actor_scope(v_uid);
    IF (NOT s.profile_ok OR s.org_partner IS DISTINCT FROM p_partner_id OR NOT s.partner_valid)
       AND NOT (platform_private.b2b_internal_commercial_actor()
                AND platform_private.c2_internal_order_target_reason(v_uid, p_partner_id) IS NULL) THEN
      RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
    END IF;
    IF public.has_role(v_uid,'parceiro_b2b'::app_role) THEN
      IF s.user_partner_count <> 1 OR s.user_partner IS DISTINCT FROM p_partner_id THEN
        RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
      END IF;
    ELSIF NOT (public.has_role(v_uid,'administrador'::app_role) OR public.has_role(v_uid,'gestor_comercial'::app_role)) THEN
      RAISE EXCEPTION 'forbidden_role' USING ERRCODE='42501';
    END IF;
    IF NOT s.has_catalog THEN RAISE EXCEPTION 'feature_not_entitled' USING ERRCODE='42501'; END IF;
  END IF;

  v_visibility_scope := platform_private.c1b_catalog_visibility_scope(p_partner_id);
  FOR r IN
    SELECT p.id, 'produto'::text AS tipo, p.nome, p.codigo, p.ativo,
           ptp.status_validacao, ptp.resumo_curto, ptp.explicacao_b2b, ptp.beneficio_combinado AS beneficios
      FROM public.produtos p LEFT JOIN public.product_technical_profiles ptp ON ptp.produto_id = p.id
     WHERE p.ativo = true AND p.b2b_enabled = true AND NOT EXISTS (SELECT 1 FROM public.catalog_tenant_visibility cv WHERE cv.organization_id=ANY(v_visibility_scope) AND cv.entity_type='produto' AND cv.hidden IS TRUE AND cv.produto_id=p.id)
    UNION ALL
    SELECT m.id, 'microrganismo'::text, m.nome, m.codigo, m.ativo,
           mtp.status_validacao, mtp.resumo_curto, mtp.explicacao_b2b, mtp.beneficios_agronomicos
      FROM public.microrganismos m LEFT JOIN public.microorganism_technical_profiles mtp ON mtp.microrganismo_id = m.id
     WHERE m.ativo = true AND m.b2b_enabled = true AND NOT EXISTS (SELECT 1 FROM public.catalog_tenant_visibility cv WHERE cv.organization_id=ANY(v_visibility_scope) AND cv.entity_type='microrganismo' AND cv.hidden IS TRUE AND cv.microrganismo_id=m.id)
  LOOP
    v_pid := CASE WHEN r.tipo='produto' THEN r.id END;
    v_mid := CASE WHEN r.tipo='microrganismo' THEN r.id END;
    j_ha := public.fn_b2b_resolve_base_unit_price(p_partner_id, v_pid, v_mid, 'hectare', NULL, current_date);
    j_li := public.fn_b2b_resolve_base_unit_price(p_partner_id, v_pid, v_mid, 'litro',   NULL, current_date);
    j_do := public.fn_b2b_resolve_base_unit_price(p_partner_id, v_pid, v_mid, 'dose',    NULL, current_date);
    n_ha := CASE WHEN COALESCE((j_ha->>'ok')::boolean,false) THEN NULLIF((j_ha->>'base_price')::numeric,0) END;
    n_li := CASE WHEN COALESCE((j_li->>'ok')::boolean,false) THEN NULLIF((j_li->>'base_price')::numeric,0) END;
    n_do := CASE WHEN COALESCE((j_do->>'ok')::boolean,false) THEN NULLIF((j_do->>'base_price')::numeric,0) END;
    v_unid := CASE WHEN n_ha IS NOT NULL THEN 'hectare' WHEN n_li IS NOT NULL THEN 'litro'
                   WHEN n_do IS NOT NULL THEN 'dose_100ml' ELSE 'sob_consulta' END;
    v_base := COALESCE(n_ha, n_li, n_do);
    item_id := r.id; item_tipo := r.tipo; product_id := v_pid;
    produto_nome := r.nome; produto_codigo := r.codigo;
    descricao_curta := CASE WHEN r.status_validacao='aprovado' THEN LEFT(COALESCE(r.resumo_curto,''),220) END;
    preco_tabela := ROUND(v_base,2);
    desconto_percentual := CASE WHEN v_base IS NOT NULL THEN 0::numeric END;
    preco_parceiro := ROUND(v_base,2);
    produto_ativo := r.ativo;
    resumo_curto := CASE WHEN r.status_validacao='aprovado' THEN r.resumo_curto END;
    explicacao_b2b := CASE WHEN r.status_validacao='aprovado' THEN r.explicacao_b2b END;
    beneficios_principais := CASE WHEN r.status_validacao='aprovado' THEN r.beneficios END;
    ficha_status := COALESCE(r.status_validacao,'sem_ficha');
    ficha_aprovada := (r.status_validacao = 'aprovado');
    valor_dose_brl := ROUND(n_do,2); valor_litro_brl := ROUND(n_li,2); valor_ha_brl := ROUND(n_ha,2);
    unidade_preco_principal := v_unid;
    RETURN NEXT;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_recalcular_prioridade_alerta(p_alerta_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_score integer := 0;
  v_alerta record;
  v_uid uuid := auth.uid();
  v_is_service boolean := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role', false);
BEGIN
  IF NOT v_is_service THEN
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'permission_denied' USING HINT = 'Usuario nao autenticado';
    END IF;
    IF NOT (
      public.has_role(v_uid,'administrador'::app_role)
      OR public.has_role(v_uid,'gestor'::app_role)
      OR public.has_role(v_uid,'administrativo'::app_role)
    ) THEN
      RAISE EXCEPTION 'permission_denied' USING HINT = 'Perfil sem permissao para recalcular prioridade';
    END IF;
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_score := CASE v_alerta.gravidade
    WHEN 'critica' THEN 100
    WHEN 'alta' THEN 70
    WHEN 'media' THEN 40
    WHEN 'baixa' THEN 20
    WHEN 'informativa' THEN 5
    ELSE 0 END;

  IF v_alerta.sla_vencido THEN v_score := v_score + 30; END IF;
  IF v_alerta.escalonado THEN v_score := v_score + 20; END IF;
  IF v_alerta.created_at < now() - interval '3 days' AND v_alerta.status NOT IN ('resolvido','ignorado') THEN
    v_score := v_score + 10;
  END IF;
  IF v_alerta.tipo = 'cq_reprovado' THEN v_score := v_score + 20; END IF;
  IF v_alerta.tipo = 'entrega_pendente_critica' THEN v_score := v_score + 15; END IF;

  UPDATE public.alertas_operacionais SET prioridade_score = v_score WHERE id = p_alerta_id;
  RETURN v_score;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_recalcular_separacao_entrega(p_entrega_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_total int; v_res int; v_sep int; v_ent int; v_status text;
BEGIN
  SELECT count(*) FILTER (WHERE status NOT IN ('cancelado','descartado')),
         count(*) FILTER (WHERE status='reservado'),
         count(*) FILTER (WHERE status='separado'),
         count(*) FILTER (WHERE status='entregue')
    INTO v_total, v_res, v_sep, v_ent
    FROM public.estoque_embalagens WHERE entrega_id = p_entrega_id;
  IF v_total = 0 THEN v_status := 'pendente';
  ELSIF (v_sep + v_ent) = v_total THEN v_status := 'separada';
  ELSIF (v_sep + v_ent) > 0 THEN v_status := 'parcialmente_separada';
  ELSE v_status := 'pendente';
  END IF;
  UPDATE public.entregas SET separacao_status = v_status WHERE id = p_entrega_id;
  RETURN v_status;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_record_aplicacao_email(_aplicacao_id uuid, _email text, _status text DEFAULT 'queued'::text, _idempotency_key text DEFAULT NULL::text, _enviado_por uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  caller_uid uuid := auth.uid();
  new_id uuid; existing_id uuid; existing_status text; final_author uuid;
  v_cli_id uuid; v_apl_resp uuid; v_apl_created_by uuid;
  allowed text[] := ARRAY['queued','pending','sent','failed','link_generated_no_send','enviado'];
  progressable text[] := ARRAY['queued','pending','failed','link_generated_no_send'];
BEGIN
  IF _aplicacao_id IS NULL OR _email IS NULL THEN
    RAISE EXCEPTION 'aplicacao_id e email são obrigatórios' USING ERRCODE = '22023';
  END IF;
  IF NOT (_status = ANY(allowed)) THEN
    RAISE EXCEPTION 'status % inválido', _status USING ERRCODE='22023';
  END IF;
  IF _email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR char_length(_email) > 320 THEN
    RAISE EXCEPTION 'e-mail inválido' USING ERRCODE='22023';
  END IF;
  final_author := COALESCE(caller_uid, _enviado_por);
  IF final_author IS NULL THEN RAISE EXCEPTION 'enviado_por obrigatório' USING ERRCODE='42501'; END IF;

  SELECT os.cliente_id, a.responsavel_id, a.created_by
    INTO v_cli_id, v_apl_resp, v_apl_created_by
    FROM public.aplicacoes a JOIN public.ordens_servico os ON os.id = a.ordem_servico_id
   WHERE a.id = _aplicacao_id;
  IF v_cli_id IS NULL THEN RAISE EXCEPTION 'Aplicação inexistente' USING ERRCODE='23503'; END IF;

  IF NOT (has_role(final_author, 'administrador'::app_role)
          OR final_author = v_apl_resp OR final_author = v_apl_created_by) THEN
    RAISE EXCEPTION 'Sem vínculo com a aplicação' USING ERRCODE='42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.clientes c
     WHERE c.id = v_cli_id
       AND lower(_email) IN (lower(coalesce(c.email,'')), lower(coalesce(c.contato_financeiro_email,'')))
  ) THEN
    RAISE EXCEPTION 'Destinatário não cadastrado para o cliente' USING ERRCODE='42501';
  END IF;

  IF _idempotency_key IS NOT NULL THEN
    INSERT INTO public.aplicacao_emails (aplicacao_id, email, status, enviado_por, idempotency_key)
    VALUES (_aplicacao_id, lower(_email), _status, final_author, _idempotency_key)
    ON CONFLICT DO NOTHING RETURNING id INTO new_id;

    IF new_id IS NOT NULL THEN
      RETURN jsonb_build_object('created', true, 'duplicated', false, 'updated', false, 'record_id', new_id, 'status', _status);
    END IF;
    SELECT id, status INTO existing_id, existing_status FROM public.aplicacao_emails
     WHERE idempotency_key = _idempotency_key LIMIT 1;
    IF existing_id IS NULL THEN RAISE EXCEPTION 'Falha de idempotência' USING ERRCODE='23505'; END IF;
    IF _status = 'sent' AND existing_status = ANY(progressable) THEN
      UPDATE public.aplicacao_emails SET status='sent', email=lower(_email),
             enviado_por = COALESCE(enviado_por, final_author)
       WHERE id = existing_id RETURNING status INTO existing_status;
      RETURN jsonb_build_object('created', false, 'duplicated', false, 'updated', true, 'record_id', existing_id, 'status', existing_status);
    END IF;
    RETURN jsonb_build_object('created', false, 'duplicated', true, 'updated', false, 'record_id', existing_id, 'status', existing_status);
  END IF;

  INSERT INTO public.aplicacao_emails (aplicacao_id, email, status, enviado_por, idempotency_key)
  VALUES (_aplicacao_id, lower(_email), _status, final_author, NULL)
  RETURNING id INTO new_id;
  RETURN jsonb_build_object('created', true, 'duplicated', false, 'updated', false, 'record_id', new_id, 'status', _status);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_b2b_resolve_base_unit_price(p_partner_id uuid, p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric DEFAULT NULL::numeric, p_ref_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ref  date := COALESCE(p_ref_date, current_date);
  v_base numeric(18,6);
  v_src  text;
BEGIN
  IF num_nonnulls(p_product_id, p_microrganismo_id) <> 1 THEN
    RETURN jsonb_build_object('ok', false, 'reason_code', 'ITEM_INVALID');
  END IF;
  IF p_unit_type IS NULL OR p_unit_type NOT IN ('hectare','litro','dose','unidade') THEN
    RETURN jsonb_build_object('ok', false, 'reason_code', 'UNIT_INVALID');
  END IF;
  IF p_unit_type = 'unidade' AND COALESCE(p_volume_ml, 0) <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason_code', 'VOLUME_REQUIRED');
  END IF;

  IF p_partner_id IS NOT NULL THEN
    SELECT ppp.preco_tabela INTO v_base
    FROM public.partner_product_prices ppp
    WHERE ppp.partner_id = p_partner_id
      AND ppp.ativo
      AND ppp.product_id IS NOT DISTINCT FROM p_product_id
      AND ppp.microrganismo_id IS NOT DISTINCT FROM p_microrganismo_id
      AND (ppp.valid_from IS NULL OR ppp.valid_from <= v_ref)
      AND (ppp.valid_until IS NULL OR ppp.valid_until >= v_ref)
    ORDER BY ppp.is_current DESC, ppp.valid_from DESC NULLS LAST
    LIMIT 1;
    IF COALESCE(v_base, 0) > 0 THEN v_src := 'partner_base_price'; ELSE v_base := NULL; END IF;
  END IF;

  -- H3b: fonte canonica de preco comercial = catalogo_volumes (apresentacao ativa).
  IF v_base IS NULL THEN
    v_base := public.fn_catalogo_preco_canonico(p_product_id, p_microrganismo_id, p_unit_type, p_volume_ml);
    IF COALESCE(v_base,0) > 0 THEN v_src := 'catalog_volume_price'; ELSE v_base := NULL; END IF;
  END IF;

  -- Fallback legado documentado: mestre produtos/microrganismos (nao canonico).
  IF v_base IS NULL THEN
    IF p_product_id IS NOT NULL THEN
      SELECT CASE p_unit_type
               WHEN 'hectare' THEN COALESCE(NULLIF(pr.valor_ha_brl,0), (pr.dose_ml_ha/100.0) * pr.valor_dose_brl)
               WHEN 'litro'   THEN COALESCE(NULLIF(pr.valor_litro_brl,0), pr.valor_dose_brl * 10)
               WHEN 'dose'    THEN COALESCE(NULLIF(pr.valor_dose_brl,0), pr.valor_litro_brl / 10)
               WHEN 'unidade' THEN (p_volume_ml / 1000.0) * COALESCE(NULLIF(pr.valor_litro_brl,0), pr.valor_dose_brl*10)
             END
        INTO v_base
      FROM public.produtos pr WHERE pr.id = p_product_id;
    ELSE
      SELECT CASE p_unit_type
               WHEN 'hectare' THEN (mo.dose_ml_ha/100.0) * mo.valor_dose_brl
               WHEN 'litro'   THEN COALESCE(NULLIF(mo.valor_litro_brl,0), mo.valor_dose_brl * 10)
               WHEN 'dose'    THEN COALESCE(NULLIF(mo.valor_dose_brl,0), mo.valor_litro_brl / 10)
               WHEN 'unidade' THEN (p_volume_ml / 1000.0) * COALESCE(NULLIF(mo.valor_litro_brl,0), mo.valor_dose_brl*10)
             END
        INTO v_base
      FROM public.microrganismos mo WHERE mo.id = p_microrganismo_id;
    END IF;
    IF COALESCE(v_base, 0) > 0 THEN v_src := 'catalog_base_price'; ELSE v_base := NULL; END IF;
  END IF;

  IF v_base IS NULL OR v_base <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason_code', 'ITEM_WITHOUT_PRICE');
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'reason_code', 'OK',
    'price_source', v_src,
    'base_price', round(v_base, 2),
    'currency', 'BRL',
    'resolved_at', now()
  );
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_refresh_bi_operacional()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_start timestamptz;
  v_dur integer;
  v_result jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;
  IF NOT (public.has_role(v_uid, 'administrador') OR public.has_role(v_uid, 'gestor')) THEN
    RAISE EXCEPTION 'Acesso negado: somente administrador ou gestor';
  END IF;

  v_start := clock_timestamp();
  BEGIN
    REFRESH MATERIALIZED VIEW public.mv_esteira_laboratorio;
    v_dur := EXTRACT(MILLISECOND FROM (clock_timestamp() - v_start))::int;
    INSERT INTO public.bi_refresh_audit(executed_by, target, duration_ms, success)
      VALUES (v_uid, 'mv_esteira_laboratorio', v_dur, true);
    v_result := v_result || jsonb_build_object('mv_esteira_laboratorio', jsonb_build_object('ok', true, 'duration_ms', v_dur));
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.bi_refresh_audit(executed_by, target, success, error_message)
      VALUES (v_uid, 'mv_esteira_laboratorio', false, SQLERRM);
    v_result := v_result || jsonb_build_object('mv_esteira_laboratorio', jsonb_build_object('ok', false, 'error', SQLERRM));
  END;

  v_start := clock_timestamp();
  BEGIN
    REFRESH MATERIALIZED VIEW public.mv_fluxo_visita_tecnica;
    v_dur := EXTRACT(MILLISECOND FROM (clock_timestamp() - v_start))::int;
    INSERT INTO public.bi_refresh_audit(executed_by, target, duration_ms, success)
      VALUES (v_uid, 'mv_fluxo_visita_tecnica', v_dur, true);
    v_result := v_result || jsonb_build_object('mv_fluxo_visita_tecnica', jsonb_build_object('ok', true, 'duration_ms', v_dur));
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.bi_refresh_audit(executed_by, target, success, error_message)
      VALUES (v_uid, 'mv_fluxo_visita_tecnica', false, SQLERRM);
    v_result := v_result || jsonb_build_object('mv_fluxo_visita_tecnica', jsonb_build_object('ok', false, 'error', SQLERRM));
  END;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_record_whatsapp_delivery_status(p_provider_message_id text, p_status text, p_timestamp timestamp with time zone, p_error_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_outbox public.comunicacao_outbox; v_error_code_norm text; v_inserted_id uuid;
  v_state_after text; v_ts_after timestamptz;
  v_delivered_after timestamptz; v_read_after timestamptz; v_failed_after timestamptz;
  v_upgraded boolean := false; v_current_state text; v_current_ts timestamptz;
BEGIN
  IF p_provider_message_id IS NULL OR length(p_provider_message_id) < 1
     OR length(p_provider_message_id) > 200 THEN
    RAISE EXCEPTION 'invalid_provider_message_id' USING ERRCODE='22023'; END IF;
  IF p_status IS NULL OR p_status NOT IN ('sent','delivered','read','failed','deleted') THEN
    RAISE EXCEPTION 'invalid_status' USING ERRCODE='22023'; END IF;
  IF p_timestamp IS NULL THEN RAISE EXCEPTION 'invalid_timestamp' USING ERRCODE='22023'; END IF;
  IF p_timestamp < timestamptz '2020-01-01' OR p_timestamp > now() + interval '1 day' THEN
    RAISE EXCEPTION 'timestamp_out_of_range' USING ERRCODE='22023'; END IF;

  v_error_code_norm := NULL;
  IF p_error_code IS NOT NULL AND length(p_error_code) > 0 THEN
    IF length(p_error_code) > 80 OR p_error_code !~ '^[a-z0-9_.:-]{1,80}$' THEN
      RAISE EXCEPTION 'invalid_error_code' USING ERRCODE='22023'; END IF;
    v_error_code_norm := p_error_code;
  END IF;

  SELECT * INTO v_outbox FROM public.comunicacao_outbox
   WHERE canal = 'whatsapp' AND provider_message_id = p_provider_message_id
   ORDER BY id FOR UPDATE LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',true,'ignored',true,'reason','unmatched');
  END IF;

  INSERT INTO public.comunicacao_provider_receipts
    (outbox_id, provider, provider_message_id, status, provider_timestamp, error_code)
  VALUES (v_outbox.id,'whatsapp',p_provider_message_id,p_status,p_timestamp,v_error_code_norm)
  ON CONFLICT (provider, provider_message_id, status, provider_timestamp) DO NOTHING
  RETURNING id INTO v_inserted_id;

  IF v_inserted_id IS NULL THEN
    RETURN jsonb_build_object('ok',true,'duplicated',true,'outbox_id',v_outbox.id);
  END IF;

  v_current_state := v_outbox.provider_delivery_status;
  v_current_ts := v_outbox.provider_status_at;
  v_state_after := v_current_state; v_ts_after := v_current_ts;
  v_delivered_after := v_outbox.delivered_at;
  v_read_after := v_outbox.read_at;
  v_failed_after := v_outbox.provider_failed_at;

  IF p_status = 'read' THEN
    v_read_after := LEAST(COALESCE(v_outbox.read_at, p_timestamp), p_timestamp);
    IF v_current_state IS DISTINCT FROM 'read' THEN
      v_state_after := 'read'; v_ts_after := p_timestamp; v_upgraded := true;
    END IF;
  ELSIF p_status = 'delivered' THEN
    v_delivered_after := LEAST(COALESCE(v_outbox.delivered_at, p_timestamp), p_timestamp);
    IF v_current_state NOT IN ('read','delivered') OR v_current_state IS NULL THEN
      v_state_after := 'delivered'; v_ts_after := p_timestamp; v_upgraded := true;
    END IF;
  ELSIF p_status = 'sent' THEN
    IF v_current_state IS NULL THEN
      v_state_after := 'sent'; v_ts_after := p_timestamp; v_upgraded := true;
    ELSIF v_current_state = 'sent'
          AND (v_current_ts IS NULL OR p_timestamp > v_current_ts) THEN
      v_ts_after := p_timestamp; v_upgraded := true;
    END IF;
  ELSIF p_status = 'failed' THEN
    v_failed_after := LEAST(COALESCE(v_outbox.provider_failed_at, p_timestamp), p_timestamp);
    IF v_outbox.delivered_at IS NULL AND v_outbox.read_at IS NULL
       AND v_current_state IS DISTINCT FROM 'deleted' THEN
      IF v_current_state IS NULL THEN
        v_state_after := 'failed'; v_ts_after := p_timestamp; v_upgraded := true;
      ELSIF v_current_state = 'sent' THEN
        IF v_current_ts IS NULL OR p_timestamp >= v_current_ts THEN
          v_state_after := 'failed'; v_ts_after := p_timestamp; v_upgraded := true;
        END IF;
      ELSIF v_current_state = 'failed' THEN NULL;
      END IF;
    END IF;
  ELSIF p_status = 'deleted' THEN
    IF v_current_state IS NULL THEN
      v_state_after := 'deleted'; v_ts_after := p_timestamp; v_upgraded := true;
    END IF;
  END IF;

  UPDATE public.comunicacao_outbox
     SET provider_delivery_status = v_state_after,
         provider_status_at       = v_ts_after,
         delivered_at             = v_delivered_after,
         read_at                  = v_read_after,
         provider_failed_at       = v_failed_after,
         updated_at               = now()
   WHERE id = v_outbox.id;

  INSERT INTO public.comunicacao_audit_log (acao, entidade, entity_id, actor_id, after_state)
  VALUES ('whatsapp_receipt','comunicacao_outbox',v_outbox.id,NULL,
    jsonb_build_object('status',p_status,'error_code',v_error_code_norm,'upgraded',v_upgraded));

  RETURN jsonb_build_object('ok',true,'outbox_id',v_outbox.id,
    'status',p_status,'state',v_state_after,'upgraded',v_upgraded);
END$function$

CREATE OR REPLACE FUNCTION public.rpc_register_receivable_payment(p_installment_id uuid, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := platform_private.h15_actor_organization();
  v_inst public.accounts_receivable_installments%ROWTYPE;
  v_amount numeric; v_disc numeric; v_int numeric; v_pen numeric; v_saldo numeric;
  v_pm uuid; v_ba uuid; v_pay_date date; v_notes text;
  v_has_receipt boolean; v_require_receipt boolean;
  v_payment_id uuid; v_idem text; v_fp text; v_existing record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para registrar recebimento.' USING ERRCODE='insufficient_privilege';
  END IF;

  -- H6-001: idempotency_key obrigatoria (fail-closed)
  IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM public.accounts_receivable_installments WHERE id=p_installment_id AND organization_id=v_org) THEN
    RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501';
  END IF;
  IF (p_payload ? 'organization_id' AND NULLIF(p_payload->>'organization_id','')::uuid IS DISTINCT FROM v_org)
     OR (p_payload ? 'tenant_id' AND NULLIF(p_payload->>'tenant_id','')::uuid IS DISTINCT FROM v_org) THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_MISMATCH' USING ERRCODE='42501';
  END IF;
  v_idem := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idem IS NULL OR length(v_idem) < 8 THEN
    RAISE EXCEPTION 'FIN_IDEMPOTENCY_REQUIRED: idempotency_key obrigatória (mín. 8 caracteres).'
      USING ERRCODE='check_violation';
  END IF;

  v_fp := public.fn_h6b_payment_fingerprint('receivable', p_installment_id, p_payload);

  -- lock determinístico por tipo + parcela + chave, ANTES da decisao de replay
  PERFORM pg_advisory_xact_lock(
    hashtextextended('fin_pay:receivable:' || p_installment_id::text || ':' || v_idem, 0));

  SELECT * INTO v_inst FROM public.accounts_receivable_installments
   WHERE id = p_installment_id AND organization_id=v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parcela não encontrada.'; END IF;

  SELECT id, request_fingerprint INTO v_existing FROM public.receivable_payments
   WHERE installment_id = p_installment_id AND idempotency_key = v_idem;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.request_fingerprint IS NOT NULL AND v_existing.request_fingerprint <> v_fp THEN
      RAISE EXCEPTION 'FIN_IDEMPOTENCY_CONFLICT: mesma idempotency_key com payload divergente.'
        USING ERRCODE='check_violation';
    END IF;
    RETURN v_existing.id;
  END IF;

  IF v_inst.status = 'CANCELED' THEN
    RAISE EXCEPTION 'Parcela cancelada.' USING ERRCODE='check_violation';
  END IF;
  IF v_inst.status = 'PAID' THEN
    RAISE EXCEPTION 'Parcela já quitada.' USING ERRCODE='check_violation';
  END IF;

  v_amount   := COALESCE((p_payload->>'amount_received')::numeric, 0);
  v_disc     := COALESCE((p_payload->>'discount_amount')::numeric, 0);
  v_int      := COALESCE((p_payload->>'interest_amount')::numeric, 0);
  v_pen      := COALESCE((p_payload->>'penalty_amount')::numeric, 0);
  v_pm       := NULLIF(p_payload->>'payment_method_id','')::uuid;
  v_ba       := NULLIF(p_payload->>'bank_account_id','')::uuid;
  v_pay_date := COALESCE((p_payload->>'payment_date')::date, (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date);
  v_notes    := NULLIF(p_payload->>'notes','');
  v_has_receipt := COALESCE((p_payload->>'has_receipt')::boolean, false);

  IF v_amount::text IN ('NaN','Infinity','-Infinity') OR v_disc::text IN ('NaN','Infinity','-Infinity') OR v_int::text IN ('NaN','Infinity','-Infinity') OR v_pen::text IN ('NaN','Infinity','-Infinity') OR v_disc < 0 OR v_int < 0 OR v_pen < 0 OR v_amount <> round(v_amount,2) OR v_disc <> round(v_disc,2) OR v_int <> round(v_int,2) OR v_pen <> round(v_pen,2) THEN
 RAISE EXCEPTION 'FIN_INVALID_AMOUNT: valores monetários inválidos.' USING ERRCODE='23514';
 END IF;
 IF v_amount <= 0 THEN
    RAISE EXCEPTION 'Valor inválido.' USING ERRCODE='check_violation';
  END IF;
  IF v_pm IS NULL OR NOT EXISTS (SELECT 1 FROM public.payment_methods WHERE id = v_pm AND active) THEN
    RAISE EXCEPTION 'Forma de pagamento inválida ou inativa.' USING ERRCODE='check_violation';
  END IF;
  IF v_ba IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.bank_accounts WHERE id = v_ba AND active) THEN
    RAISE EXCEPTION 'Conta bancária inválida ou inativa.' USING ERRCODE='check_violation';
  END IF;

  v_saldo := v_inst.original_amount + COALESCE(v_inst.interest_amount,0) + COALESCE(v_inst.penalty_amount,0) - COALESCE(v_inst.discount_amount,0) - COALESCE(v_inst.received_amount,0) + v_int + v_pen - v_disc;
  IF v_amount - v_saldo > 0.005 THEN
    RAISE EXCEPTION 'Valor excede o saldo da parcela (saldo: %).', v_saldo USING ERRCODE='check_violation';
  END IF;

  SELECT require_receipt_on_receivable_payment INTO v_require_receipt
    FROM public.financial_settings LIMIT 1;
  IF COALESCE(v_require_receipt,false) AND NOT v_has_receipt THEN
    RAISE EXCEPTION 'Comprovante de recebimento é obrigatório.' USING ERRCODE='check_violation';
  END IF;

  BEGIN
    INSERT INTO public.receivable_payments (
      organization_id, installment_id, payment_date, amount_received, payment_method_id, bank_account_id,
      discount_amount, interest_amount, penalty_amount, notes, created_by,
      idempotency_key, request_fingerprint
    ) VALUES (
      v_org, p_installment_id, v_pay_date, v_amount, v_pm, v_ba,
      v_disc, v_int, v_pen, v_notes, v_uid, v_idem, v_fp
    ) RETURNING id INTO v_payment_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id, request_fingerprint INTO v_existing FROM public.receivable_payments
     WHERE installment_id = p_installment_id AND idempotency_key = v_idem;
    IF v_existing.request_fingerprint IS NOT NULL AND v_existing.request_fingerprint <> v_fp THEN
      RAISE EXCEPTION 'FIN_IDEMPOTENCY_CONFLICT: mesma idempotency_key com payload divergente.'
        USING ERRCODE='check_violation';
    END IF;
    RETURN v_existing.id;
  END;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('receivable_payments', v_payment_id, 'PAYMENT_REGISTERED',
    jsonb_build_object('installment_id', p_installment_id, 'amount', v_amount,
      'payment_method_id', v_pm, 'bank_account_id', v_ba, 'payment_date', v_pay_date,
      'idempotency_key', v_idem, 'request_fingerprint', v_fp), v_uid);

  RETURN v_payment_id;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_registrar_primeira_resposta_alerta(p_alerta_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alerta record;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
  END IF;
  IF NOT public.can_user_access_alerta(p_alerta_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden');
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'alerta_nao_encontrado');
  END IF;

  IF v_alerta.primeira_resposta_em IS NULL THEN
    UPDATE public.alertas_operacionais
      SET primeira_resposta_em = now()
      WHERE id = p_alerta_id;

    INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, criado_por, responsavel_id)
      VALUES (p_alerta_id, v_alerta.sla_config_id, 'primeira_resposta_registrada', auth.uid(), auth.uid());

    IF v_alerta.sla_primeira_resposta_em IS NOT NULL AND now() > v_alerta.sla_primeira_resposta_em THEN
      INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, criado_por)
        VALUES (p_alerta_id, v_alerta.sla_config_id, 'sla_resposta_vencido', auth.uid());
    END IF;

    BEGIN
      INSERT INTO public.alertas_acoes (alerta_id, user_id, acao, observacao)
        VALUES (p_alerta_id, auth.uid(), 'primeira_resposta', 'Primeira resposta registrada');
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  PERFORM public.rpc_recalcular_prioridade_alerta(p_alerta_id);
  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.assert_b2b_partner_scope(_uid uuid, _partner uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s record;
BEGIN
  IF _uid IS NULL OR auth.uid() IS NULL OR _uid <> auth.uid() THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE='42501';
  END IF;
  IF _partner IS NULL OR NOT EXISTS (SELECT 1 FROM public.partner_accounts pa
       WHERE pa.id = _partner AND pa.ativo = true AND pa.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'partner_not_found' USING ERRCODE='42501';
  END IF;
  IF public.is_platform_superadmin(_uid) THEN RETURN; END IF;
  IF public.has_role(_uid,'parceiro_b2b_tecnico'::app_role) THEN
    RAISE EXCEPTION 'forbidden_financial_terms' USING ERRCODE='42501';
  END IF;
  SELECT * INTO s FROM platform_private.b2b_actor_scope(_uid);
  IF NOT s.profile_ok THEN RAISE EXCEPTION 'inactive_scope' USING ERRCODE='42501'; END IF;
  IF s.org_partner IS DISTINCT FROM _partner OR NOT s.partner_valid THEN
    RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
  END IF;
  IF public.has_role(_uid,'parceiro_b2b'::app_role) THEN
    IF s.user_partner_count <> 1 OR s.user_partner IS DISTINCT FROM _partner THEN
      RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
    END IF;
    RETURN;
  END IF;
  IF NOT (public.has_role(_uid,'administrador'::app_role) OR public.has_role(_uid,'financeiro'::app_role)
          OR public.has_role(_uid,'gestor_comercial'::app_role)) THEN
    RAISE EXCEPTION 'forbidden_role' USING ERRCODE='42501';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_document_register(p_dossier_id uuid, p_doc_type text, p_title text, p_storage_path text, p_content_sha256 text, p_issuer text DEFAULT NULL::text, p_issued_at date DEFAULT NULL::date, p_valid_until date DEFAULT NULL::date, p_source_key text DEFAULT NULL::text, p_source_url text DEFAULT NULL::text, p_consulted_at date DEFAULT NULL::date, p_doc_version text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'storage'
AS $function$
DECLARE
  v_id uuid; v_status text; v_source uuid;
  v_owner uuid; v_metadata jsonb; v_found boolean;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT status INTO v_status FROM public.microorganism_regulatory_dossiers
   WHERE id = p_dossier_id AND deleted_at IS NULL FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_FOUND' USING ERRCODE = '22023'; END IF;
  IF v_status NOT IN ('DRAFT', 'PENDING_REVIEW') THEN
    RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_EDITABLE' USING ERRCODE = '55006';
  END IF;

  IF NOT public.fn_regulatory_storage_path_ok(p_storage_path) THEN
    RAISE EXCEPTION 'REGULATORY_STORAGE_PATH_INVALID'
      USING ERRCODE = '22023',
            HINT = 'Use dossiers/<dossier_id>/<uuid>/<arquivo>.';
  END IF;
  IF public.fn_regulatory_storage_dossier_id(p_storage_path) <> p_dossier_id THEN
    RAISE EXCEPTION 'REGULATORY_STORAGE_PATH_OUT_OF_SCOPE' USING ERRCODE = '42501';
  END IF;

  -- O objeto precisa existir no bucket privado com dono compatível.
  -- Nenhum conteúdo é lido nem exposto: apenas metadados de controle.
  SELECT true, o.owner, o.metadata INTO v_found, v_owner, v_metadata
    FROM storage.objects o
   WHERE o.bucket_id = 'fiscal-regulatorio' AND o.name = p_storage_path;
  IF NOT coalesce(v_found, false) THEN
    RAISE EXCEPTION 'REGULATORY_STORAGE_OBJECT_MISSING' USING ERRCODE = '22023';
  END IF;
  IF v_owner IS NOT NULL AND NOT public.fn_regulatory_can_prepare(v_owner) THEN
    RAISE EXCEPTION 'REGULATORY_STORAGE_OWNER_MISMATCH' USING ERRCODE = '42501';
  END IF;
  IF coalesce((v_metadata ->> 'size')::bigint, 0) <= 0 THEN
    RAISE EXCEPTION 'REGULATORY_STORAGE_OBJECT_EMPTY' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_source FROM public.fiscal_official_sources
   WHERE source_key = p_source_key AND is_active;

  INSERT INTO public.microorganism_regulatory_documents
    (dossier_id, doc_type, title, storage_path, content_sha256, issuer, issued_at, valid_until,
     source_id, source_url, consulted_at, doc_version, uploaded_by)
  VALUES (p_dossier_id, p_doc_type, p_title, p_storage_path, lower(p_content_sha256),
          p_issuer, p_issued_at, p_valid_until, v_source, p_source_url, p_consulted_at,
          p_doc_version, auth.uid())
  RETURNING id INTO v_id;

  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_document_soft_delete(p_document_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_doc public.microorganism_regulatory_documents; v_status text;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION 'REGULATORY_JUSTIFICATION_REQUIRED' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_doc FROM public.microorganism_regulatory_documents
   WHERE id = p_document_id FOR UPDATE;
  IF v_doc.id IS NULL THEN RAISE EXCEPTION 'REGULATORY_DOCUMENT_NOT_FOUND' USING ERRCODE = '22023'; END IF;
  IF v_doc.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('document_id', v_doc.id, 'already_deleted', true);
  END IF;

  SELECT status INTO v_status FROM public.microorganism_regulatory_dossiers
   WHERE id = v_doc.dossier_id FOR UPDATE;
  IF v_status NOT IN ('DRAFT', 'PENDING_REVIEW') THEN
    RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_EDITABLE' USING ERRCODE = '55006';
  END IF;
  IF EXISTS (SELECT 1 FROM public.microorganism_regulatory_publication_snapshots
              WHERE dossier_id = v_doc.dossier_id) THEN
    RAISE EXCEPTION 'REGULATORY_PUBLISHED_IMMUTABLE' USING ERRCODE = '55006';
  END IF;

  UPDATE public.microorganism_regulatory_documents
     SET deleted_at = now(), deleted_by = auth.uid()
   WHERE id = p_document_id;

  INSERT INTO public.regulatory_storage_cleanup_queue
    (document_id, dossier_id, storage_bucket, storage_path, reason, requested_by)
  VALUES (v_doc.id, v_doc.dossier_id, v_doc.storage_bucket, v_doc.storage_path, p_reason, auth.uid())
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object(
    'document_id', v_doc.id,
    'storage_bucket', v_doc.storage_bucket,
    'storage_path', v_doc.storage_path,
    'cleanup_required', true);
END $function$

CREATE OR REPLACE FUNCTION public.saas_plan_version_no_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.status IN ('PUBLISHED','ARCHIVED') THEN
    IF OLD.status='PUBLISHED' AND NEW.status='ARCHIVED'
       AND platform_private.has_ticket('saas_plan_version_archive',OLD.plan_id) THEN RETURN NEW; END IF;
    -- Única alteração permitida em versão publicada: encerrar a vigência aberta
    -- desta versão exata, pela publicação da sucessora, sem tocar em outro campo.
    IF OLD.status='PUBLISHED' AND NEW.status='PUBLISHED'
       AND OLD.effective_to IS NULL AND NEW.effective_to IS NOT NULL
       AND NEW.effective_to > OLD.effective_from
       AND (to_jsonb(NEW) - 'effective_to' - 'updated_at') = (to_jsonb(OLD) - 'effective_to' - 'updated_at')
       AND platform_private.has_ticket('saas_plan_version_supersede',OLD.id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'saas_version_immutable: versão publicada não pode ser alterada';
  END IF;
  IF OLD.status='DRAFT' AND NOT platform_private.has_ticket('saas_plan_version_write',OLD.plan_id) THEN
    RAISE EXCEPTION 'platform_forbidden: rascunho alterado fora do fluxo autorizado' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_dossier_ensure_draft(p_microorganism_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid; v_next int;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.microrganismos WHERE id = p_microorganism_id) THEN
    RAISE EXCEPTION 'REGULATORY_MICROORGANISM_NOT_FOUND' USING ERRCODE='22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('regulatory_dossier:'||p_microorganism_id::text, 0));

  SELECT id INTO v_id FROM public.microorganism_regulatory_dossiers
   WHERE microorganism_id = p_microorganism_id
     AND status IN ('DRAFT','PENDING_REVIEW') AND deleted_at IS NULL
   LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  SELECT coalesce(max(version),0)+1 INTO v_next
    FROM public.microorganism_regulatory_dossiers WHERE microorganism_id = p_microorganism_id;

  INSERT INTO public.microorganism_regulatory_dossiers
    (microorganism_id, version, status, created_by, updated_by)
  VALUES (p_microorganism_id, v_next, 'DRAFT', auth.uid(), auth.uid())
  RETURNING id INTO v_id;

  INSERT INTO public.microorganism_regulatory_checklist (dossier_id, item_key, state)
  SELECT v_id, k, 'PENDING' FROM unnest(ARRAY[
    'FINALIDADE_REGULATORIA','CEPA','FORMULACAO','GARANTIA_ROTULO','REGISTRO_MAPA',
    'TITULAR_FABRICANTE','NCM_CEST_TIPI','GTIN','UNIDADE_CONVERSAO','ORIGEM',
    'CFOP','TRIBUTACAO']) k
  ON CONFLICT (dossier_id, item_key) DO NOTHING;

  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_dossier_publish(p_dossier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d public.microorganism_regulatory_dossiers;
  v_cand public.microorganism_ncm_candidates;
  v_pending int; v_docs int; v_distinct int; v_snapshot jsonb; v_sha text;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO d FROM public.microorganism_regulatory_dossiers
   WHERE id = p_dossier_id AND deleted_at IS NULL FOR UPDATE;
  IF d.id IS NULL THEN RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_FOUND' USING ERRCODE = '22023'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('regulatory_publish:' || d.microorganism_id::text, 0));

  -- Idempotência sob concorrência: re-leitura após o lock
  SELECT * INTO d FROM public.microorganism_regulatory_dossiers
   WHERE id = p_dossier_id AND deleted_at IS NULL FOR UPDATE;
  IF d.status = 'VALIDATED' THEN
    SELECT snapshot_sha256 INTO v_sha
      FROM public.microorganism_regulatory_publication_snapshots
     WHERE dossier_id = p_dossier_id ORDER BY version DESC LIMIT 1;
    RETURN jsonb_build_object('dossier_id', p_dossier_id, 'status', d.status,
                              'snapshot_sha256', v_sha, 'idempotent', true);
  END IF;
  IF d.status <> 'PENDING_REVIEW' THEN
    RAISE EXCEPTION 'REGULATORY_INVALID_TRANSITION' USING ERRCODE = '55006';
  END IF;

  IF d.technical_review_status <> 'APPROVED'
     OR d.regulatory_review_status <> 'APPROVED'
     OR d.fiscal_review_status <> 'APPROVED' THEN
    RAISE EXCEPTION 'REGULATORY_APPROVALS_INCOMPLETE' USING ERRCODE = '55006';
  END IF;

  SELECT count(DISTINCT x) INTO v_distinct
    FROM unnest(ARRAY[d.technical_review_by, d.regulatory_review_by, d.fiscal_review_by]) AS x;
  IF v_distinct < 3 AND NOT d.sod_override_active THEN
    RAISE EXCEPTION 'REGULATORY_SEGREGATION_OF_DUTIES'
      USING ERRCODE = '42501',
            HINT = 'Publicacao exige tres aprovadores distintos ou override emergencial auditado.';
  END IF;

  SELECT count(*) INTO v_pending FROM public.microorganism_regulatory_checklist
   WHERE dossier_id = p_dossier_id AND state = 'PENDING';
  IF v_pending > 0 THEN
    RAISE EXCEPTION 'REGULATORY_CHECKLIST_INCOMPLETE: % item(ns) pendente(s)', v_pending USING ERRCODE = '55006';
  END IF;

  SELECT count(*) INTO v_docs FROM public.microorganism_regulatory_documents
   WHERE dossier_id = p_dossier_id AND deleted_at IS NULL AND doc_type IN ('ROTULO', 'LAUDO');
  IF v_docs = 0 THEN
    RAISE EXCEPTION 'REGULATORY_EVIDENCE_DOCUMENT_MISSING' USING ERRCODE = '55006';
  END IF;

  SELECT * INTO v_cand FROM public.microorganism_ncm_candidates
   WHERE dossier_id = p_dossier_id AND status = 'APPROVED' FOR UPDATE;
  IF v_cand.id IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_NCM_NOT_APPROVED' USING ERRCODE = '55006';
  END IF;
  IF v_cand.source_id IS NULL OR v_cand.table_reference_date IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_NCM_OFFICIAL_SOURCE_REQUIRED' USING ERRCODE = '55006';
  END IF;

  IF EXISTS (SELECT 1 FROM public.microorganism_regulatory_presentations
              WHERE dossier_id = p_dossier_id AND (NOT units_confirmed OR NOT gtin_confirmed)) THEN
    RAISE EXCEPTION 'REGULATORY_PRESENTATION_NOT_CONFIRMED' USING ERRCODE = '55006';
  END IF;

  PERFORM set_config('app.regulatory_formal_op', 'on', true);

  UPDATE public.microorganism_regulatory_dossiers
     SET status = 'VALIDATED',
         published_ncm = v_cand.ncm,
         published_cest = v_cand.cest,
         published_ncm_candidate_id = v_cand.id,
         published_at = now(), published_by = auth.uid(),
         effective_from = coalesce(effective_from, current_date),
         updated_by = auth.uid()
   WHERE id = p_dossier_id RETURNING * INTO d;

  v_snapshot := jsonb_build_object(
    'dossier', to_jsonb(d),
    'presentations', coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.volume_ml)
                               FROM public.microorganism_regulatory_presentations p
                               WHERE p.dossier_id = p_dossier_id), '[]'::jsonb),
    'documents', coalesce((SELECT jsonb_agg(jsonb_build_object(
                              'id', x.id, 'doc_type', x.doc_type, 'title', x.title,
                              'storage_path', x.storage_path,
                              'content_sha256', x.content_sha256, 'issued_at', x.issued_at,
                              'valid_until', x.valid_until, 'source_url', x.source_url) ORDER BY x.id)
                           FROM public.microorganism_regulatory_documents x
                           WHERE x.dossier_id = p_dossier_id AND x.deleted_at IS NULL), '[]'::jsonb),
    'checklist', coalesce((SELECT jsonb_agg(jsonb_build_object(
                              'item_key', c.item_key, 'state', c.state, 'justification', c.justification)
                              ORDER BY c.item_key)
                           FROM public.microorganism_regulatory_checklist c
                           WHERE c.dossier_id = p_dossier_id), '[]'::jsonb),
    'ncm_candidate', to_jsonb(v_cand));
  v_sha := encode(extensions.digest(v_snapshot::text, 'sha256'), 'hex');

  INSERT INTO public.microorganism_regulatory_publication_snapshots
    (dossier_id, microorganism_id, version, snapshot, snapshot_sha256, published_by)
  VALUES (p_dossier_id, d.microorganism_id, d.version, v_snapshot, v_sha, auth.uid());

  PERFORM set_config('app.regulatory_formal_op', '', true);
  RETURN jsonb_build_object('dossier_id', p_dossier_id, 'status', d.status,
                            'snapshot_sha256', v_sha, 'idempotent', false);
END $function$

CREATE OR REPLACE FUNCTION public.platform_publish_plan_version_draft(_draft_id uuid, _reason text, _idempotency_key uuid, _confirmation text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v public.saas_plan_versions%ROWTYPE;
  prev public.saas_plan_versions%ROWTYPE;
  v_check jsonb; v_reason text; v_open int; v_prev_new jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _confirmation IS DISTINCT FROM 'PUBLICAR' THEN
    RAISE EXCEPTION 'platform_invalid: confirmação inválida' USING ERRCODE='22023';
  END IF;
  IF _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023';
  END IF;
  v_reason := platform_private.normalize_commercial_reason(_reason);

  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_draft_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: rascunho inexistente' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('saas_plan_version:' || v.plan_id::text,0));
  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_draft_id FOR UPDATE;

  IF v.status='PUBLISHED' AND v.publish_key=_idempotency_key THEN
    IF v.publication_reason IS DISTINCT FROM v_reason THEN
      RAISE EXCEPTION 'platform_conflict: mesma chave idempotente com motivo divergente' USING ERRCODE='40001';
    END IF;
    RETURN v.id;
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.publish_key=_idempotency_key AND x.id<>v.id) THEN
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada em outra publicação' USING ERRCODE='40001';
  END IF;
  IF v.status <> 'DRAFT' THEN RAISE EXCEPTION 'platform_conflict: versão não está em rascunho' USING ERRCODE='40001'; END IF;

  v_check := public.platform_validate_plan_version_draft(v.id);
  IF NOT coalesce((v_check->>'complete')::boolean,false) OR NOT coalesce((v_check->>'valid')::boolean,false) THEN
    RAISE EXCEPTION 'platform_invalid: rascunho incompleto ou inválido' USING ERRCODE='22023';
  END IF;

  SELECT count(*) INTO v_open FROM public.saas_plan_versions
   WHERE plan_id=v.plan_id AND status='PUBLISHED' AND effective_to IS NULL;
  IF v_open > 1 THEN
    RAISE EXCEPTION 'platform_conflict: mais de uma versão vigente para o plano' USING ERRCODE='40001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.plan_id=v.plan_id AND x.status='PUBLISHED'
              AND x.effective_from >= v.effective_from) THEN
    RAISE EXCEPTION 'platform_conflict: início da vigência deve ser posterior ao da versão publicada anterior' USING ERRCODE='40001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.plan_id=v.plan_id AND x.status='PUBLISHED'
              AND x.effective_to IS NOT NULL AND x.effective_to > v.effective_from) THEN
    RAISE EXCEPTION 'platform_conflict: vigência sobreposta' USING ERRCODE='40001';
  END IF;

  SELECT * INTO prev FROM public.saas_plan_versions
   WHERE plan_id=v.plan_id AND status='PUBLISHED' AND effective_to IS NULL FOR UPDATE;
  IF FOUND THEN
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_supersede',prev.id);
    UPDATE public.saas_plan_versions SET effective_to = v.effective_from WHERE id = prev.id;
    SELECT to_jsonb(x) INTO v_prev_new FROM public.saas_plan_versions x WHERE x.id=prev.id;
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v.plan_id);
    INSERT INTO public.saas_plan_version_audit(plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key)
    VALUES(prev.id,'superseded',to_jsonb(prev),v_prev_new || jsonb_build_object('superseded_by',v.id),
           v_reason,'platform_rpc',auth.uid(),_idempotency_key);
  END IF;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v.plan_id);
  UPDATE public.saas_plan_versions SET status='PUBLISHED',published_at=now(),publication_reason=v_reason,
    publish_key=_idempotency_key WHERE id=v.id;
  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v.plan_id);
  INSERT INTO public.saas_plan_version_audit(plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key)
  VALUES(v.id,'published',to_jsonb(v),
         (SELECT to_jsonb(x) FROM public.saas_plan_versions x WHERE x.id=v.id) || jsonb_build_object('supersedes',prev.id),
         v_reason,'platform_rpc',auth.uid(),_idempotency_key);
  RETURN v.id;
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_ncm_candidate_decide(p_candidate_id uuid, p_approve boolean, p_reason text, p_official_description text DEFAULT NULL::text, p_table_version text DEFAULT NULL::text, p_table_reference_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_cand public.microorganism_ncm_candidates; v_status text; v_row public.microorganism_ncm_candidates;
BEGIN
  IF NOT public.fn_regulatory_can_approve('FISCAL') THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF nullif(btrim(coalesce(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_JUSTIFICATION_REQUIRED' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_cand FROM public.microorganism_ncm_candidates
   WHERE id = p_candidate_id FOR UPDATE;
  IF v_cand.id IS NULL THEN RAISE EXCEPTION 'REGULATORY_CANDIDATE_NOT_FOUND' USING ERRCODE = '22023'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('regulatory_dossier_ncm:' || v_cand.dossier_id::text, 0));

  SELECT status INTO v_status FROM public.microorganism_regulatory_dossiers
   WHERE id = v_cand.dossier_id FOR UPDATE;
  IF v_status NOT IN ('DRAFT', 'PENDING_REVIEW') THEN
    RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_EDITABLE' USING ERRCODE = '55006';
  END IF;

  IF p_approve THEN
    -- B3: confianca condicional NAO pode ser aprovada. Exige reclassificacao
    -- explicita (HIGH/MEDIUM/LOW) por rpc_regulatory_ncm_candidate_add ou
    -- decisao tecnica registrada antes da aprovacao fiscal.
    IF upper(btrim(coalesce(v_cand.confidence, ''))) = 'CONDITIONAL' THEN
      RAISE EXCEPTION 'REGULATORY_NCM_CONDITIONAL_BLOCKED'
        USING ERRCODE = '55006',
              HINT = 'Candidato com confianca CONDITIONAL: reclassifique com fundamentacao oficial antes de aprovar.';
    END IF;

    IF v_cand.source_id IS NULL THEN
      RAISE EXCEPTION 'REGULATORY_NCM_OFFICIAL_SOURCE_REQUIRED'
        USING ERRCODE = '22023',
              HINT = 'URL avulsa nao basta: cadastre a fonte oficial em fiscal_official_sources.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.fiscal_official_sources
                    WHERE id = v_cand.source_id AND is_active) THEN
      RAISE EXCEPTION 'REGULATORY_NCM_SOURCE_INACTIVE' USING ERRCODE = '22023';
    END IF;
    IF length(btrim(coalesce(p_official_description, ''))) < 10
       OR nullif(btrim(coalesce(p_table_version, '')), '') IS NULL
       OR p_table_reference_date IS NULL THEN
      RAISE EXCEPTION 'REGULATORY_NCM_OFFICIAL_DESCRIPTION_REQUIRED'
        USING ERRCODE = '22023',
              HINT = 'Informe a descricao oficial do NCM e a versao/data da tabela consultada.';
    END IF;
  END IF;

  UPDATE public.microorganism_ncm_candidates
     SET status = CASE WHEN p_approve THEN 'APPROVED' ELSE 'REJECTED' END,
         decided_by = auth.uid(), decided_at = now(), decision_reason = p_reason,
         official_description = CASE WHEN p_approve THEN p_official_description ELSE official_description END,
         table_version = CASE WHEN p_approve THEN p_table_version ELSE table_version END,
         table_reference_date = CASE WHEN p_approve THEN p_table_reference_date ELSE table_reference_date END
   WHERE id = p_candidate_id
  RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_presentation_upsert(p_dossier_id uuid, p_volume_ml integer, p_patch jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid; v_status text; v_units boolean; v_gtin_conf boolean;
  v_absent boolean; v_gtin text; v_absent_reason text;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  SELECT status INTO v_status FROM public.microorganism_regulatory_dossiers
   WHERE id = p_dossier_id AND deleted_at IS NULL FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_FOUND' USING ERRCODE = '22023'; END IF;
  IF v_status NOT IN ('DRAFT', 'PENDING_REVIEW') THEN
    RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_EDITABLE' USING ERRCODE = '55006';
  END IF;

  v_units         := coalesce((p_patch ->> 'units_confirmed')::boolean, false);
  v_gtin_conf     := coalesce((p_patch ->> 'gtin_confirmed')::boolean, false);
  v_absent        := coalesce((p_patch ->> 'gtin_absent')::boolean, false);
  v_gtin          := nullif(btrim(coalesce(p_patch ->> 'gtin', '')), '');
  v_absent_reason := nullif(btrim(coalesce(p_patch ->> 'gtin_absent_reason', '')), '');

  IF v_absent AND v_gtin IS NOT NULL THEN
    RAISE EXCEPTION 'REGULATORY_GTIN_MUTUALLY_EXCLUSIVE' USING ERRCODE = '22023';
  END IF;
  IF v_absent AND (v_absent_reason IS NULL OR length(v_absent_reason) < 20) THEN
    RAISE EXCEPTION 'REGULATORY_GTIN_ABSENCE_JUSTIFICATION_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF v_gtin IS NOT NULL AND NOT public.fn_gtin_is_valid(v_gtin) THEN
    RAISE EXCEPTION 'REGULATORY_GTIN_CHECK_DIGIT_INVALID' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.microorganism_regulatory_presentations AS p
    (dossier_id, volume_ml, label, catalog_volume_id, created_by, updated_by)
  VALUES (p_dossier_id, p_volume_ml,
          coalesce(p_patch ->> 'label', (p_volume_ml / 1000.0)::text || ' L'),
          nullif(p_patch ->> 'catalog_volume_id', '')::uuid, auth.uid(), auth.uid())
  ON CONFLICT (dossier_id, volume_ml) DO UPDATE SET
    label = coalesce(EXCLUDED.label, p.label),
    updated_by = auth.uid()
  RETURNING p.id INTO v_id;

  UPDATE public.microorganism_regulatory_presentations SET
    commercial_unit    = coalesce(p_patch ->> 'commercial_unit', commercial_unit),
    taxable_unit       = coalesce(p_patch ->> 'taxable_unit', taxable_unit),
    conversion_factor  = coalesce((p_patch ->> 'conversion_factor')::numeric, conversion_factor),
    gtin               = CASE WHEN v_absent THEN NULL ELSE coalesce(v_gtin, gtin) END,
    gtin_absent        = v_absent,
    gtin_absent_reason = CASE WHEN v_absent THEN v_absent_reason ELSE NULL END,
    gtin_absent_by     = CASE WHEN v_absent THEN auth.uid() ELSE NULL END,
    gtin_absent_at     = CASE WHEN v_absent THEN now() ELSE NULL END,
    units_confirmed    = v_units,
    units_confirmed_by = CASE WHEN v_units THEN auth.uid() ELSE NULL END,
    units_confirmed_at = CASE WHEN v_units THEN now() ELSE NULL END,
    gtin_confirmed     = v_gtin_conf,
    gtin_confirmed_by  = CASE WHEN v_gtin_conf THEN auth.uid() ELSE NULL END,
    gtin_confirmed_at  = CASE WHEN v_gtin_conf THEN now() ELSE NULL END,
    updated_by = auth.uid()
  WHERE id = v_id;

  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_review_decide(p_dossier_id uuid, p_layer text, p_decision text, p_justification text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d public.microorganism_regulatory_dossiers;
  v_row public.microorganism_regulatory_dossiers;
  v_uid uuid := auth.uid();
BEGIN
  IF p_layer NOT IN ('TECHNICAL', 'REGULATORY', 'FISCAL') THEN
    RAISE EXCEPTION 'REGULATORY_INVALID_LAYER' USING ERRCODE = '22023';
  END IF;
  IF p_decision NOT IN ('APPROVED', 'REJECTED') THEN
    RAISE EXCEPTION 'REGULATORY_INVALID_DECISION' USING ERRCODE = '22023';
  END IF;
  IF NOT public.fn_regulatory_can_approve(p_layer) THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF nullif(btrim(coalesce(p_justification, '')), '') IS NULL THEN
    RAISE EXCEPTION 'REGULATORY_JUSTIFICATION_REQUIRED' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO d FROM public.microorganism_regulatory_dossiers
   WHERE id = p_dossier_id AND deleted_at IS NULL FOR UPDATE;
  IF d.id IS NULL THEN RAISE EXCEPTION 'REGULATORY_DOSSIER_NOT_FOUND' USING ERRCODE = '22023'; END IF;
  IF d.status <> 'PENDING_REVIEW' THEN
    RAISE EXCEPTION 'REGULATORY_INVALID_TRANSITION' USING ERRCODE = '55006';
  END IF;

  -- Segregação: a mesma identidade não acumula camadas no mesmo dossiê,
  -- salvo override emergencial de administrador (auditado e sinalizado).
  IF p_decision = 'APPROVED' AND NOT d.sod_override_active THEN
    IF (p_layer <> 'TECHNICAL'  AND d.technical_review_status  = 'APPROVED' AND d.technical_review_by  = v_uid)
    OR (p_layer <> 'REGULATORY' AND d.regulatory_review_status = 'APPROVED' AND d.regulatory_review_by = v_uid)
    OR (p_layer <> 'FISCAL'     AND d.fiscal_review_status     = 'APPROVED' AND d.fiscal_review_by     = v_uid) THEN
      RAISE EXCEPTION 'REGULATORY_SEGREGATION_OF_DUTIES'
        USING ERRCODE = '42501',
              HINT = 'A mesma pessoa nao pode aprovar mais de uma camada do mesmo dossie. Em emergencia use rpc_regulatory_sod_override (administrador, justificativa forte, auditada).';
    END IF;
  END IF;

  UPDATE public.microorganism_regulatory_dossiers SET
    technical_review_status  = CASE WHEN p_layer = 'TECHNICAL' THEN p_decision ELSE technical_review_status END,
    technical_review_by      = CASE WHEN p_layer = 'TECHNICAL' THEN v_uid ELSE technical_review_by END,
    technical_review_at      = CASE WHEN p_layer = 'TECHNICAL' THEN now() ELSE technical_review_at END,
    technical_review_notes   = CASE WHEN p_layer = 'TECHNICAL' THEN p_justification ELSE technical_review_notes END,
    regulatory_review_status = CASE WHEN p_layer = 'REGULATORY' THEN p_decision ELSE regulatory_review_status END,
    regulatory_review_by     = CASE WHEN p_layer = 'REGULATORY' THEN v_uid ELSE regulatory_review_by END,
    regulatory_review_at     = CASE WHEN p_layer = 'REGULATORY' THEN now() ELSE regulatory_review_at END,
    regulatory_review_notes  = CASE WHEN p_layer = 'REGULATORY' THEN p_justification ELSE regulatory_review_notes END,
    fiscal_review_status     = CASE WHEN p_layer = 'FISCAL' THEN p_decision ELSE fiscal_review_status END,
    fiscal_review_by         = CASE WHEN p_layer = 'FISCAL' THEN v_uid ELSE fiscal_review_by END,
    fiscal_review_at         = CASE WHEN p_layer = 'FISCAL' THEN now() ELSE fiscal_review_at END,
    fiscal_review_notes      = CASE WHEN p_layer = 'FISCAL' THEN p_justification ELSE fiscal_review_notes END,
    -- Rejeição nunca publica: dossiê volta para DRAFT
    status = CASE WHEN p_decision = 'REJECTED' THEN 'DRAFT' ELSE status END,
    updated_by = v_uid
  WHERE id = p_dossier_id RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_regulatory_storage_cleanup_confirm(p_document_id uuid, p_success boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'storage'
AS $function$
DECLARE v_row public.regulatory_storage_cleanup_queue; v_exists boolean; v_state text;
BEGIN
  IF NOT public.fn_regulatory_can_prepare() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM public.regulatory_storage_cleanup_queue
   WHERE document_id = p_document_id AND state = 'PENDING' FOR UPDATE;
  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('document_id', p_document_id, 'pending', false);
  END IF;

  SELECT EXISTS (SELECT 1 FROM storage.objects o
                  WHERE o.bucket_id = v_row.storage_bucket AND o.name = v_row.storage_path)
    INTO v_exists;

  v_state := CASE WHEN p_success AND NOT v_exists THEN 'DONE' ELSE 'FAILED' END;

  UPDATE public.regulatory_storage_cleanup_queue
     SET state = v_state, confirmed_by = auth.uid(), confirmed_at = now()
   WHERE id = v_row.id;

  RETURN jsonb_build_object('document_id', p_document_id,
                            'object_still_present', v_exists, 'state', v_state);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_remove_visit_technician(p_registro_id uuid, p_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_has_open_cycle boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_registro_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'parametros_obrigatorios' USING ERRCODE='22023';
  END IF;
  IF NOT public.can_manage_technical_visit(v_uid, p_registro_id) THEN
    RAISE EXCEPTION 'forbidden_gestao_equipe' USING ERRCODE='42501';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.visitas_checkin c
    WHERE c.registro_consultor_id = p_registro_id
      AND c.consultor_id = p_user_id
      AND c.tipo_checkin <> 'checkout'::public.tipo_checkin
      AND NOT EXISTS (
        SELECT 1 FROM public.visitas_checkin c2
        WHERE c2.registro_consultor_id = c.registro_consultor_id
          AND c2.consultor_id = c.consultor_id
          AND c2.tipo_checkin = 'checkout'::public.tipo_checkin
          AND c2.data_hora_checkin > c.data_hora_checkin
      )
  ) INTO v_has_open_cycle;

  IF v_has_open_cycle THEN
    RAISE EXCEPTION 'remocao_bloqueada_presenca_ativa' USING ERRCODE='22023';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason,'')), '') IS NULL THEN
    RAISE EXCEPTION 'motivo_remocao_obrigatorio' USING ERRCODE='22023';
  END IF;

  UPDATE public.technical_visit_assignments
     SET is_active = false,
         removed_at = now(),
         removal_reason = btrim(p_reason),
         updated_at = now()
   WHERE registro_consultor_id = p_registro_id
     AND user_id = p_user_id
     AND is_active = true
   RETURNING id INTO v_id;

  IF v_id IS NULL THEN RAISE EXCEPTION 'atribuicao_inexistente' USING ERRCODE='22023'; END IF;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, v_uid, 'tecnico_removido',
          'Técnico ' || p_user_id::text || ' removido — motivo: ' || btrim(p_reason));

  RETURN jsonb_build_object('id', v_id, 'removed', true);
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_reprovar_visita(p_registro_id uuid, p_expected_version integer, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_new_version integer;
BEGIN
  IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
    RAISE EXCEPTION 'motivo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, true);
  IF v_reg.status::text <> 'enviado_aprovacao' THEN
    RAISE EXCEPTION 'status_invalido' USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.registros_consultor
     SET status = 'reprovado', version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
  RETURNING version INTO v_new_version;
  INSERT INTO public.aprovacoes_tecnicas
    (registro_consultor_id, status_aprovacao, comentario_gestor, aprovado_por, data_aprovacao)
  VALUES (p_registro_id, 'reprovado', p_motivo, auth.uid(), now());
  INSERT INTO public.registros_consultor_status_log
    (registro_consultor_id, status_anterior, status_novo, motivo, changed_by, changed_at)
  VALUES (p_registro_id, v_reg.status::text, 'reprovado', p_motivo, auth.uid(), now());
  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, auth.uid(), 'recomendacao_reprovada', 'Visita reprovada. Motivo: ' || p_motivo);
  RETURN jsonb_build_object('ok', true, 'version', v_new_version, 'status', 'reprovado');
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_reservar_embalagem_entrega(p_embalagem_id uuid, p_entrega_id uuid, p_entrega_item_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_st text; v_val date; v_ent_st text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(p_embalagem_id) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  SELECT status, validade_em INTO v_st, v_val FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF v_st IS NULL THEN RAISE EXCEPTION 'embalagem inexistente'; END IF;
  IF v_st <> 'em_estoque' THEN RAISE EXCEPTION 'embalagem não está em estoque (status=%)', v_st; END IF;
  IF v_val IS NOT NULL AND v_val < CURRENT_DATE THEN RAISE EXCEPTION 'embalagem vencida'; END IF;
  SELECT status::text INTO v_ent_st FROM public.entregas WHERE id = p_entrega_id;
  IF v_ent_st IS NULL THEN RAISE EXCEPTION 'entrega inexistente'; END IF;
  IF v_ent_st = 'cancelada' THEN RAISE EXCEPTION 'entrega cancelada'; END IF;
  UPDATE public.estoque_embalagens
     SET status='reservado', entrega_id=p_entrega_id, entrega_item_id=p_entrega_item_id,
         reservado_em=now(), reservado_por=v_uid
   WHERE id = p_embalagem_id;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_anterior, status_novo, entrega_id, entrega_item_id, user_id)
    VALUES (p_embalagem_id, 'reserva_entrega', v_st, 'reservado', p_entrega_id, p_entrega_item_id, v_uid);
  PERFORM public.rpc_recalcular_separacao_entrega(p_entrega_id);
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
    VALUES ('estoque_embalagem', p_embalagem_id, 'EMB_RESERVED', v_uid, jsonb_build_object('entrega_id', p_entrega_id));
  RETURN jsonb_build_object('success', true);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_salvar_campo_visita(p_registro_consultor_id uuid, p_client_uuid uuid, p_payload jsonb, p_versao integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_existing public.visitas_campo;
  v_result public.visitas_campo;
  v_talhao uuid; v_cultura uuid; v_area numeric; v_estande numeric;
  v_fase text; v_unif text; v_obs text; v_extras jsonb;
  v_org uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_registro_consultor_id IS NULL THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;
  -- CAS mandatory. 0 = "no row yet" (initial insert contract); NULL/negative never matches.
  IF p_versao IS NULL OR p_versao < 0 THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  -- Fast denial; same message for inexistent and foreign visits (no existence oracle).
  IF NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- Payload shape (after authorization, before any lock).
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'payload_invalido' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_talhao  := NULLIF(p_payload->>'talhao_id','')::uuid;
    v_cultura := NULLIF(p_payload->>'cultura_id','')::uuid;
    v_area    := NULLIF(p_payload->>'area_avaliada_ha','')::numeric;
    v_estande := NULLIF(p_payload->>'estande_plantas_ha','')::numeric;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'payload_invalido' USING ERRCODE = '22023';
  END;
  v_fase := NULLIF(p_payload->>'fase_fenologica','');
  v_unif := NULLIF(p_payload->>'uniformidade','');
  v_obs  := NULLIF(p_payload->>'observacoes_campo','');
  v_extras := COALESCE(p_payload->'dados_extras', '{}'::jsonb);
  IF jsonb_typeof(v_extras) <> 'object'
     OR (v_area IS NOT NULL AND (v_area::text IN ('NaN','Infinity','-Infinity') OR v_area < 0))
     OR (v_estande IS NOT NULL AND (v_estande::text IN ('NaN','Infinity','-Infinity') OR v_estande < 0 OR v_estande <> trunc(v_estande) OR v_estande > 2147483647))
     OR (v_unif IS NOT NULL AND v_unif NOT IN ('baixa','media','alta')) THEN
    RAISE EXCEPTION 'payload_invalido' USING ERRCODE = '22023';
  END IF;

  -- 1) Canonical revocation gate BEFORE the parent row lock (same order as revocation writers).
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate_unavailable' USING ERRCODE = '55000';
  END IF;
  IF NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- 2) Parent lock, restricted to the ORIGINAL actor scope (admin/created_by/client execute|manage)
  --    intersected with the canonical tenant check. No role is added.
  SELECT r.* INTO v_reg FROM public.registros_consultor r
   WHERE r.id = p_registro_consultor_id
     AND COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false)
     AND COALESCE((public.has_role(v_uid, 'administrador'::app_role)
       OR r.created_by = v_uid
       OR (r.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(v_uid, r.cliente_id, ARRAY['execute','manage']))), false)
   FOR UPDATE;

  -- 3) Re-authorize after the row wait; never cached.
  IF v_reg.id IS NULL
     OR NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false)
     OR NOT COALESCE((
       public.has_role(v_uid, 'administrador'::app_role)
       OR v_reg.created_by = v_uid
       OR (v_reg.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(v_uid, v_reg.cliente_id, ARRAY['execute','manage']))
     ), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  IF NOT COALESCE(public.is_technical_visit_editable_status(v_reg.status::text), false) THEN
    RAISE EXCEPTION 'visita_locked' USING ERRCODE = 'PT409';
  END IF;
  IF v_reg.cliente_id IS NULL THEN
    RAISE EXCEPTION 'registro_sem_cliente' USING ERRCODE = 'P0002';
  END IF;

  -- 4) Child lock.
  SELECT * INTO v_existing FROM public.visitas_campo
   WHERE registro_consultor_id = p_registro_consultor_id FOR UPDATE;

  -- 5) Re-authorize again after the child wait (original scope + canonical tenant + status),
  --    re-reading the parent; nothing observed before this wait is trusted.
  SELECT r.* INTO v_reg FROM public.registros_consultor r WHERE r.id = p_registro_consultor_id;
  IF v_reg.id IS NULL
     OR NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false)
     OR NOT COALESCE((
       public.has_role(v_uid, 'administrador'::app_role)
       OR v_reg.created_by = v_uid
       OR (v_reg.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(v_uid, v_reg.cliente_id, ARRAY['execute','manage']))
     ), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;
  IF NOT COALESCE(public.is_technical_visit_editable_status(v_reg.status::text), false) THEN
    RAISE EXCEPTION 'visita_locked' USING ERRCODE = 'PT409';
  END IF;
  -- Actor tenant (active profile) resolved after every wait; the visit's cliente must belong to it.
  SELECT p.organization_id INTO v_org FROM public.profiles p
   WHERE p.user_id = v_uid AND p.ativo = true AND p.organization_id IS NOT NULL;
  IF v_org IS NULL OR NOT EXISTS (
       SELECT 1 FROM public.clientes c WHERE c.id = v_reg.cliente_id AND c.organization_id = v_org) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- References. Talhão: same tenant on talhão AND fazenda, fazenda of the visit's cliente.
  -- New choices must be active; an already-saved reference may be kept unchanged while inactive,
  -- but only if it still satisfies tenant/cliente (validity is never relaxed, only activity).
  IF v_talhao IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.talhoes t JOIN public.fazendas f ON f.id = t.fazenda_id
        WHERE t.id = v_talhao AND f.cliente_id = v_reg.cliente_id
          AND t.organization_id = v_org AND f.organization_id = v_org
          AND ((COALESCE(t.ativo, false) AND COALESCE(f.ativo, false))
               OR v_talhao IS NOT DISTINCT FROM v_existing.talhao_id)) THEN
    RAISE EXCEPTION 'talhao_invalido' USING ERRCODE = '22023';
  END IF;
  -- Cultura: global catalogue; new choice must be active AND not hidden for the actor tenant
  -- (public.catalog_tenant_visibility, same source as catalog_tenant_selection_core).
  IF v_cultura IS NOT NULL AND v_cultura IS DISTINCT FROM v_existing.cultura_id AND NOT EXISTS (
       SELECT 1 FROM public.culturas c
        WHERE c.id = v_cultura AND COALESCE(c.ativo, false)
          AND NOT EXISTS (SELECT 1 FROM public.catalog_tenant_visibility v
                           WHERE v.organization_id = v_org AND v.entity_type = 'cultura'
                             AND v.cultura_id = c.id AND v.hidden)) THEN
    RAISE EXCEPTION 'cultura_invalida' USING ERRCODE = '22023';
  END IF;
  IF v_cultura IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.culturas c WHERE c.id = v_cultura) THEN
    RAISE EXCEPTION 'cultura_invalida' USING ERRCODE = '22023';
  END IF;

  IF v_existing.id IS NULL THEN
    IF p_versao <> 0 THEN
      RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
    END IF;
    INSERT INTO public.visitas_campo (
      registro_consultor_id, cliente_id, talhao_id, cultura_id,
      area_avaliada_ha, fase_fenologica, estande_plantas_ha, uniformidade,
      observacoes_campo, dados_extras, client_uuid, versao, created_by
    ) VALUES (
      p_registro_consultor_id, v_reg.cliente_id, v_talhao, v_cultura,
      v_area, v_fase, v_estande::integer, v_unif,
      v_obs, v_extras, p_client_uuid, 1, v_uid
    ) RETURNING * INTO v_result;
    RETURN jsonb_build_object('id', v_result.id, 'registro_consultor_id', v_result.registro_consultor_id,
      'versao', v_result.versao, 'client_uuid', v_result.client_uuid, 'replayed', false);
  END IF;

  IF p_versao = 0 THEN
    -- Idempotent replay of a lost initial-insert response: only same actor, same client_uuid,
    -- still version 1 and identical content. Authorization above already proved scope on this
    -- very visit, so nothing crosses tenants. Anything else is a business conflict.
    IF p_client_uuid IS NOT NULL AND v_existing.versao = 1
       AND v_existing.client_uuid = p_client_uuid AND v_existing.created_by = v_uid
       AND v_existing.talhao_id IS NOT DISTINCT FROM v_talhao
       AND v_existing.cultura_id IS NOT DISTINCT FROM v_cultura
       AND v_existing.area_avaliada_ha IS NOT DISTINCT FROM v_area
       AND v_existing.fase_fenologica IS NOT DISTINCT FROM v_fase
       AND v_existing.estande_plantas_ha IS NOT DISTINCT FROM v_estande::integer
       AND v_existing.uniformidade IS NOT DISTINCT FROM v_unif
       AND v_existing.observacoes_campo IS NOT DISTINCT FROM v_obs
       AND v_existing.dados_extras = v_extras THEN
      RETURN jsonb_build_object('id', v_existing.id, 'registro_consultor_id', v_existing.registro_consultor_id,
        'versao', v_existing.versao, 'client_uuid', v_existing.client_uuid, 'replayed', true);
    END IF;
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  IF v_existing.versao IS NULL OR p_versao <> v_existing.versao THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  UPDATE public.visitas_campo SET
    talhao_id = v_talhao, cultura_id = v_cultura, area_avaliada_ha = v_area,
    fase_fenologica = v_fase, estande_plantas_ha = v_estande::integer, uniformidade = v_unif,
    observacoes_campo = v_obs, dados_extras = v_extras,
    versao = v_existing.versao + 1, updated_at = now()
  WHERE id = v_existing.id AND versao = p_versao
  RETURNING * INTO v_result;
  IF v_result.id IS NULL THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  RETURN jsonb_build_object('id', v_result.id, 'registro_consultor_id', v_result.registro_consultor_id,
    'versao', v_result.versao, 'client_uuid', v_result.client_uuid, 'replayed', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_resolve_commercial_prices(p_items jsonb, p_plan_id uuid, p_ref_date date DEFAULT CURRENT_DATE, p_buyer jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid(); v_partner uuid; s record;
  v_item jsonb; v_res jsonb; v_out jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
  IF COALESCE(p_buyer->>'buyer_scope','partner') <> 'partner' OR NULLIF(p_buyer->>'customer_id','') IS NOT NULL THEN
    RAISE EXCEPTION 'PRODUCER_DIRECT_NOT_ENABLED' USING ERRCODE='P0001';
  END IF;
  IF public.has_role(v_uid,'parceiro_b2b'::app_role) AND NOT public.is_platform_superadmin(v_uid) THEN
    -- parceiro: o partner_id do cliente é ignorado; usa o vínculo do servidor.
    SELECT * INTO s FROM platform_private.b2b_actor_scope(v_uid);
    v_partner := s.user_partner;
  ELSE
    v_partner := NULLIF(p_buyer->>'partner_id','')::uuid;
    IF v_partner IS NULL AND NOT public.is_platform_superadmin(v_uid) THEN
      SELECT * INTO s FROM platform_private.b2b_actor_scope(v_uid);
      v_partner := s.org_partner;
    END IF;
  END IF;
  IF v_partner IS NULL THEN RAISE EXCEPTION 'buyer_required' USING ERRCODE='42501'; END IF;
  PERFORM platform_private.assert_b2b_partner_scope(v_uid, v_partner);

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) LOOP
    v_res := public.fn_resolve_commercial_price('partner', v_partner, NULL, p_plan_id,
      NULLIF(v_item->>'product_id','')::uuid, NULLIF(v_item->>'microrganismo_id','')::uuid,
      v_item->>'unit_type', NULLIF(v_item->>'volume_ml','')::numeric,
      COALESCE(p_ref_date, current_date), NULLIF(v_item->>'quantity','')::numeric);
    v_out := v_out || jsonb_build_array(v_res || jsonb_build_object('item_ref', v_item->>'item_ref'));
  END LOOP;
  RETURN jsonb_build_object('buyer_scope','partner','plan_id',p_plan_id,
                            'ref_date',COALESCE(p_ref_date,current_date),'items',v_out);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_resolver_alerta_operacional(p_alerta_id uuid, p_observacao text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alerta record;
  v_dentro_sla boolean;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success',false,'error','unauthorized'); END IF;
  IF NOT public.can_user_access_alerta(p_alerta_id) THEN
    RETURN jsonb_build_object('success',false,'error','forbidden');
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','alerta_nao_encontrado'); END IF;

  UPDATE public.alertas_operacionais
    SET status='resolvido', resolvido_por=auth.uid(), resolvido_em=now(), updated_at=now()
    WHERE id = p_alerta_id;

  INSERT INTO public.alertas_acoes(alerta_id, user_id, acao, observacao)
    VALUES (p_alerta_id, auth.uid(), 'resolver', p_observacao);

  IF v_alerta.sla_config_id IS NOT NULL THEN
    v_dentro_sla := v_alerta.sla_resolucao_em IS NULL OR now() <= v_alerta.sla_resolucao_em;
    INSERT INTO public.alertas_sla_eventos(alerta_id, config_id, evento, criado_por, responsavel_id)
      VALUES (p_alerta_id, v_alerta.sla_config_id,
        CASE WHEN v_dentro_sla THEN 'resolvido_dentro_sla' ELSE 'resolvido_fora_sla' END,
        auth.uid(), auth.uid());
  END IF;

  PERFORM public.rpc_recalcular_prioridade_alerta(p_alerta_id);
  RETURN jsonb_build_object('success',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_resumo_atendimentos_tecnicos_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_tech boolean;
  v_res jsonb;
BEGIN
  IF NOT public.technical_actor_ready(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error','unauthenticated');
  END IF;

  v_is_admin := public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor');
  v_is_tech := EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid AND ur.role IN ('tecnico_agronomo','consultor_tecnico')
  );
  IF NOT (v_is_admin OR v_is_tech) THEN
    RETURN jsonb_build_object('ok', false, 'error','forbidden');
  END IF;

  WITH visitas AS (
    SELECT r.id, r.status::text AS status, r.origem_atendimento AS origem,
           r.data_proxima_visita, r.fazenda_id
      FROM public.registros_consultor r
     WHERE public.can_view_technical_visit(v_uid, r.id)
  ),
  demandas AS (
    SELECT s.id
      FROM public.portal_solicitacoes s
     WHERE s.status NOT IN ('concluida','cancelada')
       AND NOT EXISTS (SELECT 1 FROM public.registros_consultor r WHERE r.solicitacao_id = s.id AND public.can_view_technical_visit(v_uid,r.id))
       AND public.can_user_access_solicitacao(s.id)
      AND (v_is_admin OR (s.consultor_atribuido = v_uid AND public.technical_client_link(v_uid,s.cliente_id,ARRAY['execute','manage'])))
  )
  SELECT jsonb_build_object(
    'ok', true,
    'demandas', (SELECT count(*) FROM demandas),
    'em_andamento', (SELECT count(*) FROM visitas WHERE status IN ('rascunho','em_andamento')),
    'aguardando', (SELECT count(*) FROM visitas WHERE status IN ('enviado_aprovacao','reprovado')),
    'monitoramento', (SELECT count(*) FROM visitas WHERE status IN ('aprovado','convertido_os') AND data_proxima_visita IS NOT NULL),
    'ocorrencias', (SELECT count(*) FROM visitas WHERE origem = 'ocorrencia_campo'),
    'concluidos', (SELECT count(*) FROM visitas
                    WHERE status NOT IN ('rascunho','em_andamento','enviado_aprovacao','reprovado')
                      AND NOT (status IN ('aprovado','convertido_os') AND data_proxima_visita IS NOT NULL)),
    'todos', (SELECT count(*) FROM visitas) + (SELECT count(*) FROM demandas),
    'os_ativas', (SELECT count(*) FROM public.ordens_servico_onfarm os
                   WHERE os.status NOT IN ('finalizada','entregue','cancelada')
                     AND os.registro_consultor_id IN (SELECT id FROM visitas)),
    'fazendas', (SELECT count(*) FROM public.fazendas f WHERE public.technical_refs_in_actor_tenant(f.cliente_id,f.id,NULL) AND public.can_user_access_cliente(f.cliente_id) AND (v_is_admin OR public.technical_client_link(v_uid,f.cliente_id,ARRAY['read','execute','manage'])))
  ) INTO v_res;

  RETURN v_res;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_service_check_rate_limit(p_user uuid, p_action text, p_max integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_window_start timestamptz;
  v_count integer;
BEGIN
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_user IS NULL OR coalesce(p_action,'') = '' OR p_max <= 0 OR p_window_seconds <= 0 THEN
    RAISE EXCEPTION 'invalid_args' USING ERRCODE = '22023';
  END IF;

  v_window_start := date_trunc('second', now())
                    - (extract(epoch from now())::bigint % p_window_seconds) * interval '1 second';

  INSERT INTO public.communication_provider_settings_rate_limit(user_id, action, window_start, count)
  VALUES (p_user, p_action, v_window_start, 1)
  ON CONFLICT (user_id, action, window_start)
  DO UPDATE SET count = public.communication_provider_settings_rate_limit.count + 1
  RETURNING count INTO v_count;

  -- Housekeeping barato: apaga janelas antigas do próprio par (limita rows).
  DELETE FROM public.communication_provider_settings_rate_limit
   WHERE user_id = p_user AND action = p_action AND window_start < v_window_start;

  RETURN v_count <= p_max;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.set_org_principal_admin_core(_org uuid, _user_id uuid, _motivo text, _expected_responsavel uuid, _idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o public.organizations%ROWTYPE; a public.platform_org_admin_audit%ROWTYPE; v_motivo text; v_old uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NULL OR _org IS NULL OR _user_id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: parâmetros obrigatórios' USING ERRCODE='22023'; END IF;
  v_motivo := btrim(coalesce(_motivo,''));
  IF v_motivo = '' THEN v_motivo := 'Alteração de responsável principal'; END IF;
  IF char_length(v_motivo) < 2 THEN RAISE EXCEPTION 'platform_invalid: motivo obrigatório (mínimo 2 caracteres)' USING ERRCODE='22023'; END IF;

  SELECT * INTO o FROM public.organizations WHERE id=_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: empresa inexistente' USING ERRCODE='22023'; END IF;

  SELECT * INTO a FROM public.platform_org_admin_audit WHERE action='principal_transferred' AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF a.organization_id=_org AND a.target_user_id=_user_id AND a.reason=v_motivo THEN
      RETURN jsonb_build_object('organization_id',_org,'responsavel_user_id',_user_id,'idempotent',true); END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001';
  END IF;

  IF o.responsavel_user_id IS DISTINCT FROM _expected_responsavel THEN
    RAISE EXCEPTION 'platform_conflict: o responsável foi alterado por outra pessoa; recarregue' USING ERRCODE='40001'; END IF;
  IF o.responsavel_user_id = _user_id THEN
    RAISE EXCEPTION 'platform_invalid: este administrador já é o responsável principal' USING ERRCODE='22023'; END IF;
  IF public.is_platform_superadmin(_user_id)
     OR NOT EXISTS (SELECT 1 FROM public.platform_org_admin_invites i WHERE i.organization_id=_org AND i.user_id=_user_id AND i.status='ativo')
     OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=_user_id AND p.organization_id=_org AND p.ativo IS TRUE)
     OR NOT public.has_role(_user_id,'administrador'::public.app_role) THEN
    RAISE EXCEPTION 'platform_invalid: candidato precisa ser administrador ativo desta empresa' USING ERRCODE='22023'; END IF;

  v_old := o.responsavel_user_id;
  PERFORM platform_private.issue_ticket('org_write', _org);
  UPDATE public.organizations SET responsavel_user_id=_user_id, responsavel_definido_em=now(), updated_at=now() WHERE id=_org;
  UPDATE public.platform_org_admin_invites SET responsavel_principal = coalesce(user_id=_user_id,false), updated_at=now()
   WHERE organization_id=_org AND responsavel_principal IS DISTINCT FROM coalesce(user_id=_user_id,false);
  UPDATE public.profiles SET cargo = CASE WHEN user_id=_user_id THEN 'Responsável Principal' ELSE 'Administrador' END
   WHERE organization_id=_org AND user_id IN (_user_id, v_old) AND cargo IN ('Responsável Principal','Administrador')
     AND cargo IS DISTINCT FROM CASE WHEN user_id=_user_id THEN 'Responsável Principal' ELSE 'Administrador' END;

  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (_org,_user_id,auth.uid(),'principal_transferred','succeeded',v_motivo,'platform_rpc',_idempotency_key,
          jsonb_build_object('responsavel_user_id',v_old,'responsavel_definido_em',o.responsavel_definido_em),
          jsonb_build_object('responsavel_user_id',_user_id));
  RETURN jsonb_build_object('organization_id',_org,'responsavel_user_id',_user_id,'idempotent',false);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_solicitar_ajuste_visita(p_registro_id uuid, p_expected_version integer, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_new_version integer;
BEGIN
  IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
    RAISE EXCEPTION 'motivo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, true);
  IF v_reg.status::text <> 'enviado_aprovacao' THEN
    RAISE EXCEPTION 'status_invalido' USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.registros_consultor
     SET status = 'rascunho', version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
  RETURNING version INTO v_new_version;
  INSERT INTO public.aprovacoes_tecnicas
    (registro_consultor_id, status_aprovacao, comentario_gestor, aprovado_por, data_aprovacao)
  VALUES (p_registro_id, 'ajuste_solicitado', p_motivo, auth.uid(), now());
  INSERT INTO public.registros_consultor_status_log
    (registro_consultor_id, status_anterior, status_novo, motivo, changed_by, changed_at)
  VALUES (p_registro_id, v_reg.status::text, 'rascunho', p_motivo, auth.uid(), now());
  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, auth.uid(), 'ajuste_solicitado', 'Ajuste solicitado. Motivo: ' || p_motivo);
  RETURN jsonb_build_object('ok', true, 'version', v_new_version, 'status', 'rascunho');
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_skip_communication_delivery(p_outbox_id uuid, p_worker_id text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_outbox%rowtype; v_role text;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege'; END IF;
  IF NULLIF(trim(COALESCE(p_worker_id,'')),'') IS NULL THEN RAISE EXCEPTION 'worker_id obrigatório'; END IF;
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'processing' THEN RAISE EXCEPTION 'não estava em processing (status=%)', r.status; END IF;
  IF r.locked_by IS DISTINCT FROM p_worker_id THEN RAISE EXCEPTION 'lease de outro worker'; END IF;
  UPDATE public.comunicacao_outbox
     SET status='skipped', error_code='skipped',
         error_message=left(COALESCE(p_reason,''),2000),
         locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
   WHERE id = p_outbox_id;
  RETURN jsonb_build_object('ok',true,'status','skipped');
END$function$

CREATE OR REPLACE FUNCTION platform_private.update_org_admin_core(_invite_id uuid, _nome text, _telefone text, _cpf text, _motivo text, _expected_updated_at timestamp with time zone, _idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE; a public.platform_org_admin_audit%ROWTYPE;
  v_motivo text; v_nome text; v_tel text; v_cpf text; v_old jsonb; v_new jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NULL OR _invite_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: parâmetros obrigatórios' USING ERRCODE='22023'; END IF;
  v_motivo := btrim(coalesce(_motivo,''));
  IF char_length(v_motivo) = 1 THEN RAISE EXCEPTION 'platform_invalid: se informar o motivo, use ao menos 2 caracteres' USING ERRCODE='22023'; END IF;
  v_nome := regexp_replace(btrim(coalesce(_nome,'')), '\s+', ' ', 'g');
  v_tel := nullif(regexp_replace(coalesce(_telefone,''),'\D','','g'),'');
  v_cpf := nullif(regexp_replace(coalesce(_cpf,''),'\D','','g'),'');
  IF char_length(v_nome) NOT BETWEEN 3 AND 200 THEN RAISE EXCEPTION 'platform_invalid: nome inválido' USING ERRCODE='22023'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN (10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone inválido' USING ERRCODE='22023'; END IF;
  IF v_cpf IS NOT NULL AND (length(v_cpf)<>11 OR v_cpf ~ '^(\d)\1{10}$') THEN RAISE EXCEPTION 'platform_invalid: CPF inválido' USING ERRCODE='22023'; END IF;

  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=_invite_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: administrador inexistente' USING ERRCODE='22023'; END IF;

  SELECT * INTO a FROM public.platform_org_admin_audit WHERE action='admin_profile_updated' AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF a.invite_id=_invite_id AND a.reason=v_motivo AND a.new_values->>'nome' IS NOT DISTINCT FROM v_nome
       AND a.new_values->>'telefone' IS NOT DISTINCT FROM v_tel AND a.new_values->>'cpf_cnpj' IS NOT DISTINCT FROM v_cpf THEN
      RETURN jsonb_build_object('invite_id',_invite_id,'updated_at',j.updated_at,'idempotent',true); END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001';
  END IF;

  IF j.status='processando' OR (j.lease_expires_at IS NOT NULL AND j.lease_expires_at > clock_timestamp()) THEN
    RAISE EXCEPTION 'platform_conflict: provisionamento em andamento' USING ERRCODE='55P03'; END IF;
  IF _expected_updated_at IS NULL OR j.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RAISE EXCEPTION 'platform_conflict: o administrador foi alterado por outra pessoa; recarregue antes de salvar' USING ERRCODE='40001'; END IF;
  IF j.user_id IS NOT NULL AND public.is_platform_superadmin(j.user_id) THEN
    RAISE EXCEPTION 'platform_forbidden: acesso de plataforma não é editável aqui' USING ERRCODE='42501'; END IF;
  IF v_cpf IS DISTINCT FROM j.cpf_cnpj AND j.status='ativo' AND j.cpf_cnpj IS NOT NULL THEN
    RAISE EXCEPTION 'platform_invalid: correção de CPF de administrador ativo exige fluxo específico' USING ERRCODE='22023'; END IF;
  IF (v_nome, v_tel, v_cpf) IS NOT DISTINCT FROM (j.nome, j.telefone, j.cpf_cnpj) THEN
    RAISE EXCEPTION 'platform_invalid: nenhuma alteração para salvar' USING ERRCODE='22023'; END IF;

  v_old := jsonb_build_object('nome',j.nome,'telefone',j.telefone,'cpf_cnpj',j.cpf_cnpj);
  UPDATE public.platform_org_admin_invites SET nome=v_nome, telefone=v_tel, cpf_cnpj=v_cpf,
         updated_at=greatest(clock_timestamp(), j.updated_at + interval '1 microsecond')
   WHERE id=_invite_id RETURNING * INTO j;
  IF j.user_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=j.user_id AND p.organization_id IS DISTINCT FROM j.organization_id) THEN
      RAISE EXCEPTION 'platform_conflict: vínculo do perfil diverge da empresa' USING ERRCODE='40001'; END IF;
    UPDATE public.profiles SET nome=v_nome, telefone=v_tel, cpf_cnpj=v_cpf
     WHERE user_id=j.user_id AND organization_id=j.organization_id;
  END IF;
  v_new := jsonb_build_object('nome',v_nome,'telefone',v_tel,'cpf_cnpj',v_cpf);
  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (j.organization_id,j.user_id,_invite_id,auth.uid(),'admin_profile_updated','succeeded',v_motivo,'platform_rpc',_idempotency_key,v_old,v_new);
  RETURN jsonb_build_object('invite_id',_invite_id,'updated_at',j.updated_at,'idempotent',false);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_update_communication_template(p_template_id uuid, p_nome text, p_assunto text, p_corpo text, p_variaveis jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.comunicacao_templates%rowtype;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO r FROM public.comunicacao_templates WHERE id = p_template_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'template não encontrado'; END IF;
  IF r.status = 'active' THEN
    RAISE EXCEPTION 'template ativo é imutável; crie nova versão';
  END IF;
  IF r.status = 'archived' THEN RAISE EXCEPTION 'template arquivado'; END IF;
  UPDATE public.comunicacao_templates
     SET nome = p_nome, assunto = p_assunto, corpo = p_corpo,
         variaveis = COALESCE(p_variaveis,'[]'::jsonb), updated_by = auth.uid()
   WHERE id = p_template_id;
  PERFORM public._comunicacao_write_audit('template.update','comunicacao_templates',p_template_id,
    to_jsonb(r), (SELECT to_jsonb(t) FROM public.comunicacao_templates t WHERE t.id = p_template_id));
  RETURN jsonb_build_object('ok',true);
END$function$

CREATE OR REPLACE FUNCTION public.platform_begin_org_admin_email_change(p_actor_id uuid, p_invite_id uuid, p_new_email text, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE; c public.platform_org_admin_email_changes%ROWTYPE;
  v_email text := lower(btrim(coalesce(p_new_email,''))); v_reason text := btrim(coalesce(p_reason,''));
BEGIN
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,p_invite_id);
  PERFORM platform_private.require_service_role();
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_idempotency_key IS NULL OR p_invite_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: parâmetros' USING ERRCODE='22023'; END IF;
  IF v_reason = '' THEN v_reason := 'Alteração de e-mail administrativo'; END IF;
  IF char_length(v_reason) < 2 THEN RAISE EXCEPTION 'platform_invalid: motivo' USING ERRCODE='22023'; END IF;
  IF v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR length(v_email) > 254 THEN RAISE EXCEPTION 'platform_invalid: email' USING ERRCODE='22023'; END IF;

  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: administrador' USING ERRCODE='22023'; END IF;

  SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE idempotency_key=p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    IF c.invite_id<>p_invite_id OR c.new_email<>v_email OR c.reason<>v_reason THEN
      RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001'; END IF;
    IF c.status='cancelled' THEN RAISE EXCEPTION 'platform_conflict: solicitação substituída' USING ERRCODE='40001'; END IF;
    IF c.status='failed' THEN
      UPDATE public.platform_org_admin_email_changes SET status='requested', attempt_count=attempt_count+1, updated_at=now()
       WHERE id=c.id RETURNING * INTO c;
    END IF;
    RETURN jsonb_build_object('op_id',c.id,'status',c.status,'user_id',c.user_id,'old_email',c.old_email,'new_email',c.new_email,
      'invite_status',c.invite_status_at_request,'organization_id',c.organization_id,'attempt',c.attempt_count,'idempotent',true);
  END IF;

  PERFORM platform_private.cancel_stale_email_change(p_invite_id, p_actor_id);
  IF EXISTS (SELECT 1 FROM public.platform_org_admin_email_changes x WHERE x.invite_id=p_invite_id AND x.status IN ('requested','auth_updated','failed')) THEN
    RAISE EXCEPTION 'platform_conflict: já existe mudança de e-mail pendente para este administrador' USING ERRCODE='55P03'; END IF;
  IF j.status='processando' OR (j.lease_expires_at IS NOT NULL AND j.lease_expires_at > clock_timestamp())
     OR j.email_delivery_status='sending' THEN
    RAISE EXCEPTION 'platform_conflict: provisionamento em andamento' USING ERRCODE='55P03'; END IF;
  IF j.user_id IS NOT NULL AND public.is_platform_superadmin(j.user_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF j.user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id) THEN
    RAISE EXCEPTION 'platform_conflict: vínculo do perfil diverge da empresa' USING ERRCODE='40001'; END IF;
  IF lower(j.email)=v_email THEN RAISE EXCEPTION 'platform_invalid: e-mail igual ao atual' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM public.platform_org_admin_invites i WHERE lower(i.email)=v_email)
     OR EXISTS (SELECT 1 FROM public.profiles p WHERE lower(p.email)=v_email AND p.user_id IS DISTINCT FROM j.user_id)
     OR EXISTS (SELECT 1 FROM auth.users u WHERE lower(u.email)=v_email AND u.id IS DISTINCT FROM j.user_id)
     OR EXISTS (SELECT 1 FROM public.platform_org_admin_email_changes x WHERE x.new_email=v_email AND x.status IN ('requested','auth_updated','failed')) THEN
    RAISE EXCEPTION 'platform_email_in_use' USING ERRCODE='23505'; END IF;

  INSERT INTO public.platform_org_admin_email_changes(idempotency_key,organization_id,invite_id,user_id,invite_status_at_request,old_email,new_email,reason,actor_user_id,status)
  VALUES (p_idempotency_key,j.organization_id,j.id,j.user_id,j.status,lower(j.email),v_email,v_reason,p_actor_id,'requested') RETURNING * INTO c;
  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (j.organization_id,j.user_id,j.id,p_actor_id,'email_change_requested','requested',v_reason,'edge_platform_org_admin_email_change',p_idempotency_key,
          jsonb_build_object('email',lower(j.email),'invite_status',j.status),jsonb_build_object('email',v_email));
  RETURN jsonb_build_object('op_id',c.id,'status',c.status,'user_id',c.user_id,'old_email',c.old_email,'new_email',c.new_email,
    'invite_status',c.invite_status_at_request,'organization_id',c.organization_id,'attempt',c.attempt_count,'idempotent',false);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_validar_integridade_esteira(p_origem text, p_os_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_integridade record;
BEGIN
    -- H7O: leitura de integridade da esteira restrita ao staff operacional.
    IF NOT public.is_operational_staff(auth.uid()) THEN
        RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
          HINT = 'H7O: validação de integridade da esteira restrita ao staff operacional.';
    END IF;

    SELECT * INTO v_integridade FROM vw_os_integridade_esteira WHERE os_id = p_os_id AND origem_os = p_origem;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Dados de integridade não encontrados');
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'pode_finalizar', v_integridade.pode_finalizar,
        'detalhes', jsonb_build_object(
            'tem_programacao', v_integridade.tem_programacao,
            'tem_lote', v_integridade.tem_lote,
            'cq_resultado', v_integridade.cq_resultado,
            'tem_envase', v_integridade.tem_envase,
            'tem_estoque', v_integridade.tem_estoque,
            'entrega_confirmada', v_integridade.entrega_confirmada,
            'entrega_status', v_integridade.entrega_status
        )
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_verify_communication_channel(p_user_id uuid, p_cliente_id uuid, p_canal comunicacao_canal, p_email_verificado boolean, p_telefone_verificado boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE='insufficient_privilege';
  END IF;
  IF (p_user_id IS NOT NULL) = (p_cliente_id IS NOT NULL) THEN
    RAISE EXCEPTION 'informe exatamente um: user_id ou cliente_id';
  END IF;
  IF p_user_id IS NOT NULL THEN
    INSERT INTO public.comunicacao_preferencias(user_id, canal, enabled,
       email_verificado, telefone_verificado, source)
    VALUES (p_user_id, p_canal, true,
       COALESCE(p_email_verificado,false), COALESCE(p_telefone_verificado,false), 'admin')
    ON CONFLICT (user_id, canal) WHERE user_id IS NOT NULL DO UPDATE
       SET email_verificado = COALESCE(p_email_verificado, public.comunicacao_preferencias.email_verificado),
           telefone_verificado = COALESCE(p_telefone_verificado, public.comunicacao_preferencias.telefone_verificado),
           updated_at = now();
  ELSE
    INSERT INTO public.comunicacao_preferencias(cliente_id, canal, enabled,
       email_verificado, telefone_verificado, source)
    VALUES (p_cliente_id, p_canal, true,
       COALESCE(p_email_verificado,false), COALESCE(p_telefone_verificado,false), 'admin')
    ON CONFLICT (cliente_id, canal) WHERE cliente_id IS NOT NULL DO UPDATE
       SET email_verificado = COALESCE(p_email_verificado, public.comunicacao_preferencias.email_verificado),
           telefone_verificado = COALESCE(p_telefone_verificado, public.comunicacao_preferencias.telefone_verificado),
           updated_at = now();
  END IF;
  IF p_email_verificado IS TRUE THEN
    PERFORM public._comunicacao_write_consent(p_user_id, p_cliente_id, p_canal, 'verified_email','admin');
  END IF;
  IF p_telefone_verificado IS TRUE THEN
    PERFORM public._comunicacao_write_consent(p_user_id, p_cliente_id, p_canal, 'verified_phone','admin');
  END IF;
  RETURN jsonb_build_object('ok',true);
END$function$

CREATE OR REPLACE FUNCTION public.platform_mark_org_admin_email_change(p_actor_id uuid, p_op_id uuid, p_status text, p_error_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.platform_org_admin_email_changes%ROWTYPE;
BEGIN
  PERFORM platform_private.require_service_role();
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_status NOT IN ('auth_updated','failed') THEN RAISE EXCEPTION 'platform_invalid: status' USING ERRCODE='22023'; END IF;
  SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE id=p_op_id FOR UPDATE;
  IF NOT FOUND OR c.status='completed' THEN RETURN; END IF;
  UPDATE public.platform_org_admin_email_changes
     SET status=p_status, last_error_code=CASE WHEN p_status='failed' THEN left(coalesce(p_error_code,'unknown'),80) ELSE NULL END, updated_at=now()
   WHERE id=c.id;
  IF p_status='failed' THEN
    INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values,error_code,attempt)
    VALUES (c.organization_id,c.user_id,c.invite_id,p_actor_id,'email_change_failed','failed',c.reason,'edge_platform_org_admin_email_change',c.idempotency_key,
            jsonb_build_object('email',c.old_email),jsonb_build_object('email',c.new_email),left(coalesce(p_error_code,'unknown'),80),c.attempt_count);
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.send_partner_simulation_to_manager_secure(p_simulation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN

  IF NOT public.b2b_phase1_simulation_visible(p_simulation_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Simulação não encontrada'; END IF;
  IF v_sim.status <> 'rascunho' THEN RAISE EXCEPTION 'Somente simulações em rascunho podem ser enviadas'; END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND (v_sim.created_by = v_uid OR v_sim.partner_id = v_partner_id) THEN v_allowed := true;
  END IF;
  IF NOT v_allowed THEN RAISE EXCEPTION 'Sem permissão para enviar esta simulação'; END IF;

  UPDATE partner_simulations SET status = 'enviada_gestor', updated_at = now() WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_sim.partner_id, v_uid, 'simulation_sent_to_manager',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'enviada_gestor'));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_sent_to_manager', v_sim.partner_id, v_uid,
    v_sim.cliente_id, p_simulation_id, NULL, NULL, '{}'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_partner_order_delivery_date(p_order_id uuid, p_estimated_delivery_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_pid uuid; v_prev date; v_partner_user uuid; v_numero text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  SELECT partner_id, estimated_delivery_date, numero INTO v_pid, v_prev, v_numero
    FROM public.partner_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;

  UPDATE public.partner_orders
     SET estimated_delivery_date = p_estimated_delivery_date, updated_at = now()
   WHERE id = p_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'delivery_date_changed',
          jsonb_build_object('estimated_delivery_date', v_prev),
          jsonb_build_object('estimated_delivery_date', p_estimated_delivery_date));

  FOR v_partner_user IN SELECT user_id FROM public.partner_users WHERE partner_id = v_pid LOOP
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_partner_user, 'pedido_b2b_previsao',
            'Previsão de entrega atualizada — ' || v_numero,
            'A previsão de entrega do pedido foi atualizada para ' || to_char(p_estimated_delivery_date,'DD/MM/YYYY'),
            '/portal-parceiro/pedidos');
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.start_technical_visit_secure(p_registro_id uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_precisao_gps numeric DEFAULT NULL::numeric, p_foto_url text DEFAULT NULL::text, p_foto_path text DEFAULT NULL::text, p_observacoes text DEFAULT NULL::text, p_justificativa_sem_gps text DEFAULT NULL::text, p_client_uuid uuid DEFAULT NULL::uuid)
 RETURNS TABLE(checkin_id uuid, is_new boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_reg record;
  v_existing uuid;
  v_new_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT public.has_role(v_uid, 'administrador'::app_role) INTO v_is_admin;

  -- H9-D-L7: autorização de escopo ANTES de qualquer leitura de visita ou de check-in.
  -- Registro inexistente e registro alheio produzem a MESMA resposta (fail-closed em NULL).
  IF NOT COALESCE(v_is_admin, false)
     AND NOT COALESCE(public._visita_scope_ok(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'not_visit_owner' USING ERRCODE = '42501';
  END IF;

  -- Idempotência por client_uuid, escopada ao autor do check-in (ou administrador).
  IF p_client_uuid IS NOT NULL THEN
    SELECT id INTO v_existing
      FROM public.visitas_checkin
     WHERE client_uuid = p_client_uuid
       AND (COALESCE(v_is_admin, false) OR consultor_id = v_uid)
     LIMIT 1;
    IF v_existing IS NOT NULL THEN
      RETURN QUERY SELECT v_existing, false;
      RETURN;
    END IF;
  END IF;

  SELECT * INTO v_reg FROM public.registros_consultor WHERE id = p_registro_id;
  IF v_reg.id IS NULL THEN
    RAISE EXCEPTION 'registro_not_found' USING ERRCODE = '22023';
  END IF;

  -- Só técnico da visita ou admin
  IF NOT v_is_admin AND v_reg.consultor_responsavel IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'not_visit_owner' USING ERRCODE = '42501';
  END IF;

  -- Status permitido
  IF v_reg.status NOT IN ('rascunho') THEN
    RAISE EXCEPTION 'invalid_status_for_start:%', v_reg.status USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.visitas_checkin(
    registro_consultor_id, solicitacao_id, consultor_id,
    cliente_id, fazenda_id, talhao_id,
    latitude, longitude, precisao_gps,
    foto_url, foto_path, observacoes,
    justificativa_sem_gps, tipo_checkin, status, client_uuid
  ) VALUES (
    v_reg.id, v_reg.solicitacao_id, v_uid,
    v_reg.cliente_id, v_reg.fazenda_id, v_reg.talhao_id,
    p_latitude, p_longitude, p_precisao_gps,
    p_foto_url, p_foto_path, p_observacoes,
    p_justificativa_sem_gps, 'chegada_fazenda', 'realizado', p_client_uuid
  )
  RETURNING id INTO v_new_id;

  UPDATE public.registros_consultor
     SET status = 'em_andamento',
         hora_inicio = COALESCE(hora_inicio, now()),
         updated_at = now()
   WHERE id = v_reg.id;

  INSERT INTO public.visitas_logs(registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES (v_reg.id, v_reg.solicitacao_id, 'checkin', 'Check-in de visita técnica', v_uid,
          jsonb_build_object('checkin_id', v_new_id, 'admin_bypass', v_is_admin));

  RETURN QUERY SELECT v_new_id, true;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_partner_user_papel(p_link_id uuid, p_papel text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_role public.app_role;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador') OR public.has_role(auth.uid(), 'gestor_comercial')) THEN
    RAISE EXCEPTION 'Permissão negada';
  END IF;
  IF p_papel NOT IN ('gestor','tecnico') THEN
    RAISE EXCEPTION 'Papel inválido: %', p_papel;
  END IF;

  UPDATE public.partner_users SET papel = p_papel WHERE id = p_link_id
    RETURNING user_id INTO v_user_id;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Vínculo não encontrado';
  END IF;

  v_role := CASE WHEN p_papel = 'tecnico' THEN 'parceiro_b2b_tecnico'::public.app_role
                 ELSE 'parceiro_b2b'::public.app_role END;

  DELETE FROM public.user_roles
   WHERE user_id = v_user_id
     AND role IN ('parceiro_b2b'::public.app_role, 'parceiro_b2b_tecnico'::public.app_role);

  INSERT INTO public.user_roles(user_id, role)
  VALUES (v_user_id, v_role)
  ON CONFLICT (user_id, role) DO NOTHING;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_partner_order_status(p_order_id uuid, p_status partner_order_status, p_motivo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_prev partner_order_status;
  v_pid uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT status, partner_id INTO v_prev, v_pid FROM public.partner_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;

  IF v_prev = p_status THEN RETURN; END IF;

  -- estados terminais não retornam por esta via
  IF v_prev IN ('reprovado','cancelado','reprovado_sem_itens') THEN
    RAISE EXCEPTION 'order_terminal_status: %', v_prev USING ERRCODE = 'check_violation';
  END IF;

  -- etapas operacionais/financeiras exigem aprovação prévia
  IF public.fn_b2b_status_is_operational(p_status)
     AND NOT public.fn_b2b_status_is_approved_or_later(v_prev) THEN
    RAISE EXCEPTION 'status_requires_approved_order: % -> %', v_prev, p_status
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.partner_orders SET status = p_status, updated_at = now() WHERE id = p_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'status_changed',
          jsonb_build_object('status', v_prev),
          jsonb_build_object('status', p_status, 'motivo', p_motivo));
END;
$function$

